// 仅含法律条文(无版权), 标准不在此数据中
window.LAWS_QA = [{"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第一条", "text": "（目的和依据） 为了建立健全安全生产事故隐患排查治理机制，落实生产 经营单位的安全生产主体责任，防范和减少事故发生，保障人 民群众生命财产安全，根据《中华人民共和国安全生产法》 《上海市安全生产条例》等法律、法规，制定本办法。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第二条", "text": "（适用范围） 本市行政区域内生产经营单位安全生产事故隐患的排查治 理及其监督管理工作，适用本办法。 法律、法规、规章对消防、道路交通、铁路交通、水上交 通、民用航空、核与辐射、特种设备等安全生产事故隐患的排 查治理及其监督管理另有规定的，适用其规定。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第三条", "text": "（含义） 本办法所称的安全生产事故隐患（以下简称“事故隐 患”），是指从事生产经营活动的企业、个体工商户以及其他 能够独立承担民事责任的经营性组织（以下统称“生产经营单 位”）违反安全生产法律、法规、规章、标准、规程和管理制 度的规定或者因其他因素在生产经营活动中存在可能导致事故 发生的物的危险状态、人的不安全行为和管理上的缺陷。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第四条", "text": "（责任主体） 生产经营单位是事故隐患排查治理的责任主体。 生产经营单位法定代表人和实际负有本单位生产经营最高 管理权限的人员（以下统称“主要负责人”）是本单位事故隐 患排查治理的第一责任人，对本单位事故隐患排查治理工作全 面负责，应当履行下列职责： （一）组织制定事故隐患排查治理的各项规章制度； （二）建立健全安全生产责任制； （三）保障事故隐患排查治理的相关资金投入； （四）定期组织全面的事故隐患排查； （五）督促检查安全生产工作，及时消除事故隐患。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第五条", "text": "（政府职责） 市和区人民政府应当加强对本行政区域内事故隐患排查治 理工作的领导。 市和区人民政府的安全生产委员会及其办公室负责统筹、 协调事故隐患排查治理工作中的重大问题。 乡镇人民政府、街道办事处以及开发区、工业园区、港 区、风景区等功能区（以下统称“功能区”）管理机构应当依 法做好本辖区内事故隐患排查治理的相关工作。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第六条", "text": "（部门分工） 应急管理、公安、住房城乡建设管理、市场监管、交通、 经济信息化、水务、农业农村、生态环境和消防救援等，对有 关行业、领域安全生产工作实施监督管理的部门和机构（以下 统称“负有安全生产监管职责的部门”），依照法律、法规、 规章和本市安全生产委员会成员单位安全生产工作职责的规 定，对其职责范围内的事故隐患排查治理实施监管。 应急管理部门除承担本条第一款规定职责外，还负责指 导、协调、监督同级人民政府有关部门和下级人民政府对事故 隐患排查治理实施监管。 商务、教育、科技、民政、民族宗教等行业、领域主管部 门以及国有资产监管机构应当将事故隐患排查治理作为本行 业、领域安全生产管理的重要内容，指导、督促行业、领域内 生产经营单位加强事故隐患排查治理、落实防范措施、履行安 全生产职责。 其他有关部门按照本市安全生产委员会成员单位安全生产 工作职责规定，协同实施事故隐患排查治理监管的相关工作。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第七条", "text": "（层级分工） 市级负有安全生产监管职责的部门应当确定由其监管的生 产经营单位的范围；区级负有安全生产监管职责的部门负责对 本行政区域内其他生产经营单位实施监管。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第八条", "text": "（举报和奖励） 任何单位和个人发现事故隐患的，有权向负有安全生产监 管职责的部门举报。负有安全生产监管职责的部门接到事故隐 患举报后，应当按照职责分工，立即组织核实处理。属于其他 部门职责范围的，应当立即移送有管辖权的部门核实处理。 举报生产经营单位存在事故隐患排查治理相关违法行为， 经核实的，由负有安全生产监管职责的部门按照规定给予奖 励。负有安全生产监管职责的部门应当为举报者保密。 第二章 生产经营单位的事故隐患排查治理责任"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第九条", "text": "（事故隐患排查治理制度） 生产经营单位应当按照有关安全生产法律、法规、规章、 标准、规程，建立事故隐患排查、登记、报告、整改等安全管 理规章制度，明确单位负责人、部门（车间）负责人、班组负 责人和具体岗位从业人员的事故隐患排查治理责任范围，并予 以落实。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第十条", "text": "（教育培训） 生产经营单位应当加强对从业人员开展安全教育培训，保 证其熟悉安全管理规章制度，具备与岗位职责相适应的技术能 力和安全作业知识。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第十一条", "text": "（事故隐患日常排查） 安全生产管理人员、其他从业人员应当根据其岗位职责， 开展经常性的安全生产检查，及时发现工艺系统、基础设施、 技术装备、防（监）控设施等方面存在的危险状态以及落实安 全生产责任、执行劳动纪律、实施现场管理等方面存在的缺 陷。 安全生产管理人员、其他从业人员发现事故隐患，应当报 告直接负责人并及时处理；发现直接危及人身安全的紧急情 况，有权停止作业或者采取可能的应急措施后撤离作业场所。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第十二条", "text": "（事故隐患定期排查） 生产经营单位主要负责人和分管负责人应当定期组织安全 生产管理人员、专业技术人员和其他相关人员进行全面的事故 隐患排查，主要包括： （一）安全生产法律、法规、规章、标准、规程的贯彻执 行情况，安全生产责任制、安全管理规章制度、岗位操作规范 的建立落实情况； （二）应急（救援）预案制定、演练，应急救援物资、设 备的配备及维护情况； （三）设施、设备、装置、工具的状况和日常维护、保 养、检验、检测情况； （四）爆破、吊装、危险装置设备试生产、动火、临时用 电、有限（受限）空间作业、重大危险源作业等事故多发易发 环节的现场安全管理情况； （五）重大危险源普查建档、风险辨识、监控预警制度的 建设及措施落实情况； （六）劳动防护用品的配备、发放和佩戴使用情况，以及 从业人员的身体、精神状况； （七）从业人员接受安全教育培训、掌握安全知识和操作 技能情况，特种作业人员、特种设备作业人员培训考核和持证 上岗情况。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第十三条", "text": "（事故隐患定级） 生产经营单位发现事故隐患后，应当启动相应的应急预 案，采取措施保证安全，并组织专业技术人员、专家或者具有 相应资质的专业机构分析确定事故隐患级别。 事故隐患分为一般事故隐患和重大事故隐患。重大事故隐 患，是指按照国家有关部门制定的有关重大事故隐患判定标准 判定的隐患。一般事故隐患，是指除重大事故隐患外的其他事 故隐患。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第十四条", "text": "（事故隐患处理） 对一般事故隐患，生产经营单位应当在保证安全的前提 下，采取措施予以排除。 对重大事故隐患，生产经营单位应当按照以下规定处理： （一）根据需要停止使用相关设施、设备，局部停产停业 或者全部停产停业。 （二）组织专业技术人员、专家或者具有相应资质的专业 机构进行风险评估，明确事故隐患的现状、产生原因、危害程 度、整改难易程度。 （三）根据风险评估结果制定治理方案，明确治理目标、 治理措施、责任人员、所需经费和物资条件、时间节点、监控 保障和应急措施。 （四）落实治理方案，排除事故隐患。 生产经营单位应当及时将重大事故隐患排查治理情况向负 有安全生产监管职责的部门和职工大会或者职工代表大会报 告。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第十五条", "text": "（监控保障） 生产经营单位在事故隐患治理过程中，应当采取必要的监 控保障措施。事故隐患排除前或者排除过程中无法保证安全 的，应当从危险区域内撤出作业人员，疏散可能危及的其他人 员，并设置警示标志，必要时应当派员值守。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第十六条", "text": "（信息档案） 生产经营单位应当建立事故隐患排查治理信息档案，对隐 患排查治理情况进行如实记录。 事故隐患排查治理信息档案应当包括以下内容： （一）事故隐患排查时间； （二）事故隐患排查的具体部位或者场所； （三）发现事故隐患的数量、级别和具体情况； （四）参加隐患排查的人员及其签字； （五）事故隐患治理情况、复查情况、复查时间、复查人 员及其签字。 事故隐患排查治理信息档案应当保存2 年以上。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第十七条", "text": "（数据报送） 危险化学品、矿山、金属冶炼、建筑施工、交通运输等危 险性较高的生产经营单位应当加强事故隐患排查治理的信息化 管理，运用数字化技术开展事故隐患排查治理工作，按照要求 向负有安全生产监管职责的部门实时、准确、完整地报送事故 隐患排查治理数据。 前款规定的数据报送的范围、要素和路径等，按照市级负 有安全生产监管职责的部门制定的相关指南或者规范执行。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第十八条", "text": "（承包承租管理） 生产经营单位将生产经营项目、场所发包、租赁给其他单 位的，应当对承包、承租单位的事故隐患排查治理负有统一协 调和管理的责任；发现承包、承租单位存在事故隐患的，应当 及时督促其开展治理。 承包、承租单位应当服从生产经营单位对其事故隐患排查 治理工作的统一协调、管理。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第十九条", "text": "（奖惩制度） 生产经营单位应当建立事故隐患排查治理的奖惩制度，鼓 励从业人员发现和排除事故隐患，对发现、排除事故隐患的有 功人员给予奖励和表彰，对瞒报事故隐患或者排查治理不力的 人员按照有关规定予以处理。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第二十条", "text": "（资金保障） 生产经营单位应当保障事故隐患排查治理所需的资金，在 年度安全生产资金中列支，并专款专用；事故隐患治理资金需 求超出年度安全生产资金使用计划的，应当及时调整资金使用 计划。 第三章 监督管理"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第二十一条", "text": "（年度监督检查计划的制定及执行） 负有安全生产监管职责的部门应当制定年度监督检查计 划，明确监督检查的频次、方式、重点行业和重点内容，并建 立相应的监督检查记录。监督检查中发现事故隐患的，负有安 全生产监管职责的部门应当责令立即或者限期治理，并及时组 织复查。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第二十二条", "text": "（街镇园区的日常监督检查） 乡镇人民政府、街道办事处、功能区管理机构依法开展安 全生产日常监督检查时，发现事故隐患的，应当责令生产经营 单位立即排除或者限期治理，并报告负有安全生产监管职责的 部门。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第二十三条", "text": "（重大事故隐患的现场处理） 重大事故隐患排除前或者排除过程中无法保证安全的，负 有安全生产监管职责的部门应当责令从危险区域内撤出作业人 员，责令暂时停产停业或者停止使用相关设施、设备；重大事 故隐患排除后，经审查同意，方可恢复生产经营和使用。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第二十四条", "text": "（移送） 负有安全生产监管职责的部门发现属于其他部门职责范围 的事故隐患，应当及时将有关资料移送有管辖权的部门，并记 录备查。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第二十五条", "text": "（监督检查信息汇总和分析） 本市建立事故隐患排查治理信息系统，由市应急管理部门 负责日常运行管理，接受、汇总、分析、通报事故隐患排查治 理信息。 区级负有安全生产监管职责的部门应当按月汇总整理监督 检查记录等信息，并报送上级负有安全生产监管职责的部门和 同级应急管理部门。 市级负有安全生产监管职责的部门和区应急管理部门应当 按月汇总整理监督检查记录等信息，并报送市应急管理部门。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第二十六条", "text": "（重大事故隐患的挂牌督办） 对于下列重大事故隐患，负有安全生产监管职责的部门应 当挂牌督办或者提请同级人民政府挂牌督办： （一）危险性较大，且可能造成严重后果或者较大社会影 响的重大事故隐患； （二）治理难度较高，需要经过较长时间系统整治方能消 除的重大事故隐患； （三）受外部因素影响，生产经营单位难以单独依靠自身 力量消除的重大事故隐患； （四）上级政府或者有关部门督导检查发现的，并要求挂 牌督办的重大事故隐患； （五）需要责令暂时停产停业或者停止使用相关设施、设 备的重大事故隐患。 对于挂牌督办的重大事故隐患，负有安全生产监管职责的 部门应当协同生产经营单位建立健全“挂牌、整改、验收、销 号”闭环管理制度，加强对生产经营单位重大事故隐患整改的 跟踪督办和动态监管，指导、协助生产经营单位解决隐患整改 过程中的有关重大问题，督促生产经营单位及时整改到位。 挂牌督办的重大事故隐患应当明确项目名称、督办部门、 承担治理责任的生产经营单位（以下称“治理单位”）以及治 理目标、措施、时限等事项。涉及多个部门督办的，由应急管 理部门报请同级人民政府指定牵头督办部门和配合督办部门。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第二十七条", "text": "（挂牌督办项目的治理） 治理单位应当按照确定的目标、措施和时限，对挂牌督办 的重大事故隐患开展治理。 督办部门应当每月至少进行一次进展情况检查，每季度至 少召开一次推进会议，指导、协调解决治理过程中遇到的问 题，并对因非生产经营单位原因造成且治理单位自身难以排除 的事故隐患的治理提供技术支持。 治理项目基本完成的，治理单位应当组织专业技术人员、 专家或者委托具有相应资质的专业机构进行治理评估。经评估 达到治理目标的，由督办部门组织有关专业技术人员、专家进 行现场核查。经核查，达到治理目标的，应当解除督办并通报 同级应急管理部门；未达到治理目标的，督办部门应当依法责 令继续整改治理，直至达到治理目标。 由于客观原因无法按期完成治理目标的，治理单位应当向 督办部门说明理由和调整后的治理计划。督办部门经核查后同 意延期的，应当将相关情况通报同级应急管理部门。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第二十八条", "text": "（专业力量参与监督管理） 负有安全生产监管职责的部门、乡镇人民政府、街道办事 处、功能区管理机构可以根据实际需要，邀请专业技术人员、 专家学者参与监督管理，听取对专业技术问题的意见。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第二十九条", "text": "（信用信息记录和通报） 生产经营单位对事故隐患治理不力且负有责任的，负有安 全生产监管职责的部门应当按照规定记入该单位及其主要负责 人的信用信息记录，向市场监管、发展改革、规划资源、住房 城乡建设管理、地方金融等部门通报有关情况，并通过政府网 站或者新闻媒体向社会公布。 第四章 法律责任"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第三十条", "text": "（法律责任指引） 违反本办法规定的行为，按照《中华人民共和国安全生产 法》《上海市安全生产条例》等法律、法规的规定处理。"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第三十一条", "text": "（监管部门的法律责任） 负有安全生产监管职责的部门的工作人员有下列情形之一 的，依法给予处分；构成犯罪的，依法追究刑事责任： （一）接到事故隐患举报，未按照规定处理的； （二）未按照本办法规定，对生产经营单位安全生产事故 隐患排查治理情况履行监督检查职责，造成后果的； （三）发现生产经营单位存在安全生产事故隐患排查治理 的违法行为，不及时查处，或者有包庇、纵容违法行为，造成 后果的； （四）违法实施行政处罚的； （五）其他玩忽职守、滥用职权、徇私舞弊的行为。 第五章 附则"}, {"law": "上海市安全生产事故隐患排查治理办法.pdf", "no": "第三十二条", "text": "（实施日期） 本办法自2013 年1 月1 日起施行。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一条", "text": "为了预防、控制和消除传染病的发生与流行，保障公众生命安全和身体健康，防范和化解公共卫生风险，维护国家安全和社会稳定，根据宪法，制定本法。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第二条", "text": "传染病防治工作坚持中国共产党的领导，坚持人民至上、生命至上，坚持预防为主、防治结合的方针，坚持依法防控、科学防控的原则。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第三条", "text": "本法所称传染病，分为甲类传染病、乙类传染病、丙类传染病，以及突发原因不明的传染病等其他传染病。 甲类传染病，是指对人体健康和生命安全危害特别严重，可能造成重大经济损失和社会影响，需要特别严格管理、控制疫情蔓延的传染病，包括鼠疫、霍乱。 乙类传染病，是指对人体健康和生命安全危害严重，可能造成较大经济损失和社会影响，需要严格管理、降低发病率、减少危害的传染病，包括新型冠状病毒感染、传染性非典型肺炎、艾滋病、病毒性肝炎、脊髓灰质炎、人感染新亚型流感、麻疹、流行性出血热、狂犬病、流行性乙型脑炎、登革热、猴痘、炭疽、细菌性和阿米巴性痢疾、肺结核、伤寒和副伤寒、流行性脑脊髓膜炎、百日咳、白喉、新生儿破伤风、猩红热、布鲁氏菌病、淋病、梅毒、钩端螺旋体病、血吸虫病、疟疾。 丙类传染病，是指常见多发，对人体健康和生命安全造成危害，可能造成一定程度的经济损失和社会影响，需要关注流行趋势、控制暴发和流行的传染病，包括流行性感冒、流行性腮腺炎、风疹、急性出血性结膜炎、麻风病、流行性和地方性斑疹伤寒、黑热病、包虫病、丝虫病、手足口病，除霍乱、细菌性和阿米巴性痢疾、伤寒和副伤寒以外的感染性腹泻病。 国务院疾病预防控制部门根据传染病暴发、流行情况和危害程度，及时提出调整各类传染病目录的建议。调整甲类传染病目录，由国务院卫生健康主管部门报经国务院批准后予以公布；调整乙类、丙类传染病目录，由国务院卫生健康主管部门批准、公布。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第四条", "text": "突发原因不明的传染病需要采取本法规定的甲类传染病预防、控制措施的，国务院疾病预防控制部门及时提出建议，由国务院卫生健康主管部门报经国务院批准后予以公布。 对乙类传染病中的传染性非典型肺炎、炭疽中的肺炭疽，采取本法规定的甲类传染病预防、控制措施。其他乙类传染病需要采取本法规定的甲类传染病预防、控制措施的，依照前款规定的程序批准、公布。 需要解除依照本条规定采取的甲类传染病预防、控制措施的，国务院疾病预防控制部门及时提出建议，由国务院卫生健康主管部门报经国务院批准后予以公布。 依照本法规定采取甲类传染病预防、控制措施的传染病，适用本法有关甲类传染病的规定。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第五条", "text": "省级人民政府对本行政区域常见多发的其他传染病，可以根据情况决定按照乙类或者丙类传染病管理并予以公布，报国务院疾病预防控制部门备案。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六条", "text": "国家建立健全传染病防治体制机制，明确属地、部门、单位和个人责任，实行联防联控、群防群控。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第七条", "text": "各级人民政府加强对传染病防治工作的领导。 县级以上人民政府建立健全传染病防治的疾病预防控制、医疗救治、应急处置、物资保障和监督管理体系，加强传染病防治能力建设。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第八条", "text": "国务院卫生健康主管部门牵头组织协调全国传染病疫情应对工作，负责全国传染病医疗救治的组织指导工作。国务院疾病预防控制部门负责全国传染病预防、控制的组织指导工作，负责全国传染病疫情应对相关工作。国务院其他有关部门在各自职责范围内负责传染病防治有关工作。 县级以上地方人民政府卫生健康主管部门牵头组织协调本行政区域传染病疫情应对工作，负责本行政区域传染病医疗救治的组织指导工作。县级以上地方人民政府疾病预防控制部门负责本行政区域传染病预防、控制的组织指导工作，负责本行政区域传染病疫情应对相关工作。县级以上地方人民政府其他有关部门在各自职责范围内负责传染病防治有关工作。 中国人民解放军、中国人民武装警察部队的传染病防治工作，依照本法和中央军事委员会的有关规定办理，由中央军事委员会负责卫生工作的部门实施监督管理。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第九条", "text": "国务院和县级以上地方人民政府的重大传染病疫情联防联控机制开展疫情会商研判，组织协调、督促推进疫情防控工作。 发生重大传染病疫情，构成突发公共卫生事件的，国务院和县级以上地方人民政府依照有关突发公共卫生事件应对的法律、行政法规规定设立应急指挥机构、启动应急响应。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第十条", "text": "国家建立健全城乡一体、上下联动、功能完备的疾病预防控制网络。 国务院疾病预防控制部门领导各级疾病预防控制机构业务工作，建立上下联动的分工协作机制。 国家、省级疾病预防控制机构成立疾病预防控制专家委员会，为传染病防治提供咨询、评估、论证等专业技术支持。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第十一条", "text": "国家坚持中西医并重，加强中西医结合，充分发挥中医药在传染病防治中的作用。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第十二条", "text": "国家支持和鼓励开展传染病防治的科学研究，组织开展传染病防治和公共卫生研究工作以及多学科联合攻关，提高传染病防治的科学技术水平。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第十三条", "text": "国家支持和鼓励在传染病防治中运用现代信息技术。 传染病防治中开展个人信息收集、存储、使用、加工、传输、提供、公开、删除等个人信息处理活动，应当遵守《中华人民共和国民法典》、《中华人民共和国个人信息保护法》等法律、行政法规的规定，采取措施确保个人信息安全，保护个人隐私，不得过度收集个人信息；相关信息不得用于传染病防治以外的目的。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第十四条", "text": "中华人民共和国领域内的一切单位和个人应当支持传染病防治工作，接受和配合为预防、控制、消除传染病危害依法采取的调查、采集样本、检验检测、隔离治疗、医学观察等措施，根据传染病预防、控制需要采取必要的防护措施。 国家支持和鼓励单位和个人参与传染病防治工作。各级人民政府应当完善有关制度，提供便利措施，引导单位和个人参与传染病防治的宣传教育、疫情报告、志愿服务和捐赠等活动。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第十五条", "text": "疾病预防控制部门、街道办事处和乡镇人民政府应当开展群防群控工作，指导居民委员会、村民委员会协助做好城乡社区的传染病预防、控制工作。 居民委员会、村民委员会应当协助县级以上人民政府及其有关部门、街道办事处和乡镇人民政府做好城乡社区传染病预防、控制的宣传教育、健康提示以及疫情防控工作，组织城乡居民参与城乡社区的传染病预防、控制活动。 县级以上人民政府及其有关部门、街道办事处和乡镇人民政府应当为居民委员会、村民委员会开展传染病预防、控制工作提供必要的支持和保障。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第十六条", "text": "国家和社会应当关心、帮助传染病患者、病原携带者和疑似患者，使其得到及时救治。 任何单位或者个人不得歧视传染病患者、病原携带者和疑似患者，不得泄露个人隐私、个人信息。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第十七条", "text": "采取传染病预防、控制措施，应当依照法定权限和程序，与传染病暴发、流行和可能造成危害的程度、范围等相适应；有多种措施可供选择的，应当选择有利于最大程度保护单位和个人合法权益，且对他人权益损害和生产生活影响较小的措施，并根据情况变化及时调整。 单位和个人认为有关地方人民政府、卫生健康主管部门、疾病预防控制部门和其他有关部门，以及疾病预防控制机构、医疗机构等实施的相关行政行为或者传染病预防、控制措施，侵犯其合法权益的，可以依法申请行政复议、提起诉讼。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第十八条", "text": "国家开展传染病防治健康教育工作，加强传染病防治法治宣传，提高公众传染病防治健康素养和法治意识。 学校、托育机构应当结合年龄特点对学生和幼儿进行健康知识和传染病防治知识的教育。 新闻媒体应当开展传染病防治和公共卫生知识的公益宣传。 个人应当学习传染病防治知识，养成良好的卫生习惯，培养健康的生活方式。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第十九条", "text": "国家支持和鼓励开展传染病防治的国际交流与合作。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第二十条", "text": "对在传染病防治工作中做出显著成绩和贡献的单位和个人，按照国家有关规定给予表彰、奖励。 对因参与传染病防治工作致病、致残、死亡的人员，按照有关规定给予补助、抚恤和优待。 第二章 预 防"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第二十一条", "text": "各级人民政府组织开展爱国卫生运动，完善公共卫生设施，改善人居环境状况，加强社会健康管理，提升全民健康水平。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第二十二条", "text": "地方各级人民政府应当有计划地建设和改造城乡公共卫生设施，改善饮用水卫生条件，对污水、污物、粪便进行无害化处置。城市应当按照国家和地方有关标准修建公共厕所、垃圾和粪便无害化处置场以及排水和污水处理系统等公共卫生设施。农村应当逐步改造厕所，建立必要的卫生管理制度。 县级以上地方人民政府应当加强医疗废物收集处置能力建设。设区的市级人民政府应当确定医疗废物协同应急处置设施，提高重大传染病疫情医疗废物应急处置能力。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第二十三条", "text": "县级以上人民政府农业农村、水利、林业草原等部门依据职责指导、组织控制和消除农田、湖区、河流、牧场、林区、草原地区的鼠害与血吸虫危害，以及其他传播传染病的动物和病媒生物的危害。 交通运输、铁路、民用航空等部门依据职责指导、监督交通运输经营单位以及车站、港口、机场等相关场所的运营单位消除鼠害和蚊、蝇等病媒生物的危害。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第二十四条", "text": "国家实行免疫规划制度。政府免费向居民提供免疫规划疫苗。 国务院疾病预防控制部门制定国家免疫规划。省级人民政府在执行国家免疫规划时，可以根据本行政区域疾病预防、控制需要，增加免疫规划疫苗种类，加强重点地区、重点人群的预防接种，报国务院疾病预防控制部门备案并公布。 国家对儿童实行预防接种证制度。医疗机构、疾病预防控制机构与儿童的监护人、所在学校和托育机构应当相互配合，保证儿童及时接种免疫规划疫苗。 出现特别重大突发公共卫生事件或者其他严重威胁公众健康的紧急事件，可以依照《中华人民共和国疫苗管理法》的规定在一定范围和期限内紧急使用疫苗。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第二十五条", "text": "各级疾病预防控制机构在传染病预防、控制中履行下列职责： （一）实施传染病预防控制规划，制定传染病预防控制技术方案并组织实施； （二）组织开展传染病监测，收集、分析和报告传染病监测信息，预测传染病的发生、流行趋势； （三）开展对传染病疫情和突发公共卫生事件的流行病学调查、风险评估、现场处理及其效果评价； （四）开展传染病实验室检验检测、诊断、病原学鉴定； （五）实施免疫规划，负责预防性生物制品的使用管理； （六）开展健康教育、咨询，普及传染病防治知识； （七）指导、培训下级疾病预防控制机构及其工作人员开展传染病预防、控制工作； （八）指导医疗机构和学校、托育机构、养老机构、康复机构、福利机构、未成年人救助保护机构、救助管理机构、体育场馆、监管场所、车站、港口、机场等重点场所开展传染病预防、控制工作； （九）开展传染病防治基础性研究、应用性研究和卫生评价，提供技术咨询。 国家、省级疾病预防控制机构主要负责对传染病发生、流行以及分布进行监测，对重点传染病流行趋势进行预测，提出预防、控制对策，参与并指导对暴发的传染病疫情进行调查处理，开展传染病病原学鉴定，建立检验检测质量控制体系，开展基础性研究、应用性研究、卫生评价以及标准规范制定。 设区的市级、县级疾病预防控制机构主要负责传染病预防控制规划、预防控制技术方案的落实，组织实施免疫、消毒，指导病媒生物危害控制，普及传染病防治知识，负责本地区传染病和突发公共卫生事件监测、报告，开展流行病学调查和常见病原微生物检测，开展应用性研究和卫生评价。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第二十六条", "text": "二级以上医疗机构应当有专门的科室并指定专门的人员，承担本机构的传染病预防、控制和传染病疫情报告以及责任区域内的传染病预防工作。 基层医疗卫生机构应当有专门的科室或者指定人员负责传染病预防、控制管理工作，在疾病预防控制机构指导下，承担本机构的传染病预防、控制和责任区域内的传染病防治健康教育、预防接种、传染病疫情报告、传染病患者健康监测以及城乡社区传染病疫情防控指导等工作。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第二十七条", "text": "医疗机构的基本标准、建筑设计和服务流程应当符合预防医疗机构感染的要求，降低传染病在医疗机构内传播的风险。 医疗机构应当严格执行国家规定的管理制度、操作规范，加强与医疗机构感染有关的危险因素监测、安全防护、消毒、隔离和医疗废物、医疗污水处置工作，防止传染病在医疗机构内的传播。 医疗机构应当按照规定对使用的医疗器械进行消毒或者灭菌；对按照规定一次性使用的医疗器械，应当在使用后予以销毁。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第二十八条", "text": "国务院疾病预防控制部门拟订国家重点传染病和突发原因不明的传染病预防控制应急预案，由国务院卫生健康主管部门批准、公布。 县级以上地方人民政府制定本行政区域重点传染病和突发原因不明的传染病预防控制应急预案，报上一级人民政府备案并予以公布。鼓励毗邻、相近地区的地方人民政府制定应对区域性传染病的联合预防控制应急预案。 传染病预防控制应急预案应当根据本法和其他有关法律、法规的规定，针对传染病暴发、流行情况和危害程度，具体规定传染病预防、控制工作的组织指挥体系和职责，传染病预防、监测、疫情报告和通报、疫情风险评估、预警、应急工作方案、人员调集以及物资和技术储备与调用等内容。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第二十九条", "text": "医疗卫生机构和学校、托育机构、养老机构、康复机构、福利机构、未成年人救助保护机构、救助管理机构、体育场馆、监管场所、车站、港口、机场等重点场所，应当制定本单位传染病预防控制应急预案。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第三十条", "text": "传染病预防控制应急预案应当增强科学性、针对性和可操作性，并根据实际需要和形势变化及时修订。 县级以上人民政府疾病预防控制部门应当根据有关传染病预防控制应急预案定期组织开展演练。医疗卫生机构和学校、托育机构、养老机构、康复机构、福利机构、未成年人救助保护机构、救助管理机构、体育场馆、监管场所、车站、港口、机场等重点场所应当根据本单位传染病预防控制应急预案开展演练。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第三十一条", "text": "疾病预防控制机构、医疗机构的实验室和从事病原微生物实验的单位，应当遵守有关病原微生物实验室生物安全的法律、行政法规规定，符合国家规定的条件和技术标准，建立严格的管理制度，对传染病病原体和样本按照规定的措施实行严格管理，严防传染病病原体的实验室感染和扩散。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第三十二条", "text": "采供血机构、生物制品生产单位应当严格执行国家有关规定，保证血液、血液制品的质量和安全。 禁止非法采集血液或者组织他人出卖血液。 疾病预防控制机构、医疗机构使用血液和血液制品，应当遵守国家有关规定，防止因输入血液、使用血液制品引起经血液传播疾病的发生。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第三十三条", "text": "各级人民政府应当加强艾滋病的防治工作，采取预防、控制措施，防止艾滋病的传播。具体办法由国务院制定。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第三十四条", "text": "国家建立健全人畜共患传染病防治的协作机制，统筹规划、协同推进预防、控制工作，做好重点人群健康教育、传染病监测、疫情调查处置和信息通报等工作。 县级以上人民政府农业农村、林业草原、卫生健康、疾病预防控制等部门依据职责负责与人畜共患传染病有关的动物传染病的防治管理工作，重点加强鼠疫、狂犬病、人感染新亚型流感、布鲁氏菌病、炭疽、血吸虫病、包虫病等人畜共患传染病的防治工作。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第三十五条", "text": "国家建立病原微生物菌（毒）种保藏库。 对病原微生物菌（毒）种和传染病检测样本的采集、保藏、提供、携带、运输、使用实行分类管理，建立健全严格的管理制度。从事相关活动应当遵守有关病原微生物实验室生物安全的法律、行政法规规定；依法需要经过批准或者进行备案的，应当取得批准或者进行备案。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第三十六条", "text": "对被传染病病原体污染的水、物品和场所，有关单位和个人应当在疾病预防控制机构的指导下或者按照其提出的卫生要求，进行科学严格消毒处理；拒绝消毒处理的，由当地疾病预防控制部门组织进行强制消毒处理。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第三十七条", "text": "在国家确认的自然疫源地计划兴建水利、交通、旅游、能源等大型建设项目的，应当事先由省级以上疾病预防控制机构对施工环境进行卫生调查。建设单位应当根据疾病预防控制机构的意见，采取必要的传染病预防、控制措施。施工期间，建设单位应当设专人负责工地上的卫生防疫工作。施工期间和工程竣工后，疾病预防控制机构应当对可能发生的传染病进行监测。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第三十八条", "text": "用于传染病防治的消毒产品、饮用水供水单位供应的饮用水和涉及饮用水卫生安全的产品，应当符合国家卫生标准和卫生规范。 用于传染病防治的消毒产品的生产企业，应当经省级人民政府疾病预防控制部门批准，取得卫生许可。利用新材料、新工艺技术和新杀菌原理生产的消毒剂和消毒器械，应当经国务院疾病预防控制部门批准，取得卫生许可；其他消毒剂、消毒器械以及抗（抑）菌剂，应当报省级人民政府疾病预防控制部门备案。 饮用水供水单位应当经设区的市级或者县级人民政府疾病预防控制部门批准，取得卫生许可。涉及饮用水卫生安全的产品应当经省级以上人民政府疾病预防控制部门批准，取得卫生许可。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第三十九条", "text": "传染病患者、病原携带者和疑似患者应当如实提供相关信息，在治愈前或者在排除传染病嫌疑前，不得从事法律、行政法规和国务院疾病预防控制部门规定禁止从事的易使该传染病扩散的工作。 传染病患者、病原携带者、疑似患者以及上述人员的密切接触者应当采取必要的防护措施。 任何单位或者个人不得以任何方式故意传播传染病。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第四十条", "text": "学校、托育机构、养老机构、康复机构、福利机构、未成年人救助保护机构、救助管理机构、体育场馆、监管场所、车站、港口、机场等重点场所应当落实主体责任，加强传染病预防、控制能力建设，在疾病预防控制机构指导下开展传染病预防、控制工作。 第三章 监测、报告和预警"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第四十一条", "text": "国家加强传染病监测预警工作，建设多点触发、反应快速、权威高效的传染病监测预警体系。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第四十二条", "text": "国家建立健全传染病监测制度。 国务院疾病预防控制部门会同国务院有关部门制定国家传染病监测规划和方案。省级人民政府疾病预防控制部门会同同级人民政府有关部门，根据国家传染病监测规划和方案，制定本行政区域传染病监测计划和工作方案，报国务院疾病预防控制部门审核后实施。 国家加强传染病监测，依托传染病监测系统实行传染病疫情和突发公共卫生事件网络直报，建立重点传染病以及原因不明的传染病监测哨点，拓展传染病症状监测范围，收集传染病症候群、群体性不明原因疾病等信息，建立传染病病原学监测网络，多途径、多渠道开展多病原监测，建立智慧化多点触发机制，增强监测的敏感性和准确性，提高实时分析、集中研判能力，及时发现传染病疫情和突发公共卫生事件。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第四十三条", "text": "疾病预防控制机构对传染病的发生、流行以及影响其发生、流行的因素进行监测，及时掌握重点传染病流行强度、危害程度以及病原体变异情况。 疾病预防控制机构应当加强原因不明的传染病监测，提高快速发现和及时甄别能力；对新发传染病、境内已消除的传染病以及境外发生、境内尚未发生的传染病进行监测。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第四十四条", "text": "国家建立跨部门、跨地域的传染病监测信息共享机制，加强卫生健康、疾病预防控制、生态环境、农业农村、海关、市场监督管理、移民管理、林业草原等部门的联动监测和信息共享。 国家建立临床医疗、疾病预防控制信息的互通共享制度，加强医防协同，推动医疗机构等的信息系统与传染病监测系统互联互通，建立健全传染病诊断、病原体检测数据等的自动获取机制，规范信息共享流程，确保个人信息安全。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第四十五条", "text": "国家建立健全传染病疫情报告制度。 疾病预防控制机构、医疗机构和采供血机构及其执行职务的人员发现甲类传染病患者、病原携带者、疑似患者或者新发传染病、突发原因不明的传染病，以及其他传染病暴发、流行时，应当于两小时内进行网络直报；发现乙类传染病患者、疑似患者或者国务院疾病预防控制部门规定需要报告的乙类传染病病原携带者时，应当于二十四小时内进行网络直报；发现丙类传染病患者时，应当于二十四小时内进行网络直报。 中国人民解放军、中国人民武装警察部队的医疗机构向社会公众提供医疗服务的，应当依照前款规定报告传染病疫情。 传染病疫情报告遵循属地管理原则，具体办法由国务院疾病预防控制部门制定。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第四十六条", "text": "疾病预防控制机构、医疗机构和采供血机构应当建立健全传染病疫情报告管理制度，加强传染病疫情和相关信息报告的培训、日常管理和质量控制，定期对本机构报告的传染病疫情和相关信息以及报告质量进行分析、汇总和通报。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第四十七条", "text": "学校、托育机构、养老机构、康复机构、福利机构、未成年人救助保护机构、救助管理机构、体育场馆、监管场所、车站、港口、机场等重点场所发现传染病患者、疑似患者时，应当按照国务院疾病预防控制部门的规定，向所在地疾病预防控制机构报告有关信息。 检验检测机构等应当按照国务院疾病预防控制部门的规定，向所在地疾病预防控制机构报告与传染病防治有关的信息。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第四十八条", "text": "任何单位和个人发现传染病患者、疑似患者时，应当及时向附近的疾病预防控制机构、医疗机构或者疾病预防控制部门报告。 疾病预防控制部门应当公布热线电话等，畅通报告途径，确保及时接收、调查和处理相关报告信息。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第四十九条", "text": "疾病预防控制机构应当设立或者指定专门的部门、人员负责传染病疫情信息管理工作，主动收集、分析、调查、核实传染病疫情信息。 疾病预防控制机构接到甲类传染病、新发传染病、突发原因不明的传染病报告或者发现传染病暴发、流行时，应当于两小时内完成传染病疫情信息核实以及向同级卫生健康主管部门、疾病预防控制部门和上级疾病预防控制机构报告的工作。疾病预防控制部门接到报告后应当立即报告同级人民政府，同时报告上一级人民政府卫生健康主管部门、疾病预防控制部门和国务院卫生健康主管部门、疾病预防控制部门。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第五十条", "text": "任何单位或者个人不得干预传染病疫情报告。 依照本法规定负有传染病疫情报告职责的人民政府有关部门、疾病预防控制机构、医疗机构、采供血机构及其工作人员，不得隐瞒、谎报、缓报、漏报传染病疫情。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第五十一条", "text": "对及时发现并报告新发传染病、突发原因不明的传染病的单位和个人，按照国家有关规定给予奖励。 对经调查排除传染病疫情的，报告的单位和个人不承担法律责任。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第五十二条", "text": "国家建立健全传染病疫情风险评估制度。 疾病预防控制机构应当及时分析传染病和健康危害因素相关信息，评估发生传染病疫情的风险、可能造成的影响以及疫情发展态势。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第五十三条", "text": "国家建立健全传染病预警制度。 疾病预防控制机构根据传染病监测信息和传染病疫情风险评估结果，向社会发布健康风险提示；发现可能发生突发公共卫生事件，经评估认为需要发布预警的，向同级疾病预防控制部门提出发布预警的建议。疾病预防控制部门收到建议后应当及时组织专家进行分析研判，需要发布预警的，由卫生健康主管部门、疾病预防控制部门立即向同级人民政府报告。 县级以上人民政府依照有关突发公共卫生事件应对的法律、行政法规和国务院规定的权限和程序，决定向社会发布预警。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第五十四条", "text": "县级以上地方人民政府疾病预防控制部门应当及时向本行政区域的疾病预防控制机构和医疗机构通报传染病疫情以及监测、预警的相关信息。接到通报的疾病预防控制机构和医疗机构应当及时报告本机构的主要负责人，并告知本机构的有关人员。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第五十五条", "text": "国务院疾病预防控制部门应当及时向省级人民政府疾病预防控制部门和中央军事委员会负责卫生工作的部门通报全国传染病疫情以及监测、预警的相关信息。中央军事委员会负责卫生工作的部门发现传染病疫情时，应当向国务院疾病预防控制部门通报。 毗邻或者相关地区的地方人民政府疾病预防控制部门，应当及时相互通报本行政区域的传染病疫情以及监测、预警的相关信息。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第五十六条", "text": "县级以上人民政府疾病预防控制部门与同级人民政府教育、公安、民政、司法行政、生态环境、农业农村、市场监督管理、林业草原、中医药等部门建立传染病疫情通报机制，及时共享传染病疫情信息。 传染病暴发、流行时，国务院卫生健康、疾病预防控制、外交、工业和信息化、公安、交通运输、铁路、民用航空、海关、移民管理等部门以及中国人民解放军、中国人民武装警察部队的有关单位和部门等建立工作机制，及时共享传染病疫情信息。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第五十七条", "text": "国家建立健全传染病疫情信息公布制度。 国务院疾病预防控制部门定期向社会公布全国传染病疫情信息。县级以上地方人民政府疾病预防控制部门定期向社会公布本行政区域的传染病疫情信息。 传染病暴发、流行时，县级以上地方人民政府疾病预防控制部门应当及时、准确地向社会公布本行政区域传染病名称、流行传播范围以及确诊病例、疑似病例、死亡病例数量等传染病疫情信息。传染病跨省级行政区域暴发、流行时，国务院疾病预防控制部门应当及时、准确地向社会公布上述信息。 县级以上人民政府疾病预防控制部门发现虚假或者不完整传染病疫情信息的，应当及时发布准确的信息予以澄清。 传染病疫情信息公布的具体办法由国务院疾病预防控制部门制定。 第四章 疫情控制"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第五十八条", "text": "医疗机构、疾病预防控制机构发现甲类传染病时，应当立即采取下列措施，并向县级以上地方人民政府疾病预防控制部门报告： （一）对甲类传染病患者、病原携带者，予以隔离治疗、医学观察； （二）对甲类传染病疑似患者，确诊前单独隔离治疗； （三）对甲类传染病患者、病原携带者、疑似患者的密切接触者，予以医学观察，并采取其他必要的预防措施。 医疗机构、疾病预防控制机构对甲类传染病患者、病原携带者、疑似患者以及上述人员的密切接触者采取隔离治疗、医学观察措施，应当根据国家有关规定和医学检查结果科学合理确定具体人员范围和期限，并根据情况变化及时调整。采取隔离治疗、医学观察措施，不得超出规定的范围和期限。 医疗机构、疾病预防控制机构应当向甲类传染病患者、病原携带者、疑似患者以及上述人员的密切接触者书面告知诊断或者判定结果和依法应当采取的措施。 甲类传染病患者、病原携带者、疑似患者以及上述人员的密切接触者应当主动接受和配合医学检查、隔离治疗、医学观察等措施。 拒绝隔离治疗、医学观察或者隔离治疗、医学观察的期限未满擅自脱离的，由公安机关协助医疗机构、疾病预防控制机构采取强制隔离治疗、医学观察措施。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第五十九条", "text": "医疗机构、疾病预防控制机构接到其他单位和个人报告甲类传染病的，有关甲类传染病患者、疑似患者的移交按照国务院疾病预防控制部门的规定执行。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十条", "text": "医疗机构发现乙类或者丙类传染病患者时，应当根据病情采取必要的治疗和控制传播措施。 县级以上地方人民政府疾病预防控制部门指定的医疗机构对肺结核患者进行治疗；对具有传染性的肺结核患者进行耐药检查和规范隔离治疗，对其密切接触者进行筛查。基层医疗卫生机构对肺结核患者进行健康管理。具体办法由国务院疾病预防控制部门拟订，报国务院卫生健康主管部门审核、发布。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十一条", "text": "医疗机构对本机构内被传染病病原体污染的场所、物品以及医疗废物、医疗污水，应当依照有关法律、行政法规的规定实施消毒和无害化处置。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十二条", "text": "疾病预防控制机构发现传染病疫情或者接到传染病疫情报告时，应当及时采取下列措施： （一）对传染病疫情进行流行病学调查，根据调查情况提出对受影响的相关区域的防控建议，对被污染的场所进行卫生处理，判定密切接触者，指导做好对密切接触者的管理，并向疾病预防控制部门提出传染病疫情防控方案； （二）传染病暴发、流行时，对受影响的相关区域进行卫生处理，向疾病预防控制部门提出传染病疫情防控方案，并按照传染病疫情防控相关要求采取措施； （三）指导下级疾病预防控制机构、医疗机构实施传染病预防、控制措施，组织、指导有关单位对传染病疫情的处理。 有关单位和个人应当接受和配合疾病预防控制机构开展流行病学调查，如实提供信息。疾病预防控制机构开展流行病学调查，需要有关部门和单位协助的，有关部门和单位应当予以协助。 发生传染病疫情时，疾病预防控制机构和省级以上人民政府疾病预防控制部门指派的其他与传染病有关的专业技术机构，可以进入受影响的相关区域进行调查、采集样本、技术分析和检验检测。被调查单位和个人应当如实提供信息；任何单位或者个人不得隐瞒信息、阻碍调查。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十三条", "text": "传染病暴发、流行时，县级以上地方人民政府应当立即组织力量，按照传染病预防控制应急预案进行防治，控制传染源，切断传染病的传播途径；发生重大传染病疫情，经评估必要时，可以采取下列紧急措施： （一）限制或者停止集市、影剧院演出或者其他人群聚集的活动； （二）停工、停业、停课； （三）封闭或者封存被传染病病原体污染的公共饮用水源、食品以及相关物品； （四）控制或者扑杀、无害化处理染疫动物； （五）封闭可能造成传染病扩散的场所； （六）防止传染病传播的其他必要措施。 县级以上地方人民政府采取前款规定的紧急措施，应当同时向上一级人民政府报告。接到报告的上级人民政府认为采取的紧急措施不适当的，应当立即调整或者撤销。 必要时，国务院或者国务院授权的部门可以决定在全国或者部分区域采取本条第一款规定的紧急措施。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十四条", "text": "对已经发生甲类传染病病例的场所或者该场所内的特定区域的人员，所在地县级以上地方人民政府可以实施隔离措施，同时向上一级人民政府报告。接到报告的上级人民政府认为实施的隔离措施不适当的，应当立即调整或者撤销。 被实施隔离措施的人员应当予以配合；拒绝执行隔离措施的，由公安机关协助疾病预防控制机构采取强制隔离措施。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十五条", "text": "发生新发传染病、突发原因不明的传染病，县级以上地方人民政府经评估认为确有必要的，可以预先采取本法规定的甲类传染病预防、控制措施，同时向上一级人民政府报告。接到报告的上级人民政府认为预先采取的预防、控制措施不适当的，应当立即调整或者撤销。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十六条", "text": "因甲类、乙类传染病发生重大传染病疫情时，县级以上地方人民政府报经上一级人民政府决定，可以对进入或者离开本行政区域受影响的相关区域的人员、物资和交通工具实施卫生检疫。 因甲类传染病发生重大传染病疫情时，省级人民政府可以决定对本行政区域受影响的相关区域实施封锁；封锁大、中城市或者跨省级行政区域的受影响的相关区域，以及因封锁导致中断干线交通或者封锁国境的，由国务院决定。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十六条", "text": "规定采取传染病疫情防控措施时，决定采取措施的机关应当向社会发布公告，明确措施的具体内容、实施范围和实施期限，并进行必要的解释说明。相关疫情防控措施的解除，由原决定机关决定并宣布。 采取前款规定的措施期间，当地人民政府应当保障食品、饮用水等基本生活必需品的供应，提供基本医疗服务，维护社会稳定；对未成年人、老年人、残疾人、孕产期和哺乳期的妇女以及需要及时救治的伤病人员等群体给予特殊照顾和安排，并确保相关人员获得医疗救治。当地人民政府应当公布求助电话等，畅通求助途径，及时向有需求的人员提供帮助。 因采取本法"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十六条", "text": "规定的措施导致劳动者不能工作的，用人单位应当保留其工作，按照规定支付其在此期间的工资、发放生活费。用人单位可以按照规定享受有关帮扶政策。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十八条", "text": "发生甲类传染病时，为了防止该传染病通过交通工具及其乘运的人员、物资传播，省级人民政府可以决定实施交通卫生检疫。具体办法由国务院制定。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十九条", "text": "发生重大传染病疫情时，根据传染病疫情防控的需要，国务院及其有关部门有权在全国或者跨省级行政区域范围内，县级以上地方人民政府及其有关部门有权在本行政区域内，紧急调集人员或者调用储备物资，临时征用房屋、交通工具以及相关设施、设备、场地和其他物资，要求有关单位和个人提供技术支持。 紧急调集人员的，应当按照规定给予合理报酬。临时征用房屋、交通工具以及相关设施、设备、场地和其他物资，要求有关单位和个人提供技术支持的，应当依法给予公平、合理的补偿；能返还的，应当及时返还。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第七十条", "text": "医疗机构、疾病预防控制机构、检验检测机构应当按照传染病检验检测技术规范和标准开展检验检测活动，加强检验检测质量控制。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第七十一条", "text": "患甲类传染病、炭疽死亡的，应当将其尸体立即进行卫生处理，就近火化；患其他传染病死亡的，必要时应当将其尸体进行卫生处理后火化或者按照规定深埋。对尸体进行火化或者深埋应当及时告知死者家属。 为了查找传染病病因，医疗机构在必要时可以按照国务院卫生健康主管部门、疾病预防控制部门的规定，对传染病患者尸体或者疑似传染病患者尸体进行解剖查验，并应当及时告知死者家属。对尸体进行解剖查验应当在符合生物安全条件的场所进行。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十六条", "text": "规定的受影响的相关区域中被传染病病原体污染或者可能被传染病病原体污染的物品，经消毒可以使用的，应当在疾病预防控制机构的指导下，进行消毒处理后，方可使用、出售和运输。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第七十三条", "text": "传染病暴发、流行时，有关生产、供应单位应当及时生产、供应传染病疫情防控所需的药品、医疗器械和其他应急物资。交通运输、邮政、快递经营单位应当优先运送参与传染病疫情防控的人员以及传染病疫情防控所需的药品、医疗器械和其他应急物资。县级以上人民政府有关部门应当做好组织协调工作。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第七十四条", "text": "单位和个人认为采取本法"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十六条", "text": "规定的传染病疫情防控措施侵犯其合法权益的，可以向县级以上地方人民政府或者其指定的部门提出申诉，申诉期间相关措施不停止执行。县级以上地方人民政府应当畅通申诉渠道，完善处理程序，确保有关申诉及时处理。 第五章 医疗救治"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第七十五条", "text": "县级以上人民政府应当加强和完善常态与应急相结合的传染病医疗救治服务网络建设，指定具备传染病救治条件和能力的医疗机构承担传染病救治任务，根据传染病救治需要设置传染病专科医院。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第七十六条", "text": "国家建立健全重大传染病疫情医疗救治体系，建立由传染病专科医院、综合医院、中医医院、院前急救机构、临时性救治场所、基层医疗卫生机构、血站等构成的综合医疗救治体系，对传染病患者进行分类救治，加强重症患者医疗救治，提高重大传染病疫情医疗救治能力。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第七十七条", "text": "医疗机构应当对传染病患者、疑似患者提供医疗救护、现场救援和接诊治疗，按照规定填写并妥善保管病历记录以及其他有关资料。 医疗机构应当按照国务院卫生健康主管部门的规定设置发热门诊，加强发热门诊标准化建设，优化服务流程，提高服务能力。 医疗机构应当实行传染病预检、分诊制度；对传染病患者、疑似患者，应当引导至相对隔离的分诊点进行初诊。医疗机构不具备相应救治能力的，应当将传染病患者、疑似患者及其病历记录一并转至具备相应救治能力的医疗机构。转诊过程中，对传染病患者、疑似患者应当采取必要的防护措施。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第七十八条", "text": "医疗机构应当按照传染病诊断标准和治疗要求采取相应措施，充分发挥中西医各自优势，加强中西医结合，提高传染病诊断和救治能力。 国家支持和鼓励医疗机构结合自身特色，加强传染病诊断和救治研究。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第七十九条", "text": "国家鼓励传染病防治用药品、医疗器械的研制和创新，对防治传染病急需的药品、医疗器械予以优先审评审批。 因重大传染病疫情医疗救治紧急需要，医师可以按照国家统一制定的诊疗方案，在一定范围和期限内采用药品说明书中未明确的药品用法进行救治。 发生重大传染病疫情，构成特别重大突发公共卫生事件的，国务院卫生健康主管部门根据传染病预防、控制和医疗救治需要提出紧急使用药物的建议，经国务院药品监督管理部门组织论证同意后可以在一定范围和期限内紧急使用。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第八十条", "text": "国家建立重大传染病疫情心理援助制度。县级以上地方人民政府应当组织专业力量，定期开展培训和演练；发生重大传染病疫情时，对传染病患者、接受医学观察的人员、病亡者家属、相关工作人员等重点人群以及社会公众及时提供心理疏导和心理干预等服务。 第六章 保障措施"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第八十一条", "text": "国家将传染病防治工作纳入国民经济和社会发展规划，县级以上地方人民政府将传染病防治工作纳入本行政区域的国民经济和社会发展规划。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第八十二条", "text": "县级以上地方人民政府按照本级政府职责，负责本行政区域传染病预防、控制工作经费。 国务院卫生健康主管部门、疾病预防控制部门会同国务院有关部门，根据传染病流行趋势，确定全国传染病预防、监测、预测、预警、控制、救治、监督检查等项目。各级财政按照事权划分做好经费保障。 省级人民政府根据本行政区域传染病流行趋势，在国务院卫生健康主管部门、疾病预防控制部门确定的项目基础上，确定传染病预防、监测、检测、风险评估、预测、预警、控制、救治、监督检查等项目，并保障项目的实施经费。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第八十三条", "text": "县级以上人民政府应当按照规定落实疾病预防控制机构基本建设、设备购置、学科建设、人才培养等相关经费；对其他医疗卫生机构承担疾病预防控制任务所需经费按照规定予以保障。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第八十四条", "text": "国家加强基层传染病防治体系建设，扶持欠发达地区、民族地区和边境地区的传染病防治工作。 地方各级人民政府应当保障基层传染病预防、控制工作的必要经费。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第八十五条", "text": "国家加强医疗机构疾病预防控制能力建设，持续提升传染病专科医院、综合医院的传染病监测、检验检测、诊断和救治、科学研究等能力和水平。 国家创新医防协同、医防融合机制，推进医疗机构与疾病预防控制机构深度协作。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第八十六条", "text": "国家加强传染病防治人才队伍建设，推动传染病防治相关学科建设。 开设医学专业的院校应当加强预防医学教育和科学研究，对在校医学专业学生以及其他与传染病防治相关的人员进行预防医学教育和培训，为传染病防治工作提供专业技术支持。 疾病预防控制机构、医疗机构等应当定期对其工作人员进行传染病防治知识、技能的培训。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第八十七条", "text": "县级以上人民政府应当加强疾病预防控制信息化建设，将其纳入全民健康信息化建设。 县级以上人民政府应当建立传染病预防控制信息共享机制，利用全民健康信息平台、政务数据共享平台、应急管理信息系统等，共享并综合应用相关数据。 国家加强传染病防治相关网络安全和数据安全管理工作，提高技术防范水平。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第八十八条", "text": "对符合国家规定的传染病医疗费用，基本医疗保险按照规定予以支付。 对患者、疑似患者治疗甲类传染病以及依照本法规定采取甲类传染病预防、控制措施的传染病的医疗费用，基本医疗保险、大病保险、医疗救助等按照规定支付后，其个人负担部分，政府按照规定予以补助。 国家对患有特定传染病的困难人群实行医疗救助，减免医疗费用。 国家鼓励商业保险机构开发传染病防治相关保险产品。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第八十九条", "text": "国家建立健全公共卫生应急物资保障体系，提高传染病疫情防控应急物资保障水平，县级以上人民政府发展改革部门统筹防控应急物资保障工作。 国家加强医药储备，将传染病防治相关药品、医疗器械、卫生防护用品等物资纳入公共卫生应急物资保障体系，实行中央和地方两级储备。 国务院工业和信息化部门会同国务院有关部门，根据传染病预防、控制和公共卫生应急准备的需要，加强医药实物储备、产能储备、技术储备，指导地方开展医药储备工作，完善储备调整、调用和轮换机制。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第九十条", "text": "国家建立少见罕见传染病和境内已消除的传染病防治能力储备机制，支持相关疾病预防控制机构、医疗机构、科研机构持续开展相关培训、基础性和应用性研究、现场防治等工作，支持相关专家参与国际防控工作，持续保持对上述传染病进行识别、检验检测、诊断和救治的能力。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第九十一条", "text": "对从事传染病预防、医疗、科研、教学和现场处理疫情的人员，以及在生产、工作中接触传染病病原体的其他人员，按照国家规定采取有效的卫生防护措施和医疗保健措施，并给予适当的津贴。 第七章 监督管理"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第九十二条", "text": "县级以上人民政府应当定期研究部署重大传染病疫情防控等疾病预防控制工作，定期向社会发布传染病防治工作报告，向本级人民代表大会常务委员会报告传染病防治工作，依法接受监督。 县级以上人民政府对下级人民政府履行传染病防治职责进行监督。地方人民政府未履行传染病防治职责的，上级人民政府可以对其主要负责人进行约谈。被约谈的地方人民政府应当立即采取措施进行整改，约谈和整改情况应当纳入地方人民政府工作评议、考核记录。履行传染病防治职责不力、失职失责，造成严重后果或者恶劣影响的，依法进行问责。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第九十三条", "text": "县级以上人民政府疾病预防控制部门对传染病防治工作履行下列监督检查职责： （一）对下级人民政府疾病预防控制部门履行本法规定的职责进行监督检查； （二）对疾病预防控制机构、医疗机构、采供血机构的传染病预防、控制工作进行监督检查； （三）对用于传染病防治的消毒产品及其生产企业、饮用水供水单位以及涉及饮用水卫生安全的产品进行监督检查； （四）对公共场所、学校、托育机构的卫生条件和传染病预防、控制措施进行监督检查。 县级以上人民政府卫生健康、疾病预防控制等部门依据职责对病原微生物菌（毒）种和传染病检测样本的采集、保藏、提供、携带、运输、使用进行监督检查。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第九十四条", "text": "县级以上人民政府卫生健康主管部门、疾病预防控制部门在履行监督检查职责时，有权进入传染病疫情发生现场及相关单位，开展查阅或者复制有关资料、采集样本、制作现场笔录等调查取证工作。被检查单位应当予以配合，不得拒绝、阻挠。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第九十五条", "text": "县级以上地方人民政府疾病预防控制部门在履行监督检查职责时，发现可能被传染病病原体污染的公共饮用水源、食品以及相关物品，如不及时采取控制措施可能导致传染病传播、暴发、流行的，应当采取封闭公共饮用水源、封存食品以及相关物品或者暂停销售的临时控制措施，并予以检验或者进行消毒处理。经检验，对被污染的食品，应当予以销毁；对未被污染的食品或者经消毒处理后可以使用的物品，应当及时解除控制措施。 根据县级以上地方人民政府采取的传染病预防、控制措施，市场监督管理部门可以采取封存或者暂停销售可能导致传染病传播、暴发、流行的食品以及相关物品等措施。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第九十六条", "text": "县级以上人民政府卫生健康主管部门、疾病预防控制部门工作人员依法执行职务时，应当不少于两人，并出示执法证件，填写执法文书。 执法文书经核对无误后，应当由执法人员和当事人签名。当事人拒绝签名的，执法人员应当注明情况。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第九十七条", "text": "县级以上人民政府卫生健康主管部门、疾病预防控制部门应当依法建立健全内部监督制度，对其工作人员依据法定职权和程序履行职责的情况进行监督。 上级人民政府卫生健康主管部门、疾病预防控制部门发现下级人民政府卫生健康主管部门、疾病预防控制部门不及时处理职责范围内的事项或者不履行职责的，应当责令纠正或者直接予以处理。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第九十八条", "text": "县级以上人民政府卫生健康主管部门、疾病预防控制部门和其他有关部门应当依法履行职责，自觉接受社会监督。 任何单位和个人对违反本法规定的行为，有权向县级以上人民政府及其卫生健康主管部门、疾病预防控制部门和有关机关举报。接到举报的机关应当及时调查、处理。对查证属实的举报，按照规定给予举报人奖励。县级以上人民政府及其卫生健康主管部门、疾病预防控制部门和有关机关应当对举报人的信息予以保密，保护举报人的合法权益。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第九十九条", "text": "卫生健康、疾病预防控制等部门发现涉嫌传染病防治相关犯罪的，应当按照有关规定及时将案件移送公安机关。对移送的案件，公安机关应当及时审查处理。 对依法不需要追究刑事责任或者免予刑事处罚，但依法应当追究行政责任的，公安机关、人民检察院、人民法院应当及时将案件移送卫生健康、疾病预防控制等部门，有关部门应当依法处理。 公安机关、人民检察院、人民法院商请卫生健康、疾病预防控制等部门提供检验检测结论、认定意见以及对涉案物品进行无害化处置等协助的，有关部门应当及时予以协助。 第八章 法律责任"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百条", "text": "违反本法规定，地方各级人民政府未依法履行报告职责，隐瞒、谎报、缓报、漏报传染病疫情，干预传染病疫情报告，或者在传染病暴发、流行时未依法组织救治、采取控制措施的，由上级人民政府责令改正，通报批评；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百零一条", "text": "违反本法规定，县级以上人民政府卫生健康主管部门、疾病预防控制部门有下列情形之一的，由本级人民政府或者上级人民政府卫生健康主管部门、疾病预防控制部门责令改正，通报批评；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分： （一）未依法履行传染病疫情通报、报告或者公布职责，隐瞒、谎报、缓报、漏报传染病疫情，或者干预传染病疫情报告； （二）发生或者可能发生传染病传播时未依法采取预防、控制措施； （三）未依法履行监督检查职责，或者发现违法行为不及时查处； （四）未及时调查、处理对下级人民政府卫生健康主管部门、疾病预防控制部门不履行传染病防治职责的举报； （五）违反本法规定的其他失职、渎职行为。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百零二条", "text": "违反本法规定，县级以上人民政府有关部门未依法履行传染病防治、疫情通报和保障职责的，由本级人民政府或者上级人民政府有关部门责令改正，通报批评；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百零三条", "text": "违反本法规定，疾病预防控制机构有下列情形之一的，由县级以上人民政府疾病预防控制部门责令改正，给予警告或者通报批评，对直接负责的主管人员和其他直接责任人员依法给予处分，并可以由原发证部门依法吊销有关责任人员的执业证书： （一）未依法履行传染病监测、疫情风险评估职责； （二）未依法履行传染病疫情报告职责，隐瞒、谎报、缓报、漏报传染病疫情，或者干预传染病疫情报告； （三）未主动收集传染病疫情信息，或者对传染病疫情信息和疫情报告未及时进行分析、调查、核实； （四）发现传染病疫情或者接到传染病疫情报告时，未依据职责及时采取本法规定的措施； （五）未遵守国家有关规定，导致因使用血液制品引起经血液传播疾病的发生。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百零四条", "text": "违反本法规定，医疗机构有下列情形之一的，由县级以上人民政府疾病预防控制部门责令改正，给予警告或者通报批评，可以并处十万元以下罚款；情节严重的，可以由原发证部门或者原备案部门依法吊销医疗机构执业许可证或者责令停止执业活动，对直接负责的主管人员和其他直接责任人员依法给予处分，并可以由原发证部门责令有关责任人员暂停六个月以上一年以下执业活动直至依法吊销执业证书： （一）未按照规定承担本机构的传染病预防、控制工作，医疗机构感染控制任务或者责任区域内的传染病预防工作； （二）未按照规定报告传染病疫情，隐瞒、谎报、缓报、漏报传染病疫情，或者干预传染病疫情报告； （三）未按照规定对本机构内被传染病病原体污染的场所、物品以及医疗废物、医疗污水实施消毒或者无害化处置。 违反本法规定，医疗机构有下列情形之一的，由县级以上人民政府卫生健康主管部门依照前款规定给予行政处罚，对直接负责的主管人员和其他直接责任人员依法给予处分： （一）发现传染病疫情时，未按照规定对传染病患者、疑似患者提供医疗救护、现场救援、接诊治疗、转诊，或者拒绝接受转诊； （二）未遵守国家有关规定，导致因输入血液、使用血液制品引起经血液传播疾病的发生。 医疗机构未按照规定对使用的医疗器械进行消毒或者灭菌，或者对按照规定一次性使用的医疗器械使用后未予以销毁、再次使用的，依照有关医疗器械管理的法律、行政法规规定追究法律责任。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百零五条", "text": "违反本法规定，采供血机构未按照规定报告传染病疫情，隐瞒、谎报、缓报、漏报传染病疫情，或者干预传染病疫情报告的，由县级以上人民政府疾病预防控制部门责令改正，给予警告或者通报批评，可以并处十万元以下罚款；情节严重的，可以由原发证部门依法吊销采供血机构的执业许可证，对直接负责的主管人员和其他直接责任人员依法给予处分，并可以由原发证部门责令有关责任人员暂停六个月以上一年以下执业活动直至依法吊销执业证书。 采供血机构未执行国家有关规定，导致因输入血液引起经血液传播疾病发生的，由县级以上人民政府卫生健康主管部门依照前款规定给予行政处罚，对直接负责的主管人员和其他直接责任人员依法给予处分。 非法采集血液或者组织他人出卖血液的，由县级以上人民政府卫生健康主管部门责令停止违法行为，没收违法所得，并处五万元以上五十万元以下罚款。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百零六条", "text": "违反本法规定，交通运输、邮政、快递经营单位未优先运送参与传染病疫情防控的人员以及传染病疫情防控所需的药品、医疗器械和其他应急物资的，由交通运输、铁路、民用航空、邮政管理部门依据职责责令改正，给予警告；造成严重后果的，并处一万元以上十万元以下罚款，对直接负责的主管人员和其他直接责任人员依法给予处分。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百零七条", "text": "违反本法规定，有下列情形之一的，由县级以上人民政府疾病预防控制部门责令改正，给予警告，没收违法所得，可以并处二十万元以下罚款；情节严重的，可以由原发证部门依法吊销相关许可证，对直接负责的主管人员和其他直接责任人员可以禁止其五年内从事相应生产经营活动： （一）饮用水供水单位未取得卫生许可擅自供水，或者供应的饮用水不符合国家卫生标准和卫生规范造成或者可能造成传染病传播、暴发、流行； （二）生产、销售未取得卫生许可的涉及饮用水卫生安全的产品，或者生产、销售的涉及饮用水卫生安全的产品不符合国家卫生标准和卫生规范； （三）未取得卫生许可生产用于传染病防治的消毒产品，或者生产、销售的用于传染病防治的消毒产品不符合国家卫生标准和卫生规范； （四）生产、销售未取得卫生许可的利用新材料、新工艺技术和新杀菌原理生产的消毒剂和消毒器械； （五）出售、运输本法"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第六十六条", "text": "规定的受影响的相关区域中被传染病病原体污染或者可能被传染病病原体污染的物品，未进行消毒处理。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百零八条", "text": "违反本法规定，有下列情形之一的，由县级以上人民政府卫生健康、疾病预防控制等部门依据职责责令改正，给予警告或者通报批评，没收违法所得，可以并处十万元以下罚款；情节严重的，可以由原发证部门依法吊销相关许可证，对直接负责的主管人员和其他直接责任人员依法给予处分，并可以由原发证部门责令有关责任人员暂停六个月以上一年以下执业活动直至依法吊销执业证书： （一）疾病预防控制机构、医疗机构的实验室和从事病原微生物实验的单位，不符合国家规定的条件和技术标准，对传染病病原体和样本未按照规定的措施实行严格管理； （二）违反国家有关规定，采集、保藏、提供、携带、运输、使用病原微生物菌（毒）种和传染病检测样本； （三）医疗机构、疾病预防控制机构、检验检测机构未按照传染病检验检测技术规范和标准开展检验检测活动，或者出具虚假检验检测报告； （四）生产、销售应当备案而未备案的消毒剂、消毒器械以及抗（抑）菌剂； （五）公共场所、学校、托育机构的卫生条件和传染病预防、控制措施不符合国家卫生标准和卫生规范。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百零九条", "text": "违反本法规定，在国家确认的自然疫源地兴建水利、交通、旅游、能源等大型建设项目，未经卫生调查进行施工，或者未按照疾病预防控制机构的意见采取必要的传染病预防、控制措施的，由县级以上人民政府疾病预防控制部门责令限期改正，给予警告，并处十万元以上五十万元以下罚款；逾期不改正的，处五十万元以上一百万元以下罚款，提请有关人民政府依据职责权限责令停建、拆除，对直接负责的主管人员和其他直接责任人员依法给予处分。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百一十条", "text": "违反本法规定，县级以上人民政府卫生健康主管部门、疾病预防控制部门或者其他有关部门未依法履行个人信息保护义务的，由本级人民政府或者上级人民政府有关部门责令改正，通报批评；情节严重的，对负有责任的领导人员和直接责任人员依法给予处分。 医疗机构、疾病预防控制机构泄露传染病患者、病原携带者、疑似患者或者上述人员的密切接触者的个人隐私或者个人信息的，由县级以上人民政府卫生健康主管部门、疾病预防控制部门依据职责责令改正，给予警告或者通报批评，可以并处五万元以下罚款，对直接负责的主管人员和其他直接责任人员依法给予处分，对有关责任人员依照有关医师、护士管理等法律、行政法规规定追究法律责任。 传染病防治中其他未依法履行个人信息保护义务的，依照有关个人信息保护的法律、行政法规规定追究法律责任。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百一十一条", "text": "违反本法规定，有下列情形之一的，由县级以上人民政府疾病预防控制部门责令改正，给予警告，对违法的单位可以并处二万元以下罚款，对违法的个人可以并处一千元以下罚款；情节严重的，由原发证部门依法吊销相关许可证或者营业执照： （一）拒不执行人民政府及其有关部门依法采取的传染病疫情防控措施； （二）拒不接受和配合疾病预防控制机构依法采取的传染病疫情防控措施； （三）拒不接受和配合疾病预防控制机构开展的流行病学调查，或者在流行病学调查中故意隐瞒传染病病情、传染病接触史或者传染病暴发、流行地区旅行史； （四）甲类传染病患者、病原携带者、疑似患者或者上述人员的密切接触者拒绝接受和配合依法采取的隔离治疗、医学观察措施，或者隔离治疗、医学观察的期限未满擅自脱离； （五）故意传播传染病； （六）故意编造、散布虚假传染病疫情信息； （七）其他妨害依法采取的传染病疫情防控措施的行为。 安排传染病患者、病原携带者、疑似患者从事法律、行政法规和国务院疾病预防控制部门规定禁止从事的易使该传染病扩散的工作的，由县级以上人民政府疾病预防控制部门责令改正，给予警告，可以并处二万元以下罚款；法律、行政法规另有规定的，依照其规定。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百一十二条", "text": "违反本法规定，造成人身、财产损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。 第九章 附 则"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百一十三条", "text": "本法中下列用语的含义： （一）重大传染病疫情，是指造成或者可能造成公众生命安全和身体健康严重损害的传染病疫情。 （二）传染病患者、疑似患者，是指根据国务院卫生健康主管部门、疾病预防控制部门发布的传染病诊断标准，符合传染病患者、疑似患者诊断标准的人。 （三）病原携带者，是指感染传染病病原体无临床症状但能排出病原体的人。 （四）流行病学调查，是指对人群中疾病或者健康状况的分布及其决定因素进行调查研究，提出疾病预防、控制措施及保健对策。 （五）人畜共患传染病，是指人与脊椎动物共同罹患的传染病，如鼠疫、狂犬病、血吸虫病、包虫病等。 （六）自然疫源地，是指某些可引起人类传染病的病原体在自然界的野生动物中长期存在和循环的地区。 （七）病媒生物，是指能够将传染病病原体从人或者其他动物传播给人的生物，如鼠、蚊、蝇、蚤类等。 （八）医疗机构感染，是指在医疗机构内获得的感染，包括在医疗机构内发生的感染和在医疗机构内获得、离开医疗机构后发生的感染，但不包括进入医疗机构前已开始或者已处于潜伏期的感染。医疗机构工作人员在医疗机构内获得的感染也属医疗机构感染。 （九）实验室感染，是指从事实验室工作时，因接触传染病病原体所致的感染。 （十）消毒，是指用化学、物理、生物的方法杀灭或者消除环境中的病原微生物。 （十一）疾病预防控制机构，是指从事疾病预防控制活动的疾病预防控制中心以及铁路疾病预防控制机构等与上述机构业务活动相同的单位。 （十二）医疗机构，是指依法取得医疗机构执业许可证或者进行备案，从事疾病诊断、治疗活动的机构。 （十三）暴发，是指在局部地区或者集体单位短时间内突然出现很多症状相同的患者。这些患者多有相同的传染源或者传播途径，大多数患者常同时出现在该病的最短和最长潜伏期之间。 （十四）流行，是指在某地区某病的发病率显著超过该病历年发病率水平。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百一十四条", "text": "传染病防治中有关突发公共卫生事件的应对，本法未作规定的，适用有关突发公共卫生事件应对的法律、行政法规规定。"}, {"law": "中华人民共和国传染病防治法_20250430.docx", "no": "第一百一十五条", "text": "本法自2025年9月1日起施行。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一条", "text": "为了惩罚犯罪，保护人民，根据宪法，结合我国同犯罪作斗争的具体经验及实际情况，制定本法。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二条", "text": "中华人民共和国刑法的任务，是用刑罚同一切犯罪行为作斗争，以保卫国家安全，保卫人民民主专政的政权和社会主义制度，保护国有财产和劳动群众集体所有的财产，保护公民私人所有的财产，保护公民的人身权利、民主权利和其他权利，维护社会秩序、经济秩序，保障社会主义建设事业的顺利进行。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三条", "text": "法律明文规定为犯罪行为的，依照法律定罪处刑；法律没有明文规定为犯罪行为的，不得定罪处刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四条", "text": "对任何人犯罪，在适用法律上一律平等。不允许任何人有超越法律的特权。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五条", "text": "刑罚的轻重，应当与犯罪分子所犯罪行和承担的刑事责任相适应。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六条", "text": "凡在中华人民共和国领域内犯罪的，除法律有特别规定的以外，都适用本法。 凡在中华人民共和国船舶或者航空器内犯罪的，也适用本法。 犯罪的行为或者结果有一项发生在中华人民共和国领域内的，就认为是在中华人民共和国领域内犯罪。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七条", "text": "中华人民共和国公民在中华人民共和国领域外犯本法规定之罪的，适用本法，但是按本法规定的最高刑为三年以下有期徒刑的，可以不予追究。 中华人民共和国国家工作人员和军人在中华人民共和国领域外犯本法规定之罪的，适用本法。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第八条", "text": "外国人在中华人民共和国领域外对中华人民共和国国家或者公民犯罪，而按本法规定的最低刑为三年以上有期徒刑的，可以适用本法，但是按照犯罪地的法律不受处罚的除外。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第九条", "text": "对于中华人民共和国缔结或者参加的国际条约所规定的罪行，中华人民共和国在所承担条约义务的范围内行使刑事管辖权的，适用本法。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第十条", "text": "凡在中华人民共和国领域外犯罪，依照本法应当负刑事责任的，虽然经过外国审判，仍然可以依照本法追究，但是在外国已经受过刑罚处罚的，可以免除或者减轻处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第十一条", "text": "享有外交特权和豁免权的外国人的刑事责任，通过外交途径解决。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第十二条", "text": "中华人民共和国成立以后本法施行以前的行为，如果当时的法律不认为是犯罪的，适用当时的法律；如果当时的法律认为是犯罪的，依照本法总则第四章第八节的规定应当追诉的，按照当时的法律追究刑事责任，但是如果本法不认为是犯罪或者处刑较轻的，适用本法。 本法施行以前，依照当时的法律已经作出的生效判决，继续有效。 第二章 犯 罪 第一节 犯罪和刑事责任"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第十三条", "text": "一切危害国家主权、领土完整和安全，分裂国家、颠覆人民民主专政的政权和推翻社会主义制度，破坏社会秩序和经济秩序，侵犯国有财产或者劳动群众集体所有的财产，侵犯公民私人所有的财产，侵犯公民的人身权利、民主权利和其他权利，以及其他危害社会的行为，依照法律应当受刑罚处罚的，都是犯罪，但是情节显著轻微危害不大的，不认为是犯罪。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第十四条", "text": "明知自己的行为会发生危害社会的结果，并且希望或者放任这种结果发生，因而构成犯罪的，是故意犯罪。 故意犯罪，应当负刑事责任。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第十五条", "text": "应当预见自己的行为可能发生危害社会的结果，因为疏忽大意而没有预见，或者已经预见而轻信能够避免，以致发生这种结果的，是过失犯罪。 过失犯罪，法律有规定的才负刑事责任。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第十六条", "text": "行为在客观上虽然造成了损害结果，但是不是出于故意或者过失，而是由于不能抗拒或者不能预见的原因所引起的，不是犯罪。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第十七条", "text": "已满十六周岁的人犯罪，应当负刑事责任。 已满十四周岁不满十六周岁的人，犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质罪的，应当负刑事责任。 已满十二周岁不满十四周岁的人，犯故意杀人、故意伤害罪，致人死亡或者以特别残忍手段致人重伤造成严重残疾，情节恶劣，经最高人民检察院核准追诉的，应当负刑事责任。 对依照前三款规定追究刑事责任的不满十八周岁的人，应当从轻或者减轻处罚。 因不满十六周岁不予刑事处罚的，责令其父母或者其他监护人加以管教；在必要的时候，依法进行专门矫治教育。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第十七条", "text": "之一 已满七十五周岁的人故意犯罪的，可以从轻或者减轻处罚；过失犯罪的，应当从轻或者减轻处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第十八条", "text": "精神病人在不能辨认或者不能控制自己行为的时候造成危害结果，经法定程序鉴定确认的，不负刑事责任，但是应当责令他的家属或者监护人严加看管和医疗；在必要的时候，由政府强制医疗。 间歇性的精神病人在精神正常的时候犯罪，应当负刑事责任。 尚未完全丧失辨认或者控制自己行为能力的精神病人犯罪的，应当负刑事责任，但是可以从轻或者减轻处罚。 醉酒的人犯罪，应当负刑事责任。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第十九条", "text": "又聋又哑的人或者盲人犯罪，可以从轻、减轻或者免除处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二十条", "text": "为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而采取的制止不法侵害的行为，对不法侵害人造成损害的，属于正当防卫，不负刑事责任。 正当防卫明显超过必要限度造成重大损害的，应当负刑事责任，但是应当减轻或者免除处罚。 对正在进行行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪，采取防卫行为，造成不法侵害人伤亡的，不属于防卫过当，不负刑事责任。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二十一条", "text": "为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在发生的危险，不得已采取的紧急避险行为，造成损害的，不负刑事责任。 紧急避险超过必要限度造成不应有的损害的，应当负刑事责任，但是应当减轻或者免除处罚。 第一款中关于避免本人危险的规定，不适用于职务上、业务上负有特定责任的人。 第二节 犯罪的预备、未遂和中止"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二十二条", "text": "为了犯罪，准备工具、制造条件的，是犯罪预备。 对于预备犯，可以比照既遂犯从轻、减轻处罚或者免除处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二十三条", "text": "已经着手实行犯罪，由于犯罪分子意志以外的原因而未得逞的，是犯罪未遂。 对于未遂犯，可以比照既遂犯从轻或者减轻处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二十四条", "text": "在犯罪过程中，自动放弃犯罪或者自动有效地防止犯罪结果发生的，是犯罪中止。 对于中止犯，没有造成损害的，应当免除处罚；造成损害的，应当减轻处罚。 第三节 共同犯罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二十五条", "text": "共同犯罪是指二人以上共同故意犯罪。 二人以上共同过失犯罪，不以共同犯罪论处；应当负刑事责任的，按照他们所犯的罪分别处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二十六条", "text": "组织、领导犯罪集团进行犯罪活动的或者在共同犯罪中起主要作用的，是主犯。 三人以上为共同实施犯罪而组成的较为固定的犯罪组织，是犯罪集团。 对组织、领导犯罪集团的首要分子，按照集团所犯的全部罪行处罚。 对于第三款规定以外的主犯，应当按照其所参与的或者组织、指挥的全部犯罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二十七条", "text": "在共同犯罪中起次要或者辅助作用的，是从犯。 对于从犯，应当从轻、减轻处罚或者免除处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二十八条", "text": "对于被胁迫参加犯罪的，应当按照他的犯罪情节减轻处罚或者免除处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二十九条", "text": "教唆他人犯罪的，应当按照他在共同犯罪中所起的作用处罚。教唆不满十八周岁的人犯罪的，应当从重处罚。 如果被教唆的人没有犯被教唆的罪，对于教唆犯，可以从轻或者减轻处罚。 第四节 单位犯罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三十条", "text": "公司、企业、事业单位、机关、团体实施的危害社会的行为，法律规定为单位犯罪的，应当负刑事责任。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三十一条", "text": "单位犯罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员判处刑罚。本法分则和其他法律另有规定的，依照规定。 第三章 刑 罚 第一节 刑罚的种类"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三十二条", "text": "刑罚分为主刑和附加刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三十三条", "text": "主刑的种类如下： （一）管制； （二）拘役； （三）有期徒刑； （四）无期徒刑； （五）死刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三十四条", "text": "附加刑的种类如下： （一）罚金； （二）剥夺政治权利； （三）没收财产。 附加刑也可以独立适用。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三十五条", "text": "对于犯罪的外国人，可以独立适用或者附加适用驱逐出境。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三十六条", "text": "由于犯罪行为而使被害人遭受经济损失的，对犯罪分子除依法给予刑事处罚外，并应根据情况判处赔偿经济损失。 承担民事赔偿责任的犯罪分子，同时被判处罚金，其财产不足以全部支付的，或者被判处没收财产的，应当先承担对被害人的民事赔偿责任。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三十七条", "text": "对于犯罪情节轻微不需要判处刑罚的，可以免予刑事处罚，但是可以根据案件的不同情况，予以训诫或者责令具结悔过、赔礼道歉、赔偿损失，或者由主管部门予以行政处罚或者行政处分。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三十七条", "text": "之一 因利用职业便利实施犯罪，或者实施违背职业要求的特定义务的犯罪被判处刑罚的，人民法院可以根据犯罪情况和预防再犯罪的需要，禁止其自刑罚执行完毕之日或者假释之日起从事相关职业，期限为三年至五年。 被禁止从事相关职业的人违反人民法院依照前款规定作出的决定的，由公安机关依法给予处罚；情节严重的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百一十三条", "text": "的规定定罪处罚。 其他法律、行政法规对其从事相关职业另有禁止或者限制性规定的，从其规定。 第二节 管 制"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三十八条", "text": "管制的期限，为三个月以上二年以下。 判处管制，可以根据犯罪情况，同时禁止犯罪分子在执行期间从事特定活动，进入特定区域、场所，接触特定的人。 对判处管制的犯罪分子，依法实行社区矫正。 违反第二款规定的禁止令的，由公安机关依照《中华人民共和国治安管理处罚法》的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三十九条", "text": "被判处管制的犯罪分子，在执行期间，应当遵守下列规定： （一）遵守法律、行政法规，服从监督； （二）未经执行机关批准，不得行使言论、出版、集会、结社、游行、示威自由的权利； （三）按照执行机关规定报告自己的活动情况； （四）遵守执行机关关于会客的规定； （五）离开所居住的市、县或者迁居，应当报经执行机关批准。 对于被判处管制的犯罪分子，在劳动中应当同工同酬。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四十条", "text": "被判处管制的犯罪分子，管制期满，执行机关应即向本人和其所在单位或者居住地的群众宣布解除管制。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四十一条", "text": "管制的刑期，从判决执行之日起计算；判决执行以前先行羁押的，羁押一日折抵刑期二日。 第三节 拘 役"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四十二条", "text": "拘役的期限，为一个月以上六个月以下。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四十三条", "text": "被判处拘役的犯罪分子，由公安机关就近执行。 在执行期间，被判处拘役的犯罪分子每月可以回家一天至两天；参加劳动的，可以酌量发给报酬。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四十四条", "text": "拘役的刑期，从判决执行之日起计算；判决执行以前先行羁押的，羁押一日折抵刑期一日。 第四节 有期徒刑、无期徒刑"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四十五条", "text": "有期徒刑的期限，除本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十九条", "text": "规定外，为六个月以上十五年以下。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四十六条", "text": "被判处有期徒刑、无期徒刑的犯罪分子，在监狱或者其他执行场所执行；凡有劳动能力的，都应当参加劳动，接受教育和改造。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四十七条", "text": "有期徒刑的刑期，从判决执行之日起计算；判决执行以前先行羁押的，羁押一日折抵刑期一日。 第五节 死 刑"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四十八条", "text": "死刑只适用于罪行极其严重的犯罪分子。对于应当判处死刑的犯罪分子，如果不是必须立即执行的，可以判处死刑同时宣告缓期二年执行。 死刑除依法由最高人民法院判决的以外，都应当报请最高人民法院核准。死刑缓期执行的，可以由高级人民法院判决或者核准。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四十九条", "text": "犯罪的时候不满十八周岁的人和审判的时候怀孕的妇女，不适用死刑。 审判的时候已满七十五周岁的人，不适用死刑，但以特别残忍手段致人死亡的除外。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十条", "text": "判处死刑缓期执行的，在死刑缓期执行期间，如果没有故意犯罪，二年期满以后，减为无期徒刑；如果确有重大立功表现，二年期满以后，减为二十五年有期徒刑；如果故意犯罪，情节恶劣的，报请最高人民法院核准后执行死刑；对于故意犯罪未执行死刑的，死刑缓期执行的期间重新计算，并报最高人民法院备案。 对被判处死刑缓期执行的累犯以及因故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪被判处死刑缓期执行的犯罪分子，人民法院根据犯罪情节等情况可以同时决定对其限制减刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十一条", "text": "死刑缓期执行的期间，从判决确定之日起计算。死刑缓期执行减为有期徒刑的刑期，从死刑缓期执行期满之日起计算。 第六节 罚 金"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十二条", "text": "判处罚金，应当根据犯罪情节决定罚金数额。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十三条", "text": "罚金在判决指定的期限内一次或者分期缴纳。期满不缴纳的，强制缴纳。对于不能全部缴纳罚金的，人民法院在任何时候发现被执行人有可以执行的财产，应当随时追缴。 由于遭遇不能抗拒的灾祸等原因缴纳确实有困难的，经人民法院裁定，可以延期缴纳、酌情减少或者免除。 第七节 剥夺政治权利"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十四条", "text": "剥夺政治权利是剥夺下列权利： （一）选举权和被选举权； （二）言论、出版、集会、结社、游行、示威自由的权利； （三）担任国家机关职务的权利； （四）担任国有公司、企业、事业单位和人民团体领导职务的权利。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十五条", "text": "剥夺政治权利的期限，除本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十七条", "text": "规定外，为一年以上五年以下。 判处管制附加剥夺政治权利的，剥夺政治权利的期限与管制的期限相等，同时执行。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十六条", "text": "对于危害国家安全的犯罪分子应当附加剥夺政治权利；对于故意杀人、强奸、放火、爆炸、投毒、抢劫等严重破坏社会秩序的犯罪分子，可以附加剥夺政治权利。 独立适用剥夺政治权利的，依照本法分则的规定。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十七条", "text": "对于被判处死刑、无期徒刑的犯罪分子，应当剥夺政治权利终身。 在死刑缓期执行减为有期徒刑或者无期徒刑减为有期徒刑的时候，应当把附加剥夺政治权利的期限改为三年以上十年以下。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十八条", "text": "附加剥夺政治权利的刑期，从徒刑、拘役执行完毕之日或者从假释之日起计算；剥夺政治权利的效力当然施用于主刑执行期间。 被剥夺政治权利的犯罪分子，在执行期间，应当遵守法律、行政法规和国务院公安部门有关监督管理的规定，服从监督；不得行使本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十四条", "text": "规定的各项权利。 第八节 没收财产"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十九条", "text": "没收财产是没收犯罪分子个人所有财产的一部或者全部。没收全部财产的，应当对犯罪分子个人及其扶养的家属保留必需的生活费用。 在判处没收财产的时候，不得没收属于犯罪分子家属所有或者应有的财产。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十条", "text": "没收财产以前犯罪分子所负的正当债务，需要以没收的财产偿还的，经债权人请求，应当偿还。 第四章 刑罚的具体运用 第一节 量 刑"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十一条", "text": "对于犯罪分子决定刑罚的时候，应当根据犯罪的事实、犯罪的性质、情节和对于社会的危害程度，依照本法的有关规定判处。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十二条", "text": "犯罪分子具有本法规定的从重处罚、从轻处罚情节的，应当在法定刑的限度以内判处刑罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十三条", "text": "犯罪分子具有本法规定的减轻处罚情节的，应当在法定刑以下判处刑罚；本法规定有数个量刑幅度的，应当在法定量刑幅度的下一个量刑幅度内判处刑罚。 犯罪分子虽然不具有本法规定的减轻处罚情节，但是根据案件的特殊情况，经最高人民法院核准，也可以在法定刑以下判处刑罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十四条", "text": "犯罪分子违法所得的一切财物，应当予以追缴或者责令退赔；对被害人的合法财产，应当及时返还；违禁品和供犯罪所用的本人财物，应当予以没收。没收的财物和罚金，一律上缴国库，不得挪用和自行处理。 第二节 累 犯"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十五条", "text": "被判处有期徒刑以上刑罚的犯罪分子，刑罚执行完毕或者赦免以后，在五年以内再犯应当判处有期徒刑以上刑罚之罪的，是累犯，应当从重处罚，但是过失犯罪和不满十八周岁的人犯罪的除外。 前款规定的期限，对于被假释的犯罪分子，从假释期满之日起计算。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十六条", "text": "危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪的犯罪分子，在刑罚执行完毕或者赦免以后，在任何时候再犯上述任一类罪的，都以累犯论处。 第三节 自首和立功"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十七条", "text": "犯罪以后自动投案，如实供述自己的罪行的，是自首。对于自首的犯罪分子，可以从轻或者减轻处罚。其中，犯罪较轻的，可以免除处罚。 被采取强制措施的犯罪嫌疑人、被告人和正在服刑的罪犯，如实供述司法机关还未掌握的本人其他罪行的，以自首论。 犯罪嫌疑人虽不具有前两款规定的自首情节，但是如实供述自己罪行的，可以从轻处罚；因其如实供述自己罪行，避免特别严重后果发生的，可以减轻处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十八条", "text": "犯罪分子有揭发他人犯罪行为，查证属实的，或者提供重要线索，从而得以侦破其他案件等立功表现的，可以从轻或者减轻处罚；有重大立功表现的，可以减轻或者免除处罚。 第四节 数罪并罚"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十九条", "text": "判决宣告以前一人犯数罪的，除判处死刑和无期徒刑的以外，应当在总和刑期以下、数刑中最高刑期以上，酌情决定执行的刑期，但是管制最高不能超过三年，拘役最高不能超过一年，有期徒刑总和刑期不满三十五年的，最高不能超过二十年，总和刑期在三十五年以上的，最高不能超过二十五年。 数罪中有判处有期徒刑和拘役的，执行有期徒刑。数罪中有判处有期徒刑和管制，或者拘役和管制的，有期徒刑、拘役执行完毕后，管制仍须执行。 数罪中有判处附加刑的，附加刑仍须执行，其中附加刑种类相同的，合并执行，种类不同的，分别执行。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十条", "text": "判决宣告以后，刑罚执行完毕以前，发现被判刑的犯罪分子在判决宣告以前还有其他罪没有判决的，应当对新发现的罪作出判决，把前后两个判决所判处的刑罚，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十九条", "text": "的规定，决定执行的刑罚。已经执行的刑期，应当计算在新判决决定的刑期以内。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十一条", "text": "判决宣告以后，刑罚执行完毕以前，被判刑的犯罪分子又犯罪的，应当对新犯的罪作出判决，把前罪没有执行的刑罚和后罪所判处的刑罚，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十九条", "text": "的规定，决定执行的刑罚。 第五节 缓 刑"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十二条", "text": "对于被判处拘役、三年以下有期徒刑的犯罪分子，同时符合下列条件的，可以宣告缓刑，对其中不满十八周岁的人、怀孕的妇女和已满七十五周岁的人，应当宣告缓刑： （一）犯罪情节较轻； （二）有悔罪表现； （三）没有再犯罪的危险； （四）宣告缓刑对所居住社区没有重大不良影响。 宣告缓刑，可以根据犯罪情况，同时禁止犯罪分子在缓刑考验期限内从事特定活动，进入特定区域、场所，接触特定的人。 被宣告缓刑的犯罪分子，如果被判处附加刑，附加刑仍须执行。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十三条", "text": "拘役的缓刑考验期限为原判刑期以上一年以下，但是不能少于二个月。 有期徒刑的缓刑考验期限为原判刑期以上五年以下，但是不能少于一年。 缓刑考验期限，从判决确定之日起计算。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十四条", "text": "对于累犯和犯罪集团的首要分子，不适用缓刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十五条", "text": "被宣告缓刑的犯罪分子，应当遵守下列规定： （一）遵守法律、行政法规，服从监督； （二）按照考察机关的规定报告自己的活动情况； （三）遵守考察机关关于会客的规定； （四）离开所居住的市、县或者迁居，应当报经考察机关批准。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十六条", "text": "对宣告缓刑的犯罪分子，在缓刑考验期限内，依法实行社区矫正，如果没有本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十七条", "text": "规定的情形，缓刑考验期满，原判的刑罚就不再执行，并公开予以宣告。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十七条", "text": "被宣告缓刑的犯罪分子，在缓刑考验期限内犯新罪或者发现判决宣告以前还有其他罪没有判决的，应当撤销缓刑，对新犯的罪或者新发现的罪作出判决，把前罪和后罪所判处的刑罚，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第六十九条", "text": "的规定，决定执行的刑罚。 被宣告缓刑的犯罪分子，在缓刑考验期限内，违反法律、行政法规或者国务院有关部门关于缓刑的监督管理规定，或者违反人民法院判决中的禁止令，情节严重的，应当撤销缓刑，执行原判刑罚。 第六节 减 刑"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十八条", "text": "被判处管制、拘役、有期徒刑、无期徒刑的犯罪分子，在执行期间，如果认真遵守监规，接受教育改造，确有悔改表现的，或者有立功表现的，可以减刑；有下列重大立功表现之一的，应当减刑： （一）阻止他人重大犯罪活动的； （二）检举监狱内外重大犯罪活动，经查证属实的； （三）有发明创造或者重大技术革新的； （四）在日常生产、生活中舍己救人的； （五）在抗御自然灾害或者排除重大事故中，有突出表现的； （六）对国家和社会有其他重大贡献的。 减刑以后实际执行的刑期不能少于下列期限： （一）判处管制、拘役、有期徒刑的，不能少于原判刑期的二分之一； （二）判处无期徒刑的，不能少于十三年； （三）人民法院依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第五十条", "text": "第二款规定限制减刑的死刑缓期执行的犯罪分子，缓期执行期满后依法减为无期徒刑的，不能少于二十五年，缓期执行期满后依法减为二十五年有期徒刑的，不能少于二十年。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十九条", "text": "对于犯罪分子的减刑，由执行机关向中级以上人民法院提出减刑建议书。人民法院应当组成合议庭进行审理，对确有悔改或者立功事实的，裁定予以减刑。非经法定程序不得减刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第八十条", "text": "无期徒刑减为有期徒刑的刑期，从裁定减刑之日起计算。 第七节 假 释"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第八十一条", "text": "被判处有期徒刑的犯罪分子，执行原判刑期二分之一以上，被判处无期徒刑的犯罪分子，实际执行十三年以上，如果认真遵守监规，接受教育改造，确有悔改表现，没有再犯罪的危险的，可以假释。如果有特殊情况，经最高人民法院核准，可以不受上述执行刑期的限制。 对累犯以及因故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪被判处十年以上有期徒刑、无期徒刑的犯罪分子，不得假释。 对犯罪分子决定假释时，应当考虑其假释后对所居住社区的影响。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第八十二条", "text": "对于犯罪分子的假释，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十九条", "text": "规定的程序进行。非经法定程序不得假释。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第八十三条", "text": "有期徒刑的假释考验期限，为没有执行完毕的刑期；无期徒刑的假释考验期限为十年。 假释考验期限，从假释之日起计算。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第八十四条", "text": "被宣告假释的犯罪分子，应当遵守下列规定： （一）遵守法律、行政法规，服从监督； （二）按照监督机关的规定报告自己的活动情况； （三）遵守监督机关关于会客的规定； （四）离开所居住的市、县或者迁居，应当报经监督机关批准。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第八十五条", "text": "对假释的犯罪分子，在假释考验期限内，依法实行社区矫正，如果没有本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第八十六条", "text": "规定的情形，假释考验期满，就认为原判刑罚已经执行完毕，并公开予以宣告。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第八十六条", "text": "被假释的犯罪分子，在假释考验期限内犯新罪，应当撤销假释，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十一条", "text": "的规定实行数罪并罚。 在假释考验期限内，发现被假释的犯罪分子在判决宣告以前还有其他罪没有判决的，应当撤销假释，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第七十条", "text": "的规定实行数罪并罚。 被假释的犯罪分子，在假释考验期限内，有违反法律、行政法规或者国务院有关部门关于假释的监督管理规定的行为，尚未构成新的犯罪的，应当依照法定程序撤销假释，收监执行未执行完毕的刑罚。 第八节 时 效"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第八十七条", "text": "犯罪经过下列期限不再追诉： （一）法定最高刑为不满五年有期徒刑的，经过五年； （二）法定最高刑为五年以上不满十年有期徒刑的，经过十年； （三）法定最高刑为十年以上有期徒刑的，经过十五年； （四）法定最高刑为无期徒刑、死刑的，经过二十年。如果二十年以后认为必须追诉的，须报请最高人民检察院核准。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第八十八条", "text": "在人民检察院、公安机关、国家安全机关立案侦查或者在人民法院受理案件以后，逃避侦查或者审判的，不受追诉期限的限制。 被害人在追诉期限内提出控告，人民法院、人民检察院、公安机关应当立案而不予立案的，不受追诉期限的限制。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第八十九条", "text": "追诉期限从犯罪之日起计算；犯罪行为有连续或者继续状态的，从犯罪行为终了之日起计算。 在追诉期限以内又犯罪的，前罪追诉的期限从犯后罪之日起计算。 第五章 其他规定"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第九十条", "text": "民族自治地方不能全部适用本法规定的，可以由自治区或者省的人民代表大会根据当地民族的政治、经济、文化的特点和本法规定的基本原则，制定变通或者补充的规定，报请全国人民代表大会常务委员会批准施行。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第九十一条", "text": "本法所称公共财产，是指下列财产： （一）国有财产； （二）劳动群众集体所有的财产； （三）用于扶贫和其他公益事业的社会捐助或者专项基金的财产。 在国家机关、国有公司、企业、集体企业和人民团体管理、使用或者运输中的私人财产，以公共财产论。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第九十二条", "text": "本法所称公民私人所有的财产，是指下列财产： （一）公民的合法收入、储蓄、房屋和其他生活资料； （二）依法归个人、家庭所有的生产资料； （三）个体户和私营企业的合法财产； （四）依法归个人所有的股份、股票、债券和其他财产。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第九十三条", "text": "本法所称国家工作人员，是指国家机关中从事公务的人员。 国有公司、企业、事业单位、人民团体中从事公务的人员和国家机关、国有公司、企业、事业单位委派到非国有公司、企业、事业单位、社会团体从事公务的人员，以及其他依照法律从事公务的人员，以国家工作人员论。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第九十四条", "text": "本法所称司法工作人员，是指有侦查、检察、审判、监管职责的工作人员。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第九十五条", "text": "本法所称重伤，是指有下列情形之一的伤害： （一）使人肢体残废或者毁人容貌的； （二）使人丧失听觉、视觉或者其他器官机能的； （三）其他对于人身健康有重大伤害的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第九十六条", "text": "本法所称违反国家规定，是指违反全国人民代表大会及其常务委员会制定的法律和决定，国务院制定的行政法规、规定的行政措施、发布的决定和命令。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第九十七条", "text": "本法所称首要分子，是指在犯罪集团或者聚众犯罪中起组织、策划、指挥作用的犯罪分子。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第九十八条", "text": "本法所称告诉才处理，是指被害人告诉才处理。如果被害人因受强制、威吓无法告诉的，人民检察院和被害人的近亲属也可以告诉。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第九十九条", "text": "本法所称以上、以下、以内，包括本数。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百条", "text": "依法受过刑事处罚的人，在入伍、就业的时候，应当如实向有关单位报告自己曾受过刑事处罚，不得隐瞒。 犯罪的时候不满十八周岁被判处五年有期徒刑以下刑罚的人，免除前款规定的报告义务。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百零一条", "text": "本法总则适用于其他有刑罚规定的法律，但是其他法律有特别规定的除外。 第二编 分 则 第一章 危害国家安全罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百零二条", "text": "勾结外国，危害中华人民共和国的主权、领土完整和安全的，处无期徒刑或者十年以上有期徒刑。 与境外机构、组织、个人相勾结，犯前款罪的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百零三条", "text": "组织、策划、实施分裂国家、破坏国家统一的，对首要分子或者罪行重大的，处无期徒刑或者十年以上有期徒刑；对积极参加的，处三年以上十年以下有期徒刑；对其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。 煽动分裂国家、破坏国家统一的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利；首要分子或者罪行重大的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百零四条", "text": "组织、策划、实施武装叛乱或者武装暴乱的，对首要分子或者罪行重大的，处无期徒刑或者十年以上有期徒刑；对积极参加的，处三年以上十年以下有期徒刑；对其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。 策动、胁迫、勾引、收买国家机关工作人员、武装部队人员、人民警察、民兵进行武装叛乱或者武装暴乱的，依照前款的规定从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百零五条", "text": "组织、策划、实施颠覆国家政权、推翻社会主义制度的，对首要分子或者罪行重大的，处无期徒刑或者十年以上有期徒刑；对积极参加的，处三年以上十年以下有期徒刑；对其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。 以造谣、诽谤或者其他方式煽动颠覆国家政权、推翻社会主义制度的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利；首要分子或者罪行重大的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百零六条", "text": "与境外机构、组织、个人相勾结，实施本章"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百零五条", "text": "规定之罪的，依照各该条的规定从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百零七条", "text": "境内外机构、组织或者个人资助实施本章"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百零五条", "text": "规定之罪的，对直接责任人员，处五年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百零八条", "text": "投敌叛变的，处三年以上十年以下有期徒刑；情节严重或者带领武装部队人员、人民警察、民兵投敌叛变的，处十年以上有期徒刑或者无期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百零九条", "text": "国家机关工作人员在履行公务期间，擅离岗位，叛逃境外或者在境外叛逃的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处五年以上十年以下有期徒刑。 掌握国家秘密的国家工作人员叛逃境外或者在境外叛逃的，依照前款的规定从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百一十条", "text": "有下列间谍行为之一，危害国家安全的，处十年以上有期徒刑或者无期徒刑；情节较轻的，处三年以上十年以下有期徒刑： （一）参加间谍组织或者接受间谍组织及其代理人的任务的； （二）为敌人指示轰击目标的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百一十一条", "text": "为境外的机构、组织、人员窃取、刺探、收买、非法提供国家秘密或者情报的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑；情节较轻的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百一十二条", "text": "战时供给敌人武器装备、军用物资资敌的，处十年以上有期徒刑或者无期徒刑；情节较轻的，处三年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百一十三条", "text": "本章上述危害国家安全罪行中，除"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百零九条", "text": "外，对国家和人民危害特别严重、情节特别恶劣的，可以判处死刑。 犯本章之罪的，可以并处没收财产。 第二章 危害公共安全罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百一十四条", "text": "放火、决水、爆炸以及投放毒害性、放射性、传染病病原体等物质或者以其他危险方法危害公共安全，尚未造成严重后果的，处三年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百一十五条", "text": "放火、决水、爆炸以及投放毒害性、放射性、传染病病原体等物质或者以其他危险方法致人重伤、死亡或者使公私财产遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。 过失犯前款罪的，处三年以上七年以下有期徒刑；情节较轻的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百一十六条", "text": "破坏火车、汽车、电车、船只、航空器，足以使火车、汽车、电车、船只、航空器发生倾覆、毁坏危险，尚未造成严重后果的，处三年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百一十七条", "text": "破坏轨道、桥梁、隧道、公路、机场、航道、灯塔、标志或者进行其他破坏活动，足以使火车、汽车、电车、船只、航空器发生倾覆、毁坏危险，尚未造成严重后果的，处三年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百一十八条", "text": "破坏电力、燃气或者其他易燃易爆设备，危害公共安全，尚未造成严重后果的，处三年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百一十九条", "text": "破坏交通工具、交通设施、电力设备、燃气设备、易燃易爆设备，造成严重后果的，处十年以上有期徒刑、无期徒刑或者死刑。 过失犯前款罪的，处三年以上七年以下有期徒刑；情节较轻的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十条", "text": "组织、领导恐怖活动组织的，处十年以上有期徒刑或者无期徒刑，并处没收财产；积极参加的，处三年以上十年以下有期徒刑，并处罚金；其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，可以并处罚金。 犯前款罪并实施杀人、爆炸、绑架等犯罪的，依照数罪并罚的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十条", "text": "之一 资助恐怖活动组织、实施恐怖活动的个人的，或者资助恐怖活动培训的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产。 为恐怖活动组织、实施恐怖活动或者恐怖活动培训招募、运送人员的，依照前款的规定处罚。 单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十条", "text": "之二 有下列情形之一的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产： （一）为实施恐怖活动准备凶器、危险物品或者其他工具的； （二）组织恐怖活动培训或者积极参加恐怖活动培训的； （三）为实施恐怖活动与境外恐怖活动组织或者人员联络的； （四）为实施恐怖活动进行策划或者其他准备的。 有前款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十条", "text": "之三 以制作、散发宣扬恐怖主义、极端主义的图书、音频视频资料或者其他物品，或者通过讲授、发布信息等方式宣扬恐怖主义、极端主义的，或者煽动实施恐怖活动的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十条", "text": "之四 利用极端主义煽动、胁迫群众破坏国家法律确立的婚姻、司法、教育、社会管理等制度实施的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金；情节特别严重的，处七年以上有期徒刑，并处罚金或者没收财产。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十条", "text": "之五 以暴力、胁迫等方式强制他人在公共场所穿着、佩戴宣扬恐怖主义、极端主义服饰、标志的，处三年以下有期徒刑、拘役或者管制，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十条", "text": "之六 明知是宣扬恐怖主义、极端主义的图书、音频视频资料或者其他物品而非法持有，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十一条", "text": "以暴力、胁迫或者其他方法劫持航空器的，处十年以上有期徒刑或者无期徒刑；致人重伤、死亡或者使航空器遭受严重破坏的，处死刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十二条", "text": "以暴力、胁迫或者其他方法劫持船只、汽车的，处五年以上十年以下有期徒刑；造成严重后果的，处十年以上有期徒刑或者无期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十三条", "text": "对飞行中的航空器上的人员使用暴力，危及飞行安全，尚未造成严重后果的，处五年以下有期徒刑或者拘役；造成严重后果的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十四条", "text": "破坏广播电视设施、公用电信设施，危害公共安全的，处三年以上七年以下有期徒刑；造成严重后果的，处七年以上有期徒刑。 过失犯前款罪的，处三年以上七年以下有期徒刑；情节较轻的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十五条", "text": "非法制造、买卖、运输、邮寄、储存枪支、弹药、爆炸物的，处三年以上十年以下有期徒刑；情节严重的，处十年以上有期徒刑、无期徒刑或者死刑。 非法制造、买卖、运输、储存毒害性、放射性、传染病病原体等物质，危害公共安全的，依照前款的规定处罚。 单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十六条", "text": "依法被指定、确定的枪支制造企业、销售企业，违反枪支管理规定，有下列行为之一的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑： （一）以非法销售为目的，超过限额或者不按照规定的品种制造、配售枪支的； （二）以非法销售为目的，制造无号、重号、假号的枪支的； （三）非法销售枪支或者在境内销售为出口制造的枪支的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十七条", "text": "盗窃、抢夺枪支、弹药、爆炸物的，或者盗窃、抢夺毒害性、放射性、传染病病原体等物质，危害公共安全的，处三年以上十年以下有期徒刑；情节严重的，处十年以上有期徒刑、无期徒刑或者死刑。 抢劫枪支、弹药、爆炸物的，或者抢劫毒害性、放射性、传染病病原体等物质，危害公共安全的，或者盗窃、抢夺国家机关、军警人员、民兵的枪支、弹药、爆炸物的，处十年以上有期徒刑、无期徒刑或者死刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十八条", "text": "违反枪支管理规定，非法持有、私藏枪支、弹药的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上七年以下有期徒刑。 依法配备公务用枪的人员，非法出租、出借枪支的，依照前款的规定处罚。 依法配置枪支的人员，非法出租、出借枪支，造成严重后果的，依照第一款的规定处罚。 单位犯第二款、第三款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百二十九条", "text": "依法配备公务用枪的人员，丢失枪支不及时报告，造成严重后果的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十条", "text": "非法携带枪支、弹药、管制刀具或者爆炸性、易燃性、放射性、毒害性、腐蚀性物品，进入公共场所或者公共交通工具，危及公共安全，情节严重的，处三年以下有期徒刑、拘役或者管制。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十一条", "text": "航空人员违反规章制度，致使发生重大飞行事故，造成严重后果的，处三年以下有期徒刑或者拘役；造成飞机坠毁或者人员死亡的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十二条", "text": "铁路职工违反规章制度，致使发生铁路运营安全事故，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十三条", "text": "违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；因逃逸致人死亡的，处七年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十三条", "text": "之一 在道路上驾驶机动车，有下列情形之一的，处拘役，并处罚金： （一）追逐竞驶，情节恶劣的； （二）醉酒驾驶机动车的； （三）从事校车业务或者旅客运输，严重超过额定乘员载客，或者严重超过规定时速行驶的； （四）违反危险化学品安全管理规定运输危险化学品，危及公共安全的。 机动车所有人、管理人对前款第三项、第四项行为负有直接责任的，依照前款的规定处罚。 有前两款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十三条", "text": "之二 对行驶中的公共交通工具的驾驶人员使用暴力或者抢控驾驶操纵装置，干扰公共交通工具正常行驶，危及公共安全的，处一年以下有期徒刑、拘役或者管制，并处或者单处罚金。 前款规定的驾驶人员在行驶的公共交通工具上擅离职守，与他人互殴或者殴打他人，危及公共安全的，依照前款的规定处罚。 有前两款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十四条", "text": "在生产、作业中违反有关安全管理的规定，因而发生重大伤亡事故或者造成其他严重后果的，处三年以下有期徒刑或者拘役；情节特别恶劣的，处三年以上七年以下有期徒刑。 强令他人违章冒险作业，或者明知存在重大事故隐患而不排除，仍冒险组织作业，因而发生重大伤亡事故或者造成其他严重后果的，处五年以下有期徒刑或者拘役；情节特别恶劣的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十四条", "text": "之一 在生产、作业中违反有关安全管理的规定，有下列情形之一，具有发生重大伤亡事故或者其他严重后果的现实危险的，处一年以下有期徒刑、拘役或者管制： （一）关闭、破坏直接关系生产安全的监控、报警、防护、救生设备、设施，或者篡改、隐瞒、销毁其相关数据、信息的； （二）因存在重大事故隐患被依法责令停产停业、停止施工、停止使用有关设备、设施、场所或者立即采取排除危险的整改措施，而拒不执行的； （三）涉及安全生产的事项未经依法批准或者许可，擅自从事矿山开采、金属冶炼、建筑施工，以及危险物品生产、经营、储存等高度危险的生产作业活动的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十五条", "text": "安全生产设施或者安全生产条件不符合国家规定，因而发生重大伤亡事故或者造成其他严重后果的，对直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役；情节特别恶劣的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十五条", "text": "之一 举办大型群众性活动违反安全管理规定，因而发生重大伤亡事故或者造成其他严重后果的，对直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役；情节特别恶劣的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十六条", "text": "违反爆炸性、易燃性、放射性、毒害性、腐蚀性物品的管理规定，在生产、储存、运输、使用中发生重大事故，造成严重后果的，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十七条", "text": "建设单位、设计单位、施工单位、工程监理单位违反国家规定，降低工程质量标准，造成重大安全事故的，对直接责任人员，处五年以下有期徒刑或者拘役，并处罚金；后果特别严重的，处五年以上十年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十八条", "text": "明知校舍或者教育教学设施有危险，而不采取措施或者不及时报告，致使发生重大伤亡事故的，对直接责任人员，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十九条", "text": "违反消防管理法规，经消防监督机构通知采取改正措施而拒绝执行，造成严重后果的，对直接责任人员，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百三十九条", "text": "之一 在安全事故发生后，负有报告职责的人员不报或者谎报事故情况，贻误事故抢救，情节严重的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。 第三章 破坏社会主义市场经济秩序罪 第一节 生产、销售伪劣商品罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十条", "text": "生产者、销售者在产品中掺杂、掺假，以假充真，以次充好或者以不合格产品冒充合格产品，销售金额五万元以上不满二十万元的，处二年以下有期徒刑或者拘役，并处或者单处销售金额百分之五十以上二倍以下罚金；销售金额二十万元以上不满五十万元的，处二年以上七年以下有期徒刑，并处销售金额百分之五十以上二倍以下罚金；销售金额五十万元以上不满二百万元的，处七年以上有期徒刑，并处销售金额百分之五十以上二倍以下罚金；销售金额二百万元以上的，处十五年有期徒刑或者无期徒刑，并处销售金额百分之五十以上二倍以下罚金或者没收财产。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十一条", "text": "生产、销售假药的，处三年以下有期徒刑或者拘役，并处罚金；对人体健康造成严重危害或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；致人死亡或者有其他特别严重情节的，处十年以上有期徒刑、无期徒刑或者死刑，并处罚金或者没收财产。 药品使用单位的人员明知是假药而提供给他人使用的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十二条", "text": "生产、销售劣药，对人体健康造成严重危害的，处三年以上十年以下有期徒刑，并处罚金；后果特别严重的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。 药品使用单位的人员明知是劣药而提供给他人使用的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十二条", "text": "之一 违反药品管理法规，有下列情形之一，足以严重危害人体健康的，处三年以下有期徒刑或者拘役，并处或者单处罚金；对人体健康造成严重危害或者有其他严重情节的，处三年以上七年以下有期徒刑，并处罚金： （一）生产、销售国务院药品监督管理部门禁止使用的药品的； （二）未取得药品相关批准证明文件生产、进口药品或者明知是上述药品而销售的； （三）药品申请注册中提供虚假的证明、数据、资料、样品或者采取其他欺骗手段的； （四）编造生产、检验记录的。 有前款行为，同时又构成本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十二条", "text": "规定之罪或者其他犯罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十三条", "text": "生产、销售不符合食品安全标准的食品，足以造成严重食物中毒事故或者其他严重食源性疾病的，处三年以下有期徒刑或者拘役，并处罚金；对人体健康造成严重危害或者有其他严重情节的，处三年以上七年以下有期徒刑，并处罚金；后果特别严重的，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十四条", "text": "在生产、销售的食品中掺入有毒、有害的非食品原料的，或者销售明知掺有有毒、有害的非食品原料的食品的，处五年以下有期徒刑，并处罚金；对人体健康造成严重危害或者有其他严重情节的，处五年以上十年以下有期徒刑，并处罚金；致人死亡或者有其他特别严重情节的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十五条", "text": "生产不符合保障人体健康的国家标准、行业标准的医疗器械、医用卫生材料，或者销售明知是不符合保障人体健康的国家标准、行业标准的医疗器械、医用卫生材料，足以严重危害人体健康的，处三年以下有期徒刑或者拘役，并处销售金额百分之五十以上二倍以下罚金；对人体健康造成严重危害的，处三年以上十年以下有期徒刑，并处销售金额百分之五十以上二倍以下罚金；后果特别严重的，处十年以上有期徒刑或者无期徒刑，并处销售金额百分之五十以上二倍以下罚金或者没收财产。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十六条", "text": "生产不符合保障人身、财产安全的国家标准、行业标准的电器、压力容器、易燃易爆产品或者其他不符合保障人身、财产安全的国家标准、行业标准的产品，或者销售明知是以上不符合保障人身、财产安全的国家标准、行业标准的产品，造成严重后果的，处五年以下有期徒刑，并处销售金额百分之五十以上二倍以下罚金；后果特别严重的，处五年以上有期徒刑，并处销售金额百分之五十以上二倍以下罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十七条", "text": "生产假农药、假兽药、假化肥，销售明知是假的或者失去使用效能的农药、兽药、化肥、种子，或者生产者、销售者以不合格的农药、兽药、化肥、种子冒充合格的农药、兽药、化肥、种子，使生产遭受较大损失的，处三年以下有期徒刑或者拘役，并处或者单处销售金额百分之五十以上二倍以下罚金；使生产遭受重大损失的，处三年以上七年以下有期徒刑，并处销售金额百分之五十以上二倍以下罚金；使生产遭受特别重大损失的，处七年以上有期徒刑或者无期徒刑，并处销售金额百分之五十以上二倍以下罚金或者没收财产。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十八条", "text": "生产不符合卫生标准的化妆品，或者销售明知是不符合卫生标准的化妆品，造成严重后果的，处三年以下有期徒刑或者拘役，并处或者单处销售金额百分之五十以上二倍以下罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十八条", "text": "所列产品，不构成各该条规定的犯罪，但是销售金额在五万元以上的，依照本节"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十条", "text": "的规定定罪处罚。 生产、销售本节"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十八条", "text": "所列产品，构成各该条规定的犯罪，同时又构成本节"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十条", "text": "规定之罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百四十八条", "text": "规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该条的规定处罚。 第二节 走私罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百五十一条", "text": "走私武器、弹药、核材料或者伪造的货币的，处七年以上有期徒刑，并处罚金或者没收财产；情节特别严重的，处无期徒刑，并处没收财产；情节较轻的，处三年以上七年以下有期徒刑，并处罚金。 走私国家禁止出口的文物、黄金、白银和其他贵重金属或者国家禁止进出口的珍贵动物及其制品的，处五年以上十年以下有期徒刑，并处罚金；情节特别严重的，处十年以上有期徒刑或者无期徒刑，并处没收财产；情节较轻的，处五年以下有期徒刑，并处罚金。 走私珍稀植物及其制品等国家禁止进出口的其他货物、物品的，处五年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处五年以上有期徒刑，并处罚金。 单位犯本条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本条各款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百五十二条", "text": "以牟利或者传播为目的，走私淫秽的影片、录像带、录音带、图片、书刊或者其他淫秽物品的，处三年以上十年以下有期徒刑，并处罚金；情节严重的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；情节较轻的，处三年以下有期徒刑、拘役或者管制，并处罚金。 逃避海关监管将境外固体废物、液态废物和气态废物运输进境，情节严重的，处五年以下有期徒刑，并处或者单处罚金；情节特别严重的，处五年以上有期徒刑，并处罚金。 单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前两款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十七条", "text": "规定以外的货物、物品的，根据情节轻重，分别依照下列规定处罚： （一）走私货物、物品偷逃应缴税额较大或者一年内曾因走私被给予二次行政处罚后又走私的，处三年以下有期徒刑或者拘役，并处偷逃应缴税额一倍以上五倍以下罚金。 （二）走私货物、物品偷逃应缴税额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处偷逃应缴税额一倍以上五倍以下罚金。 （三）走私货物、物品偷逃应缴税额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处偷逃应缴税额一倍以上五倍以下罚金或者没收财产。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役；情节严重的，处三年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑。 对多次走私未经处理的，按照累计走私货物、物品的偷逃应缴税额处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百五十四条", "text": "下列走私行为，根据本节规定构成犯罪的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百五十三条", "text": "的规定定罪处罚： （一）未经海关许可并且未补缴应缴税额，擅自将批准进口的来料加工、来件装配、补偿贸易的原材料、零件、制成品、设备等保税货物，在境内销售牟利的； （二）未经海关许可并且未补缴应缴税额，擅自将特定减税、免税进口的货物、物品，在境内销售牟利的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百五十五条", "text": "下列行为，以走私罪论处，依照本节的有关规定处罚： （一）直接向走私人非法收购国家禁止进口物品的，或者直接向走私人非法收购走私进口的其他货物、物品，数额较大的； （二）在内海、领海、界河、界湖运输、收购、贩卖国家禁止进出口物品的，或者运输、收购、贩卖国家限制进出口货物、物品，数额较大，没有合法证明的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百五十六条", "text": "与走私罪犯通谋，为其提供贷款、资金、帐号、发票、证明，或者为其提供运输、保管、邮寄或者其他方便的，以走私罪的共犯论处。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百五十七条", "text": "武装掩护走私的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百五十一条", "text": "第一款的规定从重处罚。 以暴力、威胁方法抗拒缉私的，以走私罪和本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十七条", "text": "规定的阻碍国家机关工作人员依法执行职务罪，依照数罪并罚的规定处罚。 第三节 妨害对公司、企业的管理秩序罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百五十八条", "text": "申请公司登记使用虚假证明文件或者采取其他欺诈手段虚报注册资本，欺骗公司登记主管部门，取得公司登记，虚报注册资本数额巨大、后果严重或者有其他严重情节的，处三年以下有期徒刑或者拘役，并处或者单处虚报注册资本金额百分之一以上百分之五以下罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百五十九条", "text": "公司发起人、股东违反公司法的规定未交付货币、实物或者未转移财产权，虚假出资，或者在公司成立后又抽逃其出资，数额巨大、后果严重或者有其他严重情节的，处五年以下有期徒刑或者拘役，并处或者单处虚假出资金额或者抽逃出资金额百分之二以上百分之十以下罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十条", "text": "在招股说明书、认股书、公司、企业债券募集办法等发行文件中隐瞒重要事实或者编造重大虚假内容，发行股票或者公司、企业债券、存托凭证或者国务院依法认定的其他证券，数额巨大、后果严重或者有其他严重情节的，处五年以下有期徒刑或者拘役，并处或者单处罚金；数额特别巨大、后果特别严重或者有其他特别严重情节的，处五年以上有期徒刑，并处罚金。 控股股东、实际控制人组织、指使实施前款行为的，处五年以下有期徒刑或者拘役，并处或者单处非法募集资金金额百分之二十以上一倍以下罚金；数额特别巨大、后果特别严重或者有其他特别严重情节的，处五年以上有期徒刑，并处非法募集资金金额百分之二十以上一倍以下罚金。 单位犯前两款罪的，对单位判处非法募集资金金额百分之二十以上一倍以下罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十一条", "text": "依法负有信息披露义务的公司、企业向股东和社会公众提供虚假的或者隐瞒重要事实的财务会计报告，或者对依法应当披露的其他重要信息不按照规定披露，严重损害股东或者其他人利益，或者有其他严重情节的，对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处五年以上十年以下有期徒刑，并处罚金。 前款规定的公司、企业的控股股东、实际控制人实施或者组织、指使实施前款行为的，或者隐瞒相关事项导致前款规定的情形发生的，依照前款的规定处罚。 犯前款罪的控股股东、实际控制人是单位的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十二条", "text": "公司、企业进行清算时，隐匿财产，对资产负债表或者财产清单作虚伪记载或者在未清偿债务前分配公司、企业财产，严重损害债权人或者其他人利益的，对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十二条", "text": "之一 隐匿或者故意销毁依法应当保存的会计凭证、会计帐簿、财务会计报告，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十二条", "text": "之二 公司、企业通过隐匿财产、承担虚构的债务或者以其他方法转移、处分财产，实施虚假破产，严重损害债权人或者其他人利益的，对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十三条", "text": "公司、企业或者其他单位的工作人员，利用职务上的便利，索取他人财物或者非法收受他人财物，为他人谋取利益，数额较大的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金。 公司、企业或者其他单位的工作人员在经济往来中，利用职务上的便利，违反国家规定，收受各种名义的回扣、手续费，归个人所有的，依照前款的规定处罚。 国有公司、企业或者其他国有单位中从事公务的人员和国有公司、企业或者其他国有单位委派到非国有公司、企业以及其他单位从事公务的人员有前两款行为的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十六条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十四条", "text": "为谋取不正当利益，给予公司、企业或者其他单位的工作人员以财物，数额较大的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大的，处三年以上十年以下有期徒刑，并处罚金。 为谋取不正当商业利益，给予外国公职人员或者国际公共组织官员以财物的，依照前款的规定处罚。 单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。 行贿人在被追诉前主动交待行贿行为的，可以减轻处罚或者免除处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十五条", "text": "国有公司、企业的董事、经理利用职务便利，自己经营或者为他人经营与其所任职公司、企业同类的营业，获取非法利益，数额巨大的，处三年以下有期徒刑或者拘役，并处或者单处罚金；数额特别巨大的，处三年以上七年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十六条", "text": "国有公司、企业、事业单位的工作人员，利用职务便利，有下列情形之一，使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役，并处或者单处罚金；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑，并处罚金： （一）将本单位的盈利业务交由自己的亲友进行经营的； （二）以明显高于市场的价格向自己的亲友经营管理的单位采购商品或者以明显低于市场的价格向自己的亲友经营管理的单位销售商品的； （三）向自己的亲友经营管理的单位采购不合格商品的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十七条", "text": "国有公司、企业、事业单位直接负责的主管人员，在签订、履行合同过程中，因严重不负责任被诈骗，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十八条", "text": "国有公司、企业的工作人员，由于严重不负责任或者滥用职权，造成国有公司、企业破产或者严重损失，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑。 国有事业单位的工作人员有前款行为，致使国家利益遭受重大损失的，依照前款的规定处罚。 国有公司、企业、事业单位的工作人员，徇私舞弊，犯前两款罪的，依照第一款的规定从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十九条", "text": "国有公司、企业或者其上级主管部门直接负责的主管人员，徇私舞弊，将国有资产低价折股或者低价出售，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十九条", "text": "之一 上市公司的董事、监事、高级管理人员违背对公司的忠实义务，利用职务便利，操纵上市公司从事下列行为之一，致使上市公司利益遭受重大损失的，处三年以下有期徒刑或者拘役，并处或者单处罚金；致使上市公司利益遭受特别重大损失的，处三年以上七年以下有期徒刑，并处罚金： （一）无偿向其他单位或者个人提供资金、商品、服务或者其他资产的； （二）以明显不公平的条件，提供或者接受资金、商品、服务或者其他资产的； （三）向明显不具有清偿能力的单位或者个人提供资金、商品、服务或者其他资产的； （四）为明显不具有清偿能力的单位或者个人提供担保，或者无正当理由为其他单位或者个人提供担保的； （五）无正当理由放弃债权、承担债务的； （六）采用其他方式损害上市公司利益的。 上市公司的控股股东或者实际控制人，指使上市公司董事、监事、高级管理人员实施前款行为的，依照前款的规定处罚。 犯前款罪的上市公司的控股股东或者实际控制人是单位的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。 第四节 破坏金融管理秩序罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十条", "text": "伪造货币的，处三年以上十年以下有期徒刑，并处罚金；有下列情形之一的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产： （一）伪造货币集团的首要分子； （二）伪造货币数额特别巨大的； （三）有其他特别严重情节的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十一条", "text": "出售、购买伪造的货币或者明知是伪造的货币而运输，数额较大的，处三年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。 银行或者其他金融机构的工作人员购买伪造的货币或者利用职务上的便利，以伪造的货币换取货币的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处十年以上有期徒刑或者无期徒刑，并处二万元以上二十万元以下罚金或者没收财产；情节较轻的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金。 伪造货币并出售或者运输伪造的货币的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十条", "text": "的规定定罪从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十二条", "text": "明知是伪造的货币而持有、使用，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金；数额特别巨大的，处十年以上有期徒刑，并处五万元以上五十万元以下罚金或者没收财产。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十三条", "text": "变造货币，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十四条", "text": "未经国家有关主管部门批准，擅自设立商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构的，处三年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金；情节严重的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金。 伪造、变造、转让商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构的经营许可证或者批准文件的，依照前款的规定处罚。 单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十五条", "text": "以转贷牟利为目的，套取金融机构信贷资金高利转贷他人，违法所得数额较大的，处三年以下有期徒刑或者拘役，并处违法所得一倍以上五倍以下罚金；数额巨大的，处三年以上七年以下有期徒刑，并处违法所得一倍以上五倍以下罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十五条", "text": "之一 以欺骗手段取得银行或者其他金融机构贷款、票据承兑、信用证、保函等，给银行或者其他金融机构造成重大损失的，处三年以下有期徒刑或者拘役，并处或者单处罚金；给银行或者其他金融机构造成特别重大损失或者有其他特别严重情节的，处三年以上七年以下有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十六条", "text": "非法吸收公众存款或者变相吸收公众存款，扰乱金融秩序的，处三年以下有期徒刑或者拘役，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。 有前两款行为，在提起公诉前积极退赃退赔，减少损害结果发生的，可以从轻或者减轻处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十七条", "text": "有下列情形之一，伪造、变造金融票证的，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金；情节严重的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；情节特别严重的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产： （一）伪造、变造汇票、本票、支票的； （二）伪造、变造委托收款凭证、汇款凭证、银行存单等其他银行结算凭证的； （三）伪造、变造信用证或者附随的单据、文件的； （四）伪造信用卡的。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十七条", "text": "之一 有下列情形之一，妨害信用卡管理的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；数量巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金： （一）明知是伪造的信用卡而持有、运输的，或者明知是伪造的空白信用卡而持有、运输，数量较大的； （二）非法持有他人信用卡，数量较大的； （三）使用虚假的身份证明骗领信用卡的； （四）出售、购买、为他人提供伪造的信用卡或者以虚假的身份证明骗领的信用卡的。 窃取、收买或者非法提供他人信用卡信息资料的，依照前款规定处罚。 银行或者其他金融机构的工作人员利用职务上的便利，犯第二款罪的，从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十八条", "text": "伪造、变造国库券或者国家发行的其他有价证券，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。 伪造、变造股票或者公司、企业债券，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金。 单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前两款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百七十九条", "text": "未经国家有关主管部门批准，擅自发行股票或者公司、企业债券，数额巨大、后果严重或者有其他严重情节的，处五年以下有期徒刑或者拘役，并处或者单处非法募集资金金额百分之一以上百分之五以下罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百八十条", "text": "证券、期货交易内幕信息的知情人员或者非法获取证券、期货交易内幕信息的人员，在涉及证券的发行，证券、期货交易或者其他对证券、期货交易价格有重大影响的信息尚未公开前，买入或者卖出该证券，或者从事与该内幕信息有关的期货交易，或者泄露该信息，或者明示、暗示他人从事上述交易活动，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处违法所得一倍以上五倍以下罚金；情节特别严重的，处五年以上十年以下有期徒刑，并处违法所得一倍以上五倍以下罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。 内幕信息、知情人员的范围，依照法律、行政法规的规定确定。 证券交易所、期货交易所、证券公司、期货经纪公司、基金管理公司、商业银行、保险公司等金融机构的从业人员以及有关监管部门或者行业协会的工作人员，利用因职务便利获取的内幕信息以外的其他未公开的信息，违反规定，从事与该信息相关的证券、期货交易活动，或者明示、暗示他人从事相关交易活动，情节严重的，依照第一款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百八十一条", "text": "编造并且传播影响证券、期货交易的虚假信息，扰乱证券、期货交易市场，造成严重后果的，处五年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金。 证券交易所、期货交易所、证券公司、期货经纪公司的从业人员，证券业协会、期货业协会或者证券期货监督管理部门的工作人员，故意提供虚假信息或者伪造、变造、销毁交易记录，诱骗投资者买卖证券、期货合约，造成严重后果的，处五年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；情节特别恶劣的，处五年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金。 单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百八十二条", "text": "有下列情形之一，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处五年以上十年以下有期徒刑，并处罚金： （一）单独或者合谋，集中资金优势、持股或者持仓优势或者利用信息优势联合或者连续买卖的； （二）与他人串通，以事先约定的时间、价格和方式相互进行证券、期货交易的； （三）在自己实际控制的帐户之间进行证券交易，或者以自己为交易对象，自买自卖期货合约的； （四）不以成交为目的，频繁或者大量申报买入、卖出证券、期货合约并撤销申报的； （五）利用虚假或者不确定的重大信息，诱导投资者进行证券、期货交易的； （六）对证券、证券发行人、期货交易标的公开作出评价、预测或者投资建议，同时进行反向证券交易或者相关期货交易的； （七）以其他方法操纵证券、期货市场的。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百八十三条", "text": "保险公司的工作人员利用职务上的便利，故意编造未曾发生的保险事故进行虚假理赔，骗取保险金归自己所有的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十一条", "text": "的规定定罪处罚。 国有保险公司工作人员和国有保险公司委派到非国有保险公司从事公务的人员有前款行为的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十三条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百八十四条", "text": "银行或者其他金融机构的工作人员在金融业务活动中索取他人财物或者非法收受他人财物，为他人谋取利益的，或者违反国家规定，收受各种名义的回扣、手续费，归个人所有的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百六十三条", "text": "的规定定罪处罚。 国有金融机构工作人员和国有金融机构委派到非国有金融机构从事公务的人员有前款行为的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十六条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百八十五条", "text": "商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构的工作人员利用职务上的便利，挪用本单位或者客户资金的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十二条", "text": "的规定定罪处罚。 国有商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他国有金融机构的工作人员和国有商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他国有金融机构委派到前款规定中的非国有机构从事公务的人员有前款行为的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十四条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百八十五条", "text": "之一 商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构，违背受托义务，擅自运用客户资金或者其他委托、信托的财产，情节严重的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役，并处三万元以上三十万元以下罚金；情节特别严重的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金。 社会保障基金管理机构、住房公积金管理机构等公众资金管理机构，以及保险公司、保险资产管理公司、证券投资基金管理公司，违反国家规定运用资金的，对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百八十六条", "text": "银行或者其他金融机构的工作人员违反国家规定发放贷款，数额巨大或者造成重大损失的，处五年以下有期徒刑或者拘役，并处一万元以上十万元以下罚金；数额特别巨大或者造成特别重大损失的，处五年以上有期徒刑，并处二万元以上二十万元以下罚金。 银行或者其他金融机构的工作人员违反国家规定，向关系人发放贷款的，依照前款的规定从重处罚。 单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前两款的规定处罚。 关系人的范围，依照《中华人民共和国商业银行法》和有关金融法规确定。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百八十七条", "text": "银行或者其他金融机构的工作人员吸收客户资金不入帐，数额巨大或者造成重大损失的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额特别巨大或者造成特别重大损失的，处五年以上有期徒刑，并处五万元以上五十万元以下罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百八十八条", "text": "银行或者其他金融机构的工作人员违反规定，为他人出具信用证或者其他保函、票据、存单、资信证明，情节严重的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上有期徒刑。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百八十九条", "text": "银行或者其他金融机构的工作人员在票据业务中，对违反票据法规定的票据予以承兑、付款或者保证，造成重大损失的，处五年以下有期徒刑或者拘役；造成特别重大损失的，处五年以上有期徒刑。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百九十条", "text": "公司、企业或者其他单位，违反国家规定，擅自将外汇存放境外，或者将境内的外汇非法转移到境外，数额较大的，对单位判处逃汇数额百分之五以上百分之三十以下罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役；数额巨大或者有其他严重情节的，对单位判处逃汇数额百分之五以上百分之三十以下罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百九十一条", "text": "为掩饰、隐瞒毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪的所得及其产生的收益的来源和性质，有下列行为之一的，没收实施以上犯罪的所得及其产生的收益，处五年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处五年以上十年以下有期徒刑，并处罚金： （一）提供资金帐户的； （二）将财产转换为现金、金融票据、有价证券的； （三）通过转帐或者其他支付结算方式转移资金的； （四）跨境转移资产的； （五）以其他方法掩饰、隐瞒犯罪所得及其收益的来源和性质的。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。 第五节 金融诈骗罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百九十二条", "text": "以非法占有为目的，使用诈骗方法非法集资，数额较大的，处三年以上七年以下有期徒刑，并处罚金；数额巨大或者有其他严重情节的，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百九十三条", "text": "有下列情形之一，以非法占有为目的，诈骗银行或者其他金融机构的贷款，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产： （一）编造引进资金、项目等虚假理由的； （二）使用虚假的经济合同的； （三）使用虚假的证明文件的； （四）使用虚假的产权证明作担保或者超出抵押物价值重复担保的； （五）以其他方法诈骗贷款的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百九十四条", "text": "有下列情形之一，进行金融票据诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产： （一）明知是伪造、变造的汇票、本票、支票而使用的； （二）明知是作废的汇票、本票、支票而使用的； （三）冒用他人的汇票、本票、支票的； （四）签发空头支票或者与其预留印鉴不符的支票，骗取财物的； （五）汇票、本票的出票人签发无资金保证的汇票、本票或者在出票时作虚假记载，骗取财物的。 使用伪造、变造的委托收款凭证、汇款凭证、银行存单等其他银行结算凭证的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百九十五条", "text": "有下列情形之一，进行信用证诈骗活动的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产： （一）使用伪造、变造的信用证或者附随的单据、文件的； （二）使用作废的信用证的； （三）骗取信用证的； （四）以其他方法进行信用证诈骗活动的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百九十六条", "text": "有下列情形之一，进行信用卡诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产： （一）使用伪造的信用卡，或者使用以虚假的身份证明骗领的信用卡的； （二）使用作废的信用卡的； （三）冒用他人信用卡的； （四）恶意透支的。 前款所称恶意透支，是指持卡人以非法占有为目的，超过规定限额或者规定期限透支，并且经发卡银行催收后仍不归还的行为。 盗窃信用卡并使用的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十四条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百九十七条", "text": "使用伪造、变造的国库券或者国家发行的其他有价证券，进行诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百九十八条", "text": "有下列情形之一，进行保险诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处一万元以上十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑，并处二万元以上二十万元以下罚金或者没收财产： （一）投保人故意虚构保险标的，骗取保险金的； （二）投保人、被保险人或者受益人对发生的保险事故编造虚假的原因或者夸大损失的程度，骗取保险金的； （三）投保人、被保险人或者受益人编造未曾发生的保险事故，骗取保险金的； （四）投保人、被保险人故意造成财产损失的保险事故，骗取保险金的； （五）投保人、受益人故意造成被保险人死亡、伤残或者疾病，骗取保险金的。 有前款第四项、第五项所列行为，同时构成其他犯罪的，依照数罪并罚的规定处罚。 单位犯第一款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑。 保险事故的鉴定人、证明人、财产评估人故意提供虚假的证明文件，为他人诈骗提供条件的，以保险诈骗的共犯论处。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百九十五条", "text": "规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，可以并处罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金。 第六节 危害税收征管罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零一条", "text": "纳税人采取欺骗、隐瞒手段进行虚假纳税申报或者不申报，逃避缴纳税款数额较大并且占应纳税额百分之十以上的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大并且占应纳税额百分之三十以上的，处三年以上七年以下有期徒刑，并处罚金。 扣缴义务人采取前款所列手段，不缴或者少缴已扣、已收税款，数额较大的，依照前款的规定处罚。 对多次实施前两款行为，未经处理的，按照累计数额计算。 有第一款行为，经税务机关依法下达追缴通知后，补缴应纳税款，缴纳滞纳金，已受行政处罚的，不予追究刑事责任；但是，五年内因逃避缴纳税款受过刑事处罚或者被税务机关给予二次以上行政处罚的除外。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零二条", "text": "以暴力、威胁方法拒不缴纳税款的，处三年以下有期徒刑或者拘役，并处拒缴税款一倍以上五倍以下罚金；情节严重的，处三年以上七年以下有期徒刑，并处拒缴税款一倍以上五倍以下罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零三条", "text": "纳税人欠缴应纳税款，采取转移或者隐匿财产的手段，致使税务机关无法追缴欠缴的税款，数额在一万元以上不满十万元的，处三年以下有期徒刑或者拘役，并处或者单处欠缴税款一倍以上五倍以下罚金；数额在十万元以上的，处三年以上七年以下有期徒刑，并处欠缴税款一倍以上五倍以下罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零四条", "text": "以假报出口或者其他欺骗手段，骗取国家出口退税款，数额较大的，处五年以下有期徒刑或者拘役，并处骗取税款一倍以上五倍以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处骗取税款一倍以上五倍以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处骗取税款一倍以上五倍以下罚金或者没收财产。 纳税人缴纳税款后，采取前款规定的欺骗方法，骗取所缴纳的税款的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零一条", "text": "的规定定罪处罚；骗取税款超过所缴纳的税款部分，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零五条", "text": "虚开增值税专用发票或者虚开用于骗取出口退税、抵扣税款的其他发票的，处三年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；虚开的税款数额较大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；虚开的税款数额巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。 单位犯本条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役；虚开的税款数额较大或者有其他严重情节的，处三年以上十年以下有期徒刑；虚开的税款数额巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑。 虚开增值税专用发票或者虚开用于骗取出口退税、抵扣税款的其他发票，是指有为他人虚开、为自己虚开、让他人为自己虚开、介绍他人虚开行为之一的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零五条", "text": "规定以外的其他发票，情节严重的，处二年以下有期徒刑、拘役或者管制，并处罚金；情节特别严重的，处二年以上七年以下有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零六条", "text": "伪造或者出售伪造的增值税专用发票的，处三年以下有期徒刑、拘役或者管制，并处二万元以上二十万元以下罚金；数量较大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数量巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。 单位犯本条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑、拘役或者管制；数量较大或者有其他严重情节的，处三年以上十年以下有期徒刑；数量巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零七条", "text": "非法出售增值税专用发票的，处三年以下有期徒刑、拘役或者管制，并处二万元以上二十万元以下罚金；数量较大的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数量巨大的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零八条", "text": "非法购买增值税专用发票或者购买伪造的增值税专用发票的，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金。 非法购买增值税专用发票或者购买伪造的增值税专用发票又虚开或者出售的，分别依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零七条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零九条", "text": "伪造、擅自制造或者出售伪造、擅自制造的可以用于骗取出口退税、抵扣税款的其他发票的，处三年以下有期徒刑、拘役或者管制，并处二万元以上二十万元以下罚金；数量巨大的，处三年以上七年以下有期徒刑，并处五万元以上五十万元以下罚金；数量特别巨大的，处七年以上有期徒刑，并处五万元以上五十万元以下罚金或者没收财产。 伪造、擅自制造或者出售伪造、擅自制造的前款规定以外的其他发票的，处二年以下有期徒刑、拘役或者管制，并处或者单处一万元以上五万元以下罚金；情节严重的，处二年以上七年以下有期徒刑，并处五万元以上五十万元以下罚金。 非法出售可以用于骗取出口退税、抵扣税款的其他发票的，依照第一款的规定处罚。 非法出售第三款规定以外的其他发票的，依照第二款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百一十条", "text": "盗窃增值税专用发票或者可以用于骗取出口退税、抵扣税款的其他发票的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十四条", "text": "的规定定罪处罚。 使用欺骗手段骗取增值税专用发票或者可以用于骗取出口退税、抵扣税款的其他发票的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十六条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百一十条", "text": "之一 明知是伪造的发票而持有，数量较大的，处二年以下有期徒刑、拘役或者管制，并处罚金；数量巨大的，处二年以上七年以下有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零九条", "text": "规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该条的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百零五条", "text": "规定之罪，被判处罚金、没收财产的，在执行前，应当先由税务机关追缴税款和所骗取的出口退税款。 第七节 侵犯知识产权罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百一十三条", "text": "未经注册商标所有人许可，在同一种商品、服务上使用与其注册商标相同的商标，情节严重的，处三年以下有期徒刑，并处或者单处罚金；情节特别严重的，处三年以上十年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百一十四条", "text": "销售明知是假冒注册商标的商品，违法所得数额较大或者有其他严重情节的，处三年以下有期徒刑，并处或者单处罚金；违法所得数额巨大或者有其他特别严重情节的，处三年以上十年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百一十五条", "text": "伪造、擅自制造他人注册商标标识或者销售伪造、擅自制造的注册商标标识，情节严重的，处三年以下有期徒刑，并处或者单处罚金；情节特别严重的，处三年以上十年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百一十六条", "text": "假冒他人专利，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百一十七条", "text": "以营利为目的，有下列侵犯著作权或者与著作权有关的权利的情形之一，违法所得数额较大或者有其他严重情节的，处三年以下有期徒刑，并处或者单处罚金；违法所得数额巨大或者有其他特别严重情节的，处三年以上十年以下有期徒刑，并处罚金： （一）未经著作权人许可，复制发行、通过信息网络向公众传播其文字作品、音乐、美术、视听作品、计算机软件及法律、行政法规规定的其他作品的； （二）出版他人享有专有出版权的图书的； （三）未经录音录像制作者许可，复制发行、通过信息网络向公众传播其制作的录音录像的； （四）未经表演者许可，复制发行录有其表演的录音录像制品，或者通过信息网络向公众传播其表演的； （五）制作、出售假冒他人署名的美术作品的； （六）未经著作权人或者与著作权有关的权利人许可，故意避开或者破坏权利人为其作品、录音录像制品等采取的保护著作权或者与著作权有关的权利的技术措施的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百一十八条", "text": "以营利为目的，销售明知是本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百一十七条", "text": "规定的侵权复制品，违法所得数额巨大或者有其他严重情节的，处五年以下有期徒刑，并处或者单处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百一十九条", "text": "有下列侵犯商业秘密行为之一，情节严重的，处三年以下有期徒刑，并处或者单处罚金；情节特别严重的，处三年以上十年以下有期徒刑，并处罚金： （一）以盗窃、贿赂、欺诈、胁迫、电子侵入或者其他不正当手段获取权利人的商业秘密的； （二）披露、使用或者允许他人使用以前项手段获取的权利人的商业秘密的； （三）违反保密义务或者违反权利人有关保守商业秘密的要求，披露、使用或者允许他人使用其所掌握的商业秘密的。 明知前款所列行为，获取、披露、使用或者允许他人使用该商业秘密的，以侵犯商业秘密论。 本条所称权利人，是指商业秘密的所有人和经商业秘密所有人许可的商业秘密使用人。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百一十九条", "text": "之一 为境外的机构、组织、人员窃取、刺探、收买、非法提供商业秘密的，处五年以下有期徒刑，并处或者单处罚金；情节严重的，处五年以上有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百一十九条", "text": "之一规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本节各该条的规定处罚。 第八节 扰乱市场秩序罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百二十一条", "text": "捏造并散布虚伪事实，损害他人的商业信誉、商品声誉，给他人造成重大损失或者有其他严重情节的，处二年以下有期徒刑或者拘役，并处或者单处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百二十二条", "text": "广告主、广告经营者、广告发布者违反国家规定，利用广告对商品或者服务作虚假宣传，情节严重的，处二年以下有期徒刑或者拘役，并处或者单处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百二十三条", "text": "投标人相互串通投标报价，损害招标人或者其他投标人利益，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。 投标人与招标人串通投标，损害国家、集体、公民的合法利益的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百二十四条", "text": "有下列情形之一，以非法占有为目的，在签订、履行合同过程中，骗取对方当事人财物，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产： （一）以虚构的单位或者冒用他人名义签订合同的； （二）以伪造、变造、作废的票据或者其他虚假的产权证明作担保的； （三）没有实际履行能力，以先履行小额合同或者部分履行合同的方法，诱骗对方当事人继续签订和履行合同的； （四）收受对方当事人给付的货物、货款、预付款或者担保财产后逃匿的； （五）以其他方法骗取对方当事人财物的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百二十四条", "text": "之一 组织、领导以推销商品、提供服务等经营活动为名，要求参加者以缴纳费用或者购买商品、服务等方式获得加入资格，并按照一定顺序组成层级，直接或者间接以发展人员的数量作为计酬或者返利依据，引诱、胁迫参加者继续发展他人参加，骗取财物，扰乱经济社会秩序的传销活动的，处五年以下有期徒刑或者拘役，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百二十五条", "text": "违反国家规定，有下列非法经营行为之一，扰乱市场秩序，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处违法所得一倍以上五倍以下罚金；情节特别严重的，处五年以上有期徒刑，并处违法所得一倍以上五倍以下罚金或者没收财产： （一）未经许可经营法律、行政法规规定的专营、专卖物品或者其他限制买卖的物品的； （二）买卖进出口许可证、进出口原产地证明以及其他法律、行政法规规定的经营许可证或者批准文件的； （三）未经国家有关主管部门批准非法经营证券、期货、保险业务的，或者非法从事资金支付结算业务的； （四）其他严重扰乱市场秩序的非法经营行为。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百二十六条", "text": "以暴力、威胁手段，实施下列行为之一，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金： （一）强买强卖商品的； （二）强迫他人提供或者接受服务的； （三）强迫他人参与或者退出投标、拍卖的； （四）强迫他人转让或者收购公司、企业的股份、债券或者其他资产的； （五）强迫他人参与或者退出特定的经营活动的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百二十七条", "text": "伪造或者倒卖伪造的车票、船票、邮票或者其他有价票证，数额较大的，处二年以下有期徒刑、拘役或者管制，并处或者单处票证价额一倍以上五倍以下罚金；数额巨大的，处二年以上七年以下有期徒刑，并处票证价额一倍以上五倍以下罚金。 倒卖车票、船票，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处票证价额一倍以上五倍以下罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百二十八条", "text": "以牟利为目的，违反土地管理法规，非法转让、倒卖土地使用权，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处非法转让、倒卖土地使用权价额百分之五以上百分之二十以下罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处非法转让、倒卖土地使用权价额百分之五以上百分之二十以下罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百二十九条", "text": "承担资产评估、验资、验证、会计、审计、法律服务、保荐、安全评价、环境影响评价、环境监测等职责的中介组织的人员故意提供虚假证明文件，情节严重的，处五年以下有期徒刑或者拘役，并处罚金；有下列情形之一的，处五年以上十年以下有期徒刑，并处罚金： （一）提供与证券发行相关的虚假的资产评估、会计、审计、法律服务、保荐等证明文件，情节特别严重的； （二）提供与重大资产交易相关的虚假的资产评估、会计、审计等证明文件，情节特别严重的； （三）在涉及公共安全的重大工程、项目中提供虚假的安全评价、环境影响评价等证明文件，致使公共财产、国家和人民利益遭受特别重大损失的。 有前款行为，同时索取他人财物或者非法收受他人财物构成犯罪的，依照处罚较重的规定定罪处罚。 第一款规定的人员，严重不负责任，出具的证明文件有重大失实，造成严重后果的，处三年以下有期徒刑或者拘役，并处或者单处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十条", "text": "违反进出口商品检验法的规定，逃避商品检验，将必须经商检机构检验的进口商品未报经检验而擅自销售、使用，或者将必须经商检机构检验的出口商品未报经检验合格而擅自出口，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十条", "text": "规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本节各该条的规定处罚。 第四章 侵犯公民人身权利、民主权利罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十二条", "text": "故意杀人的，处死刑、无期徒刑或者十年以上有期徒刑；情节较轻的，处三年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十三条", "text": "过失致人死亡的，处三年以上七年以下有期徒刑；情节较轻的，处三年以下有期徒刑。本法另有规定的，依照规定。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十四条", "text": "故意伤害他人身体的，处三年以下有期徒刑、拘役或者管制。 犯前款罪，致人重伤的，处三年以上十年以下有期徒刑；致人死亡或者以特别残忍手段致人重伤造成严重残疾的，处十年以上有期徒刑、无期徒刑或者死刑。本法另有规定的，依照规定。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十四条", "text": "之一 组织他人出卖人体器官的，处五年以下有期徒刑，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产。 未经本人同意摘取其器官，或者摘取不满十八周岁的人的器官，或者强迫、欺骗他人捐献器官的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十二条", "text": "的规定定罪处罚。 违背本人生前意愿摘取其尸体器官，或者本人生前未表示同意，违反国家规定，违背其近亲属意愿摘取其尸体器官的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百零二条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十五条", "text": "过失伤害他人致人重伤的，处三年以下有期徒刑或者拘役。本法另有规定的，依照规定。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十六条", "text": "以暴力、胁迫或者其他手段强奸妇女的，处三年以上十年以下有期徒刑。 奸淫不满十四周岁的幼女的，以强奸论，从重处罚。 强奸妇女、奸淫幼女，有下列情形之一的，处十年以上有期徒刑、无期徒刑或者死刑： （一）强奸妇女、奸淫幼女情节恶劣的； （二）强奸妇女、奸淫幼女多人的； （三）在公共场所当众强奸妇女、奸淫幼女的； （四）二人以上轮奸的； （五）奸淫不满十周岁的幼女或者造成幼女伤害的； （六）致使被害人重伤、死亡或者造成其他严重后果的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十六条", "text": "之一 对已满十四周岁不满十六周岁的未成年女性负有监护、收养、看护、教育、医疗等特殊职责的人员，与该未成年女性发生性关系的，处三年以下有期徒刑；情节恶劣的，处三年以上十年以下有期徒刑。 有前款行为，同时又构成本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十六条", "text": "规定之罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十七条", "text": "以暴力、胁迫或者其他方法强制猥亵他人或者侮辱妇女的，处五年以下有期徒刑或者拘役。 聚众或者在公共场所当众犯前款罪的，或者有其他恶劣情节的，处五年以上有期徒刑。 猥亵儿童的，处五年以下有期徒刑；有下列情形之一的，处五年以上有期徒刑： （一）猥亵儿童多人或者多次的； （二）聚众猥亵儿童的，或者在公共场所当众猥亵儿童，情节恶劣的； （三）造成儿童伤害或者其他严重后果的； （四）猥亵手段恶劣或者有其他恶劣情节的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十八条", "text": "非法拘禁他人或者以其他方法非法剥夺他人人身自由的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。具有殴打、侮辱情节的，从重处罚。 犯前款罪，致人重伤的，处三年以上十年以下有期徒刑；致人死亡的，处十年以上有期徒刑。使用暴力致人伤残、死亡的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十二条", "text": "的规定定罪处罚。 为索取债务非法扣押、拘禁他人的，依照前两款的规定处罚。 国家机关工作人员利用职权犯前三款罪的，依照前三款的规定从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十九条", "text": "以勒索财物为目的绑架他人的，或者绑架他人作为人质的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；情节较轻的，处五年以上十年以下有期徒刑，并处罚金。 犯前款罪，杀害被绑架人的，或者故意伤害被绑架人，致人重伤、死亡的，处无期徒刑或者死刑，并处没收财产。 以勒索财物为目的偷盗婴幼儿的，依照前两款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百四十条", "text": "拐卖妇女、儿童的，处五年以上十年以下有期徒刑，并处罚金；有下列情形之一的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；情节特别严重的，处死刑，并处没收财产： （一）拐卖妇女、儿童集团的首要分子； （二）拐卖妇女、儿童三人以上的； （三）奸淫被拐卖的妇女的； （四）诱骗、强迫被拐卖的妇女卖淫或者将被拐卖的妇女卖给他人迫使其卖淫的； （五）以出卖为目的，使用暴力、胁迫或者麻醉方法绑架妇女、儿童的； （六）以出卖为目的，偷盗婴幼儿的； （七）造成被拐卖的妇女、儿童或者其亲属重伤、死亡或者其他严重后果的； （八）将妇女、儿童卖往境外的。 拐卖妇女、儿童是指以出卖为目的，有拐骗、绑架、收买、贩卖、接送、中转妇女、儿童的行为之一的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百四十一条", "text": "收买被拐卖的妇女、儿童的，处三年以下有期徒刑、拘役或者管制。 收买被拐卖的妇女，强行与其发生性关系的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十六条", "text": "的规定定罪处罚。 收买被拐卖的妇女、儿童，非法剥夺、限制其人身自由或者有伤害、侮辱等犯罪行为的，依照本法的有关规定定罪处罚。 收买被拐卖的妇女、儿童，并有第二款、第三款规定的犯罪行为的，依照数罪并罚的规定处罚。 收买被拐卖的妇女、儿童又出卖的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百四十条", "text": "的规定定罪处罚。 收买被拐卖的妇女、儿童，对被买儿童没有虐待行为，不阻碍对其进行解救的，可以从轻处罚；按照被买妇女的意愿，不阻碍其返回原居住地的，可以从轻或者减轻处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百四十二条", "text": "以暴力、威胁方法阻碍国家机关工作人员解救被收买的妇女、儿童的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十七条", "text": "的规定定罪处罚。 聚众阻碍国家机关工作人员解救被收买的妇女、儿童的首要分子，处五年以下有期徒刑或者拘役；其他参与者使用暴力、威胁方法的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百四十三条", "text": "捏造事实诬告陷害他人，意图使他人受刑事追究，情节严重的，处三年以下有期徒刑、拘役或者管制；造成严重后果的，处三年以上十年以下有期徒刑。 国家机关工作人员犯前款罪的，从重处罚。 不是有意诬陷，而是错告，或者检举失实的，不适用前两款的规定。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百四十四条", "text": "以暴力、威胁或者限制人身自由的方法强迫他人劳动的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。 明知他人实施前款行为，为其招募、运送人员或者有其他协助强迫他人劳动行为的，依照前款的规定处罚。 单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百四十四条", "text": "之一 违反劳动管理法规，雇用未满十六周岁的未成年人从事超强度体力劳动的，或者从事高空、井下作业的，或者在爆炸性、易燃性、放射性、毒害性等危险环境下从事劳动，情节严重的，对直接责任人员，处三年以下有期徒刑或者拘役，并处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。 有前款行为，造成事故，又构成其他犯罪的，依照数罪并罚的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百四十五条", "text": "非法搜查他人身体、住宅，或者非法侵入他人住宅的，处三年以下有期徒刑或者拘役。 司法工作人员滥用职权，犯前款罪的，从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百四十六条", "text": "以暴力或者其他方法公然侮辱他人或者捏造事实诽谤他人，情节严重的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。 前款罪，告诉的才处理，但是严重危害社会秩序和国家利益的除外。 通过信息网络实施第一款规定的行为，被害人向人民法院告诉，但提供证据确有困难的，人民法院可以要求公安机关提供协助。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百四十七条", "text": "司法工作人员对犯罪嫌疑人、被告人实行刑讯逼供或者使用暴力逼取证人证言的，处三年以下有期徒刑或者拘役。致人伤残、死亡的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十二条", "text": "的规定定罪从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百四十八条", "text": "监狱、拘留所、看守所等监管机构的监管人员对被监管人进行殴打或者体罚虐待，情节严重的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上十年以下有期徒刑。致人伤残、死亡的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十二条", "text": "的规定定罪从重处罚。 监管人员指使被监管人殴打或者体罚虐待其他被监管人的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百四十九条", "text": "煽动民族仇恨、民族歧视，情节严重的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节特别严重的，处三年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百五十条", "text": "在出版物中刊载歧视、侮辱少数民族的内容，情节恶劣，造成严重后果的，对直接责任人员，处三年以下有期徒刑、拘役或者管制。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百五十一条", "text": "国家机关工作人员非法剥夺公民的宗教信仰自由和侵犯少数民族风俗习惯，情节严重的，处二年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百五十二条", "text": "隐匿、毁弃或者非法开拆他人信件，侵犯公民通信自由权利，情节严重的，处一年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百五十三条", "text": "邮政工作人员私自开拆或者隐匿、毁弃邮件、电报的，处二年以下有期徒刑或者拘役。 犯前款罪而窃取财物的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十四条", "text": "的规定定罪从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百五十三条", "text": "之一 违反国家有关规定，向他人出售或者提供公民个人信息，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。 违反国家有关规定，将在履行职责或者提供服务过程中获得的公民个人信息，出售或者提供给他人的，依照前款的规定从重处罚。 窃取或者以其他方法非法获取公民个人信息的，依照第一款的规定处罚。 单位犯前三款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百五十四条", "text": "国家机关工作人员滥用职权、假公济私，对控告人、申诉人、批评人、举报人实行报复陷害的，处二年以下有期徒刑或者拘役；情节严重的，处二年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百五十五条", "text": "公司、企业、事业单位、机关、团体的领导人，对依法履行职责、抵制违反会计法、统计法行为的会计、统计人员实行打击报复，情节恶劣的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百五十六条", "text": "在选举各级人民代表大会代表和国家机关领导人员时，以暴力、威胁、欺骗、贿赂、伪造选举文件、虚报选举票数等手段破坏选举或者妨害选民和代表自由行使选举权和被选举权，情节严重的，处三年以下有期徒刑、拘役或者剥夺政治权利。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百五十七条", "text": "以暴力干涉他人婚姻自由的，处二年以下有期徒刑或者拘役。 犯前款罪，致使被害人死亡的，处二年以上七年以下有期徒刑。 第一款罪，告诉的才处理。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百五十八条", "text": "有配偶而重婚的，或者明知他人有配偶而与之结婚的，处二年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百五十九条", "text": "明知是现役军人的配偶而与之同居或者结婚的，处三年以下有期徒刑或者拘役。 利用职权、从属关系，以胁迫手段奸淫现役军人的妻子的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十六条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十条", "text": "虐待家庭成员，情节恶劣的，处二年以下有期徒刑、拘役或者管制。 犯前款罪，致使被害人重伤、死亡的，处二年以上七年以下有期徒刑。 第一款罪，告诉的才处理，但被害人没有能力告诉，或者因受到强制、威吓无法告诉的除外。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十条", "text": "之一 对未成年人、老年人、患病的人、残疾人等负有监护、看护职责的人虐待被监护、看护的人，情节恶劣的，处三年以下有期徒刑或者拘役。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。 有第一款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十一条", "text": "对于年老、年幼、患病或者其他没有独立生活能力的人，负有扶养义务而拒绝扶养，情节恶劣的，处五年以下有期徒刑、拘役或者管制。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十二条", "text": "拐骗不满十四周岁的未成年人，脱离家庭或者监护人的，处五年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十二条", "text": "之一 以暴力、胁迫手段组织残疾人或者不满十四周岁的未成年人乞讨的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十二条", "text": "之二 组织未成年人进行盗窃、诈骗、抢夺、敲诈勒索等违反治安管理活动的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。 第五章 侵犯财产罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十三条", "text": "以暴力、胁迫或者其他方法抢劫公私财物的，处三年以上十年以下有期徒刑，并处罚金；有下列情形之一的，处十年以上有期徒刑、无期徒刑或者死刑，并处罚金或者没收财产： （一）入户抢劫的； （二）在公共交通工具上抢劫的； （三）抢劫银行或者其他金融机构的； （四）多次抢劫或者抢劫数额巨大的； （五）抢劫致人重伤、死亡的； （六）冒充军警人员抢劫的； （七）持枪抢劫的； （八）抢劫军用物资或者抢险、救灾、救济物资的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十四条", "text": "盗窃公私财物，数额较大的，或者多次盗窃、入户盗窃、携带凶器盗窃、扒窃的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十五条", "text": "以牟利为目的，盗接他人通信线路、复制他人电信码号或者明知是盗接、复制的电信设备、设施而使用的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十四条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十六条", "text": "诈骗公私财物，数额较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。本法另有规定的，依照规定。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十七条", "text": "抢夺公私财物，数额较大的，或者多次抢夺的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。 携带凶器抢夺的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十三条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十八条", "text": "聚众哄抢公私财物，数额较大或者有其他严重情节的，对首要分子和积极参加的，处三年以下有期徒刑、拘役或者管制，并处罚金；数额巨大或者有其他特别严重情节的，处三年以上十年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十九条", "text": "犯盗窃、诈骗、抢夺罪，为窝藏赃物、抗拒抓捕或者毁灭罪证而当场使用暴力或者以暴力相威胁的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十三条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十条", "text": "将代为保管的他人财物非法占为己有，数额较大，拒不退还的，处二年以下有期徒刑、拘役或者罚金；数额巨大或者有其他严重情节的，处二年以上五年以下有期徒刑，并处罚金。 将他人的遗忘物或者埋藏物非法占为己有，数额较大，拒不交出的，依照前款的规定处罚。 本条罪，告诉的才处理。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十一条", "text": "公司、企业或者其他单位的工作人员，利用职务上的便利，将本单位财物非法占为己有，数额较大的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大的，处十年以上有期徒刑或者无期徒刑，并处罚金。 国有公司、企业或者其他国有单位中从事公务的人员和国有公司、企业或者其他国有单位委派到非国有公司、企业以及其他单位从事公务的人员有前款行为的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十三条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十二条", "text": "公司、企业或者其他单位的工作人员，利用职务上的便利，挪用本单位资金归个人使用或者借贷给他人，数额较大、超过三个月未还的，或者虽未超过三个月，但数额较大、进行营利活动的，或者进行非法活动的，处三年以下有期徒刑或者拘役；挪用本单位资金数额巨大的，处三年以上七年以下有期徒刑；数额特别巨大的，处七年以上有期徒刑。 国有公司、企业或者其他国有单位中从事公务的人员和国有公司、企业或者其他国有单位委派到非国有公司、企业以及其他单位从事公务的人员有前款行为的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十四条", "text": "的规定定罪处罚。 有第一款行为，在提起公诉前将挪用的资金退还的，可以从轻或者减轻处罚。其中，犯罪较轻的，可以减轻或者免除处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十三条", "text": "挪用用于救灾、抢险、防汛、优抚、扶贫、移民、救济款物，情节严重，致使国家和人民群众利益遭受重大损害的，对直接责任人员，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十四条", "text": "敲诈勒索公私财物，数额较大或者多次敲诈勒索的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十五条", "text": "故意毁坏公私财物，数额较大或者有其他严重情节的，处三年以下有期徒刑、拘役或者罚金；数额巨大或者有其他特别严重情节的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十六条", "text": "由于泄愤报复或者其他个人目的，毁坏机器设备、残害耕畜或者以其他方法破坏生产经营的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十六条", "text": "之一 以转移财产、逃匿等方法逃避支付劳动者的劳动报酬或者有能力支付而不支付劳动者的劳动报酬，数额较大，经政府有关部门责令支付仍不支付的，处三年以下有期徒刑或者拘役，并处或者单处罚金；造成严重后果的，处三年以上七年以下有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。 有前两款行为，尚未造成严重后果，在提起公诉前支付劳动者的劳动报酬，并依法承担相应赔偿责任的，可以减轻或者免除处罚。 第六章 妨害社会管理秩序罪 第一节 扰乱公共秩序罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十七条", "text": "以暴力、威胁方法阻碍国家机关工作人员依法执行职务的，处三年以下有期徒刑、拘役、管制或者罚金。 以暴力、威胁方法阻碍全国人民代表大会和地方各级人民代表大会代表依法执行代表职务的，依照前款的规定处罚。 在自然灾害和突发事件中，以暴力、威胁方法阻碍红十字会工作人员依法履行职责的，依照第一款的规定处罚。 故意阻碍国家安全机关、公安机关依法执行国家安全工作任务，未使用暴力、威胁方法，造成严重后果的，依照第一款的规定处罚。 暴力袭击正在依法执行职务的人民警察的，处三年以下有期徒刑、拘役或者管制；使用枪支、管制刀具，或者以驾驶机动车撞击等手段，严重危及其人身安全的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十八条", "text": "煽动群众暴力抗拒国家法律、行政法规实施的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；造成严重后果的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百七十九条", "text": "冒充国家机关工作人员招摇撞骗的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上十年以下有期徒刑。 冒充人民警察招摇撞骗的，依照前款的规定从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十条", "text": "伪造、变造、买卖或者盗窃、抢夺、毁灭国家机关的公文、证件、印章的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。 伪造公司、企业、事业单位、人民团体的印章的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金。 伪造、变造、买卖居民身份证、护照、社会保障卡、驾驶证等依法可以用于证明身份的证件的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十条", "text": "之一 在依照国家规定应当提供身份证明的活动中，使用伪造、变造的或者盗用他人的居民身份证、护照、社会保障卡、驾驶证等依法可以用于证明身份的证件，情节严重的，处拘役或者管制，并处或者单处罚金。 有前款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十条", "text": "之二 盗用、冒用他人身份，顶替他人取得的高等学历教育入学资格、公务员录用资格、就业安置待遇的，处三年以下有期徒刑、拘役或者管制，并处罚金。 组织、指使他人实施前款行为的，依照前款的规定从重处罚。 国家工作人员有前两款行为，又构成其他犯罪的，依照数罪并罚的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十一条", "text": "非法生产、买卖人民警察制式服装、车辆号牌等专用标志、警械，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十二条", "text": "以窃取、刺探、收买方法，非法获取国家秘密的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上七年以下有期徒刑。 非法持有属于国家绝密、机密的文件、资料或者其他物品，拒不说明来源与用途的，处三年以下有期徒刑、拘役或者管制。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十三条", "text": "非法生产、销售专用间谍器材或者窃听、窃照专用器材的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十四条", "text": "非法使用窃听、窃照专用器材，造成严重后果的，处二年以下有期徒刑、拘役或者管制。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十四条", "text": "之一 在法律规定的国家考试中，组织作弊的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。 为他人实施前款犯罪提供作弊器材或者其他帮助的，依照前款的规定处罚。 为实施考试作弊行为，向他人非法出售或者提供第一款规定的考试的试题、答案的，依照第一款的规定处罚。 代替他人或者让他人代替自己参加第一款规定的考试的，处拘役或者管制，并处或者单处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十五条", "text": "违反国家规定，侵入国家事务、国防建设、尖端科学技术领域的计算机信息系统的，处三年以下有期徒刑或者拘役。 违反国家规定，侵入前款规定以外的计算机信息系统或者采用其他技术手段，获取该计算机信息系统中存储、处理或者传输的数据，或者对该计算机信息系统实施非法控制，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。 提供专门用于侵入、非法控制计算机信息系统的程序、工具，或者明知他人实施侵入、非法控制计算机信息系统的违法犯罪行为而为其提供程序、工具，情节严重的，依照前款的规定处罚。 单位犯前三款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十六条", "text": "违反国家规定，对计算机信息系统功能进行删除、修改、增加、干扰，造成计算机信息系统不能正常运行，后果严重的，处五年以下有期徒刑或者拘役；后果特别严重的，处五年以上有期徒刑。 违反国家规定，对计算机信息系统中存储、处理或者传输的数据和应用程序进行删除、修改、增加的操作，后果严重的，依照前款的规定处罚。 故意制作、传播计算机病毒等破坏性程序，影响计算机系统正常运行，后果严重的，依照第一款的规定处罚。 单位犯前三款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十六条", "text": "之一 网络服务提供者不履行法律、行政法规规定的信息网络安全管理义务，经监管部门责令采取改正措施而拒不改正，有下列情形之一的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金： （一）致使违法信息大量传播的； （二）致使用户信息泄露，造成严重后果的； （三）致使刑事案件证据灭失，情节严重的； （四）有其他严重情节的。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。 有前两款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十七条", "text": "利用计算机实施金融诈骗、盗窃、贪污、挪用公款、窃取国家秘密或者其他犯罪的，依照本法有关规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十七条", "text": "之一 利用信息网络实施下列行为之一，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金： （一）设立用于实施诈骗、传授犯罪方法、制作或者销售违禁物品、管制物品等违法犯罪活动的网站、通讯群组的； （二）发布有关制作或者销售毒品、枪支、淫秽物品等违禁物品、管制物品或者其他违法犯罪信息的； （三）为实施诈骗等违法犯罪活动发布信息的。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。 有前两款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十七条", "text": "之二 明知他人利用信息网络实施犯罪，为其犯罪提供互联网接入、服务器托管、网络存储、通讯传输等技术支持，或者提供广告推广、支付结算等帮助，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。 有前两款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十八条", "text": "违反国家规定，擅自设置、使用无线电台（站），或者擅自使用无线电频率，干扰无线电通讯秩序，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百八十九条", "text": "聚众“打砸抢”，致人伤残、死亡的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十二条", "text": "的规定定罪处罚。毁坏或者抢走公私财物的，除判令退赔外，对首要分子，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百六十三条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十条", "text": "聚众扰乱社会秩序，情节严重，致使工作、生产、营业和教学、科研、医疗无法进行，造成严重损失的，对首要分子，处三年以上七年以下有期徒刑；对其他积极参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。 聚众冲击国家机关，致使国家机关工作无法进行，造成严重损失的，对首要分子，处五年以上十年以下有期徒刑；对其他积极参加的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。 多次扰乱国家机关工作秩序，经行政处罚后仍不改正，造成严重后果的，处三年以下有期徒刑、拘役或者管制。 多次组织、资助他人非法聚集，扰乱社会秩序，情节严重的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十一条", "text": "聚众扰乱车站、码头、民用航空站、商场、公园、影剧院、展览会、运动场或者其他公共场所秩序，聚众堵塞交通或者破坏交通秩序，抗拒、阻碍国家治安管理工作人员依法执行职务，情节严重的，对首要分子，处五年以下有期徒刑、拘役或者管制。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十一条", "text": "之一 投放虚假的爆炸性、毒害性、放射性、传染病病原体等物质，或者编造爆炸威胁、生化威胁、放射威胁等恐怖信息，或者明知是编造的恐怖信息而故意传播，严重扰乱社会秩序的，处五年以下有期徒刑、拘役或者管制；造成严重后果的，处五年以上有期徒刑。 编造虚假的险情、疫情、灾情、警情，在信息网络或者其他媒体上传播，或者明知是上述虚假信息，故意在信息网络或者其他媒体上传播，严重扰乱社会秩序的，处三年以下有期徒刑、拘役或者管制；造成严重后果的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十一条", "text": "之二 从建筑物或者其他高空抛掷物品，情节严重的，处一年以下有期徒刑、拘役或者管制，并处或者单处罚金。 有前款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十二条", "text": "聚众斗殴的，对首要分子和其他积极参加的，处三年以下有期徒刑、拘役或者管制；有下列情形之一的，对首要分子和其他积极参加的，处三年以上十年以下有期徒刑： （一）多次聚众斗殴的； （二）聚众斗殴人数多，规模大，社会影响恶劣的； （三）在公共场所或者交通要道聚众斗殴，造成社会秩序严重混乱的； （四）持械聚众斗殴的。 聚众斗殴，致人重伤、死亡的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十二条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十三条", "text": "有下列寻衅滋事行为之一，破坏社会秩序的，处五年以下有期徒刑、拘役或者管制： （一）随意殴打他人，情节恶劣的； （二）追逐、拦截、辱骂、恐吓他人，情节恶劣的； （三）强拿硬要或者任意损毁、占用公私财物，情节严重的； （四）在公共场所起哄闹事，造成公共场所秩序严重混乱的。 纠集他人多次实施前款行为，严重破坏社会秩序的，处五年以上十年以下有期徒刑，可以并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十三条", "text": "之一 有下列情形之一，催收高利放贷等产生的非法债务，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金： （一）使用暴力、胁迫方法的； （二）限制他人人身自由或者侵入他人住宅的； （三）恐吓、跟踪、骚扰他人的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十四条", "text": "组织、领导黑社会性质的组织的，处七年以上有期徒刑，并处没收财产；积极参加的，处三年以上七年以下有期徒刑，可以并处罚金或者没收财产；其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，可以并处罚金。 境外的黑社会组织的人员到中华人民共和国境内发展组织成员的，处三年以上十年以下有期徒刑。 国家机关工作人员包庇黑社会性质的组织，或者纵容黑社会性质的组织进行违法犯罪活动的，处五年以下有期徒刑；情节严重的，处五年以上有期徒刑。 犯前三款罪又有其他犯罪行为的，依照数罪并罚的规定处罚。 黑社会性质的组织应当同时具备以下特征： （一）形成较稳定的犯罪组织，人数较多，有明确的组织者、领导者，骨干成员基本固定； （二）有组织地通过违法犯罪活动或者其他手段获取经济利益，具有一定的经济实力，以支持该组织的活动； （三）以暴力、威胁或者其他手段，有组织地多次进行违法犯罪活动，为非作恶，欺压、残害群众； （四）通过实施违法犯罪活动，或者利用国家工作人员的包庇或者纵容，称霸一方，在一定区域或者行业内，形成非法控制或者重大影响，严重破坏经济、社会生活秩序。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十五条", "text": "传授犯罪方法的，处五年以下有期徒刑、拘役或者管制；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十六条", "text": "举行集会、游行、示威，未依照法律规定申请或者申请未获许可，或者未按照主管机关许可的起止时间、地点、路线进行，又拒不服从解散命令，严重破坏社会秩序的，对集会、游行、示威的负责人和直接责任人员，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十七条", "text": "违反法律规定，携带武器、管制刀具或者爆炸物参加集会、游行、示威的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十八条", "text": "扰乱、冲击或者以其他方法破坏依法举行的集会、游行、示威，造成公共秩序混乱的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十九条", "text": "在公共场合，故意以焚烧、毁损、涂划、玷污、践踏等方式侮辱中华人民共和国国旗、国徽的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。 在公共场合，故意篡改中华人民共和国国歌歌词、曲谱，以歪曲、贬损方式奏唱国歌，或者以其他方式侮辱国歌，情节严重的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百九十九条", "text": "之一 侮辱、诽谤或者以其他方式侵害英雄烈士的名誉、荣誉，损害社会公共利益，情节严重的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百条", "text": "组织、利用会道门、邪教组织或者利用迷信破坏国家法律、行政法规实施的，处三年以上七年以下有期徒刑，并处罚金；情节特别严重的，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；情节较轻的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，并处或者单处罚金。 组织、利用会道门、邪教组织或者利用迷信蒙骗他人，致人重伤、死亡的，依照前款的规定处罚。 犯第一款罪又有奸淫妇女、诈骗财物等犯罪行为的，依照数罪并罚的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百零一条", "text": "聚众进行淫乱活动的，对首要分子或者多次参加的，处五年以下有期徒刑、拘役或者管制。 引诱未成年人参加聚众淫乱活动的，依照前款的规定从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百零二条", "text": "盗窃、侮辱、故意毁坏尸体、尸骨、骨灰的，处三年以下有期徒刑、拘役或者管制。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百零三条", "text": "以营利为目的，聚众赌博或者以赌博为业的，处三年以下有期徒刑、拘役或者管制，并处罚金。 开设赌场的，处五年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处五年以上十年以下有期徒刑，并处罚金。 组织中华人民共和国公民参与国（境）外赌博，数额巨大或者有其他严重情节的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百零四条", "text": "邮政工作人员严重不负责任，故意延误投递邮件，致使公共财产、国家和人民利益遭受重大损失的，处二年以下有期徒刑或者拘役。 第二节 妨害司法罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百零五条", "text": "在刑事诉讼中，证人、鉴定人、记录人、翻译人对与案件有重要关系的情节，故意作虚假证明、鉴定、记录、翻译，意图陷害他人或者隐匿罪证的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百零六条", "text": "在刑事诉讼中，辩护人、诉讼代理人毁灭、伪造证据，帮助当事人毁灭、伪造证据，威胁、引诱证人违背事实改变证言或者作伪证的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。 辩护人、诉讼代理人提供、出示、引用的证人证言或者其他证据失实，不是有意伪造的，不属于伪造证据。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百零七条", "text": "以暴力、威胁、贿买等方法阻止证人作证或者指使他人作伪证的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。 帮助当事人毁灭、伪造证据，情节严重的，处三年以下有期徒刑或者拘役。 司法工作人员犯前两款罪的，从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百零七条", "text": "之一 以捏造的事实提起民事诉讼，妨害司法秩序或者严重侵害他人合法权益的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。 有第一款行为，非法占有他人财产或者逃避合法债务，又构成其他犯罪的，依照处罚较重的规定定罪从重处罚。 司法工作人员利用职权，与他人共同实施前三款行为的，从重处罚；同时构成其他犯罪的，依照处罚较重的规定定罪从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百零八条", "text": "对证人进行打击报复的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百零八条", "text": "之一 司法工作人员、辩护人、诉讼代理人或者其他诉讼参与人，泄露依法不公开审理的案件中不应当公开的信息，造成信息公开传播或者其他严重后果的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。 有前款行为，泄露国家秘密的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十八条", "text": "的规定定罪处罚。 公开披露、报道第一款规定的案件信息，情节严重的，依照第一款的规定处罚。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百零九条", "text": "有下列扰乱法庭秩序情形之一的，处三年以下有期徒刑、拘役、管制或者罚金： （一）聚众哄闹、冲击法庭的； （二）殴打司法工作人员或者诉讼参与人的； （三）侮辱、诽谤、威胁司法工作人员或者诉讼参与人，不听法庭制止，严重扰乱法庭秩序的； （四）有毁坏法庭设施，抢夺、损毁诉讼文书、证据等扰乱法庭秩序行为，情节严重的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百一十条", "text": "明知是犯罪的人而为其提供隐藏处所、财物，帮助其逃匿或者作假证明包庇的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上十年以下有期徒刑。 犯前款罪，事前通谋的，以共同犯罪论处。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百一十一条", "text": "明知他人有间谍犯罪或者恐怖主义、极端主义犯罪行为，在司法机关向其调查有关情况、收集有关证据时，拒绝提供，情节严重的，处三年以下有期徒刑、拘役或者管制。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百一十二条", "text": "明知是犯罪所得及其产生的收益而予以窝藏、转移、收购、代为销售或者以其他方法掩饰、隐瞒的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百一十三条", "text": "对人民法院的判决、裁定有能力执行而拒不执行，情节严重的，处三年以下有期徒刑、拘役或者罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百一十四条", "text": "隐藏、转移、变卖、故意毁损已被司法机关查封、扣押、冻结的财产，情节严重的，处三年以下有期徒刑、拘役或者罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百一十五条", "text": "依法被关押的罪犯，有下列破坏监管秩序行为之一，情节严重的，处三年以下有期徒刑： （一）殴打监管人员的； （二）组织其他被监管人破坏监管秩序的； （三）聚众闹事，扰乱正常监管秩序的； （四）殴打、体罚或者指使他人殴打、体罚其他被监管人的。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百一十六条", "text": "依法被关押的罪犯、被告人、犯罪嫌疑人脱逃的，处五年以下有期徒刑或者拘役。 劫夺押解途中的罪犯、被告人、犯罪嫌疑人的，处三年以上七年以下有期徒刑；情节严重的，处七年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百一十七条", "text": "组织越狱的首要分子和积极参加的，处五年以上有期徒刑；其他参加的，处五年以下有期徒刑或者拘役。 暴动越狱或者聚众持械劫狱的首要分子和积极参加的，处十年以上有期徒刑或者无期徒刑；情节特别严重的，处死刑；其他参加的，处三年以上十年以下有期徒刑。 第三节 妨害国（边）境管理罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百一十八条", "text": "组织他人偷越国（边）境的，处二年以上七年以下有期徒刑，并处罚金；有下列情形之一的，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产： （一）组织他人偷越国（边）境集团的首要分子； （二）多次组织他人偷越国（边）境或者组织他人偷越国（边）境人数众多的； （三）造成被组织人重伤、死亡的； （四）剥夺或者限制被组织人人身自由的； （五）以暴力、威胁方法抗拒检查的； （六）违法所得数额巨大的； （七）有其他特别严重情节的。 犯前款罪，对被组织人有杀害、伤害、强奸、拐卖等犯罪行为，或者对检查人员有杀害、伤害等犯罪行为的，依照数罪并罚的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百一十九条", "text": "以劳务输出、经贸往来或者其他名义，弄虚作假，骗取护照、签证等出境证件，为组织他人偷越国（边）境使用的，处三年以下有期徒刑，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百二十条", "text": "为他人提供伪造、变造的护照、签证等出入境证件，或者出售护照、签证等出入境证件的，处五年以下有期徒刑，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百二十一条", "text": "运送他人偷越国（边）境的，处五年以下有期徒刑、拘役或者管制，并处罚金；有下列情形之一的，处五年以上十年以下有期徒刑，并处罚金： （一）多次实施运送行为或者运送人数众多的； （二）所使用的船只、车辆等交通工具不具备必要的安全条件，足以造成严重后果的； （三）违法所得数额巨大的； （四）有其他特别严重情节的。 在运送他人偷越国（边）境中造成被运送人重伤、死亡，或者以暴力、威胁方法抗拒检查的，处七年以上有期徒刑，并处罚金。 犯前两款罪，对被运送人有杀害、伤害、强奸、拐卖等犯罪行为，或者对检查人员有杀害、伤害等犯罪行为的，依照数罪并罚的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百二十二条", "text": "违反国（边）境管理法规，偷越国（边）境，情节严重的，处一年以下有期徒刑、拘役或者管制，并处罚金；为参加恐怖活动组织、接受恐怖活动培训或者实施恐怖活动，偷越国（边）境的，处一年以上三年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百二十三条", "text": "故意破坏国家边境的界碑、界桩或者永久性测量标志的，处三年以下有期徒刑或者拘役。 第四节 妨害文物管理罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百二十四条", "text": "故意损毁国家保护的珍贵文物或者被确定为全国重点文物保护单位、省级文物保护单位的文物的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。 故意损毁国家保护的名胜古迹，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处罚金。 过失损毁国家保护的珍贵文物或者被确定为全国重点文物保护单位、省级文物保护单位的文物，造成严重后果的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百二十五条", "text": "违反文物保护法规，将收藏的国家禁止出口的珍贵文物私自出售或者私自赠送给外国人的，处五年以下有期徒刑或者拘役，可以并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百二十六条", "text": "以牟利为目的，倒卖国家禁止经营的文物，情节严重的，处五年以下有期徒刑或者拘役，并处罚金；情节特别严重的，处五年以上十年以下有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百二十七条", "text": "违反文物保护法规，国有博物馆、图书馆等单位将国家保护的文物藏品出售或者私自送给非国有单位或者个人的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百二十八条", "text": "盗掘具有历史、艺术、科学价值的古文化遗址、古墓葬的，处三年以上十年以下有期徒刑，并处罚金；情节较轻的，处三年以下有期徒刑、拘役或者管制，并处罚金；有下列情形之一的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产： （一）盗掘确定为全国重点文物保护单位和省级文物保护单位的古文化遗址、古墓葬的； （二）盗掘古文化遗址、古墓葬集团的首要分子； （三）多次盗掘古文化遗址、古墓葬的； （四）盗掘古文化遗址、古墓葬，并盗窃珍贵文物或者造成珍贵文物严重破坏的。 盗掘国家保护的具有科学价值的古人类化石和古脊椎动物化石的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百二十九条", "text": "抢夺、窃取国家所有的档案的，处五年以下有期徒刑或者拘役。 违反档案法的规定，擅自出卖、转让国家所有的档案，情节严重的，处三年以下有期徒刑或者拘役。 有前两款行为，同时又构成本法规定的其他犯罪的，依照处罚较重的规定定罪处罚。 第五节 危害公共卫生罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百三十条", "text": "违反传染病防治法的规定，有下列情形之一，引起甲类传染病以及依法确定采取甲类传染病预防、控制措施的传染病传播或者有传播严重危险的，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑： （一）供水单位供应的饮用水不符合国家规定的卫生标准的； （二）拒绝按照疾病预防控制机构提出的卫生要求，对传染病病原体污染的污水、污物、场所和物品进行消毒处理的； （三）准许或者纵容传染病病人、病原携带者和疑似传染病病人从事国务院卫生行政部门规定禁止从事的易使该传染病扩散的工作的； （四）出售、运输疫区中被传染病病原体污染或者可能被传染病病原体污染的物品，未进行消毒处理的； （五）拒绝执行县级以上人民政府、疾病预防控制机构依照传染病防治法提出的预防、控制措施的。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。 甲类传染病的范围，依照《中华人民共和国传染病防治法》和国务院有关规定确定。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百三十一条", "text": "从事实验、保藏、携带、运输传染病菌种、毒种的人员，违反国务院卫生行政部门的有关规定，造成传染病菌种、毒种扩散，后果严重的，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百三十二条", "text": "违反国境卫生检疫规定，引起检疫传染病传播或者有传播严重危险的，处三年以下有期徒刑或者拘役，并处或者单处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百三十三条", "text": "非法组织他人出卖血液的，处五年以下有期徒刑，并处罚金；以暴力、威胁方法强迫他人出卖血液的，处五年以上十年以下有期徒刑，并处罚金。 有前款行为，对他人造成伤害的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第二百三十四条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百三十四条", "text": "非法采集、供应血液或者制作、供应血液制品，不符合国家规定的标准，足以危害人体健康的，处五年以下有期徒刑或者拘役，并处罚金；对人体健康造成严重危害的，处五年以上十年以下有期徒刑，并处罚金；造成特别严重后果的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。 经国家主管部门批准采集、供应血液或者制作、供应血液制品的部门，不依照规定进行检测或者违背其他操作规定，造成危害他人身体健康后果的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百三十四条", "text": "之一 违反国家有关规定，非法采集我国人类遗传资源或者非法运送、邮寄、携带我国人类遗传资源材料出境，危害公众健康或者社会公共利益，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百三十五条", "text": "医务人员由于严重不负责任，造成就诊人死亡或者严重损害就诊人身体健康的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百三十六条", "text": "未取得医生执业资格的人非法行医，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；严重损害就诊人身体健康的，处三年以上十年以下有期徒刑，并处罚金；造成就诊人死亡的，处十年以上有期徒刑，并处罚金。 未取得医生执业资格的人擅自为他人进行节育复通手术、假节育手术、终止妊娠手术或者摘取宫内节育器，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；严重损害就诊人身体健康的，处三年以上十年以下有期徒刑，并处罚金；造成就诊人死亡的，处十年以上有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百三十六条", "text": "之一 将基因编辑、克隆的人类胚胎植入人体或者动物体内，或者将基因编辑、克隆的动物胚胎植入人体内，情节严重的，处三年以下有期徒刑或者拘役，并处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百三十七条", "text": "违反有关动植物防疫、检疫的国家规定，引起重大动植物疫情的，或者有引起重大动植物疫情危险，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。 第六节 破坏环境资源保护罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百三十八条", "text": "违反国家规定，排放、倾倒或者处置有放射性的废物、含传染病病原体的废物、有毒物质或者其他有害物质，严重污染环境的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金；有下列情形之一的，处七年以上有期徒刑，并处罚金： （一）在饮用水水源保护区、自然保护地核心保护区等依法确定的重点保护区域排放、倾倒、处置有放射性的废物、含传染病病原体的废物、有毒物质，情节特别严重的； （二）向国家确定的重要江河、湖泊水域排放、倾倒、处置有放射性的废物、含传染病病原体的废物、有毒物质，情节特别严重的； （三）致使大量永久基本农田基本功能丧失或者遭受永久性破坏的； （四）致使多人重伤、严重疾病，或者致人严重残疾、死亡的。 有前款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百三十九条", "text": "违反国家规定，将境外的固体废物进境倾倒、堆放、处置的，处五年以下有期徒刑或者拘役，并处罚金；造成重大环境污染事故，致使公私财产遭受重大损失或者严重危害人体健康的，处五年以上十年以下有期徒刑，并处罚金；后果特别严重的，处十年以上有期徒刑，并处罚金。 未经国务院有关主管部门许可，擅自进口固体废物用作原料，造成重大环境污染事故，致使公私财产遭受重大损失或者严重危害人体健康的，处五年以下有期徒刑或者拘役，并处罚金；后果特别严重的，处五年以上十年以下有期徒刑，并处罚金。 以原料利用为名，进口不能用作原料的固体废物、液态废物和气态废物的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第一百五十二条", "text": "第二款、第三款的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十条", "text": "违反保护水产资源法规，在禁渔区、禁渔期或者使用禁用的工具、方法捕捞水产品，情节严重的，处三年以下有期徒刑、拘役、管制或者罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十一条", "text": "非法猎捕、杀害国家重点保护的珍贵、濒危野生动物的，或者非法收购、运输、出售国家重点保护的珍贵、濒危野生动物及其制品的，处五年以下有期徒刑或者拘役，并处罚金；情节严重的，处五年以上十年以下有期徒刑，并处罚金；情节特别严重的，处十年以上有期徒刑，并处罚金或者没收财产。 违反狩猎法规，在禁猎区、禁猎期或者使用禁用的工具、方法进行狩猎，破坏野生动物资源，情节严重的，处三年以下有期徒刑、拘役、管制或者罚金。 违反野生动物保护管理法规，以食用为目的非法猎捕、收购、运输、出售第一款规定以外的在野外环境自然生长繁殖的陆生野生动物，情节严重的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十二条", "text": "违反土地管理法规，非法占用耕地、林地等农用地，改变被占用土地用途，数量较大，造成耕地、林地等农用地大量毁坏的，处五年以下有期徒刑或者拘役，并处或者单处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十二条", "text": "之一 违反自然保护地管理法规，在国家公园、国家级自然保护区进行开垦、开发活动或者修建建筑物，造成严重后果或者有其他恶劣情节的，处五年以下有期徒刑或者拘役，并处或者单处罚金。 有前款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十三条", "text": "违反矿产资源法的规定，未取得采矿许可证擅自采矿，擅自进入国家规划矿区、对国民经济具有重要价值的矿区和他人矿区范围采矿，或者擅自开采国家规定实行保护性开采的特定矿种，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。 违反矿产资源法的规定，采取破坏性的开采方法开采矿产资源，造成矿产资源严重破坏的，处五年以下有期徒刑或者拘役，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十四条", "text": "违反国家规定，非法采伐、毁坏珍贵树木或者国家重点保护的其他植物的，或者非法收购、运输、加工、出售珍贵树木或者国家重点保护的其他植物及其制品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十四条", "text": "之一 违反国家规定，非法引进、释放或者丢弃外来入侵物种，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十五条", "text": "盗伐森林或者其他林木，数量较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数量巨大的，处三年以上七年以下有期徒刑，并处罚金；数量特别巨大的，处七年以上有期徒刑，并处罚金。 违反森林法的规定，滥伐森林或者其他林木，数量较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数量巨大的，处三年以上七年以下有期徒刑，并处罚金。 非法收购、运输明知是盗伐、滥伐的林木，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。 盗伐、滥伐国家级自然保护区内的森林或者其他林木的，从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十五条", "text": "规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本节各该条的规定处罚。 第七节 走私、贩卖、运输、制造毒品罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十七条", "text": "走私、贩卖、运输、制造毒品，无论数量多少，都应当追究刑事责任，予以刑事处罚。 走私、贩卖、运输、制造毒品，有下列情形之一的，处十五年有期徒刑、无期徒刑或者死刑，并处没收财产： （一）走私、贩卖、运输、制造鸦片一千克以上、海洛因或者甲基苯丙胺五十克以上或者其他毒品数量大的； （二）走私、贩卖、运输、制造毒品集团的首要分子； （三）武装掩护走私、贩卖、运输、制造毒品的； （四）以暴力抗拒检查、拘留、逮捕，情节严重的； （五）参与有组织的国际贩毒活动的。 走私、贩卖、运输、制造鸦片二百克以上不满一千克、海洛因或者甲基苯丙胺十克以上不满五十克或者其他毒品数量较大的，处七年以上有期徒刑，并处罚金。 走私、贩卖、运输、制造鸦片不满二百克、海洛因或者甲基苯丙胺不满十克或者其他少量毒品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。 单位犯第二款、第三款、第四款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该款的规定处罚。 利用、教唆未成年人走私、贩卖、运输、制造毒品，或者向未成年人出售毒品的，从重处罚。 对多次走私、贩卖、运输、制造毒品，未经处理的，毒品数量累计计算。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十八条", "text": "非法持有鸦片一千克以上、海洛因或者甲基苯丙胺五十克以上或者其他毒品数量大的，处七年以上有期徒刑或者无期徒刑，并处罚金；非法持有鸦片二百克以上不满一千克、海洛因或者甲基苯丙胺十克以上不满五十克或者其他毒品数量较大的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十九条", "text": "包庇走私、贩卖、运输、制造毒品的犯罪分子的，为犯罪分子窝藏、转移、隐瞒毒品或者犯罪所得的财物的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上十年以下有期徒刑。 缉毒人员或者其他国家机关工作人员掩护、包庇走私、贩卖、运输、制造毒品的犯罪分子的，依照前款的规定从重处罚。 犯前两款罪，事先通谋的，以走私、贩卖、运输、制造毒品罪的共犯论处。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百五十条", "text": "违反国家规定，非法生产、买卖、运输醋酸酐、乙醚、三氯甲烷或者其他用于制造毒品的原料、配剂，或者携带上述物品进出境，情节较重的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金；情节特别严重的，处七年以上有期徒刑，并处罚金或者没收财产。 明知他人制造毒品而为其生产、买卖、运输前款规定的物品的，以制造毒品罪的共犯论处。 单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前两款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百五十一条", "text": "非法种植罂粟、大麻等毒品原植物的，一律强制铲除。有下列情形之一的，处五年以下有期徒刑、拘役或者管制，并处罚金： （一）种植罂粟五百株以上不满三千株或者其他毒品原植物数量较大的； （二）经公安机关处理后又种植的； （三）抗拒铲除的。 非法种植罂粟三千株以上或者其他毒品原植物数量大的，处五年以上有期徒刑，并处罚金或者没收财产。 非法种植罂粟或者其他毒品原植物，在收获前自动铲除的，可以免除处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百五十二条", "text": "非法买卖、运输、携带、持有未经灭活的罂粟等毒品原植物种子或者幼苗，数量较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百五十三条", "text": "引诱、教唆、欺骗他人吸食、注射毒品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。 强迫他人吸食、注射毒品的，处三年以上十年以下有期徒刑，并处罚金。 引诱、教唆、欺骗或者强迫未成年人吸食、注射毒品的，从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百五十四条", "text": "容留他人吸食、注射毒品的，处三年以下有期徒刑、拘役或者管制，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百五十五条", "text": "依法从事生产、运输、管理、使用国家管制的麻醉药品、精神药品的人员，违反国家规定，向吸食、注射毒品的人提供国家规定管制的能够使人形成瘾癖的麻醉药品、精神药品的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。向走私、贩卖毒品的犯罪分子或者以牟利为目的，向吸食、注射毒品的人提供国家规定管制的能够使人形成瘾癖的麻醉药品、精神药品的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百四十七条", "text": "的规定定罪处罚。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百五十五条", "text": "之一 引诱、教唆、欺骗运动员使用兴奋剂参加国内、国际重大体育竞赛，或者明知运动员参加上述竞赛而向其提供兴奋剂，情节严重的，处三年以下有期徒刑或者拘役，并处罚金。 组织、强迫运动员使用兴奋剂参加国内、国际重大体育竞赛的，依照前款的规定从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百五十六条", "text": "因走私、贩卖、运输、制造、非法持有毒品罪被判过刑，又犯本节规定之罪的，从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百五十七条", "text": "本法所称的毒品，是指鸦片、海洛因、甲基苯丙胺（冰毒）、吗啡、大麻、可卡因以及国家规定管制的其他能够使人形成瘾癖的麻醉药品和精神药品。 毒品的数量以查证属实的走私、贩卖、运输、制造、非法持有毒品的数量计算，不以纯度折算。 第八节 组织、强迫、引诱、容留、介绍卖淫罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百五十八条", "text": "组织、强迫他人卖淫的，处五年以上十年以下有期徒刑，并处罚金；情节严重的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。 组织、强迫未成年人卖淫的，依照前款的规定从重处罚。 犯前两款罪，并有杀害、伤害、强奸、绑架等犯罪行为的，依照数罪并罚的规定处罚。 为组织卖淫的人招募、运送人员或者有其他协助组织他人卖淫行为的，处五年以下有期徒刑，并处罚金；情节严重的，处五年以上十年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百五十九条", "text": "引诱、容留、介绍他人卖淫的，处五年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金。 引诱不满十四周岁的幼女卖淫的，处五年以上有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百六十条", "text": "明知自己患有梅毒、淋病等严重性病卖淫、嫖娼的，处五年以下有期徒刑、拘役或者管制，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百六十一条", "text": "旅馆业、饮食服务业、文化娱乐业、出租汽车业等单位的人员，利用本单位的条件，组织、强迫、引诱、容留、介绍他人卖淫的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百五十九条", "text": "的规定定罪处罚。 前款所列单位的主要负责人，犯前款罪的，从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百六十二条", "text": "旅馆业、饮食服务业、文化娱乐业、出租汽车业等单位的人员，在公安机关查处卖淫、嫖娼活动时，为违法犯罪分子通风报信，情节严重的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百一十条", "text": "的规定定罪处罚。 第九节 制作、贩卖、传播淫秽物品罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百六十三条", "text": "以牟利为目的，制作、复制、出版、贩卖、传播淫秽物品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金；情节特别严重的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。 为他人提供书号，出版淫秽书刊的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；明知他人用于出版淫秽书刊而提供书号的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百六十四条", "text": "传播淫秽的书刊、影片、音像、图片或者其他淫秽物品，情节严重的，处二年以下有期徒刑、拘役或者管制。 组织播放淫秽的电影、录像等音像制品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。 制作、复制淫秽的电影、录像等音像制品组织播放的，依照第二款的规定从重处罚。 向不满十八周岁的未成年人传播淫秽物品的，从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百六十五条", "text": "组织进行淫秽表演的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百六十五条", "text": "规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该条的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百六十七条", "text": "本法所称淫秽物品，是指具体描绘性行为或者露骨宣扬色情的诲淫性的书刊、影片、录像带、录音带、图片及其他淫秽物品。 有关人体生理、医学知识的科学著作不是淫秽物品。 包含有色情内容的有艺术价值的文学、艺术作品不视为淫秽物品。 第七章 危害国防利益罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百六十八条", "text": "以暴力、威胁方法阻碍军人依法执行职务的，处三年以下有期徒刑、拘役、管制或者罚金。 故意阻碍武装部队军事行动，造成严重后果的，处五年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百六十九条", "text": "破坏武器装备、军事设施、军事通信的，处三年以下有期徒刑、拘役或者管制；破坏重要武器装备、军事设施、军事通信的，处三年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑、无期徒刑或者死刑。 过失犯前款罪，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。 战时犯前两款罪的，从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百七十条", "text": "明知是不合格的武器装备、军事设施而提供给武装部队的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑、无期徒刑或者死刑。 过失犯前款罪，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。 单位犯第一款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百七十一条", "text": "聚众冲击军事禁区，严重扰乱军事禁区秩序的，对首要分子，处五年以上十年以下有期徒刑；对其他积极参加的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。 聚众扰乱军事管理区秩序，情节严重，致使军事管理区工作无法进行，造成严重损失的，对首要分子，处三年以上七年以下有期徒刑；对其他积极参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百七十二条", "text": "冒充军人招摇撞骗的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百七十三条", "text": "煽动军人逃离部队或者明知是逃离部队的军人而雇用，情节严重的，处三年以下有期徒刑、拘役或者管制。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百七十四条", "text": "在征兵工作中徇私舞弊，接送不合格兵员，情节严重的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百七十五条", "text": "伪造、变造、买卖或者盗窃、抢夺武装部队公文、证件、印章的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上十年以下有期徒刑。 非法生产、买卖武装部队制式服装，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。 伪造、盗窃、买卖或者非法提供、使用武装部队车辆号牌等专用标志，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。 单位犯第二款、第三款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百七十六条", "text": "预备役人员战时拒绝、逃避征召或者军事训练，情节严重的，处三年以下有期徒刑或者拘役。 公民战时拒绝、逃避服役，情节严重的，处二年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百七十七条", "text": "战时故意向武装部队提供虚假敌情，造成严重后果的，处三年以上十年以下有期徒刑；造成特别严重后果的，处十年以上有期徒刑或者无期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百七十八条", "text": "战时造谣惑众，扰乱军心的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百七十九条", "text": "战时明知是逃离部队的军人而为其提供隐蔽处所、财物，情节严重的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十条", "text": "战时拒绝或者故意延误军事订货，情节严重的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役；造成严重后果的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十一条", "text": "战时拒绝军事征收、征用，情节严重的，处三年以下有期徒刑或者拘役。 第八章 贪污贿赂罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十二条", "text": "国家工作人员利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有公共财物的，是贪污罪。 受国家机关、国有公司、企业、事业单位、人民团体委托管理、经营国有财产的人员，利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有国有财物的，以贪污论。 与前两款所列人员勾结，伙同贪污的，以共犯论处。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十三条", "text": "对犯贪污罪的，根据情节轻重，分别依照下列规定处罚： （一）贪污数额较大或者有其他较重情节的，处三年以下有期徒刑或者拘役，并处罚金。 （二）贪污数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金或者没收财产。 （三）贪污数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；数额特别巨大，并使国家和人民利益遭受特别重大损失的，处无期徒刑或者死刑，并处没收财产。 对多次贪污未经处理的，按照累计贪污数额处罚。 犯第一款罪，在提起公诉前如实供述自己罪行、真诚悔罪、积极退赃，避免、减少损害结果的发生，有第一项规定情形的，可以从轻、减轻或者免除处罚；有第二项、第三项规定情形的，可以从轻处罚。 犯第一款罪，有第三项规定情形被判处死刑缓期执行的，人民法院根据犯罪情节等情况可以同时决定在其死刑缓期执行二年期满依法减为无期徒刑后，终身监禁，不得减刑、假释。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十四条", "text": "国家工作人员利用职务上的便利，挪用公款归个人使用，进行非法活动的，或者挪用公款数额较大、进行营利活动的，或者挪用公款数额较大、超过三个月未还的，是挪用公款罪，处五年以下有期徒刑或者拘役；情节严重的，处五年以上有期徒刑。挪用公款数额巨大不退还的，处十年以上有期徒刑或者无期徒刑。 挪用用于救灾、抢险、防汛、优抚、扶贫、移民、救济款物归个人使用的，从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十五条", "text": "国家工作人员利用职务上的便利，索取他人财物的，或者非法收受他人财物，为他人谋取利益的，是受贿罪。 国家工作人员在经济往来中，违反国家规定，收受各种名义的回扣、手续费，归个人所有的，以受贿论处。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十六条", "text": "对犯受贿罪的，根据受贿所得数额及情节，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十三条", "text": "的规定处罚。索贿的从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十七条", "text": "国家机关、国有公司、企业、事业单位、人民团体，索取、非法收受他人财物，为他人谋取利益，情节严重的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。 前款所列单位，在经济往来中，在帐外暗中收受各种名义的回扣、手续费的，以受贿论，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十八条", "text": "国家工作人员利用本人职权或者地位形成的便利条件，通过其他国家工作人员职务上的行为，为请托人谋取不正当利益，索取请托人财物或者收受请托人财物的，以受贿论处。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十八条", "text": "之一 国家工作人员的近亲属或者其他与该国家工作人员关系密切的人，通过该国家工作人员职务上的行为，或者利用该国家工作人员职权或者地位形成的便利条件，通过其他国家工作人员职务上的行为，为请托人谋取不正当利益，索取请托人财物或者收受请托人财物，数额较大或者有其他较重情节的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大或者有其他严重情节的，处三年以上七年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处七年以上有期徒刑，并处罚金或者没收财产。 离职的国家工作人员或者其近亲属以及其他与其关系密切的人，利用该离职的国家工作人员原职权或者地位形成的便利条件实施前款行为的，依照前款的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十九条", "text": "为谋取不正当利益，给予国家工作人员以财物的，是行贿罪。 在经济往来中，违反国家规定，给予国家工作人员以财物，数额较大的，或者违反国家规定，给予国家工作人员以各种名义的回扣、手续费的，以行贿论处。 因被勒索给予国家工作人员以财物，没有获得不正当利益的，不是行贿。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十条", "text": "对犯行贿罪的，处五年以下有期徒刑或者拘役，并处罚金；因行贿谋取不正当利益，情节严重的，或者使国家利益遭受重大损失的，处五年以上十年以下有期徒刑，并处罚金；情节特别严重的，或者使国家利益遭受特别重大损失的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。 行贿人在被追诉前主动交待行贿行为的，可以从轻或者减轻处罚。其中，犯罪较轻的，对侦破重大案件起关键作用的，或者有重大立功表现的，可以减轻或者免除处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十条", "text": "之一 为谋取不正当利益，向国家工作人员的近亲属或者其他与该国家工作人员关系密切的人，或者向离职的国家工作人员或者其近亲属以及其他与其关系密切的人行贿的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，或者使国家利益遭受重大损失的，处三年以上七年以下有期徒刑，并处罚金；情节特别严重的，或者使国家利益遭受特别重大损失的，处七年以上十年以下有期徒刑，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役，并处罚金。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十一条", "text": "为谋取不正当利益，给予国家机关、国有公司、企业、事业单位、人民团体以财物的，或者在经济往来中，违反国家规定，给予各种名义的回扣、手续费的，处三年以下有期徒刑或者拘役，并处罚金。 单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十二条", "text": "向国家工作人员介绍贿赂，情节严重的，处三年以下有期徒刑或者拘役，并处罚金。 介绍贿赂人在被追诉前主动交待介绍贿赂行为的，可以减轻处罚或者免除处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十三条", "text": "单位为谋取不正当利益而行贿，或者违反国家规定，给予国家工作人员以回扣、手续费，情节严重的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，并处罚金。因行贿取得的违法所得归个人所有的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十四条", "text": "国家工作人员在国内公务活动或者对外交往中接受礼物，依照国家规定应当交公而不交公，数额较大的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十三条", "text": "的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十五条", "text": "国家工作人员的财产、支出明显超过合法收入，差额巨大的，可以责令该国家工作人员说明来源，不能说明来源的，差额部分以非法所得论，处五年以下有期徒刑或者拘役；差额特别巨大的，处五年以上十年以下有期徒刑。财产的差额部分予以追缴。 国家工作人员在境外的存款，应当依照国家规定申报。数额较大、隐瞒不报的，处二年以下有期徒刑或者拘役；情节较轻的，由其所在单位或者上级主管机关酌情给予行政处分。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十六条", "text": "国家机关、国有公司、企业、事业单位、人民团体，违反国家规定，以单位名义将国有资产集体私分给个人，数额较大的，对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役，并处或者单处罚金；数额巨大的，处三年以上七年以下有期徒刑，并处罚金。 司法机关、行政执法机关违反国家规定，将应当上缴国家的罚没财物，以单位名义集体私分给个人的，依照前款的规定处罚。 第九章 渎职罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十七条", "text": "国家机关工作人员滥用职权或者玩忽职守，致使公共财产、国家和人民利益遭受重大损失的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。本法另有规定的，依照规定。 国家机关工作人员徇私舞弊，犯前款罪的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上十年以下有期徒刑。本法另有规定的，依照规定。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十八条", "text": "国家机关工作人员违反保守国家秘密法的规定，故意或者过失泄露国家秘密，情节严重的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。 非国家机关工作人员犯前款罪的，依照前款的规定酌情处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十九条", "text": "司法工作人员徇私枉法、徇情枉法，对明知是无罪的人而使他受追诉、对明知是有罪的人而故意包庇不使他受追诉，或者在刑事审判活动中故意违背事实和法律作枉法裁判的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑。 在民事、行政审判活动中故意违背事实和法律作枉法裁判，情节严重的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上十年以下有期徒刑。 在执行判决、裁定活动中，严重不负责任或者滥用职权，不依法采取诉讼保全措施、不履行法定执行职责，或者违法采取诉讼保全措施、强制执行措施，致使当事人或者其他人的利益遭受重大损失的，处五年以下有期徒刑或者拘役；致使当事人或者其他人的利益遭受特别重大损失的，处五年以上十年以下有期徒刑。 司法工作人员收受贿赂，有前三款行为的，同时又构成本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百八十五条", "text": "规定之罪的，依照处罚较重的规定定罪处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第三百九十九条", "text": "之一 依法承担仲裁职责的人员，在仲裁活动中故意违背事实和法律作枉法裁决，情节严重的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百条", "text": "司法工作人员私放在押的犯罪嫌疑人、被告人或者罪犯的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑。 司法工作人员由于严重不负责任，致使在押的犯罪嫌疑人、被告人或者罪犯脱逃，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百零一条", "text": "司法工作人员徇私舞弊，对不符合减刑、假释、暂予监外执行条件的罪犯，予以减刑、假释或者暂予监外执行的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百零二条", "text": "行政执法人员徇私舞弊，对依法应当移交司法机关追究刑事责任的不移交，情节严重的，处三年以下有期徒刑或者拘役；造成严重后果的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百零三条", "text": "国家有关主管部门的国家机关工作人员，徇私舞弊，滥用职权，对不符合法律规定条件的公司设立、登记申请或者股票、债券发行、上市申请，予以批准或者登记，致使公共财产、国家和人民利益遭受重大损失的，处五年以下有期徒刑或者拘役。 上级部门强令登记机关及其工作人员实施前款行为的，对其直接负责的主管人员，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百零四条", "text": "税务机关的工作人员徇私舞弊，不征或者少征应征税款，致使国家税收遭受重大损失的，处五年以下有期徒刑或者拘役；造成特别重大损失的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百零五条", "text": "税务机关的工作人员违反法律、行政法规的规定，在办理发售发票、抵扣税款、出口退税工作中，徇私舞弊，致使国家利益遭受重大损失的，处五年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处五年以上有期徒刑。 其他国家机关工作人员违反国家规定，在提供出口货物报关单、出口收汇核销单等出口退税凭证的工作中，徇私舞弊，致使国家利益遭受重大损失的，依照前款的规定处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百零六条", "text": "国家机关工作人员在签订、履行合同过程中，因严重不负责任被诈骗，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百零七条", "text": "林业主管部门的工作人员违反森林法的规定，超过批准的年采伐限额发放林木采伐许可证或者违反规定滥发林木采伐许可证，情节严重，致使森林遭受严重破坏的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百零八条", "text": "负有环境保护监督管理职责的国家机关工作人员严重不负责任，导致发生重大环境污染事故，致使公私财产遭受重大损失或者造成人身伤亡的严重后果的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百零八条", "text": "之一 负有食品药品安全监督管理职责的国家机关工作人员，滥用职权或者玩忽职守，有下列情形之一，造成严重后果或者有其他严重情节的，处五年以下有期徒刑或者拘役；造成特别严重后果或者有其他特别严重情节的，处五年以上十年以下有期徒刑： （一）瞒报、谎报食品安全事故、药品安全事件的； （二）对发现的严重食品药品安全违法行为未按规定查处的； （三）在药品和特殊食品审批审评过程中，对不符合条件的申请准予许可的； （四）依法应当移交司法机关追究刑事责任不移交的； （五）有其他滥用职权或者玩忽职守行为的。 徇私舞弊犯前款罪的，从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百零九条", "text": "从事传染病防治的政府卫生行政部门的工作人员严重不负责任，导致传染病传播或者流行，情节严重的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百一十条", "text": "国家机关工作人员徇私舞弊，违反土地管理法规，滥用职权，非法批准征收、征用、占用土地，或者非法低价出让国有土地使用权，情节严重的，处三年以下有期徒刑或者拘役；致使国家或者集体利益遭受特别重大损失的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百一十一条", "text": "海关工作人员徇私舞弊，放纵走私，情节严重的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百一十二条", "text": "国家商检部门、商检机构的工作人员徇私舞弊，伪造检验结果的，处五年以下有期徒刑或者拘役；造成严重后果的，处五年以上十年以下有期徒刑。 前款所列人员严重不负责任，对应当检验的物品不检验，或者延误检验出证、错误出证，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百一十三条", "text": "动植物检疫机关的检疫人员徇私舞弊，伪造检疫结果的，处五年以下有期徒刑或者拘役；造成严重后果的，处五年以上十年以下有期徒刑。 前款所列人员严重不负责任，对应当检疫的检疫物不检疫，或者延误检疫出证、错误出证，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百一十四条", "text": "对生产、销售伪劣商品犯罪行为负有追究责任的国家机关工作人员，徇私舞弊，不履行法律规定的追究职责，情节严重的，处五年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百一十五条", "text": "负责办理护照、签证以及其他出入境证件的国家机关工作人员，对明知是企图偷越国（边）境的人员，予以办理出入境证件的，或者边防、海关等国家机关工作人员，对明知是偷越国（边）境的人员，予以放行的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百一十六条", "text": "对被拐卖、绑架的妇女、儿童负有解救职责的国家机关工作人员，接到被拐卖、绑架的妇女、儿童及其家属的解救要求或者接到其他人的举报，而对被拐卖、绑架的妇女、儿童不进行解救，造成严重后果的，处五年以下有期徒刑或者拘役。 负有解救职责的国家机关工作人员利用职务阻碍解救的，处二年以上七年以下有期徒刑；情节较轻的，处二年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百一十七条", "text": "有查禁犯罪活动职责的国家机关工作人员，向犯罪分子通风报信、提供便利，帮助犯罪分子逃避处罚的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百一十八条", "text": "国家机关工作人员在招收公务员、学生工作中徇私舞弊，情节严重的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百一十九条", "text": "国家机关工作人员严重不负责任，造成珍贵文物损毁或者流失，后果严重的，处三年以下有期徒刑或者拘役。 第十章 军人违反职责罪"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百二十条", "text": "军人违反职责，危害国家军事利益，依照法律应当受刑罚处罚的行为，是军人违反职责罪。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百二十一条", "text": "战时违抗命令，对作战造成危害的，处三年以上十年以下有期徒刑；致使战斗、战役遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百二十二条", "text": "故意隐瞒、谎报军情或者拒传、假传军令，对作战造成危害的，处三年以上十年以下有期徒刑；致使战斗、战役遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百二十三条", "text": "在战场上贪生怕死，自动放下武器投降敌人的，处三年以上十年以下有期徒刑；情节严重的，处十年以上有期徒刑或者无期徒刑。 投降后为敌人效劳的，处十年以上有期徒刑、无期徒刑或者死刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百二十四条", "text": "战时临阵脱逃的，处三年以下有期徒刑；情节严重的，处三年以上十年以下有期徒刑；致使战斗、战役遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百二十五条", "text": "指挥人员和值班、值勤人员擅离职守或者玩忽职守，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。 战时犯前款罪的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百二十六条", "text": "以暴力、威胁方法，阻碍指挥人员或者值班、值勤人员执行职务的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑。战时从重处罚。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百二十七条", "text": "滥用职权，指使部属进行违反职责的活动，造成严重后果的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百二十八条", "text": "指挥人员违抗命令，临阵畏缩，作战消极，造成严重后果的，处五年以下有期徒刑；致使战斗、战役遭受重大损失或者有其他特别严重情节的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百二十九条", "text": "在战场上明知友邻部队处境危急请求救援，能救援而不救援，致使友邻部队遭受重大损失的，对指挥人员，处五年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百三十条", "text": "在履行公务期间，擅离岗位，叛逃境外或者在境外叛逃，危害国家军事利益的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上有期徒刑。 驾驶航空器、舰船叛逃的，或者有其他特别严重情节的，处十年以上有期徒刑、无期徒刑或者死刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百三十一条", "text": "以窃取、刺探、收买方法，非法获取军事秘密的，处五年以下有期徒刑；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑。 为境外的机构、组织、人员窃取、刺探、收买、非法提供军事秘密的，处五年以上十年以下有期徒刑；情节严重的，处十年以上有期徒刑、无期徒刑或者死刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百三十二条", "text": "违反保守国家秘密法规，故意或者过失泄露军事秘密，情节严重的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上十年以下有期徒刑。 战时犯前款罪的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百三十三条", "text": "战时造谣惑众，动摇军心的，处三年以下有期徒刑；情节严重的，处三年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百三十四条", "text": "战时自伤身体，逃避军事义务的，处三年以下有期徒刑；情节严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百三十五条", "text": "违反兵役法规，逃离部队，情节严重的，处三年以下有期徒刑或者拘役。 战时犯前款罪的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百三十六条", "text": "违反武器装备使用规定，情节严重，因而发生责任事故，致人重伤、死亡或者造成其他严重后果的，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百三十七条", "text": "违反武器装备管理规定，擅自改变武器装备的编配用途，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百三十八条", "text": "盗窃、抢夺武器装备或者军用物资的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑、无期徒刑或者死刑。 盗窃、抢夺枪支、弹药、爆炸物的，依照本法"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百三十九条", "text": "非法出卖、转让军队武器装备的，处三年以上十年以下有期徒刑；出卖、转让大量武器装备或者有其他特别严重情节的，处十年以上有期徒刑、无期徒刑或者死刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百四十条", "text": "违抗命令，遗弃武器装备的，处五年以下有期徒刑或者拘役；遗弃重要或者大量武器装备的，或者有其他严重情节的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百四十一条", "text": "遗失武器装备，不及时报告或者有其他严重情节的，处三年以下有期徒刑或者拘役。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百四十二条", "text": "违反规定，擅自出卖、转让军队房地产，情节严重的，对直接责任人员，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百四十三条", "text": "滥用职权，虐待部属，情节恶劣，致人重伤或者造成其他严重后果的，处五年以下有期徒刑或者拘役；致人死亡的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百四十四条", "text": "在战场上故意遗弃伤病军人，情节恶劣的，对直接责任人员，处五年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百四十五条", "text": "战时在救护治疗职位上，有条件救治而拒不救治危重伤病军人的，处五年以下有期徒刑或者拘役；造成伤病军人重残、死亡或者有其他严重情节的，处五年以上十年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百四十六条", "text": "战时在军事行动地区，残害无辜居民或者掠夺无辜居民财物的，处五年以下有期徒刑；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑、无期徒刑或者死刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百四十七条", "text": "私放俘虏的，处五年以下有期徒刑；私放重要俘虏、私放俘虏多人或者有其他严重情节的，处五年以上有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百四十八条", "text": "虐待俘虏，情节恶劣的，处三年以下有期徒刑。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百四十九条", "text": "在战时，对被判处三年以下有期徒刑没有现实危险宣告缓刑的犯罪军人，允许其戴罪立功，确有立功表现时，可以撤销原判刑罚，不以犯罪论处。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百五十条", "text": "本章适用于中国人民解放军的现役军官、文职干部、士兵及具有军籍的学员和中国人民武装警察部队的现役警官、文职干部、士兵及具有军籍的学员以及文职人员、执行军事任务的预备役人员和其他人员。"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百五十一条", "text": "本章所称战时，是指国家宣布进入战争状态、部队受领作战任务或者遭敌突然袭击时。 部队执行戒严任务或者处置突发性暴力事件时，以战时论。 附 则"}, {"law": "中华人民共和国刑法_20201226.docx", "no": "第四百五十二条", "text": "本法自1997年10月1日起施行。 列于本法附件一的全国人民代表大会常务委员会制定的条例、补充规定和决定，已纳入本法或者已不适用，自本法施行之日起，予以废止。 列于本法附件二的全国人民代表大会常务委员会制定的补充规定和决定予以保留。其中，有关行政处罚和行政措施的规定继续有效；有关刑事责任的规定已纳入本法，自本法施行之日起，适用本法规定。 附件一 全国人民代表大会常务委员会制定的下列条例、补充规定和决定，已纳入本法或者已不适用，自本法施行之日起，予以废止： 1.中华人民共和国惩治军人违反职责罪暂行条例 2.关于严惩严重破坏经济的罪犯的决定 3.关于严惩严重危害社会治安的犯罪分子的决定 4.关于惩治走私罪的补充规定 5.关于惩治贪污罪贿赂罪的补充规定 6.关于惩治泄露国家秘密犯罪的补充规定 7.关于惩治捕杀国家重点保护的珍贵、濒危野生动物犯罪的补充规定 8.关于惩治侮辱中华人民共和国国旗国徽罪的决定 9.关于惩治盗掘古文化遗址古墓葬犯罪的补充规定 10.关于惩治劫持航空器犯罪分子的决定 11.关于惩治假冒注册商标犯罪的补充规定 12.关于惩治生产、销售伪劣商品犯罪的决定 13.关于惩治侵犯著作权的犯罪的决定 14.关于惩治违反公司法的犯罪的决定 15.关于处理逃跑或者重新犯罪的劳改犯和劳教人员的决定 附件二 全国人民代表大会常务委员会制定的下列补充规定和决定予以保留，其中，有关行政处罚和行政措施的规定继续有效；有关刑事责任的规定已纳入本法，自本法施行之日起，适用本法规定： 1.关于禁毒的决定 2.关于惩治走私、制作、贩卖、传播淫秽物品的犯罪分子的决定 3.关于严禁卖淫嫖娼的决定 4.关于严惩拐卖、绑架妇女、儿童的犯罪分子的决定 5.关于惩治偷税、抗税犯罪的补充规定 6.关于严惩组织、运送他人偷越国（边）境犯罪的补充规定 7.关于惩治破坏金融秩序犯罪的决定 8.关于惩治虚开、伪造和非法出售增值税专用发票犯罪的决定"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第一条", "text": "为了保护劳动者的合法权益，调整劳动关系，建立和维护适应社会主义市场经济的劳动制度，促进经济发展和社会进步，根据宪法，制定本法。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二条", "text": "在中华人民共和国境内的企业、个体经济组织（以下统称用人单位）和与之形成劳动关系的劳动者，适用本法。 国家机关、事业组织、社会团体和与之建立劳动合同关系的劳动者，依照本法执行。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三条", "text": "劳动者享有平等就业和选择职业的权利、取得劳动报酬的权利、休息休假的权利、获得劳动安全卫生保护的权利、接受职业技能培训的权利、享受社会保险和福利的权利、提请劳动争议处理的权利以及法律规定的其他劳动权利。 劳动者应当完成劳动任务，提高职业技能，执行劳动安全卫生规程，遵守劳动纪律和职业道德。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第四条", "text": "用人单位应当依法建立和完善规章制度，保障劳动者享有劳动权利和履行劳动义务。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第五条", "text": "国家采取各种措施，促进劳动就业，发展职业教育，制定劳动标准，调节社会收入，完善社会保险，协调劳动关系，逐步提高劳动者的生活水平。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第六条", "text": "国家提倡劳动者参加社会义务劳动，开展劳动竞赛和合理化建议活动，鼓励和保护劳动者进行科学研究、技术革新和发明创造，表彰和奖励劳动模范和先进工作者。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第七条", "text": "劳动者有权依法参加和组织工会。 工会代表和维护劳动者的合法权益，依法独立自主地开展活动。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第八条", "text": "劳动者依照法律规定，通过职工大会、职工代表大会或者其他形式，参与民主管理或者就保护劳动者合法权益与用人单位进行平等协商。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第九条", "text": "国务院劳动行政部门主管全国劳动工作。 县级以上地方人民政府劳动行政部门主管本行政区域内的劳动工作。 第二章 促进就业"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第十条", "text": "国家通过促进经济和社会发展，创造就业条件，扩大就业机会。 国家鼓励企业、事业组织、社会团体在法律、行政法规规定的范围内兴办产业或者拓展经营，增加就业。 国家支持劳动者自愿组织起来就业和从事个体经营实现就业。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第十一条", "text": "地方各级人民政府应当采取措施，发展多种类型的职业介绍机构，提供就业服务。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第十二条", "text": "劳动者就业，不因民族、种族、性别、宗教信仰不同而受歧视。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第十三条", "text": "妇女享有与男子平等的就业权利。在录用职工时，除国家规定的不适合妇女的工种或者岗位外，不得以性别为由拒绝录用妇女或者提高对妇女的录用标准。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第十四条", "text": "残疾人、少数民族人员、退出现役的军人的就业，法律、法规有特别规定的，从其规定。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第十五条", "text": "禁止用人单位招用未满十六周岁的未成年人。 文艺、体育和特种工艺单位招用未满十六周岁的未成年人，必须遵守国家有关规定，并保障其接受义务教育的权利。 第三章 劳动合同和集体合同"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第十六条", "text": "劳动合同是劳动者与用人单位确立劳动关系、明确双方权利和义务的协议。 建立劳动关系应当订立劳动合同。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第十七条", "text": "订立和变更劳动合同，应当遵循平等自愿、协商一致的原则，不得违反法律、行政法规的规定。 劳动合同依法订立即具有法律约束力，当事人必须履行劳动合同规定的义务。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第十八条", "text": "下列劳动合同无效： （一）违反法律、行政法规的劳动合同； （二）采取欺诈、威胁等手段订立的劳动合同。 无效的劳动合同，从订立的时候起，就没有法律约束力。确认劳动合同部分无效的，如果不影响其余部分的效力，其余部分仍然有效。 劳动合同的无效，由劳动争议仲裁委员会或者人民法院确认。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第十九条", "text": "劳动合同应当以书面形式订立，并具备以下条款： （一）劳动合同期限； （二）工作内容； （三）劳动保护和劳动条件； （四）劳动报酬； （五）劳动纪律； （六）劳动合同终止的条件； （七）违反劳动合同的责任。 劳动合同除前款规定的必备条款外，当事人可以协商约定其他内容。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二十条", "text": "劳动合同的期限分为有固定期限、无固定期限和以完成一定的工作为期限。 劳动者在同一用人单位连续工作满十年以上，当事人双方同意续延劳动合同的，如果劳动者提出订立无固定期限的劳动合同，应当订立无固定期限的劳动合同。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二十一条", "text": "劳动合同可以约定试用期。试用期最长不得超过六个月。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二十二条", "text": "劳动合同当事人可以在劳动合同中约定保守用人单位商业秘密的有关事项。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二十三条", "text": "劳动合同期满或者当事人约定的劳动合同终止条件出现，劳动合同即行终止。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二十四条", "text": "经劳动合同当事人协商一致，劳动合同可以解除。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二十五条", "text": "劳动者有下列情形之一的，用人单位可以解除劳动合同： （一）在试用期间被证明不符合录用条件的； （二）严重违反劳动纪律或者用人单位规章制度的； （三）严重失职，营私舞弊，对用人单位利益造成重大损害的； （四）被依法追究刑事责任的。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二十六条", "text": "有下列情形之一的，用人单位可以解除劳动合同，但是应当提前三十日以书面形式通知劳动者本人： （一）劳动者患病或者非因工负伤，医疗期满后，不能从事原工作也不能从事由用人单位另行安排的工作的； （二）劳动者不能胜任工作，经过培训或者调整工作岗位，仍不能胜任工作的； （三）劳动合同订立时所依据的客观情况发生重大变化，致使原劳动合同无法履行，经当事人协商不能就变更劳动合同达成协议的。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二十七条", "text": "用人单位濒临破产进行法定整顿期间或者生产经营状况发生严重困难，确需裁减人员的，应当提前三十日向工会或者全体职工说明情况，听取工会或者职工的意见，经向劳动行政部门报告后，可以裁减人员。 用人单位依据本条规定裁减人员，在六个月内录用人员的，应当优先录用被裁减的人员。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二十八条", "text": "用人单位依据本法"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二十七条", "text": "的规定解除劳动合同的，应当依照国家有关规定给予经济补偿。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二十九条", "text": "劳动者有下列情形之一的，用人单位不得依据本法"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第二十七条", "text": "的规定解除劳动合同： （一）患职业病或者因工负伤并被确认丧失或者部分丧失劳动能力的； （二）患病或者负伤，在规定的医疗期内的； （三）女职工在孕期、产期、哺乳期内的； （四）法律、行政法规规定的其他情形。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三十条", "text": "用人单位解除劳动合同，工会认为不适当的，有权提出意见。如果用人单位违反法律、法规或者劳动合同，工会有权要求重新处理；劳动者申请仲裁或者提起诉讼的，工会应当依法给予支持和帮助。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三十一条", "text": "劳动者解除劳动合同，应当提前三十日以书面形式通知用人单位。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三十二条", "text": "有下列情形之一的，劳动者可以随时通知用人单位解除劳动合同： （一）在试用期内的； （二）用人单位以暴力、威胁或者非法限制人身自由的手段强迫劳动的； （三）用人单位未按照劳动合同约定支付劳动报酬或者提供劳动条件的。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三十三条", "text": "企业职工一方与企业可以就劳动报酬、工作时间、休息休假、劳动安全卫生、保险福利等事项，签订集体合同。集体合同草案应当提交职工代表大会或者全体职工讨论通过。 集体合同由工会代表职工与企业签订；没有建立工会的企业，由职工推举的代表与企业签订。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三十四条", "text": "集体合同签订后应当报送劳动行政部门；劳动行政部门自收到集体合同文本之日起十五日内未提出异议的，集体合同即行生效。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三十五条", "text": "依法签订的集体合同对企业和企业全体职工具有约束力。职工个人与企业订立的劳动合同中劳动条件和劳动报酬等标准不得低于集体合同的规定。 第四章 工作时间和休息休假"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三十六条", "text": "国家实行劳动者每日工作时间不超过八小时、平均每周工作时间不超过四十四小时的工时制度。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三十七条", "text": "对实行计件工作的劳动者，用人单位应当根据本法"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三十六条", "text": "规定的工时制度合理确定其劳动定额和计件报酬标准。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三十八条", "text": "用人单位应当保证劳动者每周至少休息一日。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三十九条", "text": "企业因生产特点不能实行本法"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第三十八条", "text": "规定的，经劳动行政部门批准，可以实行其他工作和休息办法。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第四十条", "text": "用人单位在下列节日期间应当依法安排劳动者休假： （一）元旦； （二）春节； （三）国际劳动节； （四）国庆节； （五）法律、法规规定的其他休假节日。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第四十一条", "text": "用人单位由于生产经营需要，经与工会和劳动者协商后可以延长工作时间，一般每日不得超过一小时；因特殊原因需要延长工作时间的，在保障劳动者身体健康的条件下延长工作时间每日不得超过三小时，但是每月不得超过三十六小时。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第四十二条", "text": "有下列情形之一的，延长工作时间不受本法"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第四十一条", "text": "规定的限制： （一）发生自然灾害、事故或者因其他原因，威胁劳动者生命健康和财产安全，需要紧急处理的； （二）生产设备、交通运输线路、公共设施发生故障，影响生产和公众利益，必须及时抢修的； （三）法律、行政法规规定的其他情形。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第四十三条", "text": "用人单位不得违反本法规定延长劳动者的工作时间。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第四十四条", "text": "有下列情形之一的，用人单位应当按照下列标准支付高于劳动者正常工作时间工资的工资报酬： （一）安排劳动者延长工作时间的，支付不低于工资的百分之一百五十的工资报酬； （二）休息日安排劳动者工作又不能安排补休的，支付不低于工资的百分之二百的工资报酬； （三）法定休假日安排劳动者工作的，支付不低于工资的百分之三百的工资报酬。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第四十五条", "text": "国家实行带薪年休假制度。 劳动者连续工作一年以上的，享受带薪年休假。具体办法由国务院规定。 第五章 工 资"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第四十六条", "text": "工资分配应当遵循按劳分配原则，实行同工同酬。 工资水平在经济发展的基础上逐步提高。国家对工资总量实行宏观调控。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第四十七条", "text": "用人单位根据本单位的生产经营特点和经济效益，依法自主确定本单位的工资分配方式和工资水平。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第四十八条", "text": "国家实行最低工资保障制度。最低工资的具体标准由省、自治区、直辖市人民政府规定，报国务院备案。 用人单位支付劳动者的工资不得低于当地最低工资标准。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第四十九条", "text": "确定和调整最低工资标准应当综合参考下列因素： （一）劳动者本人及平均赡养人口的最低生活费用； （二）社会平均工资水平； （三）劳动生产率； （四）就业状况； （五）地区之间经济发展水平的差异。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第五十条", "text": "工资应当以货币形式按月支付给劳动者本人。不得克扣或者无故拖欠劳动者的工资。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第五十一条", "text": "劳动者在法定休假日和婚丧假期间以及依法参加社会活动期间，用人单位应当依法支付工资。 第六章 劳动安全卫生"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第五十二条", "text": "用人单位必须建立、健全劳动安全卫生制度，严格执行国家劳动安全卫生规程和标准，对劳动者进行劳动安全卫生教育，防止劳动过程中的事故，减少职业危害。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第五十三条", "text": "劳动安全卫生设施必须符合国家规定的标准。 新建、改建、扩建工程的劳动安全卫生设施必须与主体工程同时设计、同时施工、同时投入生产和使用。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第五十四条", "text": "用人单位必须为劳动者提供符合国家规定的劳动安全卫生条件和必要的劳动防护用品，对从事有职业危害作业的劳动者应当定期进行健康检查。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第五十五条", "text": "从事特种作业的劳动者必须经过专门培训并取得特种作业资格。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第五十六条", "text": "劳动者在劳动过程中必须严格遵守安全操作规程。 劳动者对用人单位管理人员违章指挥、强令冒险作业，有权拒绝执行；对危害生命安全和身体健康的行为，有权提出批评、检举和控告。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第五十七条", "text": "国家建立伤亡事故和职业病统计报告和处理制度。县级以上各级人民政府劳动行政部门、有关部门和用人单位应当依法对劳动者在劳动过程中发生的伤亡事故和劳动者的职业病状况，进行统计、报告和处理。 第七章 女职工和未成年工特殊保护"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第五十八条", "text": "国家对女职工和未成年工实行特殊劳动保护。 未成年工是指年满十六周岁未满十八周岁的劳动者。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第五十九条", "text": "禁止安排女职工从事矿山井下、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第六十条", "text": "不得安排女职工在经期从事高处、低温、冷水作业和国家规定的第三级体力劳动强度的劳动。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第六十一条", "text": "不得安排女职工在怀孕期间从事国家规定的第三级体力劳动强度的劳动和孕期禁忌从事的劳动。对怀孕七个月以上的女职工，不得安排其延长工作时间和夜班劳动。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第六十二条", "text": "女职工生育享受不少于九十天的产假。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第六十三条", "text": "不得安排女职工在哺乳未满一周岁的婴儿期间从事国家规定的第三级体力劳动强度的劳动和哺乳期禁忌从事的其他劳动，不得安排其延长工作时间和夜班劳动。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第六十四条", "text": "不得安排未成年工从事矿山井下、有毒有害、国家规定的第四级体力劳动强度的劳动和其他禁忌从事的劳动。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第六十五条", "text": "用人单位应当对未成年工定期进行健康检查。 第八章 职业培训"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第六十六条", "text": "国家通过各种途径，采取各种措施，发展职业培训事业，开发劳动者的职业技能，提高劳动者素质，增强劳动者的就业能力和工作能力。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第六十七条", "text": "各级人民政府应当把发展职业培训纳入社会经济发展的规划，鼓励和支持有条件的企业、事业组织、社会团体和个人进行各种形式的职业培训。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第六十八条", "text": "用人单位应当建立职业培训制度，按照国家规定提取和使用职业培训经费，根据本单位实际，有计划地对劳动者进行职业培训。 从事技术工种的劳动者，上岗前必须经过培训。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第六十九条", "text": "国家确定职业分类，对规定的职业制定职业技能标准，实行职业资格证书制度，由经备案的考核鉴定机构负责对劳动者实施职业技能考核鉴定。 第九章 社会保险和福利"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第七十条", "text": "国家发展社会保险事业，建立社会保险制度，设立社会保险基金，使劳动者在年老、患病、工伤、失业、生育等情况下获得帮助和补偿。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第七十一条", "text": "社会保险水平应当与社会经济发展水平和社会承受能力相适应。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第七十二条", "text": "社会保险基金按照保险类型确定资金来源，逐步实行社会统筹。用人单位和劳动者必须依法参加社会保险，缴纳社会保险费。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第七十三条", "text": "劳动者在下列情形下，依法享受社会保险待遇： （一）退休； （二）患病、负伤； （三）因工伤残或者患职业病； （四）失业； （五）生育。 劳动者死亡后，其遗属依法享受遗属津贴。 劳动者享受社会保险待遇的条件和标准由法律、法规规定。 劳动者享受的社会保险金必须按时足额支付。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第七十四条", "text": "社会保险基金经办机构依照法律规定收支、管理和运营社会保险基金，并负有使社会保险基金保值增值的责任。 社会保险基金监督机构依照法律规定，对社会保险基金的收支、管理和运营实施监督。 社会保险基金经办机构和社会保险基金监督机构的设立和职能由法律规定。 任何组织和个人不得挪用社会保险基金。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第七十五条", "text": "国家鼓励用人单位根据本单位实际情况为劳动者建立补充保险。 国家提倡劳动者个人进行储蓄性保险。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第七十六条", "text": "国家发展社会福利事业，兴建公共福利设施，为劳动者休息、休养和疗养提供条件。 用人单位应当创造条件，改善集体福利，提高劳动者的福利待遇。 第十章 劳动争议"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第七十七条", "text": "用人单位与劳动者发生劳动争议，当事人可以依法申请调解、仲裁、提起诉讼，也可以协商解决。 调解原则适用于仲裁和诉讼程序。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第七十八条", "text": "解决劳动争议，应当根据合法、公正、及时处理的原则，依法维护劳动争议当事人的合法权益。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第七十九条", "text": "劳动争议发生后，当事人可以向本单位劳动争议调解委员会申请调解；调解不成，当事人一方要求仲裁的，可以向劳动争议仲裁委员会申请仲裁。当事人一方也可以直接向劳动争议仲裁委员会申请仲裁。对仲裁裁决不服的，可以向人民法院提起诉讼。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第八十条", "text": "在用人单位内，可以设立劳动争议调解委员会。劳动争议调解委员会由职工代表、用人单位代表和工会代表组成。劳动争议调解委员会主任由工会代表担任。 劳动争议经调解达成协议的，当事人应当履行。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第八十一条", "text": "劳动争议仲裁委员会由劳动行政部门代表、同级工会代表、用人单位方面的代表组成。劳动争议仲裁委员会主任由劳动行政部门代表担任。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第八十二条", "text": "提出仲裁要求的一方应当自劳动争议发生之日起六十日内向劳动争议仲裁委员会提出书面申请。仲裁裁决一般应在收到仲裁申请的六十日内作出。对仲裁裁决无异议的，当事人必须履行。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第八十三条", "text": "劳动争议当事人对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。一方当事人在法定期限内不起诉又不履行仲裁裁决的，另一方当事人可以申请人民法院强制执行。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第八十四条", "text": "因签订集体合同发生争议，当事人协商解决不成的，当地人民政府劳动行政部门可以组织有关各方协调处理。 因履行集体合同发生争议，当事人协商解决不成的，可以向劳动争议仲裁委员会申请仲裁；对仲裁裁决不服的，可以自收到仲裁裁决书之日起十五日内向人民法院提起诉讼。 第十一章 监督检查"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第八十五条", "text": "县级以上各级人民政府劳动行政部门依法对用人单位遵守劳动法律、法规的情况进行监督检查，对违反劳动法律、法规的行为有权制止，并责令改正。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第八十六条", "text": "县级以上各级人民政府劳动行政部门监督检查人员执行公务，有权进入用人单位了解执行劳动法律、法规的情况，查阅必要的资料，并对劳动场所进行检查。 县级以上各级人民政府劳动行政部门监督检查人员执行公务，必须出示证件，秉公执法并遵守有关规定。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第八十七条", "text": "县级以上各级人民政府有关部门在各自职责范围内，对用人单位遵守劳动法律、法规的情况进行监督。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第八十八条", "text": "各级工会依法维护劳动者的合法权益，对用人单位遵守劳动法律、法规的情况进行监督。 任何组织和个人对于违反劳动法律、法规的行为有权检举和控告。 第十二章 法律责任"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第八十九条", "text": "用人单位制定的劳动规章制度违反法律、法规规定的，由劳动行政部门给予警告，责令改正；对劳动者造成损害的，应当承担赔偿责任。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第九十条", "text": "用人单位违反本法规定，延长劳动者工作时间的，由劳动行政部门给予警告，责令改正，并可以处以罚款。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第九十一条", "text": "用人单位有下列侵害劳动者合法权益情形之一的，由劳动行政部门责令支付劳动者的工资报酬、经济补偿，并可以责令支付赔偿金： （一）克扣或者无故拖欠劳动者工资的； （二）拒不支付劳动者延长工作时间工资报酬的； （三）低于当地最低工资标准支付劳动者工资的； （四）解除劳动合同后，未依照本法规定给予劳动者经济补偿的。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第九十二条", "text": "用人单位的劳动安全设施和劳动卫生条件不符合国家规定或者未向劳动者提供必要的劳动防护用品和劳动保护设施的，由劳动行政部门或者有关部门责令改正，可以处以罚款；情节严重的，提请县级以上人民政府决定责令停产整顿；对事故隐患不采取措施，致使发生重大事故，造成劳动者生命和财产损失的，对责任人员依照刑法有关规定追究刑事责任。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第九十三条", "text": "用人单位强令劳动者违章冒险作业，发生重大伤亡事故，造成严重后果的，对责任人员依法追究刑事责任。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第九十四条", "text": "用人单位非法招用未满十六周岁的未成年人的，由劳动行政部门责令改正，处以罚款；情节严重的，由市场监督管理部门吊销营业执照。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第九十五条", "text": "用人单位违反本法对女职工和未成年工的保护规定，侵害其合法权益的，由劳动行政部门责令改正，处以罚款；对女职工或者未成年工造成损害的，应当承担赔偿责任。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第九十六条", "text": "用人单位有下列行为之一，由公安机关对责任人员处以十五日以下拘留、罚款或者警告；构成犯罪的，对责任人员依法追究刑事责任： （一）以暴力、威胁或者非法限制人身自由的手段强迫劳动的； （二）侮辱、体罚、殴打、非法搜查和拘禁劳动者的。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第九十七条", "text": "由于用人单位的原因订立的无效合同，对劳动者造成损害的，应当承担赔偿责任。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第九十八条", "text": "用人单位违反本法规定的条件解除劳动合同或者故意拖延不订立劳动合同的，由劳动行政部门责令改正；对劳动者造成损害的，应当承担赔偿责任。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第九十九条", "text": "用人单位招用尚未解除劳动合同的劳动者，对原用人单位造成经济损失的，该用人单位应当依法承担连带赔偿责任。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第一百条", "text": "用人单位无故不缴纳社会保险费的，由劳动行政部门责令其限期缴纳；逾期不缴的，可以加收滞纳金。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第一百零一条", "text": "用人单位无理阻挠劳动行政部门、有关部门及其工作人员行使监督检查权，打击报复举报人员的，由劳动行政部门或者有关部门处以罚款；构成犯罪的，对责任人员依法追究刑事责任。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第一百零二条", "text": "劳动者违反本法规定的条件解除劳动合同或者违反劳动合同中约定的保密事项，对用人单位造成经济损失的，应当依法承担赔偿责任。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第一百零三条", "text": "劳动行政部门或者有关部门的工作人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；不构成犯罪的，给予行政处分。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第一百零四条", "text": "国家工作人员和社会保险基金经办机构的工作人员挪用社会保险基金，构成犯罪的，依法追究刑事责任。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第一百零五条", "text": "违反本法规定侵害劳动者合法权益，其他法律、行政法规已规定处罚的，依照该法律、行政法规的规定处罚。 第十三章 附 则"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第一百零六条", "text": "省、自治区、直辖市人民政府根据本法和本地区的实际情况，规定劳动合同制度的实施步骤，报国务院备案。"}, {"law": "中华人民共和国劳动法_20181229.docx", "no": "第一百零七条", "text": "本法自1995年1月1日起施行。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一条", "text": "为了加强危险化学品的安全管理，预防和减少危险化学品事故，保障人民群众身体健康、生命安全和财产安全，保护生态环境，制定本法。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第二条", "text": "危险化学品生产、储存、使用、经营和运输的安全管理，适用本法。 废弃危险化学品的处置，依照有关生态环境保护的法律、行政法规和国家有关规定执行。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三条", "text": "本法所称危险化学品，是指具有毒害、腐蚀、爆炸、燃烧、助燃等性质，对人体、设施、生态环境具有危害的剧毒化学品和其他化学品。 国家建立健全危险化学品目录管理制度。危险化学品目录，由国务院应急管理部门会同工业和信息化、公安、生态环境、交通运输、农业农村、卫生健康、海关、市场监督管理、铁路、民用航空等部门，根据化学品危险特性的鉴定和分类标准确定、公布，并适时调整。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四条", "text": "危险化学品安全管理工作坚持中国共产党的领导。 危险化学品安全管理工作应当坚持人民至上、生命至上，贯彻总体国家安全观，统筹发展和安全，坚持安全第一、预防为主、综合治理的方针，从源头上防范化解重大安全风险。 危险化学品安全管理工作实行管行业必须管安全、管业务必须管安全、管生产经营必须管安全，强化和落实单位主体责任与政府监管责任，建立单位负责、职工参与、政府监管、行业自律、社会监督的机制。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五条", "text": "生产、储存、使用、经营、运输危险化学品的企业、学校、科研机构、医疗机构、检测机构、检验机构等单位（以下统称危险化学品单位）应当实行全员安全生产责任制，构建安全风险分级管控和隐患排查治理双重预防机制，加强安全生产标准化、信息化建设，其主要负责人对本单位的危险化学品安全生产工作全面负责。 危险化学品单位应当具备法律、行政法规规定和国家标准、行业标准要求的安全条件，建立健全安全管理规章制度和岗位安全责任制度，对从业人员进行安全生产教育和培训，为从业人员提供符合国家标准或者行业标准的劳动防护用品，依法参加工伤保险。从业人员应当接受教育和培训，考核合格后上岗作业；对有资格要求的岗位，应当配备依法取得相应资格的人员。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第六条", "text": "任何单位和个人不得生产、使用、经营国家禁止生产、使用、经营的危险化学品。 国家对危险化学品的使用有限制性规定的，任何单位和个人不得违反限制性规定使用危险化学品。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第七条", "text": "对危险化学品的生产、储存、使用、经营、运输实施安全监督管理的有关部门（以下统称负有危险化学品安全监督管理职责的部门），依照下列规定履行职责： （一）应急管理部门负责危险化学品安全生产监督管理工作和危险化学品安全监督管理综合工作，组织确定、公布、调整危险化学品目录，依法对新建、改建、扩建生产、储存危险化学品（包括使用长输管道输送危险化学品，下同）的建设项目（以下统称危险化学品建设项目）进行安全条件审查和安全设施设计审查，核发危险化学品安全生产许可证、危险化学品安全使用许可证和危险化学品经营许可证，并负责危险化学品登记工作，组织危险化学品事故应急处置。 （二）公安机关负责危险化学品的公共安全管理，核发剧毒化学品购买许可证、剧毒化学品道路运输通行证，负责运输危险化学品的车辆进入危险化学品运输车辆限制通行区域的许可，并负责危险化学品运输车辆的道路交通安全管理。 （三）市场监督管理部门负责对纳入工业产品生产许可证管理目录的危险化学品及其包装物、容器（包括罐体，不包括储存危险化学品的固定式大型储罐，下同）实施工业产品生产许可证管理和产品质量监督，签发危险化学品生产、储存、经营、运输企业营业执照。 （四）生态环境主管部门负责废弃危险化学品处置的监督管理，组织危险化学品的生态环境危害性鉴定和生态环境风险程度评估，负责新化学物质环境管理登记，依照职责分工调查相关危险化学品环境污染事故和生态破坏事件，负责危险化学品事故现场的生态环境应急监测。 （五）交通运输主管部门负责危险化学品道路、水路运输活动安全监督管理，负责危险化学品道路运输、水路运输的许可或者备案，以及运输工具的安全监督管理，负责危险化学品道路运输企业、水路运输企业驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员的资格认定。铁路监管部门负责危险化学品铁路运输及其运输工具的安全监督管理。民用航空主管部门负责危险化学品航空运输以及航空运输企业及其运输工具的安全监督管理。邮政管理部门负责依法查处寄递危险化学品的行为。 （六）卫生健康主管部门负责危险化学品毒性鉴定的管理，负责危险化学品单位职业健康的监督管理，负责组织、协调危险化学品事故受伤人员的医疗卫生救援工作。 （七）自然资源主管部门负责在编制国土空间规划时，将危险化学品建设项目及化工园区、储存危险化学品的专门区域和周边安全控制距离等有关内容按照程序纳入当地国土空间规划，并做好规划监督实施。 （八）工业和信息化主管部门依照职责负责危险化学品生产、储存的相关行业规划和布局，组织制定化工园区的建设标准和认定管理办法，并推动落后工艺、产能退出。 （九）海关负责依法对进出口危险化学品及其包装实施检验。 （十）其他部门依照各自职责履行危险化学品安全监督管理职责。 对因涉及新兴行业、领域，危险化学品安全监督管理职责不明确的，由县级以上人民政府按照业务相近的原则及时确定监督管理部门。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第八条", "text": "负有危险化学品安全监督管理职责的部门依法进行监督检查，可以采取下列措施： （一）进入危险化学品作业场所实施现场检查，向有关单位和人员了解情况，查阅、复制有关文件、资料，必要时可以对危险化学品实施抽样检测； （二）运用信息化手段对危险化学品单位的重大危险源开展在线巡查抽查； （三）发现危险化学品事故隐患，责令立即消除或者限期消除； （四）对不符合法律、行政法规、规章规定或者国家标准、行业标准要求的设施、设备、装置、器材、运输工具等，责令立即停止使用； （五）经本部门主要负责人批准，查封违法生产、储存、使用、经营危险化学品的场所，扣押违法生产、储存、使用、经营、运输的危险化学品以及用于违法生产、使用、运输危险化学品的原材料、设备、运输工具； （六）发现影响危险化学品安全的违法行为，当场予以纠正或者责令限期改正。 负有危险化学品安全监督管理职责的部门依法进行监督检查，监督检查人员不得少于二人，并应当出示执法证件；有关单位和个人对依法进行的监督检查应当予以配合，不得拒绝、阻挠。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第九条", "text": "县级以上人民政府应当建立危险化学品安全监督管理工作协调机制，支持、督促负有危险化学品安全监督管理职责的部门依法履行职责，协调、解决危险化学品安全监督管理工作中的重大问题。 负有危险化学品安全监督管理职责的部门应当加强监管协作和联合执法，密切协调配合，实现信息及时、充分、有效共享，依法加强对危险化学品的安全监督管理。发现依法应当由其他部门处理的违法行为，及时移交其他部门处理。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第十条", "text": "任何单位和个人对违反本法规定的行为或者事故隐患，有权向负有危险化学品安全监督管理职责的部门举报或者报告。县级以上人民政府及其有关部门对举报违法行为或者报告重大事故隐患的有功人员依法给予奖励，并对举报人、报告人的信息进行严格保密。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第十一条", "text": "县级以上人民政府负有危险化学品安全监督管理职责的部门应当加强危险化学品信息化监管，对危险化学品实行电子标识和全生命周期信息化管理和监控。 化工园区应当明确负责安全生产监督管理的有关工作机构及其职责，加强危险化学品信息化建设，实现信息化安全监测、监控和预警，并与政府有关部门实现互联互通。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第十二条", "text": "国家鼓励危险化学品单位采用有利于提高安全保障水平的先进技术、工艺、设备以及自动控制系统，鼓励对危险化学品实行专门储存、统一配送、集中销售。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第十三条", "text": "生产、储存、使用、经营危险化学品的单位应当按照国家有关规定对危险化学品重大危险源登记建档，进行定期检测、评估、监控，制定应急预案，建立重大危险源安全责任制，并将重大危险源的储存数量、储存地点、管理人员的情况及有关安全措施、应急措施报所在地县级人民政府应急管理部门、消防救援机构和有关部门备案；在港区内储存的，报港口行政管理部门、消防救援机构和有关部门备案。 负有危险化学品安全监督管理职责的部门应当分级分类定期对危险化学品重大危险源开展专项监督检查，督促危险化学品单位及时消除事故隐患，防范重特大事故发生。 本法所称重大危险源，是指长期或者临时生产、储存、使用和经营危险化学品，且危险化学品的数量等于或者超过临界量的单元（包括场所和设施）。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第十四条", "text": "各级人民政府及其有关部门应当采取多种形式，加强危险化学品安全法律法规和危险化学品安全知识宣传普及工作，促进全社会危险化学品安全意识的提升。 化工园区、危险化学品单位应当对周边群众和其他生产经营单位进行危险化学品安全法律法规和危险化学品安全知识宣传。 新闻媒体应当开展危险化学品安全法律法规和危险化学品安全知识公益宣传，对危险化学品安全违法行为进行舆论监督。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第十五条", "text": "对在危险化学品安全工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。 第二章 规划布局"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第十六条", "text": "国家对危险化学品的生产、储存实行统筹规划、合理布局。 国务院工业和信息化主管部门以及国务院其他有关部门依照各自职责，负责危险化学品生产、储存的行业规划和布局。 地方人民政府组织编制国土空间规划时，应当根据本地区的实际情况，按照确保安全的原则，规划适当区域（包括化工园区）专门用于危险化学品的生产、储存。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第十七条", "text": "化工园区应当由省、自治区、直辖市人民政府或者其授权的部门认定公布并定期复核。 省、自治区、直辖市人民政府应当合理建设化工园区，组织开展化工园区的安全风险等级评估、论证，建立并落实管控措施。 化工园区应当对进出园区的所有危险化学品实行动态监管，对园区内企业、重点场所、重大危险源、基础设施实施风险监测预警。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第十八条", "text": "新建、扩建危险化学品生产建设项目应当进入化工园区，与其他行业生产装置配套建设的项目和符合国家规定的其他项目除外。 除为化工企业提供配套服务的企业外，非化工企业禁止进入化工园区。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第十九条", "text": "化工园区应当至少每三年开展一次整体性安全风险评估，提出消除、降低、管控安全风险的对策措施并有效实施。 当化工园区及危险化学品品种、数量、布局等发生变化，按照国家有关规定需要调整化工园区风险控制条件时，应当及时组织重新开展化工园区整体性安全风险评估，并修订相关应急预案。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第二十条", "text": "化工园区与城市建成区、人员密集场所、重要设施、敏感目标等应当保持符合相关法律、法规规定和国家标准要求的安全距离。 化工园区应当依照相关法律、法规规定和国家标准要求，拟定化工园区周边规划安全控制线，并报送化工园区所在地设区的市级人民政府或者其授权的部门确定后，按照程序纳入当地国土空间规划。 化工园区所在地设区的市级和县级人民政府自然资源主管部门应当严格控制化工园区周边规划安全控制线内的土地开发利用，规划安全控制线范围内的建设项目应当满足安全风险控制要求。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第二十一条", "text": "县级以上地方人民政府应当加强危险化学品运输安全保障，对涉及危险化学品储存、装卸、运输的物流园区、集中停车区域，以及高速公路服务区的加油站、加气站等进行规划。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第二十二条", "text": "危险化学品生产装置或者储存数量构成重大危险源的危险化学品储存设施，与下列场所、设施、区域的安全距离应当符合国家有关规定： （一）居住区以及商业中心、公园等人员密集场所； （二）学校、医院、影剧院、体育场馆等公共设施； （三）饮用水水源、水厂以及饮用水水源保护区； （四）车站、码头（依法经许可从事危险化学品装卸作业的除外）、机场以及通信干线、通信枢纽、铁路线路、道路交通干线、水路交通干线、地铁风亭以及地铁站出入口； （五）生态保护红线、自然保护地、永久基本农田、基本草原、种质资源库（场、区、圃）、畜禽规模化养殖场、渔业水域以及种子、种畜禽、水产苗种生产基地； （六）河流、湖泊、水库、海洋、重要调水输水线路、蓄滞洪区； （七）军事禁区、军事管理区以及有关军事设施； （八）核设施； （九）法律、行政法规规定的其他场所、设施、区域。 已建的危险化学品生产装置或者储存数量构成重大危险源的危险化学品储存设施不符合前款规定的，由所在地设区的市级人民政府应急管理部门会同有关部门监督其所属单位在规定期限内进行整改；需要转产、停产、搬迁、关闭的，由本级人民政府决定并组织实施。 储存数量构成重大危险源的危险化学品储存设施的选址，应当避开地震活动断层和容易发生洪灾、地质灾害、森林草原火灾的区域。 第三章 生产和储存安全"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第二十三条", "text": "危险化学品建设项目应当由应急管理部门进行安全条件审查。 建设单位应当委托具备国家规定的资质条件的机构对危险化学品建设项目进行安全评价，并将安全评价情况报建设项目所在地设区的市级以上人民政府应急管理部门；应急管理部门应当自收到报告之日起二十个工作日内作出安全条件审查决定，并书面通知建设单位。具体办法由国务院应急管理部门制定。 新建、改建、扩建储存、装卸危险化学品的港口建设项目（以下统称危险化学品港口建设项目），由港口行政管理部门按照国务院交通运输主管部门的规定进行安全条件审查。 承担安全评价等职责的机构的资质条件由国务院应急管理部门会同有关部门规定。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第二十四条", "text": "危险化学品建设项目和危险化学品港口建设项目的安全设施，必须与主体工程同时设计、同时施工、同时投入生产和使用。安全设施投资应当纳入建设项目概算。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第二十五条", "text": "危险化学品建设项目和危险化学品港口建设项目安全设施的设计人、设计单位应当对安全设施设计负责。在安全设施设计中应当提出保障安全的措施建议。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第二十六条", "text": "危险化学品建设项目的安全设施设计应当报所在地设区的市级以上人民政府应急管理部门审查。具体办法由国务院应急管理部门制定。 危险化学品港口建设项目的安全设施设计，由港口行政管理部门按照国家有关规定进行审查。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第二十七条", "text": "施工单位必须按照批准的安全设施设计施工，并对安全设施的工程质量和施工安全负责。实行工程监理的危险化学品建设项目，建设单位应当对安全设施施工一并委托监理。 建设单位应当组织对安全设施进行验收，验收合格方可投入生产和使用。 对危险化学品建设项目和危险化学品港口建设项目负有安全生产监督管理职责的部门应当加强对建设单位验收活动和验收结果的监督核查。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第二十八条", "text": "生产、储存危险化学品的单位在公共区域埋地、地面和架空的危险化学品输送管道及其附属设施的安全管理，应当符合法律、行政法规的规定和国家标准、行业标准的要求。 生产、储存危险化学品的单位，应当对其敷设的危险化学品管道设置明显标志，并对危险化学品管道定期检查、检测、巡护。 进行可能危及危险化学品管道安全的施工作业，施工单位应当在开工的七日前将施工方案书面通知管道所属单位，并与管道所属单位共同制定应急预案，采取相应的安全防护措施。管道所属单位应当指派专门人员到现场进行管道安全保护指导。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第二十九条", "text": "危险化学品生产企业主要负责人（包括法定代表人、实际控制人、实际负责人）和安全生产管理人员应当具备相应的安全生产知识和管理能力，并经应急管理部门考核合格。 危险化学品生产企业从业人员应当满足国家规定的学历要求，接受安全生产教育和培训，考核合格后上岗作业。 危险化学品生产企业应当建立健全安全培训管理制度，定期组织培训，提高从业人员安全意识和安全生产技能水平。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三十条", "text": "危险化学品生产企业进行生产前，应当依照有关安全生产许可法律、行政法规的规定，取得危险化学品安全生产许可证。 生产列入国家实行生产许可证制度的工业产品目录的危险化学品的企业，还应当依照有关工业产品生产许可法律、行政法规的规定，取得工业产品生产许可证。试生产的危险化学品，在取得工业产品生产许可证后，经具有相应资质的检验机构检验合格可以销售。 负责颁发危险化学品安全生产许可证、工业产品生产许可证的部门，应当将其颁发许可证的情况依照有关法律、行政法规的规定及时向社会公开。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三十一条", "text": "危险化学品生产企业、进口企业应当提供与其生产、进口的危险化学品相符的中文化学品安全技术说明书，并在危险化学品包装（包括外包装件，下同）上粘贴、印刷或者拴挂与包装内危险化学品相符的中文化学品安全标签。化学品安全技术说明书和化学品安全标签应当符合国家标准的要求。 危险化学品生产企业、进口企业发现其生产或者进口的危险化学品有新的危险特性的，应当立即公告，及时修订其化学品安全技术说明书和化学品安全标签。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三十二条", "text": "危险化学品的包装应当符合法律、行政法规、规章的规定和国家标准、行业标准的要求。 危险化学品包装物、容器的材质以及危险化学品包装的型式、规格、方法和单件质量，应当与所包装的危险化学品的性质和用途相适应。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三十三条", "text": "生产列入国家实行生产许可证制度的工业产品目录的危险化学品包装物、容器的企业，应当依照有关工业产品生产许可法律、行政法规的规定，取得工业产品生产许可证；其生产的危险化学品包装物、容器经具有相应资质的检验机构检验合格，方可出厂销售。 运输危险化学品的船舶及其配载的容器，应当符合有关法律、行政法规、规章以及强制性标准和技术规范的要求，并经国家海事管理机构认定的船舶检验机构检验合格，方可投入使用。 对重复使用的危险化学品包装物、容器，使用单位在重复使用前应当进行检查；发现存在安全隐患的，应当及时维修或者更换。使用单位应当对检查情况作出记录，记录的保存期限不得少于三年。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三十四条", "text": "生产、储存危险化学品的企业应当建立安全风险分级管控制度，开展安全风险辨识评估，按照安全风险分级采取相应的管控措施。 生产、储存危险化学品的企业的工艺、设施、设备、原料等发生变更时应当重新进行安全风险辨识评估。 生产、储存危险化学品的企业不得使用国家明令淘汰或者禁止使用的危及生产安全的工艺、技术、设施、设备，具体目录由国务院应急管理部门会同有关部门制定并公布。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三十五条", "text": "生产、储存危险化学品的企业应当建立包括工艺操作、特殊作业、设备管理、储存条件、开停车和检维修、变更等全部生产作业环节在内的过程安全管理制度，明确责任人、岗位职责和操作规程，并组织有效实施。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三十六条", "text": "生产、储存危险化学品的企业应当按照国家标准或者行业标准装备自动控制系统和安全仪表系统，建立安全风险监测预警系统，并与政府有关部门实现互联互通。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三十七条", "text": "生产、储存危险化学品的单位，应当根据其生产、储存的危险化学品的种类和危险特性，在作业场所设置相应的监测、监控、通风、防晒、调温、防火、灭火、防爆、泄压、防毒、中和、防潮、防雷、防静电、防腐、防泄漏以及防护围堤或者隔离操作等安全设施、设备，并按照国家标准、行业标准或者国家有关规定对安全设施、设备进行经常性维护、保养，保证安全设施、设备的正常使用。 生产、储存危险化学品的单位，应当在其作业场所和安全设施、设备上设置明显的安全警示标志。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三十八条", "text": "生产、储存危险化学品的单位，应当在其作业场所设置通信、报警装置，并保证处于适用状态。 生产、储存危险化学品的单位，不得关闭、破坏直接关系生产安全的监控、报警、防护、救生设施、设备，或者以其他任何方式影响其正常使用，不得篡改、隐瞒、销毁其相关数据、信息。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三十九条", "text": "生产、储存危险化学品的企业，应当委托具备国家规定的资质条件的机构，对本企业的安全生产条件每三年进行一次安全评价，提出安全评价报告。安全评价报告的内容应当包括对安全生产条件存在的问题进行整改的方案和整改完成后的结论性意见。安全评价报告应当按照规定向社会公开。 生产、储存危险化学品的企业，应当将安全评价报告以及整改方案的落实情况报所在地县级人民政府应急管理部门备案。 在港区内储存、装卸危险化学品的企业，应当依照本条第一款要求进行安全评价，安全评价报告以及整改方案的落实情况按照规定报港口行政管理部门或者所在地县级人民政府应急管理部门备案。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十条", "text": "生产、储存剧毒化学品或者国务院公安部门规定的可用于制造爆炸物品的危险化学品（以下简称易制爆危险化学品）的单位，应当如实记录其生产、储存的剧毒化学品、易制爆危险化学品的品种、数量、流向，并采取必要的安全防范措施，防止剧毒化学品、易制爆危险化学品丢失或者被盗；发现剧毒化学品、易制爆危险化学品丢失或者被盗的，应当立即向当地公安机关报告；公安机关应当根据实际情况及时通报应急管理等有关部门。 生产、储存剧毒化学品、易制爆危险化学品的单位，应当设置治安保卫机构，配备专职治安保卫人员，并依法报公安机关备案。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十一条", "text": "危险化学品应当储存在专用仓库、专用场地或者专用储存室、储存专柜（以下统称专用储存场所）内，并由专人负责管理；剧毒化学品以及储存数量构成重大危险源的其他危险化学品，应当在专用储存场所内单独存放，实行双人收发、双人保管制度，收发记录的保存期限不得少于三年。 危险化学品的储存方式、方法以及储存数量应当符合国家标准或者国家有关规定。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十二条", "text": "储存危险化学品的单位应当建立危险化学品出入库核查、登记制度。 剧毒化学品储存单位应当将剧毒化学品的储存数量、储存地点以及管理人员的情况，报所在地县级人民政府应急管理部门、消防救援机构和公安机关备案；在港区内储存的，报港口行政管理部门、消防救援机构和公安机关备案。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十三条", "text": "危险化学品专用储存场所应当符合国家标准、行业标准的要求，并设置明显的标志。储存剧毒化学品、易制爆危险化学品的专用储存场所，应当按照国家有关规定设置相应的实体防范、技术防范设施。 储存危险化学品的单位应当对其危险化学品专用储存场所的安全设施、设备定期进行检测、检验；检测、检验不合格的，应当停止使用，并按照规定予以维修或者更换。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十四条", "text": "研制开发单位进行危险化学品新工艺、新技术、新产品开发，应当加强研制开发过程的安全管理，确保研制开发过程安全，不得将未经小试、中试、工业化试验的新工艺、新技术直接用于工业化生产。 研制开发单位转让危险化学品新工艺、新技术时，应当提供新工艺、新技术的安全论证报告及相关资料，并进行技术指导。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十五条", "text": "生产、储存危险化学品的单位整体或者部分转产、停产、停业、解散的，应当采取有效措施，及时、妥善处置其危险化学品生产装置、储存设施以及库存的危险化学品，不得丢弃危险化学品；处置方案应当报所在地县级人民政府应急管理、工业和信息化、生态环境部门和公安机关、消防救援机构备案。应急管理部门应当会同生态环境主管部门和公安机关、消防救援机构对处置情况进行监督检查，发现未按照规定处置的，应当责令其立即处置。 第四章 使用安全"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十六条", "text": "县级以上人民政府有关部门应当依照职责分工，加强对企业、学校、科研机构、医疗机构、检测机构、检验机构等单位使用危险化学品的监督管理。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十七条", "text": "使用危险化学品的单位的使用条件（包括工艺）应当符合法律、行政法规的规定和国家标准、行业标准的要求，并根据所使用的危险化学品的种类、危险特性以及使用量和使用方式，建立健全使用危险化学品的安全管理规章制度和安全操作规程，保证危险化学品的安全使用。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十八条", "text": "使用国家规定种类的危险化学品从事生产并且使用量达到规定数量的化工企业（属于危险化学品生产企业的除外，下同），应当依照本法的规定取得危险化学品安全使用许可证。 前款规定的危险化学品种类及其使用量的数量标准，由国务院应急管理部门会同公安、农业农村部门确定并公布。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十九条", "text": "申请危险化学品安全使用许可证的化工企业，除应当符合本法"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十七条", "text": "的规定外，还应当具备下列条件： （一）有与所使用的危险化学品相适应的专业技术人员，从业人员经考核合格； （二）有安全生产管理机构和专职安全生产管理人员； （三）有符合国家规定的危险化学品事故应急预案和必要的应急救援器材、装备、设备和物资； （四）依法进行了安全评价； （五）法律、法规规定的其他条件。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十条", "text": "申请危险化学品安全使用许可证的化工企业，应当向所在地设区的市级人民政府应急管理部门提出申请，并提交其符合本法"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十九条", "text": "规定条件的证明材料。设区的市级人民政府应急管理部门应当依法进行审查，自收到证明材料之日起二十个工作日内作出批准或者不予批准的决定。予以批准的，颁发危险化学品安全使用许可证；不予批准的，书面通知申请人并说明理由。 设区的市级人民政府应急管理部门应当将其颁发危险化学品安全使用许可证的情况依照有关法律、行政法规的规定及时向社会公开。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十一条", "text": "使用危险化学品的单位应当将其作业场所使用的化学品安全技术说明书和化学品安全标签提供给从业人员，并加强培训教育，告知从业人员正确使用的方法和在紧急情况下应当采取的措施。 使用危险化学品的个人，应当了解危险化学品的危险特性、正确使用方法和防护措施，不得违法使用、储存、处置危险化学品。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第四十五条", "text": "关于生产、储存危险化学品的单位的规定，适用于使用危险化学品的单位；"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三十九条", "text": "关于生产、储存危险化学品的企业的规定，适用于使用危险化学品从事生产的企业。 第五章 经营安全"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十三条", "text": "国家对危险化学品经营（包括仓储经营，下同）实行许可制度。未经许可，任何单位和个人不得经营危险化学品。危险化学品经营企业不得向未经许可从事危险化学品生产、经营活动的企业采购危险化学品。 依法设立的危险化学品生产企业在其厂区范围内销售本企业生产的危险化学品，不需要取得危险化学品经营许可。 依照《中华人民共和国港口法》的规定取得港口经营许可证的港口经营人，在港区内从事危险化学品仓储经营，不需要取得危险化学品经营许可。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十四条", "text": "从事危险化学品经营的企业应当具备下列条件： （一）有符合国家标准、行业标准的经营场所，储存危险化学品的，还应当有符合国家标准、行业标准的储存设施； （二）从业人员经过专业技术培训并经考核合格； （三）有健全的安全管理规章制度； （四）有专职安全生产管理人员，主要负责人和安全生产管理人员具备与本企业危险化学品经营活动相适应的安全生产知识和管理能力，经应急管理部门考核合格； （五）有符合国家规定的危险化学品事故应急预案和必要的应急救援器材、装备、设备和物资； （六）法律、法规规定的其他条件。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十五条", "text": "从事剧毒化学品、易制爆危险化学品经营的企业，应当向所在地设区的市级人民政府应急管理部门提出申请。从事其他危险化学品经营的企业，应当向所在地县级人民政府应急管理部门提出申请；有储存设施且储存数量构成重大危险源的，应当向所在地设区的市级人民政府应急管理部门提出申请。申请人应当提交其符合本法"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十四条", "text": "规定条件的证明材料。设区的市级人民政府应急管理部门或者县级人民政府应急管理部门应当依法进行审查，并按照规定对申请人的经营场所、储存设施进行现场核查。自收到证明材料之日起二十个工作日内作出批准或者不予批准的决定。予以批准的，颁发危险化学品经营许可证；不予批准的，书面通知申请人并说明理由。 设区的市级人民政府应急管理部门和县级人民政府应急管理部门应当将其颁发危险化学品经营许可证的情况依照有关法律、行政法规的规定及时向社会公开。 申请人持危险化学品经营许可证向市场监督管理部门办理登记手续后，方可从事危险化学品经营活动。法律、行政法规或者国务院规定经营危险化学品还需要经其他有关部门许可的，申请人向市场监督管理部门办理登记手续时应当持相应的许可证件。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十六条", "text": "危险化学品经营企业储存危险化学品的，应当遵守本法第三章关于储存危险化学品的规定。危险化学品商店内只能存放民用小包装的危险化学品。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十七条", "text": "危险化学品生产企业、经营企业在销售危险化学品时，应当向购买单位或者个人提供符合法律、行政法规规定和国家标准、行业标准要求的化学品安全技术说明书，不得经营没有化学品安全技术说明书或者化学品安全标签的危险化学品，不得擅自更改化学品安全技术说明书或者化学品安全标签。 任何单位和个人购买危险化学品时，有权向危险化学品生产企业、经营企业索取有关危险化学品的安全技术说明书，了解其危险特性、防护措施和使用方法。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十八条", "text": "依法取得危险化学品安全生产许可证、危险化学品安全使用许可证或者危险化学品经营许可证的企业，凭相应的许可证件购买剧毒化学品、易制爆危险化学品。民用爆炸物品、烟花爆竹、武器装备科研生产企业凭相应许可证购买易制爆危险化学品。 前款规定以外的单位购买剧毒化学品的，应当向所在地县级人民政府公安机关申请取得剧毒化学品购买许可证；购买易制爆危险化学品的，应当持本单位出具的合法用途说明。 个人不得购买剧毒化学品（属于剧毒化学品的农药除外）和易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十九条", "text": "申请取得剧毒化学品购买许可证，申请人应当向所在地县级人民政府公安机关提交下列材料： （一）营业执照或者法人证书（登记证书）的复印件； （二）拟购买的剧毒化学品品种、数量的说明； （三）购买剧毒化学品用途的说明； （四）经办人的身份证明。 县级人民政府公安机关应当自收到前款规定的材料之日起三个工作日内，作出批准或者不予批准的决定。予以批准的，颁发剧毒化学品购买许可证；不予批准的，书面通知申请人并说明理由。 剧毒化学品购买许可管理按照国务院公安部门的规定执行。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第六十条", "text": "危险化学品生产企业、经营企业销售剧毒化学品、易制爆危险化学品，应当查验本法"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十八条", "text": "第一款、第二款规定的相关许可证件或者证明文件，不得向不具有相关许可证件或者证明文件的单位销售剧毒化学品、易制爆危险化学品。对持剧毒化学品购买许可证购买剧毒化学品的，应当按照许可证载明的品种、数量销售。 禁止向个人销售剧毒化学品（属于剧毒化学品的农药除外）和易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第六十一条", "text": "危险化学品生产企业、经营企业销售剧毒化学品、易制爆危险化学品，应当如实记录购买单位的名称、地址，经办人的姓名、身份证号码以及所购买的剧毒化学品、易制爆危险化学品的品种、数量、用途。销售记录以及经办人的身份证明复印件、相关许可证件复印件或者证明文件的保存期限不得少于三年。 剧毒化学品、易制爆危险化学品的销售企业、购买单位应当在销售、购买后三日内，将所销售、购买的剧毒化学品、易制爆危险化学品的品种、数量以及流向信息报所在地县级人民政府公安机关备案，并录入计算机系统。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第六十二条", "text": "使用剧毒化学品、易制爆危险化学品的单位不得出借、转让其购买的剧毒化学品、易制爆危险化学品；因转产、停产、搬迁、关闭等确需转让的，应当向具有本法"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十八条", "text": "第一款、第二款规定的相关许可证件或者证明文件的单位转让，并在转让后三日内将所转让的剧毒化学品、易制爆危险化学品品种、数量以及流向信息报所在地县级人民政府公安机关备案。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第六十三条", "text": "禁止在互联网上销售、购买剧毒化学品、易制爆危险化学品。 第六章 运输安全"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第六十四条", "text": "通过道路、水路运输按照危险货物管理的危险化学品，应当遵守本法和有关法律、行政法规、国务院交通运输主管部门关于危险货物道路、水路运输安全的规定。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第六十五条", "text": "从事危险化学品道路运输、水路运输的，应当向市场监督管理部门办理登记手续，并分别依照有关道路运输、水路运输的法律、行政法规的规定，取得危险货物道路运输许可、相应危险货物水路运输许可或者办理备案手续。 通过道路、水路运输危险化学品，应当由依法取得相应许可或者办理备案手续的运输企业承运，其他单位和个人不得承运。托运人应当委托依法取得相应许可或者办理备案手续的运输企业承运，不得委托其他单位和个人承运。其他单位和个人的危险化学品运输车辆不得挂靠经营。 危险化学品道路运输企业、水路运输企业应当配备专职安全生产管理人员。 经妥善处理后可以按照普通货物管理的危险化学品按照普通货物运输，具体办法由国务院交通运输主管部门制定。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第六十六条", "text": "危险化学品道路运输企业、水路运输企业的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员应当经交通运输主管部门考核合格，取得从业资格。具体办法由国务院交通运输主管部门制定。 危险化学品的装卸作业应当遵守安全作业标准、规程和制度，并在装卸管理人员的现场指挥或者监控下进行。水路运输危险化学品的集装箱装箱作业应当在集装箱装箱现场检查员的指挥或者监控下进行，并符合积载、隔离的规范和要求；装箱作业完毕后，集装箱装箱现场检查员应当签署装箱证明书。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第六十七条", "text": "运输危险化学品，应当根据危险化学品的危险特性采取相应的安全防护措施，并配备必要的防护用品和应急救援器材、装备、设备和物资。 用于运输危险化学品的槽罐以及其他容器应当封口严密，能够防止危险化学品在运输过程中因温度、湿度或者压力的变化发生渗漏、洒漏；槽罐以及其他容器的溢流和泄压装置应当设置准确、启闭灵活。 运输危险化学品，驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员应当熟悉所运输的危险化学品的危险特性及其包装物、容器的使用要求，掌握出现危险情况时的应急处置方法。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第六十八条", "text": "通过道路运输危险化学品，应当按照运输车辆的核定载质量装载危险化学品，不得超载。 危险化学品运输车辆应当符合国家标准要求的安全技术条件，并按照国家有关规定定期进行安全技术检验。 危险化学品运输车辆应当悬挂或者喷涂符合国家标准要求的警示标志，不得遮挡、拆除。 危险化学品运输车辆应当安装符合国家标准、行业标准要求的卫星定位监控装置并确保处于良好运行状态，不得拆除、关闭或者采取屏蔽信号等方式影响其正常运行，不得删除、篡改监控数据。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第六十九条", "text": "通过道路运输危险化学品，应当按照要求配备押运人员，并保证所运输的危险化学品处于押运人员的监控之下。具体办法由国务院交通运输主管部门会同有关部门制定。 危险化学品道路运输企业应当对运输车辆、驾驶人员的作业状态进行实时监控、管理，及时纠正超速行驶、疲劳驾驶、不按规定线路行驶等违法违规驾驶行为，实现安全监测、监控和预警。运输危险化学品车辆的驾驶人员应当严格遵守道路交通安全法律法规，日间连续驾驶时间不得超过四小时，夜间连续驾驶时间不得超过二小时，每次停车休息时间不少于二十分钟。 运输危险化学品途中需要停车的，驾驶人员、押运人员应当采取相应的安全防范措施；运输剧毒化学品或者易制爆危险化学品因住宿或者发生影响正常运输的情况，需要较长时间停车的，还应当向当地公安机关报告。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第七十条", "text": "未经公安机关批准，运输危险化学品的车辆不得进入危险化学品运输车辆限制通行的区域。危险化学品运输车辆限制通行的区域由县级人民政府公安机关划定或者会同有关部门划定，并设置明显的标志。 运输危险化学品的车辆进入危险化学品运输车辆限制通行区域许可管理按照国务院公安部门的规定执行。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第七十一条", "text": "通过道路运输剧毒化学品，托运人应当向运输始发地或者目的地县级人民政府公安机关申请剧毒化学品道路运输通行证。 申请剧毒化学品道路运输通行证，托运人应当向县级人民政府公安机关提交下列材料： （一）拟运输的剧毒化学品品种、数量的说明； （二）运输始发地、目的地、运输时间和运输路线的说明； （三）承运人取得相应危险货物道路运输许可、运输车辆取得相应营运证以及驾驶人员、押运人员取得相应上岗资格的证明文件； （四）本法"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十八条", "text": "第一款、第二款规定的购买剧毒化学品的相关许可证件，或者海关出具的进出口证明文件。 县级人民政府公安机关应当自收到前款规定的材料之日起七个工作日内，作出批准或者不予批准的决定。予以批准的，颁发剧毒化学品道路运输通行证；不予批准的，书面通知申请人并说明理由。 剧毒化学品道路运输通行证管理按照国务院公安部门的规定执行。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第七十二条", "text": "剧毒化学品、易制爆危险化学品在道路运输途中丢失、被盗、被抢或者出现流散、泄漏等情况的，驾驶人员、押运人员应当立即采取相应的警示措施和安全措施，并向当地公安机关报告。公安机关接到报告后，应当根据实际情况立即向交通运输、应急管理、生态环境、卫生健康部门通报。有关部门应当采取必要的应急处置措施。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第七十三条", "text": "海事管理机构应当根据危险化学品的种类和危险特性，确定船舶运输危险化学品的安全运输条件。 拟交付船舶运输的化学品的安全运输条件不明确的，货物所有人或者代理人应当委托相关技术机构进行评估，明确相关安全运输条件并经海事管理机构确认后，方可交付船舶运输。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第七十四条", "text": "禁止通过内河封闭水域运输剧毒化学品。 禁止通过内河水域运输国家规定禁止通过内河运输的危险化学品。禁止通过内河运输的危险化学品的范围，由国务院交通运输主管部门会同生态环境、应急管理、工业和信息化部门，根据危险化学品的危险特性、危险化学品对人体和水环境的危害程度以及消除危害后果的难易程度等因素规定并公布。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第七十五条", "text": "国务院交通运输主管部门应当根据危险化学品的危险特性，对通过内河运输本法"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第七十四条", "text": "规定以外的危险化学品（以下简称通过内河运输危险化学品）实行分类管理，对各类危险化学品的运输方式、包装规范和安全防护措施等分别作出规定并监督实施。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第七十六条", "text": "通过内河运输危险化学品，应当使用依法取得危险货物适装证书的运输船舶。水路运输企业应当针对所运输的危险化学品的危险特性，制定运输船舶危险化学品事故应急救援预案，并为运输船舶配备充足、有效的应急救援器材、装备、设备和物资。 通过内河运输危险化学品的船舶，其所有人或者经营人应当取得船舶污染损害责任保险证书或者财务担保证明。船舶污染损害责任保险证书或者财务担保证明的副本应当随船携带。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第七十七条", "text": "通过内河运输危险化学品，危险化学品包装物的材质、型式、强度以及包装方法应当符合水路运输相关包装规范的要求。国务院交通运输主管部门对单船运输的危险化学品数量有限制性规定的，承运人应当按照规定安排运输数量。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第七十八条", "text": "用于危险化学品运输作业的内河码头、泊位应当符合国家有关安全规范，与饮用水取水口保持国家规定的安全距离。有关管理单位应当制定码头、泊位危险化学品事故应急预案，并为码头、泊位配备充足、有效的应急救援器材、装备、设备和物资。 用于危险化学品运输作业的内河码头、泊位，按照国家有关规定验收合格后方可投入使用。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第七十九条", "text": "船舶载运危险化学品进出内河港口，应当依照法律、行政法规的规定向海事管理机构报告。海事管理机构接到报告后，应当在国务院交通运输主管部门规定的时间内作出是否同意的决定，通知报告人，同时通报港口行政管理部门。 在内河港口内进行危险化学品的装卸、过驳作业，应当将危险化学品的名称、危险特性、包装和作业的时间、地点等事项报告港口行政管理部门。港口行政管理部门接到报告后，应当在国务院交通运输主管部门规定的时间内作出是否同意的决定，通知报告人，同时通报海事管理机构。 载运危险化学品的船舶在内河航行，通过通航建筑物的，应当符合通航建筑物安全管理有关要求，并提前向通航建筑物运行单位报告。运行单位应当及时转报交通运输主管部门。载运危险化学品的船舶通过通航建筑物时，应当接受交通运输主管部门的管理。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第八十条", "text": "载运危险化学品的船舶在内河航行、装卸或者停泊，应当悬挂专用的警示标志，按照规定显示专用信号。 载运危险化学品的船舶在内河航行，依照法律、行政法规以及国务院交通运输主管部门的规定需要引航的，应当申请引航。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第八十一条", "text": "载运危险化学品的船舶在内河航行，应当遵守法律、行政法规和国家其他有关饮用水水源和自然保护地保护的规定。内河航道发展规划应当与依法经批准的饮用水水源保护区划定方案和自然保护地总体规划相协调。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第八十二条", "text": "托运危险化学品，托运人应当向承运人提交电子或者纸质的危险货物托运清单，说明所托运的危险化学品的种类、数量、危险特性以及发生危险情况的应急处置措施，提供化学品安全技术说明书，并按照国家有关规定对所托运的危险化学品妥善包装，在危险化学品包装上粘贴、印刷或者拴挂与包装内危险化学品相符的化学品安全标签，并保证随时可查。 运输危险化学品需要添加抑制剂或者稳定剂的，托运人应当按照规定添加，并将有关情况告知承运人。 装货人应当在充装或者装载危险化学品前履行查验责任，并按照标准要求进行充装、装载作业。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第八十三条", "text": "托运人不得在托运的普通货物中夹带危险化学品，不得将危险化学品匿报或者谎报为普通货物托运。 任何单位和个人不得交寄危险化学品或者在邮件、快件内夹带危险化学品，不得将危险化学品匿报或者谎报为普通物品交寄。邮政企业、快递企业不得收寄危险化学品。 对涉嫌违反本条第一款、第二款规定的，交通运输主管部门、邮政管理部门可以依法开拆，并通过取样检验等多种方式开展查验。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第八十四条", "text": "通过铁路、航空运输危险化学品的安全管理，依照有关铁路、航空运输的法律、行政法规、规章的规定执行。 第七章 危险化学品登记"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第八十五条", "text": "国家实行危险化学品登记制度，为危险化学品安全管理以及危险化学品事故预防和应急救援提供技术、信息支持。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第八十六条", "text": "危险化学品生产企业、进口企业应当向国务院应急管理部门负责危险化学品登记的机构（以下简称危险化学品登记机构）办理危险化学品登记。 危险化学品登记包括下列内容： （一）分类和标签信息； （二）物理、化学性质； （三）主要用途； （四）危险特性； （五）储存、使用、运输的安全要求； （六）出现危险情况的应急处置措施。 对同一企业生产、进口的同一品种的危险化学品，不进行重复登记。危险化学品生产企业、进口企业发现其生产、进口的危险化学品有新的危险特性或者其他登记内容发生变更的，应当及时向危险化学品登记机构办理登记内容变更手续。 危险化学品登记的具体办法由国务院应急管理部门制定。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第八十七条", "text": "国家对研究开发、试产试销过程中的低量低释放、低暴露的危险化学品等免予登记。免予登记的具体办法由国务院应急管理部门会同工业和信息化、公安、生态环境、农业农村、卫生健康、海关等部门制定。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第八十八条", "text": "危险化学品登记机构应当将危险化学品登记信息数据与工业和信息化、公安、自然资源、生态环境、交通运输、农业农村、卫生健康、海关、市场监督管理、能源、军事机关等单位共享。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第八十九条", "text": "新化学物质环境管理登记，依照有关生态环境保护的法律、行政法规、规章的规定执行。 第八章 事故应急救援"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第九十条", "text": "县级以上地方人民政府应急管理部门应当会同工业和信息化、公安、生态环境、交通运输、卫生健康、市场监督管理等部门，根据本地区实际情况，制定危险化学品事故应急预案，报本级人民政府批准，并依法向社会公布。 负有危险化学品安全监督管理职责的部门在制定本部门应急预案时应当包含危险化学品事故应急处置的内容。 中国人民解放军、中国人民武装警察部队按照中央军事委员会的命令，依法参加危险化学品事故应急救援工作。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第九十一条", "text": "危险化学品单位应当做好应急准备工作，健全应急管理制度，制定本单位危险化学品事故应急预案，依法建立专职或者兼职应急救援队伍，配备必要的应急救援器材、装备、设备和物资，并定期组织应急救援演练，提高从业人员的应急处置能力。生产经营规模较小的，可以不建立应急救援队伍，但应当指定兼职的应急救援人员，并可以与邻近的应急救援队伍签订应急救援协议。 危险化学品单位应当将其危险化学品事故应急预案按照国家有关规定报送县级以上人民政府应急管理部门备案，并依法向社会公布。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第九十二条", "text": "县级以上地方人民政府根据生产安全事故应急工作的实际需要，加强化工园区危险化学品专业应急救援力量建设，可以依托有条件的生产经营单位、社会组织共同建立危险化学品专业应急救援队伍，配备必要的应急救援器材、装备、设备和物资，并定期组织训练。 化工园区内的危险化学品单位，可以联合建立应急救援队伍。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第九十三条", "text": "发生危险化学品事故，事故单位主要负责人应当立即按照本单位危险化学品事故应急预案组织救援，并向当地应急管理、生态环境、公安、卫生健康、市场监督管理部门报告，及时通知可能受影响的单位和人员；道路运输、水路运输过程中发生危险化学品事故的，驾驶人员、船员或者押运人员还应当向事故发生地交通运输主管部门报告。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第九十四条", "text": "危险化学品单位发生直接危及人身安全的紧急情况时，在确保安全的前提下，作业现场带班人员、班组长、调度人员有权立即下达停产撤人命令，指挥有关遇险人员撤离。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第九十五条", "text": "发生危险化学品事故，有关地方人民政府应当立即组织应急管理、生态环境、公安、卫生健康、交通运输等有关部门，按照本地区危险化学品事故应急预案组织实施救援，不得拖延、推诿。 有关地方人民政府及其有关部门应当按照下列规定，采取必要的应急处置措施，减少事故损失，防止事故蔓延、扩大： （一）立即组织营救和救治受害人员，转移、疏散、撤离并妥善安置受到威胁的其他人员或者采取其他保护措施； （二）迅速控制危害源，测定危险化学品的性质，评估事故的危害区域及危害程度； （三）针对事故对人体、动植物、土壤、水源、水体、大气造成的现实危害和可能产生的危害，迅速采取封闭、隔离、洗消等措施； （四）对危险化学品事故造成的环境污染和生态破坏状况进行监测、评估，并采取相应的环境污染治理和生态修复措施。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第九十六条", "text": "有关危险化学品单位应当为危险化学品事故应急救援提供技术指导和必要的协助。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第九十七条", "text": "危险化学品事故造成环境污染和生态破坏的，由履行统一领导职责的人民政府统一发布有关信息。 第九章 法律责任"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第九十八条", "text": "生产、使用、经营国家禁止生产、使用、经营的危险化学品的，由应急管理部门责令停止生产、使用、经营活动，有违法所得的，没收违法所得，并没收违法生产、使用、经营的危险化学品以及用于违法生产、使用、经营的工具、设备、原料等；违法生产、使用、经营的危险化学品货值金额不足十万元的，并处三十万元以上五十万元以下的罚款；货值金额十万元以上的，并处货值金额五倍以上十倍以下的罚款。 有前款规定行为的，应急管理部门还应当责令其对所生产、使用、经营的危险化学品进行无害化处理。 违反国家关于危险化学品使用的限制性规定使用危险化学品的，依照本条第一款的规定处理、处罚。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第九十九条", "text": "有下列情形之一的，由负有危险化学品安全监督管理职责的部门按照职责分工责令停止建设或者停产停业整顿，限期改正，并处十万元以上五十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；逾期未改正的，处五十万元以上一百万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款： （一）危险化学品建设项目未经安全条件审查； （二）危险化学品建设项目没有安全设施设计或者安全设施设计未报有关应急管理部门审查同意； （三）施工单位未按照批准的安全设施设计施工； （四）实行工程监理的危险化学品建设项目，建设单位未对安全设施施工一并委托监理； （五）危险化学品建设项目竣工投入生产或者使用前，安全设施未经验收合格。 危险化学品港口建设项目有前款规定情形的，由港口行政管理部门依照前款规定予以处理、处罚。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百条", "text": "未依法取得危险化学品安全生产许可证从事危险化学品生产，或者未依法取得工业产品生产许可证从事危险化学品及其包装物、容器生产的，分别依照有关安全生产许可、工业产品生产许可法律、行政法规的规定处理、处罚。 违反本法规定，化工企业未取得危险化学品安全使用许可证，使用危险化学品从事生产的，由应急管理部门责令限期改正，处十万元以上五十万元以下的罚款；逾期不改正的，责令停产整顿。 违反本法规定，未取得危险化学品经营许可证从事危险化学品经营的，由应急管理部门责令停止经营活动，没收违法经营的危险化学品以及违法所得，并处十万元以上五十万元以下的罚款。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百零一条", "text": "有下列情形之一的，由负有危险化学品安全监督管理职责的部门按照职责分工责令限期改正，可以处十万元以下的罚款；逾期未改正的，处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；情节严重的，责令停产停业整顿： （一）危险化学品生产企业、进口企业未提供中文化学品安全技术说明书，或者未在危险化学品包装上粘贴、印刷、拴挂中文化学品安全标签； （二）危险化学品生产企业、进口企业提供的中文化学品安全技术说明书与其生产、进口的危险化学品不相符，在危险化学品包装上粘贴、印刷、拴挂的中文化学品安全标签与包装内危险化学品不相符，或者化学品安全技术说明书、化学品安全标签不符合国家标准要求； （三）危险化学品生产企业、进口企业发现其生产或者进口的危险化学品有新的危险特性不立即公告，或者不及时修订其化学品安全技术说明书、化学品安全标签； （四）生产、储存危险化学品的单位未对其敷设的危险化学品管道设置明显标志，或者未对危险化学品管道定期检查、检测、巡护； （五）进行可能危及危险化学品管道安全的施工作业，施工单位未按照规定将施工方案书面通知管道所属单位，未与管道所属单位共同制定应急预案、采取相应的安全防护措施，或者管道所属单位未指派专门人员到现场进行管道安全保护指导； （六）危险化学品生产企业从业人员未满足国家规定的学历要求，未接受安全生产教育和培训，或者未经考核合格上岗作业； （七）危险化学品包装物、容器的材质以及包装的型式、规格、方法和单件质量与所包装的危险化学品的性质和用途不相适应； （八）生产、储存危险化学品的企业以及使用危险化学品从事生产的企业未明确责任人、岗位职责和操作规程； （九）生产、储存危险化学品的企业以及使用危险化学品从事生产的企业未按照规定装备自动控制系统和安全仪表系统，未建立安全风险监测预警系统，或者安全风险监测预警系统未与政府有关部门实现互联互通； （十）生产、储存、使用危险化学品的单位未在作业场所和安全设施、设备上设置明显的安全警示标志，或者未在作业场所设置通信、报警装置并处于适用状态； （十一）危险化学品专用储存场所未设专人负责管理，对储存的剧毒化学品以及储存数量构成重大危险源的其他危险化学品未实行双人收发、双人保管制度，或者收发记录的保存期限少于三年； （十二）储存危险化学品的单位未建立危险化学品出入库核查、登记制度； （十三）危险化学品专用储存场所未设置明显标志； （十四）研制开发单位将未经小试、中试、工业化试验的新工艺、新技术直接用于工业化生产，或者转让危险化学品新工艺、新技术时，未提供新工艺、新技术的安全论证报告及相关资料； （十五）使用危险化学品的单位未将其作业场所使用的化学品安全技术说明书、化学品安全标签提供给从业人员，或者未告知从业人员正确使用的方法、在紧急情况下应当采取的措施； （十六）危险化学品生产企业、经营企业经营没有化学品安全技术说明书、化学品安全标签的危险化学品，或者擅自更改化学品安全技术说明书、化学品安全标签； （十七）危险化学品生产企业、进口企业不办理危险化学品登记，或者发现其生产、进口的危险化学品有新的危险特性、其他登记内容发生变更，不办理危险化学品登记内容变更手续。 从事危险化学品仓储经营的港口经营人有前款规定情形的，由港口行政管理部门依照前款规定予以处理、处罚。储存剧毒化学品、易制爆危险化学品的专用储存场所未按照国家有关规定设置相应的实体防范、技术防范设施的，由公安机关依照前款规定予以处理、处罚。 生产、储存剧毒化学品、易制爆危险化学品的单位未设置治安保卫机构、配备专职治安保卫人员的，依照有关企业事业单位内部治安保卫法律、行政法规的规定处理、处罚。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百零二条", "text": "危险化学品包装物、容器生产企业销售未经检验或者经检验不合格的危险化学品包装物、容器的，由市场监督管理部门责令限期改正，处二十万元以上五十万元以下的罚款，有违法所得的，没收违法所得；逾期不改正的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款。 将未经检验合格的运输危险化学品的船舶及其配载的容器投入使用的，由海事管理机构依照前款规定予以处理、处罚。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百零三条", "text": "有下列情形之一的，由负有危险化学品安全监督管理职责的部门按照职责分工责令限期改正，处五万元以上十万元以下的罚款；逾期不改正的，责令停产停业整顿直至由原发证机关吊销其相关许可证件，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；相关许可证件被吊销的，由市场监督管理部门责令其办理经营范围变更登记或者吊销其营业执照： （一）未按照国家有关规定对危险化学品重大危险源登记建档，未进行定期检测、评估、监控，未制定应急预案，或者未建立重大危险源安全责任制； （二）对重复使用的危险化学品包装物、容器，在重复使用前不进行检查，或者使用存在安全隐患的危险化学品包装物、容器； （三）未根据其生产、储存的危险化学品的种类和危险特性，在作业场所设置相关安全设施、设备，或者未按照国家标准、行业标准或者国家有关规定对安全设施、设备进行经常性维护、保养； （四）未依照本法规定对其安全生产条件定期进行安全评价； （五）未将危险化学品储存在专用储存场所内，或者未将剧毒化学品以及储存数量构成重大危险源的其他危险化学品在专用储存场所内单独存放； （六）危险化学品的储存方式、方法或者储存数量不符合国家标准或者国家有关规定； （七）危险化学品专用储存场所不符合国家标准、行业标准的要求； （八）未对危险化学品专用储存场所的安全设施、设备定期进行检测、检验，或者经检测、检验不合格，没有停止使用并按照规定予以维修或者更换； （九）生产、储存危险化学品的企业以及使用危险化学品从事生产的企业未建立安全风险分级管控制度，未开展安全风险辨识评估，未按照安全风险分级采取相应安全管控措施，或者工艺、设施、设备、原料等发生变更时未重新进行安全风险辨识评估。 从事危险化学品仓储经营的港口经营人有前款规定情形的，由港口行政管理部门依照前款规定予以处理、处罚。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百零四条", "text": "有下列情形之一的，由公安机关责令限期改正，可以处二万元以上十万元以下的罚款；逾期不改正的，处十万元以上二十万元以下的罚款，对直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款： （一）生产、储存、使用剧毒化学品、易制爆危险化学品的单位不如实记录其生产、储存、使用的剧毒化学品、易制爆危险化学品的品种、数量、流向； （二）生产、储存、使用剧毒化学品、易制爆危险化学品的单位发现剧毒化学品、易制爆危险化学品丢失或者被盗，不立即向公安机关报告； （三）储存剧毒化学品的单位未将剧毒化学品的储存数量、储存地点以及管理人员的情况报所在地县级人民政府公安机关备案； （四）危险化学品生产企业、经营企业不如实记录剧毒化学品、易制爆危险化学品购买单位的名称、地址，经办人的姓名、身份证号码以及所购买的剧毒化学品、易制爆危险化学品的品种、数量、用途，或者保存销售记录和相关材料的时间少于三年； （五）剧毒化学品、易制爆危险化学品的销售企业、购买单位未在规定的时限内将所销售、购买的剧毒化学品、易制爆危险化学品的品种、数量以及流向信息报所在地县级人民政府公安机关备案； （六）使用剧毒化学品、易制爆危险化学品的单位依照本法规定转让其购买的剧毒化学品、易制爆危险化学品，未将有关情况在转让后三日内向所在地县级人民政府公安机关备案。 生产、储存危险化学品的企业，使用危险化学品从事生产的企业，或者在港区内储存、装卸危险化学品的企业未依照本法规定将安全评价报告以及整改方案的落实情况报所在地县级人民政府应急管理部门或者港口行政管理部门备案的，分别由应急管理部门或者港口行政管理部门依照前款规定予以处理、处罚。 未依照本法规定将剧毒化学品以及危险化学品重大危险源的情况报应急管理部门、港口行政管理部门或者消防救援机构备案的，分别由应急管理部门、港口行政管理部门或者消防救援机构依照本条第一款的规定予以处理、处罚。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百零五条", "text": "生产、储存、使用危险化学品的单位转产、停产、停业或者解散，未采取有效措施及时、妥善处置其危险化学品生产装置、储存设施以及库存的危险化学品，或者丢弃危险化学品的，由应急管理部门责令限期改正，处十万元以上五十万元以下的罚款。 生产、储存、使用危险化学品的单位转产、停产、停业或者解散，未依照本法规定将其危险化学品生产装置、储存设施以及库存危险化学品的处置方案报有关部门备案的，分别由有关部门责令限期改正，可以处二万元以上十万元以下的罚款；逾期不改正的，处十万元以上二十万元以下的罚款。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百零六条", "text": "危险化学品经营企业向未经许可违法从事危险化学品生产、经营活动的企业采购危险化学品的，由应急管理部门责令限期改正，处二十万元以上五十万元以下的罚款；逾期不改正的，责令停业整顿直至由原发证机关吊销其危险化学品经营许可证，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；相关许可证件被吊销的，由市场监督管理部门责令其办理经营范围变更登记或者吊销其营业执照。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百零七条", "text": "危险化学品生产企业、经营企业有下列情形之一的，由应急管理部门责令限期改正，没收违法所得，并处二十万元以上五十万元以下的罚款；逾期不改正的，责令停产停业整顿直至由原发证机关吊销其危险化学品安全生产许可证、危险化学品经营许可证，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；相关许可证件被吊销的，由市场监督管理部门责令其办理经营范围变更登记或者吊销其营业执照： （一）向不具有本法"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十八条", "text": "第一款、第二款规定的相关许可证件或者证明文件的单位销售剧毒化学品、易制爆危险化学品； （二）不按照剧毒化学品购买许可证载明的品种、数量销售剧毒化学品； （三）向个人销售剧毒化学品（属于剧毒化学品的农药除外）、易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）。 不具有本法"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十八条", "text": "第一款、第二款规定的相关许可证件或者证明文件的单位购买剧毒化学品、易制爆危险化学品，或者个人购买剧毒化学品（属于剧毒化学品的农药除外）、易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）的，由公安机关没收所购买的剧毒化学品、易制爆危险化学品，可以并处二万元以上五万元以下的罚款。 使用剧毒化学品、易制爆危险化学品的单位出借或者向不具有本法"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第五十八条", "text": "第一款、第二款规定的相关许可证件或者证明文件的单位转让其购买的剧毒化学品、易制爆危险化学品，或者向个人转让其购买的剧毒化学品（属于剧毒化学品的农药除外）、易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）的，由公安机关责令限期改正，没收违法所得，并处十万元以上五十万元以下的罚款；逾期不改正的，责令停产停业整顿。 违反本法规定，在互联网上销售剧毒化学品、易制爆危险化学品的，由负有危险化学品安全监督管理职责的部门按照职责分工依照本条第一款的规定予以处理、处罚。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百零八条", "text": "未依法取得危险货物道路运输许可、相应危险货物水路运输许可或者未办理备案手续，从事危险化学品道路运输、水路运输的，分别依照有关道路运输、水路运输的法律、行政法规的规定处理、处罚。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百零九条", "text": "有下列情形之一的，由交通运输主管部门责令限期改正，处五万元以上五十万元以下的罚款；逾期不改正的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款： （一）危险化学品道路运输企业、水路运输企业的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员未取得从业资格上岗作业； （二）危险化学品的装卸作业未遵守安全作业标准、规程和制度，或者未在装卸管理人员的现场指挥或者监控下进行； （三）水路运输危险化学品的集装箱装箱作业未在集装箱装箱现场检查员的指挥或者监控下进行，或者不符合积载、隔离的规范和要求； （四）运输危险化学品，未根据危险化学品的危险特性采取相应的安全防护措施，或者未配备必要的防护用品和应急救援器材、装备、设备和物资； （五）危险化学品道路运输企业未对运输车辆、驾驶人员的作业状态进行实时监控、管理； （六）使用未依法取得危险货物适装证书的船舶，通过内河运输危险化学品； （七）通过内河运输危险化学品的承运人违反国务院交通运输主管部门对单船运输的危险化学品数量的限制性规定运输危险化学品； （八）用于危险化学品运输作业的内河码头、泊位不符合国家有关安全规范，未与饮用水取水口保持国家规定的安全距离，或者未按照国家有关规定验收合格投入使用； （九）托运人未向承运人提交电子或者纸质的危险货物托运清单说明所托运的危险化学品相关情况，未提供化学品安全技术说明书，或者未按照国家有关规定对所托运的危险化学品妥善包装并在危险化学品包装上粘贴、印刷、拴挂与包装内危险化学品相符的化学品安全标签； （十）运输危险化学品需要添加抑制剂或者稳定剂，托运人未按照规定添加或者未将有关情况告知承运人。 水路运输企业的申报人员、集装箱装箱现场检查员违反法律、行政法规或者规章关于危险化学品安全管理规定的，由交通运输主管部门责令限期改正，给予警告；情节严重的，责令暂停从业活动直至吊销其从业资格。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百一十条", "text": "有下列情形之一的，由交通运输主管部门责令限期改正，处二十万元以上三十万元以下的罚款，有违法所得的，没收违法所得；逾期不改正的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款： （一）委托未依法取得相应许可或者办理备案手续的单位或者个人承运危险化学品； （二）通过内河封闭水域运输剧毒化学品； （三）通过内河水域运输国家规定禁止通过内河运输的危险化学品； （四）载运危险化学品的船舶在内河航行时通过通航建筑物，未提前向通航建筑物运行单位报告，或者不服从交通运输主管部门管理； （五）在托运的普通货物中夹带危险化学品，或者将危险化学品匿报、谎报为普通货物托运。 邮政企业、快递企业收寄危险化学品的，依照《中华人民共和国邮政法》的规定处理、处罚。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百一十一条", "text": "有下列情形之一的，由公安机关责令限期改正，处十万元以上二十万元以下的罚款： （一）超过运输车辆的核定载质量装载危险化学品； （二）使用安全技术条件不符合国家标准要求的车辆运输危险化学品； （三）运输危险化学品的车辆未经公安机关批准进入危险化学品运输车辆限制通行的区域； （四）未取得剧毒化学品道路运输通行证，通过道路运输剧毒化学品。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百一十二条", "text": "有下列情形之一的，由公安机关责令限期改正，处五万元以上十万元以下的罚款： （一）危险化学品运输车辆未悬挂、喷涂或者遮挡、拆除警示标志，或者警示标志不符合国家标准要求； （二）通过道路运输危险化学品，不按照要求配备押运人员； （三）运输剧毒化学品或者易制爆危险化学品途中需要较长时间停车，驾驶人员、押运人员不向当地公安机关报告； （四）剧毒化学品、易制爆危险化学品在道路运输途中丢失、被盗、被抢或者出现流散、泄漏等情况，驾驶人员、押运人员不采取相应的警示措施和安全措施，或者不向当地公安机关报告。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百一十三条", "text": "对发生交通事故负有全部责任或者主要责任的危险化学品道路运输企业，由公安机关责令消除安全隐患，未消除安全隐患的危险化学品运输车辆，禁止上道路行驶。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百一十四条", "text": "有下列情形之一的，由交通运输主管部门责令限期改正，可以处五万元以下的罚款；逾期不改正的，处五万元以上十万元以下的罚款： （一）危险化学品道路运输企业、水路运输企业未配备专职安全生产管理人员； （二）用于危险化学品运输作业的内河码头、泊位的管理单位未制定码头、泊位危险化学品事故应急预案，或者未为码头、泊位配备充足、有效的应急救援器材、装备、设备和物资。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百一十五条", "text": "有下列情形之一的，依照有关内河交通安全管理法律、行政法规的规定处理、处罚： （一）通过内河运输危险化学品的水路运输企业未制定运输船舶危险化学品事故应急救援预案，或者未为运输船舶配备充足、有效的应急救援器材、装备、设备和物资； （二）通过内河运输危险化学品的船舶的所有人或者经营人未取得船舶污染损害责任保险证书或者财务担保证明； （三）船舶载运危险化学品进出内河港口，未依照法律、行政法规的规定报告海事管理机构并经其同意； （四）载运危险化学品的船舶在内河航行、装卸或者停泊，未悬挂专用的警示标志，未按照规定显示专用信号，或者未按照规定申请引航。 未向港口行政管理部门报告并经其同意，在内河港口内进行危险化学品的装卸、过驳作业的，依照《中华人民共和国港口法》的规定处理、处罚。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百一十六条", "text": "伪造、变造或者出租、出借、转让危险化学品安全生产许可证、工业产品生产许可证，或者使用伪造、变造的危险化学品安全生产许可证、工业产品生产许可证的，分别依照有关安全生产许可、工业产品生产许可法律、行政法规的规定处理、处罚。 伪造、变造或者出租、出借、转让本法规定的其他许可证，或者使用伪造、变造的本法规定的其他许可证的，分别由相关许可证的颁发管理机关处二十万元以上三十万元以下的罚款，有违法所得的，没收违法所得。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百一十七条", "text": "危险化学品单位发生危险化学品事故，其主要负责人不立即组织救援或者不立即向有关部门报告的，依照有关生产安全事故报告和调查处理法律、行政法规的规定处理、处罚。 危险化学品单位的主要负责人未履行安全生产管理职责，导致发生生产安全事故的，依照《中华人民共和国安全生产法》的规定限制从业。 危险化学品单位发生危险化学品事故，造成他人人身伤害或者财产损失的，依法承担赔偿责任。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百一十八条", "text": "发生危险化学品事故，有关地方人民政府及其有关部门不立即组织实施救援，或者不采取必要的应急处置措施减少事故损失，防止事故蔓延、扩大的，对负有责任的领导人员和直接责任人员依法给予处分。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百一十九条", "text": "负有危险化学品安全监督管理职责的部门的工作人员，在危险化学品安全监督管理工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百二十条", "text": "违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。 第十章 附 则"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百二十一条", "text": "监控化学品、属于危险化学品的药品和农药的安全管理，依照本法的规定执行；法律、行政法规另有规定的，依照其规定。 民用爆炸物品、烟花爆竹、放射性物品、核能物质以及用于国防科研生产的危险化学品的安全管理，不适用本法。 法律、行政法规对燃气的安全管理另有规定的，依照其规定。 危险化学品容器属于特种设备的，其安全管理依照有关特种设备安全的法律、行政法规的规定执行。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百二十二条", "text": "危险化学品的进出口管理，依照有关对外贸易的法律、行政法规、规章的规定执行；出口危险化学品涉及《中华人民共和国出口管制法》规定的管制物项的，依照有关出口管制的法律、行政法规、规章的规定执行；进口的危险化学品的储存、使用、经营、运输的安全管理，依照本法的规定执行。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百二十三条", "text": "公众发现、捡拾的无主危险化学品，由公安机关或者应急管理部门接收。有关部门接收或者依法没收的危险化学品，需要进行处置的，交由生态环境主管部门组织其认定的专业单位进行处置，或者交由有关危险化学品生产企业进行处置。处置所需费用由政府负担。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百二十四条", "text": "化学品的危险特性尚未确定的，由国务院应急管理、生态环境、卫生健康部门分别负责组织对该化学品的物理危险性、生态环境危害性、毒理特性进行鉴定。根据鉴定结果需要调整危险化学品目录的，依照本法"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第三条", "text": "第二款的规定办理。 化学品的危险特性尚未确定的，任何单位和个人不得擅自从事该化学品的生产、储存、使用、经营、运输等活动。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百二十五条", "text": "港区内危险化学品生产和使用危险化学品的生产装置及相连储罐部分，由应急管理部门负责安全监督管理；仅与危险化学品码头相连的储罐部分，由港口行政管理部门负责安全监督管理。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百二十六条", "text": "中国人民解放军、中国人民武装警察部队的危险化学品安全管理，依照本法有关规定和中央军事委员会的规定执行。"}, {"law": "中华人民共和国危险化学品安全法_20251227.docx", "no": "第一百二十七条", "text": "本法自2026年5月1日起施行。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一条", "text": "为了加强安全生产工作，防止和减少生产安全事故，保障人民群众生命和财产安全，促进经济社会持续健康发展，制定本法。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第二条", "text": "在中华人民共和国领域内从事生产经营活动的单位（以下统称生产经营单位）的安全生产，适用本法；有关法律、行政法规对消防安全和道路交通安全、铁路交通安全、水上交通安全、民用航空安全以及核与辐射安全、特种设备安全另有规定的，适用其规定。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第三条", "text": "安全生产工作坚持中国共产党的领导。 安全生产工作应当以人为本，坚持人民至上、生命至上，把保护人民生命安全摆在首位，树牢安全发展理念，坚持安全第一、预防为主、综合治理的方针，从源头上防范化解重大安全风险。 安全生产工作实行管行业必须管安全、管业务必须管安全、管生产经营必须管安全，强化和落实生产经营单位主体责任与政府监管责任，建立生产经营单位负责、职工参与、政府监管、行业自律和社会监督的机制。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第四条", "text": "生产经营单位必须遵守本法和其他有关安全生产的法律、法规，加强安全生产管理，建立健全全员安全生产责任制和安全生产规章制度，加大对安全生产资金、物资、技术、人员的投入保障力度，改善安全生产条件，加强安全生产标准化、信息化建设，构建安全风险分级管控和隐患排查治理双重预防机制，健全风险防范化解机制，提高安全生产水平，确保安全生产。 平台经济等新兴行业、领域的生产经营单位应当根据本行业、领域的特点，建立健全并落实全员安全生产责任制，加强从业人员安全生产教育和培训，履行本法和其他法律、法规规定的有关安全生产义务。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第五条", "text": "生产经营单位的主要负责人是本单位安全生产第一责任人，对本单位的安全生产工作全面负责。其他负责人对职责范围内的安全生产工作负责。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第六条", "text": "生产经营单位的从业人员有依法获得安全生产保障的权利，并应当依法履行安全生产方面的义务。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第七条", "text": "工会依法对安全生产工作进行监督。 生产经营单位的工会依法组织职工参加本单位安全生产工作的民主管理和民主监督，维护职工在安全生产方面的合法权益。生产经营单位制定或者修改有关安全生产的规章制度，应当听取工会的意见。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第八条", "text": "国务院和县级以上地方各级人民政府应当根据国民经济和社会发展规划制定安全生产规划，并组织实施。安全生产规划应当与国土空间规划等相关规划相衔接。 各级人民政府应当加强安全生产基础设施建设和安全生产监管能力建设，所需经费列入本级预算。 县级以上地方各级人民政府应当组织有关部门建立完善安全风险评估与论证机制，按照安全风险管控要求，进行产业规划和空间布局，并对位置相邻、行业相近、业态相似的生产经营单位实施重大安全风险联防联控。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第九条", "text": "国务院和县级以上地方各级人民政府应当加强对安全生产工作的领导，建立健全安全生产工作协调机制，支持、督促各有关部门依法履行安全生产监督管理职责，及时协调、解决安全生产监督管理中存在的重大问题。 乡镇人民政府和街道办事处，以及开发区、工业园区、港区、风景区等应当明确负责安全生产监督管理的有关工作机构及其职责，加强安全生产监管力量建设，按照职责对本行政区域或者管理区域内生产经营单位安全生产状况进行监督检查，协助人民政府有关部门或者按照授权依法履行安全生产监督管理职责。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第十条", "text": "国务院应急管理部门依照本法，对全国安全生产工作实施综合监督管理；县级以上地方各级人民政府应急管理部门依照本法，对本行政区域内安全生产工作实施综合监督管理。 国务院交通运输、住房和城乡建设、水利、民航等有关部门依照本法和其他有关法律、行政法规的规定，在各自的职责范围内对有关行业、领域的安全生产工作实施监督管理；县级以上地方各级人民政府有关部门依照本法和其他有关法律、法规的规定，在各自的职责范围内对有关行业、领域的安全生产工作实施监督管理。对新兴行业、领域的安全生产监督管理职责不明确的，由县级以上地方各级人民政府按照业务相近的原则确定监督管理部门。 应急管理部门和对有关行业、领域的安全生产工作实施监督管理的部门，统称负有安全生产监督管理职责的部门。负有安全生产监督管理职责的部门应当相互配合、齐抓共管、信息共享、资源共用，依法加强安全生产监督管理工作。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第十一条", "text": "国务院有关部门应当按照保障安全生产的要求，依法及时制定有关的国家标准或者行业标准，并根据科技进步和经济发展适时修订。 生产经营单位必须执行依法制定的保障安全生产的国家标准或者行业标准。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第十二条", "text": "国务院有关部门按照职责分工负责安全生产强制性国家标准的项目提出、组织起草、征求意见、技术审查。国务院应急管理部门统筹提出安全生产强制性国家标准的立项计划。国务院标准化行政主管部门负责安全生产强制性国家标准的立项、编号、对外通报和授权批准发布工作。国务院标准化行政主管部门、有关部门依据法定职责对安全生产强制性国家标准的实施进行监督检查。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第十三条", "text": "各级人民政府及其有关部门应当采取多种形式，加强对有关安全生产的法律、法规和安全生产知识的宣传，增强全社会的安全生产意识。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第十四条", "text": "有关协会组织依照法律、行政法规和章程，为生产经营单位提供安全生产方面的信息、培训等服务，发挥自律作用，促进生产经营单位加强安全生产管理。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第十五条", "text": "依法设立的为安全生产提供技术、管理服务的机构，依照法律、行政法规和执业准则，接受生产经营单位的委托为其安全生产工作提供技术、管理服务。 生产经营单位委托前款规定的机构提供安全生产技术、管理服务的，保证安全生产的责任仍由本单位负责。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第十六条", "text": "国家实行生产安全事故责任追究制度，依照本法和有关法律、法规的规定，追究生产安全事故责任单位和责任人员的法律责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第十七条", "text": "县级以上各级人民政府应当组织负有安全生产监督管理职责的部门依法编制安全生产权力和责任清单，公开并接受社会监督。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第十八条", "text": "国家鼓励和支持安全生产科学技术研究和安全生产先进技术的推广应用，提高安全生产水平。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第十九条", "text": "国家对在改善安全生产条件、防止生产安全事故、参加抢险救护等方面取得显著成绩的单位和个人，给予奖励。 第二章 生产经营单位的安全生产保障"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第二十条", "text": "生产经营单位应当具备本法和有关法律、行政法规和国家标准或者行业标准规定的安全生产条件；不具备安全生产条件的，不得从事生产经营活动。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第二十一条", "text": "生产经营单位的主要负责人对本单位安全生产工作负有下列职责： （一）建立健全并落实本单位全员安全生产责任制，加强安全生产标准化建设； （二）组织制定并实施本单位安全生产规章制度和操作规程； （三）组织制定并实施本单位安全生产教育和培训计划； （四）保证本单位安全生产投入的有效实施； （五）组织建立并落实安全风险分级管控和隐患排查治理双重预防工作机制，督促、检查本单位的安全生产工作，及时消除生产安全事故隐患； （六）组织制定并实施本单位的生产安全事故应急救援预案； （七）及时、如实报告生产安全事故。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第二十二条", "text": "生产经营单位的全员安全生产责任制应当明确各岗位的责任人员、责任范围和考核标准等内容。 生产经营单位应当建立相应的机制，加强对全员安全生产责任制落实情况的监督考核，保证全员安全生产责任制的落实。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第二十三条", "text": "生产经营单位应当具备的安全生产条件所必需的资金投入，由生产经营单位的决策机构、主要负责人或者个人经营的投资人予以保证，并对由于安全生产所必需的资金投入不足导致的后果承担责任。 有关生产经营单位应当按照规定提取和使用安全生产费用，专门用于改善安全生产条件。安全生产费用在成本中据实列支。安全生产费用提取、使用和监督管理的具体办法由国务院财政部门会同国务院应急管理部门征求国务院有关部门意见后制定。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第二十四条", "text": "矿山、金属冶炼、建筑施工、运输单位和危险物品的生产、经营、储存、装卸单位，应当设置安全生产管理机构或者配备专职安全生产管理人员。 前款规定以外的其他生产经营单位，从业人员超过一百人的，应当设置安全生产管理机构或者配备专职安全生产管理人员；从业人员在一百人以下的，应当配备专职或者兼职的安全生产管理人员。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第二十五条", "text": "生产经营单位的安全生产管理机构以及安全生产管理人员履行下列职责： （一）组织或者参与拟订本单位安全生产规章制度、操作规程和生产安全事故应急救援预案； （二）组织或者参与本单位安全生产教育和培训，如实记录安全生产教育和培训情况； （三）组织开展危险源辨识和评估，督促落实本单位重大危险源的安全管理措施； （四）组织或者参与本单位应急救援演练； （五）检查本单位的安全生产状况，及时排查生产安全事故隐患，提出改进安全生产管理的建议； （六）制止和纠正违章指挥、强令冒险作业、违反操作规程的行为； （七）督促落实本单位安全生产整改措施。 生产经营单位可以设置专职安全生产分管负责人，协助本单位主要负责人履行安全生产管理职责。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第二十六条", "text": "生产经营单位的安全生产管理机构以及安全生产管理人员应当恪尽职守，依法履行职责。 生产经营单位作出涉及安全生产的经营决策，应当听取安全生产管理机构以及安全生产管理人员的意见。 生产经营单位不得因安全生产管理人员依法履行职责而降低其工资、福利等待遇或者解除与其订立的劳动合同。 危险物品的生产、储存单位以及矿山、金属冶炼单位的安全生产管理人员的任免，应当告知主管的负有安全生产监督管理职责的部门。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第二十七条", "text": "生产经营单位的主要负责人和安全生产管理人员必须具备与本单位所从事的生产经营活动相应的安全生产知识和管理能力。 危险物品的生产、经营、储存、装卸单位以及矿山、金属冶炼、建筑施工、运输单位的主要负责人和安全生产管理人员，应当由主管的负有安全生产监督管理职责的部门对其安全生产知识和管理能力考核合格。考核不得收费。 危险物品的生产、储存、装卸单位以及矿山、金属冶炼单位应当有注册安全工程师从事安全生产管理工作。鼓励其他生产经营单位聘用注册安全工程师从事安全生产管理工作。注册安全工程师按专业分类管理，具体办法由国务院人力资源和社会保障部门、国务院应急管理部门会同国务院有关部门制定。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第二十八条", "text": "生产经营单位应当对从业人员进行安全生产教育和培训，保证从业人员具备必要的安全生产知识，熟悉有关的安全生产规章制度和安全操作规程，掌握本岗位的安全操作技能，了解事故应急处理措施，知悉自身在安全生产方面的权利和义务。未经安全生产教育和培训合格的从业人员，不得上岗作业。 生产经营单位使用被派遣劳动者的，应当将被派遣劳动者纳入本单位从业人员统一管理，对被派遣劳动者进行岗位安全操作规程和安全操作技能的教育和培训。劳务派遣单位应当对被派遣劳动者进行必要的安全生产教育和培训。 生产经营单位接收中等职业学校、高等学校学生实习的，应当对实习学生进行相应的安全生产教育和培训，提供必要的劳动防护用品。学校应当协助生产经营单位对实习学生进行安全生产教育和培训。 生产经营单位应当建立安全生产教育和培训档案，如实记录安全生产教育和培训的时间、内容、参加人员以及考核结果等情况。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第二十九条", "text": "生产经营单位采用新工艺、新技术、新材料或者使用新设备，必须了解、掌握其安全技术特性，采取有效的安全防护措施，并对从业人员进行专门的安全生产教育和培训。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第三十条", "text": "生产经营单位的特种作业人员必须按照国家有关规定经专门的安全作业培训，取得相应资格，方可上岗作业。 特种作业人员的范围由国务院应急管理部门会同国务院有关部门确定。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第三十一条", "text": "生产经营单位新建、改建、扩建工程项目（以下统称建设项目）的安全设施，必须与主体工程同时设计、同时施工、同时投入生产和使用。安全设施投资应当纳入建设项目概算。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第三十二条", "text": "矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目，应当按照国家有关规定进行安全评价。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第三十三条", "text": "建设项目安全设施的设计人、设计单位应当对安全设施设计负责。 矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目的安全设施设计应当按照国家有关规定报经有关部门审查，审查部门及其负责审查的人员对审查结果负责。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第三十四条", "text": "矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目的施工单位必须按照批准的安全设施设计施工，并对安全设施的工程质量负责。 矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目竣工投入生产或者使用前，应当由建设单位负责组织对安全设施进行验收；验收合格后，方可投入生产和使用。负有安全生产监督管理职责的部门应当加强对建设单位验收活动和验收结果的监督核查。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第三十五条", "text": "生产经营单位应当在有较大危险因素的生产经营场所和有关设施、设备上，设置明显的安全警示标志。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第三十六条", "text": "安全设备的设计、制造、安装、使用、检测、维修、改造和报废，应当符合国家标准或者行业标准。 生产经营单位必须对安全设备进行经常性维护、保养，并定期检测，保证正常运转。维护、保养、检测应当作好记录，并由有关人员签字。 生产经营单位不得关闭、破坏直接关系生产安全的监控、报警、防护、救生设备、设施，或者篡改、隐瞒、销毁其相关数据、信息。 餐饮等行业的生产经营单位使用燃气的，应当安装可燃气体报警装置，并保障其正常使用。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第三十七条", "text": "生产经营单位使用的危险物品的容器、运输工具，以及涉及人身安全、危险性较大的海洋石油开采特种设备和矿山井下特种设备，必须按照国家有关规定，由专业生产单位生产，并经具有专业资质的检测、检验机构检测、检验合格，取得安全使用证或者安全标志，方可投入使用。检测、检验机构对检测、检验结果负责。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第三十八条", "text": "国家对严重危及生产安全的工艺、设备实行淘汰制度，具体目录由国务院应急管理部门会同国务院有关部门制定并公布。法律、行政法规对目录的制定另有规定的，适用其规定。 省、自治区、直辖市人民政府可以根据本地区实际情况制定并公布具体目录，对前款规定以外的危及生产安全的工艺、设备予以淘汰。 生产经营单位不得使用应当淘汰的危及生产安全的工艺、设备。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第三十九条", "text": "生产、经营、运输、储存、使用危险物品或者处置废弃危险物品的，由有关主管部门依照有关法律、法规的规定和国家标准或者行业标准审批并实施监督管理。 生产经营单位生产、经营、运输、储存、使用危险物品或者处置废弃危险物品，必须执行有关法律、法规和国家标准或者行业标准，建立专门的安全管理制度，采取可靠的安全措施，接受有关主管部门依法实施的监督管理。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第四十条", "text": "生产经营单位对重大危险源应当登记建档，进行定期检测、评估、监控，并制定应急预案，告知从业人员和相关人员在紧急情况下应当采取的应急措施。 生产经营单位应当按照国家有关规定将本单位重大危险源及有关安全措施、应急措施报有关地方人民政府应急管理部门和有关部门备案。有关地方人民政府应急管理部门和有关部门应当通过相关信息系统实现信息共享。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第四十一条", "text": "生产经营单位应当建立安全风险分级管控制度，按照安全风险分级采取相应的管控措施。 生产经营单位应当建立健全并落实生产安全事故隐患排查治理制度，采取技术、管理措施，及时发现并消除事故隐患。事故隐患排查治理情况应当如实记录，并通过职工大会或者职工代表大会、信息公示栏等方式向从业人员通报。其中，重大事故隐患排查治理情况应当及时向负有安全生产监督管理职责的部门和职工大会或者职工代表大会报告。 县级以上地方各级人民政府负有安全生产监督管理职责的部门应当将重大事故隐患纳入相关信息系统，建立健全重大事故隐患治理督办制度，督促生产经营单位消除重大事故隐患。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第四十二条", "text": "生产、经营、储存、使用危险物品的车间、商店、仓库不得与员工宿舍在同一座建筑物内，并应当与员工宿舍保持安全距离。 生产经营场所和员工宿舍应当设有符合紧急疏散要求、标志明显、保持畅通的出口、疏散通道。禁止占用、锁闭、封堵生产经营场所或者员工宿舍的出口、疏散通道。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第四十三条", "text": "生产经营单位进行爆破、吊装、动火、临时用电以及国务院应急管理部门会同国务院有关部门规定的其他危险作业，应当安排专门人员进行现场安全管理，确保操作规程的遵守和安全措施的落实。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第四十四条", "text": "生产经营单位应当教育和督促从业人员严格执行本单位的安全生产规章制度和安全操作规程；并向从业人员如实告知作业场所和工作岗位存在的危险因素、防范措施以及事故应急措施。 生产经营单位应当关注从业人员的身体、心理状况和行为习惯，加强对从业人员的心理疏导、精神慰藉，严格落实岗位安全生产责任，防范从业人员行为异常导致事故发生。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第四十五条", "text": "生产经营单位必须为从业人员提供符合国家标准或者行业标准的劳动防护用品，并监督、教育从业人员按照使用规则佩戴、使用。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第四十六条", "text": "生产经营单位的安全生产管理人员应当根据本单位的生产经营特点，对安全生产状况进行经常性检查；对检查中发现的安全问题，应当立即处理；不能处理的，应当及时报告本单位有关负责人，有关负责人应当及时处理。检查及处理情况应当如实记录在案。 生产经营单位的安全生产管理人员在检查中发现重大事故隐患，依照前款规定向本单位有关负责人报告，有关负责人不及时处理的，安全生产管理人员可以向主管的负有安全生产监督管理职责的部门报告，接到报告的部门应当依法及时处理。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第四十七条", "text": "生产经营单位应当安排用于配备劳动防护用品、进行安全生产培训的经费。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第四十八条", "text": "两个以上生产经营单位在同一作业区域内进行生产经营活动，可能危及对方生产安全的，应当签订安全生产管理协议，明确各自的安全生产管理职责和应当采取的安全措施，并指定专职安全生产管理人员进行安全检查与协调。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第四十九条", "text": "生产经营单位不得将生产经营项目、场所、设备发包或者出租给不具备安全生产条件或者相应资质的单位或者个人。 生产经营项目、场所发包或者出租给其他单位的，生产经营单位应当与承包单位、承租单位签订专门的安全生产管理协议，或者在承包合同、租赁合同中约定各自的安全生产管理职责；生产经营单位对承包单位、承租单位的安全生产工作统一协调、管理，定期进行安全检查，发现安全问题的，应当及时督促整改。 矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目的施工单位应当加强对施工项目的安全管理，不得倒卖、出租、出借、挂靠或者以其他形式非法转让施工资质，不得将其承包的全部建设工程转包给第三人或者将其承包的全部建设工程支解以后以分包的名义分别转包给第三人，不得将工程分包给不具备相应资质条件的单位。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第五十条", "text": "生产经营单位发生生产安全事故时，单位的主要负责人应当立即组织抢救，并不得在事故调查处理期间擅离职守。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第五十一条", "text": "生产经营单位必须依法参加工伤保险，为从业人员缴纳保险费。 国家鼓励生产经营单位投保安全生产责任保险；属于国家规定的高危行业、领域的生产经营单位，应当投保安全生产责任保险。具体范围和实施办法由国务院应急管理部门会同国务院财政部门、国务院保险监督管理机构和相关行业主管部门制定。 第三章 从业人员的安全生产权利义务"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第五十二条", "text": "生产经营单位与从业人员订立的劳动合同，应当载明有关保障从业人员劳动安全、防止职业危害的事项，以及依法为从业人员办理工伤保险的事项。 生产经营单位不得以任何形式与从业人员订立协议，免除或者减轻其对从业人员因生产安全事故伤亡依法应承担的责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第五十三条", "text": "生产经营单位的从业人员有权了解其作业场所和工作岗位存在的危险因素、防范措施及事故应急措施，有权对本单位的安全生产工作提出建议。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第五十四条", "text": "从业人员有权对本单位安全生产工作中存在的问题提出批评、检举、控告；有权拒绝违章指挥和强令冒险作业。 生产经营单位不得因从业人员对本单位安全生产工作提出批评、检举、控告或者拒绝违章指挥、强令冒险作业而降低其工资、福利等待遇或者解除与其订立的劳动合同。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第五十五条", "text": "从业人员发现直接危及人身安全的紧急情况时，有权停止作业或者在采取可能的应急措施后撤离作业场所。 生产经营单位不得因从业人员在前款紧急情况下停止作业或者采取紧急撤离措施而降低其工资、福利等待遇或者解除与其订立的劳动合同。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第五十六条", "text": "生产经营单位发生生产安全事故后，应当及时采取措施救治有关人员。 因生产安全事故受到损害的从业人员，除依法享有工伤保险外，依照有关民事法律尚有获得赔偿的权利的，有权提出赔偿要求。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第五十七条", "text": "从业人员在作业过程中，应当严格落实岗位安全责任，遵守本单位的安全生产规章制度和操作规程，服从管理，正确佩戴和使用劳动防护用品。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第五十八条", "text": "从业人员应当接受安全生产教育和培训，掌握本职工作所需的安全生产知识，提高安全生产技能，增强事故预防和应急处理能力。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第五十九条", "text": "从业人员发现事故隐患或者其他不安全因素，应当立即向现场安全生产管理人员或者本单位负责人报告；接到报告的人员应当及时予以处理。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第六十条", "text": "工会有权对建设项目的安全设施与主体工程同时设计、同时施工、同时投入生产和使用进行监督，提出意见。 工会对生产经营单位违反安全生产法律、法规，侵犯从业人员合法权益的行为，有权要求纠正；发现生产经营单位违章指挥、强令冒险作业或者发现事故隐患时，有权提出解决的建议，生产经营单位应当及时研究答复；发现危及从业人员生命安全的情况时，有权向生产经营单位建议组织从业人员撤离危险场所，生产经营单位必须立即作出处理。 工会有权依法参加事故调查，向有关部门提出处理意见，并要求追究有关人员的责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第六十一条", "text": "生产经营单位使用被派遣劳动者的，被派遣劳动者享有本法规定的从业人员的权利，并应当履行本法规定的从业人员的义务。 第四章 安全生产的监督管理"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第六十二条", "text": "县级以上地方各级人民政府应当根据本行政区域内的安全生产状况，组织有关部门按照职责分工，对本行政区域内容易发生重大生产安全事故的生产经营单位进行严格检查。 应急管理部门应当按照分类分级监督管理的要求，制定安全生产年度监督检查计划，并按照年度监督检查计划进行监督检查，发现事故隐患，应当及时处理。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第六十三条", "text": "负有安全生产监督管理职责的部门依照有关法律、法规的规定，对涉及安全生产的事项需要审查批准（包括批准、核准、许可、注册、认证、颁发证照等，下同）或者验收的，必须严格依照有关法律、法规和国家标准或者行业标准规定的安全生产条件和程序进行审查；不符合有关法律、法规和国家标准或者行业标准规定的安全生产条件的，不得批准或者验收通过。对未依法取得批准或者验收合格的单位擅自从事有关活动的，负责行政审批的部门发现或者接到举报后应当立即予以取缔，并依法予以处理。对已经依法取得批准的单位，负责行政审批的部门发现其不再具备安全生产条件的，应当撤销原批准。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第六十四条", "text": "负有安全生产监督管理职责的部门对涉及安全生产的事项进行审查、验收，不得收取费用；不得要求接受审查、验收的单位购买其指定品牌或者指定生产、销售单位的安全设备、器材或者其他产品。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第六十五条", "text": "应急管理部门和其他负有安全生产监督管理职责的部门依法开展安全生产行政执法工作，对生产经营单位执行有关安全生产的法律、法规和国家标准或者行业标准的情况进行监督检查，行使以下职权： （一）进入生产经营单位进行检查，调阅有关资料，向有关单位和人员了解情况； （二）对检查中发现的安全生产违法行为，当场予以纠正或者要求限期改正；对依法应当给予行政处罚的行为，依照本法和其他有关法律、行政法规的规定作出行政处罚决定； （三）对检查中发现的事故隐患，应当责令立即排除；重大事故隐患排除前或者排除过程中无法保证安全的，应当责令从危险区域内撤出作业人员，责令暂时停产停业或者停止使用相关设施、设备；重大事故隐患排除后，经审查同意，方可恢复生产经营和使用； （四）对有根据认为不符合保障安全生产的国家标准或者行业标准的设施、设备、器材以及违法生产、储存、使用、经营、运输的危险物品予以查封或者扣押，对违法生产、储存、使用、经营危险物品的作业场所予以查封，并依法作出处理决定。 监督检查不得影响被检查单位的正常生产经营活动。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第六十六条", "text": "生产经营单位对负有安全生产监督管理职责的部门的监督检查人员（以下统称安全生产监督检查人员）依法履行监督检查职责，应当予以配合，不得拒绝、阻挠。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第六十七条", "text": "安全生产监督检查人员应当忠于职守，坚持原则，秉公执法。 安全生产监督检查人员执行监督检查任务时，必须出示有效的行政执法证件；对涉及被检查单位的技术秘密和业务秘密，应当为其保密。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第六十八条", "text": "安全生产监督检查人员应当将检查的时间、地点、内容、发现的问题及其处理情况，作出书面记录，并由检查人员和被检查单位的负责人签字；被检查单位的负责人拒绝签字的，检查人员应当将情况记录在案，并向负有安全生产监督管理职责的部门报告。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第六十九条", "text": "负有安全生产监督管理职责的部门在监督检查中，应当互相配合，实行联合检查；确需分别进行检查的，应当互通情况，发现存在的安全问题应当由其他有关部门进行处理的，应当及时移送其他有关部门并形成记录备查，接受移送的部门应当及时进行处理。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第七十条", "text": "负有安全生产监督管理职责的部门依法对存在重大事故隐患的生产经营单位作出停产停业、停止施工、停止使用相关设施或者设备的决定，生产经营单位应当依法执行，及时消除事故隐患。生产经营单位拒不执行，有发生生产安全事故的现实危险的，在保证安全的前提下，经本部门主要负责人批准，负有安全生产监督管理职责的部门可以采取通知有关单位停止供电、停止供应民用爆炸物品等措施，强制生产经营单位履行决定。通知应当采用书面形式，有关单位应当予以配合。 负有安全生产监督管理职责的部门依照前款规定采取停止供电措施，除有危及生产安全的紧急情形外，应当提前二十四小时通知生产经营单位。生产经营单位依法履行行政决定、采取相应措施消除事故隐患的，负有安全生产监督管理职责的部门应当及时解除前款规定的措施。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第七十一条", "text": "监察机关依照监察法的规定，对负有安全生产监督管理职责的部门及其工作人员履行安全生产监督管理职责实施监察。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第七十二条", "text": "承担安全评价、认证、检测、检验职责的机构应当具备国家规定的资质条件，并对其作出的安全评价、认证、检测、检验结果的合法性、真实性负责。资质条件由国务院应急管理部门会同国务院有关部门制定。 承担安全评价、认证、检测、检验职责的机构应当建立并实施服务公开和报告公开制度，不得租借资质、挂靠、出具虚假报告。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第七十三条", "text": "负有安全生产监督管理职责的部门应当建立举报制度，公开举报电话、信箱或者电子邮件地址等网络举报平台，受理有关安全生产的举报；受理的举报事项经调查核实后，应当形成书面材料；需要落实整改措施的，报经有关负责人签字并督促落实。对不属于本部门职责，需要由其他有关部门进行调查处理的，转交其他有关部门处理。 涉及人员死亡的举报事项，应当由县级以上人民政府组织核查处理。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第七十四条", "text": "任何单位或者个人对事故隐患或者安全生产违法行为，均有权向负有安全生产监督管理职责的部门报告或者举报。 因安全生产违法行为造成重大事故隐患或者导致重大事故，致使国家利益或者社会公共利益受到侵害的，人民检察院可以根据民事诉讼法、行政诉讼法的相关规定提起公益诉讼。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第七十五条", "text": "居民委员会、村民委员会发现其所在区域内的生产经营单位存在事故隐患或者安全生产违法行为时，应当向当地人民政府或者有关部门报告。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第七十六条", "text": "县级以上各级人民政府及其有关部门对报告重大事故隐患或者举报安全生产违法行为的有功人员，给予奖励。具体奖励办法由国务院应急管理部门会同国务院财政部门制定。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第七十七条", "text": "新闻、出版、广播、电影、电视等单位有进行安全生产公益宣传教育的义务，有对违反安全生产法律、法规的行为进行舆论监督的权利。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第七十八条", "text": "负有安全生产监督管理职责的部门应当建立安全生产违法行为信息库，如实记录生产经营单位及其有关从业人员的安全生产违法行为信息；对违法行为情节严重的生产经营单位及其有关从业人员，应当及时向社会公告，并通报行业主管部门、投资主管部门、自然资源主管部门、生态环境主管部门、证券监督管理机构以及有关金融机构。有关部门和机构应当对存在失信行为的生产经营单位及其有关从业人员采取加大执法检查频次、暂停项目审批、上调有关保险费率、行业或者职业禁入等联合惩戒措施，并向社会公示。 负有安全生产监督管理职责的部门应当加强对生产经营单位行政处罚信息的及时归集、共享、应用和公开，对生产经营单位作出处罚决定后七个工作日内在监督管理部门公示系统予以公开曝光，强化对违法失信生产经营单位及其有关从业人员的社会监督，提高全社会安全生产诚信水平。 第五章 生产安全事故的应急救援与调查处理"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第七十九条", "text": "国家加强生产安全事故应急能力建设，在重点行业、领域建立应急救援基地和应急救援队伍，并由国家安全生产应急救援机构统一协调指挥；鼓励生产经营单位和其他社会力量建立应急救援队伍，配备相应的应急救援装备和物资，提高应急救援的专业化水平。 国务院应急管理部门牵头建立全国统一的生产安全事故应急救援信息系统，国务院交通运输、住房和城乡建设、水利、民航等有关部门和县级以上地方人民政府建立健全相关行业、领域、地区的生产安全事故应急救援信息系统，实现互联互通、信息共享，通过推行网上安全信息采集、安全监管和监测预警，提升监管的精准化、智能化水平。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第八十条", "text": "县级以上地方各级人民政府应当组织有关部门制定本行政区域内生产安全事故应急救援预案，建立应急救援体系。 乡镇人民政府和街道办事处，以及开发区、工业园区、港区、风景区等应当制定相应的生产安全事故应急救援预案，协助人民政府有关部门或者按照授权依法履行生产安全事故应急救援工作职责。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第八十一条", "text": "生产经营单位应当制定本单位生产安全事故应急救援预案，与所在地县级以上地方人民政府组织制定的生产安全事故应急救援预案相衔接，并定期组织演练。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第八十二条", "text": "危险物品的生产、经营、储存单位以及矿山、金属冶炼、城市轨道交通运营、建筑施工单位应当建立应急救援组织；生产经营规模较小的，可以不建立应急救援组织，但应当指定兼职的应急救援人员。 危险物品的生产、经营、储存、运输单位以及矿山、金属冶炼、城市轨道交通运营、建筑施工单位应当配备必要的应急救援器材、设备和物资，并进行经常性维护、保养，保证正常运转。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第八十三条", "text": "生产经营单位发生生产安全事故后，事故现场有关人员应当立即报告本单位负责人。 单位负责人接到事故报告后，应当迅速采取有效措施，组织抢救，防止事故扩大，减少人员伤亡和财产损失，并按照国家有关规定立即如实报告当地负有安全生产监督管理职责的部门，不得隐瞒不报、谎报或者迟报，不得故意破坏事故现场、毁灭有关证据。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第八十四条", "text": "负有安全生产监督管理职责的部门接到事故报告后，应当立即按照国家有关规定上报事故情况。负有安全生产监督管理职责的部门和有关地方人民政府对事故情况不得隐瞒不报、谎报或者迟报。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第八十五条", "text": "有关地方人民政府和负有安全生产监督管理职责的部门的负责人接到生产安全事故报告后，应当按照生产安全事故应急救援预案的要求立即赶到事故现场，组织事故抢救。 参与事故抢救的部门和单位应当服从统一指挥，加强协同联动，采取有效的应急救援措施，并根据事故救援的需要采取警戒、疏散等措施，防止事故扩大和次生灾害的发生，减少人员伤亡和财产损失。 事故抢救过程中应当采取必要措施，避免或者减少对环境造成的危害。 任何单位和个人都应当支持、配合事故抢救，并提供一切便利条件。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第八十六条", "text": "事故调查处理应当按照科学严谨、依法依规、实事求是、注重实效的原则，及时、准确地查清事故原因，查明事故性质和责任，评估应急处置工作，总结事故教训，提出整改措施，并对事故责任单位和人员提出处理建议。事故调查报告应当依法及时向社会公布。事故调查和处理的具体办法由国务院制定。 事故发生单位应当及时全面落实整改措施，负有安全生产监督管理职责的部门应当加强监督检查。 负责事故调查处理的国务院有关部门和地方人民政府应当在批复事故调查报告后一年内，组织有关部门对事故整改和防范措施落实情况进行评估，并及时向社会公开评估结果；对不履行职责导致事故整改和防范措施没有落实的有关单位和人员，应当按照有关规定追究责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第八十七条", "text": "生产经营单位发生生产安全事故，经调查确定为责任事故的，除了应当查明事故单位的责任并依法予以追究外，还应当查明对安全生产的有关事项负有审查批准和监督职责的行政部门的责任，对有失职、渎职行为的，依照本法"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第九十条", "text": "的规定追究法律责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第八十八条", "text": "任何单位和个人不得阻挠和干涉对事故的依法调查处理。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第八十九条", "text": "县级以上地方各级人民政府应急管理部门应当定期统计分析本行政区域内发生生产安全事故的情况，并定期向社会公布。 第六章 法律责任"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第九十条", "text": "负有安全生产监督管理职责的部门的工作人员，有下列行为之一的，给予降级或者撤职的处分；构成犯罪的，依照刑法有关规定追究刑事责任： （一）对不符合法定安全生产条件的涉及安全生产的事项予以批准或者验收通过的； （二）发现未依法取得批准、验收的单位擅自从事有关活动或者接到举报后不予取缔或者不依法予以处理的； （三）对已经依法取得批准的单位不履行监督管理职责，发现其不再具备安全生产条件而不撤销原批准或者发现安全生产违法行为不予查处的； （四）在监督检查中发现重大事故隐患，不依法及时处理的。 负有安全生产监督管理职责的部门的工作人员有前款规定以外的滥用职权、玩忽职守、徇私舞弊行为的，依法给予处分；构成犯罪的，依照刑法有关规定追究刑事责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第九十一条", "text": "负有安全生产监督管理职责的部门，要求被审查、验收的单位购买其指定的安全设备、器材或者其他产品的，在对安全生产事项的审查、验收中收取费用的，由其上级机关或者监察机关责令改正，责令退还收取的费用；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第九十二条", "text": "承担安全评价、认证、检测、检验职责的机构出具失实报告的，责令停业整顿，并处三万元以上十万元以下的罚款；给他人造成损害的，依法承担赔偿责任。 承担安全评价、认证、检测、检验职责的机构租借资质、挂靠、出具虚假报告的，没收违法所得；违法所得在十万元以上的，并处违法所得二倍以上五倍以下的罚款，没有违法所得或者违法所得不足十万元的，单处或者并处十万元以上二十万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；给他人造成损害的，与生产经营单位承担连带赔偿责任；构成犯罪的，依照刑法有关规定追究刑事责任。 对有前款违法行为的机构及其直接责任人员，吊销其相应资质和资格，五年内不得从事安全评价、认证、检测、检验等工作；情节严重的，实行终身行业和职业禁入。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第九十三条", "text": "生产经营单位的决策机构、主要负责人或者个人经营的投资人不依照本法规定保证安全生产所必需的资金投入，致使生产经营单位不具备安全生产条件的，责令限期改正，提供必需的资金；逾期未改正的，责令生产经营单位停产停业整顿。 有前款违法行为，导致发生生产安全事故的，对生产经营单位的主要负责人给予撤职处分，对个人经营的投资人处二万元以上二十万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第九十四条", "text": "生产经营单位的主要负责人未履行本法规定的安全生产管理职责的，责令限期改正，处二万元以上五万元以下的罚款；逾期未改正的，处五万元以上十万元以下的罚款，责令生产经营单位停产停业整顿。 生产经营单位的主要负责人有前款违法行为，导致发生生产安全事故的，给予撤职处分；构成犯罪的，依照刑法有关规定追究刑事责任。 生产经营单位的主要负责人依照前款规定受刑事处罚或者撤职处分的，自刑罚执行完毕或者受处分之日起，五年内不得担任任何生产经营单位的主要负责人；对重大、特别重大生产安全事故负有责任的，终身不得担任本行业生产经营单位的主要负责人。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第九十五条", "text": "生产经营单位的主要负责人未履行本法规定的安全生产管理职责，导致发生生产安全事故的，由应急管理部门依照下列规定处以罚款： （一）发生一般事故的，处上一年年收入百分之四十的罚款； （二）发生较大事故的，处上一年年收入百分之六十的罚款； （三）发生重大事故的，处上一年年收入百分之八十的罚款； （四）发生特别重大事故的，处上一年年收入百分之一百的罚款。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第九十六条", "text": "生产经营单位的其他负责人和安全生产管理人员未履行本法规定的安全生产管理职责的，责令限期改正，处一万元以上三万元以下的罚款；导致发生生产安全事故的，暂停或者吊销其与安全生产有关的资格，并处上一年年收入百分之二十以上百分之五十以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第九十七条", "text": "生产经营单位有下列行为之一的，责令限期改正，处十万元以下的罚款；逾期未改正的，责令停产停业整顿，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款： （一）未按照规定设置安全生产管理机构或者配备安全生产管理人员、注册安全工程师的； （二）危险物品的生产、经营、储存、装卸单位以及矿山、金属冶炼、建筑施工、运输单位的主要负责人和安全生产管理人员未按照规定经考核合格的； （三）未按照规定对从业人员、被派遣劳动者、实习学生进行安全生产教育和培训，或者未按照规定如实告知有关的安全生产事项的； （四）未如实记录安全生产教育和培训情况的； （五）未将事故隐患排查治理情况如实记录或者未向从业人员通报的； （六）未按照规定制定生产安全事故应急救援预案或者未定期组织演练的； （七）特种作业人员未按照规定经专门的安全作业培训并取得相应资格，上岗作业的。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第九十八条", "text": "生产经营单位有下列行为之一的，责令停止建设或者停产停业整顿，限期改正，并处十万元以上五十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；逾期未改正的，处五十万元以上一百万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任： （一）未按照规定对矿山、金属冶炼建设项目或者用于生产、储存、装卸危险物品的建设项目进行安全评价的； （二）矿山、金属冶炼建设项目或者用于生产、储存、装卸危险物品的建设项目没有安全设施设计或者安全设施设计未按照规定报经有关部门审查同意的； （三）矿山、金属冶炼建设项目或者用于生产、储存、装卸危险物品的建设项目的施工单位未按照批准的安全设施设计施工的； （四）矿山、金属冶炼建设项目或者用于生产、储存、装卸危险物品的建设项目竣工投入生产或者使用前，安全设施未经验收合格的。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第九十九条", "text": "生产经营单位有下列行为之一的，责令限期改正，处五万元以下的罚款；逾期未改正的，处五万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以上二万元以下的罚款；情节严重的，责令停产停业整顿；构成犯罪的，依照刑法有关规定追究刑事责任： （一）未在有较大危险因素的生产经营场所和有关设施、设备上设置明显的安全警示标志的； （二）安全设备的安装、使用、检测、改造和报废不符合国家标准或者行业标准的； （三）未对安全设备进行经常性维护、保养和定期检测的； （四）关闭、破坏直接关系生产安全的监控、报警、防护、救生设备、设施，或者篡改、隐瞒、销毁其相关数据、信息的； （五）未为从业人员提供符合国家标准或者行业标准的劳动防护用品的； （六）危险物品的容器、运输工具，以及涉及人身安全、危险性较大的海洋石油开采特种设备和矿山井下特种设备未经具有专业资质的机构检测、检验合格，取得安全使用证或者安全标志，投入使用的； （七）使用应当淘汰的危及生产安全的工艺、设备的； （八）餐饮等行业的生产经营单位使用燃气未安装可燃气体报警装置的。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百条", "text": "未经依法批准，擅自生产、经营、运输、储存、使用危险物品或者处置废弃危险物品的，依照有关危险物品安全管理的法律、行政法规的规定予以处罚；构成犯罪的，依照刑法有关规定追究刑事责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百零一条", "text": "生产经营单位有下列行为之一的，责令限期改正，处十万元以下的罚款；逾期未改正的，责令停产停业整顿，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任： （一）生产、经营、运输、储存、使用危险物品或者处置废弃危险物品，未建立专门安全管理制度、未采取可靠的安全措施的； （二）对重大危险源未登记建档，未进行定期检测、评估、监控，未制定应急预案，或者未告知应急措施的； （三）进行爆破、吊装、动火、临时用电以及国务院应急管理部门会同国务院有关部门规定的其他危险作业，未安排专门人员进行现场安全管理的； （四）未建立安全风险分级管控制度或者未按照安全风险分级采取相应管控措施的； （五）未建立事故隐患排查治理制度，或者重大事故隐患排查治理情况未按照规定报告的。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百零二条", "text": "生产经营单位未采取措施消除事故隐患的，责令立即消除或者限期消除，处五万元以下的罚款；生产经营单位拒不执行的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百零三条", "text": "生产经营单位将生产经营项目、场所、设备发包或者出租给不具备安全生产条件或者相应资质的单位或者个人的，责令限期改正，没收违法所得；违法所得十万元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足十万元的，单处或者并处十万元以上二十万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处一万元以上二万元以下的罚款；导致发生生产安全事故给他人造成损害的，与承包方、承租方承担连带赔偿责任。 生产经营单位未与承包单位、承租单位签订专门的安全生产管理协议或者未在承包合同、租赁合同中明确各自的安全生产管理职责，或者未对承包单位、承租单位的安全生产统一协调、管理的，责令限期改正，处五万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以下的罚款；逾期未改正的，责令停产停业整顿。 矿山、金属冶炼建设项目和用于生产、储存、装卸危险物品的建设项目的施工单位未按照规定对施工项目进行安全管理的，责令限期改正，处十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以下的罚款；逾期未改正的，责令停产停业整顿。以上施工单位倒卖、出租、出借、挂靠或者以其他形式非法转让施工资质的，责令停产停业整顿，吊销资质证书，没收违法所得；违法所得十万元以上的，并处违法所得二倍以上五倍以下的罚款，没有违法所得或者违法所得不足十万元的，单处或者并处十万元以上二十万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百零四条", "text": "两个以上生产经营单位在同一作业区域内进行可能危及对方安全生产的生产经营活动，未签订安全生产管理协议或者未指定专职安全生产管理人员进行安全检查与协调的，责令限期改正，处五万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以下的罚款；逾期未改正的，责令停产停业。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百零五条", "text": "生产经营单位有下列行为之一的，责令限期改正，处五万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处一万元以下的罚款；逾期未改正的，责令停产停业整顿；构成犯罪的，依照刑法有关规定追究刑事责任： （一）生产、经营、储存、使用危险物品的车间、商店、仓库与员工宿舍在同一座建筑内，或者与员工宿舍的距离不符合安全要求的； （二）生产经营场所和员工宿舍未设有符合紧急疏散需要、标志明显、保持畅通的出口、疏散通道，或者占用、锁闭、封堵生产经营场所或者员工宿舍出口、疏散通道的。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百零六条", "text": "生产经营单位与从业人员订立协议，免除或者减轻其对从业人员因生产安全事故伤亡依法应承担的责任的，该协议无效；对生产经营单位的主要负责人、个人经营的投资人处二万元以上十万元以下的罚款。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百零七条", "text": "生产经营单位的从业人员不落实岗位安全责任，不服从管理，违反安全生产规章制度或者操作规程的，由生产经营单位给予批评教育，依照有关规章制度给予处分；构成犯罪的，依照刑法有关规定追究刑事责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百零八条", "text": "违反本法规定，生产经营单位拒绝、阻碍负有安全生产监督管理职责的部门依法实施监督检查的，责令改正；拒不改正的，处二万元以上二十万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处一万元以上二万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百零九条", "text": "高危行业、领域的生产经营单位未按照国家规定投保安全生产责任保险的，责令限期改正，处五万元以上十万元以下的罚款；逾期未改正的，处十万元以上二十万元以下的罚款。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百一十条", "text": "生产经营单位的主要负责人在本单位发生生产安全事故时，不立即组织抢救或者在事故调查处理期间擅离职守或者逃匿的，给予降级、撤职的处分，并由应急管理部门处上一年年收入百分之六十至百分之一百的罚款；对逃匿的处十五日以下拘留；构成犯罪的，依照刑法有关规定追究刑事责任。 生产经营单位的主要负责人对生产安全事故隐瞒不报、谎报或者迟报的，依照前款规定处罚。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百一十一条", "text": "有关地方人民政府、负有安全生产监督管理职责的部门，对生产安全事故隐瞒不报、谎报或者迟报的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依照刑法有关规定追究刑事责任。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百一十二条", "text": "生产经营单位违反本法规定，被责令改正且受到罚款处罚，拒不改正的，负有安全生产监督管理职责的部门可以自作出责令改正之日的次日起，按照原处罚数额按日连续处罚。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百一十三条", "text": "生产经营单位存在下列情形之一的，负有安全生产监督管理职责的部门应当提请地方人民政府予以关闭，有关部门应当依法吊销其有关证照。生产经营单位主要负责人五年内不得担任任何生产经营单位的主要负责人；情节严重的，终身不得担任本行业生产经营单位的主要负责人： （一）存在重大事故隐患，一百八十日内三次或者一年内四次受到本法规定的行政处罚的； （二）经停产停业整顿，仍不具备法律、行政法规和国家标准或者行业标准规定的安全生产条件的； （三）不具备法律、行政法规和国家标准或者行业标准规定的安全生产条件，导致发生重大、特别重大生产安全事故的； （四）拒不执行负有安全生产监督管理职责的部门作出的停产停业整顿决定的。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百一十四条", "text": "发生生产安全事故，对负有责任的生产经营单位除要求其依法承担相应的赔偿等责任外，由应急管理部门依照下列规定处以罚款： （一）发生一般事故的，处三十万元以上一百万元以下的罚款； （二）发生较大事故的，处一百万元以上二百万元以下的罚款； （三）发生重大事故的，处二百万元以上一千万元以下的罚款； （四）发生特别重大事故的，处一千万元以上二千万元以下的罚款。 发生生产安全事故，情节特别严重、影响特别恶劣的，应急管理部门可以按照前款罚款数额的二倍以上五倍以下对负有责任的生产经营单位处以罚款。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百一十五条", "text": "本法规定的行政处罚，由应急管理部门和其他负有安全生产监督管理职责的部门按照职责分工决定；其中，根据本法"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百一十四条", "text": "的规定应当给予民航、铁路、电力行业的生产经营单位及其主要负责人行政处罚的，也可以由主管的负有安全生产监督管理职责的部门进行处罚。予以关闭的行政处罚，由负有安全生产监督管理职责的部门报请县级以上人民政府按照国务院规定的权限决定；给予拘留的行政处罚，由公安机关依照治安管理处罚的规定决定。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百一十六条", "text": "生产经营单位发生生产安全事故造成人员伤亡、他人财产损失的，应当依法承担赔偿责任；拒不承担或者其负责人逃匿的，由人民法院依法强制执行。 生产安全事故的责任人未依法承担赔偿责任，经人民法院依法采取执行措施后，仍不能对受害人给予足额赔偿的，应当继续履行赔偿义务；受害人发现责任人有其他财产的，可以随时请求人民法院执行。 第七章 附 则"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百一十七条", "text": "本法下列用语的含义： 危险物品，是指易燃易爆物品、危险化学品、放射性物品等能够危及人身安全和财产安全的物品。 重大危险源，是指长期地或者临时地生产、搬运、使用或者储存危险物品，且危险物品的数量等于或者超过临界量的单元（包括场所和设施）。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百一十八条", "text": "本法规定的生产安全一般事故、较大事故、重大事故、特别重大事故的划分标准由国务院规定。 国务院应急管理部门和其他负有安全生产监督管理职责的部门应当根据各自的职责分工，制定相关行业、领域重大危险源的辨识标准和重大事故隐患的判定标准。"}, {"law": "中华人民共和国安全生产法_20210610.docx", "no": "第一百一十九条", "text": "本法自2002年11月1日起施行。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一条", "text": "中华人民共和国是工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家。 社会主义制度是中华人民共和国的根本制度。中国共产党领导是中国特色社会主义最本质的特征。禁止任何组织或者个人破坏社会主义制度。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第二条", "text": "中华人民共和国的一切权力属于人民。 人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。 人民依照法律规定，通过各种途径和形式，管理国家事务，管理经济和文化事业，管理社会事务。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第三条", "text": "中华人民共和国的国家机构实行民主集中制的原则。 全国人民代表大会和地方各级人民代表大会都由民主选举产生，对人民负责，受人民监督。 国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。 中央和地方的国家机构职权的划分，遵循在中央的统一领导下，充分发挥地方的主动性、积极性的原则。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第四条", "text": "中华人民共和国各民族一律平等。国家保障各少数民族的合法的权利和利益，维护和发展各民族的平等团结互助和谐关系。禁止对任何民族的歧视和压迫，禁止破坏民族团结和制造民族分裂的行为。 国家根据各少数民族的特点和需要，帮助各少数民族地区加速经济和文化的发展。 各少数民族聚居的地方实行区域自治，设立自治机关，行使自治权。各民族自治地方都是中华人民共和国不可分离的部分。 各民族都有使用和发展自己的语言文字的自由，都有保持或者改革自己的风俗习惯的自由。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第五条", "text": "中华人民共和国实行依法治国，建设社会主义法治国家。 国家维护社会主义法制的统一和尊严。 一切法律、行政法规和地方性法规都不得同宪法相抵触。 一切国家机关和武装力量、各政党和各社会团体、各企业事业组织都必须遵守宪法和法律。一切违反宪法和法律的行为，必须予以追究。 任何组织或者个人都不得有超越宪法和法律的特权。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第六条", "text": "中华人民共和国的社会主义经济制度的基础是生产资料的社会主义公有制，即全民所有制和劳动群众集体所有制。社会主义公有制消灭人剥削人的制度，实行各尽所能、按劳分配的原则。 国家在社会主义初级阶段，坚持公有制为主体、多种所有制经济共同发展的基本经济制度，坚持按劳分配为主体、多种分配方式并存的分配制度。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第七条", "text": "国有经济，即社会主义全民所有制经济，是国民经济中的主导力量。国家保障国有经济的巩固和发展。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第八条", "text": "农村集体经济组织实行家庭承包经营为基础、统分结合的双层经营体制。农村中的生产、供销、信用、消费等各种形式的合作经济，是社会主义劳动群众集体所有制经济。参加农村集体经济组织的劳动者，有权在法律规定的范围内经营自留地、自留山、家庭副业和饲养自留畜。 城镇中的手工业、工业、建筑业、运输业、商业、服务业等行业的各种形式的合作经济，都是社会主义劳动群众集体所有制经济。 国家保护城乡集体经济组织的合法的权利和利益，鼓励、指导和帮助集体经济的发展。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第九条", "text": "矿藏、水流、森林、山岭、草原、荒地、滩涂等自然资源，都属于国家所有，即全民所有；由法律规定属于集体所有的森林和山岭、草原、荒地、滩涂除外。 国家保障自然资源的合理利用，保护珍贵的动物和植物。禁止任何组织或者个人用任何手段侵占或者破坏自然资源。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第十条", "text": "城市的土地属于国家所有。 农村和城市郊区的土地，除由法律规定属于国家所有的以外，属于集体所有；宅基地和自留地、自留山，也属于集体所有。 国家为了公共利益的需要，可以依照法律规定对土地实行征收或者征用并给予补偿。 任何组织或者个人不得侵占、买卖或者以其他形式非法转让土地。土地的使用权可以依照法律的规定转让。 一切使用土地的组织和个人必须合理地利用土地。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第十一条", "text": "在法律规定范围内的个体经济、私营经济等非公有制经济，是社会主义市场经济的重要组成部分。 国家保护个体经济、私营经济等非公有制经济的合法的权利和利益。国家鼓励、支持和引导非公有制经济的发展，并对非公有制经济依法实行监督和管理。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第十二条", "text": "社会主义的公共财产神圣不可侵犯。 国家保护社会主义的公共财产。禁止任何组织或者个人用任何手段侵占或者破坏国家的和集体的财产。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第十三条", "text": "公民的合法的私有财产不受侵犯。 国家依照法律规定保护公民的私有财产权和继承权。 国家为了公共利益的需要，可以依照法律规定对公民的私有财产实行征收或者征用并给予补偿。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第十四条", "text": "国家通过提高劳动者的积极性和技术水平，推广先进的科学技术，完善经济管理体制和企业经营管理制度，实行各种形式的社会主义责任制，改进劳动组织，以不断提高劳动生产率和经济效益，发展社会生产力。 国家厉行节约，反对浪费。 国家合理安排积累和消费，兼顾国家、集体和个人的利益，在发展生产的基础上，逐步改善人民的物质生活和文化生活。 国家建立健全同经济发展水平相适应的社会保障制度。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第十五条", "text": "国家实行社会主义市场经济。 国家加强经济立法，完善宏观调控。 国家依法禁止任何组织或者个人扰乱社会经济秩序。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第十六条", "text": "国有企业在法律规定的范围内有权自主经营。 国有企业依照法律规定，通过职工代表大会和其他形式，实行民主管理。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第十七条", "text": "集体经济组织在遵守有关法律的前提下，有独立进行经济活动的自主权。 集体经济组织实行民主管理，依照法律规定选举和罢免管理人员，决定经营管理的重大问题。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第十八条", "text": "中华人民共和国允许外国的企业和其他经济组织或者个人依照中华人民共和国法律的规定在中国投资，同中国的企业或者其他经济组织进行各种形式的经济合作。 在中国境内的外国企业和其他外国经济组织以及中外合资经营的企业，都必须遵守中华人民共和国的法律。它们的合法的权利和利益受中华人民共和国法律的保护。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第十九条", "text": "国家发展社会主义的教育事业，提高全国人民的科学文化水平。 国家举办各种学校，普及初等义务教育，发展中等教育、职业教育和高等教育，并且发展学前教育。 国家发展各种教育设施，扫除文盲，对工人、农民、国家工作人员和其他劳动者进行政治、文化、科学、技术、业务的教育，鼓励自学成才。 国家鼓励集体经济组织、国家企业事业组织和其他社会力量依照法律规定举办各种教育事业。 国家推广全国通用的普通话。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第二十条", "text": "国家发展自然科学和社会科学事业，普及科学和技术知识，奖励科学研究成果和技术发明创造。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第二十一条", "text": "国家发展医疗卫生事业，发展现代医药和我国传统医药，鼓励和支持农村集体经济组织、国家企业事业组织和街道组织举办各种医疗卫生设施，开展群众性的卫生活动，保护人民健康。 国家发展体育事业，开展群众性的体育活动，增强人民体质。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第二十二条", "text": "国家发展为人民服务、为社会主义服务的文学艺术事业、新闻广播电视事业、出版发行事业、图书馆博物馆文化馆和其他文化事业，开展群众性的文化活动。 国家保护名胜古迹、珍贵文物和其他重要历史文化遗产。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第二十三条", "text": "国家培养为社会主义服务的各种专业人才，扩大知识分子的队伍，创造条件，充分发挥他们在社会主义现代化建设中的作用。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第二十四条", "text": "国家通过普及理想教育、道德教育、文化教育、纪律和法制教育，通过在城乡不同范围的群众中制定和执行各种守则、公约，加强社会主义精神文明的建设。 国家倡导社会主义核心价值观，提倡爱祖国、爱人民、爱劳动、爱科学、爱社会主义的公德，在人民中进行爱国主义、集体主义和国际主义、共产主义的教育，进行辩证唯物主义和历史唯物主义的教育，反对资本主义的、封建主义的和其他的腐朽思想。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第二十五条", "text": "国家推行计划生育，使人口的增长同经济和社会发展计划相适应。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第二十六条", "text": "国家保护和改善生活环境和生态环境，防治污染和其他公害。 国家组织和鼓励植树造林，保护林木。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第二十七条", "text": "一切国家机关实行精简的原则，实行工作责任制，实行工作人员的培训和考核制度，不断提高工作质量和工作效率，反对官僚主义。 一切国家机关和国家工作人员必须依靠人民的支持，经常保持同人民的密切联系，倾听人民的意见和建议，接受人民的监督，努力为人民服务。 国家工作人员就职时应当依照法律规定公开进行宪法宣誓。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第二十八条", "text": "国家维护社会秩序，镇压叛国和其他危害国家安全的犯罪活动，制裁危害社会治安、破坏社会主义经济和其他犯罪的活动，惩办和改造犯罪分子。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第二十九条", "text": "中华人民共和国的武装力量属于人民。它的任务是巩固国防，抵抗侵略，保卫祖国，保卫人民的和平劳动，参加国家建设事业，努力为人民服务。 国家加强武装力量的革命化、现代化、正规化的建设，增强国防力量。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第三十条", "text": "中华人民共和国的行政区域划分如下： （一）全国分为省、自治区、直辖市； （二）省、自治区分为自治州、县、自治县、市； （三）县、自治县分为乡、民族乡、镇。 直辖市和较大的市分为区、县。自治州分为县、自治县、市。 自治区、自治州、自治县都是民族自治地方。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第三十一条", "text": "国家在必要时得设立特别行政区。在特别行政区内实行的制度按照具体情况由全国人民代表大会以法律规定。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第三十二条", "text": "中华人民共和国保护在中国境内的外国人的合法权利和利益，在中国境内的外国人必须遵守中华人民共和国的法律。 中华人民共和国对于因为政治原因要求避难的外国人，可以给予受庇护的权利。 第二章 公民的基本权利和义务"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第三十三条", "text": "凡具有中华人民共和国国籍的人都是中华人民共和国公民。 中华人民共和国公民在法律面前一律平等。 国家尊重和保障人权。 任何公民享有宪法和法律规定的权利，同时必须履行宪法和法律规定的义务。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第三十四条", "text": "中华人民共和国年满十八周岁的公民，不分民族、种族、性别、职业、家庭出身、宗教信仰、教育程度、财产状况、居住期限，都有选举权和被选举权；但是依照法律被剥夺政治权利的人除外。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第三十五条", "text": "中华人民共和国公民有言论、出版、集会、结社、游行、示威的自由。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第三十六条", "text": "中华人民共和国公民有宗教信仰自由。 任何国家机关、社会团体和个人不得强制公民信仰宗教或者不信仰宗教，不得歧视信仰宗教的公民和不信仰宗教的公民。 国家保护正常的宗教活动。任何人不得利用宗教进行破坏社会秩序、损害公民身体健康、妨碍国家教育制度的活动。 宗教团体和宗教事务不受外国势力的支配。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第三十七条", "text": "中华人民共和国公民的人身自由不受侵犯。 任何公民，非经人民检察院批准或者决定或者人民法院决定，并由公安机关执行，不受逮捕。 禁止非法拘禁和以其他方法非法剥夺或者限制公民的人身自由，禁止非法搜查公民的身体。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第三十八条", "text": "中华人民共和国公民的人格尊严不受侵犯。禁止用任何方法对公民进行侮辱、诽谤和诬告陷害。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第三十九条", "text": "中华人民共和国公民的住宅不受侵犯。禁止非法搜查或者非法侵入公民的住宅。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第四十条", "text": "中华人民共和国公民的通信自由和通信秘密受法律的保护。除因国家安全或者追查刑事犯罪的需要，由公安机关或者检察机关依照法律规定的程序对通信进行检查外，任何组织或者个人不得以任何理由侵犯公民的通信自由和通信秘密。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第四十一条", "text": "中华人民共和国公民对于任何国家机关和国家工作人员，有提出批评和建议的权利；对于任何国家机关和国家工作人员的违法失职行为，有向有关国家机关提出申诉、控告或者检举的权利，但是不得捏造或者歪曲事实进行诬告陷害。 对于公民的申诉、控告或者检举，有关国家机关必须查清事实，负责处理。任何人不得压制和打击报复。 由于国家机关和国家工作人员侵犯公民权利而受到损失的人，有依照法律规定取得赔偿的权利。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第四十二条", "text": "中华人民共和国公民有劳动的权利和义务。 国家通过各种途径，创造劳动就业条件，加强劳动保护，改善劳动条件，并在发展生产的基础上，提高劳动报酬和福利待遇。 劳动是一切有劳动能力的公民的光荣职责。国有企业和城乡集体经济组织的劳动者都应当以国家主人翁的态度对待自己的劳动。国家提倡社会主义劳动竞赛，奖励劳动模范和先进工作者。国家提倡公民从事义务劳动。 国家对就业前的公民进行必要的劳动就业训练。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第四十三条", "text": "中华人民共和国劳动者有休息的权利。 国家发展劳动者休息和休养的设施，规定职工的工作时间和休假制度。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第四十四条", "text": "国家依照法律规定实行企业事业组织的职工和国家机关工作人员的退休制度。退休人员的生活受到国家和社会的保障。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第四十五条", "text": "中华人民共和国公民在年老、疾病或者丧失劳动能力的情况下，有从国家和社会获得物质帮助的权利。国家发展为公民享受这些权利所需要的社会保险、社会救济和医疗卫生事业。 国家和社会保障残废军人的生活，抚恤烈士家属，优待军人家属。 国家和社会帮助安排盲、聋、哑和其他有残疾的公民的劳动、生活和教育。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第四十六条", "text": "中华人民共和国公民有受教育的权利和义务。 国家培养青年、少年、儿童在品德、智力、体质等方面全面发展。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第四十七条", "text": "中华人民共和国公民有进行科学研究、文学艺术创作和其他文化活动的自由。国家对于从事教育、科学、技术、文学、艺术和其他文化事业的公民的有益于人民的创造性工作，给以鼓励和帮助。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第四十八条", "text": "中华人民共和国妇女在政治的、经济的、文化的、社会的和家庭的生活等各方面享有同男子平等的权利。 国家保护妇女的权利和利益，实行男女同工同酬，培养和选拔妇女干部。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第四十九条", "text": "婚姻、家庭、母亲和儿童受国家的保护。 夫妻双方有实行计划生育的义务。 父母有抚养教育未成年子女的义务，成年子女有赡养扶助父母的义务。 禁止破坏婚姻自由，禁止虐待老人、妇女和儿童。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第五十条", "text": "中华人民共和国保护华侨的正当的权利和利益，保护归侨和侨眷的合法的权利和利益。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第五十一条", "text": "中华人民共和国公民在行使自由和权利的时候，不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第五十二条", "text": "中华人民共和国公民有维护国家统一和全国各民族团结的义务。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第五十三条", "text": "中华人民共和国公民必须遵守宪法和法律，保守国家秘密，爱护公共财产，遵守劳动纪律，遵守公共秩序，尊重社会公德。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第五十四条", "text": "中华人民共和国公民有维护祖国的安全、荣誉和利益的义务，不得有危害祖国的安全、荣誉和利益的行为。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第五十五条", "text": "保卫祖国、抵抗侵略是中华人民共和国每一个公民的神圣职责。 依照法律服兵役和参加民兵组织是中华人民共和国公民的光荣义务。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第五十六条", "text": "中华人民共和国公民有依照法律纳税的义务。 第三章 国家机构 第一节 全国人民代表大会"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第五十七条", "text": "中华人民共和国全国人民代表大会是最高国家权力机关。它的常设机关是全国人民代表大会常务委员会。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第五十八条", "text": "全国人民代表大会和全国人民代表大会常务委员会行使国家立法权。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第五十九条", "text": "全国人民代表大会由省、自治区、直辖市、特别行政区和军队选出的代表组成。各少数民族都应当有适当名额的代表。 全国人民代表大会代表的选举由全国人民代表大会常务委员会主持。 全国人民代表大会代表名额和代表产生办法由法律规定。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第六十条", "text": "全国人民代表大会每届任期五年。 全国人民代表大会任期届满的两个月以前，全国人民代表大会常务委员会必须完成下届全国人民代表大会代表的选举。如果遇到不能进行选举的非常情况，由全国人民代表大会常务委员会以全体组成人员的三分之二以上的多数通过，可以推迟选举，延长本届全国人民代表大会的任期。在非常情况结束后一年内，必须完成下届全国人民代表大会代表的选举。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第六十一条", "text": "全国人民代表大会会议每年举行一次，由全国人民代表大会常务委员会召集。如果全国人民代表大会常务委员会认为必要，或者有五分之一以上的全国人民代表大会代表提议，可以临时召集全国人民代表大会会议。 全国人民代表大会举行会议的时候，选举主席团主持会议。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第六十二条", "text": "全国人民代表大会行使下列职权： （一）修改宪法； （二）监督宪法的实施； （三）制定和修改刑事、民事、国家机构的和其他的基本法律； （四）选举中华人民共和国主席、副主席； （五）根据中华人民共和国主席的提名，决定国务院总理的人选；根据国务院总理的提名，决定国务院副总理、国务委员、各部部长、各委员会主任、审计长、秘书长的人选； （六）选举中央军事委员会主席；根据中央军事委员会主席的提名，决定中央军事委员会其他组成人员的人选； （七）选举国家监察委员会主任； （八）选举最高人民法院院长； （九）选举最高人民检察院检察长； （十）审查和批准国民经济和社会发展计划和计划执行情况的报告； （十一）审查和批准国家的预算和预算执行情况的报告； （十二）改变或者撤销全国人民代表大会常务委员会不适当的决定； （十三）批准省、自治区和直辖市的建置； （十四）决定特别行政区的设立及其制度； （十五）决定战争和和平的问题； （十六）应当由最高国家权力机关行使的其他职权。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第六十三条", "text": "全国人民代表大会有权罢免下列人员： （一）中华人民共和国主席、副主席； （二）国务院总理、副总理、国务委员、各部部长、各委员会主任、审计长、秘书长； （三）中央军事委员会主席和中央军事委员会其他组成人员； （四）国家监察委员会主任； （五）最高人民法院院长； （六）最高人民检察院检察长。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第六十四条", "text": "宪法的修改，由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过。 法律和其他议案由全国人民代表大会以全体代表的过半数通过。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第六十五条", "text": "全国人民代表大会常务委员会由下列人员组成： 委员长， 副委员长若干人， 秘书长， 委员若干人。 全国人民代表大会常务委员会组成人员中，应当有适当名额的少数民族代表。 全国人民代表大会选举并有权罢免全国人民代表大会常务委员会的组成人员。 全国人民代表大会常务委员会的组成人员不得担任国家行政机关、监察机关、审判机关和检察机关的职务。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第六十六条", "text": "全国人民代表大会常务委员会每届任期同全国人民代表大会每届任期相同，它行使职权到下届全国人民代表大会选出新的常务委员会为止。 委员长、副委员长连续任职不得超过两届。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第六十七条", "text": "全国人民代表大会常务委员会行使下列职权： （一）解释宪法，监督宪法的实施； （二）制定和修改除应当由全国人民代表大会制定的法律以外的其他法律； （三）在全国人民代表大会闭会期间，对全国人民代表大会制定的法律进行部分补充和修改，但是不得同该法律的基本原则相抵触； （四）解释法律； （五）在全国人民代表大会闭会期间，审查和批准国民经济和社会发展计划、国家预算在执行过程中所必须作的部分调整方案； （六）监督国务院、中央军事委员会、国家监察委员会、最高人民法院和最高人民检察院的工作； （七）撤销国务院制定的同宪法、法律相抵触的行政法规、决定和命令； （八）撤销省、自治区、直辖市国家权力机关制定的同宪法、法律和行政法规相抵触的地方性法规和决议； （九）在全国人民代表大会闭会期间，根据国务院总理的提名，决定部长、委员会主任、审计长、秘书长的人选； （十）在全国人民代表大会闭会期间，根据中央军事委员会主席的提名，决定中央军事委员会其他组成人员的人选； （十一）根据国家监察委员会主任的提请，任免国家监察委员会副主任、委员； （十二）根据最高人民法院院长的提请，任免最高人民法院副院长、审判员、审判委员会委员和军事法院院长； （十三）根据最高人民检察院检察长的提请，任免最高人民检察院副检察长、检察员、检察委员会委员和军事检察院检察长，并且批准省、自治区、直辖市的人民检察院检察长的任免； （十四）决定驻外全权代表的任免； （十五）决定同外国缔结的条约和重要协定的批准和废除； （十六）规定军人和外交人员的衔级制度和其他专门衔级制度； （十七）规定和决定授予国家的勋章和荣誉称号； （十八）决定特赦； （十九）在全国人民代表大会闭会期间，如果遇到国家遭受武装侵犯或者必须履行国际间共同防止侵略的条约的情况，决定战争状态的宣布； （二十）决定全国总动员或者局部动员； （二十一）决定全国或者个别省、自治区、直辖市进入紧急状态； （二十二）全国人民代表大会授予的其他职权。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第六十八条", "text": "全国人民代表大会常务委员会委员长主持全国人民代表大会常务委员会的工作，召集全国人民代表大会常务委员会会议。副委员长、秘书长协助委员长工作。 委员长、副委员长、秘书长组成委员长会议，处理全国人民代表大会常务委员会的重要日常工作。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第六十九条", "text": "全国人民代表大会常务委员会对全国人民代表大会负责并报告工作。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第七十条", "text": "全国人民代表大会设立民族委员会、宪法和法律委员会、财政经济委员会、教育科学文化卫生委员会、外事委员会、华侨委员会和其他需要设立的专门委员会。在全国人民代表大会闭会期间，各专门委员会受全国人民代表大会常务委员会的领导。 各专门委员会在全国人民代表大会和全国人民代表大会常务委员会领导下，研究、审议和拟订有关议案。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第七十一条", "text": "全国人民代表大会和全国人民代表大会常务委员会认为必要的时候，可以组织关于特定问题的调查委员会，并且根据调查委员会的报告，作出相应的决议。 调查委员会进行调查的时候，一切有关的国家机关、社会团体和公民都有义务向它提供必要的材料。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第七十二条", "text": "全国人民代表大会代表和全国人民代表大会常务委员会组成人员，有权依照法律规定的程序分别提出属于全国人民代表大会和全国人民代表大会常务委员会职权范围内的议案。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第七十三条", "text": "全国人民代表大会代表在全国人民代表大会开会期间，全国人民代表大会常务委员会组成人员在常务委员会开会期间，有权依照法律规定的程序提出对国务院或者国务院各部、各委员会的质询案。受质询的机关必须负责答复。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第七十四条", "text": "全国人民代表大会代表，非经全国人民代表大会会议主席团许可，在全国人民代表大会闭会期间非经全国人民代表大会常务委员会许可，不受逮捕或者刑事审判。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第七十五条", "text": "全国人民代表大会代表在全国人民代表大会各种会议上的发言和表决，不受法律追究。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第七十六条", "text": "全国人民代表大会代表必须模范地遵守宪法和法律，保守国家秘密，并且在自己参加的生产、工作和社会活动中，协助宪法和法律的实施。 全国人民代表大会代表应当同原选举单位和人民保持密切的联系，听取和反映人民的意见和要求，努力为人民服务。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第七十七条", "text": "全国人民代表大会代表受原选举单位的监督。原选举单位有权依照法律规定的程序罢免本单位选出的代表。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第七十八条", "text": "全国人民代表大会和全国人民代表大会常务委员会的组织和工作程序由法律规定。 第二节 中华人民共和国主席"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第七十九条", "text": "中华人民共和国主席、副主席由全国人民代表大会选举。 有选举权和被选举权的年满四十五周岁的中华人民共和国公民可以被选为中华人民共和国主席、副主席。 中华人民共和国主席、副主席每届任期同全国人民代表大会每届任期相同。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第八十条", "text": "中华人民共和国主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定，公布法律，任免国务院总理、副总理、国务委员、各部部长、各委员会主任、审计长、秘书长，授予国家的勋章和荣誉称号，发布特赦令，宣布进入紧急状态，宣布战争状态，发布动员令。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第八十一条", "text": "中华人民共和国主席代表中华人民共和国，进行国事活动，接受外国使节；根据全国人民代表大会常务委员会的决定，派遣和召回驻外全权代表，批准和废除同外国缔结的条约和重要协定。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第八十二条", "text": "中华人民共和国副主席协助主席工作。 中华人民共和国副主席受主席的委托，可以代行主席的部分职权。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第八十三条", "text": "中华人民共和国主席、副主席行使职权到下届全国人民代表大会选出的主席、副主席就职为止。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第八十四条", "text": "中华人民共和国主席缺位的时候，由副主席继任主席的职位。 中华人民共和国副主席缺位的时候，由全国人民代表大会补选。 中华人民共和国主席、副主席都缺位的时候，由全国人民代表大会补选；在补选以前，由全国人民代表大会常务委员会委员长暂时代理主席职位。 第三节 国务院"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第八十五条", "text": "中华人民共和国国务院，即中央人民政府，是最高国家权力机关的执行机关，是最高国家行政机关。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第八十六条", "text": "国务院由下列人员组成： 总理， 副总理若干人， 国务委员若干人， 各部部长， 各委员会主任， 审计长， 秘书长。 国务院实行总理负责制。各部、各委员会实行部长、主任负责制。 国务院的组织由法律规定。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第八十七条", "text": "国务院每届任期同全国人民代表大会每届任期相同。 总理、副总理、国务委员连续任职不得超过两届。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第八十八条", "text": "总理领导国务院的工作。副总理、国务委员协助总理工作。 总理、副总理、国务委员、秘书长组成国务院常务会议。 总理召集和主持国务院常务会议和国务院全体会议。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第八十九条", "text": "国务院行使下列职权： （一）根据宪法和法律，规定行政措施，制定行政法规，发布决定和命令； （二）向全国人民代表大会或者全国人民代表大会常务委员会提出议案； （三）规定各部和各委员会的任务和职责，统一领导各部和各委员会的工作，并且领导不属于各部和各委员会的全国性的行政工作； （四）统一领导全国地方各级国家行政机关的工作，规定中央和省、自治区、直辖市的国家行政机关的职权的具体划分； （五）编制和执行国民经济和社会发展计划和国家预算； （六）领导和管理经济工作和城乡建设、生态文明建设； （七）领导和管理教育、科学、文化、卫生、体育和计划生育工作； （八）领导和管理民政、公安、司法行政等工作； （九）管理对外事务，同外国缔结条约和协定； （十）领导和管理国防建设事业； （十一）领导和管理民族事务，保障少数民族的平等权利和民族自治地方的自治权利； （十二）保护华侨的正当的权利和利益，保护归侨和侨眷的合法的权利和利益； （十三）改变或者撤销各部、各委员会发布的不适当的命令、指示和规章； （十四）改变或者撤销地方各级国家行政机关的不适当的决定和命令； （十五）批准省、自治区、直辖市的区域划分，批准自治州、县、自治县、市的建置和区域划分； （十六）依照法律规定决定省、自治区、直辖市的范围内部分地区进入紧急状态； （十七）审定行政机构的编制，依照法律规定任免、培训、考核和奖惩行政人员； （十八）全国人民代表大会和全国人民代表大会常务委员会授予的其他职权。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第九十条", "text": "国务院各部部长、各委员会主任负责本部门的工作；召集和主持部务会议或者委员会会议、委务会议，讨论决定本部门工作的重大问题。 各部、各委员会根据法律和国务院的行政法规、决定、命令，在本部门的权限内，发布命令、指示和规章。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第九十一条", "text": "国务院设立审计机关，对国务院各部门和地方各级政府的财政收支，对国家的财政金融机构和企业事业组织的财务收支，进行审计监督。 审计机关在国务院总理领导下，依照法律规定独立行使审计监督权，不受其他行政机关、社会团体和个人的干涉。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第九十二条", "text": "国务院对全国人民代表大会负责并报告工作；在全国人民代表大会闭会期间，对全国人民代表大会常务委员会负责并报告工作。 第四节 中央军事委员会"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第九十三条", "text": "中华人民共和国中央军事委员会领导全国武装力量。 中央军事委员会由下列人员组成： 主席， 副主席若干人， 委员若干人。 中央军事委员会实行主席负责制。 中央军事委员会每届任期同全国人民代表大会每届任期相同。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第九十四条", "text": "中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责。 第五节 地方各级人民代表大会和地方各级人民政府"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第九十五条", "text": "省、直辖市、县、市、市辖区、乡、民族乡、镇设立人民代表大会和人民政府。 地方各级人民代表大会和地方各级人民政府的组织由法律规定。 自治区、自治州、自治县设立自治机关。自治机关的组织和工作根据宪法第三章第五节、第六节规定的基本原则由法律规定。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第九十六条", "text": "地方各级人民代表大会是地方国家权力机关。 县级以上的地方各级人民代表大会设立常务委员会。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第九十七条", "text": "省、直辖市、设区的市的人民代表大会代表由下一级的人民代表大会选举；县、不设区的市、市辖区、乡、民族乡、镇的人民代表大会代表由选民直接选举。 地方各级人民代表大会代表名额和代表产生办法由法律规定。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第九十八条", "text": "地方各级人民代表大会每届任期五年。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第九十九条", "text": "地方各级人民代表大会在本行政区域内，保证宪法、法律、行政法规的遵守和执行；依照法律规定的权限，通过和发布决议，审查和决定地方的经济建设、文化建设和公共事业建设的计划。 县级以上的地方各级人民代表大会审查和批准本行政区域内的国民经济和社会发展计划、预算以及它们的执行情况的报告；有权改变或者撤销本级人民代表大会常务委员会不适当的决定。 民族乡的人民代表大会可以依照法律规定的权限采取适合民族特点的具体措施。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百条", "text": "省、直辖市的人民代表大会和它们的常务委员会，在不同宪法、法律、行政法规相抵触的前提下，可以制定地方性法规，报全国人民代表大会常务委员会备案。 设区的市的人民代表大会和它们的常务委员会，在不同宪法、法律、行政法规和本省、自治区的地方性法规相抵触的前提下，可以依照法律规定制定地方性法规，报本省、自治区人民代表大会常务委员会批准后施行。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百零一条", "text": "地方各级人民代表大会分别选举并且有权罢免本级人民政府的省长和副省长、市长和副市长、县长和副县长、区长和副区长、乡长和副乡长、镇长和副镇长。 县级以上的地方各级人民代表大会选举并且有权罢免本级监察委员会主任、本级人民法院院长和本级人民检察院检察长。选出或者罢免人民检察院检察长，须报上级人民检察院检察长提请该级人民代表大会常务委员会批准。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百零二条", "text": "省、直辖市、设区的市的人民代表大会代表受原选举单位的监督；县、不设区的市、市辖区、乡、民族乡、镇的人民代表大会代表受选民的监督。 地方各级人民代表大会代表的选举单位和选民有权依照法律规定的程序罢免由他们选出的代表。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百零三条", "text": "县级以上的地方各级人民代表大会常务委员会由主任、副主任若干人和委员若干人组成，对本级人民代表大会负责并报告工作。 县级以上的地方各级人民代表大会选举并有权罢免本级人民代表大会常务委员会的组成人员。 县级以上的地方各级人民代表大会常务委员会的组成人员不得担任国家行政机关、监察机关、审判机关和检察机关的职务。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百零四条", "text": "县级以上的地方各级人民代表大会常务委员会讨论、决定本行政区域内各方面工作的重大事项；监督本级人民政府、监察委员会、人民法院和人民检察院的工作；撤销本级人民政府的不适当的决定和命令；撤销下一级人民代表大会的不适当的决议；依照法律规定的权限决定国家机关工作人员的任免；在本级人民代表大会闭会期间，罢免和补选上一级人民代表大会的个别代表。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百零五条", "text": "地方各级人民政府是地方各级国家权力机关的执行机关，是地方各级国家行政机关。 地方各级人民政府实行省长、市长、县长、区长、乡长、镇长负责制。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百零六条", "text": "地方各级人民政府每届任期同本级人民代表大会每届任期相同。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百零七条", "text": "县级以上地方各级人民政府依照法律规定的权限，管理本行政区域内的经济、教育、科学、文化、卫生、体育事业、城乡建设事业和财政、民政、公安、民族事务、司法行政、计划生育等行政工作，发布决定和命令，任免、培训、考核和奖惩行政工作人员。 乡、民族乡、镇的人民政府执行本级人民代表大会的决议和上级国家行政机关的决定和命令，管理本行政区域内的行政工作。 省、直辖市的人民政府决定乡、民族乡、镇的建置和区域划分。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百零八条", "text": "县级以上的地方各级人民政府领导所属各工作部门和下级人民政府的工作，有权改变或者撤销所属各工作部门和下级人民政府的不适当的决定。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百零九条", "text": "县级以上的地方各级人民政府设立审计机关。地方各级审计机关依照法律规定独立行使审计监督权，对本级人民政府和上一级审计机关负责。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百一十条", "text": "地方各级人民政府对本级人民代表大会负责并报告工作。县级以上的地方各级人民政府在本级人民代表大会闭会期间，对本级人民代表大会常务委员会负责并报告工作。 地方各级人民政府对上一级国家行政机关负责并报告工作。全国地方各级人民政府都是国务院统一领导下的国家行政机关，都服从国务院。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百一十一条", "text": "城市和农村按居民居住地区设立的居民委员会或者村民委员会是基层群众性自治组织。居民委员会、村民委员会的主任、副主任和委员由居民选举。居民委员会、村民委员会同基层政权的相互关系由法律规定。 居民委员会、村民委员会设人民调解、治安保卫、公共卫生等委员会，办理本居住地区的公共事务和公益事业，调解民间纠纷，协助维护社会治安，并且向人民政府反映群众的意见、要求和提出建议。 第六节 民族自治地方的自治机关"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百一十二条", "text": "民族自治地方的自治机关是自治区、自治州、自治县的人民代表大会和人民政府。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百一十三条", "text": "自治区、自治州、自治县的人民代表大会中，除实行区域自治的民族的代表外，其他居住在本行政区域内的民族也应当有适当名额的代表。 自治区、自治州、自治县的人民代表大会常务委员会中应当有实行区域自治的民族的公民担任主任或者副主任。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百一十四条", "text": "自治区主席、自治州州长、自治县县长由实行区域自治的民族的公民担任。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百一十五条", "text": "自治区、自治州、自治县的自治机关行使宪法第三章第五节规定的地方国家机关的职权，同时依照宪法、民族区域自治法和其他法律规定的权限行使自治权，根据本地方实际情况贯彻执行国家的法律、政策。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百一十六条", "text": "民族自治地方的人民代表大会有权依照当地民族的政治、经济和文化的特点，制定自治条例和单行条例。自治区的自治条例和单行条例，报全国人民代表大会常务委员会批准后生效。自治州、自治县的自治条例和单行条例，报省或者自治区的人民代表大会常务委员会批准后生效，并报全国人民代表大会常务委员会备案。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百一十七条", "text": "民族自治地方的自治机关有管理地方财政的自治权。凡是依照国家财政体制属于民族自治地方的财政收入，都应当由民族自治地方的自治机关自主地安排使用。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百一十八条", "text": "民族自治地方的自治机关在国家计划的指导下，自主地安排和管理地方性的经济建设事业。 国家在民族自治地方开发资源、建设企业的时候，应当照顾民族自治地方的利益。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百一十九条", "text": "民族自治地方的自治机关自主地管理本地方的教育、科学、文化、卫生、体育事业，保护和整理民族的文化遗产，发展和繁荣民族文化。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百二十条", "text": "民族自治地方的自治机关依照国家的军事制度和当地的实际需要，经国务院批准，可以组织本地方维护社会治安的公安部队。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百二十一条", "text": "民族自治地方的自治机关在执行职务的时候，依照本民族自治地方自治条例的规定，使用当地通用的一种或者几种语言文字。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百二十二条", "text": "国家从财政、物资、技术等方面帮助各少数民族加速发展经济建设和文化建设事业。 国家帮助民族自治地方从当地民族中大量培养各级干部、各种专业人才和技术工人。 第七节 监察委员会"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百二十三条", "text": "中华人民共和国各级监察委员会是国家的监察机关。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百二十四条", "text": "中华人民共和国设立国家监察委员会和地方各级监察委员会。 监察委员会由下列人员组成： 主任， 副主任若干人， 委员若干人。 监察委员会主任每届任期同本级人民代表大会每届任期相同。国家监察委员会主任连续任职不得超过两届。 监察委员会的组织和职权由法律规定。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百二十五条", "text": "中华人民共和国国家监察委员会是最高监察机关。 国家监察委员会领导地方各级监察委员会的工作，上级监察委员会领导下级监察委员会的工作。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百二十六条", "text": "国家监察委员会对全国人民代表大会和全国人民代表大会常务委员会负责。地方各级监察委员会对产生它的国家权力机关和上一级监察委员会负责。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百二十七条", "text": "监察委员会依照法律规定独立行使监察权，不受行政机关、社会团体和个人的干涉。 监察机关办理职务违法和职务犯罪案件，应当与审判机关、检察机关、执法部门互相配合，互相制约。 第八节 人民法院和人民检察院"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百二十八条", "text": "中华人民共和国人民法院是国家的审判机关。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百二十九条", "text": "中华人民共和国设立最高人民法院、地方各级人民法院和军事法院等专门人民法院。 最高人民法院院长每届任期同全国人民代表大会每届任期相同，连续任职不得超过两届。 人民法院的组织由法律规定。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百三十条", "text": "人民法院审理案件，除法律规定的特别情况外，一律公开进行。被告人有权获得辩护。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百三十一条", "text": "人民法院依照法律规定独立行使审判权，不受行政机关、社会团体和个人的干涉。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百三十二条", "text": "最高人民法院是最高审判机关。 最高人民法院监督地方各级人民法院和专门人民法院的审判工作，上级人民法院监督下级人民法院的审判工作。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百三十三条", "text": "最高人民法院对全国人民代表大会和全国人民代表大会常务委员会负责。地方各级人民法院对产生它的国家权力机关负责。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百三十四条", "text": "中华人民共和国人民检察院是国家的法律监督机关。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百三十五条", "text": "中华人民共和国设立最高人民检察院、地方各级人民检察院和军事检察院等专门人民检察院。 最高人民检察院检察长每届任期同全国人民代表大会每届任期相同，连续任职不得超过两届。 人民检察院的组织由法律规定。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百三十六条", "text": "人民检察院依照法律规定独立行使检察权，不受行政机关、社会团体和个人的干涉。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百三十七条", "text": "最高人民检察院是最高检察机关。 最高人民检察院领导地方各级人民检察院和专门人民检察院的工作，上级人民检察院领导下级人民检察院的工作。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百三十八条", "text": "最高人民检察院对全国人民代表大会和全国人民代表大会常务委员会负责。地方各级人民检察院对产生它的国家权力机关和上级人民检察院负责。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百三十九条", "text": "各民族公民都有用本民族语言文字进行诉讼的权利。人民法院和人民检察院对于不通晓当地通用的语言文字的诉讼参与人，应当为他们翻译。 在少数民族聚居或者多民族共同居住的地区，应当用当地通用的语言进行审理；起诉书、判决书、布告和其他文书应当根据实际需要使用当地通用的一种或者几种文字。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百四十条", "text": "人民法院、人民检察院和公安机关办理刑事案件，应当分工负责，互相配合，互相制约，以保证准确有效地执行法律。 第四章 国旗、国歌、国徽、首都"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百四十一条", "text": "中华人民共和国国旗是五星红旗。 中华人民共和国国歌是《义勇军进行曲》。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百四十二条", "text": "中华人民共和国国徽，中间是五星照耀下的天安门，周围是谷穗和齿轮。"}, {"law": "中华人民共和国宪法（2018年修正文本）_20180311.docx", "no": "第一百四十三条", "text": "中华人民共和国首都是北京。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第一条", "text": "为了预防火灾和减少火灾危害，加强应急救援工作，保护人身、财产安全，维护公共安全，制定本法。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第二条", "text": "消防工作贯彻预防为主、防消结合的方针，按照政府统一领导、部门依法监管、单位全面负责、公民积极参与的原则，实行消防安全责任制，建立健全社会化的消防工作网络。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第三条", "text": "国务院领导全国的消防工作。地方各级人民政府负责本行政区域内的消防工作。 各级人民政府应当将消防工作纳入国民经济和社会发展计划，保障消防工作与经济社会发展相适应。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第四条", "text": "国务院应急管理部门对全国的消防工作实施监督管理。县级以上地方人民政府应急管理部门对本行政区域内的消防工作实施监督管理，并由本级人民政府消防救援机构负责实施。军事设施的消防工作，由其主管单位监督管理，消防救援机构协助；矿井地下部分、核电厂、海上石油天然气设施的消防工作，由其主管单位监督管理。 县级以上人民政府其他有关部门在各自的职责范围内，依照本法和其他相关法律、法规的规定做好消防工作。 法律、行政法规对森林、草原的消防工作另有规定的，从其规定。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第五条", "text": "任何单位和个人都有维护消防安全、保护消防设施、预防火灾、报告火警的义务。任何单位和成年人都有参加有组织的灭火工作的义务。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第六条", "text": "各级人民政府应当组织开展经常性的消防宣传教育，提高公民的消防安全意识。 机关、团体、企业、事业等单位，应当加强对本单位人员的消防宣传教育。 应急管理部门及消防救援机构应当加强消防法律、法规的宣传，并督促、指导、协助有关单位做好消防宣传教育工作。 教育、人力资源行政主管部门和学校、有关职业培训机构应当将消防知识纳入教育、教学、培训的内容。 新闻、广播、电视等有关单位，应当有针对性地面向社会进行消防宣传教育。 工会、共产主义青年团、妇女联合会等团体应当结合各自工作对象的特点，组织开展消防宣传教育。 村民委员会、居民委员会应当协助人民政府以及公安机关、应急管理等部门，加强消防宣传教育。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第七条", "text": "国家鼓励、支持消防科学研究和技术创新，推广使用先进的消防和应急救援技术、设备；鼓励、支持社会力量开展消防公益活动。 对在消防工作中有突出贡献的单位和个人，应当按照国家有关规定给予表彰和奖励。 第二章 火灾预防"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第八条", "text": "地方各级人民政府应当将包括消防安全布局、消防站、消防供水、消防通信、消防车通道、消防装备等内容的消防规划纳入城乡规划，并负责组织实施。 城乡消防安全布局不符合消防安全要求的，应当调整、完善；公共消防设施、消防装备不足或者不适应实际需要的，应当增建、改建、配置或者进行技术改造。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第九条", "text": "建设工程的消防设计、施工必须符合国家工程建设消防技术标准。建设、设计、施工、工程监理等单位依法对建设工程的消防设计、施工质量负责。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第十条", "text": "对按照国家工程建设消防技术标准需要进行消防设计的建设工程，实行建设工程消防设计审查验收制度。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第十一条", "text": "国务院住房和城乡建设主管部门规定的特殊建设工程，建设单位应当将消防设计文件报送住房和城乡建设主管部门审查，住房和城乡建设主管部门依法对审查的结果负责。 前款规定以外的其他建设工程，建设单位申请领取施工许可证或者申请批准开工报告时应当提供满足施工需要的消防设计图纸及技术资料。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第十二条", "text": "特殊建设工程未经消防设计审查或者审查不合格的，建设单位、施工单位不得施工；其他建设工程，建设单位未提供满足施工需要的消防设计图纸及技术资料的，有关部门不得发放施工许可证或者批准开工报告。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第十三条", "text": "国务院住房和城乡建设主管部门规定应当申请消防验收的建设工程竣工，建设单位应当向住房和城乡建设主管部门申请消防验收。 前款规定以外的其他建设工程，建设单位在验收后应当报住房和城乡建设主管部门备案，住房和城乡建设主管部门应当进行抽查。 依法应当进行消防验收的建设工程，未经消防验收或者消防验收不合格的，禁止投入使用；其他建设工程经依法抽查不合格的，应当停止使用。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第十四条", "text": "建设工程消防设计审查、消防验收、备案和抽查的具体办法，由国务院住房和城乡建设主管部门规定。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第十五条", "text": "公众聚集场所投入使用、营业前消防安全检查实行告知承诺管理。公众聚集场所在投入使用、营业前，建设单位或者使用单位应当向场所所在地的县级以上地方人民政府消防救援机构申请消防安全检查，作出场所符合消防技术标准和管理规定的承诺，提交规定的材料，并对其承诺和材料的真实性负责。 消防救援机构对申请人提交的材料进行审查；申请材料齐全、符合法定形式的，应当予以许可。消防救援机构应当根据消防技术标准和管理规定，及时对作出承诺的公众聚集场所进行核查。 申请人选择不采用告知承诺方式办理的，消防救援机构应当自受理申请之日起十个工作日内，根据消防技术标准和管理规定，对该场所进行检查。经检查符合消防安全要求的，应当予以许可。 公众聚集场所未经消防救援机构许可的，不得投入使用、营业。消防安全检查的具体办法，由国务院应急管理部门制定。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第十六条", "text": "机关、团体、企业、事业等单位应当履行下列消防安全职责： （一）落实消防安全责任制，制定本单位的消防安全制度、消防安全操作规程，制定灭火和应急疏散预案； （二）按照国家标准、行业标准配置消防设施、器材，设置消防安全标志，并定期组织检验、维修，确保完好有效； （三）对建筑消防设施每年至少进行一次全面检测，确保完好有效，检测记录应当完整准确，存档备查； （四）保障疏散通道、安全出口、消防车通道畅通，保证防火防烟分区、防火间距符合消防技术标准； （五）组织防火检查，及时消除火灾隐患； （六）组织进行有针对性的消防演练； （七）法律、法规规定的其他消防安全职责。 单位的主要负责人是本单位的消防安全责任人。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第十七条", "text": "县级以上地方人民政府消防救援机构应当将发生火灾可能性较大以及发生火灾可能造成重大的人身伤亡或者财产损失的单位，确定为本行政区域内的消防安全重点单位，并由应急管理部门报本级人民政府备案。 消防安全重点单位除应当履行本法"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第十六条", "text": "规定的职责外，还应当履行下列消防安全职责： （一）确定消防安全管理人，组织实施本单位的消防安全管理工作； （二）建立消防档案，确定消防安全重点部位，设置防火标志，实行严格管理； （三）实行每日防火巡查，并建立巡查记录； （四）对职工进行岗前消防安全培训，定期组织消防安全培训和消防演练。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第十八条", "text": "同一建筑物由两个以上单位管理或者使用的，应当明确各方的消防安全责任，并确定责任人对共用的疏散通道、安全出口、建筑消防设施和消防车通道进行统一管理。 住宅区的物业服务企业应当对管理区域内的共用消防设施进行维护管理，提供消防安全防范服务。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第十九条", "text": "生产、储存、经营易燃易爆危险品的场所不得与居住场所设置在同一建筑物内，并应当与居住场所保持安全距离。 生产、储存、经营其他物品的场所与居住场所设置在同一建筑物内的，应当符合国家工程建设消防技术标准。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第二十条", "text": "举办大型群众性活动，承办人应当依法向公安机关申请安全许可，制定灭火和应急疏散预案并组织演练，明确消防安全责任分工，确定消防安全管理人员，保持消防设施和消防器材配置齐全、完好有效，保证疏散通道、安全出口、疏散指示标志、应急照明和消防车通道符合消防技术标准和管理规定。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第二十一条", "text": "禁止在具有火灾、爆炸危险的场所吸烟、使用明火。因施工等特殊情况需要使用明火作业的，应当按照规定事先办理审批手续，采取相应的消防安全措施；作业人员应当遵守消防安全规定。 进行电焊、气焊等具有火灾危险作业的人员和自动消防系统的操作人员，必须持证上岗，并遵守消防安全操作规程。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第二十二条", "text": "生产、储存、装卸易燃易爆危险品的工厂、仓库和专用车站、码头的设置，应当符合消防技术标准。易燃易爆气体和液体的充装站、供应站、调压站，应当设置在符合消防安全要求的位置，并符合防火防爆要求。 已经设置的生产、储存、装卸易燃易爆危险品的工厂、仓库和专用车站、码头，易燃易爆气体和液体的充装站、供应站、调压站，不再符合前款规定的，地方人民政府应当组织、协调有关部门、单位限期解决，消除安全隐患。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第二十三条", "text": "生产、储存、运输、销售、使用、销毁易燃易爆危险品，必须执行消防技术标准和管理规定。 进入生产、储存易燃易爆危险品的场所，必须执行消防安全规定。禁止非法携带易燃易爆危险品进入公共场所或者乘坐公共交通工具。 储存可燃物资仓库的管理，必须执行消防技术标准和管理规定。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第二十四条", "text": "消防产品必须符合国家标准；没有国家标准的，必须符合行业标准。禁止生产、销售或者使用不合格的消防产品以及国家明令淘汰的消防产品。 依法实行强制性产品认证的消防产品，由具有法定资质的认证机构按照国家标准、行业标准的强制性要求认证合格后，方可生产、销售、使用。实行强制性产品认证的消防产品目录，由国务院产品质量监督部门会同国务院应急管理部门制定并公布。 新研制的尚未制定国家标准、行业标准的消防产品，应当按照国务院产品质量监督部门会同国务院应急管理部门规定的办法，经技术鉴定符合消防安全要求的，方可生产、销售、使用。 依照本条规定经强制性产品认证合格或者技术鉴定合格的消防产品，国务院应急管理部门应当予以公布。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第二十五条", "text": "产品质量监督部门、工商行政管理部门、消防救援机构应当按照各自职责加强对消防产品质量的监督检查。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第二十六条", "text": "建筑构件、建筑材料和室内装修、装饰材料的防火性能必须符合国家标准；没有国家标准的，必须符合行业标准。 人员密集场所室内装修、装饰，应当按照消防技术标准的要求，使用不燃、难燃材料。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第二十七条", "text": "电器产品、燃气用具的产品标准，应当符合消防安全的要求。 电器产品、燃气用具的安装、使用及其线路、管路的设计、敷设、维护保养、检测，必须符合消防技术标准和管理规定。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第二十八条", "text": "任何单位、个人不得损坏、挪用或者擅自拆除、停用消防设施、器材，不得埋压、圈占、遮挡消火栓或者占用防火间距，不得占用、堵塞、封闭疏散通道、安全出口、消防车通道。人员密集场所的门窗不得设置影响逃生和灭火救援的障碍物。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第二十九条", "text": "负责公共消防设施维护管理的单位，应当保持消防供水、消防通信、消防车通道等公共消防设施的完好有效。在修建道路以及停电、停水、截断通信线路时有可能影响消防队灭火救援的，有关单位必须事先通知当地消防救援机构。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第三十条", "text": "地方各级人民政府应当加强对农村消防工作的领导，采取措施加强公共消防设施建设，组织建立和督促落实消防安全责任制。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第三十一条", "text": "在农业收获季节、森林和草原防火期间、重大节假日期间以及火灾多发季节，地方各级人民政府应当组织开展有针对性的消防宣传教育，采取防火措施，进行消防安全检查。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第三十二条", "text": "乡镇人民政府、城市街道办事处应当指导、支持和帮助村民委员会、居民委员会开展群众性的消防工作。村民委员会、居民委员会应当确定消防安全管理人，组织制定防火安全公约，进行防火安全检查。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第三十三条", "text": "国家鼓励、引导公众聚集场所和生产、储存、运输、销售易燃易爆危险品的企业投保火灾公众责任保险；鼓励保险公司承保火灾公众责任保险。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第三十四条", "text": "消防设施维护保养检测、消防安全评估等消防技术服务机构应当符合从业条件，执业人员应当依法获得相应的资格；依照法律、行政法规、国家标准、行业标准和执业准则，接受委托提供消防技术服务，并对服务质量负责。 第三章 消防组织"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第三十五条", "text": "各级人民政府应当加强消防组织建设，根据经济社会发展的需要，建立多种形式的消防组织，加强消防技术人才培养，增强火灾预防、扑救和应急救援的能力。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第三十六条", "text": "县级以上地方人民政府应当按照国家规定建立国家综合性消防救援队、专职消防队，并按照国家标准配备消防装备，承担火灾扑救工作。 乡镇人民政府应当根据当地经济发展和消防工作的需要，建立专职消防队、志愿消防队，承担火灾扑救工作。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第三十七条", "text": "国家综合性消防救援队、专职消防队按照国家规定承担重大灾害事故和其他以抢救人员生命为主的应急救援工作。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第三十八条", "text": "国家综合性消防救援队、专职消防队应当充分发挥火灾扑救和应急救援专业力量的骨干作用；按照国家规定，组织实施专业技能训练，配备并维护保养装备器材，提高火灾扑救和应急救援的能力。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第三十九条", "text": "下列单位应当建立单位专职消防队，承担本单位的火灾扑救工作： （一）大型核设施单位、大型发电厂、民用机场、主要港口； （二）生产、储存易燃易爆危险品的大型企业； （三）储备可燃的重要物资的大型仓库、基地； （四）第一项、第二项、第三项规定以外的火灾危险性较大、距离国家综合性消防救援队较远的其他大型企业； （五）距离国家综合性消防救援队较远、被列为全国重点文物保护单位的古建筑群的管理单位。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第四十条", "text": "专职消防队的建立，应当符合国家有关规定，并报当地消防救援机构验收。 专职消防队的队员依法享受社会保险和福利待遇。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第四十一条", "text": "机关、团体、企业、事业等单位以及村民委员会、居民委员会根据需要，建立志愿消防队等多种形式的消防组织，开展群众性自防自救工作。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第四十二条", "text": "消防救援机构应当对专职消防队、志愿消防队等消防组织进行业务指导；根据扑救火灾的需要，可以调动指挥专职消防队参加火灾扑救工作。 第四章 灭火救援"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第四十三条", "text": "县级以上地方人民政府应当组织有关部门针对本行政区域内的火灾特点制定应急预案，建立应急反应和处置机制，为火灾扑救和应急救援工作提供人员、装备等保障。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第四十四条", "text": "任何人发现火灾都应当立即报警。任何单位、个人都应当无偿为报警提供便利，不得阻拦报警。严禁谎报火警。 人员密集场所发生火灾，该场所的现场工作人员应当立即组织、引导在场人员疏散。 任何单位发生火灾，必须立即组织力量扑救。邻近单位应当给予支援。 消防队接到火警，必须立即赶赴火灾现场，救助遇险人员，排除险情，扑灭火灾。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第四十五条", "text": "消防救援机构统一组织和指挥火灾现场扑救，应当优先保障遇险人员的生命安全。 火灾现场总指挥根据扑救火灾的需要，有权决定下列事项： （一）使用各种水源； （二）截断电力、可燃气体和可燃液体的输送，限制用火用电； （三）划定警戒区，实行局部交通管制； （四）利用临近建筑物和有关设施； （五）为了抢救人员和重要物资，防止火势蔓延，拆除或者破损毗邻火灾现场的建筑物、构筑物或者设施等； （六）调动供水、供电、供气、通信、医疗救护、交通运输、环境保护等有关单位协助灭火救援。 根据扑救火灾的紧急需要，有关地方人民政府应当组织人员、调集所需物资支援灭火。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第四十六条", "text": "国家综合性消防救援队、专职消防队参加火灾以外的其他重大灾害事故的应急救援工作，由县级以上人民政府统一领导。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第四十七条", "text": "消防车、消防艇前往执行火灾扑救或者应急救援任务，在确保安全的前提下，不受行驶速度、行驶路线、行驶方向和指挥信号的限制，其他车辆、船舶以及行人应当让行，不得穿插超越；收费公路、桥梁免收车辆通行费。交通管理指挥人员应当保证消防车、消防艇迅速通行。 赶赴火灾现场或者应急救援现场的消防人员和调集的消防装备、物资，需要铁路、水路或者航空运输的，有关单位应当优先运输。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第四十八条", "text": "消防车、消防艇以及消防器材、装备和设施，不得用于与消防和应急救援工作无关的事项。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第四十九条", "text": "国家综合性消防救援队、专职消防队扑救火灾、应急救援，不得收取任何费用。 单位专职消防队、志愿消防队参加扑救外单位火灾所损耗的燃料、灭火剂和器材、装备等，由火灾发生地的人民政府给予补偿。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第五十条", "text": "对因参加扑救火灾或者应急救援受伤、致残或者死亡的人员，按照国家有关规定给予医疗、抚恤。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第五十一条", "text": "消防救援机构有权根据需要封闭火灾现场，负责调查火灾原因，统计火灾损失。 火灾扑灭后，发生火灾的单位和相关人员应当按照消防救援机构的要求保护现场，接受事故调查，如实提供与火灾有关的情况。 消防救援机构根据火灾现场勘验、调查情况和有关的检验、鉴定意见，及时制作火灾事故认定书，作为处理火灾事故的证据。 第五章 监督检查"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第五十二条", "text": "地方各级人民政府应当落实消防工作责任制，对本级人民政府有关部门履行消防安全职责的情况进行监督检查。 县级以上地方人民政府有关部门应当根据本系统的特点，有针对性地开展消防安全检查，及时督促整改火灾隐患。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第五十三条", "text": "消防救援机构应当对机关、团体、企业、事业等单位遵守消防法律、法规的情况依法进行监督检查。公安派出所可以负责日常消防监督检查、开展消防宣传教育，具体办法由国务院公安部门规定。 消防救援机构、公安派出所的工作人员进行消防监督检查，应当出示证件。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第五十四条", "text": "消防救援机构在消防监督检查中发现火灾隐患的，应当通知有关单位或者个人立即采取措施消除隐患；不及时消除隐患可能严重威胁公共安全的，消防救援机构应当依照规定对危险部位或者场所采取临时查封措施。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第五十五条", "text": "消防救援机构在消防监督检查中发现城乡消防安全布局、公共消防设施不符合消防安全要求，或者发现本地区存在影响公共安全的重大火灾隐患的，应当由应急管理部门书面报告本级人民政府。 接到报告的人民政府应当及时核实情况，组织或者责成有关部门、单位采取措施，予以整改。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第五十六条", "text": "住房和城乡建设主管部门、消防救援机构及其工作人员应当按照法定的职权和程序进行消防设计审查、消防验收、备案抽查和消防安全检查，做到公正、严格、文明、高效。 住房和城乡建设主管部门、消防救援机构及其工作人员进行消防设计审查、消防验收、备案抽查和消防安全检查等，不得收取费用，不得利用职务谋取利益；不得利用职务为用户、建设单位指定或者变相指定消防产品的品牌、销售单位或者消防技术服务机构、消防设施施工单位。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第五十七条", "text": "住房和城乡建设主管部门、消防救援机构及其工作人员执行职务，应当自觉接受社会和公民的监督。 任何单位和个人都有权对住房和城乡建设主管部门、消防救援机构及其工作人员在执法中的违法行为进行检举、控告。收到检举、控告的机关，应当按照职责及时查处。 第六章 法律责任"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第五十八条", "text": "违反本法规定，有下列行为之一的，由住房和城乡建设主管部门、消防救援机构按照各自职权责令停止施工、停止使用或者停产停业，并处三万元以上三十万元以下罚款： （一）依法应当进行消防设计审查的建设工程，未经依法审查或者审查不合格，擅自施工的； （二）依法应当进行消防验收的建设工程，未经消防验收或者消防验收不合格，擅自投入使用的； （三）本法"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第十三条", "text": "规定的其他建设工程验收后经依法抽查不合格，不停止使用的； （四）公众聚集场所未经消防救援机构许可，擅自投入使用、营业的，或者经核查发现场所使用、营业情况与承诺内容不符的。 核查发现公众聚集场所使用、营业情况与承诺内容不符，经责令限期改正，逾期不整改或者整改后仍达不到要求的，依法撤销相应许可。 建设单位未依照本法规定在验收后报住房和城乡建设主管部门备案的，由住房和城乡建设主管部门责令改正，处五千元以下罚款。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第五十九条", "text": "违反本法规定，有下列行为之一的，由住房和城乡建设主管部门责令改正或者停止施工，并处一万元以上十万元以下罚款： （一）建设单位要求建筑设计单位或者建筑施工企业降低消防技术标准设计、施工的； （二）建筑设计单位不按照消防技术标准强制性要求进行消防设计的； （三）建筑施工企业不按照消防设计文件和消防技术标准施工，降低消防施工质量的； （四）工程监理单位与建设单位或者建筑施工企业串通，弄虚作假，降低消防施工质量的。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第六十条", "text": "单位违反本法规定，有下列行为之一的，责令改正，处五千元以上五万元以下罚款： （一）消防设施、器材或者消防安全标志的配置、设置不符合国家标准、行业标准，或者未保持完好有效的； （二）损坏、挪用或者擅自拆除、停用消防设施、器材的； （三）占用、堵塞、封闭疏散通道、安全出口或者有其他妨碍安全疏散行为的； （四）埋压、圈占、遮挡消火栓或者占用防火间距的； （五）占用、堵塞、封闭消防车通道，妨碍消防车通行的； （六）人员密集场所在门窗上设置影响逃生和灭火救援的障碍物的； （七）对火灾隐患经消防救援机构通知后不及时采取措施消除的。 个人有前款第二项、第三项、第四项、第五项行为之一的，处警告或者五百元以下罚款。 有本条第一款第三项、第四项、第五项、第六项行为，经责令改正拒不改正的，强制执行，所需费用由违法行为人承担。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第六十一条", "text": "生产、储存、经营易燃易爆危险品的场所与居住场所设置在同一建筑物内，或者未与居住场所保持安全距离的，责令停产停业，并处五千元以上五万元以下罚款。 生产、储存、经营其他物品的场所与居住场所设置在同一建筑物内，不符合消防技术标准的，依照前款规定处罚。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第六十二条", "text": "有下列行为之一的，依照《中华人民共和国治安管理处罚法》的规定处罚： （一）违反有关消防技术标准和管理规定生产、储存、运输、销售、使用、销毁易燃易爆危险品的； （二）非法携带易燃易爆危险品进入公共场所或者乘坐公共交通工具的； （三）谎报火警的； （四）阻碍消防车、消防艇执行任务的； （五）阻碍消防救援机构的工作人员依法执行职务的。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第六十三条", "text": "违反本法规定，有下列行为之一的，处警告或者五百元以下罚款；情节严重的，处五日以下拘留： （一）违反消防安全规定进入生产、储存易燃易爆危险品场所的； （二）违反规定使用明火作业或者在具有火灾、爆炸危险的场所吸烟、使用明火的。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第六十四条", "text": "违反本法规定，有下列行为之一，尚不构成犯罪的，处十日以上十五日以下拘留，可以并处五百元以下罚款；情节较轻的，处警告或者五百元以下罚款： （一）指使或者强令他人违反消防安全规定，冒险作业的； （二）过失引起火灾的； （三）在火灾发生后阻拦报警，或者负有报告职责的人员不及时报警的； （四）扰乱火灾现场秩序，或者拒不执行火灾现场指挥员指挥，影响灭火救援的； （五）故意破坏或者伪造火灾现场的； （六）擅自拆封或者使用被消防救援机构查封的场所、部位的。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第六十五条", "text": "违反本法规定，生产、销售不合格的消防产品或者国家明令淘汰的消防产品的，由产品质量监督部门或者工商行政管理部门依照《中华人民共和国产品质量法》的规定从重处罚。 人员密集场所使用不合格的消防产品或者国家明令淘汰的消防产品的，责令限期改正；逾期不改正的，处五千元以上五万元以下罚款，并对其直接负责的主管人员和其他直接责任人员处五百元以上二千元以下罚款；情节严重的，责令停产停业。 消防救援机构对于本条第二款规定的情形，除依法对使用者予以处罚外，应当将发现不合格的消防产品和国家明令淘汰的消防产品的情况通报产品质量监督部门、工商行政管理部门。产品质量监督部门、工商行政管理部门应当对生产者、销售者依法及时查处。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第六十六条", "text": "电器产品、燃气用具的安装、使用及其线路、管路的设计、敷设、维护保养、检测不符合消防技术标准和管理规定的，责令限期改正；逾期不改正的，责令停止使用，可以并处一千元以上五千元以下罚款。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第六十七条", "text": "机关、团体、企业、事业等单位违反本法"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第二十一条", "text": "第二款规定的，责令限期改正；逾期不改正的，对其直接负责的主管人员和其他直接责任人员依法给予处分或者给予警告处罚。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第六十八条", "text": "人员密集场所发生火灾，该场所的现场工作人员不履行组织、引导在场人员疏散的义务，情节严重，尚不构成犯罪的，处五日以上十日以下拘留。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第六十九条", "text": "消防设施维护保养检测、消防安全评估等消防技术服务机构，不具备从业条件从事消防技术服务活动或者出具虚假文件的，由消防救援机构责令改正，处五万元以上十万元以下罚款，并对直接负责的主管人员和其他直接责任人员处一万元以上五万元以下罚款；不按照国家标准、行业标准开展消防技术服务活动的，责令改正，处五万元以下罚款，并对直接负责的主管人员和其它直接责任人员处一万元以下罚款；有违法所得的，并处没收违法所得；给他人造成损失的，依法承担赔偿责任；情节严重的，依法责令停止执业或者吊销相应资格；造成重大损失的，由相关部门吊销营业执照，并对有关责任人员采取终身市场禁入措施。 前款规定的机构出具失实文件，给他人造成损失的，依法承担赔偿责任；造成重大损失的，由消防救援机构依法责令停止执业或者吊销相应资格，由相关部门吊销营业执照，并对有关责任人员采取终身市场禁入措施。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第七十条", "text": "本法规定的行政处罚，除应当由公安机关依照《中华人民共和国治安管理处罚法》的有关规定决定的外，由住房和城乡建设主管部门、消防救援机构按照各自职权决定。 被责令停止施工、停止使用、停产停业的，应当在整改后向作出决定的部门或者机构报告，经检查合格，方可恢复施工、使用、生产、经营。 当事人逾期不执行停产停业、停止使用、停止施工决定的，由作出决定的部门或者机构强制执行。 责令停产停业，对经济和社会生活影响较大的，由住房和城乡建设主管部门或者应急管理部门报请本级人民政府依法决定。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第七十一条", "text": "住房和城乡建设主管部门、消防救援机构的工作人员滥用职权、玩忽职守、徇私舞弊，有下列行为之一，尚不构成犯罪的，依法给予处分： （一）对不符合消防安全要求的消防设计文件、建设工程、场所准予审查合格、消防验收合格、消防安全检查合格的； （二）无故拖延消防设计审查、消防验收、消防安全检查，不在法定期限内履行职责的； （三）发现火灾隐患不及时通知有关单位或者个人整改的； （四）利用职务为用户、建设单位指定或者变相指定消防产品的品牌、销售单位或者消防技术服务机构、消防设施施工单位的； （五）将消防车、消防艇以及消防器材、装备和设施用于与消防和应急救援无关的事项的； （六）其他滥用职权、玩忽职守、徇私舞弊的行为。 产品质量监督、工商行政管理等其他有关行政主管部门的工作人员在消防工作中滥用职权、玩忽职守、徇私舞弊，尚不构成犯罪的，依法给予处分。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第七十二条", "text": "违反本法规定，构成犯罪的，依法追究刑事责任。 第七章 附 则"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第七十三条", "text": "本法下列用语的含义： （一）消防设施，是指火灾自动报警系统、自动灭火系统、消火栓系统、防烟排烟系统以及应急广播和应急照明、安全疏散设施等。 （二）消防产品，是指专门用于火灾预防、灭火救援和火灾防护、避难、逃生的产品。 （三）公众聚集场所，是指宾馆、饭店、商场、集贸市场、客运车站候车室、客运码头候船厅、民用机场航站楼、体育场馆、会堂以及公共娱乐场所等。 （四）人员密集场所，是指公众聚集场所，医院的门诊楼、病房楼，学校的教学楼、图书馆、食堂和集体宿舍，养老院，福利院，托儿所，幼儿园，公共图书馆的阅览室，公共展览馆、博物馆的展示厅，劳动密集型企业的生产加工车间和员工集体宿舍，旅游、宗教活动场所等。"}, {"law": "中华人民共和国消防法_20210429.docx", "no": "第七十四条", "text": "本法自2009年5月1日起施行。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第一条", "text": "为了加强特种设备安全工作，预防特种设备事故，保障人身和财产安全，促进经济社会发展，制定本法。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第二条", "text": "特种设备的生产（包括设计、制造、安装、改造、修理）、经营、使用、检验、检测和特种设备安全的监督管理，适用本法。 本法所称特种设备，是指对人身和财产安全有较大危险性的锅炉、压力容器（含气瓶）、压力管道、电梯、起重机械、客运索道、大型游乐设施、场（厂）内专用机动车辆，以及法律、行政法规规定适用本法的其他特种设备。 国家对特种设备实行目录管理。特种设备目录由国务院负责特种设备安全监督管理的部门制定，报国务院批准后执行。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第三条", "text": "特种设备安全工作应当坚持安全第一、预防为主、节能环保、综合治理的原则。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第四条", "text": "国家对特种设备的生产、经营、使用，实施分类的、全过程的安全监督管理。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第五条", "text": "国务院负责特种设备安全监督管理的部门对全国特种设备安全实施监督管理。县级以上地方各级人民政府负责特种设备安全监督管理的部门对本行政区域内特种设备安全实施监督管理。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第六条", "text": "国务院和地方各级人民政府应当加强对特种设备安全工作的领导，督促各有关部门依法履行监督管理职责。 县级以上地方各级人民政府应当建立协调机制，及时协调、解决特种设备安全监督管理中存在的问题。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第七条", "text": "特种设备生产、经营、使用单位应当遵守本法和其他有关法律、法规，建立、健全特种设备安全和节能责任制度，加强特种设备安全和节能管理，确保特种设备生产、经营、使用安全，符合节能要求。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第八条", "text": "特种设备生产、经营、使用、检验、检测应当遵守有关特种设备安全技术规范及相关标准。 特种设备安全技术规范由国务院负责特种设备安全监督管理的部门制定。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第九条", "text": "特种设备行业协会应当加强行业自律，推进行业诚信体系建设，提高特种设备安全管理水平。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第十条", "text": "国家支持有关特种设备安全的科学技术研究，鼓励先进技术和先进管理方法的推广应用，对做出突出贡献的单位和个人给予奖励。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第十一条", "text": "负责特种设备安全监督管理的部门应当加强特种设备安全宣传教育，普及特种设备安全知识，增强社会公众的特种设备安全意识。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第十二条", "text": "任何单位和个人有权向负责特种设备安全监督管理的部门和有关部门举报涉及特种设备安全的违法行为，接到举报的部门应当及时处理。 第二章 生产、经营、使用 第一节 一般规定"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第十三条", "text": "特种设备生产、经营、使用单位及其主要负责人对其生产、经营、使用的特种设备安全负责。 特种设备生产、经营、使用单位应当按照国家有关规定配备特种设备安全管理人员、检测人员和作业人员，并对其进行必要的安全教育和技能培训。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第十四条", "text": "特种设备安全管理人员、检测人员和作业人员应当按照国家有关规定取得相应资格，方可从事相关工作。特种设备安全管理人员、检测人员和作业人员应当严格执行安全技术规范和管理制度，保证特种设备安全。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第十五条", "text": "特种设备生产、经营、使用单位对其生产、经营、使用的特种设备应当进行自行检测和维护保养，对国家规定实行检验的特种设备应当及时申报并接受检验。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第十六条", "text": "特种设备采用新材料、新技术、新工艺，与安全技术规范的要求不一致，或者安全技术规范未作要求、可能对安全性能有重大影响的，应当向国务院负责特种设备安全监督管理的部门申报，由国务院负责特种设备安全监督管理的部门及时委托安全技术咨询机构或者相关专业机构进行技术评审，评审结果经国务院负责特种设备安全监督管理的部门批准，方可投入生产、使用。 国务院负责特种设备安全监督管理的部门应当将允许使用的新材料、新技术、新工艺的有关技术要求，及时纳入安全技术规范。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第十七条", "text": "国家鼓励投保特种设备安全责任保险。 第二节 生 产"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第十八条", "text": "国家按照分类监督管理的原则对特种设备生产实行许可制度。特种设备生产单位应当具备下列条件，并经负责特种设备安全监督管理的部门许可，方可从事生产活动： （一）有与生产相适应的专业技术人员； （二）有与生产相适应的设备、设施和工作场所； （三）有健全的质量保证、安全管理和岗位责任等制度。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第十九条", "text": "特种设备生产单位应当保证特种设备生产符合安全技术规范及相关标准的要求，对其生产的特种设备的安全性能负责。不得生产不符合安全性能要求和能效指标以及国家明令淘汰的特种设备。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第二十条", "text": "锅炉、气瓶、氧舱、客运索道、大型游乐设施的设计文件，应当经负责特种设备安全监督管理的部门核准的检验机构鉴定，方可用于制造。 特种设备产品、部件或者试制的特种设备新产品、新部件以及特种设备采用的新材料，按照安全技术规范的要求需要通过型式试验进行安全性验证的，应当经负责特种设备安全监督管理的部门核准的检验机构进行型式试验。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第二十一条", "text": "特种设备出厂时，应当随附安全技术规范要求的设计文件、产品质量合格证明、安装及使用维护保养说明、监督检验证明等相关技术资料和文件，并在特种设备显著位置设置产品铭牌、安全警示标志及其说明。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第二十二条", "text": "电梯的安装、改造、修理，必须由电梯制造单位或者其委托的依照本法取得相应许可的单位进行。电梯制造单位委托其他单位进行电梯安装、改造、修理的，应当对其安装、改造、修理进行安全指导和监控，并按照安全技术规范的要求进行校验和调试。电梯制造单位对电梯安全性能负责。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第二十三条", "text": "特种设备安装、改造、修理的施工单位应当在施工前将拟进行的特种设备安装、改造、修理情况书面告知直辖市或者设区的市级人民政府负责特种设备安全监督管理的部门。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第二十四条", "text": "特种设备安装、改造、修理竣工后，安装、改造、修理的施工单位应当在验收后三十日内将相关技术资料和文件移交特种设备使用单位。特种设备使用单位应当将其存入该特种设备的安全技术档案。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第二十五条", "text": "锅炉、压力容器、压力管道元件等特种设备的制造过程和锅炉、压力容器、压力管道、电梯、起重机械、客运索道、大型游乐设施的安装、改造、重大修理过程，应当经特种设备检验机构按照安全技术规范的要求进行监督检验；未经监督检验或者监督检验不合格的，不得出厂或者交付使用。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第二十六条", "text": "国家建立缺陷特种设备召回制度。因生产原因造成特种设备存在危及安全的同一性缺陷的，特种设备生产单位应当立即停止生产，主动召回。 国务院负责特种设备安全监督管理的部门发现特种设备存在应当召回而未召回的情形时，应当责令特种设备生产单位召回。 第三节 经 营"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第二十七条", "text": "特种设备销售单位销售的特种设备，应当符合安全技术规范及相关标准的要求，其设计文件、产品质量合格证明、安装及使用维护保养说明、监督检验证明等相关技术资料和文件应当齐全。 特种设备销售单位应当建立特种设备检查验收和销售记录制度。 禁止销售未取得许可生产的特种设备，未经检验和检验不合格的特种设备，或者国家明令淘汰和已经报废的特种设备。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第二十八条", "text": "特种设备出租单位不得出租未取得许可生产的特种设备或者国家明令淘汰和已经报废的特种设备，以及未按照安全技术规范的要求进行维护保养和未经检验或者检验不合格的特种设备。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第二十九条", "text": "特种设备在出租期间的使用管理和维护保养义务由特种设备出租单位承担，法律另有规定或者当事人另有约定的除外。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第三十条", "text": "进口的特种设备应当符合我国安全技术规范的要求，并经检验合格；需要取得我国特种设备生产许可的，应当取得许可。 进口特种设备随附的技术资料和文件应当符合本法"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第二十一条", "text": "的规定，其安装及使用维护保养说明、产品铭牌、安全警示标志及其说明应当采用中文。 特种设备的进出口检验，应当遵守有关进出口商品检验的法律、行政法规。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第三十一条", "text": "进口特种设备，应当向进口地负责特种设备安全监督管理的部门履行提前告知义务。 第四节 使 用"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第三十二条", "text": "特种设备使用单位应当使用取得许可生产并经检验合格的特种设备。 禁止使用国家明令淘汰和已经报废的特种设备。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第三十三条", "text": "特种设备使用单位应当在特种设备投入使用前或者投入使用后三十日内，向负责特种设备安全监督管理的部门办理使用登记，取得使用登记证书。登记标志应当置于该特种设备的显著位置。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第三十四条", "text": "特种设备使用单位应当建立岗位责任、隐患治理、应急救援等安全管理制度，制定操作规程，保证特种设备安全运行。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第三十五条", "text": "特种设备使用单位应当建立特种设备安全技术档案。安全技术档案应当包括以下内容： （一）特种设备的设计文件、产品质量合格证明、安装及使用维护保养说明、监督检验证明等相关技术资料和文件； （二）特种设备的定期检验和定期自行检查记录； （三）特种设备的日常使用状况记录； （四）特种设备及其附属仪器仪表的维护保养记录； （五）特种设备的运行故障和事故记录。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第三十六条", "text": "电梯、客运索道、大型游乐设施等为公众提供服务的特种设备的运营使用单位，应当对特种设备的使用安全负责，设置特种设备安全管理机构或者配备专职的特种设备安全管理人员；其他特种设备使用单位，应当根据情况设置特种设备安全管理机构或者配备专职、兼职的特种设备安全管理人员。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第三十七条", "text": "特种设备的使用应当具有规定的安全距离、安全防护措施。 与特种设备安全相关的建筑物、附属设施，应当符合有关法律、行政法规的规定。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第三十八条", "text": "特种设备属于共有的，共有人可以委托物业服务单位或者其他管理人管理特种设备，受托人履行本法规定的特种设备使用单位的义务，承担相应责任。共有人未委托的，由共有人或者实际管理人履行管理义务，承担相应责任。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第三十九条", "text": "特种设备使用单位应当对其使用的特种设备进行经常性维护保养和定期自行检查，并作出记录。 特种设备使用单位应当对其使用的特种设备的安全附件、安全保护装置进行定期校验、检修，并作出记录。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第四十条", "text": "特种设备使用单位应当按照安全技术规范的要求，在检验合格有效期届满前一个月向特种设备检验机构提出定期检验要求。 特种设备检验机构接到定期检验要求后，应当按照安全技术规范的要求及时进行安全性能检验。特种设备使用单位应当将定期检验标志置于该特种设备的显著位置。 未经定期检验或者检验不合格的特种设备，不得继续使用。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第四十一条", "text": "特种设备安全管理人员应当对特种设备使用状况进行经常性检查，发现问题应当立即处理；情况紧急时，可以决定停止使用特种设备并及时报告本单位有关负责人。 特种设备作业人员在作业过程中发现事故隐患或者其他不安全因素，应当立即向特种设备安全管理人员和单位有关负责人报告；特种设备运行不正常时，特种设备作业人员应当按照操作规程采取有效措施保证安全。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第四十二条", "text": "特种设备出现故障或者发生异常情况，特种设备使用单位应当对其进行全面检查，消除事故隐患，方可继续使用。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第四十三条", "text": "客运索道、大型游乐设施在每日投入使用前，其运营使用单位应当进行试运行和例行安全检查，并对安全附件和安全保护装置进行检查确认。 电梯、客运索道、大型游乐设施的运营使用单位应当将电梯、客运索道、大型游乐设施的安全使用说明、安全注意事项和警示标志置于易于为乘客注意的显著位置。 公众乘坐或者操作电梯、客运索道、大型游乐设施，应当遵守安全使用说明和安全注意事项的要求，服从有关工作人员的管理和指挥；遇有运行不正常时，应当按照安全指引，有序撤离。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第四十四条", "text": "锅炉使用单位应当按照安全技术规范的要求进行锅炉水（介）质处理，并接受特种设备检验机构的定期检验。 从事锅炉清洗，应当按照安全技术规范的要求进行，并接受特种设备检验机构的监督检验。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第四十五条", "text": "电梯的维护保养应当由电梯制造单位或者依照本法取得许可的安装、改造、修理单位进行。 电梯的维护保养单位应当在维护保养中严格执行安全技术规范的要求，保证其维护保养的电梯的安全性能，并负责落实现场安全防护措施，保证施工安全。 电梯的维护保养单位应当对其维护保养的电梯的安全性能负责；接到故障通知后，应当立即赶赴现场，并采取必要的应急救援措施。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第四十六条", "text": "电梯投入使用后，电梯制造单位应当对其制造的电梯的安全运行情况进行跟踪调查和了解，对电梯的维护保养单位或者使用单位在维护保养和安全运行方面存在的问题，提出改进建议，并提供必要的技术帮助；发现电梯存在严重事故隐患时，应当及时告知电梯使用单位，并向负责特种设备安全监督管理的部门报告。电梯制造单位对调查和了解的情况，应当作出记录。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第四十七条", "text": "特种设备进行改造、修理，按照规定需要变更使用登记的，应当办理变更登记，方可继续使用。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第四十八条", "text": "特种设备存在严重事故隐患，无改造、修理价值，或者达到安全技术规范规定的其他报废条件的，特种设备使用单位应当依法履行报废义务，采取必要措施消除该特种设备的使用功能，并向原登记的负责特种设备安全监督管理的部门办理使用登记证书注销手续。 前款规定报废条件以外的特种设备，达到设计使用年限可以继续使用的，应当按照安全技术规范的要求通过检验或者安全评估，并办理使用登记证书变更，方可继续使用。允许继续使用的，应当采取加强检验、检测和维护保养等措施，确保使用安全。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第四十九条", "text": "移动式压力容器、气瓶充装单位，应当具备下列条件，并经负责特种设备安全监督管理的部门许可，方可从事充装活动： （一）有与充装和管理相适应的管理人员和技术人员； （二）有与充装和管理相适应的充装设备、检测手段、场地厂房、器具、安全设施； （三）有健全的充装管理制度、责任制度、处理措施。 充装单位应当建立充装前后的检查、记录制度，禁止对不符合安全技术规范要求的移动式压力容器和气瓶进行充装。 气瓶充装单位应当向气体使用者提供符合安全技术规范要求的气瓶，对气体使用者进行气瓶安全使用指导，并按照安全技术规范的要求办理气瓶使用登记，及时申报定期检验。 第三章 检验、检测"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第五十条", "text": "从事本法规定的监督检验、定期检验的特种设备检验机构，以及为特种设备生产、经营、使用提供检测服务的特种设备检测机构，应当具备下列条件，并经负责特种设备安全监督管理的部门核准，方可从事检验、检测工作： （一）有与检验、检测工作相适应的检验、检测人员； （二）有与检验、检测工作相适应的检验、检测仪器和设备； （三）有健全的检验、检测管理制度和责任制度。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第五十一条", "text": "特种设备检验、检测机构的检验、检测人员应当经考核，取得检验、检测人员资格，方可从事检验、检测工作。 特种设备检验、检测机构的检验、检测人员不得同时在两个以上检验、检测机构中执业；变更执业机构的，应当依法办理变更手续。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第五十二条", "text": "特种设备检验、检测工作应当遵守法律、行政法规的规定，并按照安全技术规范的要求进行。 特种设备检验、检测机构及其检验、检测人员应当依法为特种设备生产、经营、使用单位提供安全、可靠、便捷、诚信的检验、检测服务。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第五十三条", "text": "特种设备检验、检测机构及其检验、检测人员应当客观、公正、及时地出具检验、检测报告，并对检验、检测结果和鉴定结论负责。 特种设备检验、检测机构及其检验、检测人员在检验、检测中发现特种设备存在严重事故隐患时，应当及时告知相关单位，并立即向负责特种设备安全监督管理的部门报告。 负责特种设备安全监督管理的部门应当组织对特种设备检验、检测机构的检验、检测结果和鉴定结论进行监督抽查，但应当防止重复抽查。监督抽查结果应当向社会公布。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第五十四条", "text": "特种设备生产、经营、使用单位应当按照安全技术规范的要求向特种设备检验、检测机构及其检验、检测人员提供特种设备相关资料和必要的检验、检测条件，并对资料的真实性负责。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第五十五条", "text": "特种设备检验、检测机构及其检验、检测人员对检验、检测过程中知悉的商业秘密，负有保密义务。 特种设备检验、检测机构及其检验、检测人员不得从事有关特种设备的生产、经营活动，不得推荐或者监制、监销特种设备。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第五十六条", "text": "特种设备检验机构及其检验人员利用检验工作故意刁难特种设备生产、经营、使用单位的，特种设备生产、经营、使用单位有权向负责特种设备安全监督管理的部门投诉，接到投诉的部门应当及时进行调查处理。 第四章 监督管理"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第五十七条", "text": "负责特种设备安全监督管理的部门依照本法规定，对特种设备生产、经营、使用单位和检验、检测机构实施监督检查。 负责特种设备安全监督管理的部门应当对学校、幼儿园以及医院、车站、客运码头、商场、体育场馆、展览馆、公园等公众聚集场所的特种设备，实施重点安全监督检查。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第五十八条", "text": "负责特种设备安全监督管理的部门实施本法规定的许可工作，应当依照本法和其他有关法律、行政法规规定的条件和程序以及安全技术规范的要求进行审查；不符合规定的，不得许可。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第五十九条", "text": "负责特种设备安全监督管理的部门在办理本法规定的许可时，其受理、审查、许可的程序必须公开，并应当自受理申请之日起三十日内，作出许可或者不予许可的决定；不予许可的，应当书面向申请人说明理由。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第六十条", "text": "负责特种设备安全监督管理的部门对依法办理使用登记的特种设备应当建立完整的监督管理档案和信息查询系统；对达到报废条件的特种设备，应当及时督促特种设备使用单位依法履行报废义务。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第六十一条", "text": "负责特种设备安全监督管理的部门在依法履行监督检查职责时，可以行使下列职权： （一）进入现场进行检查，向特种设备生产、经营、使用单位和检验、检测机构的主要负责人和其他有关人员调查、了解有关情况； （二）根据举报或者取得的涉嫌违法证据，查阅、复制特种设备生产、经营、使用单位和检验、检测机构的有关合同、发票、账簿以及其他有关资料； （三）对有证据表明不符合安全技术规范要求或者存在严重事故隐患的特种设备实施查封、扣押； （四）对流入市场的达到报废条件或者已经报废的特种设备实施查封、扣押； （五）对违反本法规定的行为作出行政处罚决定。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第六十二条", "text": "负责特种设备安全监督管理的部门在依法履行职责过程中，发现违反本法规定和安全技术规范要求的行为或者特种设备存在事故隐患时，应当以书面形式发出特种设备安全监察指令，责令有关单位及时采取措施予以改正或者消除事故隐患。紧急情况下要求有关单位采取紧急处置措施的，应当随后补发特种设备安全监察指令。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第六十三条", "text": "负责特种设备安全监督管理的部门在依法履行职责过程中，发现重大违法行为或者特种设备存在严重事故隐患时，应当责令有关单位立即停止违法行为、采取措施消除事故隐患，并及时向上级负责特种设备安全监督管理的部门报告。接到报告的负责特种设备安全监督管理的部门应当采取必要措施，及时予以处理。 对违法行为、严重事故隐患的处理需要当地人民政府和有关部门的支持、配合时，负责特种设备安全监督管理的部门应当报告当地人民政府，并通知其他有关部门。当地人民政府和其他有关部门应当采取必要措施，及时予以处理。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第六十四条", "text": "地方各级人民政府负责特种设备安全监督管理的部门不得要求已经依照本法规定在其他地方取得许可的特种设备生产单位重复取得许可，不得要求对已经依照本法规定在其他地方检验合格的特种设备重复进行检验。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第六十五条", "text": "负责特种设备安全监督管理的部门的安全监察人员应当熟悉相关法律、法规，具有相应的专业知识和工作经验，取得特种设备安全行政执法证件。 特种设备安全监察人员应当忠于职守、坚持原则、秉公执法。 负责特种设备安全监督管理的部门实施安全监督检查时，应当有二名以上特种设备安全监察人员参加，并出示有效的特种设备安全行政执法证件。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第六十六条", "text": "负责特种设备安全监督管理的部门对特种设备生产、经营、使用单位和检验、检测机构实施监督检查，应当对每次监督检查的内容、发现的问题及处理情况作出记录，并由参加监督检查的特种设备安全监察人员和被检查单位的有关负责人签字后归档。被检查单位的有关负责人拒绝签字的，特种设备安全监察人员应当将情况记录在案。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第六十七条", "text": "负责特种设备安全监督管理的部门及其工作人员不得推荐或者监制、监销特种设备；对履行职责过程中知悉的商业秘密负有保密义务。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第六十八条", "text": "国务院负责特种设备安全监督管理的部门和省、自治区、直辖市人民政府负责特种设备安全监督管理的部门应当定期向社会公布特种设备安全总体状况。 第五章 事故应急救援与调查处理"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第六十九条", "text": "国务院负责特种设备安全监督管理的部门应当依法组织制定特种设备重特大事故应急预案，报国务院批准后纳入国家突发事件应急预案体系。 县级以上地方各级人民政府及其负责特种设备安全监督管理的部门应当依法组织制定本行政区域内特种设备事故应急预案，建立或者纳入相应的应急处置与救援体系。 特种设备使用单位应当制定特种设备事故应急专项预案，并定期进行应急演练。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第七十条", "text": "特种设备发生事故后，事故发生单位应当按照应急预案采取措施，组织抢救，防止事故扩大，减少人员伤亡和财产损失，保护事故现场和有关证据，并及时向事故发生地县级以上人民政府负责特种设备安全监督管理的部门和有关部门报告。 县级以上人民政府负责特种设备安全监督管理的部门接到事故报告，应当尽快核实情况，立即向本级人民政府报告，并按照规定逐级上报。必要时，负责特种设备安全监督管理的部门可以越级上报事故情况。对特别重大事故、重大事故，国务院负责特种设备安全监督管理的部门应当立即报告国务院并通报国务院安全生产监督管理部门等有关部门。 与事故相关的单位和人员不得迟报、谎报或者瞒报事故情况，不得隐匿、毁灭有关证据或者故意破坏事故现场。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第七十一条", "text": "事故发生地人民政府接到事故报告，应当依法启动应急预案，采取应急处置措施，组织应急救援。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第七十二条", "text": "特种设备发生特别重大事故，由国务院或者国务院授权有关部门组织事故调查组进行调查。 发生重大事故，由国务院负责特种设备安全监督管理的部门会同有关部门组织事故调查组进行调查。 发生较大事故，由省、自治区、直辖市人民政府负责特种设备安全监督管理的部门会同有关部门组织事故调查组进行调查。 发生一般事故，由设区的市级人民政府负责特种设备安全监督管理的部门会同有关部门组织事故调查组进行调查。 事故调查组应当依法、独立、公正开展调查，提出事故调查报告。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第七十三条", "text": "组织事故调查的部门应当将事故调查报告报本级人民政府，并报上一级人民政府负责特种设备安全监督管理的部门备案。有关部门和单位应当依照法律、行政法规的规定，追究事故责任单位和人员的责任。 事故责任单位应当依法落实整改措施，预防同类事故发生。事故造成损害的，事故责任单位应当依法承担赔偿责任。 第六章 法律责任"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第七十四条", "text": "违反本法规定，未经许可从事特种设备生产活动的，责令停止生产，没收违法制造的特种设备，处十万元以上五十万元以下罚款；有违法所得的，没收违法所得；已经实施安装、改造、修理的，责令恢复原状或者责令限期由取得许可的单位重新安装、改造、修理。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第七十五条", "text": "违反本法规定，特种设备的设计文件未经鉴定，擅自用于制造的，责令改正，没收违法制造的特种设备，处五万元以上五十万元以下罚款。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第七十六条", "text": "违反本法规定，未进行型式试验的，责令限期改正；逾期未改正的，处三万元以上三十万元以下罚款。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第七十七条", "text": "违反本法规定，特种设备出厂时，未按照安全技术规范的要求随附相关技术资料和文件的，责令限期改正；逾期未改正的，责令停止制造、销售，处二万元以上二十万元以下罚款；有违法所得的，没收违法所得。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第七十八条", "text": "违反本法规定，特种设备安装、改造、修理的施工单位在施工前未书面告知负责特种设备安全监督管理的部门即行施工的，或者在验收后三十日内未将相关技术资料和文件移交特种设备使用单位的，责令限期改正；逾期未改正的，处一万元以上十万元以下罚款。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第七十九条", "text": "违反本法规定，特种设备的制造、安装、改造、重大修理以及锅炉清洗过程，未经监督检验的，责令限期改正；逾期未改正的，处五万元以上二十万元以下罚款；有违法所得的，没收违法所得；情节严重的，吊销生产许可证。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第八十条", "text": "违反本法规定，电梯制造单位有下列情形之一的，责令限期改正；逾期未改正的，处一万元以上十万元以下罚款： （一）未按照安全技术规范的要求对电梯进行校验、调试的； （二）对电梯的安全运行情况进行跟踪调查和了解时，发现存在严重事故隐患，未及时告知电梯使用单位并向负责特种设备安全监督管理的部门报告的。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第八十一条", "text": "违反本法规定，特种设备生产单位有下列行为之一的，责令限期改正；逾期未改正的，责令停止生产，处五万元以上五十万元以下罚款；情节严重的，吊销生产许可证： （一）不再具备生产条件、生产许可证已经过期或者超出许可范围生产的； （二）明知特种设备存在同一性缺陷，未立即停止生产并召回的。 违反本法规定，特种设备生产单位生产、销售、交付国家明令淘汰的特种设备的，责令停止生产、销售，没收违法生产、销售、交付的特种设备，处三万元以上三十万元以下罚款；有违法所得的，没收违法所得。 特种设备生产单位涂改、倒卖、出租、出借生产许可证的，责令停止生产，处五万元以上五十万元以下罚款；情节严重的，吊销生产许可证。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第八十二条", "text": "违反本法规定，特种设备经营单位有下列行为之一的，责令停止经营，没收违法经营的特种设备，处三万元以上三十万元以下罚款；有违法所得的，没收违法所得： （一）销售、出租未取得许可生产，未经检验或者检验不合格的特种设备的； （二）销售、出租国家明令淘汰、已经报废的特种设备，或者未按照安全技术规范的要求进行维护保养的特种设备的。 违反本法规定，特种设备销售单位未建立检查验收和销售记录制度，或者进口特种设备未履行提前告知义务的，责令改正，处一万元以上十万元以下罚款。 特种设备生产单位销售、交付未经检验或者检验不合格的特种设备的，依照本条第一款规定处罚；情节严重的，吊销生产许可证。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第八十三条", "text": "违反本法规定，特种设备使用单位有下列行为之一的，责令限期改正；逾期未改正的，责令停止使用有关特种设备，处一万元以上十万元以下罚款： （一）使用特种设备未按照规定办理使用登记的； （二）未建立特种设备安全技术档案或者安全技术档案不符合规定要求，或者未依法设置使用登记标志、定期检验标志的； （三）未对其使用的特种设备进行经常性维护保养和定期自行检查，或者未对其使用的特种设备的安全附件、安全保护装置进行定期校验、检修，并作出记录的； （四）未按照安全技术规范的要求及时申报并接受检验的； （五）未按照安全技术规范的要求进行锅炉水（介）质处理的； （六）未制定特种设备事故应急专项预案的。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第八十四条", "text": "违反本法规定，特种设备使用单位有下列行为之一的，责令停止使用有关特种设备，处三万元以上三十万元以下罚款： （一）使用未取得许可生产，未经检验或者检验不合格的特种设备，或者国家明令淘汰、已经报废的特种设备的； （二）特种设备出现故障或者发生异常情况，未对其进行全面检查、消除事故隐患，继续使用的； （三）特种设备存在严重事故隐患，无改造、修理价值，或者达到安全技术规范规定的其他报废条件，未依法履行报废义务，并办理使用登记证书注销手续的。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第八十五条", "text": "违反本法规定，移动式压力容器、气瓶充装单位有下列行为之一的，责令改正，处二万元以上二十万元以下罚款；情节严重的，吊销充装许可证： （一）未按照规定实施充装前后的检查、记录制度的； （二）对不符合安全技术规范要求的移动式压力容器和气瓶进行充装的。 违反本法规定，未经许可，擅自从事移动式压力容器或者气瓶充装活动的，予以取缔，没收违法充装的气瓶，处十万元以上五十万元以下罚款；有违法所得的，没收违法所得。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第八十六条", "text": "违反本法规定，特种设备生产、经营、使用单位有下列情形之一的，责令限期改正；逾期未改正的，责令停止使用有关特种设备或者停产停业整顿，处一万元以上五万元以下罚款： （一）未配备具有相应资格的特种设备安全管理人员、检测人员和作业人员的； （二）使用未取得相应资格的人员从事特种设备安全管理、检测和作业的； （三）未对特种设备安全管理人员、检测人员和作业人员进行安全教育和技能培训的。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第八十七条", "text": "违反本法规定，电梯、客运索道、大型游乐设施的运营使用单位有下列情形之一的，责令限期改正；逾期未改正的，责令停止使用有关特种设备或者停产停业整顿，处二万元以上十万元以下罚款： （一）未设置特种设备安全管理机构或者配备专职的特种设备安全管理人员的； （二）客运索道、大型游乐设施每日投入使用前，未进行试运行和例行安全检查，未对安全附件和安全保护装置进行检查确认的； （三）未将电梯、客运索道、大型游乐设施的安全使用说明、安全注意事项和警示标志置于易于为乘客注意的显著位置的。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第八十八条", "text": "违反本法规定，未经许可，擅自从事电梯维护保养的，责令停止违法行为，处一万元以上十万元以下罚款；有违法所得的，没收违法所得。 电梯的维护保养单位未按照本法规定以及安全技术规范的要求，进行电梯维护保养的，依照前款规定处罚。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第八十九条", "text": "发生特种设备事故，有下列情形之一的，对单位处五万元以上二十万元以下罚款；对主要负责人处一万元以上五万元以下罚款；主要负责人属于国家工作人员的，并依法给予处分： （一）发生特种设备事故时，不立即组织抢救或者在事故调查处理期间擅离职守或者逃匿的； （二）对特种设备事故迟报、谎报或者瞒报的。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第九十条", "text": "发生事故，对负有责任的单位除要求其依法承担相应的赔偿等责任外，依照下列规定处以罚款： （一）发生一般事故，处十万元以上二十万元以下罚款； （二）发生较大事故，处二十万元以上五十万元以下罚款； （三）发生重大事故，处五十万元以上二百万元以下罚款。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第九十一条", "text": "对事故发生负有责任的单位的主要负责人未依法履行职责或者负有领导责任的，依照下列规定处以罚款；属于国家工作人员的，并依法给予处分： （一）发生一般事故，处上一年年收入百分之三十的罚款； （二）发生较大事故，处上一年年收入百分之四十的罚款； （三）发生重大事故，处上一年年收入百分之六十的罚款。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第九十二条", "text": "违反本法规定，特种设备安全管理人员、检测人员和作业人员不履行岗位职责，违反操作规程和有关安全规章制度，造成事故的，吊销相关人员的资格。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第九十三条", "text": "违反本法规定，特种设备检验、检测机构及其检验、检测人员有下列行为之一的，责令改正，对机构处五万元以上二十万元以下罚款，对直接负责的主管人员和其他直接责任人员处五千元以上五万元以下罚款；情节严重的，吊销机构资质和有关人员的资格： （一）未经核准或者超出核准范围、使用未取得相应资格的人员从事检验、检测的； （二）未按照安全技术规范的要求进行检验、检测的； （三）出具虚假的检验、检测结果和鉴定结论或者检验、检测结果和鉴定结论严重失实的； （四）发现特种设备存在严重事故隐患，未及时告知相关单位，并立即向负责特种设备安全监督管理的部门报告的； （五）泄露检验、检测过程中知悉的商业秘密的； （六）从事有关特种设备的生产、经营活动的； （七）推荐或者监制、监销特种设备的； （八）利用检验工作故意刁难相关单位的。 违反本法规定，特种设备检验、检测机构的检验、检测人员同时在两个以上检验、检测机构中执业的，处五千元以上五万元以下罚款；情节严重的，吊销其资格。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第九十四条", "text": "违反本法规定，负责特种设备安全监督管理的部门及其工作人员有下列行为之一的，由上级机关责令改正；对直接负责的主管人员和其他直接责任人员，依法给予处分： （一）未依照法律、行政法规规定的条件、程序实施许可的； （二）发现未经许可擅自从事特种设备的生产、使用或者检验、检测活动不予取缔或者不依法予以处理的； （三）发现特种设备生产单位不再具备本法规定的条件而不吊销其许可证，或者发现特种设备生产、经营、使用违法行为不予查处的； （四）发现特种设备检验、检测机构不再具备本法规定的条件而不撤销其核准，或者对其出具虚假的检验、检测结果和鉴定结论或者检验、检测结果和鉴定结论严重失实的行为不予查处的； （五）发现违反本法规定和安全技术规范要求的行为或者特种设备存在事故隐患，不立即处理的； （六）发现重大违法行为或者特种设备存在严重事故隐患，未及时向上级负责特种设备安全监督管理的部门报告，或者接到报告的负责特种设备安全监督管理的部门不立即处理的； （七）要求已经依照本法规定在其他地方取得许可的特种设备生产单位重复取得许可，或者要求对已经依照本法规定在其他地方检验合格的特种设备重复进行检验的； （八）推荐或者监制、监销特种设备的； （九）泄露履行职责过程中知悉的商业秘密的； （十）接到特种设备事故报告未立即向本级人民政府报告，并按照规定上报的； （十一）迟报、漏报、谎报或者瞒报事故的； （十二）妨碍事故救援或者事故调查处理的； （十三）其他滥用职权、玩忽职守、徇私舞弊的行为。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第九十五条", "text": "违反本法规定，特种设备生产、经营、使用单位或者检验、检测机构拒不接受负责特种设备安全监督管理的部门依法实施的监督检查的，责令限期改正；逾期未改正的，责令停产停业整顿，处二万元以上二十万元以下罚款。 特种设备生产、经营、使用单位擅自动用、调换、转移、损毁被查封、扣押的特种设备或者其主要部件的，责令改正，处五万元以上二十万元以下罚款；情节严重的，吊销生产许可证，注销特种设备使用登记证书。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第九十六条", "text": "违反本法规定，被依法吊销许可证的，自吊销许可证之日起三年内，负责特种设备安全监督管理的部门不予受理其新的许可申请。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第九十七条", "text": "违反本法规定，造成人身、财产损害的，依法承担民事责任。 违反本法规定，应当承担民事赔偿责任和缴纳罚款、罚金，其财产不足以同时支付时，先承担民事赔偿责任。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第九十八条", "text": "违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。 第七章 附 则"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第九十九条", "text": "特种设备行政许可、检验的收费，依照法律、行政法规的规定执行。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第一百条", "text": "军事装备、核设施、航空航天器使用的特种设备安全的监督管理不适用本法。 铁路机车、海上设施和船舶、矿山井下使用的特种设备以及民用机场专用设备安全的监督管理，房屋建筑工地、市政工程工地用起重机械和场（厂）内专用机动车辆的安装、使用的监督管理，由有关部门依照本法和其他有关法律的规定实施。"}, {"law": "中华人民共和国特种设备安全法_20130629.docx", "no": "第一百零一条", "text": "本法自2014年1月1日起施行。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一条", "text": "为了保护生态环境，防治污染和其他公害，保障公众健康和生态环境权益，维护生态安全，推动绿色低碳发展，建设生态文明，全面推进美丽中国建设，加快推进人与自然和谐共生的现代化，实现中华民族永续发展，根据宪法，制定本法。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二条", "text": "本法所称生态环境，是指影响人类生存和发展以及生态系统功能的各种天然的和经过人工改造的自然空间、自然因素及其相互联系与作用的总体，包括大气、水、海洋、土地、矿藏、森林、山岭、草原、湿地、冰川、高原、荒漠、野生生物、自然遗迹、人文遗迹、自然保护地、城市和乡村等。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三条", "text": "中华人民共和国领域和中华人民共和国管辖的其他海域内的污染防治、生态保护、绿色低碳发展等生态环境保护相关活动，适用本法。 在中华人民共和国领域和中华人民共和国管辖的其他海域以外，造成或者可能造成中华人民共和国领域和中华人民共和国管辖的其他海域环境污染、生态破坏的，适用本法相关规定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四条", "text": "生态环境保护坚持中国共产党的领导，贯彻习近平生态文明思想，树立尊重自然、顺应自然、保护自然的生态文明理念，坚持良好生态环境是最普惠的民生福祉，完善落实绿水青山就是金山银山理念的体制机制，坚持用最严格制度最严密法治保护生态环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五条", "text": "节约资源和保护生态环境是国家的基本国策。 国家采取有利于保护生态环境、促进人与自然和谐共生的经济、技术等政策措施，统筹产业结构调整、污染防治、生态保护、应对气候变化，协同推进降碳、减污、扩绿、增长，推进生态优先、节约集约和绿色低碳发展。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六条", "text": "生态环境保护坚持预防为主、系统治理、生态优先、绿色发展、公众参与、损害担责的原则。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七条", "text": "任何单位和个人都有保护生态环境的义务。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八条", "text": "各级人民政府应当加强生态环境保护工作，正确处理高质量发展和高水平保护的关系，根据生态环境保护目标和治理任务，采取有效措施，改善生态环境质量。 地方各级人民政府应当对本行政区域及其管理的海域的生态环境保护工作和生态环境质量负责。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九条", "text": "企业事业单位和其他生产经营者应当采取有效措施，防止、减少环境污染和生态破坏，节约集约利用资源，控制温室气体排放，履行绿色低碳发展义务，并对所造成的损害依法承担责任。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第十条", "text": "公民应当增强生态环境保护意识，采取简约适度、绿色低碳的生活方式，自觉履行生态环境保护义务，遵守生态环境法律法规，配合实施生态环境保护措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第十一条", "text": "国家支持生态环境科学技术研究、开发和应用，加强生态环境保护工作的科技支撑和人才培养，在确保安全前提下促进信息技术、数字技术、人工智能技术等的应用，提高生态环境保护的科学技术水平。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第十二条", "text": "各级人民政府及其有关部门应当加强生态环境保护宣传和普及工作，开展生态环境法治宣传教育，弘扬生态文化，增强公众的生态环境保护意识和法治素养。 教育行政部门、学校应当将生态环境法律法规和生态环境保护知识纳入学校教育内容，培养学生的生态环境保护意识和法治素养。 新闻媒体应当开展生态环境法律法规和生态环境保护知识的宣传，对生态环境违法行为进行舆论监督。 国家鼓励基层群众性自治组织、社会组织、生态环境保护志愿者等开展生态环境法律法规和生态环境保护知识的宣传，营造保护生态环境、建设生态文明的良好风气。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第十三条", "text": "对在生态环境保护工作中做出显著成绩的单位和个人，按照国家规定给予表彰和奖励。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第十四条", "text": "国家加强生态环境领域的国际合作，履行中华人民共和国缔结或者参加的国际条约规定的义务，支持生态环境保护国际交流与合作，积极参与生态环境国际规则的研究与制定，积极阐释中国特色生态环境法治理念、主张和成功实践，推动构建公平合理、合作共赢的全球环境治理体系。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第十五条", "text": "每年8月15日为全国生态日。国家通过多种形式开展生态文明宣传教育活动。 第二章 监督管理 第一节 监督管理体制和工作机制"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第十六条", "text": "县级以上人民政府应当组织、协调、督促有关部门依法履行生态环境保护监督管理职责。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第十七条", "text": "国务院生态环境主管部门在其职责范围内对全国生态环境保护工作实施统一监督管理，统一政策规划标准制定，统一监测评估，统一监督执法，统一督察问责。地方人民政府生态环境主管部门在其职责范围内对本行政区域生态环境保护工作实施统一监督管理。 国务院自然资源主管部门在其职责范围内对全国自然资源开发利用和保护工作实施监督管理，根据国务院授权统一履行全民所有自然资源资产所有者职责，统一履行所有国土空间用途管制和生态的保护与修复职责。地方人民政府自然资源主管部门在其职责范围内对本行政区域自然资源开发利用和保护，以及国土空间开发保护工作实施监督管理。 县级以上人民政府发展改革、工业和信息化、住房城乡建设、交通运输、水行政、农业农村、林业草原等有关部门和军队生态环境保护部门在各自职责范围内对生态环境保护工作实施监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第十八条", "text": "国家建立健全生态环境保护责任清单制度，明确国务院有关部门和地方人民政府有关部门的生态环境保护监督管理职责。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第十九条", "text": "省、市、县、乡依法建立健全河湖长制、林长制。各级河湖长负责本行政区域江河湖泊管理和保护相关工作；各级林长负责本行政区域森林草原资源保护发展相关工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二十条", "text": "县级以上地方人民政府根据实际需要建立生态环境保护工作协调联动机制，加强部门协同配合，推进本行政区域生态环境保护工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二十一条", "text": "国家建立健全跨行政区域的重点区域、流域、海域生态环境联合保护协调机制，实行统一规划、统一标准、统一监测、统一保护措施。 前款规定以外的跨行政区域的生态环境保护，由上级人民政府协调解决，或者由有关地方人民政府协商解决。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二十二条", "text": "国家完善生态安全工作协调机制，采取有效措施提升生态安全风险研判评估、监测预警、应急应对和处置能力，形成全域联动、立体高效的生态安全防护体系，统筹推进生态安全工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二十三条", "text": "国家建立健全生态环境信息共享机制，提升信息共享能力，加强生态环境信息共享。 县级以上人民政府应当推进生态环境信息共享平台建设，有关部门应当及时组织上传生态环境信息并动态更新。 第二节 监督管理制度"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二十四条", "text": "国家坚持分区域、差异化、精准管控，实施地上地下、陆海统筹、区域联动的生态环境监督管理制度，加强规划、标准、监测等监督管理制度的衔接协调。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二十五条", "text": "各级人民政府及其有关部门应当加强生态环境保护监督管理能力建设，提高生态环境保护监督管理信息化、数字化、智能化水平。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二十六条", "text": "国务院有关部门和县级以上地方人民政府组织制定经济、技术政策和措施，应当充分考虑对生态环境的影响，听取有关方面和专家的意见。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二十七条", "text": "国家实行生态环境保护目标责任制和考核评价制度，将生态环境保护目标完成情况纳入考核评价内容。考核评价工作应当增强针对性、实效性，力戒形式主义。考核结果应当向社会公开。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二十八条", "text": "国家建立健全生态环境保护督察制度，对有关方面履行生态文明建设和生态环境保护责任组织开展全面督察。生态环境保护督察实行中央和省、自治区、直辖市两级督察体制。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二十九条", "text": "被督察对象应当自觉接受生态环境保护督察，积极配合督察工作。 被督察对象收到生态环境保护督察反馈意见后，应当组织编制督察整改方案，针对督察反馈问题逐项明确整改实施主体、整改目标、整改时限、重点措施和验收单位。 对生态环境保护督察及整改中发现的重要生态环境问题及其失职失责情况，按照国家规定追责问责。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三十条", "text": "县级以上人民政府应当每年向本级人民代表大会或者人民代表大会常务委员会报告生态环境状况和生态环境保护目标完成情况，对发生的重大生态环境事件应当及时向本级人民代表大会常务委员会报告，依法接受监督。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三十一条", "text": "国家加强生态环境司法保障建设。 人民法院应当加强生态环境审判工作，推进生态环境专业化审判机制建设。 人民检察院应当加强生态环境检察工作，强化检察监督。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三十二条", "text": "国家完善生态环境损害赔偿和生态环境公益诉讼制度，维护国家利益、社会公共利益。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三十三条", "text": "行政机关、监察机关、审判机关和检察机关应当加强协同配合，建立健全案件移送、信息共享等机制，对污染环境、破坏生态等违法行为依法追究法律责任。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三十四条", "text": "国家实行自然资源资产离任审计，对领导干部履行自然资源资产管理和生态环境保护责任情况进行审计。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三十五条", "text": "国家加强生态的保护与修复，坚持山水林田湖草沙一体化保护与修复，实行自然恢复为主、自然恢复与人工修复相结合的系统治理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三十六条", "text": "国家健全主体功能区制度体系，根据城市化地区、农产品主产区、重点生态功能区等的不同定位，优化国土空间发展格局。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三十七条", "text": "国家完善资源总量管理和全面节约制度，避免资源浪费，提高资源利用效率。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三十八条", "text": "国家健全自然资源资产产权制度和管理制度体系，完善全民所有自然资源资产所有权委托代理机制，推进自然资源有偿使用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三十九条", "text": "国家健全生态产品价值实现机制，形成多元化的生态产品价值实现路径，推进生态产业化和产业生态化。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四十条", "text": "开发利用自然资源，应当合理开发，节约集约，高效利用，防止污染环境、破坏生态，减少温室气体排放，依法制定有关生态环境保护的方案并予以实施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四十一条", "text": "国家统筹水资源、水环境、水生态治理，加强水生态环境保护。 国家实行水资源刚性约束制度，坚持以水定城、以水定地、以水定人、以水定产，促进人口和城市科学合理布局，构建与水资源承载能力相适应的现代产业体系，保障国家水安全。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四十二条", "text": "国家加强生物多样性保护，建立健全生物多样性保护工作协调机制和生物多样性调查、监测、评估和保护制度，合理布局建设生物多样性保护空间体系。 引进外来物种以及研究、开发和利用生物技术，应当采取有效措施，防止对生物多样性的破坏。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四十三条", "text": "国家建设以国家公园为主体、以自然保护区为基础、以各类自然公园为补充的自然保护地体系，确保重要生态系统、自然遗迹、自然景观和生物多样性得到系统性保护。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四十四条", "text": "国家推进青藏高原生态屏障区、长江重点生态区、黄河重点生态区和东北森林带、北方防沙带、南方丘陵山地带、海岸带等区域生态屏障建设，加强长江、黄河、淮河、海河、珠江、松花江、辽河、洞庭湖、鄱阳湖、太湖、洪泽湖、巢湖等重要江河湖泊生态环境保护。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四十五条", "text": "国务院生态环境主管部门根据海洋生态环境状况和质量改善要求，会同国务院发展改革、自然资源、住房城乡建设、交通运输、水行政、渔业渔政、林业草原等有关部门和海警机构，划定国家生态环境治理重点海域及其控制区域，拟订综合治理行动方案，报国务院批准后实施。 沿海设区的市级以上地方人民政府应当根据综合治理行动方案，制定其管理海域的实施方案，因地制宜采取特别管控措施，开展综合治理，协同推进重点海域治理与美丽海湾建设。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四十六条", "text": "各级人民政府应当加强对农业生态环境的保护，促进农业生态环境保护新技术的应用，加强对农业污染源的监测预警，统筹有关部门采取有效措施，防治土壤污染和土地沙化、酸化、盐渍化、贫瘠化、石漠化、地面沉降以及防治植被破坏、水土流失、水体富营养化、水源枯竭、种源灭绝、外来物种入侵等生态失调现象，推广植物病虫害的综合防治。 各级人民政府应当提高农村生态环境保护公共服务水平，推动农村生态环境综合整治，持续改善农村人居环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四十七条", "text": "城乡建设应当结合当地自然的生态环境特点，保护植被、水域和自然景观、人文遗迹、古树名木等，加强城市园林、绿地的建设与管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四十八条", "text": "国家建立健全生态环境与健康监测、调查和风险评估制度；鼓励和组织开展生态环境质量对公众健康影响的研究，采取有效措施预防和控制与环境污染、生态破坏等有关的疾病。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四十九条", "text": "国家对严重污染环境、破坏生态等的技术、工艺、设备、材料、产品实行淘汰制度。 国务院发展改革部门会同有关部门确定严重污染环境、破坏生态等的技术、工艺、设备、材料、产品淘汰期限，并纳入国家综合性产业政策目录。 生产者、进口者、销售者、使用者应当在规定期限内停止生产、进口、销售、使用列入前款规定目录的设备、材料、产品。技术、工艺的采用者应当在规定期限内停止采用列入前款规定目录的技术、工艺。 被淘汰的设备、材料、产品，不得转让给他人使用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五十条", "text": "国务院负有生态环境保护监督管理职责的部门以及重点区域、流域、海域有关省、自治区、直辖市人民政府可以组织有关部门开展联合执法，跨行政区域、流域、海域执法，交叉执法。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五十一条", "text": "负有生态环境保护监督管理职责的部门有权依法对污染环境、破坏生态等的企业事业单位和其他生产经营者以及生态环境技术服务机构等进行现场检查。被检查者应当如实反映情况，提供必要的资料。实施现场检查的部门及其工作人员应当为被检查者保守商业秘密、个人隐私和个人信息。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五十二条", "text": "企业事业单位和其他生产经营者违反法律法规规定，造成或者可能造成严重污染环境、破坏生态等后果，或者有关证据可能灭失、被隐匿的，负有生态环境保护监督管理职责的部门可以依法查封、扣押有关场所、船舶、设施、设备、工具、物品。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五十三条", "text": "设区的市级人民政府生态环境主管部门设立的派出机构，可以以自己的名义依法实施现场检查、查封、扣押、代履行和行政处罚。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五十四条", "text": "国家构建生态环境信用监管体系。 负有生态环境保护监督管理职责的部门应当依法将企业事业单位和其他生产经营者有关生态环境违法信息记入信用记录。 企业事业单位和其他生产经营者纠正失信行为、消除不良影响、符合信用修复条件的，可以提出信用修复申请，有关国家机关应当按照规定开展信用修复。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五十五条", "text": "在中华人民共和国领域和中华人民共和国管辖的其他海域以外，造成或者可能造成中华人民共和国领域和中华人民共和国管辖的其他海域环境污染、生态破坏的，有关部门和机构有权采取必要的措施。 第三章 规划和生态环境分区管控"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五十六条", "text": "国家建立健全以国家发展规划为统领，以国土空间规划为基础，以专项规划、区域规划为支撑，由国家和地方规划共同组成的国家规划体系，加强规划之间的衔接协调，发挥规划对生态环境保护的引领、指导和约束作用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五十七条", "text": "县级以上人民政府应当将生态环境保护工作纳入国民经济和社会发展规划。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五十八条", "text": "国家建立健全覆盖全域全类型、统一衔接的国土空间用途管制和规划许可制度，依据国土空间规划对国土空间实行分区、分类用途管制，国土空间开发利用活动应当符合国土空间用途管制要求，并依法取得规划许可。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五十九条", "text": "国土空间规划应当科学有序统筹安排农业、生态、城镇等功能空间，划定耕地和永久基本农田、生态保护红线、城镇开发边界，优化国土空间结构和布局。 涉及国土空间利用的专项规划应当与国土空间规划相衔接。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六十条", "text": "国家建立健全生态保护红线管理制度，优先将生态功能极重要区域、生态极敏感脆弱区域等区域划入生态保护红线，实行严格保护。 开发利用自然资源或者从事影响生态环境的建设活动，应当严守生态保护红线，不得造成生态环境的损害。 省、自治区、直辖市人民政府应当加强对生态保护红线内人为活动的监督管理，定期评估保护成效。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六十一条", "text": "国务院生态环境主管部门会同有关部门，根据国家发展规划编制国家生态环境保护规划，报国务院批准并公布实施。 设区的市级以上地方人民政府生态环境主管部门会同有关部门，根据国家生态环境保护规划的要求，编制本行政区域的生态环境保护规划，报本级人民政府批准并公布实施。 生态环境保护规划的内容应当包括污染防治、生态保护、应对气候变化的目标、任务、保障措施等。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六十二条", "text": "未达到国家生态环境质量标准的重点区域、流域、海域的有关地方人民政府，应当依法编制限期达标规划、改善规划及其实施方案，并采取有效措施按期达标、改善生态环境质量。限期达标规划、改善规划及其实施方案应当及时公布。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六十三条", "text": "生态环境、发展改革、自然资源、住房城乡建设、水行政、农业农村、林业草原等有关部门，可以在各自职责范围内根据实际需要编制有关生态环境领域的规划。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六十四条", "text": "国家可以根据实际需要，对国家发展规划确定的重点地区、跨行政区域且经济社会活动联系紧密的连片区域和承担重大战略任务的特定区域编制区域规划，指导区域生态环境保护和协调协同发展。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六十五条", "text": "编制生态环境领域的规划，应当征求有关部门、专家等方面的意见；规划实施后，规划编制机关应当按照国家规定组织开展监测分析和评估。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六十六条", "text": "国家建立健全生态环境分区管控制度。 设区的市级以上地方人民政府根据本行政区域的生态环境状况，制定和调整生态环境分区管控方案，报上一级人民政府生态环境主管部门备案后公布实施。 生态环境分区管控方案应当与国土空间规划相衔接。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六十七条", "text": "生态环境分区管控方案应当落实生态保护红线、环境质量底线、资源利用上线目标，划定优先保护、重点管控、一般管控单元，明确相应的生态环境准入清单。禁止违反生态环境准入清单规定进行生产建设活动。 第四章 标准和监测"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六十八条", "text": "国家推进生态环境领域标准体系建设，加强标准之间的衔接协调，发挥标准对生态环境保护的支撑作用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六十九条", "text": "国务院生态环境主管部门制定国家生态环境质量标准。 省、自治区、直辖市人民政府对国家生态环境质量标准中未作规定的项目，可以制定地方生态环境质量标准；对国家生态环境质量标准中已作规定的项目，可以制定严于国家生态环境质量标准的地方生态环境质量标准。地方生态环境质量标准应当报国务院生态环境主管部门备案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七十条", "text": "国务院生态环境、发展改革、工业和信息化、自然资源、住房城乡建设、交通运输、水行政、农业农村、林业草原、标准化等有关部门，在各自职责范围内依法制定有关污染防治、生态保护、绿色低碳发展等方面的标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七十一条", "text": "制定生态环境领域的标准，应当以保障公众健康、保护生态环境为宗旨，与经济社会发展相适应，做到科学合理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七十二条", "text": "制定生态环境领域的标准，应当组织专家进行审查和论证，并征求有关部门、行业协会、企业事业单位和公众等方面的意见，提高标准的科学性。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七十三条", "text": "生态环境领域标准的制定机关，应当在其网站上及时公布标准全文，供公众免费查阅、下载。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七十四条", "text": "生态环境领域标准的执行情况应当定期进行评估，根据评估结果对标准适时进行修订、废止。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七十五条", "text": "国家鼓励、支持开展生态环境基准研究。 国务院生态环境主管部门根据保障公众健康、保护生态环境的需要，制定生态环境基准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七十六条", "text": "国家建立健全生态环境监测制度。 国务院生态环境主管部门会同有关部门制定生态环境监测规范，构建陆海统筹、天地一体、上下协同、信息共享的生态环境监测网络，统一规划国家生态环境质量监测站点的设置，推进综合监测、协同监测和常态化监测，建立健全监测数据共享机制，加强对生态环境监测的管理。 生态环境、自然资源、住房城乡建设、交通运输、水行政、农业农村、气象、林业草原、疾病预防控制等有关部门，在各自职责范围内做好生态环境监测相关工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七十七条", "text": "各类生态环境监测站点的设置应当符合法律法规规定和有关监测规范的要求。 生态环境监测应当使用符合法律、行政法规规定和国家标准的监测设施、设备，遵守有关监测规范。 禁止生产、进口、销售或者使用不符合法律、行政法规规定和国家标准的监测设施、设备。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七十八条", "text": "生态环境监测机构、实行排污许可管理和其他负有法定监测义务的企业事业单位应当依法建立健全监测数据质量管理制度。 前款规定的监测机构和企业事业单位及其负责人应当对监测数据的真实性、准确性和完整性负责。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七十九条", "text": "生态环境监测机构应当具备相应的设施、设备、技术人员、技术能力和管理能力，并依法报有关部门备案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八十条", "text": "禁止通过干扰采样、调换样品、改变监测条件、虚假监测、篡改或者伪造记录等方式对生态环境监测数据弄虚作假或者指使对生态环境监测数据弄虚作假。 禁止通过侵占、损毁或者擅自移动、改变等方式干扰、破坏生态环境监测设施、设备或者指使干扰、破坏生态环境监测设施、设备。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八十一条", "text": "省级以上人民政府应当组织有关部门或者委托专业机构，对生态环境状况进行调查、评价，建立健全生态环境的承载能力监测预警机制。 第五章 生态环境影响评价 第一节 一般规定"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八十二条", "text": "本法所称生态环境影响评价，是指对规划和建设项目实施后可能造成的生态环境影响进行分析、预测和评估，提出预防或者减轻不良生态环境影响的对策和措施，进行跟踪监测的方法与制度。 国家加强温室气体排放的生态环境影响评价，具体办法和实施步骤由国务院生态环境主管部门规定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八十三条", "text": "编制有关开发利用规划，建设对生态环境有影响的项目，应当依法进行生态环境影响评价。 未依法进行生态环境影响评价的开发利用规划，不得组织实施；未依法进行生态环境影响评价的建设项目，不得开工建设。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八十四条", "text": "生态环境影响评价应当客观、公开、公正，综合考虑规划或者建设项目实施后对各种生态环境因素及其所构成的生态系统可能造成的影响，为决策提供科学依据。 国家鼓励有关单位、专家和公众依法参与生态环境影响评价。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八十五条", "text": "国家加强生态环境影响评价的基础数据库和评价指标体系建设，鼓励、支持对生态环境影响评价的方法、技术规范进行科学研究，建立必要的生态环境影响评价信息共享制度，提高生态环境影响评价的科学性。 国务院生态环境主管部门会同有关部门组织建立健全生态环境影响评价的基础数据库和评价指标体系。 第二节 规划的生态环境影响评价"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八十六条", "text": "国务院有关部门、设区的市级以上地方人民政府及其有关部门，对其组织编制的国土空间规划，区域、流域、海域的建设、开发利用规划，应当在规划编制过程中组织进行生态环境影响评价，编写该规划有关生态环境影响的篇章或者说明。 规划有关生态环境影响的篇章或者说明，应当对规划实施后可能造成的生态环境影响作出分析、预测和评估，提出预防或者减轻不良生态环境影响的对策和措施，作为规划草案的组成部分一并报送规划审批机关。 未编写有关生态环境影响的篇章或者说明的规划草案，审批机关不予审批。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八十七条", "text": "国务院有关部门、设区的市级以上地方人民政府及其有关部门，对其组织编制的工业、农业、林业、能源、水利、交通、城市和产业园区建设、旅游、自然资源开发的有关专项规划，应当在规划编制过程中组织进行生态环境影响评价，并向审批该专项规划的机关提出生态环境影响报告书。 前款所列专项规划中的指导性规划，依照本法"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八十六条", "text": "规定进行生态环境影响评价。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八十七条", "text": "规定进行生态环境影响评价的规划的具体范围，由国务院生态环境主管部门会同有关部门规定，报国务院批准。 省、自治区、直辖市人民政府可以根据本地实际情况，要求对本辖区的县级人民政府编制的规划进行生态环境影响评价。具体办法由省、自治区、直辖市参照本节规定制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八十九条", "text": "专项规划的生态环境影响报告书应当包括下列内容： （一）实施该规划对生态环境可能造成影响的分析、预测和评估； （二）预防或者减轻不良生态环境影响的对策和措施； （三）生态环境影响评价的结论。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九十条", "text": "专项规划的编制机关对可能造成不良生态环境影响并直接涉及公众生态环境权益的规划，应当在该规划草案报送审批前，举行论证会、听证会，或者采取其他形式，征求有关单位、专家和公众对生态环境影响报告书草案的意见。但是，国家规定不予公开的情形除外。 编制机关应当认真考虑有关单位、专家和公众对生态环境影响报告书草案的意见，并在报送审查的生态环境影响报告书中附具对意见采纳或者不采纳的说明。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九十一条", "text": "专项规划的编制机关在报批规划草案时，应当将生态环境影响报告书一并附送审批机关审查；未附送生态环境影响报告书的，审批机关不予审批。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九十二条", "text": "设区的市级以上人民政府在审批专项规划草案、作出决策前，应当先由其生态环境主管部门召集有关部门代表和专家组成审查小组，对生态环境影响报告书进行审查，并提出书面审查意见。 参加前款规定的审查小组的专家，应当从按照国务院生态环境主管部门规定设立的专家库内相关专业的专家名单中，以随机抽取的方式确定。 由省级以上人民政府有关部门负责审批的专项规划，其生态环境影响报告书的审查办法，由国务院生态环境主管部门会同有关部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九十三条", "text": "审查小组提出修改意见的，专项规划的编制机关应当根据生态环境影响报告书结论和审查意见对规划草案进行修改完善，并对生态环境影响报告书结论和审查意见的采纳情况作出说明；不采纳的，应当说明理由。 设区的市级以上人民政府或者省级以上人民政府有关部门在审批专项规划草案时，应当将生态环境影响报告书结论以及审查意见作为决策的重要依据。 在审批中未采纳生态环境影响报告书结论以及审查意见的，应当作出说明，并存档备查。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九十四条", "text": "对生态环境有重大影响的规划实施后，编制机关应当及时组织生态环境影响的跟踪评价，将评价结果报告审批机关，并通报生态环境等有关部门；发现有明显不良生态环境影响的，应当及时提出改进措施。 第三节 建设项目的生态环境影响评价"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九十五条", "text": "国家根据建设项目对生态环境的影响程度，对建设项目的生态环境影响评价实行分类管理。 建设单位应当按照下列规定组织编制生态环境影响报告书、生态环境影响报告表或者填报生态环境影响登记表： （一）可能造成重大生态环境影响的，应当编制生态环境影响报告书，对产生的生态环境影响进行全面评价； （二）可能造成轻度生态环境影响的，应当编制生态环境影响报告表，对产生的生态环境影响进行分析或者专项评价； （三）对生态环境影响很小，不需要编制生态环境影响报告书、生态环境影响报告表的，应当填报生态环境影响登记表。 建设项目的生态环境影响评价分类管理名录，由国务院生态环境主管部门制定并公布。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九十六条", "text": "建设项目的生态环境影响报告书应当包括下列内容： （一）建设项目概况； （二）建设项目周围生态环境现状； （三）建设项目对生态环境可能造成影响的分析、预测和评估； （四）建设项目生态环境保护措施及其技术、经济论证； （五）建设项目对生态环境影响的经济损益分析； （六）对建设项目实施生态环境监测和排放管理的建议； （七）生态环境影响评价的结论； （八）法律规定的其他内容。 生态环境影响报告表和生态环境影响登记表的内容和格式，由国务院生态环境主管部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九十七条", "text": "建设项目的生态环境影响评价，应当避免与规划的生态环境影响评价相重复。 作为一项整体建设项目的规划，按照建设项目进行生态环境影响评价，不进行规划的生态环境影响评价。 已经进行了生态环境影响评价的规划包含具体建设项目的，规划的生态环境影响评价结论应当作为建设项目生态环境影响评价的重要依据，建设项目生态环境影响评价的内容应当根据规划的生态环境影响评价审查意见予以简化。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九十八条", "text": "建设单位可以委托技术单位对其建设项目开展生态环境影响评价，编制建设项目生态环境影响报告书、生态环境影响报告表；建设单位具备生态环境影响评价技术能力的，可以自行对其建设项目开展生态环境影响评价，编制建设项目生态环境影响报告书、生态环境影响报告表。 编制建设项目生态环境影响报告书、生态环境影响报告表应当遵守国家有关生态环境影响评价标准、技术规范等规定。 建设项目生态环境影响报告书、生态环境影响报告表编制的管理办法由国务院生态环境主管部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九十九条", "text": "接受委托为建设单位编制建设项目生态环境影响报告书、生态环境影响报告表的技术单位应当依法独立客观公正开展业务，建立健全质量控制制度，确保所出具的生态环境影响报告书、生态环境影响报告表客观、真实、准确。 接受委托为建设单位编制建设项目生态环境影响报告书、生态环境影响报告表的技术单位和人员，应当具有良好的信用记录，不得与负责审批建设项目生态环境影响报告书、生态环境影响报告表的生态环境主管部门或者其他有关审批部门存在任何利益关系，编制、审核等关键岗位人员应当具有相关专业技术水平和从业经历。 接受委托为建设单位编制建设项目生态环境影响报告书、生态环境影响报告表的技术单位，应当报生态环境主管部门备案，生态环境主管部门应当加强对技术单位开展生态环境影响评价业务的监督管理。具体办法由国务院生态环境主管部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百条", "text": "建设单位应当对建设项目生态环境影响报告书、生态环境影响报告表的内容和结论负责，接受委托编制建设项目生态环境影响报告书、生态环境影响报告表的技术单位对其编制的建设项目生态环境影响报告书、生态环境影响报告表承担相应责任。 设区的市级以上人民政府生态环境主管部门应当加强对建设项目生态环境影响报告书、生态环境影响报告表编制单位和人员的监督管理和质量考核。 负责审批建设项目生态环境影响报告书、生态环境影响报告表的生态环境主管部门应当对编制单位、编制主持人和主要编制人员有关违法行为，依照法律规定进行信用监管。 任何单位和个人不得为建设单位指定编制建设项目生态环境影响报告书、生态环境影响报告表的技术单位。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百零一条", "text": "除国家规定不予公开的情形外，对生态环境可能造成重大影响、应当编制生态环境影响报告书的建设项目，建设单位应当在报批建设项目生态环境影响报告书前，举行论证会、听证会，或者采取其他形式，向可能受影响的公众说明情况，充分征求有关单位、专家和公众的意见。 建设单位报批的生态环境影响报告书应当附具对有关单位、专家和公众的意见采纳或者不采纳的说明。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百零二条", "text": "建设项目的生态环境影响报告书、生态环境影响报告表，由建设单位按照规定报有审批权的生态环境主管部门审批。 生态环境主管部门应当自收到生态环境影响报告书之日起六十日内，收到生态环境影响报告表之日起三十日内，分别作出审批决定并书面通知建设单位。 国家对生态环境影响登记表实行备案管理。 审批、审核建设项目生态环境影响报告书、生态环境影响报告表以及备案生态环境影响登记表，不得收取任何费用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百零三条", "text": "生态环境主管部门在收到建设项目生态环境影响报告书后，除国家规定不予公开的情形外，应当全文公开；发现建设项目未充分征求公众意见的，应当责成建设单位征求公众意见。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百零四条", "text": "国务院生态环境主管部门负责审批下列建设项目的生态环境影响报告书、生态环境影响报告表： （一）核设施等特殊性质的建设项目； （二）跨省、自治区、直辖市行政区域的建设项目； （三）由国务院审批的或者由国务院授权有关部门审批的建设项目； （四）法律、行政法规规定的其他建设项目。 前款规定以外的建设项目的生态环境影响报告书、生态环境影响报告表的审批权限，由省、自治区、直辖市人民政府规定，报国务院生态环境主管部门备案。 建设项目可能造成跨行政区域的不良生态环境影响，有关生态环境主管部门对该项目的生态环境影响评价结论有争议的，其生态环境影响报告书、生态环境影响报告表由共同的上一级生态环境主管部门审批。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百零五条", "text": "建设项目有下列情形之一的，生态环境主管部门应当对生态环境影响报告书、生态环境影响报告表作出不予批准的决定： （一）建设项目类型及其选址、布局、规模等不符合生态环境法律法规规定和相关法定规划； （二）所在区域、流域、海域生态环境质量未达到生态环境质量标准，且建设项目拟采取的措施不能满足生态环境质量改善目标管理要求； （三）建设项目采取的污染防治措施无法确保污染物排放达到排放标准，或者未采取必要措施预防和控制生态破坏； （四）改建、扩建和技术改造项目，未针对项目原有环境污染和生态破坏提出有效防治措施； （五）建设项目的生态环境影响报告书、生态环境影响报告表存在基础资料明显不实，内容存在重大缺陷、遗漏或者虚假，生态环境影响评价结论不正确或者不合理等严重质量问题。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百零六条", "text": "建设项目的生态环境影响报告书、生态环境影响报告表经批准后，建设项目的性质、规模、地点、采用的生产工艺或者防治污染、防止生态破坏的措施发生重大变动的，建设单位应当重新报批建设项目的生态环境影响报告书、生态环境影响报告表。 建设项目的生态环境影响报告书、生态环境影响报告表自批准之日起超过五年，该项目方开工建设的，其生态环境影响报告书、生态环境影响报告表应当报原审批部门重新审核；原审批部门应当自收到建设项目生态环境影响报告书、生态环境影响报告表之日起十日内，将审核意见书面通知建设单位。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百零七条", "text": "建设项目的生态环境影响报告书、生态环境影响报告表未依法经审批部门审查或者审查后未予批准的，或者未经原审批部门重新审核同意的，建设单位不得开工建设。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百零八条", "text": "建设项目建设、运行过程中，建设单位应当实施生态环境影响报告书、生态环境影响报告表及其审批部门审批意见中提出的生态环境保护对策措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百零九条", "text": "建设项目建设、运行过程中产生不符合经审批的生态环境影响报告书、生态环境影响报告表的情形的，建设单位应当组织生态环境影响的后评价，采取改进措施，并报原生态环境影响报告书、生态环境影响报告表审批部门和建设项目审批部门备案；原生态环境影响报告书、生态环境影响报告表审批部门也可以责成建设单位进行生态环境影响的后评价，采取改进措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百一十条", "text": "生态环境主管部门应当对建设项目投入生产或者使用后所产生的生态环境影响进行跟踪检查，对造成严重环境污染或者生态破坏的，应当查清原因、查明责任。 第六章 生态保护补偿"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百一十一条", "text": "国家建立健全生态保护补偿制度，通过财政纵向补偿、地区间横向补偿、市场机制补偿等机制，对按照规定或者约定开展生态环境保护的地区、单位和个人予以补偿，按照生态系统的整体性、系统性及其内在规律，建立健全政府主导、企业和社会参与、市场化运作、可持续的生态保护补偿机制，促进对生态环境的整体保护。 生态保护补偿可以采取资金补偿、对口协作、产业转移、人才培训、共建园区、购买生态产品和服务等多种方式。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百一十二条", "text": "县级以上人民政府应当构建稳定的生态保护补偿资金投入机制，依法通过多种方式拓宽生态保护补偿资金渠道。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百一十三条", "text": "国家通过财政转移支付等方式，对开展重要生态环境要素保护的地区、单位和个人，以及在依法划定的重点生态功能区、生态保护红线、自然保护地等生态功能重要区域开展生态环境保护的地区、单位和个人，予以补偿。 中央财政按照森林、草原、湿地、荒漠、海洋、水流、耕地以及法律、行政法规和国家规定的水生生物资源、陆生野生动植物资源等其他重要生态环境要素分类实施补偿。有关地方人民政府可以在中央财政分类补偿的基础上，按照中央与地方财政事权和支出责任划分原则，结合本地实际建立分类补偿制度，对开展重要生态环境要素保护的单位和个人加大补偿力度。 中央财政安排重点生态功能区转移支付，结合财力状况逐步增加转移支付规模。根据生态效益外溢性、生态功能重要性、生态环境敏感性和脆弱性等特点，在重点生态功能区转移支付中实施差异化补偿，加大对生态保护红线覆盖比例较高地区支持力度。 有关地方人民政府应当落实生态保护补偿资金，确保其用于生态保护补偿。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百一十四条", "text": "国家鼓励、指导、推动受益地区与保护地区人民政府通过协商等方式建立生态保护补偿机制，开展地区间横向生态保护补偿。根据生态环境保护的需要，上级人民政府可以组织、协调下级人民政府之间开展地区间横向生态保护补偿。 对在生态功能特别重要的跨省、自治区、直辖市和跨自治州、设区的市重点区域开展地区间横向生态保护补偿的，中央财政和省级财政可以给予引导支持。对开展地区间横向生态保护补偿取得显著成效的，国务院发展改革、财政等有关部门可以在规划、资金、项目安排等方面给予适当支持。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百一十五条", "text": "国家充分发挥市场机制在生态保护补偿中的作用，推进生态保护补偿市场化发展。 国家鼓励企业、公益组织等社会力量以及地方人民政府按照市场规则，通过购买生态产品和服务等方式开展生态保护补偿。 国家鼓励、引导社会资金建立市场化运作的生态保护补偿基金，依法有序参与生态保护补偿。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百一十六条", "text": "国家完善生态保护补偿监测支撑体系，建立健全生态保护补偿统计体系，完善生态保护补偿标准体系，为生态保护补偿工作提供技术支撑。 第七章 突发生态环境事件应对"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百一十七条", "text": "各级人民政府及其有关部门、企业事业单位和其他生产经营者，应当依法做好突发生态环境事件的预防准备、监测预警、应急处置、调查评估、事后恢复等工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百一十八条", "text": "按照社会危害程度、影响范围等因素，突发生态环境事件分为特别重大、重大、较大和一般四级。突发生态环境事件的分级标准由国务院生态环境主管部门会同有关部门制定，报国务院批准后公布实施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百一十九条", "text": "国家建立健全分级负责、属地为主、部门协同的突发生态环境事件应对责任体系，严密防控生态环境风险、保护生态环境敏感目标，及时妥善科学处置各类突发生态环境事件。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百二十条", "text": "生态环境、应急管理等有关部门应当密切配合，加强信息共享、协调联动，共同做好突发生态环境事件应对工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百二十一条", "text": "企业事业单位和其他生产经营者应当依法完善突发生态环境事件风险防控措施，开展隐患排查，及时消除隐患。 企业事业单位和其他生产经营者应当按照国家规定储备必要的生态环境应急物资和装备，定期开展应急演练，做好应急准备。在发生或者可能发生突发生态环境事件时，企业事业单位和其他生产经营者应当立即采取措施处理，切断或者控制污染源，防止危害扩大，及时通报可能受到危害者，并向生态环境、应急管理等有关部门报告，接受调查处理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百二十二条", "text": "各级人民政府及其有关部门、企业事业单位和其他生产经营者，在自然灾害、事故灾难、公共卫生事件应急处置过程中，应当采取必要措施，避免或者减少对生态环境造成的危害。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百二十三条", "text": "国务院组织制定国家突发生态环境事件应急预案并组织实施。县级以上地方人民政府应当制定本行政区域的突发生态环境事件应急预案并按照规定备案。 企业事业单位和其他生产经营者应当按照国家规定制定突发生态环境事件应急预案，报生态环境等有关部门备案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百二十四条", "text": "县级以上人民政府应当建立健全突发生态环境事件监测预警机制，组织制定预警方案；生态环境受到损害，可能影响公众健康和生态安全时，依法及时发布预警信息，启动应急措施。 生态环境主管部门应当加强对可能导致突发生态环境事件的风险信息的收集、分析和研判，经研判可能发生突发生态环境事件时，及时向本级人民政府提出预警信息发布建议。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百二十五条", "text": "突发生态环境事件涉及或者可能涉及相邻行政区域的，事发地人民政府及其生态环境主管部门应当及时通报相邻行政区域同级人民政府及其生态环境主管部门。 接到通报的人民政府应当按照国家规定，及时启动应急响应，采取应急联动措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百二十六条", "text": "突发生态环境事件应急处置工作结束后，有关人民政府应当立即组织评估事件造成的生态环境影响和损失，并及时公布评估结果。 评估结果应当作为突发生态环境事件调查处理、损害赔偿、生态修复等的重要依据。 第八章 保障措施"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百二十七条", "text": "国家采取有利于保护生态环境的财政、税收、价格、采购、金融、产业等政策和措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百二十八条", "text": "国务院和县级以上地方人民政府应当按照事权和支出责任划分原则，将生态环境保护工作所需经费纳入本级政府预算，加大生态环境保护的财政投入，优化生态文明建设领域财政资源配置，确保投入规模同建设任务相匹配，提高财政资金的使用效益。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百二十九条", "text": "国家对参与生态环境保护的单位和个人，依法给予税收优惠。 国家鼓励并提倡社会各界为生态环境保护捐赠财产，并依法给予税收优惠。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百三十条", "text": "国家完善自然资源、污水垃圾处理、用水用能等领域价格形成机制，对资源高消耗、高污染行业依法实行差别化的价格政策。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百三十一条", "text": "国家机关和其他使用财政性资金的公共机构应当优先采购和使用节能、节水、节地、节材、节矿等有利于保护生态环境的产品、设备、设施和服务。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百三十二条", "text": "国家强化对生态环境保护的金融支持，持续推动绿色信贷、绿色债券、绿色保险、绿色信托等绿色金融产品和服务规范健康发展。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百三十三条", "text": "国家鼓励、支持生态环境保护技术装备、资源节约集约利用和生态环境服务等生态环境保护产业的发展。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百三十四条", "text": "国家推动建立资源环境要素市场交易制度，推进资源环境要素市场化配置，充分发挥市场机制作用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百三十五条", "text": "国家推广先进适用技术、工艺、设备，减少资源消耗和污染物、温室气体的产生、排放，促进废弃物综合利用和污染物无害化处理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百三十六条", "text": "企业事业单位和其他生产经营者，为保护生态环境，依照有关规定转产、搬迁、关闭的，人民政府应当予以支持。 第九章 信息公开与公众参与"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百三十七条", "text": "公民、法人和其他组织依法享有获取生态环境信息、参与和监督生态环境保护的权利。 负有生态环境保护监督管理职责的部门应当依法公开生态环境信息、完善公众参与程序，为公民、法人和其他组织参与和监督生态环境保护提供便利。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百三十八条", "text": "国务院生态环境主管部门统一发布国家生态环境质量、重点污染源监测信息及其他重大生态环境信息。省级以上人民政府生态环境主管部门定期发布生态环境状况公报。 负有生态环境保护监督管理职责的部门应当依法公开生态环境质量、生态环境监测、突发生态环境事件以及生态环境行政许可、行政处罚等信息。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百三十九条", "text": "负有生态环境保护监督管理职责的部门应当加强协调沟通，保证公开的生态环境信息准确一致。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百四十条", "text": "国家鼓励企业事业单位和其他生产经营者自愿公开相关生态环境信息。 实行排污许可重点管理和其他法定的应当披露生态环境信息的企业事业单位和其他生产经营者，应当依法及时、真实、准确、完整披露污染物排放信息、温室气体排放信息等生态环境信息。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百四十一条", "text": "国家鼓励、引导公民、法人和其他组织按照依法、有序、自愿、便利的原则，参与生态环境保护。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百四十二条", "text": "国家鼓励、引导公民、法人和其他组织使用有利于保护生态环境的产品、技术和工艺，减少废弃物的产生，促进废弃物循环利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百四十三条", "text": "编制生态环境领域的规划、制定生态环境领域的标准、开展生态环境影响评价等工作，应当依法采取举行听证会、公开征求意见等方式，保障公众参与生态环境保护的权利。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百四十四条", "text": "国家鼓励公民、法人和其他组织对生态环境保护公共事务进行监督。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百四十五条", "text": "负有生态环境保护监督管理职责的部门应当公布举报电话、电子邮箱等高效便捷的举报渠道，方便公众举报。 公民、法人和其他组织发现任何单位和个人有污染环境、破坏生态等行为的，有权向负有生态环境保护监督管理职责的部门举报。 公民、法人和其他组织发现地方各级人民政府或者负有生态环境保护监督管理职责的部门、机构不依法履行职责的，有权向其上级机关或者监察机关举报。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百四十六条", "text": "接受举报的机关应当及时处理并对举报人的相关信息予以保密；对实名举报的，应当反馈处理结果等情况。 举报人举报所在单位的，该单位不得以解除、变更劳动合同、聘用合同，或者以其他方式对举报人进行打击报复。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百四十七条", "text": "国家鼓励社会组织、志愿者依法从事生态环境保护公益活动。 污染环境、破坏生态等损害社会公共利益的，符合下列条件的社会组织可以依法向人民法院提起民事公益诉讼： （一）依法在设区的市级以上人民政府民政部门登记； （二）专门从事生态环境保护公益活动连续五年以上且无违法记录。 符合前款规定的社会组织向人民法院提起民事公益诉讼，人民法院应当依法受理。 提起诉讼的社会组织不得通过诉讼牟取经济利益。 第二编 污染防治 第一分编 通 则 第一章 一般规定"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百四十八条", "text": "本编适用于环境污染的防治。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百四十九条", "text": "污染防治坚持精准治污、科学治污、依法治污的方针，坚持统筹规划、源头防控、分类管理、社会共治，强化多污染物控制协同、区域治理协同，加强全过程监督管理，实现减污降碳协同增效，改善生态环境质量，保障公众健康。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百五十条", "text": "排放污染物的单位和个人，应当采取有效措施，防治在生产、生活和其他活动中产生的大气污染、水污染、海洋污染、土壤污染、固体废物污染、噪声污染、放射性污染，以及化学物质污染、电磁辐射污染、光污染等环境污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百五十一条", "text": "排放污染物，应当符合污染物排放标准、重点污染物排放总量控制指标、排污许可管理和有关法律、法规、规章的要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百五十二条", "text": "排放污染物的企业事业单位，应当建立污染防治责任制度，明确单位负责人和相关人员的责任。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百五十三条", "text": "国务院生态环境主管部门制定国家污染物排放标准。 省、自治区、直辖市人民政府对国家污染物排放标准中未作规定的项目，可以制定地方污染物排放标准；对国家污染物排放标准中已作规定的项目，可以制定严于国家污染物排放标准的地方污染物排放标准。地方污染物排放标准应当报国务院生态环境主管部门备案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百五十四条", "text": "制定污染物排放标准，应当以生态环境质量标准和经济、技术条件为根据，反映污染物排放特征、可接受生态环境风险，科学合理确定污染物排放控制要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百五十五条", "text": "国家实行重点污染物排放总量控制制度。 重点污染物排放总量控制指标，由国务院生态环境主管部门在征求有关部门和各省、自治区、直辖市人民政府意见后，会同国务院发展改革部门报国务院批准并下达实施。省、自治区、直辖市人民政府应当分解落实国务院下达的总量控制指标，控制或者削减本行政区域的重点污染物排放总量。 确定和分解总量控制指标的具体办法，由国务院生态环境主管部门会同有关部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百五十六条", "text": "省、自治区、直辖市人民政府可以根据本行政区域的生态环境质量状况和污染防治工作的需要，对国家确定的重点污染物之外的其他重点污染物排放实行总量控制。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百五十七条", "text": "企业事业单位应当遵守分解落实到本单位的重点污染物排放总量控制指标。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百五十八条", "text": "对超过重点污染物排放总量控制指标或者未完成生态环境质量目标的地区，省级以上人民政府生态环境主管部门应当暂停审批该地区新增重点污染物排放总量的建设项目的生态环境影响报告书、生态环境影响报告表。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百五十九条", "text": "省级以上人民政府生态环境主管部门会同有关部门对环境污染问题突出、防治工作不力、群众反映强烈的地区，约谈县级以上地方人民政府及其有关部门主要负责人，要求其采取有效措施及时整改。约谈整改情况应当向社会公开。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百六十条", "text": "国务院生态环境主管部门依法组织实施排放源统计调查，建立健全排放源统计核算方法体系、数据质量控制制度。国家定期组织实施全国污染源普查。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百六十一条", "text": "国务院生态环境主管部门会同有关部门，建立健全污染损害评估制度。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百六十二条", "text": "建设项目中的污染防治设施，应当与主体工程同时设计、同时施工、同时投产使用。污染防治设施应当符合经批准的生态环境影响报告书、生态环境影响报告表的要求，不得擅自拆除或者闲置。 建设项目在投入生产或者使用前，建设单位应当按照国家规定，对配套建设的污染防治设施进行验收。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百六十三条", "text": "企业事业单位和其他生产经营者排放污染物的，应当依照法律法规和国务院生态环境主管部门的规定设置、使用污染物排放口（以下简称排污口）。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百六十四条", "text": "禁止通过暗管、渗井、渗坑、灌注、裂隙、溶洞、篡改或者伪造监测数据、以逃避现场检查为目的的临时停产、非紧急情况下开启应急排放通道、不正常运行污染防治设施等逃避监管的方式排放污染物。 禁止向江河湖泊、运河、渠道、水库及其最高水位线以下的滩地和岸坡以及法律法规规定的其他地点倾倒、堆放、贮存固体废物和其他污染物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百六十五条", "text": "各级人民政府应当统筹规划、建设城乡污水处理设施及配套管网，固体废物的收集、运输和处置设施、场所，以及其他污染防治设施，并保障其正常运行，提高城乡污染防治设施建设水平。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百六十六条", "text": "国务院生态环境主管部门定期公布污染防治技术、工艺和设备导向目录。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百六十七条", "text": "国家逐步推行重点大气污染物、水污染物等排污权交易，建立健全针对重点污染物排放总量控制指标的排污权交易制度，加强对排污权交易全过程监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百六十八条", "text": "直接向环境排放应税污染物的企业事业单位和其他生产经营者，应当依照法律规定缴纳环境保护税。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百六十九条", "text": "国家鼓励投保环境污染责任保险。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百七十条", "text": "各级人民政府应当在财政预算中安排资金，支持农村饮用水水源地保护、生活污水治理和生活垃圾等废弃物处理、农业面源污染防治、畜禽养殖和屠宰污染防治、水产养殖污染防治、土壤污染防治和农村工矿污染治理等工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百七十一条", "text": "各级人民政府及其农业农村等有关部门和机构应当指导农业生产经营者科学种植和养殖，科学合理安全使用农药、兽药、饲料和饲料添加剂、肥料等农业投入品，科学处置农用薄膜、农作物秸秆、农业投入品包装废弃物等农业废弃物，加强对农业生产经营活动排放污染物的控制，防止农业面源污染。 禁止将不符合农用标准和生态环境保护标准的固体废物、废水施入农田。施用农药、肥料等农业投入品及进行灌溉，应当采取有效措施，防止重金属和其他有毒有害物质污染环境。 畜禽养殖场、定点屠宰企业等的选址、建设和管理应当符合法律法规规定。畜禽养殖场应当提高精准饲喂水平，加强畜禽粪污综合管理。从事畜禽养殖和屠宰的单位和个人应当采取有效措施，及时对畜禽粪污、尸体等废弃物进行收集、贮存、清运、无害化处理和资源化利用，防止污染环境。 县级人民政府负责组织农村生活废弃物的处置工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百七十二条", "text": "国家对农业面源污染突出区域强化系统治理，提升农业面源污染防治成效。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百七十三条", "text": "国务院生态环境主管部门会同有关部门确定重金属污染防治重点地区和重点行业，报国务院批准。重点地区所在设区的市级以上地方人民政府，应当按照国家规定组织编制并实施重金属污染防治方案。重点行业企业应当定期开展隐患排查整治，采取有效措施防治重金属污染。 第二章 排污许可管理"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百七十四条", "text": "国家建立健全以排污许可制为核心的固定污染源监督管理制度，具体办法由国务院制定。 实行排污许可管理的企业事业单位和其他生产经营者应当按照规定取得排污许可证，未取得排污许可证的不得排放污染物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百七十五条", "text": "根据污染物产生量、排放量、对生态环境的影响程度等因素，对实行排污许可管理的企业事业单位和其他生产经营者实行排污许可分类管理： （一）污染物产生量、排放量或者对生态环境的影响程度较大的，实行排污许可重点管理； （二）污染物产生量、排放量和对生态环境的影响程度都较小的，实行排污许可简化管理。 实行排污许可管理的企业事业单位和其他生产经营者范围、实施步骤和管理类别名录，由国务院生态环境主管部门拟订并报国务院批准后公布实施。制定实行排污许可管理的企业事业单位和其他生产经营者范围、实施步骤和管理类别名录，应当征求有关部门、行业协会、企业事业单位和公众等方面的意见。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百七十六条", "text": "下列企业事业单位和其他生产经营者应当取得排污许可证： （一）排放工业废气或者有毒有害大气污染物的企业事业单位和集中供热设施的燃煤热源生产运营单位； （二）直接或者间接向水体排放工业废水、医疗污水的企业事业单位和其他生产经营者； （三）城镇污水集中处理设施的运营单位； （四）直接向海洋排放工业废水、医疗污水的海岸工程和海洋工程单位； （五）产生工业固体废物的单位； （六）排放工业噪声的企业事业单位和其他生产经营者； （七）排放放射性废液或者产生放射性固体废物的伴生放射性矿开发利用单位； （八）运行一类电磁辐射设施的企业事业单位和依法实行排污许可管理的运行二类电磁辐射设施的企业事业单位； （九）其他依照法律、行政法规规定实行排污许可管理的企业事业单位和其他生产经营者。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百七十七条", "text": "设区的市级以上人民政府生态环境主管部门应当加强排污许可的监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百七十八条", "text": "企业事业单位和其他生产经营者应当向其生产经营场所所在地设区的市级以上地方人民政府生态环境主管部门申请取得排污许可证。 海洋工程需要取得排污许可证的，应当向国务院生态环境主管部门或者国务院生态环境主管部门海域派出机构申请。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百七十九条", "text": "排污许可证是对实行排污许可管理的企业事业单位和其他生产经营者进行生态环境监督管理的主要依据。 实行排污许可管理的企业事业单位和其他生产经营者应当遵守排污许可证的要求，按照规定运行和维护污染防治设施，建立生态环境管理制度，严格控制污染物排放。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百八十条", "text": "对具备下列条件的实行排污许可管理的企业事业单位和其他生产经营者，颁发排污许可证： （一）依法取得生态环境影响报告书、生态环境影响报告表批准文件，或者已经办理生态环境影响登记表备案手续； （二）污染物排放符合污染物排放标准等要求，重点污染物排放符合排污许可证申请与核发技术规范和生态环境影响报告书、生态环境影响报告表批准文件以及重点污染物排放总量控制指标要求，实行排污许可管理的企业事业单位和其他生产经营者生产经营场所位于未达到国家生态环境质量标准区域、流域、海域的，还应当符合有关地方人民政府关于改善生态环境质量的特别要求； （三）采用污染防治设施可以达到许可排放浓度等要求或者符合污染防治可行技术； （四）自行监测方案的监测点位、指标、频次等符合国家自行监测规范； （五）法律、行政法规规定的其他条件。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百八十一条", "text": "排污许可证应当记载下列信息： （一）排污口位置和数量、污染物排放方式和排放去向等； （二）污染物排放种类、许可排放浓度、许可排放量，或者许可排放限值等； （三）产生和排放污染物环节、污染防治设施及其运行和维护要求、排污口规范化建设要求等； （四）特殊时段禁止或者限制污染物排放的要求； （五）法律、行政法规规定的其他信息。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百八十二条", "text": "排污许可证有效期为五年。在排污许可证有效期内，实行排污许可管理的企业事业单位和其他生产经营者有下列情形之一的，应当重新取得排污许可证： （一）新建、改建、扩建排放污染物的项目； （二）生产经营场所、排污口位置或者污染物排放方式、排放去向发生变化； （三）排污口数量或者污染物排放种类、排放浓度、排放量增加； （四）法律、行政法规规定的其他情形。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百八十三条", "text": "实行排污许可管理的企业事业单位和其他生产经营者应当按照排污许可证的要求和有关标准规范，依法开展自行监测，建立管理台账，并保存原始监测记录和管理台账。原始监测记录和管理台账保存期限不得少于五年。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百八十四条", "text": "实行排污许可重点管理的企业事业单位和其他生产经营者，应当按照国家规定安装、使用、维护污染物排放自动监测设备，开展监控、自动监测，并与生态环境主管部门的监控设备联网，保证自动监测设备正常运行，保存原始监测记录。监测的具体办法由国务院生态环境主管部门制定。 实行排污许可重点管理的企业事业单位和其他生产经营者发现污染物排放自动监测设备传输数据异常，应当及时报告生态环境主管部门，并进行检查、修复。生态环境主管部门发现实行排污许可重点管理的企业事业单位和其他生产经营者的污染物排放自动监测设备传输数据异常，应当及时进行调查。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百八十五条", "text": "实行排污许可管理的企业事业单位和其他生产经营者应当按照规定向社会公开污染物排放种类、排放浓度和排放量，以及污染防治设施的建设运行情况、自行监测数据等污染物排放信息，接受社会监督。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百八十六条", "text": "污染物产生量、排放量和对生态环境的影响程度都很小的企业事业单位和其他生产经营者，应当填报排污登记表，不实行排污许可管理。排污登记表有效期为五年。 需要填报排污登记表的企业事业单位和其他生产经营者范围名录，由国务院生态环境主管部门制定并公布。制定需要填报排污登记表的企业事业单位和其他生产经营者范围名录，应当征求有关部门、行业协会、企业事业单位和公众等方面的意见。 第二分编 大气污染防治 第三章 一般规定"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百八十七条", "text": "本分编适用于大气污染的防治。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百八十八条", "text": "本法所称大气污染，是指大气因某种物质的介入，而导致其化学、物理等方面特性的改变，危害公众健康或者破坏生态环境，造成大气环境质量恶化的现象。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百八十九条", "text": "防治大气污染，应当以改善大气环境质量为目标，转变经济发展方式，优化产业结构和布局，调整能源结构、交通运输结构。 防治大气污染，应当加强对燃煤、工业、机动车船、非道路移动机械、扬尘、农业等大气污染的综合防治，推行区域大气污染联合防治，对颗粒物、二氧化硫、氮氧化物、挥发性有机物、氨等大气污染物和温室气体实施协同控制。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百九十条", "text": "设区的市级以上地方人民政府编制规划，采取有效措施，控制或者逐步削减大气污染物的排放量，使大气环境质量达到规定标准并逐步改善。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百九十一条", "text": "国务院生态环境主管部门对全国大气污染防治工作实施统一监督管理。地方人民政府生态环境主管部门对本行政区域大气污染防治工作实施统一监督管理。 县级以上人民政府其他有关部门在各自职责范围内对大气污染防治工作实施监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百九十二条", "text": "未达到国家大气环境质量标准的地区所在直辖市和设区的市、县级人民政府，应当及时编制大气环境质量限期达标规划，采取有效措施，按照省级以上人民政府规定的期限达到大气环境质量标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百九十三条", "text": "直辖市和设区的市级人民政府编制的大气环境质量限期达标规划应当报国务院生态环境主管部门备案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百九十四条", "text": "大气环境质量限期达标规划应当根据大气污染防治的要求和经济、技术条件适时进行评估、修订。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百九十五条", "text": "制定燃煤、石油焦、生物质燃料、涂料等含挥发性有机物的产品、烟花爆竹以及锅炉等产品的质量标准，应当明确大气污染防治要求。 制定燃油质量标准，应当符合国家大气污染物控制要求，并与国家机动车船、非道路移动机械大气污染物排放标准相互衔接，同步实施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百九十六条", "text": "国务院生态环境主管部门组织开展大气环境质量和大气污染源监测，组织建设与管理全国大气环境质量和大气污染源监测网络。 设区的市级以上地方人民政府生态环境主管部门负责组织建设与管理本行政区域的大气环境质量和大气污染源监测网络，开展大气环境质量和大气污染源监测。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百九十七条", "text": "企业事业单位和其他生产经营者应当按照国家规定对其排放的工业废气和有毒有害大气污染物进行监测，并保存原始监测记录。监测的具体办法由国务院生态环境主管部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百九十八条", "text": "生态环境主管部门应当及时对突发环境污染事件产生的大气污染物进行监测，并向社会公开监测信息。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第一百九十九条", "text": "国家鼓励、支持开展对大气污染来源及其变化趋势的分析，发挥科学技术在大气污染防治中的支撑作用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百条", "text": "海洋工程大气污染的防治不适用本分编。 第四章 大气污染防治措施 第一节 燃煤和其他能源大气污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百零一条", "text": "国务院有关部门和地方各级人民政府应当优化煤炭使用方式，减少煤炭生产、贮存、运输、使用、转化过程中的大气污染物排放。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百零二条", "text": "国家推行煤炭洗选加工，降低煤炭的硫分和灰分，限制高硫分、高灰分煤炭的开采。新建煤矿应当同步建设配套的煤炭洗选设施，使煤炭的硫分、灰分含量达到规定标准；已建成的煤矿除所采煤炭属于低硫分、低灰分或者根据已达标排放的燃煤电厂要求不需要洗选的外，应当限期建成配套的煤炭洗选设施。 禁止开采含放射性和砷等有毒有害物质超过规定标准的煤炭。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百零三条", "text": "从事煤层气开采利用的，煤层气排放应当符合相关标准规范。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百零四条", "text": "禁止进口、销售或者燃用不符合质量标准的煤炭，鼓励燃用优质煤炭。 单位存放煤炭、煤矸石、煤渣、煤灰等物料，应当采取防燃措施，防止大气污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百零五条", "text": "地方各级人民政府应当采取有效措施，加强散煤的管理，禁止销售不符合散煤质量标准的煤炭，鼓励、支持采取清洁低碳能源、集中供热替代等措施防治燃用散煤造成大气污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百零六条", "text": "石油炼制企业应当按照燃油质量标准生产燃油。 禁止进口、销售或者使用不符合质量标准的石油焦。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百零七条", "text": "设区的市级以上地方人民政府可以划定并公布高污染燃料禁燃区，并根据大气环境质量改善要求，逐步扩大高污染燃料禁燃区范围。高污染燃料的目录由国务院生态环境主管部门确定。 在禁燃区内，禁止销售、燃用高污染燃料；禁止新建、扩建燃用高污染燃料的设施，已建成的，应当在设区的市级以上地方人民政府规定的期限内改用天然气、页岩气、液化石油气、电或者其他清洁低碳能源。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百零八条", "text": "城市建设应当统筹规划，在燃煤供热地区，推进热电联产和集中供热。在集中供热管网覆盖地区，禁止新建、扩建分散燃煤供热锅炉；已建成的不能达标排放的燃煤供热锅炉，应当在设区的市级以上地方人民政府规定的期限内拆除。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百零九条", "text": "县级以上人民政府市场监督管理部门会同生态环境主管部门对锅炉生产、进口、销售、使用环节执行大气污染防治标准或者要求的情况进行监督检查；不符合大气污染防治标准或者要求的，不得生产、进口、销售或者使用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百一十条", "text": "燃煤电厂和其他燃煤单位应当采用清洁生产工艺，配套建设除尘、脱硫、脱硝等装置，或者采取技术改造等其他控制大气污染物排放的措施。 国家鼓励燃煤单位采用先进的除尘、脱硫、脱硝、脱汞等大气污染物协同控制的技术和装置，减少大气污染物的排放。 第二节 工业大气污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百一十一条", "text": "钢铁、建材、有色金属、石油、化工等企业生产过程中排放粉尘、硫化物和氮氧化物的，应当采用清洁生产工艺，配套建设除尘、脱硫、脱硝等装置，或者采取技术改造等其他控制大气污染物排放的措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百一十二条", "text": "国家鼓励、支持钢铁、水泥、焦化等重点行业和燃煤锅炉采用超低排放等技术，减少大气污染物的排放。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百一十三条", "text": "国务院有关部门在各自职责范围内制定含挥发性有机物的原辅材料和产品的挥发性有机物含量限值标准、低挥发性有机物含量的原辅材料和产品标准。 生产、进口、销售、使用含挥发性有机物的原辅材料和产品的，其挥发性有机物含量应当符合质量标准或者要求。 国家鼓励生产、进口、销售、使用低毒、低挥发性有机物含量的原辅材料和产品，工业涂装企业等应当按照规定使用低挥发性有机物含量的原辅材料和产品。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百一十四条", "text": "生产、使用含挥发性有机物的原辅材料和产品，应当按照国家规定，在密闭空间、设备中进行并安装、使用污染防治设施，或者采取有效措施减少废气排放。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百一十五条", "text": "国家建立健全产品的低挥发性有机物含量标识制度，低挥发性有机物含量的产品的生产者应当按照规定标识。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百一十六条", "text": "石油、化工及其他生产、使用有机溶剂的企业，应当采取有效措施对管道、设备进行日常维护、维修，减少物料泄漏，对泄漏的物料应当及时收集处理。 储油库、加油站、原油成品油码头、原油成品油运输船舶和油罐车、铁路罐车等，应当按照国家规定安装油气回收装置并保持正常使用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百一十七条", "text": "钢铁、建材、有色金属、石油、化工、制药、矿产开采企业和其他工业生产企业，应当加强精细化管理，采取集中收集处理等措施，严格控制粉尘和气态污染物的排放。 工业生产企业应当采取密闭、围挡、遮盖、清扫、洒水等措施，减少内部物料的堆存、传输、装卸等环节产生的粉尘和气态污染物的排放。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百一十八条", "text": "工业生产、垃圾填埋和其他活动产生的可燃性气体应当回收利用，不具备回收利用条件的，应当进行污染防治处理。 可燃性气体回收利用装置不能正常作业的，应当及时修复或者更新。在回收利用装置不能正常作业期间确需排放可燃性气体的，应当将排放的可燃性气体充分燃烧或者采取其他控制大气污染物排放的措施，并向当地生态环境主管部门报告，按照要求限期修复或者更新。 第三节 机动车船等大气污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百一十九条", "text": "国家倡导绿色出行，根据城市规划合理控制燃油机动车保有量，大力发展城市公共交通，提高公共交通出行比例。 国家采取财政、税收、政府采购等措施推广应用节能环保型和新能源机动车船、非道路移动机械，限制高油耗、高排放机动车船、非道路移动机械的发展，减少化石能源的消耗。 省、自治区、直辖市人民政府可以在条件具备的地区，提前执行国家机动车大气污染物排放标准中相应阶段排放限值，并报国务院生态环境主管部门备案。 县级以上地方人民政府应当加强并改善城市交通管理，优化道路设置，保障人行道和非机动车道的连续、畅通。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百二十条", "text": "重型货车使用较多的重点用车单位应当按照国家规定，将运输及装卸环节排放管理纳入单位污染防治责任制度，加强重型货车大气污染防治。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百二十一条", "text": "机动车船、非道路移动机械及其发动机不得超过标准排放大气污染物。 禁止生产、进口或者销售不符合大气污染物排放标准的机动车船、非道路移动机械及其发动机。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百二十二条", "text": "机动车、非道路移动机械及其发动机生产企业应当对新生产的机动车、非道路移动机械及其发动机进行排放检验。经检验合格的，方可出厂销售。检验信息应当向社会公开，并报生态环境主管部门备案。 省级以上人民政府生态环境主管部门可以通过现场检查、抽样检测等方式，加强对新生产、进口、销售机动车、非道路移动机械及其发动机大气污染物排放状况、排放控制系统运行情况的监督检查。工业和信息化、交通运输、市场监督管理、海关等有关部门予以配合。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百二十三条", "text": "在用机动车应当按照规定，由机动车排放检验机构定期对其进行排放检验。经检验合格的，方可上道路行驶。未经检验合格的，公安机关交通管理部门不得核发安全技术检验合格标志。 生态环境主管部门可以在机动车集中停放地、维修地和重型汽车使用地对在用机动车的大气污染物排放状况、排放控制系统运行情况进行监督抽测；在不影响正常通行的情况下，可以通过非接触式道路监测等技术手段对在道路上行驶的机动车的大气污染物排放状况、排放控制系统运行情况进行监督抽测，公安机关交通管理部门予以配合。 本法所称排放控制系统，是指装载于机动车船、非道路移动机械等的污染控制、排放诊断、远程排放管理终端等系统。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百二十四条", "text": "生态环境主管部门会同交通运输、住房城乡建设、农业农村、水行政等有关部门对在用非道路移动机械的大气污染物排放状况、排放控制系统运行情况进行监督检查；排放不合格的，不得使用。 海事管理机构、渔业渔政主管部门应当在各自职责范围内对船舶的大气污染物排放状况、排放控制系统运行情况进行监督检查；排放不合格的，不得使用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百二十五条", "text": "机动车、非道路移动机械排放检验机构应当依法通过计量认证，使用经依法检定合格的机动车、非道路移动机械排放检验设备，按照国务院生态环境主管部门制定的规范，对机动车、非道路移动机械进行排放检验，并与生态环境主管部门联网，实现检验数据实时共享。机动车、非道路移动机械排放检验机构及其负责人应当对检验数据的真实性、准确性和完整性负责。 生态环境主管部门、认证认可监督管理部门应当在各自职责范围内对机动车、非道路移动机械排放检验机构的排放检验情况进行监督检查。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百二十六条", "text": "机动车、非道路移动机械的生产、进口企业应当向社会公开其生产、进口机动车车型、非道路移动机械机型的排放检验信息、污染控制技术信息和有关维修技术信息。 机动车、非道路移动机械的维修单位应当按照防治大气污染的要求和国家有关技术规范对在用机动车、非道路移动机械进行维修，使其符合排放标准。交通运输、生态环境等有关部门应当在各自职责范围内依法加强监督管理。 机动车船、非道路移动机械所有人不得以临时更换、篡改、屏蔽、伪造排放控制系统等弄虚作假的方式通过机动车船、非道路移动机械排放检验。机动车船、非道路移动机械维修单位不得提供该类维修服务。禁止破坏、拆除、篡改、屏蔽、伪造机动车船、非道路移动机械排放控制系统。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百二十七条", "text": "国家建立健全机动车和非道路移动机械环保召回制度。 生产、进口企业获知机动车、非道路移动机械不符合大气污染物排放标准或者存在不合理排放大气污染物情形，属于设计、生产缺陷的，应当召回；未召回的，由国务院市场监督管理部门会同国务院生态环境主管部门责令其召回。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百二十八条", "text": "在用重型汽车、船舶、非道路移动机械等未按照规定安装排放控制系统或者排放控制系统不符合要求，不能达标排放的，应当加装或者更换符合要求的排放控制系统，或者采取其他有效措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百二十九条", "text": "在用机动车、非道路移动机械等排放大气污染物超过标准的，应当进行维修；经维修或者采用污染控制技术后，大气污染物排放仍不符合国家排放标准的，应当强制报废。其所有人应当将机动车、非道路移动机械等交售给报废回收拆解企业，由报废回收拆解企业按照国家规定进行登记、拆解、销毁等处理。 国家鼓励、支持高排放机动车船、非道路移动机械等提前报废。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百三十条", "text": "县级以上地方人民政府可以根据大气环境质量状况，划定并公布禁止使用高排放非道路移动机械的区域。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百三十一条", "text": "船舶检验机构对船舶发动机及有关设备进行排放检验。经检验符合国家排放标准的，船舶方可运营。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百三十二条", "text": "非道路移动机械检验机构对在用非道路移动机械进行排放检验。经检验符合国家排放标准的，方可运营。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百三十三条", "text": "禁止生产、进口或者销售用于篡改、屏蔽、伪造机动车船、非道路移动机械及其发动机排放检验数据的装置和为虚假排放检验提供条件的检验设备。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百三十四条", "text": "内河和江海直达船舶应当使用符合标准的燃油。远洋船舶靠港后应当使用符合大气污染物控制要求的燃油。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百三十五条", "text": "新建码头应当按照规定规划、设计和建设岸基供电设施；已建成的码头应当按照规定逐步实施岸基供电设施改造。具备岸电使用条件的船舶靠港应当按照国家规定使用岸电，但是使用清洁低碳能源的除外。具备岸电供应能力的港口经营人、岸电供电企业应当按照国家规定为具备岸电使用条件的船舶提供岸电。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百三十六条", "text": "禁止生产、进口或者销售不符合标准的机动车船、非道路移动机械用燃料和氮氧化物还原剂；禁止向机动车、非道路移动机械、内河和江海直达船舶销售非机动车船用燃料；禁止机动车、非道路移动机械、内河和江海直达船舶使用非机动车船用燃料。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百三十七条", "text": "发动机油、氮氧化物还原剂、燃料和润滑油添加剂及其他添加剂的有毒有害物质含量和其他大气污染防治指标，应当符合相关标准的要求，不得损害机动车船、非道路移动机械排放控制系统效果和耐久性，不得增加新的大气污染物排放。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百三十八条", "text": "国家积极推进民用航空器的大气污染防治，鼓励在设计、生产、使用过程中采取有效措施减少大气污染物排放。 民用航空器应当符合国务院民用航空主管部门规定的适航标准中的有关发动机排出物要求。 在用铁路内燃机车大气污染物排放应当符合国家排放标准。 第四节 扬尘大气污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百三十九条", "text": "地方各级人民政府应当加强对建设施工和运输的管理，保持道路清洁，控制料堆和渣土堆放，扩大绿地、水面、湿地和地面铺装面积，防治扬尘污染。 住房城乡建设、市容环境卫生、交通运输、自然资源等有关部门，应当根据本级人民政府确定的职责，做好扬尘污染防治工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百四十条", "text": "建设单位应当将扬尘污染防治费用列入工程造价，在施工合同中明确施工单位的扬尘污染防治责任。施工单位应当制定具体的施工扬尘污染防治实施方案。 从事房屋建筑、市政基础设施建设、河道整治以及建筑物拆除等施工单位，应当报负有扬尘污染防治监督管理职责的部门备案。 施工单位应当在施工工地设置硬质围挡，并采取覆盖、分段作业、择时施工、洒水抑尘、冲洗地面和车辆等有效防尘降尘措施。工程渣土等建筑垃圾、建筑土方应当及时清运；在场地内堆存的，应当采用密闭式防尘网遮盖。工程渣土等建筑垃圾应当进行资源化处理。 施工单位应当在施工工地公示扬尘污染防治措施、负责人、监督管理部门等信息。 暂时不能开工的建设用地，建设单位应当对裸露地面进行覆盖；超过三个月的，应当进行绿化、铺装或者遮盖。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百四十一条", "text": "运输煤炭、垃圾、渣土、砂石、土方、灰浆等散装、流体物料的车辆和船舶应当采取密闭或者其他有效措施防止物料遗撒造成扬尘污染，并按照规定路线行驶。 装卸物料应当采取密闭或者喷淋等方式防治扬尘污染。 县级以上地方人民政府应当加强道路、广场、停车场和其他公共场所的清扫保洁管理，推行清洁动力机械化清扫和其他科学合理的低尘作业方式，防治扬尘污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百四十二条", "text": "市政河道和河道沿线、公共用地的裸露地面及其他城镇裸露地面，有关部门应当按照规划组织实施绿化或者透水铺装。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百四十三条", "text": "贮存煤炭、煤矸石、煤渣、煤灰、水泥、石灰、石膏、砂土、铁矿石等易产生扬尘的物料应当密闭；不能密闭的，应当设置不低于堆放物高度的严密围挡，并采取有效覆盖措施防治扬尘污染。 码头、矿山、填埋场和消纳场应当实施分区作业，并采取有效措施防治扬尘污染。 第五节 农业和其他大气污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百四十四条", "text": "禁止在人口集中地区对树木、花草喷洒剧毒、高毒农药。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百四十五条", "text": "各级人民政府及其农业农村等有关部门应当鼓励、支持采用先进适用技术，对秸秆、落叶等进行肥料化、饲料化、能源化、工业原料化、食用菌基料化等综合利用，加大对秸秆还田、收集一体化等农业机械的财政补贴力度。 县级人民政府应当组织建立健全秸秆收集、贮存、运输、处置和综合利用服务体系，采用财政补贴等措施支持农村集体经济组织、农民专业合作社、企业等开展秸秆收集、贮存、运输、处置和综合利用服务。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百四十六条", "text": "地方各级人民政府应当科学精准加强秸秆、落叶等焚烧的组织、指导和管理。禁止在人口集中地区、机场周围、交通干线附近以及省级以上人民政府划定的其他区域和规定的时段露天焚烧秸秆、落叶等产生烟尘污染的物质。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百四十七条", "text": "国务院生态环境主管部门会同国务院卫生健康主管部门，根据大气污染物对公众健康、生态环境的危害和影响程度，制定公布有毒有害大气污染物名录并适时更新，实行风险管理。 排放前款规定名录中所列有毒有害大气污染物的企业事业单位，应当按照国家规定建设环境风险预警体系，对排污口和周边环境进行定期监测，评估环境风险，排查环境安全隐患，并采取有效措施防范环境风险。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百四十八条", "text": "向大气排放持久性有机污染物的企业事业单位和其他生产经营者以及废弃物焚烧设施的运营单位，应当按照国家规定，采取有利于减少持久性有机污染物排放的技术方法和工艺，配备有效的净化装置，实现达标排放。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百四十九条", "text": "各级人民政府及其有关部门编制国土空间规划和相关规划，应当统筹规划，合理安排土地用途和建设布局，防止、减少恶臭污染。 企业事业单位和其他生产经营者在生产经营活动中产生恶臭气体的，应当科学选址，设置合理的防护距离，并安装净化装置或者采取其他有效措施，防止排放恶臭气体。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百五十条", "text": "地方各级人民政府应当加强对餐饮服务业布局和设置的引导，在经营主体登记注册环节提示选址禁止性要求。 排放油烟污染物的餐饮服务业经营者应当按照规定安装油烟净化等污染防治设施并保持正常使用。禁止在居民住宅楼、未配套设立专用烟道的商住综合楼以及商住综合楼内与居住层相邻的商业楼层内新建、改建、扩建产生油烟、异味、废气的餐饮服务项目。 排放油烟污染物的餐饮服务业经营者应当采取有效措施，使污染物达标排放，并防止对附近居民的正常生活环境造成污染。 任何单位和个人不得在当地人民政府禁止的时段和区域露天烧烤食品或者为露天烧烤食品提供场地。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百五十一条", "text": "禁止在人口集中地区和其他依法需要特殊保护的区域焚烧沥青、油毡、橡胶、塑料、皮革、垃圾及其他产生有毒有害烟尘和恶臭气体的物质。 禁止生产、销售或者燃放不符合质量标准的烟花爆竹。任何单位和个人不得在县级以上地方人民政府禁止的时段和区域燃放烟花爆竹。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百五十二条", "text": "国家鼓励和倡导文明、绿色祭祀。 火葬场应当设置除尘等污染防治设施并保持正常使用，防止影响周边环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百五十三条", "text": "从事服装干洗和机动车维修等服务活动的经营者，应当按照国家相关标准或者要求设置异味和废气处理装置等污染防治设施并保持正常使用，防止影响周边环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百五十四条", "text": "国家鼓励、支持消耗臭氧层物质替代品的生产、使用，逐步减少直至停止消耗臭氧层物质的生产、使用。 国家对消耗臭氧层物质的生产、使用、进出口实行总量控制和配额管理，具体办法由国务院制定。 第五章 重点区域大气污染联合防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百五十五条", "text": "国家建立健全重点区域大气污染联防联控机制，统筹协调重点区域内大气污染防治工作。国务院生态环境主管部门根据主体功能区划、区域大气环境质量状况和大气污染传输扩散规律，划定国家大气污染防治重点区域，报国务院批准。 国家大气污染防治重点区域内有关省、自治区、直辖市人民政府应当确定牵头的地方人民政府，定期召开联席会议，按照统一规划、统一标准、统一监测、统一防治措施的要求，开展大气污染联合防治，落实大气污染防治目标责任。国务院生态环境主管部门应当加强指导、督促。 省、自治区、直辖市可以参照本条第一款规定划定本行政区域的大气污染防治重点区域。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百五十六条", "text": "国务院生态环境主管部门会同有关部门和国家大气污染防治重点区域内有关省、自治区、直辖市人民政府，根据重点区域经济社会发展和大气环境的承载能力，制定重点区域大气污染联合防治行动计划，明确控制目标，优化区域经济布局，统筹交通管理，发展清洁低碳能源，提出重点防治任务和措施，促进重点区域大气环境质量改善。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百五十七条", "text": "国务院发展改革部门会同国务院生态环境主管部门，结合国家大气污染防治重点区域产业发展实际和大气环境质量状况，进一步提高污染防治、能源消耗等要求。 国家大气污染防治重点区域内有关省、自治区、直辖市人民政府应当实施更严格的机动车大气污染物排放标准，统一在用机动车检验方法和排放限值，并配套供应合格的车用燃油。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百五十八条", "text": "编制可能对国家大气污染防治重点区域的大气环境造成严重污染的有关工业园区、开发区、区域产业和发展等规划，规划编制机关应当与重点区域内有关省、自治区、直辖市人民政府或者有关部门会商。 国家大气污染防治重点区域内有关省、自治区、直辖市建设可能对相邻省、自治区、直辖市大气环境质量产生重大影响的项目，应当及时通报有关信息，进行会商。 会商意见及其采纳情况作为生态环境影响报告书、生态环境影响报告表审查或者审批的重要依据。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百五十九条", "text": "国家大气污染防治重点区域内新建、改建、扩建用煤项目的，应当实行煤炭的等量或者减量替代。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百六十条", "text": "国务院生态环境主管部门应当组织建立健全国家大气污染防治重点区域的大气环境质量监测、大气污染源监测等相关信息共享机制，利用监测、模拟以及卫星、航测、遥感等新技术分析重点区域内大气污染来源及其变化趋势，并向社会公开。 第六章 重污染天气应对"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百六十一条", "text": "国家建立健全重污染天气监测预警体系。 国务院生态环境主管部门会同国务院气象等有关部门和国家大气污染防治重点区域内有关省、自治区、直辖市人民政府，建立健全重点区域重污染天气监测预警机制，统一预警分级标准。可能发生区域重污染天气的，应当及时向重点区域内有关省、自治区、直辖市人民政府通报。 设区的市级以上地方人民政府生态环境主管部门会同气象等有关部门建立健全本行政区域重污染天气监测预警机制。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百六十二条", "text": "设区的市级以上地方人民政府以及可能发生重污染天气的县级人民政府，应当制定重污染天气应对预案，报上一级人民政府生态环境主管部门备案并公布。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百六十三条", "text": "设区的市级以上地方人民政府生态环境主管部门会同气象主管机构建立健全会商机制，进行大气环境质量预报。可能发生重污染天气的，应当及时向本级人民政府报告。设区的市级以上地方人民政府依据重污染天气预报信息，进行综合研判，确定预警等级并及时发出预警。预警等级根据情况变化及时调整。任何单位和个人不得擅自发布重污染天气预报预警信息。 预警信息发布后，人民政府及其有关部门应当通过电视、广播、网络、短信等途径及时告知公众采取健康防护措施，指导公众出行和调整其他相关社会活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百六十四条", "text": "县级以上地方人民政府应当依据重污染天气的预警等级，及时启动应对预案，根据应对的需要可以采取责令有关企业停产或者限产、限制部分机动车行驶和非道路移动机械使用、禁止燃放烟花爆竹、停止工地土石方作业和建筑物拆除施工、停止露天烧烤、停止幼儿园和学校组织的户外活动、组织开展人工影响天气作业等应对措施。 应对响应结束后，人民政府应当及时开展应对预案实施情况的评估，适时修改完善应对预案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百六十五条", "text": "国家加强重污染天气重点行业绩效分级。绩效分级水平作为重污染天气差异化采取应对措施的依据。 第三分编 水污染防治 第七章 一般规定"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百六十六条", "text": "本分编适用于江河湖泊、运河、渠道、水库等地表水体以及地下水体污染的防治。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百六十七条", "text": "本法所称水污染，是指水体因某种物质的介入，而导致其化学、物理、生物或者放射性等方面特性的改变，从而影响水的有效利用，危害公众健康或者破坏生态环境，造成水质恶化的现象。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百六十八条", "text": "水污染防治应当优先保护饮用水水源、保障饮用水安全，严格控制工业污染、城镇生活污染，防治农业面源污染，加强入河排污口设置和管理，积极推进生态治理工程建设，预防、控制和减少水环境污染和生态破坏。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百六十九条", "text": "国务院生态环境主管部门对全国水污染防治工作实施统一监督管理。国务院生态环境主管部门流域生态环境监督管理机构依法开展流域水污染防治监督管理相关工作。地方人民政府生态环境主管部门对本行政区域水污染防治工作实施统一监督管理。 海事管理机构对船舶污染水域的防治工作实施监督管理。 县级以上人民政府水行政、自然资源、卫生健康、住房城乡建设、农业农村、渔业渔政等有关部门在各自职责范围内对水污染防治工作实施监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百七十条", "text": "防治水污染应当按流域或者按区域进行统一规划。国务院生态环境主管部门会同国务院发展改革、水行政等有关部门编制国家流域水生态环境保护规划，明确长江、黄河、淮河、海河、珠江、松花江、辽河等流域的生态环境保护要求，报国务院批准。 省、自治区、直辖市内跨县江河湖泊的流域水生态环境保护规划，由省级人民政府生态环境主管部门会同发展改革、水行政等有关部门，根据国家流域水生态环境保护规划和本地实际情况编制，报省、自治区、直辖市人民政府批准，并报国务院生态环境主管部门备案。 县级以上地方人民政府根据依法批准的流域水生态环境保护规划和实际需要，可以组织编制本行政区域的水生态环境保护规划。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百七十一条", "text": "有关设区的市、县级人民政府应当按照水生态环境保护规划确定的水生态环境质量改善目标的要求，编制限期达标规划，采取有效措施按期达标。 有关设区的市、县级人民政府应当将限期达标规划报上一级人民政府备案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百七十二条", "text": "国家建立健全水生态环境质量监测和水污染物排放监测制度。国务院生态环境主管部门会同国务院水行政等有关部门组织监测网络，统一规划国家水生态环境质量监测站点的设置，建立健全监测数据共享机制，加强对水生态环境监测的管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百七十三条", "text": "国务院生态环境主管部门及其流域生态环境监督管理机构负责监测省界水体的水生态环境质量状况。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百七十四条", "text": "国务院生态环境主管部门会同国务院卫生健康主管部门，根据对公众健康、生态环境的危害和影响程度，制定公布有毒有害水污染物名录并适时更新，实行风险管理。 排放前款规定名录中所列有毒有害水污染物的企业事业单位和其他生产经营者，应当对排污口和周边环境进行监测，评估环境风险，排查环境安全隐患，并向社会公开有毒有害水污染物信息，采取有效措施防范环境风险。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百七十五条", "text": "新设、改设、扩大入河排污口，应当按照规定报经有管辖权的生态环境主管部门或者国务院生态环境主管部门流域生态环境监督管理机构同意。新设、改设、扩大可能影响防洪、供水、堤防安全、河势稳定的入河排污口的，审批时应当征求地方人民政府水行政主管部门或者有关流域管理机构的意见。入河排污口设置和管理的具体办法由国务院生态环境主管部门制定。 本法所称入河排污口，是指直接或者通过管道、沟、渠等排污通道向江河湖泊、运河、水库等水体排放污水的口门。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百七十六条", "text": "水生态环境质量不达标的水功能区，除城乡污水集中处理设施等重要民生工程的入河排污口外，应当严格控制新设、改设、扩大入河排污口。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百七十七条", "text": "县级以上地方人民政府应当对本行政区域的入河排污口组织开展排查整治，明确责任主体，实施分类管理。 入河排污口的责任主体应当加强源头治理、排污通道巡查维护和入河排污口整治、规范化建设、维护管理等。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百七十八条", "text": "多个单位和个人共用入河排污口的责任主体，应当加强入河排污口监测，按照规定开展监控、自动监测。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百七十九条", "text": "禁止向水体排放油类、酸液、碱液、剧毒废液。禁止在水体清洗装贮过油类或者有毒有害污染物的车辆和容器。 禁止向水体排放、倾倒放射性固体废物或者含有高放射性和中放射性物质的废水。向水体排放含低放射性物质的废水，应当符合国家有关放射性污染防治的规定和标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百八十条", "text": "向水体排放含热废水，应当采取有效措施，保证水体的水温符合水生态环境质量标准，避免对珍稀濒危水生生物、水产资源造成危害。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百八十一条", "text": "含病原体的污水应当经过消毒处理，符合国家相关标准后，方可排放。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百八十二条", "text": "禁止向水体排放、倾倒工业废渣、城镇垃圾和其他废弃物。 禁止将含有汞、镉、砷、铬、铅、氰化物、黄磷等的可溶性剧毒废渣向水体排放、倾倒或者直接埋入地下。 存放可溶性剧毒废渣的场所，应当采取防水、防渗漏、防流失的措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百八十三条", "text": "地方各级人民政府应当组织开展本行政区域的黑臭水体调查和治理工作，建立健全长效机制，制定公布黑臭水体清单，科学制定黑臭水体治理方案，系统推进黑臭水体整治，防止水体返黑返臭。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百八十四条", "text": "县级以上人民政府应当组织水行政、自然资源、生态环境等有关部门开展地下水状况调查评价，包括地下水资源调查评价、地下水污染调查评价和水文地质勘查评价等。 地下水状况调查评价结论是编制地下水保护利用和污染防治等规划以及管理地下水的重要依据，应当依法向社会公开。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百八十五条", "text": "国务院生态环境主管部门会同国务院水行政、自然资源等有关部门，指导全国地下水污染防治重点区划定工作。 省级人民政府生态环境主管部门会同水行政、自然资源等有关部门，根据本行政区域地下水污染防治的需要，划定地下水污染防治重点区，明确环境准入、隐患排查、风险管控等管理要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百八十六条", "text": "在泉域保护范围以及岩溶强发育、存在较多落水洞和岩溶漏斗的区域，不得新建、改建、扩建可能造成地下水污染的建设项目。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百八十七条", "text": "化工园区和化工项目、矿山开采区、尾矿库、危险废物处置场、垃圾填埋场等的运营、管理单位，应当采取防渗漏等措施，并建设地下水水质监测井进行监测，防止地下水污染。 加油站、采油厂等的地下油罐应当使用双层罐或者采取建造防渗池等其他有效措施，并进行防渗漏监测，防止地下水污染。 禁止利用无防渗漏措施的沟渠、坑塘等输送或者贮存含有毒有害污染物的废水、含病原体的污水和其他废弃物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百八十八条", "text": "多层含水层开采、回灌地下水应当防止串层污染。 多层地下水的含水层水质差异大的，应当分层开采；对已受污染的潜水和承压水，不得混合开采。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百八十九条", "text": "建设地下工程设施或者进行地下勘探、采矿等活动，应当采取防护措施，防止地下水污染。 报废矿井、钻井或者取水井等，应当实施封井或者回填。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百九十条", "text": "人工回灌补给地下水，应当符合相关水质标准，不得恶化地下水水质。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百九十一条", "text": "可能发生水污染事故的企业事业单位，应当制定有关水污染事故的应急预案，做好应急准备，并定期进行演练。 生产、储存危险化学品的企业事业单位，应当采取封堵、围挡、转移等措施，防止在处理安全生产事故过程中产生的可能严重污染水体的消防废物直接排入水体。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百九十二条", "text": "企业事业单位发生事故或者其他突发性事件，造成或者可能造成水污染事故的，应当立即启动本单位的应急预案，采取隔离等应急措施，防止水污染物进入水体，并向事故发生地县级以上地方人民政府或者生态环境主管部门报告。生态环境主管部门接到报告后，应当及时向本级人民政府报告，并抄送水行政、应急管理等有关部门。 造成渔业污染事故或者渔业船舶造成水污染事故的，应当向事故发生地渔业渔政主管部门报告，接受调查处理。其他船舶造成水污染事故的，应当向事故发生地海事管理机构报告，接受调查处理；给渔业造成损害的，海事管理机构应当通知渔业渔政主管部门参与调查处理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百九十三条", "text": "设区的市、县级人民政府应当组织制定饮用水安全突发事件应急预案。 饮用水供水单位应当根据所在地饮用水安全突发事件应急预案，制定相应的突发事件应急预案，报所在地设区的市、县级人民政府备案，并定期进行演练。 饮用水水源发生水污染事故，或者发生其他可能影响饮用水安全的突发性事件，饮用水供水单位应当采取应急处理措施，向所在地设区的市、县级人民政府报告，并向社会公开。有关人民政府应当根据实际情况及时启动应急预案，采取有效措施，保障供水安全。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百九十四条", "text": "国家推行重点行业企业污水治理与排放水平绩效分级。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百九十五条", "text": "各级人民政府应当加强水污染防治，安排必要的资金用于下列事项： （一）水污染防治的科学技术研究开发、示范工程和项目； （二）各级人民政府及其有关部门组织实施的水生态环境状况调查评估、流域水污染治理、集中式饮用水水源地保护、城镇污水处理管网建设和维护、入河排污口排查整治、黑臭水体整治、地下水生态环境保护、水污染防治监督管理能力建设等活动； （三）各级人民政府及其有关部门对水污染事故的应急处置； （四）各级人民政府规定的涉及水污染防治的其他事项。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百九十六条", "text": "海洋污染的防治不适用本分编。 第八章 水污染防治措施 第一节 工业水污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百九十七条", "text": "国务院有关部门和县级以上地方人民政府应当合理规划工业布局，要求造成水污染的企业进行技术改造，采取综合防治措施，提高水的重复利用率，减少废水和污染物排放量。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百九十八条", "text": "排放工业废水的企业应当采取有效措施，收集和处理产生的全部废水，防止污染环境。含有毒有害水污染物的工业废水应当分类收集和处理，防止渗漏、流失，不得稀释排放。 工业园区等区域应当配套建设相应的污水集中处理设施，按照规定安装自动监测设备，与生态环境主管部门的监控设备联网，并保证监测设备正常运行。 向污水集中处理设施排放工业废水的，应当按照国家规定进行预处理，达到集中处理设施处理工艺要求后，方可排放。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第二百九十九条", "text": "禁止建设不符合国家产业政策的小型造纸、制革、印染、染料、炼焦、炼硫、炼砷、炼汞、炼油、电镀、农药、石棉、水泥、玻璃、钢铁、火电及其他严重污染水环境的生产项目。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百条", "text": "企业应当采用原材料利用效率高、污染物排放量少的清洁工艺，并加强管理，减少水污染物的产生。 第二节 城镇水污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百零一条", "text": "城镇污水应当集中处理。 县级以上地方人民政府应当通过财政预算和其他渠道筹集资金，统筹安排建设城镇污水集中处理设施及配套管网、污泥无害化处理处置设施，因地制宜推进雨污分流，提高本行政区域城镇污水的收集率和处理率。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百零二条", "text": "国务院住房城乡建设主管部门会同国务院发展改革部门、生态环境主管部门，根据国土空间规划和水生态环境保护规划，组织编制全国城镇污水处理设施建设相关规划。县级以上地方人民政府组织住房城乡建设、发展改革、生态环境、水行政等有关部门依法编制本行政区域的城镇污水处理设施建设相关规划。县级以上地方人民政府住房城乡建设主管部门应当按照城镇污水处理设施建设相关规划，组织建设城镇污水集中处理设施及配套管网、污泥无害化处理处置设施，并加强监督管理。 城镇污水集中处理设施的运营单位按照国家规定向排污者提供污水处理的有偿服务，收取污水处理费用，保证污水集中处理设施的正常运行。收取的污水处理费用应当用于城镇污水集中处理设施的建设、运行、维护和污泥无害化处理处置以及国务院规定的其他相关事项，不得挪作他用。 城镇污水集中处理设施的污水处理收费、管理以及使用的具体办法，由国务院制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百零三条", "text": "向城镇污水集中处理设施排放水污染物，应当符合水污染物排放标准。 城镇污水集中处理设施的运营单位，应当对城镇污水集中处理设施的出水水质负责。 生态环境主管部门应当对城镇污水集中处理设施的出水水质和水量进行监督检查。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百零四条", "text": "城镇污水集中处理设施的运营单位和污泥无害化处理处置单位应当无害化处理处置污泥，保证处理处置后的污泥符合国家标准，并对污泥的流向、用途、用量等进行跟踪、记录，并报告城镇排水主管部门、生态环境主管部门。 第三节 农业和农村水污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百零五条", "text": "国家支持农村污水、垃圾处理设施的建设，因地制宜推进农村污水、垃圾处理和厕所改造。 地方各级人民政府应当统筹规划、建设农村污水、垃圾处理设施，并保障其正常运行。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百零六条", "text": "制定农药、肥料等产品的质量标准和使用标准，应当适应水生态环境保护的要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百零七条", "text": "运输、贮存农药和处置过期失效农药，应当加强管理，防止造成水污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百零八条", "text": "县级以上地方人民政府农业农村等有关部门应当在各自职责范围内推广高效低毒低残留农药和测土配方施肥技术，控制农药和化肥的过量使用，防止造成水污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百零九条", "text": "国家支持畜禽养殖场建设畜禽粪污的综合利用或者无害化处理设施。 畜禽养殖场应当保证其畜禽粪污的综合利用或者无害化处理设施正常运行，保证粪污达标排放，防止污染水环境。 畜禽散养密集区所在地县、乡级人民政府应当组织对畜禽粪污进行分户收集、集中处理利用。县级人民政府组织确定本行政区域的畜禽散养密集区。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百一十条", "text": "从事水产养殖活动应当保护水域生态环境，排放水产养殖尾水污染物等应当符合污染物排放标准，防止污染水环境。 工厂化养殖和设置统一排污口的集中连片养殖的单位和其他生产经营者，应当按照规定对养殖尾水自行监测。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百一十一条", "text": "农田灌溉用水应当符合相应的水质标准，防止污染土壤、地下水和农产品。 禁止向农田灌溉渠道排放工业废水或者医疗污水。向农田灌溉渠道排放城镇污水以及未综合利用的畜禽养殖粪污、水产养殖尾水、农产品加工废水的，应当保证其下游最近的灌溉取水点的水质符合农田灌溉用水水质标准。 第四节 船舶水污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百一十二条", "text": "船舶排放含油污水、生活污水，应当符合船舶污染物排放标准。从事海洋航运的船舶进入内河和港口的，应当遵守内河的船舶污染物排放标准。 船舶的残油、废油应当回收，禁止排入水体。 禁止向水体倾倒船舶垃圾。 船舶装载运输油类、有毒有害货物，应当采取防止溢流和渗漏的措施，防止货物落水造成水污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百一十三条", "text": "进入中华人民共和国内河的国际航线船舶排放压载水的，应当采用压载水处理装置或者采取其他等效措施，对压载水进行灭活等处理。禁止排放不符合规定的船舶压载水。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百一十四条", "text": "船舶应当按照国家规定配备相应的防污设备和器材，并持有合法有效的防治水域环境污染的证书与文书。 船舶进行涉及污染物、压载水等排放及操作，应当严格遵守操作规程，按照规定开展监测、监控，如实记录并保存。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百一十五条", "text": "港口、码头、装卸站和船舶修造厂所在地县级以上地方人民政府应当统筹规划、建设船舶污染物、废弃物的接收、转运、处理处置设施，建立健全相应的接收、转运、处理处置多部门联合监督管理制度。 港口、码头、装卸站和船舶修造厂应当配备足够的船舶污染物、废弃物的接收设施。从事船舶污染物、废弃物接收作业，或者从事装载油类、污染危害性货物船舱清洗作业的单位，应当具备与其运营规模相适应的接收处理能力。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百一十六条", "text": "船舶及有关作业单位从事有污染风险的作业活动，应当遵守法律法规、标准和国务院有关部门的规定，采取有效措施，防止造成水污染。海事管理机构、渔业渔政主管部门应当在各自职责范围内加强对船舶及有关作业活动的监督管理。 通过船舶运输散装液体污染危害性货物的，应当遵守法律、行政法规以及国务院交通运输主管部门关于船舶污染防治的规定。船舶进行散装液体污染危害性货物的过驳作业，应当编制作业方案，采取有效的安全和污染防治措施，并报作业地海事管理机构批准。 禁止采取冲滩方式进行船舶拆解作业。 第九章 饮用水水源和其他特殊水体保护"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百一十七条", "text": "国家建立健全饮用水水源保护区制度。饮用水水源保护区分为一级保护区和二级保护区；必要时，可以在饮用水水源保护区外围划定一定的区域作为准保护区。 饮用水水源保护区的划定，由有关市、县人民政府提出划定方案，报省、自治区、直辖市人民政府批准。跨市、县饮用水水源保护区的划定，由有关市、县人民政府协商提出划定方案，报省、自治区、直辖市人民政府批准；协商不成的，由省级人民政府生态环境主管部门会同水行政、自然资源、住房城乡建设、疾病预防控制等有关部门提出划定方案，征求有关部门的意见后，报省、自治区、直辖市人民政府批准。 跨省、自治区、直辖市的饮用水水源保护区，由有关省、自治区、直辖市人民政府商国务院生态环境主管部门流域生态环境监督管理机构、国务院水行政主管部门流域管理机构划定；协商不成的，由国务院生态环境主管部门会同国务院水行政、自然资源、住房城乡建设、疾病预防控制等有关部门提出划定方案，征求国务院有关部门的意见后，报国务院批准。 省级以上人民政府可以根据保护饮用水水源的需要，调整饮用水水源保护区的范围，确保饮用水安全。有关地方人民政府应当在饮用水水源保护区的边界设立明确的地理界标和明显的警示标志。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百一十八条", "text": "在饮用水水源保护区内，禁止设置排污口。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百一十九条", "text": "禁止在饮用水水源一级保护区内新建、改建、扩建与供水设施和保护水源无关的建设项目；已建成的与供水设施和保护水源无关的建设项目，由县级以上人民政府责令拆除或者关闭。 禁止在饮用水水源一级保护区内从事网箱养殖、旅游、游泳、垂钓或者其他可能污染饮用水水体的活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百二十条", "text": "禁止在饮用水水源二级保护区内新建、改建、扩建排放污染物的建设项目；已建成的排放污染物的建设项目，由县级以上人民政府责令拆除或者关闭。 在饮用水水源二级保护区内从事网箱养殖、旅游等活动的，应当按照规定采取有效措施，防止污染饮用水水体。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百二十一条", "text": "禁止在饮用水水源准保护区内新建、扩建对水体污染严重的建设项目；改建建设项目，不得增加排污量。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百二十二条", "text": "县级以上地方人民政府应当根据保护饮用水水源的需要，在准保护区内采取工程措施或者建造湿地、水源涵养林等生态保护措施，防止水污染物直接排入饮用水水体，确保饮用水安全。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百二十三条", "text": "县级以上地方人民政府应当组织生态环境等有关部门，对饮用水水源保护区、地下水型饮用水源的补给区以及供水单位周边区域的生态环境状况和污染风险进行调查评估，筛查可能存在的污染风险因素，并采取相应的风险防范措施。 饮用水水源受到污染可能威胁供水安全的，生态环境主管部门应当责令有关企业事业单位和其他生产经营者采取停止排放水污染物等措施，并通报饮用水供水单位和供水、卫生健康、水行政等有关部门；跨行政区域的，还应当通报有关地方人民政府。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百二十四条", "text": "单一水源供水城市的人民政府应当建设应急水源或者备用水源，有条件的地区可以开展区域联网供水。 县级以上地方人民政府应当合理安排、布局农村饮用水水源，有条件的地区可以采取城镇供水管网延伸或者建设跨村、跨乡镇联片集中供水工程等方式，发展规模集中供水。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百二十五条", "text": "饮用水供水单位应当做好取水口和出水口的水质检测工作。发现取水口水质不符合饮用水水源水质标准或者出水口水质不符合饮用水卫生标准的，应当及时采取相应措施，并向所在地设区的市、县级人民政府供水主管部门报告。供水主管部门接到报告后，应当通报生态环境、卫生健康、水行政等有关部门。 饮用水供水单位应当对供水水质负责，确保供水设施安全可靠运行，保证供水水质符合国家相关标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百二十六条", "text": "县级以上地方人民政府应当组织有关部门监测、评估本行政区域饮用水水源、供水单位供水和用户水龙头出水的水质等饮用水安全状况。 县级以上地方人民政府应当组织有关部门至少每季度向社会公开一次饮用水安全状况信息。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百二十七条", "text": "省级以上人民政府根据水生态环境保护的需要，可以规定在饮用水水源保护区内，采取禁止或者限制使用含磷洗涤剂、农药、化肥以及限制种植养殖等措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百二十八条", "text": "县级以上人民政府可以对自然保护地水体、重要渔业水体和其他具有特殊经济文化价值的水体划定保护区，并采取有效措施，保证保护区的水质符合规定用途的水生态环境质量标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百二十九条", "text": "在自然保护地水体、重要渔业水体和其他具有特殊经济文化价值的水体的保护区内，禁止新设排污口；法律、行政法规另有规定的除外。在保护区附近新设排污口，应当科学论证，制定水污染防治方案，采取有效措施保证保护区水体不受污染。 第十章 重点流域水污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百三十条", "text": "国家加强重点流域水污染的综合治理、系统治理、源头治理，推进重点河湖综合整治。 国务院生态环境等有关部门和重点流域地方各级人民政府应当采取有效措施，加大对重点流域的水污染防治力度，预防、控制和减少水环境污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百三十一条", "text": "国务院生态环境主管部门会同国务院水行政等有关部门和有关省、自治区、直辖市人民政府，建立健全重要江河湖泊的流域水生态环境联合保护协调机制。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百三十二条", "text": "对没有国家水污染物排放标准的特色产业、特有污染物，以及国家有明确要求的特定水污染源或者水污染物，重点流域省、自治区、直辖市人民政府应当补充制定地方水污染物排放标准，报国务院生态环境主管部门备案。 有下列情形之一的，重点流域省、自治区、直辖市人民政府应当制定严于国家水污染物排放标准的地方水污染物排放标准，报国务院生态环境主管部门备案： （一）产业密集、水环境污染问题突出； （二）现有水污染物排放标准不能满足重点流域水生态环境质量要求； （三）流域或者区域水生态环境形势复杂，无法适用统一的水污染物排放标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百三十三条", "text": "重点流域产业结构和布局应当与其生态环境的承载能力相适应。禁止重污染企业和项目向重点流域中上游转移。 第四分编 海洋污染防治 第十一章 一般规定"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百三十四条", "text": "本分编适用于海洋污染的防治。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百三十五条", "text": "本法所称海洋污染，是指直接或者间接地把物质或者能量引入海洋，导致损害海洋生物资源、危害人体健康、妨害渔业和海上其他合法活动、损害海水使用素质和减损生态环境质量的现象。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百三十六条", "text": "国务院生态环境主管部门负责全国防治陆源污染物、海岸工程和海洋工程建设项目、海洋倾倒废弃物对海洋环境污染损害的工作。 国务院交通运输主管部门负责所辖港区水域内非军事船舶和港区水域外非渔业、非军事船舶污染海洋环境的监督管理，组织、协调、指挥重大海上溢油应急处置。海事管理机构具体负责上述水域内相关船舶污染海洋环境的监督管理，并负责污染事故的调查处理；对在中华人民共和国管辖海域航行、停泊和作业的外国籍船舶造成的污染事故登轮检查处理。船舶污染事故给渔业造成损害的，应当吸收渔业渔政主管部门参与调查处理。 国务院渔业渔政主管部门负责渔港水域内非军事船舶和渔港水域外渔业船舶污染海洋环境的监督管理，负责调查处理前款规定的污染事故以外的渔业污染事故。 军队生态环境保护部门负责军事船舶污染海洋环境的监督管理及污染事故的调查处理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百三十七条", "text": "跨部门的重大海洋污染防治工作，由国务院生态环境主管部门协调；协调未能解决的，由国务院作出决定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百三十八条", "text": "国务院生态环境主管部门会同有关部门、机构和沿海省、自治区、直辖市人民政府编制全国海洋生态环境保护规划，报国务院批准后实施。 沿海地方各级人民政府应当根据全国海洋生态环境保护规划，组织实施其管理海域的海洋生态环境保护工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百三十九条", "text": "国务院生态环境主管部门负责海洋生态环境监测工作，组织实施海洋生态环境质量监测，统一发布国家海洋生态环境状况公报，定期组织对海洋生态环境质量状况进行调查评价。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百四十条", "text": "国务院有关部门和海警机构应当向国务院生态环境主管部门提供编制国家海洋生态环境状况公报所必需的入海河口和海洋生态环境监测、调查、监视等方面的资料。 生态环境主管部门应当向有关部门和海警机构提供与海洋生态环境监督管理有关的资料。 本法所称入海河口，是指河流终端与受水体（海）相结合的地段。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百四十一条", "text": "国家加强海洋辐射环境监测，国务院生态环境主管部门负责制定海洋辐射环境应急监测方案并组织实施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百四十二条", "text": "企业事业单位和其他生产经营者应当优先使用清洁低碳能源，采用资源利用率高、污染物排放量少的清洁生产工艺，防止对海洋环境的污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百四十三条", "text": "沿海县级以上地方人民政府因地制宜依法编制并组织实施养殖水域滩涂规划，确定可以用于养殖业的水域和滩涂，科学划定海水养殖限养区和养殖区，建立禁养区内海水养殖的清理和退出机制。 从事海水养殖活动应当保护海域生态环境，及时规范收集处理固体废物，防止造成海洋生态环境的损害。 向海洋排放养殖尾水污染物等应当符合污染物排放标准。沿海省、自治区、直辖市人民政府应当制定海水养殖污染物排放相关地方标准，加强养殖尾水污染防治的监督管理。工厂化养殖和设置统一排污口的集中连片养殖的单位和其他生产经营者，应当按照规定对养殖尾水自行监测。 禁止在氮磷浓度严重超标的近岸海域新增或者扩大投饵、投肥、投饲海水养殖规模。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百四十四条", "text": "因发生事故或者其他突发性事件，造成或者可能造成海洋环境污染、生态破坏事件的单位和个人，应当立即采取有效措施解除或者减轻危害，及时通报可能受到危害者，并向负有海洋生态环境保护监督管理职责的部门、机构报告，接受调查处理。 沿海县级以上地方人民政府在本行政区域近岸海域的生态环境受到严重损害时，应当采取有效措施，解除或者减轻危害。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百四十五条", "text": "国家根据防止海洋环境污染的需要，制定国家重大海上污染事件应急预案，建立健全海上溢油污染等应急机制，保障应对工作的必要经费。 国家建立健全重大海上溢油应急处置部际联席会议制度。国务院交通运输主管部门牵头组织制定国家重大海上溢油应急处置预案并组织实施。 国务院生态环境主管部门负责制定全国海洋石油勘探开发海上溢油污染事件应急预案并组织实施。 国家海事管理机构负责制定全国船舶重大海上溢油污染事件应急预案，报国务院生态环境主管部门、应急管理部门备案。 沿海县级以上地方人民政府及其有关部门应当制定有关应急预案，在发生海洋污染事件时，及时启动应急预案，采取有效措施，解除或者减轻危害。 可能发生海洋污染事件的单位，应当按照规定制定本单位的应急预案，配备应急设备和器材，定期组织开展应急演练；应急预案应当报负有海洋生态环境保护监督管理职责的部门、机构备案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百四十六条", "text": "负有海洋生态环境保护监督管理职责的部门、机构，有权对从事影响海洋生态环境活动的单位和个人进行监督检查，可以在海上开展联合执法；在巡航监视中发现违法行为时，应当依法予以制止并调查取证，必要时有权采取有效措施，防止事态扩大，并报告有关部门、机构处理。 第十二章 陆源污染物海洋污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百四十七条", "text": "向海域排放陆源污染物，应当严格执行有关规定和标准。 本法所称陆源，是陆地污染源的简称，是指从陆地向海域排放污染物，造成或者可能造成海洋环境污染的场所、设施等。 本法所称陆源污染物，是指由陆地污染源排放的污染物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百四十八条", "text": "入海排污口位置的选择，应当符合国土空间用途管制要求，根据海水动力条件和有关规定，经科学论证后，报设区的市级以上人民政府生态环境主管部门备案。入海排污口的责任主体应当加强入海排污口监测，按照规定开展监控、自动监测。 生态环境主管部门应当在完成备案后十五个工作日内将入海排污口设置情况通报自然资源、海事、渔业渔政等有关部门和海警机构、军队生态环境保护部门。 沿海县级以上地方人民政府应当根据入海排污口类别、责任主体，组织有关部门对本行政区域的各类入海排污口进行排查整治和日常监督管理，建立健全近岸海域、入海排污口、排污管线、污染源全链条治理体系。 国务院生态环境主管部门负责制定入海排污口设置和管理的具体办法，制定入海排污口技术规范，组织建设统一的入海排污口信息平台，加强动态更新、信息共享和公开。 本法所称入海排污口，是指海岸线向海一侧，直接或者通过管道、沟、渠等排污通道向海洋排放污水的口门，包括工业排污口、城镇污水集中处理设施排污口、农业排口及其他排口等类型。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百四十九条", "text": "在自然保护地、重要渔业水域、海水浴场、生态保护红线区域及其他需要特别保护的区域，禁止新设工业排污口和城镇污水集中处理设施排污口；法律、行政法规另有规定的除外。 在有条件的地区，应当将入海排污口深水设置，实行离岸排放。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百五十条", "text": "经开放式沟、渠向海洋排放污染物的，对开放式沟、渠按照有关规定和标准实施水生态环境质量管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百五十一条", "text": "国务院有关部门、县级以上地方人民政府及其有关部门应当按照河海联动的原则，依照水污染防治有关法律、行政法规的规定，加强入海河流管理，协同推进入海河流污染防治，使入海河口的水质符合入海河口生态环境质量要求。 入海河流流域省、自治区、直辖市人民政府应当按照国家规定，加强入海总氮、总磷排放的管控，制定控制方案并组织实施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百五十二条", "text": "禁止向海域排放油类、酸液、碱液、剧毒废液。 禁止向海域排放污染海洋环境、破坏海洋生态的放射性废水。 严格控制向海域排放含有不易降解的有机物和重金属的废水。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百五十三条", "text": "含病原体的医疗污水、生活污水和工业废水应当经过处理，符合有关排放标准后，方可排入海域。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百五十四条", "text": "含有机物和营养物质的工业废水、生活污水，应当严格控制向海湾、半封闭海及其他自净能力较差的海域排放。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百五十五条", "text": "向海域排放含热废水，应当采取有效措施，保证邻近自然保护地、渔业水域的水温符合海洋生态环境质量标准，避免对珍稀濒危海洋生物、海洋水产资源造成危害。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百五十六条", "text": "沿海地方各级人民政府应当加强农业面源污染防治。沿海农田、林场施用化学农药，应当执行国家农药安全使用的规定和标准。沿海农田、林场应当合理使用化肥和植物生长调节剂。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百五十七条", "text": "在沿海陆域弃置、堆放和处理尾矿、矿渣、煤灰渣、垃圾和其他固体废物的，依照法律规定执行，并采取有效措施防止固体废物进入海洋。 禁止在岸滩弃置、堆放或者处理固体废物；法律、行政法规另有规定的除外。 本法所称沿海陆域，是指与海岸相连，或者通过管道、沟、渠、设施，直接或者间接向海洋排放污染物及其相关活动的一带区域。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百五十八条", "text": "沿海县级以上地方人民政府负责其管理海域的海洋垃圾污染防治，建立健全海洋垃圾监测、清理制度，统筹规划、建设陆域接收、转运、处理海洋垃圾的设施，明确有关部门、乡镇、街道、企业事业单位等的海洋垃圾管控区域，建立海洋垃圾监测、拦截、收集、打捞、运输、处理体系并组织实施，采取有效措施鼓励、支持公众参与上述活动。 国务院生态环境、住房城乡建设、发展改革等有关部门应当在各自职责范围内加强海洋垃圾污染防治的监督指导和保障。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百五十九条", "text": "禁止经中华人民共和国内水、领海过境转移危险废物。 经中华人民共和国管辖的其他海域转移危险废物的，应当事先取得国务院生态环境主管部门的书面同意。 本法所称内水，是指我国领海基线向内陆一侧的所有海域。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百六十条", "text": "沿海县级以上地方人民政府应当建设和完善排水管网，根据改善海洋生态环境质量的需要建设污水处理设施，加强城乡污水处理。 建设污水海洋处置工程，应当符合国家规定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百六十一条", "text": "国家采取必要措施，防止、减少和控制来自大气层或者通过大气层造成的海洋污染。 第十三章 工程建设项目海洋污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百六十二条", "text": "新建、改建、扩建海岸工程和海洋工程建设项目，应当遵守国家有关建设项目生态环境保护的规定，并把污染防治和生态保护所需资金纳入建设项目投资计划。 禁止在依法划定的自然保护地、重要渔业水域及其他需要特别保护的区域，违法建设污染环境、破坏生态的海岸工程和海洋工程建设项目或者从事其他活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百六十三条", "text": "禁止在沿海陆域建设不符合国家产业政策的化学制浆造纸、化工、印染、制革、电镀、酿造、炼油、岸边冲滩拆船及其他严重污染海洋环境的生产项目。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百六十四条", "text": "从岸上打井开采海底矿产资源，应当采取有效措施，防止污染海洋环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百六十五条", "text": "海岸工程和海洋工程建设项目不得使用含超标放射性物质或者易溶出有毒有害物质的材料；不得造成领海基点及其周边环境的侵蚀、淤积、损害，不得危及领海基点的稳定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百六十六条", "text": "海岸工程和海洋工程建设项目需要爆破作业时，应当采取有效措施，保护海洋生态环境。 海洋石油勘探开发及输油过程中，应当采取有效措施，避免溢油事故的发生。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百六十七条", "text": "海岸工程和海洋工程建设项目不得违法向海洋排放污染物、废弃物及其他有害物质。 海洋油气钻井平台（船）、生产生活平台、生产储卸装置等海洋油气装备的含油污水和油性混合物，应当经过处理达标后排放；残油、废油应当予以回收，不得排放入海。 钻井所使用的油基泥浆和其他有毒复合泥浆不得排放入海。水基泥浆和无毒复合泥浆及钻屑的排放，应当符合国家规定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百六十八条", "text": "海洋油气钻井平台（船）、生产生活平台、生产储卸装置等海洋油气装备及其有关海上设施，不得向海域处置含油的工业固体废物。处置其他固体废物，不得造成海洋环境污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百六十九条", "text": "海上试油时，应当确保油气充分燃烧，油和油性混合物不得排放入海。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百七十条", "text": "勘探开发海洋油气资源，应当按照规定制定油气污染应急预案，报国务院生态环境主管部门海域派出机构备案。 第十四章 废弃物倾倒海洋污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百七十一条", "text": "任何个人和未经批准的单位，不得向中华人民共和国管辖海域倾倒任何废弃物。 需要倾倒废弃物的，产生废弃物的单位应当向国务院生态环境主管部门海域派出机构提出书面申请，并出具废弃物特性和成分检验报告，取得倾倒许可证后，方可倾倒。 国家鼓励疏浚物等废弃物的综合利用，避免或者减少海洋倾倒。 禁止中华人民共和国境外的废弃物在中华人民共和国管辖海域倾倒。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百七十二条", "text": "国务院生态环境主管部门根据废弃物的毒性、有毒物质含量和对海洋生态环境的影响程度，制定海洋倾倒废弃物评价程序和标准。 可以向海洋倾倒的废弃物名录，由国务院生态环境主管部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百七十三条", "text": "国务院生态环境主管部门会同国务院自然资源主管部门编制全国海洋倾倒区规划，并征求国务院交通运输、渔业渔政等有关部门和海警机构的意见，报国务院批准。 国务院生态环境主管部门根据全国海洋倾倒区规划，按照科学、合理、经济、安全的原则及时选划海洋倾倒区，征求国务院交通运输、渔业渔政等有关部门和海警机构的意见，并向社会公告。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百七十四条", "text": "国务院生态环境主管部门组织开展海洋倾倒区使用状况评估，根据评估结果予以调整、暂停使用或者封闭海洋倾倒区。 海洋倾倒区的调整、暂停使用和封闭情况，应当通报国务院有关部门、海警机构并向社会公开。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百七十五条", "text": "获准和实施倾倒废弃物的单位，应当按照许可证注明的期限及条件，到指定的区域进行倾倒。倾倒作业船舶等载运工具应当安装使用符合要求的海洋倾倒在线监控设备，并与国务院生态环境主管部门监管系统联网。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百七十六条", "text": "获准和实施倾倒废弃物的单位，应当按照规定向颁发许可证的国务院生态环境主管部门海域派出机构报告倾倒情况。倾倒废弃物的船舶应当向驶出港的海事管理机构、海警机构报告。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百七十七条", "text": "获准倾倒废弃物的单位委托实施废弃物海洋倾倒作业的，应当对受托单位的主体资格、技术能力和信用状况进行核实，依法签订书面合同，在合同中约定污染防治和生态保护要求，并监督实施。 受托单位实施废弃物海洋倾倒作业，应当依照法律法规规定和合同约定，履行污染防治和生态保护要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百七十八条", "text": "向海洋倾倒废弃物，应当按照国家规定缴纳倾倒费。具体办法由国务院发展改革部门、财政部门会同国务院生态环境主管部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百七十九条", "text": "禁止海上焚烧废弃物。 禁止在海上处置污染海洋环境、破坏海洋生态的放射性废物或者其他放射性物质。 本法所称海上焚烧，是指以热摧毁为目的，在海上焚烧设施上，故意焚烧废弃物或者其他物质的行为，但是船舶、平台或者其他人工构造物正常操作中所附带发生的行为除外。 第十五章 船舶海洋污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百八十条", "text": "在中华人民共和国管辖海域，任何船舶及有关作业不得违法向海洋排放船舶垃圾、生活污水、含油污水、含有毒有害物质污水、废气等污染物，废弃物，压载水和沉积物及其他有害物质。 船舶应当按照国家规定采取有效措施，对压载水和沉积物进行处理处置，严格防控引入外来有害生物。 从事船舶污染物、废弃物接收和船舶清舱、洗舱作业活动的，应当具备相应的接收处理能力。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百八十一条", "text": "船舶应当配备相应的防污设备和器材。 船舶的材料、结构、配备的防污设备和器材应当符合国家防治船舶污染海洋环境的规定，并经检验合格。 船舶应当取得并持有防治海洋环境污染的证书与文书，进行涉及船舶污染物、压载水和沉积物等排放及操作，应当按照规定开展监测、监控，如实记录并保存。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百八十二条", "text": "船舶应当遵守海上交通安全法律法规的规定，防止因碰撞、触礁、搁浅、火灾或者爆炸等引起的海难事故，造成海洋环境污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百八十三条", "text": "国家完善并实施船舶油污损害民事赔偿责任制度；按照船舶油污损害赔偿责任由船东和货主共同承担风险的原则，完善并实施船舶油污保险、油污损害赔偿基金制度，具体办法由国务院制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百八十四条", "text": "载运具有污染危害性货物进出港口的船舶，其承运人、货物所有人或者代理人，应当事先向海事管理机构申报。经批准后，方可进出港口或者装卸作业。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百八十五条", "text": "交付船舶载运污染危害性货物的，托运人应当将货物的正式名称、污染危害性以及应当采取的防护措施如实告知承运人。污染危害性货物的单证、包装、标志、数量限制等，应当符合对所交付货物的有关规定。 需要船舶载运污染危害性不明的货物，应当按照规定事先进行评估。 装卸油类、有毒有害货物的作业，船岸双方应当遵守安全防污操作规程。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百八十六条", "text": "港口、码头、装卸站和船舶修造拆解单位所在地县级以上地方人民政府应当统筹规划、建设船舶污染物等的接收、转运、处理处置设施，建立健全相应的接收、转运、处理处置多部门联合监督管理制度。 沿海县级以上地方人民政府负责对其管理海域的渔港和渔业船舶停泊点及周边区域污染防治的监督管理，规范生产生活污水和渔业垃圾回收处置，推进污染防治设备建设和环境清理整治。 港口、码头、装卸站和船舶修造拆解单位应当按照规定配备足够的船舶污染物、废弃物的接收设施，使该设施处于良好状态并有效运行。 装卸污染危害性货物的港口、码头、装卸站和船舶应当制定污染应急预案，并配备相应的污染应急设备和器材。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百八十七条", "text": "国家海事管理机构组织制定中国籍船舶禁止或者限制安装和使用的有害材料名录。 船舶修造单位和船舶所有人、经营人、管理人应当在船上备有有害材料清单，在船舶建造、营运和维修过程中持续更新，并在船舶拆解前提供给从事船舶拆解的单位。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百八十八条", "text": "从事船舶拆解的单位，应当采取有效的污染防治措施，在船舶拆解前将船舶污染物减至最小量，对拆解产生的船舶污染物、废弃物和其他有害物质进行安全与环境无害化处置，防止污染海洋环境。拆解的船舶部件不得入水。 禁止采取冲滩方式在海岸进行船舶拆解作业。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百八十九条", "text": "船舶应当按照国家规定采取有效措施提高能效水平。倡导绿色低碳智能航运，鼓励船舶使用清洁低碳能源，淘汰高耗能高排放老旧船舶，减少温室气体和大气污染物的排放。沿海县级以上地方人民政府应当制定港口岸电、船舶受电等设施建设和改造计划，并组织实施。港口岸电设施的供电能力应当与靠港船舶的用电需求相适应。 国务院和沿海县级以上地方人民政府对港口岸电设施、船舶受电设施的改造和使用，以及清洁低碳能源动力船舶的建造等按照规定给予支持。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百九十条", "text": "国务院交通运输主管部门可以划定船舶污染物排放控制区。进入控制区的船舶应当符合船舶污染物排放相关控制要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百九十一条", "text": "船舶及有关作业活动应当遵守法律法规、标准和国务院有关部门的规定，采取有效措施，防止造成海洋环境污染。海事管理机构等应当加强对船舶及有关作业活动的监督管理。 船舶进行散装液体污染危害性货物的过驳作业，应当编制作业方案，采取有效的安全和污染防治措施，并事先按照规定报经批准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百九十二条", "text": "船舶发生海难事故，造成或者可能造成海洋环境重大污染的，海事管理机构有权强制采取避免或者减少污染的措施。 对在公海上因发生海难事故，造成中华人民共和国管辖海域重大污染后果或者具有污染威胁的船舶、海上设施，海事管理机构有权采取与实际的或者可能发生的损害相称的必要措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百九十三条", "text": "所有船舶均有监视海上污染的义务，在发现海上污染事件或者违反本法规定的行为时，应当立即向就近的负有海洋生态环境保护监督管理职责的部门、机构报告。 民用航空器发现海上排污或者污染事件，应当及时向就近的民用航空空中交通管制单位报告。接到报告的单位，应当立即向负有海洋生态环境保护监督管理职责的部门、机构通报。 第五分编 土壤污染防治 第十六章 一般规定"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百九十四条", "text": "本分编适用于土壤污染的防治。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百九十五条", "text": "本法所称土壤污染，是指因人为因素导致某种物质进入陆地表层土壤，引起土壤化学、物理、生物等方面特性的改变，影响土壤功能和有效利用，危害公众健康或者破坏生态环境的现象。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百九十六条", "text": "土壤污染防治应当坚持风险管控，保障农产品质量安全、人居环境安全，推动土壤资源永续利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百九十七条", "text": "土地使用权人从事土地开发利用活动，企业事业单位和其他生产经营者从事生产经营活动，应当采取有效措施，防止、减少土壤污染，对所造成的土壤污染依法承担责任。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百九十八条", "text": "国务院生态环境主管部门对全国土壤污染防治工作实施统一监督管理。地方人民政府生态环境主管部门对本行政区域土壤污染防治工作实施统一监督管理。 县级以上人民政府农业农村、自然资源、住房城乡建设、林业草原等有关部门在各自职责范围内对土壤污染防治工作实施监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第三百九十九条", "text": "设区的市级以上地方人民政府生态环境主管部门会同发展改革、农业农村、自然资源、住房城乡建设、林业草原等有关部门，根据生态环境保护规划要求、土地用途、土壤污染状况普查和监测结果等，编制土壤污染防治规划，报本级人民政府批准后公布实施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百条", "text": "国务院生态环境主管部门根据土壤污染状况、公众健康风险、生态环境风险和科学技术水平，并按照土地用途，制定国家土壤污染风险管控标准，加强土壤污染防治标准体系建设。 省、自治区、直辖市人民政府对国家土壤污染风险管控标准中未作规定的项目，可以制定地方土壤污染风险管控标准；对国家土壤污染风险管控标准中已作规定的项目，可以制定严于国家土壤污染风险管控标准的地方土壤污染风险管控标准。地方土壤污染风险管控标准应当报国务院生态环境主管部门备案。 土壤污染风险管控标准是强制性标准。 国家支持对土壤环境背景值的研究。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百零一条", "text": "国务院统一领导全国土壤污染状况普查。国务院生态环境主管部门会同国务院农业农村、自然资源、住房城乡建设、林业草原等有关部门，每十年至少组织开展一次全国土壤污染状况普查。 国务院有关部门和设区的市级以上地方人民政府可以根据本行业、本行政区域实际情况组织开展土壤污染状况详查。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百零二条", "text": "国务院生态环境主管部门会同国务院农业农村、自然资源、住房城乡建设、水行政、卫生健康、林业草原等有关部门组织监测网络，统一规划国家土壤环境监测站点的设置。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百零三条", "text": "地方人民政府农业农村主管部门、林业草原主管部门会同生态环境主管部门、自然资源主管部门对下列农用地地块进行重点监测： （一）产出的农产品污染物含量超标的； （二）作为或者曾作为污水灌溉区的； （三）用于或者曾用于规模化养殖，固体废物堆放、填埋的； （四）曾作为工矿用地或者发生过重大、特别重大污染事故的； （五）有毒有害物质生产、贮存、利用、处置设施周边的； （六）国务院农业农村主管部门、林业草原主管部门、生态环境主管部门、自然资源主管部门规定的其他情形。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百零四条", "text": "地方人民政府生态环境主管部门会同自然资源主管部门对下列建设用地地块进行重点监测： （一）曾用于生产、贮存、使用、回收、处置有毒有害物质的； （二）曾用于固体废物堆放、填埋的； （三）曾发生过重大、特别重大污染事故的； （四）国务院生态环境主管部门、自然资源主管部门规定的其他情形。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百零五条", "text": "国务院生态环境主管部门会同国务院农业农村、自然资源、住房城乡建设、水行政、卫生健康、林业草原等有关部门建立健全土壤环境基础数据库，构建全国土壤环境信息平台，实行数据动态更新和信息共享。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百零六条", "text": "土壤污染状况普查报告、监测数据、调查报告和土壤污染风险评估报告、风险管控效果评估报告、修复效果评估报告等，应当及时上传全国土壤环境信息平台。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百零七条", "text": "生态环境主管部门应当将涉及主要食用农产品生产区域的重大土壤环境信息，及时通报农业农村主管部门、卫生健康主管部门和市场监督管理部门。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百零八条", "text": "省级以上人民政府生态环境主管部门和其他负有土壤污染防治监督管理职责的部门，应当在各自职责范围内对从事土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估、后期管理等活动的单位和个人的执业情况，依照法律规定进行信用监管。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百零九条", "text": "各级人民政府应当加强土壤污染防治，安排必要的资金用于下列事项： （一）土壤污染防治的科学技术研究开发、示范工程和项目； （二）各级人民政府及其有关部门组织实施的土壤污染状况普查、监测、调查和土壤污染责任人认定、风险评估、风险管控、修复等活动； （三）各级人民政府及其有关部门对涉及土壤污染的突发事件的应急处置； （四）各级人民政府规定的涉及土壤污染防治的其他事项。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百一十条", "text": "国家加大土壤污染防治资金投入力度，建立健全土壤污染防治基金制度。设立中央土壤污染防治专项资金和省级土壤污染防治基金，主要用于农用地土壤污染防治和土壤污染责任人或者土地使用权人无法认定的土壤污染风险管控和修复以及人民政府规定的其他事项。 土壤污染责任人无法认定的污染地块，土地使用权人实际承担土壤污染风险管控和修复的，可以按照规定申请土壤污染防治基金，集中用于土壤污染风险管控和修复。 土壤污染防治基金的具体管理办法，由国务院财政部门会同国务院生态环境、农业农村、自然资源、住房城乡建设、林业草原等有关部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百一十一条", "text": "国家鼓励金融机构加大对土壤污染风险管控和修复项目的信贷投放。 国家鼓励金融机构在办理土地权利抵押业务时开展土壤污染状况调查。 第十七章 土壤污染预防"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百一十二条", "text": "生产、贮存、运输、使用、回收、处置、排放有毒有害物质的单位和个人，应当采取有效措施，防止有毒有害物质渗漏、流失、扬散，避免土壤受到污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百一十三条", "text": "国务院生态环境主管部门会同国务院卫生健康、农业农村等有关部门，根据对公众健康、生态环境的危害和影响程度，对土壤中有毒有害物质进行筛查评估，制定公布重点控制的土壤有毒有害物质名录并适时更新。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百一十四条", "text": "设区的市级以上地方人民政府生态环境主管部门应当按照国务院生态环境主管部门的规定，根据有毒有害物质排放等情况，制定公布本行政区域的土壤污染重点监管单位名录并适时更新。 土壤污染重点监管单位应当履行下列义务： （一）严格控制有毒有害物质排放，并按年度向生态环境主管部门报告排放情况； （二）建立土壤、地下水污染隐患排查整治制度，保证持续有效防止有毒有害物质渗漏、流失、扬散； （三）制定、实施自行监测方案，并将监测数据报送生态环境主管部门； （四）将贮存有毒有害物质的地下储罐信息报送生态环境主管部门。 前款规定的义务应当在排污许可证中记载。 生态环境主管部门发现土壤污染重点监管单位监测数据异常，应当及时进行调查。设区的市级以上地方人民政府生态环境主管部门应当定期对土壤污染重点监管单位周边土壤、地下水进行监测。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百一十五条", "text": "企业事业单位和其他生产经营者拆除设施、设备或者建筑物、构筑物的，应当采取相应的土壤污染防治措施。 土壤污染重点监管单位拆除设施、设备或者建筑物、构筑物的，应当制定包括应急措施在内的土壤污染防治工作方案，报地方人民政府生态环境主管部门、工业和信息化主管部门备案并实施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百一十六条", "text": "生态环境主管部门、自然资源主管部门应当在各自职责范围内依法加强对矿产资源开发区域土壤污染防治的监督管理，按照相关标准和总量控制的要求，严格控制可能造成土壤污染的重点污染物排放。 尾矿库运营、管理单位应当按照规定，加强尾矿库的安全管理，采取有效措施防止土壤污染。危库、险库、病库及其他需要重点监管的尾矿库的运营、管理单位应当按照规定，进行土壤污染状况监测和定期评估。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百一十七条", "text": "地方人民政府应急管理部门应当监督尾矿库运营、管理单位履行防治土壤污染的法定义务，防止其发生可能污染土壤的事故；地方人民政府生态环境主管部门应当加强对尾矿库土壤污染防治情况的监督检查和定期评估，发现风险隐患的，及时督促尾矿库运营、管理单位采取相应措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百一十八条", "text": "国家鼓励在建筑、通信、电力、交通、水利等领域的信息、网络、防雷、接地等建设工程中采用新技术、新材料，防止土壤污染。 禁止在土壤中使用重金属含量超标的降阻产品。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百一十九条", "text": "建设和运行污水集中处理设施、固体废物处置设施，应当依照法律法规规定和相关标准的要求，采取有效措施防止土壤污染。 地方人民政府生态环境主管部门应当定期对污水集中处理设施、固体废物处置设施周边土壤进行监测；对不符合法律法规规定和相关标准要求的，应当根据监测结果，要求污水集中处理设施、固体废物处置设施运营单位采取相应改进措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百二十条", "text": "国务院农业农村主管部门、林业草原主管部门在各自职责范围内编制规划，完善相关标准和措施，加强农用地农药、化肥使用指导和使用总量控制，加强农用薄膜使用控制。 国务院农业农村主管部门应当加强农药、肥料登记，组织开展农药、肥料对土壤环境影响的安全性评价。 制定农药、兽药、饲料和饲料添加剂、肥料、农用薄膜等农业投入品及其包装物标准和农田灌溉用水水质标准，应当适应土壤污染防治的要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百二十一条", "text": "地方人民政府农业农村主管部门、林业草原主管部门应当在各自职责范围内开展农用地土壤污染防治宣传和技术培训活动，扶持农业生产专业化服务，指导农业生产经营者科学合理安全使用农药、兽药、饲料和饲料添加剂、肥料、农用薄膜等农业投入品，控制农药、兽药、化肥等的使用量。 地方人民政府农业农村主管部门应当鼓励农业生产经营者采取有利于防止土壤污染的种养结合、轮作休耕等农业耕作措施；支持采取土壤改良、土壤肥力提升等有利于土壤养护和培育的措施；支持畜禽粪污处理、利用设施的建设。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百二十二条", "text": "禁止向耕地、林地、草地等农用地排放重金属或者其他有毒有害物质含量超标的污水、污泥，以及可能造成土壤污染的清淤底泥、尾矿、矿渣等。 县级以上人民政府有关部门应当在各自职责范围内加强对畜禽粪污、沼渣、沼液等收集、贮存、利用、处置的监督管理，防止土壤污染。 地方人民政府生态环境主管部门会同农业农村主管部门、水行政主管部门加强对农田灌溉用水水质的管理，对农田灌溉用水水质进行监测和监督检查。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百二十三条", "text": "国家鼓励、支持农业生产经营者采取下列措施： （一）使用高效低毒低残留农药以及先进喷施技术； （二）使用符合标准的有机肥、高效肥； （三）采用测土配方施肥技术、生物防治等病虫害绿色防控技术； （四）使用生物可降解农用薄膜； （五）综合利用秸秆、移出高富集污染物秸秆； （六）按照规定对退化土壤等进行改良。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百二十四条", "text": "禁止生产、销售或者使用国家明令禁止的农业投入品。 农业投入品生产者、销售者和使用者应当及时回收农药、肥料等农业投入品的包装废弃物和农用薄膜，并将农药包装废弃物交由专门的机构或者组织进行无害化处理。具体办法由国务院农业农村主管部门会同国务院生态环境等有关部门制定。 国家采取有效措施，鼓励研究开发、生产、销售、使用在生态环境中可降解且无害的农用薄膜，鼓励、支持单位和个人回收农业投入品包装废弃物和农用薄膜。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百二十五条", "text": "国家加强对未污染土壤的保护。 地方各级人民政府应当重点保护未污染的耕地、林地、草地和饮用水水源地。 对未利用地应当予以保护，不得污染、破坏。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百二十六条", "text": "地方人民政府及其有关部门应当依法加强对向沙漠、滩涂、盐碱地、沼泽地等未利用地非法排放有毒有害物质等行为的监督检查。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百二十七条", "text": "县级以上地方人民政府及其有关部门应当按照国土空间规划，严格执行相关行业企业布局选址要求，禁止在居民住宅区和学校、医院、疗养院、养老院等单位周边新建、改建、扩建可能造成土壤污染的建设项目。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百二十八条", "text": "对开发建设过程中剥离的表土，应当单独收集和存放，符合条件的应当优先用于土地复垦、土壤改良、造地和绿化等。 禁止将重金属或者其他有毒有害物质含量超标的工业固体废物、生活垃圾或者污染土壤用于土地复垦。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百二十九条", "text": "因科学研究等特殊原因，需要进口土壤的，应当遵守国家出入境检验检疫的规定。 第十八章 土壤污染风险管控和修复 第一节 总体要求"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百三十条", "text": "土壤污染风险管控和修复，包括土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估、后期管理等活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百三十一条", "text": "实施土壤污染状况调查活动，应当编制土壤污染状况调查报告。 土壤污染状况调查报告应当主要包括地块基本信息、污染物含量是否超过土壤污染风险管控标准等内容。污染物含量超过土壤污染风险管控标准的，土壤污染状况调查报告还应当包括污染类型、污染来源以及地下水是否受到污染等内容。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百三十二条", "text": "实施土壤污染风险评估活动，应当编制土壤污染风险评估报告。 土壤污染风险评估报告应当主要包括下列内容： （一）主要污染物状况； （二）土壤及地下水污染范围； （三）农产品质量安全风险、公众健康风险或者生态环境风险； （四）风险管控、修复的目标和基本要求等。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百三十三条", "text": "实施风险管控、修复活动，应当因地制宜、科学合理，提高针对性和有效性。 实施风险管控、修复活动，不得对土壤和周边环境造成新的污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百三十四条", "text": "实施风险管控、修复活动前，地方人民政府有关部门有权根据实际情况，要求土壤污染责任人、土地使用权人采取移除污染源、防止污染扩散等措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百三十五条", "text": "实施风险管控、修复活动中产生的废水、废气和固体废物，应当按照规定进行处理、处置，并达到相关生态环境保护标准。 实施风险管控、修复活动中产生的固体废物以及拆除的设施、设备或者建筑物、构筑物属于危险废物的，应当依照法律法规规定和相关标准的要求进行处置。 修复施工期间，应当设立公告牌，向社会公开相关情况和生态环境保护措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百三十六条", "text": "修复施工单位转运污染土壤的，应当制定转运计划，将运输时间、方式、线路和污染土壤数量、去向、最终处置措施等，提前报送所在地和接受地生态环境主管部门。 转运的污染土壤属于危险废物的，修复施工单位应当依照法律法规规定和相关标准的要求进行处置。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百三十七条", "text": "实施风险管控效果评估、修复效果评估活动，应当编制效果评估报告。 效果评估报告应当主要包括是否达到土壤污染风险评估报告确定的风险管控、修复目标等内容。 风险管控、修复活动完成后，需要实施后期管理的，土壤污染责任人应当按照要求实施后期管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百三十八条", "text": "从事土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估、后期管理等活动的单位，应当具备相应的专业能力。 接受委托从事前款活动的单位应当对其出具的调查报告、风险评估报告、风险管控效果评估报告、修复效果评估报告的真实性、准确性和完整性负责，并按照约定对风险管控、修复、后期管理等活动结果负责。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百三十九条", "text": "土壤污染责任人负有实施土壤污染风险管控和修复的义务。土壤污染责任人无法认定的，土地使用权人应当实施土壤污染风险管控和修复。 地方人民政府及其有关部门可以根据实际情况组织实施土壤污染风险管控和修复。 国家鼓励、支持有关当事人自愿实施土壤污染风险管控和修复。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百四十条", "text": "因实施或者组织实施土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估、后期管理等活动所支出的费用，由土壤污染责任人承担。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百四十一条", "text": "土壤污染责任人变更的，由变更后承继其债权、债务的单位和个人履行相关土壤污染风险管控和修复义务并承担相关费用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百四十二条", "text": "土壤污染责任人不明确或者存在争议的，农用地由地方人民政府农业农村主管部门、林业草原主管部门会同生态环境主管部门、自然资源主管部门认定，建设用地由地方人民政府生态环境主管部门会同自然资源主管部门认定。认定办法由国务院生态环境主管部门会同有关部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百四十三条", "text": "发生突发事件可能造成土壤污染的，地方人民政府及其有关部门、有关企业事业单位和其他生产经营者应当立即采取应急措施，防止土壤污染，并依照本法规定做好土壤污染状况监测、调查和土壤污染风险评估、风险管控、修复等工作。 第二节 农用地土壤污染风险管控和修复"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百四十四条", "text": "国家建立健全农用地分类管理制度。按照土壤污染程度和相关标准，将农用地划分为优先保护类、安全利用类和严格管控类。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百四十五条", "text": "县级以上地方人民政府应当依法将符合条件的优先保护类耕地划为永久基本农田，实行严格保护。 在永久基本农田集中区域，不得新建可能造成土壤污染的建设项目；已建成的，应当限期拆除或者关闭。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百四十六条", "text": "未利用地、复垦土地等拟开垦为耕地的，地方人民政府农业农村主管部门会同生态环境主管部门、自然资源主管部门进行土壤污染状况调查，依法进行分类管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百四十七条", "text": "对土壤污染状况普查、详查和监测、现场检查表明有土壤污染风险的农用地地块，地方人民政府农业农村主管部门、林业草原主管部门会同生态环境主管部门、自然资源主管部门进行土壤污染状况调查。 对土壤污染状况调查表明污染物含量超过土壤污染风险管控标准的农用地地块，地方人民政府农业农村主管部门、林业草原主管部门会同生态环境主管部门、自然资源主管部门组织进行土壤污染风险评估，并按照农用地分类管理制度管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百四十八条", "text": "对安全利用类农用地地块，地方人民政府农业农村主管部门、林业草原主管部门，应当在各自职责范围内结合主要作物品种和种植习惯等情况，制定并实施安全利用方案。 安全利用方案应当包括下列内容： （一）农艺调控、替代种植； （二）定期开展土壤和农产品协同监测与评价； （三）对农民、农民专业合作社及其他农业生产经营主体进行技术指导和培训； （四）其他风险管控措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百四十九条", "text": "对严格管控类农用地地块，地方人民政府农业农村主管部门、林业草原主管部门应当在各自职责范围内采取下列风险管控措施： （一）提出划定特定农产品禁止生产区域的建议，报本级人民政府批准后实施； （二）按照规定开展土壤和农产品协同监测与评价； （三）对农民、农民专业合作社及其他农业生产经营主体进行技术指导和培训； （四）其他风险管控措施。 各级人民政府及其有关部门应当鼓励对严格管控类农用地采取调整种植结构、退耕还林还草、退耕还湿、轮作休耕、轮牧休牧等风险管控措施，并给予相应的政策支持。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百五十条", "text": "安全利用类和严格管控类农用地地块的土壤污染影响或者可能影响地下水、饮用水水源安全的，地方人民政府生态环境主管部门会同农业农村、林业草原等有关部门制定防治污染的方案，并采取相应的措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百五十一条", "text": "对安全利用类和严格管控类农用地地块，土壤污染责任人应当按照国家规定以及土壤污染风险评估报告的要求，采取相应的风险管控措施，并定期向地方人民政府农业农村主管部门、林业草原主管部门报告。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百五十二条", "text": "对产出的农产品污染物含量超标，需要实施修复的农用地地块，土壤污染责任人应当编制修复方案，报地方人民政府农业农村主管部门、林业草原主管部门备案并实施。修复方案应当包括地下水污染防治的内容。 修复活动应当优先采取不影响农业生产、不降低土壤生产功能的生物修复措施，阻断或者减少污染物进入农作物食用部分，确保农产品质量安全。 风险管控、修复活动完成后，土壤污染责任人应当另行委托有关单位对风险管控效果、修复效果进行评估，并将效果评估报告报地方人民政府农业农村主管部门、林业草原主管部门备案。 农村集体经济组织及其成员、农民专业合作社及其他农业生产经营主体等负有协助实施土壤污染风险管控和修复的义务。 第三节 建设用地土壤污染风险管控和修复"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百五十三条", "text": "国家实行建设用地土壤污染风险管控和修复名录制度。 建设用地土壤污染风险管控和修复名录由省级人民政府生态环境主管部门会同自然资源等有关部门制定，按照规定向社会公开，并根据风险管控、修复情况适时更新。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百五十四条", "text": "对土壤污染状况普查、详查和监测、现场检查表明有土壤污染风险的建设用地地块，地方人民政府生态环境主管部门应当要求土地使用权人按照规定进行土壤污染状况调查。 用途变更为居住、公共管理与公共服务用地的，变更前应当按照规定进行土壤污染状况调查。土壤污染状况调查应当在省、自治区、直辖市确定的时限前完成。 前两款规定的土壤污染状况调查报告应当报送地方人民政府生态环境主管部门，由地方人民政府生态环境主管部门会同自然资源主管部门组织评审。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百五十五条", "text": "对土壤污染状况调查报告评审表明污染物含量超过土壤污染风险管控标准的建设用地地块，土壤污染责任人、土地使用权人应当按照国务院生态环境主管部门的规定进行土壤污染风险评估，并将土壤污染风险评估报告报送省级人民政府生态环境主管部门。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百五十六条", "text": "省级人民政府生态环境主管部门会同自然资源等有关部门按照国务院生态环境主管部门的规定，对土壤污染风险评估报告组织评审，及时将需要实施风险管控、修复的地块纳入建设用地土壤污染风险管控和修复名录，并定期向国务院生态环境主管部门、自然资源主管部门报告。 列入建设用地土壤污染风险管控和修复名录的地块，不得作为居住、公共管理与公共服务用地。具体管理办法由省、自治区、直辖市制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百五十七条", "text": "对建设用地土壤污染风险管控和修复名录中的地块，土壤污染责任人应当按照国家规定以及土壤污染风险评估报告的要求，采取相应的风险管控措施，并定期向地方人民政府生态环境主管部门报告。风险管控措施应当包括地下水污染防治的内容。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百五十八条", "text": "对建设用地土壤污染风险管控和修复名录中的地块，地方人民政府生态环境主管部门可以根据实际情况采取下列风险管控措施： （一）提出划定隔离区域的建议，报本级人民政府批准后实施； （二）进行土壤及地下水污染状况监测； （三）其他风险管控措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百五十九条", "text": "对建设用地土壤污染风险管控和修复名录中需要实施修复的地块，土壤污染责任人应当结合国土空间规划编制修复方案，报地方人民政府生态环境主管部门备案并实施。修复方案应当包括地下水污染防治的内容。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百六十条", "text": "风险管控、修复活动完成后，土壤污染责任人应当另行委托有关单位对风险管控效果、修复效果进行评估，并将效果评估报告报地方人民政府生态环境主管部门备案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百六十一条", "text": "对达到土壤污染风险评估报告确定的风险管控、修复目标的建设用地地块，土壤污染责任人、土地使用权人可以申请省级人民政府生态环境主管部门移出建设用地土壤污染风险管控和修复名录。 省级人民政府生态环境主管部门会同自然资源等有关部门对风险管控效果评估报告、修复效果评估报告组织评审，及时将达到土壤污染风险评估报告确定的风险管控、修复目标且可以安全利用的地块移出建设用地土壤污染风险管控和修复名录，按照规定向社会公开，并定期向国务院生态环境主管部门、自然资源主管部门报告。 未达到土壤污染风险评估报告确定的风险管控、修复目标，或者未按照规定进行土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估的建设用地地块，禁止开工建设任何与风险管控、修复无关的项目；已经开工建设的，应当立即停止施工。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百六十二条", "text": "土壤污染重点监管单位生产经营用地的用途变更或者在其土地使用权收回、转让前，应当由土地使用权人按照规定进行土壤污染状况调查。土壤污染状况调查报告应当作为不动产登记资料送交地方人民政府不动产登记机构，并报地方人民政府生态环境主管部门备案；土地使用权人未送交土壤污染状况调查报告的，地方人民政府不动产登记机构应当要求其补充提供。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百六十三条", "text": "土地使用权已经被地方人民政府收回，土壤污染责任人为原土地使用权人的，由地方人民政府组织实施土壤污染风险管控和修复。 第六分编 固体废物污染防治 第十九章 一般规定"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百六十四条", "text": "本分编适用于固体废物污染的防治。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百六十五条", "text": "本法所称固体废物，是指在生产、生活和其他活动中产生的丧失原有利用价值或者虽未丧失利用价值但是被抛弃或者放弃的固态、半固态和置于容器中的气态的物品、物质以及法律、行政法规规定纳入固体废物管理的物品、物质。经无害化加工处理，并且符合强制性国家产品质量标准，不会危害公众健康和生态安全，或者根据固体废物鉴别标准和鉴别程序认定为不属于固体废物的除外。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百六十六条", "text": "固体废物污染防治坚持减量化、资源化和无害化的原则，加强产生、收集、贮存、运输、利用、处置等全过程管控。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百六十七条", "text": "国家采取有效措施加强固体废物综合治理，推进城乡固体废物源头减量和资源化充分利用，最大限度降低固体废物填埋量。 任何单位和个人都应当采取有效措施，减少固体废物的产生量，促进固体废物的综合利用，降低固体废物的危害性。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百六十八条", "text": "产生、收集、贮存、运输、利用、处置固体废物的单位和个人，应当采取有效措施，防止或者减少固体废物污染，对所造成的污染依法承担责任。 贮存固体废物，是指将固体废物临时置于特定设施或者场所中的活动。 利用固体废物，是指将固体废物直接作为替代原材料或者燃料使用、从固体废物中提取物质作为原材料或者燃料的活动。 处置固体废物，是指将固体废物焚烧和用其他改变固体废物的物理、化学、生物特性的方法，达到减少已产生的固体废物数量、缩小固体废物体积、减少或者消除其危险成分的活动，或者将固体废物最终置于符合生态环境保护规定要求的填埋场的活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百六十九条", "text": "国务院生态环境主管部门对全国固体废物污染防治工作实施统一监督管理。地方人民政府生态环境主管部门对本行政区域固体废物污染防治工作实施统一监督管理。 县级以上人民政府发展改革、工业和信息化、自然资源、住房城乡建设、交通运输、农业农村、商务、卫生健康、海关等有关部门在各自职责范围内对固体废物污染防治工作实施监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百七十条", "text": "省、自治区、直辖市之间可以协商建立跨行政区域固体废物污染联防联控机制，统筹规划制定、设施建设、固体废物转移等工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百七十一条", "text": "设区的市级以上地方人民政府编制固体废物污染防治规划，统筹规划、建设固体废物转运、集中处置等设施、场所，推动固体废物污染防治工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百七十二条", "text": "国务院生态环境主管部门会同有关部门根据国家生态环境质量标准和国家经济、技术条件，制定固体废物鉴别标准、鉴别程序、污染防治技术标准和工业固体废物中有毒有害物质含量控制标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百七十三条", "text": "固体废物综合利用标准应当明确综合利用产品中的有毒有害物质限值。 综合利用固体废物应当遵守生态环境法律法规的规定，符合固体废物综合利用标准和污染防治技术标准。使用固体废物综合利用产物应当符合国家规定的用途、标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百七十四条", "text": "国务院生态环境主管部门会同有关部门建立全国危险废物等固体废物污染防治信息平台，推进固体废物产生、收集、贮存、转移、利用、处置等全过程监控和信息化追溯。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百七十五条", "text": "产生、收集、贮存、运输、利用、处置固体废物的单位和其他生产经营者，应当采取防扬散、防流失、防渗漏或者其他防止污染环境的措施，不得擅自倾倒、堆放、丢弃、抛撒、遗撒或者焚烧固体废物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百七十六条", "text": "转移固体废物出省、自治区、直辖市行政区域贮存、处置的，应当向固体废物移出地省级人民政府生态环境主管部门提出申请。移出地省级人民政府生态环境主管部门应当及时商经接受地省级人民政府生态环境主管部门同意后，在规定期限内批准转移该固体废物出省、自治区、直辖市行政区域。未经批准的，不得转移。 转移固体废物出省、自治区、直辖市行政区域利用的，应当通过固体废物污染防治信息平台等提前将有关信息报送固体废物移出地和接受地省级人民政府生态环境主管部门。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百七十七条", "text": "禁止中华人民共和国境外的固体废物进境倾倒、堆放、处置。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百七十八条", "text": "国家实行固体废物零进口，由国务院生态环境主管部门会同国务院商务、发展改革、海关等有关部门组织实施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百七十九条", "text": "海关发现进口货物疑似固体废物的，可以委托专业机构开展属性鉴别，并根据鉴别结论依法管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百八十条", "text": "收集、贮存、运输、利用、处置固体废物的单位和其他生产经营者，应当加强对相关设施、设备和场所的管理和维护，保证其正常运行和使用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百八十一条", "text": "在生态保护红线区域、永久基本农田集中区域和其他需要特别保护的区域，禁止建设工业固体废物、建筑垃圾、危险废物集中贮存、利用、处置的设施、场所和生活垃圾填埋场。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百八十二条", "text": "各级人民政府及其有关部门编制国土空间规划和相关规划，应当统筹生活垃圾、建筑垃圾、危险废物等固体废物转运、集中处置等设施、场所建设需求，保障转运、集中处置等设施、场所用地。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百八十三条", "text": "各级人民政府应当加强固体废物污染防治，安排必要的资金用于下列事项： （一）固体废物污染防治的科学技术研究开发； （二）生活垃圾分类； （三）固体废物贮存、利用、集中处置等设施建设； （四）重大传染病疫情等突发事件产生的医疗废物等危险废物应急处置； （五）各级人民政府规定的涉及固体废物污染防治的其他事项。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百八十四条", "text": "收集、贮存、运输、利用、处置危险废物的单位，应当按照规定投保环境污染责任强制保险。环境污染责任强制保险制度的具体实施办法，由国务院金融监督管理机构会同国务院生态环境主管部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百八十五条", "text": "设区的市级人民政府生态环境主管部门会同住房城乡建设、农业农村、卫生健康等有关部门，定期向社会公开固体废物的种类、产生量、处置能力、利用处置状况等信息。 产生、收集、贮存、运输、利用、处置固体废物的单位，应当依法及时向社会公开固体废物污染防治信息，接受社会监督。 利用、处置固体废物的单位，应当依法向公众开放设施、场所，提高公众生态环境保护意识和参与程度。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百八十六条", "text": "固体废物污染海洋的防治和放射性固体废物污染的防治不适用本分编。 液态废物污染的防治适用本分编，但是排入水体的废水污染的防治不适用本分编。 第二十章 工业固体废物污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百八十七条", "text": "国务院生态环境主管部门会同国务院发展改革、工业和信息化等有关部门对工业固体废物对公众健康、生态环境的危害和影响程度等作出界定，制定防治工业固体废物污染的技术政策，组织推广先进的防治工业固体废物污染的生产工艺和设备。 本法所称工业固体废物，是指在工业生产活动中产生的固体废物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百八十八条", "text": "国务院工业和信息化主管部门会同有关部门组织研究开发、推广减少工业固体废物产生量和降低工业固体废物危害性的生产工艺和设备，制定公布限期淘汰产生严重污染环境的工业固体废物的落后生产工艺、设备的名录。 生产者、进口者、销售者、使用者应当在国务院工业和信息化主管部门会同有关部门规定的期限内停止生产、进口、销售、使用列入前款规定名录中的设备。生产工艺的采用者应当在国务院工业和信息化主管部门会同有关部门规定的期限内停止采用列入前款规定名录中的工艺。 列入限期淘汰名录被淘汰的设备，不得转让给他人使用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百八十九条", "text": "产生工业固体废物的单位应当建立健全工业固体废物产生、收集、贮存、运输、利用、处置全过程的污染防治责任制度，建立工业固体废物管理台账，如实记录产生工业固体废物的种类、数量、流向、贮存、利用、处置等信息，实现工业固体废物可追溯、可查询，并采取防治工业固体废物污染的措施。 禁止向生活垃圾收集设施中投放工业固体废物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百九十条", "text": "产生工业固体废物的单位委托他人运输、利用、处置工业固体废物的，应当对受托方的主体资格和技术能力进行核实，依法签订书面合同，在合同中约定污染防治要求。 受托方运输、利用、处置工业固体废物，应当依照法律法规规定和合同约定履行污染防治要求，并将运输、利用、处置情况告知产生工业固体废物的单位。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百九十一条", "text": "实行排污许可管理的产生工业固体废物的单位的排污许可证中应当记载工业固体废物的贮存、利用、处置要求等信息。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百九十二条", "text": "产生工业固体废物的单位应当向所在地生态环境主管部门提供工业固体废物的种类、数量、流向、贮存、利用、处置等有关资料，以及减少工业固体废物产生、促进综合利用的具体措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百九十三条", "text": "产生、贮存、利用、处置工业固体废物的单位应当按照国家规定，对工业固体废物进行检测、监测，并按照分类管理要求采取必要措施，防止工业固体废物污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百九十四条", "text": "产生工业固体废物的单位应当根据经济、技术条件对工业固体废物加以利用；对暂时不利用或者不能利用的，应当按照国务院生态环境等有关部门的规定建设贮存设施、场所，安全分类存放，或者采取无害化处置措施。贮存工业固体废物应当采取符合国家生态环境保护标准的防护措施。 建设工业固体废物贮存、处置的设施、场所，应当符合国家生态环境保护标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百九十五条", "text": "产生工业固体废物的单位终止的，应当在终止前对工业固体废物的贮存、处置的设施、场所采取污染防治措施，并对未处置的工业固体废物作出妥善处置，防止污染环境。 产生工业固体废物的单位发生变更的，变更后的单位应当按照国家有关生态环境保护的规定对未处置的工业固体废物及其贮存、处置的设施、场所进行安全处置或者采取有效措施保证该设施、场所安全运行。变更前当事人对工业固体废物及其贮存、处置的设施、场所的污染防治责任另有约定的，从其约定。但是，不得免除当事人的污染防治义务。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百九十六条", "text": "矿产资源的勘查、开采，应当采用有利于保护生态环境和防止固体废物污染的勘查、开采方法和工艺技术，减少尾矿、煤矸石、废石等矿业固体废物的产生量和贮存量。 尾矿、煤矸石、废石等矿业固体废物贮存设施停止使用后，矿山企业应当按照国家有关生态环境保护等规定进行封场，防止造成环境污染和生态破坏。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百九十七条", "text": "尾矿贮存设施污染防治实行分级分类管理。 尾矿贮存设施运营、管理单位应当建立环境污染隐患排查治理制度，定期开展环境污染隐患排查，防止造成环境污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百九十八条", "text": "国家鼓励采取先进工艺技术对尾矿、煤矸石、废石等矿业固体废物进行综合利用。 第二十一章 生活垃圾污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第四百九十九条", "text": "国家推行生活垃圾分类制度。 生活垃圾分类坚持政府推动、全民参与、城乡统筹、因地制宜、简便易行的原则。 本法所称生活垃圾，是指在日常生活中或者为日常生活提供服务的活动中产生的固体废物，以及法律、行政法规规定视为生活垃圾的固体废物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百条", "text": "县级以上地方人民政府应当加快建立健全分类投放、分类收集、分类运输、分类处理的生活垃圾管理系统，实现生活垃圾分类制度有效覆盖。 县级以上地方人民政府应当建立健全生活垃圾分类工作协调机制，加强和统筹生活垃圾分类管理能力建设。 各级人民政府及其有关部门应当组织开展生活垃圾分类宣传，教育引导公众养成生活垃圾分类习惯，督促和指导生活垃圾分类工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百零一条", "text": "县级以上地方人民政府有关部门应当在各自职责范围内加强产品生产和流通过程管理，避免过度包装，组织净菜上市，减少生活垃圾的产生量。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百零二条", "text": "县级以上人民政府应当统筹安排建设城乡生活垃圾收集、运输、处理设施、场所，确定设施、场所位置，提高生活垃圾的综合利用和无害化处置水平，促进生活垃圾收集、处理的产业化发展，逐步建立健全生活垃圾污染防治的社会服务体系。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百零三条", "text": "地方各级人民政府应当加强农村生活垃圾污染的防治，保护和改善农村人居环境。 国家鼓励农村生活垃圾源头减量。城乡结合部、人口密集的农村地区和其他有条件的地方，应当建立城乡一体的生活垃圾管理系统；其他农村地区应当积极探索生活垃圾管理模式，因地制宜，就近就地利用或者妥善处理生活垃圾。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百零四条", "text": "设区的市级以上人民政府环境卫生主管部门应当制定生活垃圾清扫、收集、贮存、运输和处理设施、场所建设运行规范，公布生活垃圾分类指导目录，加强监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百零五条", "text": "县级以上地方人民政府环境卫生等有关部门应当在各自职责范围内组织对城乡生活垃圾进行清扫、收集、运输和处理，可以通过招标等方式选择具备条件的单位从事生活垃圾的清扫、收集、运输和处理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百零六条", "text": "产生生活垃圾的单位、家庭和个人应当依法履行生活垃圾源头减量和分类投放义务，承担生活垃圾产生者责任。 任何单位和个人都应当依法在指定的地点分类投放生活垃圾。禁止随意倾倒、堆放、丢弃、抛撒、遗撒或者焚烧生活垃圾。 机关、事业单位等应当在生活垃圾分类工作中起示范带头作用。 已经分类投放的生活垃圾，应当按照规定分类收集、分类运输、分类处理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百零七条", "text": "清扫、收集、运输、处理城乡生活垃圾，应当遵守国家有关生态环境保护和环境卫生管理的规定，防止污染环境。 从生活垃圾中分类并集中收集的有害垃圾，属于危险废物的，应当按照危险废物管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百零八条", "text": "从事公共交通运输的经营单位，应当及时清扫、收集运输过程中产生的生活垃圾。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百零九条", "text": "农贸市场、农产品批发市场等应当加强环境卫生管理，保持环境卫生清洁，对所产生的垃圾及时清扫、分类收集、妥善处理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百一十条", "text": "从事城市新区开发、旧区改建和住宅小区开发建设、村镇建设的单位，以及机场、码头、车站、公园、商场、体育场馆等公共设施、场所的经营管理单位，应当按照国家有关环境卫生的规定，配套建设生活垃圾收集设施。 县级以上地方人民政府应当统筹生活垃圾公共转运、处理设施与前款规定的收集设施的有效衔接，并加强生活垃圾分类收运体系和再生资源回收体系在规划、建设、运营等方面的融合。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百一十一条", "text": "从生活垃圾中回收的物质应当按照国家规定的用途、标准使用，不得用于生产可能危害人体健康的产品。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百一十二条", "text": "建设生活垃圾处理设施、场所，应当符合国务院生态环境主管部门和国务院住房城乡建设主管部门规定的生态环境保护和环境卫生标准。 鼓励相邻地区统筹生活垃圾处理设施建设，促进生活垃圾处理设施跨行政区域共建共享。 禁止擅自关闭、闲置或者拆除生活垃圾处理设施、场所；确有必要关闭、闲置或者拆除的，应当经所在地设区的市、县级人民政府环境卫生主管部门商所在地生态环境主管部门同意后核准，并采取防止污染环境的措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百一十三条", "text": "生活垃圾处理单位应当按照国家规定，安装使用监测设备，实时监测污染物的排放情况，将污染排放数据实时向社会公开。监测设备应当与所在地生态环境主管部门的监控设备联网。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百一十四条", "text": "县级以上地方人民政府环境卫生主管部门负责组织开展厨余垃圾资源化、无害化处理工作。 产生、收集厨余垃圾的单位和其他生产经营者，应当将厨余垃圾交由具备相应资质条件的单位进行无害化处理。 禁止畜禽养殖场利用未经无害化处理的厨余垃圾饲喂畜禽。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百一十五条", "text": "县级以上地方人民政府应当按照产生者付费原则，建立健全生活垃圾处理收费制度。 县级以上地方人民政府制定生活垃圾处理收费标准，应当根据本地实际，结合生活垃圾分类情况，体现分类计价、计量收费等差别化管理，并充分征求公众意见。生活垃圾处理收费标准应当及时公布。 生活垃圾处理费应当专项用于生活垃圾的收集、运输和处理等，不得挪作他用。 第二十二章 建筑垃圾、农业固体废物等污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百一十六条", "text": "县级以上地方人民政府应当加强建筑垃圾污染的防治，建立健全建筑垃圾分类处理制度。 本法所称建筑垃圾，是指建设单位、施工单位新建、改建、扩建和拆除各类建筑物、构筑物、管网等，以及居民装饰装修房屋过程中产生的弃土、弃料和其他固体废物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百一十七条", "text": "建筑工程应当采用有利于保护生态环境的建筑设计方案、建筑材料和装修材料、建筑构配件及设备，减少建筑垃圾的产生。 建筑材料和装修材料应当符合国家标准。禁止生产、销售或者使用有毒有害物质超过国家标准的建筑材料和装修材料。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百一十八条", "text": "县级以上地方人民政府环境卫生主管部门负责建筑垃圾污染防治工作，建立健全建筑垃圾全过程管理制度，按照规定实行联单管理，规范建筑垃圾产生、收集、贮存、运输、利用、处置行为，推进综合利用，加强建筑垃圾处置等设施、场所建设，保障处置安全，防止污染环境。建筑垃圾管理的具体办法由国务院住房城乡建设主管部门制定。 任何单位和个人不得擅自倾倒、堆放、丢弃、抛撒、遗撒或者焚烧建筑垃圾。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百一十九条", "text": "建设单位应当按照规定将建筑垃圾污染防治费用列入工程造价，在施工合同中明确工程施工单位的建筑垃圾污染防治责任。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百二十条", "text": "工程施工单位应当编制建筑垃圾处理方案，采取污染防治措施，并报县级以上地方人民政府环境卫生主管部门备案。 工程施工单位应当及时清运工程施工过程中产生的建筑垃圾等固体废物，并按照环境卫生主管部门的规定进行利用或者处置。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百二十一条", "text": "县级以上人民政府农业农村主管部门负责指导农业固体废物回收利用体系建设，鼓励和引导有关单位和其他生产经营者依法收集、贮存、运输、利用、处置农业固体废物，加强监督管理，防止污染环境。 本法所称农业固体废物，是指在农业生产活动中产生的固体废物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百二十二条", "text": "产生农业固体废物的单位和其他生产经营者，应当采取回收利用和其他防止污染环境的措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百二十三条", "text": "退役风电机组叶片、退役光伏组件、废旧动力电池等产品的拆解、处置应当加强污染防治，按照规定开展精细化、无害化拆解、处置。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百二十四条", "text": "禁止将报废机动车船等交由不符合规定条件的企业或者个人回收、拆解。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百二十五条", "text": "县级以上人民政府城镇排水主管部门依法将污泥处理处置设施纳入城镇排水与污水处理规划，推动同步建设污泥处理处置设施与污水处理设施，鼓励协同处理处置，污水处理费征收标准和补偿范围应当覆盖污泥处理处置成本和污水处理设施正常运营成本。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百二十六条", "text": "禁止擅自倾倒、堆放、丢弃、抛撒、遗撒或者焚烧城镇污水处理设施产生的污泥和处理处置后的污泥。 从事水体清淤疏浚应当按照国家规定处理清淤疏浚过程中产生的底泥，防止污染环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百二十七条", "text": "各级各类实验室及其设立单位应当加强对实验室产生的固体废物的管理，依法收集、贮存、运输、利用、处置实验室固体废物。实验室固体废物属于危险废物的，应当按照危险废物管理。 第二十三章 危险废物污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百二十八条", "text": "本法所称危险废物，是指列入国家危险废物名录或者根据国家规定的危险废物鉴别标准和鉴别方法认定的具有危险特性的固体废物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百二十九条", "text": "国务院生态环境主管部门会同有关部门制定国家危险废物名录，规定统一的危险废物鉴别标准、鉴别方法、鉴别程序、识别标志和鉴别单位管理要求。国家危险废物名录应当动态调整。 国务院生态环境主管部门根据危险废物的危害特性和产生数量，科学评估其环境风险，实施分级分类管理，建立健全全过程信息化监管体系，并通过信息化手段管理、共享危险废物转移数据和信息。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百三十条", "text": "省、自治区、直辖市人民政府应当组织有关部门编制危险废物集中处置设施、场所的建设规划，科学评估危险废物处置需求，合理布局危险废物集中处置设施、场所，确保本行政区域的危险废物得到妥善处置。 编制危险废物集中处置设施、场所的建设规划，应当征求有关行业协会、企业事业单位、专家和公众等方面的意见。 相邻省、自治区、直辖市之间可以开展区域合作，统筹建设区域性危险废物集中处置设施、场所。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百三十一条", "text": "对危险废物的容器和包装物以及收集、贮存、运输、利用、处置危险废物的设施、场所，应当按照规定设置危险废物识别标志。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百三十二条", "text": "产生危险废物的单位，应当按照国家规定制定危险废物管理计划；建立危险废物管理台账，如实记录有关信息，并通过国家危险废物信息管理系统向所在地生态环境主管部门申报危险废物的种类、产生量、流向、贮存、利用、处置等有关资料。 前款所称危险废物管理计划应当包括减少危险废物产生量和降低危险废物危害性的措施以及危险废物贮存、利用、处置措施。危险废物管理计划应当报产生危险废物的单位所在地生态环境主管部门备案。 产生危险废物的单位已经取得排污许可证的，执行排污许可管理制度的规定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百三十三条", "text": "产生危险废物的单位，应当按照国家规定和生态环境保护标准的要求贮存、利用、处置危险废物。 任何单位和个人不得擅自倾倒、堆放、丢弃、抛撒、遗撒或者焚烧危险废物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百三十四条", "text": "从事收集、贮存、利用、处置危险废物经营活动的单位，应当按照国家规定取得许可证。许可证的具体管理办法由国务院制定。 禁止无许可证或者不按照许可证的要求从事危险废物收集、贮存、利用、处置的经营活动。 禁止将危险废物提供或者委托给无许可证的单位和个人从事收集、贮存、利用、处置活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百三十五条", "text": "收集、贮存危险废物，应当按照危险废物特性分类进行。禁止混合收集、贮存、运输或者处置性质不相容而未经安全性处置的危险废物。 贮存危险废物应当采取符合国家生态环境保护标准的防护措施。禁止将危险废物混入非危险废物中贮存。 从事收集、贮存、利用、处置危险废物经营活动的单位，贮存危险废物不得超过一年；确需延长期限的，应当报经颁发许可证的生态环境主管部门批准；法律、行政法规另有规定的除外。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百三十六条", "text": "转移危险废物的，应当按照国家规定填写、运行危险废物电子或者纸质转移联单。 跨省、自治区、直辖市转移危险废物的，应当向危险废物移出地省级人民政府生态环境主管部门申请。移出地省级人民政府生态环境主管部门应当及时商经接受地省级人民政府生态环境主管部门同意后，在规定期限内批准转移该危险废物，并将批准信息通报相关省级人民政府生态环境主管部门和交通运输主管部门。未经批准的，不得转移。 危险废物转移管理应当全程管控、提高效率，具体办法由国务院生态环境主管部门会同国务院交通运输主管部门、公安部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百三十七条", "text": "运输危险废物，应当采取防止污染环境的措施，并遵守国家有关危险货物运输管理的规定。 禁止将危险废物与旅客在同一运输工具上载运。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百三十八条", "text": "收集、贮存、运输、利用、处置危险废物的场所、设施、设备和容器、包装物及其他物品转作他用时，应当按照国家规定经过消除污染处理，方可使用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百三十九条", "text": "产生、收集、贮存、运输、利用、处置危险废物的单位，应当依法制定意外事故的防范措施和应急预案，并报所在地生态环境主管部门和其他负有固体废物污染防治监督管理职责的部门备案；生态环境主管部门和其他负有固体废物污染防治监督管理职责的部门应当在各自职责范围内进行监督检查。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百四十条", "text": "因发生事故或者其他突发性事件，造成危险废物严重污染的单位，应当立即采取有效措施消除或者减轻污染危害，及时通报可能受到污染危害者，并向所在地生态环境主管部门和有关部门报告，接受调查处理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百四十一条", "text": "在发生或者有证据证明可能发生危险废物严重污染、威胁居民生命财产安全时，生态环境主管部门和其他负有固体废物污染防治监督管理职责的部门应当立即向本级人民政府和上一级人民政府有关部门报告，由人民政府采取防止或者减轻危害的有效措施。有关人民政府可以根据实际需要责令停止导致或者可能导致环境污染事故的作业。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百四十二条", "text": "重点危险废物集中处置设施、场所退役前，运营单位应当按照国家规定对设施、场所采取污染防治措施。退役的费用应当预提，列入投资概算或者生产成本，专门用于重点危险废物集中处置设施、场所的退役。具体提取和管理办法，由国务院财政部门、价格主管部门会同国务院生态环境主管部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百四十三条", "text": "禁止经中华人民共和国过境转移危险废物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百四十四条", "text": "医疗废物按照国家危险废物名录管理。县级以上地方人民政府应当加强医疗废物集中处置能力建设。 卫生健康、生态环境等有关部门应当在各自职责范围内加强对医疗废物收集、贮存、运输、处置的监督管理，防止危害公众健康、造成环境污染。 医疗卫生机构应当依法分类收集本单位产生的医疗废物，交由医疗废物集中处置单位处置。医疗废物集中处置单位应当及时收集、运输和处置医疗废物。 医疗卫生机构和医疗废物集中处置单位，应当采取有效措施，防止医疗废物流失、泄漏、渗漏、扩散。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百四十五条", "text": "重大传染病疫情等突发事件发生时，县级以上人民政府应当统筹协调医疗废物等危险废物收集、贮存、运输、处置等工作，保障所需的车辆、场地、处置设施和防护物资。卫生健康、生态环境、环境卫生、交通运输等有关部门应当协同配合，依法履行应急处置职责。 第七分编 噪声污染防治 第二十四章 一般规定"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百四十六条", "text": "本分编适用于噪声污染的防治。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百四十七条", "text": "本法所称噪声污染，是指在工业生产、建筑施工、交通运输和社会生活中超过噪声排放标准或者未依法采取防控措施产生噪声，并干扰他人正常生活、工作和学习的现象。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百四十八条", "text": "国务院生态环境主管部门对全国噪声污染防治工作实施统一监督管理。地方人民政府生态环境主管部门对本行政区域噪声污染防治工作实施统一监督管理。 县级以上人民政府住房城乡建设、公安、交通运输、铁路监督管理、民用航空、海事等有关部门在各自职责范围内对建筑施工、交通运输和社会生活噪声污染防治工作实施监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百四十九条", "text": "基层群众性自治组织协助地方人民政府及其有关部门做好噪声污染防治工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百五十条", "text": "排放噪声的单位和公共场所管理者，应当建立噪声污染防治责任制度，明确负责人和相关人员的责任。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百五十一条", "text": "各级人民政府及其有关部门编制国土空间规划和相关规划，应当充分考虑城乡区域开发、改造和建设项目产生的噪声对周围生活环境的影响，统筹规划，合理安排土地用途和建设布局，防止、减轻噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百五十二条", "text": "未达到国家声环境质量标准的地区所在设区的市、县级人民政府，应当及时编制声环境质量改善规划及其实施方案，采取有效措施，改善声环境质量。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百五十三条", "text": "县级以上地方人民政府根据国家声环境质量标准和国土空间规划以及用地现状，划定本行政区域各类声环境质量标准的适用区域；将以用于居住、科学研究、医疗卫生、文化教育、机关团体办公、社会福利等的建筑物为主的区域，划定为噪声敏感建筑物集中区域，加强噪声污染防治。 声环境质量标准适用区域范围和噪声敏感建筑物集中区域范围应当及时公布。 本法所称噪声敏感建筑物，是指用于居住、科学研究、医疗卫生、文化教育、机关团体办公、社会福利等需要保持安静的建筑物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百五十四条", "text": "国务院生态环境主管部门根据国家声环境质量标准和国家经济、技术条件，制定国家环境振动控制标准。 产生振动，应当符合环境振动控制标准和有关法律、法规、规章的要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百五十五条", "text": "国务院标准化主管部门会同国务院发展改革、生态环境、工业和信息化、住房城乡建设、交通运输、铁路监督管理、民用航空、海事等有关部门，对可能产生噪声污染的工业设备、施工机械、机动车、铁路机车车辆、城市轨道交通车辆、民用航空器、机动船舶、电气电子产品、建筑附属设备等产品，根据噪声污染防治的要求和国家经济、技术条件，在其技术规范或者产品质量标准中规定噪声限值。 前款规定的产品使用时产生噪声的限值，应当在有关技术文件中注明。禁止生产、进口或者销售不符合噪声限值的产品。 县级以上人民政府市场监督管理等有关部门应当在各自职责范围内对生产、销售的有噪声限值的产品进行监督抽查，对电梯等特种设备使用时发出的噪声进行监督抽测，生态环境主管部门予以配合。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百五十六条", "text": "国务院生态环境主管部门会同有关部门组织开展声环境质量监测，推进监测自动化。地方人民政府生态环境主管部门会同有关部门按照规定设置本行政区域的声环境质量监测站点，组织开展本行政区域的声环境质量监测。 地方人民政府生态环境等有关部门应当在各自职责范围内加强对噪声敏感建筑物周边等重点区域噪声排放情况的调查、监测。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百五十七条", "text": "确定建设布局，应当根据国家声环境质量标准和民用建筑隔声设计相关标准，合理划定建筑物与交通干线等的防噪声距离，并提出相应的规划设计要求。 前款所称交通干线，包括铁路、高速公路、一级公路、二级公路、城市快速路、城市主干路、城市次干路、城市轨道交通线路、内河高等级航道。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百五十八条", "text": "建设噪声敏感建筑物，应当符合民用建筑隔声设计相关标准的要求，不符合标准要求的，不得通过验收、交付使用；在交通干线两侧、工业企业周边等地方建设噪声敏感建筑物，还应当按照规定间隔一定距离，并采取减少振动、降低噪声的措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百五十九条", "text": "国家鼓励、支持低噪声工艺和设备的研究开发和推广应用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百六十条", "text": "国家鼓励开展宁静小区、静音车厢等宁静区域创建活动，共同维护生活环境和谐安宁。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百六十一条", "text": "在举行中等学校招生考试、高等学校招生统一考试等特殊活动期间，地方人民政府或者其指定的部门可以对可能产生噪声影响的活动，作出时间和区域的限制性规定，并提前向社会公告。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百六十二条", "text": "排放噪声造成严重污染，被责令改正拒不改正的，生态环境主管部门和其他负有噪声污染防治监督管理职责的部门，可以依法查封、扣押排放噪声的场所、设施、设备、工具、物品。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百六十三条", "text": "因从事本职生产经营工作受到噪声危害的防治，适用职业病防治法律的有关规定。 第二十五章 工业噪声污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百六十四条", "text": "本法所称工业噪声，是指在工业生产活动中产生的干扰周围生活环境的声音。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百六十五条", "text": "工业企业选址应当符合国土空间规划以及相关规划要求，县级以上地方人民政府应当按照规划要求优化工业企业布局，防止工业噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百六十六条", "text": "在噪声敏感建筑物集中区域，禁止新建排放噪声的工业企业，改建、扩建工业企业的，应当采取有效措施防止工业噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百六十七条", "text": "排放工业噪声的企业事业单位和其他生产经营者，应当采取有效措施，减少振动、降低噪声。 第二十六章 建筑施工噪声污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百六十八条", "text": "本法所称建筑施工噪声，是指在建筑施工过程中产生的干扰周围生活环境的声音。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百六十九条", "text": "建设单位应当按照规定将噪声污染防治费用列入工程造价，在施工合同中明确施工单位的噪声污染防治责任。 施工单位应当按照规定制定噪声污染防治实施方案，采取有效措施，减少振动、降低噪声。建设单位应当监督施工单位落实噪声污染防治实施方案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百七十条", "text": "在噪声敏感建筑物集中区域施工作业或者因施工作业可能造成严重污染的，应当优先使用低噪声施工工艺和设备。 国务院工业和信息化主管部门会同国务院生态环境、住房城乡建设、市场监督管理等有关部门，制定公布低噪声施工设备指导名录并适时更新。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百七十一条", "text": "在噪声敏感建筑物集中区域施工作业或者因施工作业可能造成严重污染的，建设单位应当按照国家规定，设置噪声自动监测系统，与监督管理部门联网，保存原始监测记录。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百七十二条", "text": "在噪声敏感建筑物集中区域禁止夜间进行产生噪声的施工作业，但是抢修、抢险施工作业，因生产工艺要求或者其他特殊需要必须连续施工作业的除外。 因特殊需要必须连续施工作业的，应当取得地方人民政府住房城乡建设主管部门、生态环境主管部门或者地方人民政府指定的部门的证明，并在施工现场显著位置公示或者以其他方式公告附近居民。 本条第一款所称夜间，是指晚上十点至次日早晨六点之间的期间，设区的市级以上人民政府可以另行规定本行政区域夜间的起止时间，夜间时段长度为八小时。 第二十七章 交通运输噪声污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百七十三条", "text": "本法所称交通运输噪声，是指机动车、铁路机车车辆、城市轨道交通车辆、机动船舶、航空器等交通运输工具在运行时产生的干扰周围生活环境的声音。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百七十四条", "text": "各级人民政府及其有关部门编制国土空间规划和交通运输等相关规划，应当综合考虑公路、城市道路、铁路、城市轨道交通线路、水路、港口和民用机场及其起降航线对周围声环境的影响。 新建公路、铁路线路选线设计，应当尽量避让噪声敏感建筑物集中区域。 新建民用机场选址与噪声敏感建筑物集中区域的距离应当符合标准的要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百七十五条", "text": "制定交通基础设施工程技术规范，应当明确噪声污染防治要求。 新建、改建、扩建经过噪声敏感建筑物集中区域的高速公路、城市高架、铁路和城市轨道交通线路等的，建设单位应当在可能造成噪声污染的重点路段设置声屏障或者采取其他减少振动、降低噪声的措施，符合相关交通基础设施工程技术规范和标准的要求。 建设单位违反前款规定的，由县级以上人民政府指定的部门责令制定、实施治理方案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百七十六条", "text": "机动车的消声器和喇叭应当符合国家规定。禁止驾驶拆除或者损坏消声器、加装排气管等擅自改装的机动车以轰鸣、疾驶等方式造成噪声污染。 使用机动车音响器材，应当控制音量，防止噪声污染。 机动车应当加强维修和保养，保持性能良好，防止噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百七十七条", "text": "机动车、铁路机车车辆、城市轨道交通车辆、机动船舶等交通运输工具运行时，应当按照规定使用喇叭等声响装置。 警车、消防车、工程救险车、救护车等机动车安装、使用警报器，应当符合国务院公安等有关部门的规定；非执行紧急任务，不得使用警报器。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百七十八条", "text": "地方人民政府生态环境主管部门会同公安机关根据噪声污染防治的需要，可以划定禁止机动车行驶和使用喇叭等声响装置的路段和时间，向社会公告，并由公安机关交通管理部门依法设置相关标志、标线。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百七十九条", "text": "在车站、铁路站场、港口等地方指挥作业时使用广播喇叭的，应当控制音量，减轻噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百八十条", "text": "公路养护管理单位、城市道路养护维修单位应当加强对公路、城市道路的维护和保养，保证减少振动、降低噪声设施正常运行。 城市轨道交通运营单位、铁路运输企业应当加强对城市轨道交通线路和城市轨道交通车辆、铁路线路和铁路机车车辆的维护和保养，保证减少振动、降低噪声设施正常运行，并按照国家规定进行监测，保存原始监测记录。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百八十一条", "text": "民用机场所在地人民政府，应当根据生态环境影响评价以及监测结果确定的民用航空器噪声对机场周围生活环境产生影响的范围和程度，划定噪声敏感建筑物禁止建设区域和限制建设区域，并实施控制。 在禁止建设区域禁止新建与航空无关的噪声敏感建筑物。 在限制建设区域确需建设噪声敏感建筑物的，建设单位应当对噪声敏感建筑物进行建筑隔声设计，符合民用建筑隔声设计相关标准的要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百八十二条", "text": "民用航空器应当符合国务院民用航空主管部门规定的适航标准中的有关噪声要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百八十三条", "text": "民用机场管理机构负责机场起降航空器噪声的管理，会同航空运输企业、通用航空企业、空中交通管理部门等单位，采取低噪声飞行程序、起降跑道优化、运行架次和时段控制、高噪声航空器运行限制或者周围噪声敏感建筑物隔声降噪等措施，防止、减轻民用航空器噪声污染。 民用机场管理机构应当按照国家规定，对机场周围民用航空器噪声进行监测，保存原始监测记录，监测结果定期向民用航空主管部门、生态环境主管部门报告。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百八十四条", "text": "因公路、城市道路和城市轨道交通运行排放噪声造成严重污染的，设区的市、县级人民政府应当组织有关部门和其他有关单位对噪声污染情况进行调查评估和责任认定，制定噪声污染综合治理方案。 噪声污染责任主体应当按照噪声污染综合治理方案的要求采取管理或者工程措施，减轻噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百八十五条", "text": "因铁路运行排放噪声造成严重污染的，铁路运输企业和设区的市、县级人民政府应当对噪声污染情况进行调查，制定噪声污染综合治理方案。 铁路运输企业和设区的市、县级人民政府有关部门和其他有关单位应当按照噪声污染综合治理方案的要求采取有效措施，减轻噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百八十六条", "text": "因民用航空器起降排放噪声造成严重污染的，民用机场所在地人民政府应当组织有关部门和其他有关单位对噪声污染情况进行调查，综合考虑经济、技术和管理措施，制定噪声污染综合治理方案。 民用机场管理机构、地方各级人民政府和其他有关单位应当按照噪声污染综合治理方案的要求采取有效措施，减轻噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百八十七条", "text": "制定噪声污染综合治理方案，应当征求有关专家、公众等方面的意见。 第二十八章 社会生活噪声污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百八十八条", "text": "本法所称社会生活噪声，是指人为活动产生的除工业噪声、建筑施工噪声和交通运输噪声外的干扰周围生活环境的声音。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百八十九条", "text": "全社会应当增强噪声污染防治意识，自觉减少社会生活噪声排放，积极开展噪声污染防治活动，形成人人有责、人人参与、人人受益的良好噪声污染防治氛围，共同维护生活环境和谐安宁。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百九十条", "text": "文化娱乐、体育、餐饮等场所的经营管理者应当采取有效措施，防止、减轻噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百九十一条", "text": "使用空调器、冷却塔、水泵、油烟净化器、风机、发电机、变压器、锅炉、装卸设备等可能产生社会生活噪声污染的设备、设施的企业事业单位和其他经营管理者等，应当采取优化布局、集中排放等措施，防止、减轻噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百九十二条", "text": "禁止在商业经营活动中使用高音广播喇叭或者采用其他持续反复发出高噪声的方法进行广告宣传。 对商业经营活动中产生的其他噪声，经营者应当采取有效措施，防止噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百九十三条", "text": "禁止在噪声敏感建筑物集中区域使用高音广播喇叭，但是紧急情况以及地方人民政府规定的特殊情形除外。 在街道、广场、公园等公共场所组织或者开展娱乐、健身等活动，应当遵守公共场所管理者有关活动区域、时段、音量等规定，采取有效措施，防止噪声污染；不得违反规定使用音响器材产生过大音量。 公共场所管理者应当合理规定娱乐、健身等活动的区域、时段、音量，可以采取设置噪声自动监测和显示设施等措施加强管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百九十四条", "text": "家庭及其成员应当培养形成减少噪声产生的良好习惯，乘坐公共交通工具、饲养宠物和其他日常活动尽量避免产生噪声对周围人员造成干扰，互谅互让解决噪声纠纷，共同维护声环境质量。 使用家用电器、乐器或者进行其他家庭场所活动，应当控制音量或者采取其他有效措施，防止噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百九十五条", "text": "对已竣工交付使用的住宅楼、商铺、办公楼等建筑物进行室内装修活动，应当按照规定限定作业时间，采取有效措施，防止、减轻噪声污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百九十六条", "text": "新建居民住房的房地产开发经营者应当在销售场所公示住房可能受到噪声影响的情况以及采取或者拟采取的防治措施，并纳入买卖合同。 新建居民住房的房地产开发经营者应当在买卖合同中明确住房的共用设施、设备位置和建筑隔声情况。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百九十七条", "text": "居民住宅区安装电梯、水泵、变压器等共用设施、设备的，建设单位应当合理设置，采取减少振动、降低噪声的措施，符合民用建筑隔声设计相关标准的要求。 已建成使用的居民住宅区电梯、水泵、变压器等共用设施、设备由专业运营单位负责维护管理，符合民用建筑隔声设计相关标准的要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百九十八条", "text": "基层群众性自治组织指导业主委员会、物业服务人、业主通过制定管理规约或者其他形式，约定本物业管理区域噪声污染防治要求，由业主共同遵守。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第五百九十九条", "text": "对噪声敏感建筑物集中区域的社会生活噪声扰民行为，基层群众性自治组织、业主委员会、物业服务人应当及时劝阻、调解；劝阻、调解无效的，可以向负有社会生活噪声污染防治监督管理职责的部门或者地方人民政府指定的部门报告或者投诉，接到报告或者投诉的部门应当依法处理。 第八分编 放射性污染防治 第二十九章 一般规定"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百条", "text": "本分编适用于在核设施选址、建造、运行、退役和核技术、铀（钍）矿、伴生放射性矿开发利用过程中发生的放射性污染的防治活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百零一条", "text": "本法所称放射性污染，是指由于人类活动造成物料、人体、场所、环境介质表面或者内部出现超过国家标准的放射性物质或者射线。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百零二条", "text": "放射性污染防治应当坚持严格管理、安全第一，促进核能、核技术的开发与和平利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百零三条", "text": "核设施营运单位，核技术利用单位和其他生产经营者，铀（钍）矿和伴生放射性矿开发利用单位，专门从事放射性废物贮存、处理、处置的单位应当采取有效措施，防止、减少放射性污染，依法对其造成的放射性污染承担责任。 生产、贮存、运输、销售、使用、处置含有放射性物质的物品，应当遵守国家规定，防止污染环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百零四条", "text": "国务院生态环境主管部门对全国放射性污染防治工作实施统一监督管理。 国务院卫生健康等有关部门在各自职责范围内对放射性污染防治工作实施监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百零五条", "text": "国务院生态环境主管部门根据环境安全要求和国家经济、技术条件制定国家放射性污染防治标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百零六条", "text": "含有放射性物质的产品和射线装置，应当符合国家放射性污染防治标准；不符合国家放射性污染防治标准的，不得出厂、销售。 使用伴生放射性矿渣和含有天然放射性物质的石材等，应当符合国家建筑材料放射性核素控制等标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百零七条", "text": "国务院生态环境主管部门会同有关部门组织监测网络，对放射性污染实施监测管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百零八条", "text": "核设施营运单位，核技术利用单位和其他生产经营者，铀（钍）矿和伴生放射性矿开发利用单位，专门从事放射性废物贮存、处理、处置的单位应当采取安全与防护措施，预防发生可能导致放射性污染的各类事故，避免放射性污染危害。 核设施营运单位，核技术利用单位和其他生产经营者，铀（钍）矿和伴生放射性矿开发利用单位，专门从事放射性废物贮存、处理、处置的单位应当对其工作人员进行放射性安全教育、培训，采取有效的防护安全措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百零九条", "text": "运输放射性物质应当采取有效措施，防止放射性污染。具体办法由国务院制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百一十条", "text": "放射性物质和射线装置应当设置明显的放射性标识和中文警示说明。生产、贮存、销售、使用、处置放射性物质和射线装置的场所，以及运输放射性物质的工具，应当设置明显的放射性标志。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百一十一条", "text": "国家对从事放射性污染防治的专业人员实行资格管理制度，对从事放射性污染监测工作的机构实行资质管理制度。 从事放射性污染监测工作的机构，应当具备下列条件，经国务院生态环境主管部门依法审查合格，取得资质证书后，方可在资质许可范围内从事放射性污染监测工作： （一）有法人资格； （二）有与所开展监测工作相匹配的专业技术人员； （三）有满足相关标准规范要求的工作场所、实验条件、设施、设备； （四）有健全的质量管理体系。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百一十二条", "text": "国务院生态环境等有关部门应当互通信息、密切配合，在各自职责范围内对核设施、核技术利用、铀（钍）矿开发利用中的放射性污染防治进行监督检查。 地方人民政府生态环境等有关部门应当互通信息、密切配合，在各自职责范围内对本行政区域核技术利用、伴生放射性矿开发利用中的放射性污染防治进行监督检查。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百一十三条", "text": "国家建立符合受控热核聚变特点、促进核聚变应用的放射性污染防治制度，对聚变燃料、聚变装置（设施）放射性污染防治实行分级分类管理。聚变装置（设施）建造等应当依法进行生态环境影响评价。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百一十四条", "text": "在职业活动中接触放射性物质造成的职业病的防治，适用职业病防治法律的有关规定。 第三十章 核设施放射性污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百一十五条", "text": "核设施营运单位进行核设施选址、建造、运行、退役等活动，应当依法申请核设施安全许可。 本法所称核设施，是指核电厂、核热电厂、核供汽供热厂等核动力厂及装置，核动力厂以外的研究堆、实验堆、临界装置等其他反应堆，核燃料生产、加工、贮存和后处理设施等核燃料循环设施，以及上述设施产生的放射性废物的贮存、处理、处置设施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百一十六条", "text": "核设施营运单位应当按照国务院生态环境主管部门的规定在核设施建造、退役，以及选址、运行等环节开展生态环境影响评价。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百一十七条", "text": "进口核设施，应当符合国家放射性污染防治标准；没有相应的国家放射性污染防治标准的，采用国务院生态环境主管部门指定的相关标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百一十八条", "text": "省、自治区、直辖市人民政府应当依法在核动力厂等重要核设施周围划定规划限制区。禁止在规划限制区内建设可能威胁核设施安全的易燃、易爆、腐蚀性物品的生产、贮存设施以及人口密集场所。规划限制区的划定和管理办法，由国务院制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百一十九条", "text": "核设施营运单位应当对核设施周边环境中所含的放射性核素的种类、浓度以及核设施流出物中的放射性核素总量实施监测，并定期向国务院生态环境主管部门和所在地省级人民政府生态环境主管部门报告监测结果。 国务院生态环境主管部门负责对核动力厂等重要核设施实施监督性监测，并根据实际需要对其他核设施的流出物实施监测。监督性监测系统的建设、运行、维护费用由财政预算安排。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百二十条", "text": "国家建立健全核事故应急制度。 国家设立核事故应急协调委员会，组织、协调全国的核事故应急管理工作。国家核事故应急协调委员会成员单位，省、自治区、直辖市人民政府，核设施营运单位，应当依法做好核事故应急工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百二十一条", "text": "核设施营运单位应当制定核设施退役计划。 核设施的退役费用和放射性废物处置费用应当预提，列入投资概算或者生产成本，专门用于核设施退役、放射性废物处置。核设施的退役费用和放射性废物处置费用的提取和管理办法，由国务院财政部门、价格主管部门会同国务院生态环境主管部门、核工业主管部门和能源主管部门制定。 第三十一章 核技术利用放射性污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百二十二条", "text": "国家加强核技术利用放射性污染防治。国务院生态环境主管部门对可能造成污染的放射性同位素和射线装置实施分级分类管理。 本法所称核技术利用，是指放射性同位素和射线装置在医疗、工业、农业、地质调查、科学研究和教学等领域中的使用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百二十三条", "text": "生产、销售、使用放射性同位素和射线装置的单位和其他生产经营者，应当按照国务院有关放射性同位素与射线装置放射防护的规定取得许可证。未取得许可证的，不得从事放射性同位素和射线装置生产、销售、使用活动。禁止在网络上销售放射性同位素和射线装置。 转让、进出口放射性同位素和射线装置的单位和其他生产经营者以及装备有放射性同位素的仪表的单位和其他生产经营者，应当按照国务院有关放射性同位素与射线装置放射防护的规定办理有关手续。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百二十四条", "text": "生产、销售、使用放射性同位素和射线装置的单位和其他生产经营者，应当在申请许可证前依法取得生态环境影响报告书、生态环境影响报告表批准文件或者已经办理生态环境影响登记表备案手续。 国家建立健全放射性同位素备案制度，具体办法由国务院制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百二十五条", "text": "放射性同位素应当单独存放，不得与易燃、易爆、腐蚀性物品等一起存放，其贮存场所应当采取有效的防火、防盗、防射线泄漏的安全防护措施，并指定专人负责保管。贮存、领取、使用、归还放射性同位素时，应当进行登记、检查，做到账物相符。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百二十六条", "text": "生产、使用放射性同位素和射线装置的单位和其他生产经营者，应当按照国务院生态环境主管部门的规定对其产生的放射性废物进行收集、包装、贮存。 生产放射源的单位和其他生产经营者，应当按照国务院生态环境主管部门的规定回收和利用废旧放射源；使用放射源的单位和其他生产经营者，应当按照国务院生态环境主管部门的规定将废旧放射源交回生产放射源的单位和其他生产经营者或者送交专门从事放射性废物贮存、处理、处置的单位。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百二十七条", "text": "使用对人体健康、生态环境潜在危害程度较高的放射源的场所和生产放射性同位素的场所，以及终结运行后产生放射性污染的射线装置，应当依法实施退役。具体办法由国务院制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百二十八条", "text": "生产、贮存、销售、使用放射源的单位和其他生产经营者，应当建立健全安全保卫制度，指定专人负责，落实安全责任制，制定必要的事故应急措施。发生放射源丢失、被盗和放射性污染事故时，有关单位和个人应当立即采取应急措施，并向公安机关、卫生健康主管部门和生态环境主管部门报告。 公安机关、卫生健康主管部门和生态环境主管部门接到放射源丢失、被盗和放射性污染事故报告后，应当报告本级人民政府，并在各自职责范围内立即组织采取有效措施，防止放射性污染蔓延，减少事故损失。当地人民政府应当及时将有关情况告知公众，并做好事故的调查、处理工作。 第三十二章 铀（钍）矿和伴生放射性矿开发利用放射性污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百二十九条", "text": "开发利用或者关闭铀（钍）矿的单位，应当在开工建设或者办理退役审批手续前编制生态环境影响报告书、生态环境影响报告表，报国务院生态环境主管部门审查批准。 开发利用伴生放射性矿的单位，应当在开工建设或者退役前编制生态环境影响报告书、生态环境影响报告表，报省级以上人民政府生态环境主管部门审查批准。 本法所称伴生放射性矿，是指列入伴生放射性矿开发利用辐射环境管理名录，含有较高水平天然放射性核素浓度的稀土矿、磷酸盐矿等非铀矿。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百三十条", "text": "国务院生态环境主管部门根据矿产资源开发利用中放射性核素对人体健康、生态环境的潜在危害程度，制定伴生放射性矿开发利用辐射环境管理名录，统一规定纳入伴生放射性矿开发利用辐射环境管理的判定方法及标准、矿产类别和工业活动。伴生放射性矿开发利用辐射环境管理名录应当动态调整。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百三十一条", "text": "实行排污许可管理的伴生放射性矿开发利用单位的排污许可证中应当记载排放废液中放射性核素的种类、浓度、排放量，伴生放射性固体废物的类别、物理性状、产生环节、去向，伴生放射性固体废物自行贮存、利用、处置及相关设施等信息。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百三十二条", "text": "铀（钍）矿开发利用单位应当对铀（钍）矿的流出物和周边环境实施监测，并定期向国务院生态环境主管部门和所在地省级人民政府生态环境主管部门报告监测结果。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百三十三条", "text": "对铀（钍）矿和伴生放射性矿开发利用过程中产生的尾矿等放射性固体废物，应当建造尾矿库等设施进行贮存、处置；建造的尾矿库等设施应当符合放射性污染防治的要求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百三十四条", "text": "铀（钍）矿开发利用单位应当制定铀（钍）矿退役计划。铀矿退役和监护费用由国家财政预算安排。 第三十三章 放射性废物污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百三十五条", "text": "核设施营运单位、核技术利用单位和其他生产经营者、铀（钍）矿和伴生放射性矿开发利用单位，应当合理选择和利用原材料，采用先进的生产工艺和设备，尽量减少放射性废物的产生量。 放射性废物是含有放射性核素或者被放射性核素污染，其浓度或者比活度大于国家确定的清洁解控水平，预期不再使用的废弃物。清洁解控的具体办法由国务院生态环境主管部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百三十六条", "text": "排放放射性废气、废液，应当符合国家放射性污染防治的规定和标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百三十七条", "text": "产生放射性废气、废液的单位排放符合国家放射性污染防治的规定和标准的放射性废气、废液，应当向审批生态环境影响报告书、生态环境影响报告表的生态环境主管部门申请放射性核素排放量，并定期报告排放计量结果。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百三十八条", "text": "产生放射性废液的单位，应当按照国家放射性污染防治的规定和标准的要求，对不得排放的放射性废液进行处理或者贮存。不能经净化或者贮存衰变达到国家放射性污染防治的规定和标准要求的放射性废液，应当使其转变为符合处置要求的稳定的、标准化的放射性固体废物。 产生放射性废液的单位，排放符合国家放射性污染防治的规定和标准的放射性废液，应当采用符合国务院生态环境主管部门规定的排放方式。 禁止通过渗井、渗坑、天然裂隙、溶洞或者国家禁止的其他方式排放放射性废液。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百三十九条", "text": "低、中水平放射性固体废物应当按照国家规定实行近地表处置或者中等深度处置。 高水平放射性固体废物实行集中的深地质处置。 禁止在内河水域和海上处置放射性固体废物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百四十条", "text": "国务院核工业主管部门会同国务院生态环境主管部门根据地质条件和放射性固体废物处置的需要，在生态环境影响评价的基础上，依法组织编制放射性固体废物处置场所选址规划，报国务院批准后实施。 有关地方人民政府应当根据放射性固体废物处置场所选址规划，提供放射性固体废物处置场所的建设用地，并采取有效措施支持放射性固体废物的处置。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百四十一条", "text": "产生放射性固体废物的单位，应当按照国务院生态环境主管部门的规定，对其产生的放射性固体废物进行处理后，送交放射性废物处置单位处置，并承担处置费用。 放射性固体废物处置费用收取和使用管理办法，由国务院财政部门、价格主管部门会同国务院生态环境主管部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百四十二条", "text": "设立专门从事放射性废物贮存、处理、处置的单位，应当经国务院生态环境主管部门审查批准，取得许可证；仅贮存、处理本单位产生的放射性废物的，无需取得许可证。具体办法由国务院制定。 禁止无许可证或者不按照许可证的要求专门从事贮存、处理、处置放射性废物的活动。 禁止将放射性废物提供或者委托给无许可证的单位和个人贮存、处理、处置。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百四十三条", "text": "禁止违反法律规定将放射性废物和被放射性污染的物品输入中华人民共和国境内或者经中华人民共和国境内转移。 第九分编 化学物质污染风险管控、电磁辐射和光污染防治 第三十四章 化学物质污染风险管控"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百四十四条", "text": "国家加强化学物质污染风险管控。生产、进口、储存、运输、销售、使用、处置化学物质，应当遵守国家规定，防止污染环境，保障公众健康。具体办法由国务院制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百四十五条", "text": "国家建立持久性有机污染物等新污染物协同治理和环境风险管控体系。国务院生态环境主管部门会同有关部门，分析研判新污染物环境风险管控形势，制定完善相关标准，组织开展调查监测，有效降低新污染物环境风险。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百四十六条", "text": "国务院生态环境主管部门对全国化学物质污染风险管控工作实施统一监督管理。国务院发展改革、工业和信息化、农业农村、商务、卫生健康、海关、市场监督管理、疾病预防控制、药品监督管理等有关部门在各自职责范围内对化学物质污染风险管控工作实施监督管理。 县级以上地方人民政府及其有关部门应当加强化学物质污染风险管控。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百四十七条", "text": "国务院生态环境主管部门根据化学物质的危害特性等定期组织开展化学物质污染信息调查，生产、进口、销售化学物质和使用化学物质生产产品的企业事业单位应当按照规定提供调查所需的化学物质的物理化学性质、数量、用途、危害特性、排放等信息。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百四十八条", "text": "国务院有关部门应当在各自职责范围内按照规定采取有效措施，推动有毒有害化学物质替代。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百四十九条", "text": "国务院生态环境主管部门会同有关部门，组织开展化学物质污染风险评估，制定公布重点管控新污染物清单并适时调整，明确禁止、限制等环境风险管控措施。生产、进口重点管控新污染物清单中化学物质和使用重点管控新污染物清单中化学物质生产产品的，应当遵守上述环境风险管控措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百五十条", "text": "国家实行新化学物质环境管理登记制度。 生产、进口新化学物质的企业事业单位，应当在生产、进口前向国务院生态环境主管部门申请新化学物质环境管理登记。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百五十一条", "text": "禁止无新化学物质环境管理登记证或者不按照新化学物质环境管理登记证的要求生产、进口新化学物质。禁止使用无新化学物质环境管理登记证的企业事业单位生产、进口的新化学物质生产产品。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百五十二条", "text": "化学物质污染防治，本章未作规定的，适用本编其他有关规定。 第三十五章 电磁辐射污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百五十三条", "text": "本法所称电磁辐射污染，是指人类活动产生的超过国家电磁辐射排放标准的非电离辐射。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百五十四条", "text": "国务院生态环境主管部门对全国电磁辐射污染防治工作实施统一监督管理。地方人民政府生态环境主管部门对本行政区域电磁辐射污染防治工作实施统一监督管理。 县级以上人民政府工业和信息化、交通运输、卫生健康、广播电视、气象、能源等有关部门在各自职责范围内对电磁辐射污染防治工作实施监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百五十五条", "text": "各级人民政府及其有关部门编制国土空间规划和相关规划，应当充分考虑电磁辐射设施产生的电磁辐射对周边环境的影响，统筹规划，合理安排土地用途和建设布局，防止、减轻电磁辐射污染。 生态环境主管部门应当加强对电磁辐射排放情况的调查、监测。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百五十六条", "text": "县级以上地方人民政府根据国家电磁环境质量标准和国土空间规划以及用地现状，划定本行政区域各类电磁环境质量标准的适用区域。电磁环境质量标准适用区域范围应当及时公布。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百五十七条", "text": "国务院标准化主管部门会同国务院生态环境、工业和信息化、交通运输、铁路监督管理、民用航空、海事、广播电视、气象、能源、药品监督管理等有关部门，对可能产生电磁辐射污染的工业设备、无线电发射设备、电信设备、机动车、铁路机车车辆、城市轨道交通车辆、导航设备、机动船舶、气象设备、电气电子设备、医疗设备等产品，根据电磁辐射污染防治的要求和国家经济、技术条件，在其技术规范或者产品质量标准中规定电磁辐射限值。 前款规定的产品使用时产生电磁辐射的限值，应当在有关技术文件中注明。禁止生产、进口或者销售不符合电磁辐射限值的产品。 县级以上人民政府市场监督管理等有关部门应当在各自职责范围内对生产、销售的有电磁辐射限值的产品进行监督抽查。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百五十八条", "text": "国家对电磁辐射设施实行分类管理，根据电磁辐射排放水平及其对周边环境的影响，将电磁辐射设施分为一类电磁辐射设施、二类电磁辐射设施、三类电磁辐射设施。具体办法由国务院生态环境主管部门会同有关部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百五十九条", "text": "运行电磁辐射设施的企业事业单位应当优化布局，合理安排电磁辐射设施，采取有效措施，防止、减轻电磁辐射污染。 运行电磁辐射设施的企业事业单位，应当按照国家规定配套建设电磁辐射污染防治设施，并保证污染防治设施正常运行。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百六十条", "text": "运行一类、二类电磁辐射设施的企业事业单位，应当按照国家规定采取发射功率控制、发射方向调整、紧急制动、屏蔽、接地、隔离等电磁辐射污染防治措施，开展自行监测，保存原始监测记录，监测结果定期向生态环境主管部门报告。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百六十一条", "text": "运行一类电磁辐射设施的企业事业单位，应当按照国家规定设置警示标识、采取设置围栏防止公众近距离接触等电磁辐射污染防治措施。新建、改建、扩建一类电磁辐射设施应当避让人口密集区域。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百六十二条", "text": "实行排污许可管理的运行电磁辐射设施的企业事业单位的排污许可证中应当记载电磁辐射设施的工作频率、发射功率、场强以及电磁辐射叠加影响情况等信息。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百六十三条", "text": "使用移动式信息发射设施应当按照国家规定科学合理划定防护距离，采取设置警戒线、警示标识等防护措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百六十四条", "text": "多个电磁辐射设施共用装置的责任主体，应当合理确定电磁辐射设施的数量、位置、功率等，采取有效措施，防止因电磁辐射叠加造成电磁辐射污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百六十五条", "text": "涉及国家安全、重大社会公共利益的电磁辐射设施造成严重电磁辐射污染的，县级以上地方人民政府应当组织有关部门和其他有关单位对电磁辐射污染情况进行调查评估和责任认定，综合考虑经济、技术和管理措施，制定电磁辐射污染综合治理方案。 电磁辐射污染责任主体应当按照电磁辐射污染综合治理方案的要求采取有效措施，减轻电磁辐射污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百六十六条", "text": "在职业活动中接触电磁辐射造成的职业病的防治，适用职业病防治法律的有关规定。 第三十六章 光污染防治"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百六十七条", "text": "本法所称光污染，是指过度、不恰当使用人工照明或者不恰当改变日光的照射条件，造成周围生活环境中人的视觉受到干扰的现象。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百六十八条", "text": "国务院生态环境主管部门对全国光污染防治工作实施统一监督管理。地方人民政府生态环境主管部门对本行政区域光污染防治工作实施统一监督管理。 县级以上人民政府住房城乡建设、交通运输等有关部门在各自职责范围内对光污染防治工作实施监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百六十九条", "text": "各级人民政府及其有关部门编制国土空间规划和相关规划，应当充分考虑城乡区域开发、改造和建设项目可能产生的光污染影响，统筹规划，合理安排土地用途和建设布局，防止、减轻光污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百七十条", "text": "国务院标准化主管部门会同国务院住房城乡建设、生态环境、交通运输等有关部门根据光污染防治的要求和国家经济、技术条件，对照明产品、户外显示产品、交通补光灯、建筑玻璃和材料等在其技术规范或者产品质量标准中规定合理的光限值。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百七十一条", "text": "广告屏、广告牌、灯箱、媒体立面墙、道路、体育场、施工场地等，应当按照国家规定合理设计、安装、使用照明设施，定期保养维护，采取有效措施，防止、减轻光污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百七十二条", "text": "建筑物、构筑物外表面采用玻璃幕墙等建筑材料，应当符合国家规定，合理设计和选材，防止、减轻光污染。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百七十三条", "text": "县级以上地方人民政府应当根据实际情况，实行光污染防治分区管理，加强对需要特殊保护区域的人工照明和日光照射条件的控制。 第三编 生态保护 第一章 一般规定"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百七十四条", "text": "本编适用于生态保护相关活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百七十五条", "text": "国家统筹考虑生态环境要素的复杂性、生态系统的完整性、自然地理单元的连续性、经济社会发展的可持续性，坚持山水林田湖草沙一体化保护和系统治理，提升生态系统多样性、稳定性、持续性，维护生态安全。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百七十六条", "text": "国家根据主体功能区定位，优化生态空间布局，推进国家重点生态功能区、重要生态廊道保护建设，筑牢生态安全屏障。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百七十七条", "text": "国家加强对森林、草原、湿地、海洋、海岛、江河湖泊、荒漠、雪山冰川、耕地等生态系统的保护，坚持自然恢复为主、自然恢复与人工修复相结合，推进实施重要生态系统保护和修复重大工程，培育健康稳定、功能完备的生态系统，增强各类生态系统的服务功能。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百七十八条", "text": "国家加强自然资源的保护，坚持节约集约利用，统筹资源保护与开发利用，制定自然资源保护和利用规划，提升自然资源保护和合理利用水平。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百七十九条", "text": "国家对各类自然资源依法实行有偿使用，完善反映市场供求和资源稀缺程度、体现生态价值和代际补偿的自然资源有偿使用制度。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百八十条", "text": "国家建立健全以国家公园为主体的自然保护地体系，实行统一设置、分级管理、分区管控，加强对重要生态系统、自然遗迹、自然景观和生物多样性的系统性保护，满足人民群众对优美生态环境、优良生态产品、优质生态服务的需要。 国家逐步将生态系统最重要、自然景观最独特、自然遗产最精华、生物多样性最富集的特定陆域和海域纳入国家公园管理，实行严格保护。 国家公园以外，对典型的生态系统、珍稀濒危野生动植物物种的天然集中分布区、有特殊意义的自然遗迹等保护对象所在的区域，应当依法划出一定面积，设立自然保护区，予以特殊保护。 国家公园和自然保护区以外，对具有生态、观赏、文化和科学价值的生态系统、自然遗迹和自然景观所在的区域，应当依法划出一定面积，设立自然公园，实施长期保护、可持续利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百八十一条", "text": "国家统筹规划、协同推进长江、黄河等重要流域和重点海域的生态环境保护修复，构建重要流域上下游贯通一体的生态环境治理体系。 国家加强青藏高原等重要区域的生态保护，针对高原特点，加强高原生物物种、生态系统等的科学研究，增强生态产品供给能力和生态系统的服务功能。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百八十二条", "text": "国家对重要生态系统、生物物种、生物遗传资源实施有效保护，保护生物多样性相关传统知识，维护生物多样性。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百八十三条", "text": "国家健全种质资源保护与利用体系，有计划地普查、收集、整理、鉴定、登记、保存、交流和利用种质资源。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百八十四条", "text": "向境外提供，或者与境外机构、个人或者其设立或者实际控制的机构合作研究利用我国生物遗传资源的，应当依法取得批准，并提出公平、合理的国家共享惠益方案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百八十五条", "text": "国家加强生物安全管理，防范外来物种侵害，完善风险监测预警、调查评估、信息发布、应急处置等制度，对入境动植物及其产品依法实行检疫监督，对可能传入我国的外来物种加强动态跟踪和风险评估。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百八十六条", "text": "县级以上人民政府有关部门可以在各自职责范围内，根据实际需要编制森林、草原、湿地、海洋、海岛、江河湖泊、荒漠、土地、矿产、水、渔业、野生动物及其栖息地保护和水土保持、防沙治沙等生态保护领域的规划。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百八十七条", "text": "国务院生态环境、自然资源、水行政、农业农村、林业草原和标准化等有关部门，在各自职责范围内建立健全生态系统质量和等级评定、自然资源分类分级和节约集约利用、生物多样性保护以及水土保持、生态修复等标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百八十八条", "text": "国家加强土地、矿产、森林、草原、湿地、海洋、海岛、江河湖泊、雪山冰川、荒漠、野生动植物、水土保持等自然资源状况和生态状况的调查评价，为保障生态安全、合理开发和高效利用国土空间及各类自然资源提供依据。 国家建立健全生态系统、自然资源、生物多样性、水文、气象、水土保持、自然灾害等监测网络体系，优化重要区域的监测点位布局，提升自动监测预警能力。 调查评价和监测信息应当按照国家规定共享和发布，提高生态保护综合管理水平。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百八十九条", "text": "国家实行耕地养护、修复、轮作休耕和森林、草原、湿地、海洋、江河湖泊休养生息制度。 县级以上人民政府及其有关部门应当依法划定江河湖泊、海洋限捕、禁捕的时间和区域，限制公益林的采伐，划定草原禁牧、休牧、轮牧区域，实施沙化土地封禁保护，并可以根据地下水超采等情况划定禁止、限制开采地下水区域。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百九十条", "text": "国家建立严格的水土流失预防保护和监督管理制度，加强荒漠化、石漠化、水土流失的综合治理。 地方各级人民政府应当采取有效措施，保护和合理利用水土资源，开展水土保持，减轻水、旱、风沙灾害，预防土地沙化，治理沙化土地，保护和改善本行政区域的生态环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百九十一条", "text": "国家按照生态系统的整体性、系统性及其内在规律，建立健全源头保护和全过程修复治理相结合的工作机制；按照尊重自然规律，宜林则林、宜草则草、宜沙则沙、宜荒则荒的原则，科学开展生态修复；完善多元化投入机制，鼓励、支持社会资本参与，并加强生态修复的监测、监督、成效评估，巩固生态治理成果。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百九十二条", "text": "国家统筹城乡绿化，科学开展大规模国土绿化行动，绿化美化城乡。城乡绿化应当因地制宜，科学选择绿化树种草种，加强监测评估，满足健康、安全、宜居的需求。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百九十三条", "text": "国家建立生态产品调查监测机制，通过开展自然资源统一确权登记探索确定生态产品权责归属。 国家建立生态产品价值评价机制，完善价值核算办法，促进生态产品价值有效转化。 国家完善政府主导、企业和社会各界参与、市场化运作、可持续的生态产品价值实现路径，健全生态产品经营开发机制，在严格保护生态环境的前提下，因地制宜拓展生态产品价值实现渠道。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百九十四条", "text": "国家建立健全生态风险防控体系，采取有效措施，提高生态风险防控能力和水平。 县级以上人民政府及其有关部门在各自职责范围内开展生态灾害预防、风险评估和隐患排查治理，采取必要的灾害预防、处置和灾后恢复措施，防止和减轻灾害影响。 因突发性事件造成或者可能造成生态破坏的，有关单位和个人应当立即采取有效措施解除或者减轻危害，及时依法报告、通报，接受调查处理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百九十五条", "text": "国家实行自然资源督察制度。国家自然资源督察机构根据授权对省、自治区、直辖市人民政府以及国务院确定的城市人民政府自然资源保护和开发利用情况、国土空间规划实施情况及相关法律法规执行情况进行督察。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百九十六条", "text": "国家坚持平等互利、合作共赢的方针，支持开展生物多样性、野生动物、海洋生态保护和深海极地考察、防沙治沙、生态保护科学技术研究等方面的国际交流与合作。 国家依法规范有关南极活动，保护南极生态环境。 第二章 生态系统保护 第一节 森 林"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百九十七条", "text": "国家坚持生态优先、保护优先、保育结合、可持续发展，加强对森林生态系统和作为森林重要载体的山岭的保护，发挥森林蓄水保土、调节气候、改善生态环境、维护生物多样性和提供林产品等多种功能。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百九十八条", "text": "国务院林业草原主管部门主管全国林业工作。 县级以上地方人民政府林业草原主管部门主管本行政区域的林业工作。 乡镇人民政府可以确定相关机构或者设置专职、兼职人员承担林业相关工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第六百九十九条", "text": "县级以上人民政府应当落实国土空间开发保护要求，合理规划森林生态系统保护利用结构和布局，提高森林覆盖率、森林蓄积量，提升森林生态系统质量和稳定性。 县级以上人民政府林业草原主管部门可以根据实际需要，组织编制森林生态系统保护修复利用等专项规划。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百条", "text": "植树造林、保护森林，是公民应尽的义务。 国家组织和鼓励植树造林。各级人民政府应当组织开展全民义务植树活动，组织各行各业和城乡居民造林绿化。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百零一条", "text": "国家加强森林生态系统调查监测，对森林生态系统的规模、质量、结构、功能及生态状况进行调查监测和评价。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百零二条", "text": "国家实行天然林全面保护制度，严格限制天然林采伐，加强天然林管护能力建设，科学实施修复措施，保护和修复天然林，逐步提高天然林生态功能。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百零三条", "text": "国家对公益林和商品林实行分类经营管理，突出主导功能，发挥多种功能，培育稳定、健康、优质、高效的森林生态系统。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百零四条", "text": "国家根据生态保护的需要，将森林生态区位重要或者生态状况脆弱，以发挥生态效益为主要目的的林地和林地上的森林划定为公益林。 国家对公益林实行严格保护。县级以上人民政府林业草原主管部门应当有计划地组织公益林经营者对公益林中生态功能低下的疏林、残次林等低质低效林，采取林分改造、森林抚育等措施，提高公益林的质量和生态功能。 公益林只能进行抚育、更新和低质低效林改造性质的采伐，法律、行政法规另有规定的除外。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百零五条", "text": "国家保护古树名木，禁止破坏古树名木及其生存的生态环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百零六条", "text": "国家在不同自然地带的典型森林生态地区、珍贵动物和植物生长繁殖的林区、天然热带雨林区和具有特殊保护价值的其他天然林区，依法建立自然保护地，加强保护管理。 县级以上人民政府应当采取措施，加强森林野生动植物保护。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百零七条", "text": "地方各级人民政府负责本行政区域森林防灭火工作，发挥群防作用；县级以上人民政府组织领导应急管理、林业草原、公安等有关部门密切配合做好森林火灾的科学预防、扑救和处置工作。国家综合性消防救援队伍承担国家规定的森林火灾扑救任务和预防相关工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百零八条", "text": "县级以上人民政府林业草原主管部门负责本行政区域林业有害生物的监测、检疫和防治。 省级以上人民政府林业草原主管部门负责确定林业植物及其产品的检疫性有害生物，划定疫区和保护区。 重大林业有害生物灾害防治实行地方人民政府负责制。发生暴发性、危险性等重大林业有害生物灾害时，当地人民政府应当及时组织除治。 林业经营者在政府支持引导下，对其经营管理范围内的林业有害生物进行防治。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百零九条", "text": "禁止毁林开垦、采石、采砂、采土以及其他毁坏林木和林地的行为。 禁止在幼林地砍柴、毁苗、放牧。 禁止擅自移动或者损坏森林保护标志。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百一十条", "text": "地方人民政府应当组织有关部门建立护林组织，负责护林工作；根据实际需要建设护林设施，加强森林生态系统保护；督促相关组织订立护林公约、组织群众护林、划定护林责任区、配备专职或者兼职护林员。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百一十一条", "text": "国家提升森林生态系统的功能，增强生态产品供给能力，为人类生活、生产提供优良空气、优美生态环境，发挥休闲游憩、科研教育等生态价值。 开发利用森林资源不得破坏森林野生动植物生存环境，不得损害森林生态系统的功能。 第二节 草 原"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百一十二条", "text": "草原生态系统保护坚持科学规划、全面保护、重点修复、合理利用，发挥草原调节气候、涵养水源、保持水土、防风固沙以及作为野生动植物生存环境等多种功能，促进草原生态系统良性循环和资源可持续利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百一十三条", "text": "国务院林业草原主管部门主管全国草原监督管理工作。 县级以上地方人民政府林业草原主管部门主管本行政区域草原监督管理工作。 乡镇人民政府应当加强对本行政区域草原保护、修复和利用情况的监督检查，根据需要可以设专职或者兼职人员负责具体监督检查工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百一十四条", "text": "县级以上人民政府林业草原主管部门可以根据实际需要，会同有关部门组织编制草原保护修复利用等相关专项规划。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百一十五条", "text": "国家加强对草原生态系统的调查。县级以上人民政府林业草原主管部门会同有关部门对草原的面积、等级、产草量、载畜量、生态系统稳定性等进行调查。 国家建立草原生产、生态监测预警系统。县级以上人民政府林业草原主管部门会同有关部门对草原的面积、等级、植被构成、生产能力、生态健康状况、自然灾害、生物灾害等草原基本状况实行动态监测，及时为本级人民政府和有关部门提供动态监测和预警信息服务。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百一十六条", "text": "国家实行基本草原保护制度，依法将对维护生态安全、保障草原畜牧业健康发展具有最基本、最重要作用的草原划为基本草原，实行严格保护和管理，确保面积不减少、质量不下降、用途不改变。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百一十七条", "text": "国家加强草原野生动植物保护，依法建立草原类型自然保护地，增强草原生态系统的完整性和连通性，加强野生动物栖息地、迁徙通道和野生植物生长环境的保护，保障野生动植物生存繁衍的空间，保护草原生物多样性。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百一十八条", "text": "地方各级人民政府负责本行政区域草原防灭火工作，发挥群防作用；县级以上人民政府组织应急管理、林业草原、公安等有关部门密切配合做好草原火灾的科学预防、扑救和处置工作。国家综合性消防救援队伍承担国家规定的草原火灾扑救任务和预防相关工作。 县级以上地方人民政府应当做好草原鼠害、病虫害和毒害草科学防治的组织管理工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百一十九条", "text": "开发利用草原不得破坏草原野生动植物生存环境，不得损害草原生态系统的功能。 国家实行以草定畜、草畜平衡制度，防止超载过牧。县级以上地方人民政府林业草原主管部门按照国务院林业草原主管部门制定的草原载畜量标准，结合当地实际情况，考虑野生动物生存繁衍合理需求，定期核定草原载畜量。 国家对严重退化、沙化、盐碱化、石漠化的草原和生态脆弱区的草原，实行禁牧、休牧，对落实禁牧、休牧和草畜平衡的农牧民给予补助或者奖励。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百二十条", "text": "禁止开垦草原。对水土流失严重、有沙化趋势、需要改善生态环境的已垦草原，应当有计划、有步骤地退耕还草；已造成沙化、盐碱化、石漠化的，应当限期治理。 禁止在荒漠、半荒漠和严重退化、沙化、盐碱化、石漠化、水土流失的草原以及生态脆弱区的草原上采挖植物和从事破坏草原植被的其他活动，法律、行政法规另有规定的除外。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百二十一条", "text": "国家保护、修复和合理利用草原，在保护草原生态的基础上，引导科学开展草原生态旅游、生态教育、科研等活动，发挥草原生态价值。 第三节 湿 地"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百二十二条", "text": "国家坚持保护优先、严格管理、系统治理、科学修复、合理利用，完善湿地生态系统保护制度，发挥湿地涵养水源、调节气候、改善生态环境、维护生物多样性等多种生态功能，实现生态效益、社会效益、经济效益相统一。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百二十三条", "text": "国务院林业草原主管部门负责湿地资源的监督管理，负责湿地保护规划和相关国家标准拟定、湿地开发利用的监督管理、湿地生态保护修复工作。国务院自然资源、水行政、住房城乡建设、生态环境、农业农村等其他有关部门，在各自职责范围内承担湿地保护、修复、管理有关工作。 国务院林业草原主管部门会同国务院自然资源、水行政、住房城乡建设、生态环境、农业农村等主管部门建立湿地保护协作和信息通报机制。 县级以上地方人民政府应当加强湿地保护协调工作，对本行政区域湿地保护负责，采取措施保持湿地面积稳定，提升湿地生态功能。县级以上地方人民政府有关部门在各自职责范围内负责湿地保护、修复、管理相关工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百二十四条", "text": "国务院林业草原主管部门会同有关部门依法编制全国湿地保护规划。 县级以上地方人民政府林业草原主管部门可以根据实际需要，会同有关部门编制本行政区域的湿地保护规划。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百二十五条", "text": "国务院自然资源主管部门应当会同国务院林业草原等有关部门对全国湿地类型、分布、面积、生物多样性、保护与利用情况等进行调查，建立统一的信息发布和共享机制。 国务院林业草原主管部门应当按照监测技术规范开展国家重要湿地动态监测，并依据监测数据，对国家重要湿地生态状况进行评估，按照规定发布预警信息。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百二十六条", "text": "国家按照生态区位、面积以及维护生态功能、生物多样性的重要程度，将湿地分为重要湿地和一般湿地，实行分级管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百二十七条", "text": "国家实行湿地面积总量管控制度，将湿地面积总量管控目标纳入湿地保护目标责任制。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百二十八条", "text": "国家严格控制占用湿地。确需占用的，应当依照《中华人民共和国湿地保护法》的规定办理相关手续。 需要临时使用湿地的，应当依法办理相关手续，并不得修建永久性建筑物。临时使用湿地期满后，用地单位或者个人应当恢复湿地面积和生态条件。 除因防洪、航道、港口或者其他水工程占用河道管理范围及蓄滞洪区内的湿地外，经依法批准占用重要湿地的单位应当根据当地自然条件恢复或者重建与所占用湿地面积和质量相当的湿地；没有条件恢复、重建的，应当缴纳湿地恢复费。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百二十九条", "text": "地方人民政府及其有关部门应当采取措施，预防和控制人为活动对湿地及其生物多样性的不利影响，加强湿地污染防治，减缓人为因素和自然因素导致的湿地退化，维护湿地生态功能稳定。县级以上地方人民政府应当充分考虑保障重要湿地生态功能的需要，优化重要湿地周边产业布局。 地方人民政府对省级重要湿地和一般湿地利用活动进行分类指导，鼓励单位和个人开展符合湿地保护要求的生态旅游、生态农业、生态教育、自然体验等活动，适度控制种植养殖等湿地利用规模。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百三十条", "text": "禁止下列破坏湿地及其生态功能的行为： （一）开（围）垦、排干自然湿地，永久性截断自然湿地水源； （二）擅自填埋自然湿地，擅自采砂、采矿、取土； （三）排放不符合水污染物排放标准的工业废水、生活污水及其他污染湿地的废水、污水，倾倒、堆放、丢弃、抛撒、遗撒固体废物； （四）过度放牧或者滥采野生植物，过度捕捞或者灭绝式捕捞，过度施肥、投药、投饵等污染湿地的种植养殖行为； （五）其他破坏湿地及其生态功能的行为。 不得擅自采伐湿地上生长的林木，确需采伐的应当依法办理采伐许可证。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百三十一条", "text": "在红树林湿地禁止挖塘，禁止采伐、采挖、移植红树林或者过度采摘红树林种子，禁止投放、种植危害红树林生长的物种。因科研、医药或者红树林湿地保护等需要采伐、采挖、移植、采摘的，应当依照有关法律法规办理。 禁止在泥炭沼泽湿地开采泥炭或者擅自开采地下水；禁止将泥炭沼泽湿地蓄水向外排放，因防灾减灾需要的除外。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百三十二条", "text": "县级以上人民政府应当加强对国家重点保护野生动植物集中分布湿地的保护。任何单位和个人不得破坏鸟类和水生生物的生存环境。 禁止在以水鸟为保护对象的自然保护地及其他重要栖息地从事捕鱼、挖捕底栖生物、捡拾鸟蛋、破坏鸟巢等危及水鸟生存、繁衍的活动。开展观鸟、科学研究以及科普活动等应当保持安全距离，避免影响鸟类正常觅食和繁殖。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百三十三条", "text": "县级以上人民政府有关部门应当在各自职责范围内开展湿地有害生物监测工作，及时采取有效措施预防、控制、消除有害生物对湿地生态系统的危害。 第四节 海洋、海岛"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百三十四条", "text": "国家坚持保护优先、预防为主、源头防控、陆海统筹，加强海洋生态系统保护。 国家对海岛实行科学规划、保护优先、合理开发、永续利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百三十五条", "text": "国务院自然资源主管部门负责海洋、海岛保护和开发利用的监督管理，负责全国海洋生态、海域海岸线和海岛的修复工作。国务院渔业渔政主管部门负责渔业水域生态环境保护工作。其他有关部门和机构在各自职责范围内负责海洋、海岛生态保护相关工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百三十六条", "text": "国务院自然资源主管部门组织开展海洋资源调查和海洋生态预警监测，发布海洋生态预警监测警报和公报。其他负有海洋生态环境保护监督管理职责的部门和机构在各自职责范围内开展监测、监视。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百三十七条", "text": "国务院和沿海地方各级人民政府应当采取有效措施，重点保护红树林、珊瑚礁、海藻场、海草床、滨海湿地、海岛、海湾、入海河口、重要渔业水域等具有典型性、代表性的海洋生态系统，珍稀濒危海洋生物的天然集中分布区，具有重要经济价值的海洋生物生存区域及有重大科学文化价值的海洋自然遗迹和自然景观。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百三十八条", "text": "国家健全海洋生物多样性调查、监测、评估和保护体系，维护和修复重要海洋生态廊道，防止对海洋生物多样性的破坏。 国家鼓励科学开展水生生物增殖放流，支持科学规划，因地制宜采取投放人工鱼礁和种植海藻场、海草床、珊瑚等措施，恢复海洋生物多样性，修复改善海洋生态。 开发利用海洋和海岸带资源，应当对重要海洋生态系统、生物物种、生物遗传资源实施有效保护，维护海洋生物多样性。 引进海洋动植物物种，应当进行科学论证，避免对海洋生态系统造成危害。 国家积极参与国家管辖范围以外区域的海洋生物多样性养护和可持续利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百三十九条", "text": "国家严格保护海洋自然岸线，建立健全自然岸线控制制度。沿海省、自治区、直辖市人民政府负责划定严格保护岸线的范围并发布。 沿海地方各级人民政府应当加强海岸线分类保护与利用，保护修复自然岸线，促进人工岸线生态化，维护岸线岸滩稳定平衡，因地制宜、科学合理划定海岸建筑退缩线。 禁止违法占用、损害自然岸线。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百四十条", "text": "沿海地方各级人民政府应当结合当地生态环境的特点，建设海岸防护设施、沿海防护林、沿海城镇园林和绿地，对海岸侵蚀和海水入侵地区进行综合治理。 禁止毁坏海岸防护设施、沿海防护林、沿海城镇园林和绿地。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百四十一条", "text": "国家鼓励发展生态渔业，推广多种生态渔业生产方式，改善海洋生态状况，保护海洋生态环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百四十二条", "text": "国务院自然资源主管部门负责开展全国海洋生态灾害预防、风险评估和隐患排查治理。 沿海县级以上地方人民政府负责其管理海域的海洋生态灾害应对工作，采取必要的灾害预防、处置和灾后恢复措施，防止和减轻灾害影响。 企业事业单位和其他生产经营者应当采取必要应对措施，防止海洋生态灾害扩大。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百四十三条", "text": "国务院和沿海地方各级人民政府应当依照《中华人民共和国海岛保护法》等法律法规的规定采取措施，保护海岛的自然资源、自然景观以及自然遗迹、人文遗迹。 开发海岛及周围海域的资源，应当采取严格的生态保护措施，不得造成海岛地形、岸滩、植被和海岛周围海域生态环境的损害。 禁止改变自然保护区内海岛的海岸线。禁止砍伐海岛周边海域的红树林；禁止采挖、破坏珊瑚和珊瑚礁。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百四十四条", "text": "有居民海岛的开发、建设应当遵守本法和有关生态环境法律法规的规定，保护海岛及其周边海域生态系统。 未经批准利用的无居民海岛，应当维持现状；可利用无居民海岛的开发利用，应当遵守国土空间规划，采取严格的生态保护措施，避免造成海岛及其周边海域生态系统破坏。 国家对领海基点所在海岛、国防用途海岛、海洋自然保护区内的海岛等具有特殊用途或者特殊保护价值的海岛，实行特别保护。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百四十五条", "text": "中华人民共和国缔结或者参加的与海洋生态环境保护有关的国际条约与本法有不同规定的，适用国际条约的规定；但是，中华人民共和国声明保留的条款除外。 第五节 江河湖泊"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百四十六条", "text": "国家加强对江河湖泊生态系统的严格保护，巩固提升江河湖泊生态系统的功能。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百四十七条", "text": "县级以上人民政府水行政、农业农村等主管部门在各自职责范围内负责江河湖泊生态系统的保护、管理等相关工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百四十八条", "text": "国家加强江河湖泊生态用水保障，县级以上人民政府水行政主管部门、国务院水行政主管部门有关流域管理机构应当按照管理权限，确定重要江河控制断面生态流量和重要湖泊生态水位的管控指标。确定生态流量和生态水位的管控指标，应当进行科学论证，综合考虑水资源条件、气候状况、生态环境保护要求、生活生产用水状况等因素。 县级以上人民政府水行政主管部门、国务院水行政主管部门有关流域管理机构应当将生态水量纳入年度水量调度计划，保证江河湖泊基本生态用水需求，保障重要江河湖泊生态系统枯水期和鱼类产卵期生态流量，维护生态系统稳定性。 重要江河和重要湖泊上游的水利水电、航运枢纽等工程应当将生态用水调度纳入日常运行调度规程，建立常规生态调度机制，保证江河湖泊生态流量和生态水位。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百四十九条", "text": "国家对江河湖泊水域岸线等水生态空间实行分区管理，严格控制开发利用强度，最大程度保持岸线自然形态。沿江河湖泊土地开发利用和产业布局，应与岸线分区要求相衔接，并为经济社会可持续发展预留空间。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百五十条", "text": "国务院有关部门根据流域生态环境功能需要，明确流域生态环境保护要求，组织开展流域生态环境的承载能力监测、评价，实施流域生态环境的承载能力预警。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百五十一条", "text": "国家加强江河湖泊管理和保护，建立江河湖泊定期普查制度，按照规定实行江河湖泊名录管理，划定江河湖泊管理范围，实行严格保护。 禁止非法侵占和违法利用、占用江河湖泊水域和岸线、围湖造地、围垦河道、填埋河湖。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百五十二条", "text": "国家科学实施水生生物增殖放流、栖息地修复、迁地保护、生态通道修复等措施，构建水生生物多样性保护网络，并对珍贵、濒危水生野生动植物实行重点保护。 国家对水生生物产卵场、索饵场、越冬场和洄游通道等重要栖息地，实行严格的保护和管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百五十三条", "text": "国家加大对重要江河湖泊生态保护的支持力度。县级以上地方人民政府应当根据流域生态功能需要，因地制宜建设人工湿地、水源涵养林、沿江河湖泊植被缓冲带和隔离带等生态治理与保护工程，整治黑臭水体，提高流域生态环境的承载能力。 第六节 荒 漠"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百五十四条", "text": "国家加强干旱、半干旱地区自然形成的沙漠、砾漠、岩漠等原生荒漠及其生物群落的保护，坚持保护优先、统一规划、因地制宜，建立荒漠生态系统保护制度，发挥荒漠生态系统防风固沙、调节气候、调控水文、保育土壤、维护生物多样性等多种功能。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百五十五条", "text": "国务院林业草原主管部门负责荒漠生态系统保护工作。 国务院自然资源、生态环境、水行政、农业农村、气象等有关部门在各自职责范围内共同做好荒漠生态系统保护工作。 有关地方人民政府组织林业草原和其他有关部门共同做好本行政区域荒漠生态系统保护工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百五十六条", "text": "县级以上人民政府及其有关部门根据实际需要编制生态保护相关规划时，应当科学规划荒漠生态系统保护利用的结构和布局，稳固和提升荒漠生态系统的功能。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百五十七条", "text": "国家建立健全原生荒漠保护制度。地方人民政府及其有关部门应当采取措施，预防和控制人为活动对原生荒漠中原生植被、土壤、水、野生动物及其栖息地的扰动，加强地表结皮的保育，及时制止导致土地荒漠化的行为，并采取有效措施进行治理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百五十八条", "text": "国家对生态区位重要的原生荒漠实施封禁保护，促进荒漠植被自然修复，综合采用生物措施和工程措施提高荒漠生态系统稳定性。 第三章 自然资源保护与可持续利用 第一节 土地资源"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百五十九条", "text": "十分珍惜、合理利用土地和切实保护耕地是我国的基本国策。 国家坚持实行最严格的耕地保护制度、最严格的节约集约用地制度，严守耕地保护红线。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百六十条", "text": "国务院自然资源主管部门统一负责全国土地的管理和监督工作，国务院农业农村主管部门负责全国农村宅基地改革和管理有关工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百六十一条", "text": "国家建立土地调查、统计与监测制度。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百六十二条", "text": "地方各级人民政府应当按照国土空间规划，组织实施田、水、路、林、村综合整治，增加有效耕地面积，提高耕地质量，改善农业生产条件和生态环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百六十三条", "text": "国家加强对土壤资源的保护和合理利用，减少开发利用对土壤生态系统和生物多样性的影响。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百六十四条", "text": "国家实行耕地数量、质量、生态一体保护。 国家建立耕地保护补偿制度，调动耕地保护责任主体保护耕地的积极性。 国家建立耕地保护责任目标考核制度。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百六十五条", "text": "国家实行占用耕地补偿制度，严格控制各类占用耕地行为；确需占用耕地的，应当依法落实补充耕地责任。 国家建立严格的耕地质量建设和保护制度，加强高标准农田建设和退化耕地治理，促进耕地质量提升。 国家建立耕地的生态保护与修复制度，鼓励采取生态修复措施，恢复和提升耕地生态功能，维持生态系统整体稳定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百六十六条", "text": "国家对永久基本农田实行特殊保护。永久基本农田经依法划定后，任何单位和个人不得擅自占用或者改变其用途。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百六十七条", "text": "国家实行科学、有效的黑土地保护政策，保障黑土地保护财政投入，综合采取工程、农艺、农机、生物等措施，保护黑土地的优良生产能力，确保黑土地总量不减少、功能不退化、质量有提升、产能可持续。 有关县级以上人民政府应当依照《中华人民共和国黑土地保护法》的规定，加强黑土地生态保护和黑土地周边林地、草原、湿地的保护与修复，推动荒山荒坡治理，提升生态系统涵养水源、保持水土、防风固沙、维护生物多样性等生态功能，维持有利于黑土地保护的生态环境。 任何单位和个人不得破坏黑土地资源和生态环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百六十八条", "text": "国家实行建设用地总量控制，严格限制农用地转为建设用地。确需占用的，应当依照《中华人民共和国土地管理法》、《中华人民共和国森林法》、《中华人民共和国草原法》，以及有关耕地保护和质量提升的法律等的规定办理相关手续。 建设项目使用土地的，应当节约集约利用土地，严格遵守生态环境保护要求，防止污染环境、破坏生态。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百六十九条", "text": "依照法律、行政法规的规定申请临时用地的，应当尽量不占或者少占耕地、避让永久基本农田，不得修建永久性建筑物。 临时用地确需占用耕地的，应当按照规定恢复种植条件。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百七十条", "text": "具有重要生态功能的未利用地应当依法划入生态保护红线，实行严格保护。开垦未利用的土地，应当经过科学论证和评估，经依法批准后进行。 第二节 矿产资源"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百七十一条", "text": "矿产资源的勘查、开采以及矿区生态修复，应当坚持开发利用与保护并重，实现绿色发展。 国家鼓励、支持矿业绿色低碳转型发展，加强绿色矿山建设。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百七十二条", "text": "国家对矿产资源的勘查、开采实行统一规划、科学布局、综合勘查、合理开采和综合利用的方针。 各级人民政府应当依照《中华人民共和国矿产资源法》的规定，加强矿产资源保护工作。禁止以任何手段侵占或者破坏矿产资源。 对国务院确定的特定战略性矿产资源，按照国家规定实行保护性开采。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百七十三条", "text": "矿业权出让合同应当明确矿区生态修复等有关要求。 勘查、开采矿产资源，应当遵守本法和有关生态环境法律法规的规定，防止污染环境、破坏生态；应当采用先进适用、符合生态环境保护要求的技术、工艺、设备，不得使用国家明令淘汰的技术、工艺、设备。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百七十四条", "text": "勘查活动结束后，探矿权人应当及时对勘查区域进行清理；破坏地表植被的，应当及时恢复。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百七十五条", "text": "开采矿产资源，应当采取合理的开采顺序、开采方法；采取有效措施保护地下水资源，并优先使用矿井水；避免、减少对矿区森林、草原、耕地、湿地、江河湖泊、海洋等生态系统的破坏；加强对尾矿库建设、运行、闭库等活动的管理，防范生态环境风险。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百七十六条", "text": "禁止在严格保护岸线范围内开采海砂。依法在其他区域开发利用海砂资源，应当采取严格措施，保护海洋生态。载运海砂资源应当持有合法来源证明；海砂开采者应当为载运海砂的船舶提供合法来源证明。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百七十七条", "text": "国家依法保护煤炭资源，禁止任何乱采、滥挖等破坏煤炭资源的行为。 国家统筹推进采煤沉陷区综合治理，促进采煤沉陷区转型发展。 煤矿企业应当依法开展矿区生态环境综合治理，履行环境污染治理和生态修复义务。 第三节 水资源"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百七十八条", "text": "保护、开发、利用、节约水资源和防治水害，应当全面规划、统筹兼顾、标本兼治、综合利用、讲求效益，实现水资源的可持续利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百七十九条", "text": "国家厉行节水，坚持和落实节水优先方针，全面建设节水型社会。 任何单位和个人都有节约用水的义务。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百八十条", "text": "国家制定水资源综合规划，对水资源合理配置、有效保护和节约集约利用等作出总体安排。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百八十一条", "text": "国家对水资源实行流域管理与行政区域管理相结合的管理体制。 国务院水行政主管部门负责全国水资源的统一管理和监督工作；国务院其他有关部门在各自职责范围内负责水资源保护、开发、利用、节约的有关工作。 国务院水行政主管部门在国家确定的重要江河湖泊设立的流域管理机构及其所属管理机构，在所管辖的范围内行使法律、行政法规规定的和国务院水行政主管部门授予的水资源管理和监督职责。 县级以上地方人民政府水行政主管部门按照规定的权限，负责本行政区域水资源的统一管理和监督工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百八十二条", "text": "国家加强水文、水资源信息系统建设。县级以上人民政府水行政主管部门和流域管理机构应当加强对水资源的动态监测，提升水文监测预报预警能力。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百八十三条", "text": "国家建立健全水功能区划制度。 设区的市级以上地方人民政府生态环境主管部门和流域生态环境监督管理机构应当对水功能区的水生态环境质量状况进行监测，发现水生态环境质量未达到要求的，应当及时报告有关人民政府采取治理措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百八十四条", "text": "制定水资源开发、利用规划和调度水资源时，应当保障维持江河的合理流量和湖泊、水库以及地下水的合理水位，维护水体的自然净化能力。在干旱和半干旱地区开发、利用水资源，应当充分考虑生态用水需要。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百八十五条", "text": "国家加强饮用水水源地保护，实行饮用水水源地名录管理，将饮用水水源地水量保障作为流域区域水量调度方案和调度计划的优先目标，严格取水管理，防止水源枯竭和水体污染，保证城乡居民饮用水安全。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百八十六条", "text": "国家加强地下水管理和保护，实行地下水取水总量控制和水位控制制度，划定地下水超采区，实施地下水超采综合治理，保障地下水可持续利用。 省级人民政府水行政主管部门应当会同自然资源等有关部门，统筹考虑地下水超采区划定、地下水利用情况以及地质环境条件等因素，依法组织划定本行政区域地下水禁止开采区、限制开采区。 国家建立地下水储备制度。除特殊干旱年份以及发生重大突发事件外，不得动用地下水储备。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百八十七条", "text": "开发、利用水资源，应当坚持节约保护优先、兴利与除害相结合，兼顾上下游、左右岸、干支流和有关地区之间的利益，充分发挥水资源的综合效益，并服从防洪的总体安排。 国家根据水资源承载能力对水资源实行差别化管控，强化水资源节约保护，合理控制水资源开发利用规模。地方人民政府应当结合本地区水资源的实际情况，按照地表水与地下水统一调度开发、开源与节流相结合、节流优先和污水处理再利用的原则，合理组织开发、综合利用水资源。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百八十八条", "text": "国民经济和社会发展规划、国土空间总体规划的编制以及重大建设项目的布局，应当与当地水资源条件和防洪要求相适应，并进行科学论证。 国家建立健全涉及水资源开发利用的建设项目和有关规划水资源论证制度。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百八十九条", "text": "国家鼓励、支持污水资源化利用，县级以上地方人民政府应当统筹规划、建设污水资源化利用基础设施。 县级以上地方人民政府应当根据当地水资源状况，加强污水处理回用，将再生水、集蓄雨水、海水及海水淡化水、矿井（坑）水、微咸水等非常规水纳入水资源统一配置，统筹规划、建设非常规水开发利用设施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百九十条", "text": "县级以上人民政府组织实施调水工程，应当进行全面规划和科学论证，统筹兼顾调出区和调入区的用水安全和生态安全，加强对调入区的节水管理，优化水资源配置，提高水资源承载能力，防止对生态环境造成破坏。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百九十一条", "text": "开发、利用水资源，应当维护水体的生态功能，防止对水生态造成破坏。 开发、利用水资源，应当优先满足城乡居民生活用水，保障基本生态用水、粮食安全用水，并统筹农业、工业、生态修复用水以及航运等需要。 水工程应当加强水生生物保护，合理制定调度规程，在确保防洪、供水安全的前提下，开展适宜水生生物生长繁育需求的生态调度。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百九十二条", "text": "国家对用水实行总量控制和定额管理相结合的制度，依照《中华人民共和国水法》的规定对水资源实行取水许可制度和有偿使用制度。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百九十三条", "text": "国家大力推行节约用水措施，推广节约用水新技术、新工艺，发展节水型工业、农业和服务业，推进生活节水，加强生活废水循环利用。 各级人民政府应当采取措施，加强对节约用水的管理，建立节约用水技术开发推广体系，培育和发展节约用水产业。 新建、扩建、改建建设项目应当制定节水措施方案，配套建设节水设施。节水设施应当与主体工程同时设计、同时施工、同时投产使用。 工业和服务业企业应当采用先进适用节水技术、工艺和设备，增加循环用水次数，提高水的重复利用率。 县级以上人民政府及其有关部门应当推行节水灌溉方式和节水技术，提高农业用水效率，加强灌区建设和改造，发展节水型农业。 县级以上地方人民政府应当全面推进节水型城市建设。城市绿化、道路清扫、车辆冲洗、建筑施工以及生态景观等用水，应当优先使用符合标准要求的再生水。 第四节 渔业资源"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百九十四条", "text": "渔业生产应当坚持养殖为主、适度捕捞，实现渔业资源的保护和可持续利用。 地方人民政府及其有关部门应当因地制宜采取改良水域条件、人工投放苗种、投放鱼巢、灌江纳苗、营救幼鱼、移植驯化、消除敌害、引种栽植等措施，增殖渔业资源。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百九十五条", "text": "国务院渔业渔政主管部门主管全国的渔业工作。县级以上地方人民政府渔业渔政主管部门主管本行政区域渔业工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百九十六条", "text": "国家保护水产种质资源及其生存环境，并在具有较高经济价值和遗传育种价值的水产种质资源的主要生长繁育区域建立水产种质资源保护区。 未经省级以上人民政府渔业渔政主管部门批准，任何单位和个人不得在水产种质资源保护区内从事捕捞活动。 禁止非法占用或者破坏水产种质资源保护区。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百九十七条", "text": "国家鼓励、支持因地制宜采取增殖放流、建设海洋牧场、投放人工鱼礁、种植海藻场或者海草床等措施，养护水生生物资源，修复、改善渔业水域生态环境。 国家对具有较高经济价值的水生动植物资源实行重点保护。国家重点保护经济水生动植物资源名录，由国务院渔业渔政主管部门组织科学论证评估后制定并公布。 禁止向开放水域投放不符合生态要求的水生外来种、杂交种等水生生物。 在重要渔业水域开展建闸、筑坝、航道建设、港口建设等工程建设，对渔业资源有严重影响的，建设单位应当依法建造过鱼设施或者采取其他渔业资源保护措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百九十八条", "text": "国家对水域、滩涂利用进行统一规划，确定可以用于养殖业的水域和滩涂，建立养殖水域、滩涂保护制度；单位和个人使用国家所有的水域、滩涂从事养殖生产的，应当依照《中华人民共和国渔业法》的规定取得养殖证。 县级以上地方人民政府应当采取有效措施，加强对水产品生产基地和重要养殖水域、滩涂的保护。 从事养殖生产应当保护水域、滩涂生态环境，科学确定养殖密度和养殖规模，合理投饵、投饲、投药，养殖排放尾水应当符合有关污染物排放标准，不得破坏水域、滩涂的生态环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第七百九十九条", "text": "国家根据捕捞量低于渔业资源增长量的原则，确定渔业资源的总可捕捞量，实行捕捞限额制度。 国家根据捕捞能力与渔业资源可捕捞量相适应的原则，确定渔业船网工具控制指标。 国家对捕捞业实行捕捞许可证制度。从事捕捞作业的单位和个人，应当按照捕捞许可证规定的作业类型、场所、时限、渔具数量和捕捞限额等进行作业。 禁止捕捞有重要经济价值的水生动物苗种或者禁捕的怀卵亲本；捕捞作业时误捕的，应当及时放生；因科学研究、养殖、捕捞过坝、增殖放流或者其他特殊需要确需捕捞的，应当经省级以上人民政府渔业渔政主管部门批准，在指定的区域和时间内，按照限额捕捞。 捕捞活动中误捕珍贵、濒危水生野生动物的，应当及时采取救护、处置措施，并报告渔业渔政主管部门。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百条", "text": "各级人民政府应当采取有效措施，保护和改善渔业水域生态环境。 对用于渔业并兼有调蓄、灌溉等功能的水体，有关主管部门应当确定渔业资源保护和渔业生产所需的最低水位线。 进行水下爆破、勘探、采砂、施工等作业，对渔业资源有严重影响的，作业单位应当事先同有关县级以上地方人民政府渔业渔政主管部门协商，采取措施，防止或者减少对渔业资源的损害。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百零一条", "text": "禁止违反禁渔区、禁渔期的规定从事捕捞活动。禁止渔业船舶违反禁渔区、禁渔期的规定航行、停泊。 对违反前款规定的渔业船舶，任何单位和个人不得为其提供供油、供水、供冰等服务，不得代冻、转载、运输、收购、加工、销售其非法捕捞的渔获物。 禁止使用炸鱼、毒鱼、电鱼等破坏渔业资源和渔业水域生态环境的方法进行捕捞。禁止制造、销售、使用禁用的渔具。禁止使用小于最小网目尺寸的网具进行捕捞。捕捞的渔获物中幼鱼不得超过规定的比例。 第五节 其他自然资源"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百零二条", "text": "国家加强对林木、草原、野生动物和海洋资源等其他自然资源开发利用的管理，实现资源的保护与可持续利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百零三条", "text": "国家实行林木采伐许可制度。采伐林地上的林木应当依法申请采伐许可证，并按照采伐许可证的规定进行采伐。非林地上的农田防护林、防风固沙林、护路林、护岸护堤林和城镇林木等的更新采伐，由有关主管部门按照规定管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百零四条", "text": "国家鼓励、支持人工草地建设、天然草原改良和饲草饲料基地建设，稳定、提高草原生产能力。 县级以上人民政府应当按照草原保护、修复、利用规划加强草种基地建设，鼓励选育、引进、推广优良草品种。 草原承包经营者应当合理利用草原，不得超过林业草原主管部门核定的载畜量，采取有效措施保持草畜平衡。 牧区的草原承包经营者应当实行划区轮牧，合理配置畜群，均衡利用草原。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百零五条", "text": "人工繁育野生动物，实行分类分级管理，严格保护和科学利用野生动物资源，并依法办理许可或者备案。 人工繁育野生动物应当使用人工繁育子代种源，建立物种系谱、繁育档案和个体数据。因物种保护目的确需采用野外种源的，应当遵守本法和《中华人民共和国野生动物保护法》有关猎捕野生动物的规定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百零六条", "text": "开发利用海洋资源或者从事影响海洋生态环境的建设活动，应当根据国土空间规划科学合理布局，严格遵守国土空间用途管制要求，严守生态保护红线，不得造成海洋生态环境的损害。沿海省、自治区、直辖市人民政府应当加强对生态保护红线内人为活动的监督管理，定期评估保护成效。 新建、改建、扩建工程建设项目，应当采取有效措施，保护国家和地方重点保护的野生动植物及其生存环境，保护海洋水产资源，避免或者减轻对海洋生物的影响。 国家严格管理填海、围海等改变海域自然属性的用海活动。沿海地方各级人民政府应当根据国土空间规划，保护和科学合理使用海域。 使用海域的单位和个人应当依照《中华人民共和国海域使用管理法》的规定，保护和科学合理使用海域，不得擅自改变经批准的海域用途。海域使用权终止后，应当及时拆除可能造成海洋环境污染、生态破坏或者影响其他用海项目的用海设施和构筑物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百零七条", "text": "国家加强对专属经济区和大陆架自然资源开发利用活动的管理。中华人民共和国主管机关依照《中华人民共和国专属经济区和大陆架法》的规定，有权采取必要的措施，防止、减少和控制对海洋生态环境的破坏。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百零八条", "text": "从事深海海底区域资源勘探、开发活动应当依照《中华人民共和国深海海底区域资源勘探开发法》的规定，采取必要措施，保护和保全稀有或者脆弱的生态系统，以及衰竭、受威胁或者有灭绝危险的物种和其他海洋生物的生存环境，保护海洋生物多样性，维护海洋资源的可持续利用。 第四章 物种保护 第一节 野生动物保护"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百零九条", "text": "本法规定保护的野生动物，是指珍贵、濒危的陆生、水生野生动物和有重要生态、科学、社会价值的陆生野生动物。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百一十条", "text": "国家加强野生动物保护，拯救珍贵、濒危野生动物，维护生物多样性和生态平衡。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百一十一条", "text": "国务院林业草原、渔业渔政主管部门分别主管全国陆生、水生野生动物保护工作。 县级以上地方人民政府对本行政区域野生动物保护工作负责，其林业草原、渔业渔政主管部门分别主管本行政区域陆生、水生野生动物保护工作。 县级以上人民政府其他有关部门在各自职责范围内负责野生动物保护相关工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百一十二条", "text": "国家对野生动物实行分类分级保护。 国家对珍贵、濒危的野生动物实行重点保护。国家重点保护的野生动物分为一级保护野生动物和二级保护野生动物。 国家重点保护野生动物，有重要生态、科学、社会价值的陆生野生动物，以及地方重点保护野生动物实行名录管理，定期论证评估，及时进行调整。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百一十三条", "text": "县级以上人民政府野生动物保护主管部门应当加强信息技术应用，定期组织或者委托有关科学研究机构对野生动物及其栖息地状况进行调查、监测和评估，建立健全野生动物及其栖息地档案。 各级野生动物保护主管部门应当监测外部因素对野生动物的影响，发现野生动物受到危害时，应当会同有关部门及时进行调查处理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百一十四条", "text": "县级以上人民政府野生动物保护主管部门根据野生动物及其栖息地调查、监测和评估情况，对种群数量明显超过生态环境容量的物种，可以采取迁地保护、猎捕等种群调控措施，保障人身财产安全、生态安全和农业生产。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百一十五条", "text": "国家保护野生动物及其栖息地。 国务院野生动物保护主管部门应当会同有关部门，根据野生动物及其栖息地状况的调查、监测和评估结果，依法确定并发布野生动物重要栖息地名录。 省级以上人民政府依法将野生动物重要栖息地划入自然保护地，保护、恢复和改善野生动物生存环境。对不具备划定自然保护地条件的，县级以上人民政府可以采取划定禁猎（渔）区、规定禁猎（渔）期等措施予以保护。 禁止破坏野生动物栖息地，禁止或者限制在自然保护地内引入外来物种、营造单一纯林、过量施洒农药、产生高噪声、过度照明等人为干扰、威胁野生动物生息繁衍的行为。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百一十六条", "text": "县级以上人民政府及其有关部门在依法编制有关开发利用规划时，应当充分考虑野生动物及其栖息地保护的需要，分析、预测和评估规划实施可能对野生动物及其栖息地保护产生的整体影响，避免或者减少规划实施可能造成的不利后果。 机场、铁路、公路、航道、水利水电、风电、光伏发电、围堰、填海、围海等建设项目的选址选线，应当避让野生动物重要栖息地、迁徙洄游通道；确实无法避让的，应当采取修建野生动物通道、过鱼设施等措施，消除或者减少对野生动物的不利影响。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百一十七条", "text": "在自然保护地和禁猎（渔）区、禁猎（渔）期内，禁止猎捕以及其他妨碍野生动物生息繁衍的活动，法律法规另有规定的除外。 野生动物迁徙洄游期间，在前款规定区域外的迁徙洄游通道内，禁止猎捕并严格限制其他妨碍野生动物生息繁衍的活动。县级以上人民政府或者其野生动物保护主管部门应当规定并公布迁徙洄游通道的范围以及妨碍野生动物生息繁衍活动的内容。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百一十八条", "text": "禁止猎捕、杀害国家重点保护野生动物，因科学研究、种群调控、疫源疫病监测或者其他特殊情况需要猎捕的，应当依法申请特许猎捕证。 猎捕有重要生态、科学、社会价值的陆生野生动物和地方重点保护野生动物的，应当依法取得狩猎证，并服从猎捕量限额管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百一十九条", "text": "禁止使用毒药、爆炸物、电击或者电子诱捕装置以及猎套、猎夹、捕鸟网、地枪、排铳、地弓等工具进行猎捕，禁止使用夜间照明行猎、歼灭性围猎、捣毁巢穴、设置陷阱、火攻、烟熏、网捕等方法进行猎捕，但因物种保护、科学研究确需网捕、电子诱捕以及植保作业等除外。 前款规定以外的禁止使用的猎捕工具和方法，由县级以上地方人民政府规定并公布。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百二十条", "text": "社会公众应当增强保护野生动物和维护公共卫生安全的意识，防止野生动物源性传染病传播，抵制违法食用野生动物，养成文明健康的生活方式。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百二十一条", "text": "禁止出售、购买、利用国家重点保护野生动物及其制品。 因科学研究、人工繁育、公众展示展演、文物保护或者其他特殊情况，需要出售、购买、利用国家重点保护野生动物及其制品的，应当经依法批准，并按照规定取得和使用专用标识，保证可追溯。 出售、利用有重要生态、科学、社会价值的陆生野生动物和地方重点保护野生动物及其制品的，应当提供狩猎、人工繁育、进出口等合法来源证明。 出售本条第二款、第三款规定的野生动物的，还应当依法附有检疫证明。 利用野生动物进行公众展示展演应当采取安全管理措施，并保障野生动物健康状态。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百二十二条", "text": "国家重点保护野生动物和有重要生态、科学、社会价值的陆生野生动物或者地方重点保护野生动物受到突发事件威胁时，当地人民政府应当及时采取应急救助措施。 国家加强野生动物收容救护能力建设。县级以上人民政府野生动物保护主管部门应当按照国家规定组织开展野生动物收容救护工作，加强对社会组织开展野生动物收容救护工作的规范和指导。 收容救护机构应当根据野生动物收容救护的实际需要，建立收容救护场所，配备相应的专业技术人员、救护工具、设备和药品等。 禁止以野生动物收容救护为名买卖野生动物及其制品。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百二十三条", "text": "国务院野生动物保护主管部门应当会同有关部门加强对放生野生动物活动的规范、引导。任何单位和个人将野生动物放生至野外环境，应当选择适合放生地野外生存的当地物种，不得干扰当地居民的正常生活、生产，避免对生态系统造成危害。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百二十四条", "text": "外国人在我国对国家重点保护野生动物进行野外考察或者在野外拍摄电影、录像，应当经依法批准，并遵守有关法律法规的规定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百二十五条", "text": "国家加强对野生动物遗传资源的保护，对濒危野生动物实施抢救性保护。 国务院野生动物保护主管部门应当会同有关部门制定有关野生动物遗传资源保护和利用规划，建立国家野生动物遗传资源基因库，对原产我国的珍贵、濒危野生动物遗传资源实行重点保护。 禁止向境外机构或者人员提供我国特有的野生动物遗传资源。开展国际科学研究合作的，应当依法取得批准，有我国科研机构、高等学校、企业及其研究人员实质性参与研究，按照规定提出国家共享惠益的方案，并遵守我国法律、行政法规的规定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百二十六条", "text": "中华人民共和国缔结或者参加的国际公约禁止或者限制贸易的野生动物或者其制品名录，由国家濒危物种进出口管理机构制定、调整并公布。 进出口列入前款名录的野生动物或者其制品，或者出口国家重点保护野生动物或者其制品的，应当经依法批准，并取得允许进出口证明书，凭允许进出口证明书办理海关手续。 涉及科学技术保密的野生动物物种的出口，按照国务院有关规定办理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百二十七条", "text": "国家组织开展野生动物保护及相关执法活动的国际交流与合作，加强与毗邻国家的协作，保护候鸟、洄游鱼类等野生动物的迁徙洄游通道；建立防范、打击野生动物及其制品走私和非法贸易的部门协调机制，开展防范、打击走私和非法贸易行动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百二十八条", "text": "在野生动物致害严重区域，县级以上地方人民政府应当组织有关单位和个人积极开展野生动物致害综合防控，通过建设隔离防护设施、设置安全警示标志、强化监测预警、开展防护知识宣传等，科学预防野生动物可能造成的危害。 因保护珍贵、濒危的陆生、水生野生动物和有重要生态、科学、社会价值的陆生野生动物，造成人员伤亡、农作物或者其他财产损失的，依法给予补偿。 在野生动物危及人身安全的紧急情况下，采取措施造成野生动物损害的，依法不承担法律责任。 第二节 野生植物保护"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百二十九条", "text": "本法规定保护的野生植物，是指原生地天然生长的珍贵植物和原生地天然生长并具有重要经济、科学、文化价值的濒危、稀有植物。 药用野生植物和城市园林、自然保护地内的野生植物的保护，同时适用有关法律法规的规定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百三十条", "text": "国家加强野生植物保护，严格管理我国野生植物采集、利用、对外提供等活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百三十一条", "text": "国务院林业草原、农业农村主管部门在各自职责范围内分别主管全国野生植物保护和监督管理工作。 国务院住房城乡建设主管部门负责城市园林内野生植物的监督管理工作。国务院生态环境主管部门负责监督全国野生植物保护工作。国务院其他有关部门在各自职责范围内负责野生植物保护相关工作。 县级以上地方人民政府林业草原、农业农村主管部门在各自职责范围内分别主管本行政区域野生植物保护和监督管理工作。县级以上地方人民政府其他有关部门在各自职责范围内负责野生植物保护相关工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百三十二条", "text": "国家保护野生植物及其生长环境。禁止非法采集野生植物或者破坏其生长环境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百三十三条", "text": "国家对野生植物实行分类分级保护。 野生植物分为国家重点保护野生植物和地方重点保护野生植物。国家重点保护野生植物分为国家一级保护野生植物和国家二级保护野生植物。 国家重点保护野生植物、地方重点保护野生植物实行名录管理，并及时进行调整。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百三十四条", "text": "国家鼓励、支持野生植物的就地保护。在国家重点保护野生植物物种和地方重点保护野生植物物种的天然集中分布区域，应当依法建立自然保护地；在其他区域，县级以上地方人民政府野生植物保护主管部门和其他有关部门可以根据实际情况建立重点保护野生植物的保护点或者设立保护标志。 禁止擅自移动或者破坏重点保护野生植物的保护设施和保护标志。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百三十五条", "text": "各级野生植物保护主管部门和有关单位对生长受到威胁的国家重点保护野生植物和地方重点保护野生植物应当采取拯救措施，恢复其生长环境，必要时应当采取迁地保护、建立种质资源库和野外回归等措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百三十六条", "text": "国家建立健全野生植物迁地保护网络，逐步建立国家植物园体系。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百三十七条", "text": "国务院野生植物保护主管部门负责组织开展全国野生植物资源调查、监测、评估和信息发布工作。地方人民政府野生植物保护主管部门负责本行政区域相关工作。 县级以上人民政府野生植物保护主管部门及其他有关部门应当监视、监测外部因素对国家重点保护野生植物和地方重点保护野生植物生长的影响，并采取有效措施，维护和改善国家重点保护野生植物和地方重点保护野生植物的生长条件。国家重点保护野生植物和地方重点保护野生植物的生长受到危害时，野生植物保护主管部门应当会同其他有关部门调查并依法处理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百三十八条", "text": "除因科学研究、人工培育、文化交流等特殊需要外，禁止采集国家一级保护野生植物。 采集国家一级、二级保护野生植物的，应当依法申请采集证。 采集城市园林、自然保护地内的国家重点保护野生植物的，须先征得城市园林、自然保护地管理机构同意，分别依照前两款的规定申请采集证。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百三十九条", "text": "国家引导和规范具备条件的单位和个人依法开展野生植物人工培植活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百四十条", "text": "禁止出售、收购国家一级保护野生植物。 出售、收购国家二级保护野生植物的，应当经依法批准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百四十一条", "text": "禁止外国人在中国境内采集或者收购国家重点保护野生植物及其种质资源。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百四十二条", "text": "出口国家重点保护野生植物及其制品或者进出口中华人民共和国参加的国际公约所限制进出口的野生植物及其制品的，应当经依法批准，并取得允许进出口证明书或者标签，凭允许进出口证明书或者标签办理海关手续。国务院野生植物保护主管部门应当将有关野生植物进出口的资料抄送国务院生态环境主管部门。 禁止出口未定名的或者新发现并有重要价值的野生植物及其制品。 第三节 外来入侵物种防控"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百四十三条", "text": "本法所称外来入侵物种，是指境外传入定殖并对生态系统、物种及其栖息生长环境带来威胁或者危害，影响我国生态环境，损害农林牧渔业可持续发展和生物多样性的外来物种。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百四十四条", "text": "国家坚持风险预防、源头管控、综合治理、协同配合、公众参与，完善外来物种入侵防控体系，加强外来入侵物种防控管理，保护生物多样性，维护国家生物安全。 国家严厉打击非法引入外来物种行为。任何单位和个人不得违反《中华人民共和国生物安全法》、《中华人民共和国野生动物保护法》等法律法规的规定，擅自引进、释放或者丢弃外来物种。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百四十五条", "text": "国务院农业农村主管部门会同有关部门建立外来入侵物种防控协调机制，统筹全国外来入侵物种防控工作，协调解决重大问题。 省级人民政府农业农村主管部门会同有关部门建立外来入侵物种防控协调机制，组织开展本行政区域外来入侵物种防控工作。 海关完善境外风险预警和应急处理机制，强化入境货物、运输工具、寄递物品、旅客行李、跨境电商、边民互市等渠道外来入侵物种的口岸检疫监督管理。 县级以上地方人民政府依法对本行政区域外来入侵物种防控工作负责，组织、协调、督促有关部门依法履行外来入侵物种防控管理职责。 县级以上地方人民政府农业农村、林业草原、自然资源、生态环境以及其他有关部门在各自职责范围内负责外来入侵物种的监督管理工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百四十六条", "text": "国务院农业农村主管部门会同有关部门制定完善外来入侵物种名录，实行动态调整和分类分级管理，建立外来入侵物种数据库，制定外来入侵物种风险评估、监测预警、防控治理等技术规范。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百四十七条", "text": "国务院农业农村、自然资源、生态环境、海关、林业草原等有关部门建立健全应急处置机制，组织制定相关领域外来入侵物种突发事件应急预案。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百四十八条", "text": "国家加强外来物种引入审批管理。因品种培育等特殊需要从境外引进农作物和林草种子苗木、水产苗种等外来物种的，应当依法办理进口审批与检疫审批。 属于首次引进的，引进单位应当就引进物种对生态环境的潜在影响进行风险分析，并向审批部门提交风险评估报告。审批部门应当及时组织开展审查评估。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百四十九条", "text": "国务院农业农村主管部门会同有关部门建立外来入侵物种普查制度，掌握我国外来入侵物种的种类数量、分布范围、危害程度等情况。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百五十条", "text": "国务院农业农村主管部门会同有关部门建立外来入侵物种监测制度，构建全国外来入侵物种监测网络，在各自职责范围内布设监测站点，组织开展常态化监测和信息共享。 县级以上地方人民政府农业农村主管部门和有关部门在各自职责范围内开展本行政区域外来入侵物种监测工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百五十一条", "text": "国家加强外来入侵物种口岸防控。 输入动物、动物产品、植物种子苗木及其他繁殖材料的，应当依照《中华人民共和国进出境动植物检疫法》的规定，事先提出申请，办理检疫审批手续。 输入动植物、动植物产品和其他检疫物，应当在进境口岸实施检疫。未经海关同意，不得卸离运输工具。输入动植物，需隔离检疫的，在海关指定的隔离场所检疫。 输入动物，经检疫合格的，准予进境。输入植物、动植物产品和其他检疫物，经检疫合格或者经除害处理合格的，准予进境。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百五十二条", "text": "国务院农业农村、自然资源、生态环境、林业草原等有关部门在各自职责范围内研究制定本领域外来入侵物种防控策略措施，指导地方开展防控。 县级以上地方人民政府农业农村、自然资源、林业草原等有关部门应当在各自职责范围内综合考虑外来入侵物种种类、危害对象、危害程度、扩散趋势等因素，制定本行政区域外来入侵物种防控治理方案，并组织实施，及时控制或者消除危害。 第五章 重要地理单元保护 第一节 自然保护地"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百五十三条", "text": "国家以保护自然、服务人民、永续发展为目标，坚持严格保护、科学管理、政府主导、多方参与、合理利用、社会共享，建立健全自然保护地体系，保护生物多样性与地质地貌景观多样性，维护生态系统健康稳定，提升生态产品供给能力，维护生态安全。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百五十四条", "text": "国务院林业草原主管部门负责各类自然保护地的监督管理工作。 国务院自然资源主管部门根据国务院授权履行自然保护地范围内全民所有自然资源资产所有者职责。 国务院生态环境主管部门在其职责范围内负责组织制定各类自然保护地生态环境监督管理制度并监督执法。 国务院住房城乡建设、交通运输、水行政、农业农村、文化和旅游等有关部门和海警机构在各自职责范围内负责自然保护地内相关工作。 按照规定设立的各自然保护地管理机构依照法律和规定的职责，负责各该自然保护地的保护和管理工作。 有关县级以上地方人民政府履行本行政区域自然保护地的经济社会发展综合协调、公共服务、社会管理、市场监督管理、防灾减灾等职责；其有关部门在各自职责范围内负责自然保护地的有关监督管理工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百五十五条", "text": "国务院林业草原主管部门会同国务院发展改革、财政、自然资源、生态环境、住房城乡建设、交通运输、水行政、农业农村、文化和旅游等有关部门开展保护协作、信息共享等，研究解决自然保护地保护工作中的重大问题。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百五十六条", "text": "跨两个以上行政区域的自然保护地，由相关行政区域人民政府加强自然保护地保护工作协商，或者由涉及行政区域联合申请，由上级人民政府协调解决；跨两个以上省级行政区域的，由国务院林业草原主管部门商自然保护地所在地省、自治区、直辖市人民政府解决。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百五十七条", "text": "国家加强自然保护地监测网络体系建设，充分发挥各类监测站点的作用，运用信息化手段加强监测数据集成分析、共享和综合应用，全面掌握生态系统构成、分布、动态变化和生物多样性状况，及时评估和预警生态风险。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百五十八条", "text": "国家建立健全自然保护地相关标准体系，依法组织制定并适时修订自然保护地相关标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百五十九条", "text": "国家实行自然保护地分类分级管理。自然保护地按生态价值和保护强度高低依次分为国家公园、自然保护区和自然公园。自然保护区和自然公园分为国家级和省级。 国家科学规划自然保护地总体布局，严格自然保护地设立条件，合理确定自然保护地数量和规模。 各类自然保护地范围不得交叉重叠。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百六十条", "text": "国家公园的设立、名称变更、区域范围或者管控分区调整等，依照《中华人民共和国国家公园法》的规定办理。 国家级自然保护区的设立、名称变更、范围调整报国务院批准。省级自然保护区的设立、名称变更、范围调整报省、自治区、直辖市人民政府批准。 自然公园的设立、范围调整报省级以上人民政府或者其林业草原主管部门批准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百六十一条", "text": "自然保护地实行分区管控。根据生态系统特性、功能定位和管理目标，国家公园和自然保护区划分为核心保护区和一般控制区。 国家公园区域内生态系统保存完整、代表性强，核心资源集中分布，或者生态脆弱需要休养生息的区域划为核心保护区，核心保护区以外的区域划为一般控制区。 自然保护区区域内自然生态系统保存完整或者生态脆弱需要休养生息的区域、珍稀濒危野生动植物物种的关键分布区域以及生态廊道重要节点、重要自然遗迹的集中分布区域，以及其他需要重点保护的区域划为核心保护区，核心保护区以外的区域划为一般控制区。 自然公园按一般控制区管理，法律法规另有规定的，依照其规定管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百六十二条", "text": "自然保护地周边社区建设应当与自然保护地保护目标相协调，避免或者减少对自然保护地的不利影响。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百六十三条", "text": "国家对自然保护地实行整体保护，建立健全政府、企业事业单位、社会组织和公众共同参与保护的长效机制，指导、支持自然保护地内原有居民、农村集体经济组织以及自然保护地周边居民、企业等积极参与自然保护地的保护，提供与自然保护地保护目标相一致的生态产品和服务。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百六十四条", "text": "国家完善自然保护地公共服务体系，提升公共服务功能，促进社会共享自然保护地生态价值。 自然保护地一般控制区可以按照规定划定适当区域，设置必要的辅助设施设备，为开展相关科学研究、科普宣传、生态旅游、教育文化体育等公共服务活动提供支持。 自然保护地区域内不得开设与保护目标不一致的参观、旅游等项目。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百六十五条", "text": "国家加强自然保护地生态建设，尊重自然规律，建设生态廊道，开展重要栖息地恢复和废弃地修复。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百六十六条", "text": "国家公园管理机构组织编制所管理国家公园的总体规划，明确保护和管理的目标任务、保护对象、保护措施等事项，并对拟开展的生态修复活动和原有居民生产生活活动等作出安排。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百六十七条", "text": "设立国家公园后，国家公园所在地省、自治区、直辖市人民政府应当及时组织完成国家公园勘界；国家公园管理机构应当根据保护和管理需要及时设置界线标志。 禁止损毁、涂改、遮挡或者擅自拆除、移动国家公园界线标志。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百六十八条", "text": "对国家公园、自然保护区内自然生态过程、保护对象生息繁衍具有明显季节性变化规律的区域，经科学论证，在不损害生态功能的前提下，可以实行季节性差别管控措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百六十九条", "text": "在国家公园区域内开展经营性服务的，可以由国家公园管理机构以竞争性方式选择服务提供者。 第二节 长江、黄河、青藏高原等重要流域、区域"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百七十条", "text": "长江、黄河、青藏高原等重要流域、区域生态环境保护及相关工作，应当坚持生态优先、绿色发展，因地制宜、分类施策，统筹协调、科学规划、创新驱动、系统治理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百七十一条", "text": "国家根据需要在长江、黄河、青藏高原等重要流域、区域建立协调机制，统筹指导、综合协调长江、黄河、青藏高原等重要流域、区域的生态环境保护等工作。 国务院有关部门和长江、黄河、青藏高原等重要流域、区域地方各级人民政府在各自职责范围内做好相关工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百七十二条", "text": "国务院生态环境主管部门会同国务院发展改革、自然资源、水行政、农业农村等有关部门编制长江、黄河等重要流域生态环境保护规划。 国务院水行政主管部门会同有关部门编制流域综合规划。长江、黄河等重要流域的流域综合规划是水资源保护、开发、利用、节约等的重要依据。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百七十三条", "text": "长江、黄河等重要流域产业结构和布局应当与流域生态环境的承载能力相适应。禁止在流域重点生态功能区布局对生态系统有严重影响的产业。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百七十四条", "text": "国家加强长江、黄河等重要流域源头、重点水域、湖泊、库区消落区、河口生态的保护与修复，保护良好生态功能。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百七十五条", "text": "国家推动建立长江、黄河等重要流域生态系统水生生物完整性指数评价体系，组织开展水生生物完整性评价，并将结果作为评估生态系统总体状况的重要依据。重要流域水生生物完整性指数应当与水生态环境质量标准相衔接。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百七十六条", "text": "国家对长江流域江河湖泊岸线实施特殊管制，依照《中华人民共和国长江保护法》的规定划定江河湖泊岸线保护范围，制定江河湖泊岸线保护规划，严格控制岸线开发建设，促进岸线合理高效利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百七十七条", "text": "国家对跨长江流域调水实行科学论证，加强控制和管理。实施跨长江流域调水应当优先保障调出区域及其下游区域的用水安全和生态安全，统筹调出区域和调入区域用水需求。 丹江口库区及其上游所在地县级以上地方人民政府应当加强山水林田湖草沙整体保护，增强水源涵养能力，保障水质稳定达标。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百七十八条", "text": "黄河流域水资源利用，应当坚持节水优先、统筹兼顾、集约使用、精打细算，优先满足城乡居民生活用水，保障基本生态用水，统筹生产用水。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百七十九条", "text": "国家依照《中华人民共和国黄河保护法》的规定，实行黄河流域水沙统一调度制度。水沙调控应当尽量减少对水生生物及其栖息地的影响。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百八十条", "text": "国家加强对黄河流域水土流失重点预防区、治理区、重要支流源头区的水土流失防治和生态脆弱区域保护治理，开展土壤侵蚀和水土流失状况评估，实施重点防治工程。 禁止在黄河流域水土流失严重、生态脆弱区域开展可能造成水土流失的生产建设活动。确因国家战略和国计民生需要建设的，应当进行科学论证，并依法办理审批手续。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百八十一条", "text": "国家加强淮河、海河、珠江、松花江、辽河、洞庭湖、鄱阳湖、太湖、洪泽湖、巢湖等重要江河湖泊治理，巩固提升流域水源涵养、水土保持、生物多样性保护等生态功能，保障流域生态安全。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百八十二条", "text": "国家依照《中华人民共和国青藏高原生态保护法》的规定，加强对青藏高原森林、草原、湿地、江河湖泊、荒漠、雪山冰川、高原冻土、泉域等生态系统的保护，巩固提升青藏高原内国家重点生态功能区的水源涵养、生物多样性保护、水土保持、防风固沙等生态功能。 国家统筹青藏高原生态安全布局，推进山水林田湖草沙冰综合治理、系统治理、源头治理，实施重要生态系统保护修复重大工程，提升生态系统质量和多样性、稳定性、持续性，增强生态产品供给能力和生态系统服务功能，建设国家生态安全屏障战略地。 青藏高原产业结构和布局应当与青藏高原生态环境的承载能力相适应。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百八十三条", "text": "国家建立健全青藏高原生态风险防控体系，采取有效措施提高防治自然灾害、应对气候变化等生态风险防控能力和水平，保障青藏高原生态安全。 国务院有关部门和青藏高原县级以上地方人民政府及其有关部门应当加强对青藏高原建设、文化旅游、山地户外运动等活动的监督管理，切实维护青藏高原生态安全。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百八十四条", "text": "国家建立健全青藏高原雪山冰川冻土保护制度，加强对雪山冰川冻土的监测预警和系统保护，对重要雪山冰川实施封禁保护，采取有效措施，严格控制人为扰动。 国家建立健全青藏高原江河湖泊管理和保护制度，严格保护青藏高原大江大河源头等重要生态区位的天然草原，全面加强青藏高原天然林保护，加强高原湿地生态保护、泥炭资源保护。 国家对青藏高原珍贵、濒危或者特有野生动植物物种实行重点保护。 国家加强对青藏高原退化草原、退化湿地、沙化土地治理和水土流失防治的力度，综合整治重度退化土地，加强对重要江河源头区和水土流失重点预防区、治理区以及人口相对密集高原河谷区的水土流失防治。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百八十五条", "text": "海南岛全岛坚持生态优先、绿色发展，创新生态文明体制机制，持续优化生态环境质量和资源利用效率，加强生态环境损害责任追究。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百八十六条", "text": "国家加强秦岭地区生态的保护与修复，巩固提升秦岭在气候调节、水土保持、水源涵养和生物多样性保护等方面的生态功能。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百八十七条", "text": "国务院建立加强荒漠化综合防治和推进“三北”等重点生态工程建设协调机制，统筹协调解决重大问题，推动重点生态工程建设，推进重大政策实施。 国家加强“三北”工程建设区生态系统保护和修复，实行目标责任制，定期开展建设成效监测评估，保护和巩固工程建设成果。 第六章 生态退化的预防和治理 第一节 水土保持"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百八十八条", "text": "本法所称水土保持，是指对自然因素和人为活动造成水土流失所采取的预防和治理措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百八十九条", "text": "水土保持工作实行预防为主、保护优先、全面规划、综合治理、因地制宜、突出重点、科学管理、注重效益的方针。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百九十条", "text": "国务院水行政主管部门主管全国的水土保持工作。 国务院水行政主管部门在国家确定的重要江河湖泊设立的流域管理机构，在所管辖范围内依法承担水土保持监督管理职责。 县级以上地方人民政府水行政主管部门主管本行政区域的水土保持工作。 县级以上人民政府林业草原、农业农村、自然资源、生态环境等有关部门在各自职责范围内做好水土流失预防和治理相关工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百九十一条", "text": "国家建立健全水土保持相关标准。国务院水行政主管部门、标准化主管部门组织制定并完善水土流失综合治理、生产建设项目水土保持、水土流失监测等国家标准。国家标准未作规定的，可以依法制定地方标准或者行业标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百九十二条", "text": "国家在水土流失调查结果及水土流失重点预防区和重点治理区划定的基础上，编制水土保持规划。 有关基础设施建设、矿产资源开发、城镇建设、公共服务设施建设等方面的规划，以及重大产业和工程布局等实施方案，在实施过程中可能造成水土流失的，规划的组织编制机关应当在规划中提出水土流失预防和治理的对策和措施，并在规划报请审批前征求本级人民政府水行政主管部门的意见。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百九十三条", "text": "县级以上人民政府水行政主管部门应当加强水土保持监测工作，完善水土保持监测网络，定期组织水土流失调查并公告调查结果，发挥水土保持监测工作在政府决策、经济社会发展和社会公众服务中的作用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百九十四条", "text": "地方各级人民政府应当按照水土保持规划，采取封育保护、自然修复、重点治理等措施，组织单位和个人植树种草，扩大林草覆盖面积，涵养水源，加强对取土、挖砂、采石等活动的管理，预防和减轻水土流失。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百九十五条", "text": "国家按照国土空间规划和用途管控要求，建立水土保持空间管控制度，落实差别化保护治理措施。 禁止在崩塌、滑坡危险区和泥石流易发区从事取土、挖砂、采石等可能造成水土流失的活动。 限制或者禁止在水土流失严重、生态脆弱区域开展可能造成水土流失的生产建设活动。确因国家发展战略和国计民生需要建设的，应当进行科学论证，并依照《中华人民共和国水土保持法》的规定办理审批手续。 在侵蚀沟的沟坡和沟岸、河流的两岸以及湖泊和水库的周边，土地所有权人、使用权人或者有关管理单位应当营造植物保护带。禁止开垦、开发植物保护带。 禁止在二十五度以上陡坡地开垦种植农作物。在二十五度以上陡坡地种植经济林的，应当科学选择树种，合理确定规模，采取水土保持措施，防止造成水土流失。 禁止毁林、毁草开垦和采集发菜。禁止在水土流失重点预防区和重点治理区铲草皮、挖树兜或者滥挖虫草、甘草、麻黄等。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百九十六条", "text": "林木采伐应当采用合理方式，严格控制皆伐；对水源涵养林、水土保持林、防风固沙林等防护林只能进行抚育和更新性质的采伐；对采伐区和集材道应当采取防止水土流失的措施，并在采伐后及时更新造林。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百九十七条", "text": "县级以上人民政府水行政主管部门应当加强对地表扰动、土石方开挖等人为活动的管理，严格管控因人为活动造成的水土流失。 在山区、丘陵区、风沙区以及水土保持规划确定的容易发生水土流失的其他区域开办可能造成水土流失的生产建设项目，生产建设单位应当编制水土保持方案，报县级以上人民政府水行政主管部门审批，并按照经批准的水土保持方案，采取水土流失预防和治理措施。 未纳入水土保持方案管理的生产建设活动，依照生产建设活动水土流失防治标准进行水土流失防治。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百九十八条", "text": "依法应当编制水土保持方案的生产建设项目中的水土保持设施，应当与主体工程同时设计、同时施工、同时投产使用；生产建设项目竣工验收，应当验收水土保持设施；水土保持设施未经验收或者验收不合格的，生产建设项目不得投产使用。 在山区、丘陵区、风沙区以及水土保持规划确定的容易发生水土流失的其他区域开办生产建设项目或者从事其他生产建设活动，损坏水土保持设施、地貌植被，不能恢复原有水土保持功能的，应当缴纳水土保持补偿费，专项用于水土流失预防和治理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第八百九十九条", "text": "国家加强水土流失重点预防区和重点治理区的小流域综合治理提质增效、坡耕地改梯田、淤地坝、侵蚀沟治理、崩岗治理、固沟保塬等水土保持重点工程建设，加大生态修复力度。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百条", "text": "国家鼓励、支持承包治理荒山、荒沟、荒丘、荒滩，防治水土流失，保护和改善生态环境，促进土地资源的合理开发和可持续利用。 承包治理荒山、荒沟、荒丘、荒滩和承包水土流失严重地区农村土地的，在依法签订的土地承包合同中应当包括预防和治理水土流失责任的内容。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百零一条", "text": "在水力侵蚀地区，以流域水系为单元一体化推进小流域综合治理，开展坡耕地和沟道水土流失综合整治，因地制宜采取工程措施和植物措施，加强坡耕地改梯田、淤地坝等工程建设，统筹推进保护性耕作和高标准农田建设，完善田间道路、坡面水系等配套设施；建设生态清洁小流域，提供更多更优蕴含水土保持功能的生态产品。 在风力侵蚀地区，地方人民政府及其有关部门应当组织单位和个人，因地制宜采取轮封轮牧、植树种草、设置人工沙障和网格林带等措施，建立防风固沙防护体系。 在重力侵蚀地区，地方人民政府及其有关部门应当组织单位和个人，采取径流排导、削坡减载、支挡固坡、修建拦挡工程等措施，建立监测预报预警体系。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百零二条", "text": "在饮用水水源保护区，地方人民政府及其有关部门应当组织单位和个人，采取预防保护、自然修复和综合治理措施，配套建设植物过滤带，开展生态清洁小流域建设，严格控制化肥和农药的使用，减少水土流失引起的面源污染，保护饮用水水源。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百零三条", "text": "已在禁止开垦的陡坡地上开垦种植农作物的，应当按照国家规定进行生态修复；耕地短缺、退耕确有困难的，应当修建梯田或者采取其他水土保持措施。 在禁止开垦坡度以下的坡耕地上开垦种植农作物的，应当根据不同情况，采取修建梯田、坡面水系整治、蓄水保土耕作或者退耕等水土保持措施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百零四条", "text": "对生产建设活动所占用土地的地表土应当进行分层剥离、保存和利用，做到土石方挖填平衡，减少地表扰动范围。依法应当编制水土保持方案的生产建设项目，应当综合利用其排弃的砂、石、土、矸石、尾矿、废渣等；确需废弃的，应当堆放在水土保持方案确定的存放地，并采取拦挡、坡面防护、防洪排导等措施。生产建设活动结束后，应当及时在取土场、开挖面和存放地的裸露土地上植树种草、恢复植被。 在干旱缺水地区从事生产建设活动，应当采取防止风力侵蚀措施，设置降水蓄渗设施，充分利用降水资源。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百零五条", "text": "国家鼓励、支持在山区、丘陵区、风沙区以及容易发生水土流失的其他区域，采取下列有利于水土保持的措施： （一）免耕、等高耕作、轮耕轮作、草田轮作、间作套种等； （二）封禁抚育、轮封轮牧、舍饲圈养； （三）发展生物质能，利用太阳能、风能和水能，以煤、电、气代替薪柴等； （四）从生态脆弱地区向外移民； （五）其他有利于水土保持的措施。 第二节 防沙治沙"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百零六条", "text": "本法所称土地沙化，是指主要因人类不合理活动所导致的天然沙漠扩张和沙质土壤上植被及覆盖物被破坏，形成流沙及沙土裸露的过程。 本法所称沙化土地，包括已经沙化的土地和具有明显沙化趋势的土地。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百零七条", "text": "防沙治沙坚持预防为主、防治结合、合理利用、统一规划、因地制宜、因害设防、分类施策的原则。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百零八条", "text": "国务院林业草原主管部门负责组织、协调、指导全国防沙治沙工作。 国务院林业草原、农业农村、水行政、自然资源、生态环境、气象等有关部门在各自职责范围内共同做好防沙治沙工作。 县级以上地方人民政府组织、领导有关部门密切配合共同做好本行政区域的防沙治沙工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百零九条", "text": "国务院林业草原主管部门会同有关部门依照《中华人民共和国防沙治沙法》的规定编制全国防沙治沙规划。县级以上地方人民政府可以根据实际需要，组织编制本行政区域的防沙治沙规划。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百一十条", "text": "国家加强荒漠化综合防治，积极推进防沙治沙，重点开展沙漠边缘、沙源区和路径区生态修复，加强自然生态空间管控以及沙生植物保护，推行保护性耕作措施，实施防护林建设等生态工程，在岩溶地区开展石漠化综合治理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百一十一条", "text": "沙化土地所在地区的县级以上地方人民政府应当按照防沙治沙规划，划出一定比例的土地，因地制宜营造防风固沙林网、林带，种植多年生灌木和草本植物。 除了抚育更新性质的采伐外，不得批准对防风固沙林网、林带进行采伐。在对防风固沙林网、林带进行抚育更新性质的采伐之前，应当在其附近预先形成接替林网和林带。对林木更新困难地区已有的防风固沙林网、林带，不得批准采伐。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百一十二条", "text": "禁止在沙化土地上砍挖灌木、药材及其他固沙植物，法律、行政法规另有规定的除外。 沙化土地所在地区的县级人民政府，应当建立植被管护制度，完善管护组织体系，建设管护设施，严格保护植被。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百一十三条", "text": "沙化土地所在地区的县级以上地方人民政府水行政主管部门，应当加强流域和区域水资源的统一调配和管理，防止因地下水和上游水资源的过度开发利用，导致植被破坏和土地沙化。 沙化土地所在地区的县级以上地方人民政府，不得批准在沙漠边缘地带和林地、草原开垦耕地；已经开垦并对生态产生不良影响的，应当有计划地组织退耕还林还草。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百一十四条", "text": "国家建立沙化土地封禁保护区制度。对暂不具备治理条件的连片沙化土地，应当规划为沙化土地封禁保护区。 在沙化土地封禁保护区范围内，禁止破坏植被的活动。禁止在沙化土地封禁保护区范围内安置移民。未经批准，不得在沙化土地封禁保护区范围进行修建铁路、公路等建设活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百一十五条", "text": "沙化土地所在地区的地方各级人民政府，应当按照防沙治沙规划，组织有关部门、单位和个人，因地制宜采取工程措施、生物措施和合理调配生态用水等措施，恢复和增加植被，防止土地沙化，治理已经沙化的土地。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百一十六条", "text": "国家鼓励单位和个人在自愿的前提下，捐资或者以其他形式开展公益性的治沙活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百一十七条", "text": "使用已经沙化的国有土地的使用权人和农民集体所有土地的承包经营权人，应当采取治理措施，改善土地质量。 采取退耕还林还草、植树种草或者封育措施治沙的土地使用权人和承包经营权人，按照国家规定享受政策优惠。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百一十八条", "text": "在沙化土地范围内从事种植、养殖、旅游、风电、光伏发电等生产经营活动，应当采取措施防止土地沙化。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百一十九条", "text": "沙化土地所在地区的地方各级人民政府，可以组织当地农村集体经济组织及其成员在自愿的前提下，对已经沙化的土地进行集中治理。 第七章 生态修复"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百二十条", "text": "各级人民政府及有关部门开展生态修复活动，以及依法承担生态修复责任的单位和个人开展生态修复活动，应当遵守本章的有关规定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百二十一条", "text": "生态修复应当建立健全源头保护和全过程修复治理相结合的工作机制，实现整体保护、系统修复、综合治理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百二十二条", "text": "国务院自然资源主管部门应当会同有关部门组织实施重大生态修复项目，统筹重点流域和重要区域生态的保护与修复工作。 国务院生态环境主管部门在其职责范围内指导协调和监督生态的保护与修复工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百二十三条", "text": "县级以上人民政府自然资源主管部门会同有关部门依法编制国土空间生态修复规划。 国务院有关部门在各自职责范围内组织编制生态修复等相关专项规划。县级以上地方人民政府按照国家规定，在本行政区域组织实施生态修复等相关专项规划。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百二十四条", "text": "编制生态修复规划、设计项目方案，应当充分征求有关方面的意见、科学论证，确定生态修复的目标、内容、实施方案、修复技术措施等。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百二十五条", "text": "国务院自然资源、生态环境主管部门会同有关部门对重大生态修复项目的实施开展动态监测。 地方人民政府有关部门在各自职责范围内对各类生态修复项目的实施开展动态监测。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百二十六条", "text": "国务院有关部门在各自职责范围内建立健全生态修复实施过程的监督机制，对重大生态修复项目进行跟踪检查。 地方人民政府有关部门加强对各类生态修复项目的监督，及时组织开展跟踪检查。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百二十七条", "text": "生态修复项目竣工后，县级以上人民政府有关部门在各自职责范围内针对各类生态修复项目的不同特点，组织开展生态修复项目的验收。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百二十八条", "text": "国家实施生态修复项目后期管护制度。 生态修复项目验收合格后，县级以上人民政府及其有关部门应当确定后期管护责任主体，明确管护内容、管护措施、管护周期和资金来源等。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百二十九条", "text": "国家鼓励、支持生态修复的科学技术研究开发和推广应用，提升生态修复领域自主创新能力，提升生态修复科学化、专业化水平。 国务院自然资源主管部门会同有关部门制定生态修复相关标准、规范并组织实施。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百三十条", "text": "国家坚持政策支持、企业和社会参与、市场化运作，采取有效措施鼓励社会资本参与生态修复项目投资、设计、修复、管护等全过程活动。 国家建立生态修复资金保障制度，支持设立绿色基金、生态专项债券，鼓励社会捐赠，拓宽生态修复资金渠道。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百三十一条", "text": "各级人民政府应当科学保护和修复森林生态系统，加强生态脆弱地区森林生态系统的保护与修复。新造幼林地和其他应当封山育林的地方，由当地人民政府组织封山育林。 各级人民政府应当对自然因素等导致的荒废和受损山体、退化林地以及宜林荒山荒地荒滩，因地制宜实施森林生态修复工程，恢复植被。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百三十二条", "text": "国家加强生态脆弱草原保护。对退化、沙化、盐碱化、石漠化和水土流失的草原，地方各级人民政府应当按照草原保护修复利用规划，组织生态的保护与修复，提高生态系统稳定性。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百三十三条", "text": "县级以上人民政府应当坚持系统治理，加强湿地修复工作，恢复湿地面积，提高湿地生态系统质量。 县级以上人民政府对破碎化严重或者功能退化的自然湿地进行综合整治和修复，优先修复生态功能严重退化的重要湿地。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百三十四条", "text": "对遭到破坏的具有重要生态、经济、社会价值的海洋生态系统，应当进行修复。海洋生态修复应当以改善动植物栖息生长环境、恢复生物多样性和生态系统基本功能为重点，以自然恢复为主、人工修复为辅，并优先修复具有典型性、代表性的海洋生态系统。 国务院自然资源主管部门负责统筹海洋生态修复，牵头组织编制海洋生态修复规划并实施有关海洋生态修复重大工程。编制海洋生态修复规划，应当进行科学论证评估。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百三十五条", "text": "县级以上人民政府应当加强对生态恶化江河湖泊的治理和修复，统筹运用生态补水、生物净化、生态清淤、江河湖泊连通等措施，对江河湖泊生态系统进行综合治理，改善和恢复江河湖泊生态系统。 入海河口所在地县级以上地方人民政府及其有关部门按照河海联动的要求，制定实施河口生态修复和其他保护措施方案，加强对水、沙、盐、潮滩、生物种群、河口形态的综合监测，采取有效措施防止海水入侵和倒灌，维护河口良好生态功能。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百三十六条", "text": "开采矿产资源前，采矿权人应当依法编制矿区生态修复方案。采矿权人应当按照经批准的矿区生态修复方案进行矿区生态修复。 采矿权人应当按照规定提取矿区生态修复费用，专门用于矿区生态修复。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百三十七条", "text": "国家建立健全生态修复成效评估机制，制定和完善生态修复效果的评估标准、技术指南等。 国务院自然资源、生态环境等主管部门应当在各自职责范围内开展生态修复成效评估。 县级以上人民政府及其有关部门应当加强生态修复成效评估工作。 第四编 绿色低碳发展 第一章 一般规定"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百三十八条", "text": "本编适用于发展循环经济、能源节约与绿色低碳转型、应对气候变化等绿色低碳发展相关活动。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百三十九条", "text": "国家建立健全绿色低碳发展机制，完善绿色低碳转型政策体系，加快经济社会发展全面绿色转型，形成有利于节约资源和保护生态环境的空间格局、产业结构、生产方式、生活方式。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百四十条", "text": "国家采取有效措施推动各类资源节约集约循环利用，促进生产、流通、消费过程中减少污染物和温室气体的产生、排放，提高资源利用效率，建设绿色低碳循环发展经济体系。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百四十一条", "text": "国家推进节能降碳增效，加强化石能源清洁高效利用和安全可靠有序替代，大力发展非化石能源，稳妥推进能源绿色低碳转型，加快建设清洁低碳安全高效的新型能源体系，建设能源强国。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百四十二条", "text": "国家采取积极应对气候变化的政策和措施，控制和减少温室气体排放，积极稳妥推进碳达峰碳中和，增强适应气候变化能力，提高全社会的应对气候变化意识。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百四十三条", "text": "国家强化区域重大战略实施中的绿色低碳发展导向和任务要求，构建绿色低碳高质量发展空间格局。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百四十四条", "text": "国家推动钢铁、有色金属、石化、化工、建材、造纸、印染等行业绿色低碳转型，推广节能低碳和清洁生产技术装备，推进工艺流程更新升级，完善能源效率、碳排放等相关约束性标准，促进传统产业优化升级。 国家促进绿色低碳产业发展，培育壮大新能源、生物制造等新兴产业和未来产业，建设绿色制造和服务体系，逐步提升绿色低碳产业在经济总量中的比重。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百四十五条", "text": "国家优化交通运输结构，完善交通运输网络，推动铁路、公路、水运、航空不同运输方式合理分工、有效衔接，构建绿色高效交通运输体系。 国家建设绿色交通基础设施，优先发展公共交通，推广低碳交通运输工具，推动使用清洁动力，积极引导绿色出行。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百四十六条", "text": "国家倡导绿色低碳规划设计理念，推广绿色建造方式，优化建筑用能结构，支持超低能耗、低碳建筑规模化发展，推动绿色低碳和气候适应型城市建设。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百四十七条", "text": "国家推动农业农村绿色低碳发展，加快绿色技术推广应用，引导农业生产经营者科学合理使用生产资料，加强农业废弃物资源化利用，优先发展生态农业。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百四十八条", "text": "国家建立健全绿色低碳标准体系。 国务院有关部门和县级以上地方人民政府应当采取有效措施，促进绿色低碳产品标准实施和认证结果、标识信息的使用与效果评价。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百四十九条", "text": "国家机关和其他使用财政性资金的公共机构应当率先贯彻绿色低碳理念，厉行节约、反对浪费，推进绿色办公、绿色采购，使用绿色低碳产品，发挥绿色低碳转型示范引领作用。 企业应当加大绿色低碳技术和产品的研究开发、推广应用，推进生产经营活动绿色化，提高资源利用效率，减少污染物和温室气体的产生、排放，自觉履行绿色低碳发展社会责任。 公民应当增强绿色低碳意识，积极参与绿色消费、绿色出行、“光盘行动”、生活垃圾分类等绿色低碳活动，反对铺张浪费，形成文明健康的生活方式和消费模式。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百五十条", "text": "国家优化绿色转型投资机制，加大对绿色低碳先进适用技术示范、重点行业节能降碳、资源高效循环利用等领域重点项目的财政投入，引导和规范社会资本参与绿色低碳项目投资、建设、运营，鼓励社会资本以市场化方式设立绿色低碳产业投资基金。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百五十一条", "text": "国家加强绿色低碳领域应用基础研究，鼓励、支持资源节约与循环利用、能源绿色低碳转型、减缓和适应气候变化相关技术研究开发，加快先进适用技术示范和推广应用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百五十二条", "text": "国家加强绿色经贸、技术、金融、标准等领域国际合作，鼓励绿色低碳技术、产品和服务进出口，积极参与国际规则和标准制定，引领全球绿色转型。 第二章 发展循环经济 第一节 一般规定"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百五十三条", "text": "发展循环经济应当坚持减量化、再利用、资源化，遵循统筹规划、合理布局，因地制宜、注重实效，政府推动、市场引导，企业实施、公众参与的方针。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百五十四条", "text": "国务院发展改革部门负责组织协调、监督管理全国的循环经济发展工作；国务院生态环境、工业和信息化、住房城乡建设等有关部门在各自职责范围内，负责有关循环经济的监督管理工作。 县级以上地方人民政府发展改革部门负责组织协调、监督管理本行政区域的循环经济发展工作；县级以上地方人民政府生态环境、工业和信息化、住房城乡建设等有关部门在各自职责范围内，负责有关循环经济的监督管理工作。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百五十五条", "text": "国务院发展改革部门会同国务院生态环境等有关部门编制全国循环经济发展规划，报国务院批准后公布实施。 设区的市级以上地方人民政府发展改革部门会同生态环境等有关部门编制本行政区域循环经济发展规划，报本级人民政府批准后公布实施。 循环经济发展规划应当包括规划目标、适用范围、主要内容、重点任务和保障措施等。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百五十六条", "text": "国家制定产业政策，应当符合发展循环经济的要求。 国家支持在技术可行、经济合理和有利于保护生态环境的前提下，推广资源循环型生产模式，促进资源循环利用产业集约化、规模化发展。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百五十七条", "text": "国务院标准化主管部门会同国务院发展改革、生态环境、工业和信息化等有关部门制定绿色设计、绿色制造、产业废弃物综合利用、生活垃圾回收利用等循环经济标准。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百五十八条", "text": "国家建立健全循环经济统计制度，加强资源消耗、综合利用、废弃物产生等的统计管理，并将主要统计指标定期向社会公布。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百五十九条", "text": "国家建立健全生产者责任延伸制度，促进资源循环利用。 第二节 清洁生产"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百六十条", "text": "国家鼓励通过开展绿色设计、使用清洁的能源和原料、采用先进适用的工艺技术与设备等措施，从源头降低资源消耗，减少污染物和温室气体的产生、排放，推进清洁生产。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百六十一条", "text": "国务院发展改革部门会同国务院生态环境、工业和信息化等有关部门编制全国清洁生产推行方案，报国务院批准后公布。全国清洁生产推行方案应当包括推进清洁生产的目标、主要任务和保障措施，确定开展清洁生产的重点领域、重点行业和重点工程。 国务院有关行业主管部门根据全国清洁生产推行方案，确定本行业推进清洁生产的重点任务和重点项目，并组织落实。 县级以上地方人民政府根据全国清洁生产推行方案，按照本行政区域节约资源、降低能源消耗、减少污染物和温室气体排放的要求，制定推进清洁生产的实施方案，并组织落实。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百六十二条", "text": "中央预算应当加强对清洁生产推进工作的资金投入，包括中央财政清洁生产专项资金和中央预算安排的其他清洁生产资金，用于支持全国清洁生产推行方案确定的重点领域、重点行业、重点工程实施清洁生产及其技术推广工作，以及生态脆弱地区实施清洁生产的项目。中央预算用于支持清洁生产推进工作的资金使用的具体办法，由国务院财政、发展改革部门会同有关部门制定。 县级以上地方人民政府应当统筹地方财政安排的清洁生产推进工作的资金，引导社会资金支持清洁生产重点项目。 在按照国家规定设立的中小企业发展基金中，应当根据需要安排适当数额用于支持中小企业实施清洁生产。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百六十三条", "text": "国务院发展改革部门会同国务院生态环境、工业和信息化、科学技术、住房城乡建设、农业农村、林业草原等有关部门定期发布清洁生产技术、工艺、设备和产品导向目录。 县级以上地方人民政府应当指导和支持清洁生产技术、工艺、设备和产品的研究开发，以及清洁生产技术示范和推广应用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百六十四条", "text": "省级以上人民政府发展改革、生态环境、工业和信息化部门会同有关部门，组织编制重点行业或者地区的清洁生产指南，指导实施清洁生产。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百六十五条", "text": "企业在进行技术改造过程中，应当采取以下清洁生产措施： （一）采用无毒无害或者低毒低害的原料，替代毒性大、危害严重的原料； （二）采用资源利用率高、污染物和温室气体产生量少的工艺和设备，替代资源利用率低、污染物和温室气体产生量多的工艺和设备； （三）对生产过程中产生的废弃物进行综合利用； （四）采用能够达到国家或者地方规定的污染物排放标准和污染物排放总量控制指标的污染防治技术。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百六十六条", "text": "企业应当对生产和服务过程中的资源消耗以及废弃物的产生情况进行监测，并根据需要对生产和服务实施清洁生产审核。 国家加强清洁生产审核结果应用，将其作为用水定额等差异化政策制定和实施的重要依据。 清洁生产审核的具体办法，由国务院发展改革、生态环境部门会同有关部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百六十七条", "text": "有下列情形之一的企业，应当实施强制性清洁生产审核： （一）污染物排放超过国家或者地方规定的排放标准，或者虽未超过国家或者地方规定的排放标准，但超过重点污染物排放总量控制指标的； （二）使用有毒有害原料进行生产或者在生产中排放有毒有害物质的； （三）国家规定应当实施强制性清洁生产审核的其他情形。 污染物排放超过国家或者地方规定的排放标准的企业，应当按照本法的规定承担法律责任。 实施强制性清洁生产审核的企业，应当将审核结果向所在地县级以上地方人民政府发展改革、生态环境部门报告，并采取便于公众知晓的方式公开，接受公众监督，但涉及商业秘密的除外。 县级以上地方人民政府有关部门应当对企业实施强制性清洁生产审核的情况进行监督，必要时可以组织对企业实施清洁生产的效果进行评估验收，所需费用纳入同级政府预算。承担评估验收工作的部门或者单位不得向被评估验收企业收取费用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百六十七条", "text": "第一款规定以外的企业可以按照国家规定，自愿与发展改革、生态环境、工业和信息化部门签订节约资源、减少污染物排放的协议。发展改革、生态环境、工业和信息化部门应当采取便于公众知晓的方式，公布企业的名称和节约资源、防治污染的成果。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百六十九条", "text": "生产大型机电设备、机动运输工具以及国务院工业和信息化主管部门指定的其他产品的企业，应当按照国务院标准化主管部门或者其授权机构制定的技术规范，在产品的主体构件上注明材料成分的标准牌号。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百七十条", "text": "国务院和省、自治区、直辖市人民政府的有关部门，应当组织和支持建立清洁生产信息系统和技术咨询服务体系。 国家鼓励提供清洁生产咨询、审核等服务的机构开展清洁生产知识宣传和技术培训。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百七十一条", "text": "企业用于清洁生产审核和培训的费用，可以列入企业经营成本。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百七十二条", "text": "国家鼓励产品的生产经营者开展绿色设计，推动绿色设计应用。 电器电子、机动车等产品的设计，应当考虑其在生命周期中对人体健康和生态环境的影响，优先选择无毒无害、易于降解或者便于回收利用的方案，按照国家规定加强有害物质源头减量和替代。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百七十三条", "text": "国家鼓励产品的生产经营者使用绿色包装、减量包装。 国务院标准化主管部门应当根据国家经济和技术条件、固体废物污染防治状况以及产品的技术要求，组织制定有关标准，防止过度包装造成资源浪费和环境污染。 生产经营者对产品的包装应当合理，遵守限制商品过度包装的强制性标准，减少包装性废弃物的产生，不得进行过度包装。包装的材质、结构和成本应当与内装产品的质量、规格和成本相适应。 县级以上地方人民政府市场监督管理等有关部门应当在各自职责范围内，加强对过度包装的监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百七十四条", "text": "电子商务、快递、外卖等行业应当减少包装物的使用，优先采用可重复使用、易回收利用的包装物，并积极回收利用。县级以上地方人民政府商务、邮政管理等有关部门应当加强监督管理。 第三节 废弃物循环利用"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百七十五条", "text": "国家推进废弃物循环利用体系建设，促进生产生活各领域废弃物精细管理、有效回收、高效利用，提升废弃物循环利用水平。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百七十六条", "text": "企业应当采用先进适用的回收技术、工艺和设备，对生产过程中产生的余热、余压、废水、废液等进行综合利用。 企业应当按照国家规定，对生产过程中产生的粉煤灰、煤矸石、磷石膏、赤泥、尾矿、废石、废料、废气等工业废弃物进行综合利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百七十七条", "text": "生产、进口、销售依法列入强制回收名录的产品和包装物的企业，应当按照国家规定对该产品和包装物进行回收。对其中可以利用的，由企业负责利用；对因不具备技术经济条件而不适合利用的，由企业负责无害化处置。 对前款规定的废弃产品或者包装物，生产者委托销售者或者其他组织进行回收，或者委托废弃物利用、处置企业进行利用、处置的，受托方应当依照有关法律、行政法规的规定和合同的约定负责回收或者利用、处置。 强制回收的产品和包装物的名录及管理办法，由国务院发展改革部门会同有关部门制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百七十八条", "text": "电器电子、机动车、铅蓄电池、动力电池等产品的生产者应当按照国家规定，以自建或者委托等方式建立与产品销售量相匹配的废旧产品回收体系，并向社会公开，履行回收和利用责任。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百七十九条", "text": "国家建立健全风电和光伏发电退役设备处理责任制度。 从事风电、光伏发电建设运营的企业，应当自行或者委托具备条件的企业对退役风电机组叶片、光伏组件等进行循环利用或者无害化处置。 国家推进数据中心、通信基站等新型基础设施领域废弃物循环利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百八十条", "text": "国家支持生产经营者建立产业废弃物交换信息系统，促进企业交流产业废弃物信息。 企业对生产过程中产生的废弃物不具备综合利用条件的，应当提供给具备条件的生产经营者进行综合利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百八十一条", "text": "国家鼓励、支持农业生产经营者和相关企业采用先进适用技术，对农作物秸秆、畜禽粪便、农产品加工业副产品、废农用薄膜等进行综合利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百八十二条", "text": "国家鼓励采用先进适用技术、工艺、设备、材料和管理措施，推进建筑垃圾源头减量，建立健全建筑垃圾回收利用体系。 县级以上地方人民政府应当推动建筑垃圾综合利用产品应用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百八十三条", "text": "国家加强生活垃圾分类收集、处理和资源化利用，推进生活垃圾减量化、资源化。 县级以上地方人民政府有关部门应当统筹规划，合理布局回收、分拣、打包网点，促进生活垃圾回收利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百八十四条", "text": "国家推进生活垃圾分类网点和废旧物资回收网点融合建设，完善城乡废旧物资回收网络。 地方人民政府应当按照国土空间规划，合理布局废旧物资回收网点和交易市场，支持废旧物资回收企业和其他组织开展废旧物资的收集、储存、运输及信息交流。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百八十五条", "text": "国家完善低值可回收物目录，促进废玻璃、废塑料、废旧纺织品等回收利用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百八十六条", "text": "国家加强废钢铁、废有色金属等高效利用，推动再生金属加工利用产业集聚化发展。 国家鼓励企业提升废有色金属利用技术水平，支持从废弃电器电子产品等废弃物中提取稀贵金属技术的研究开发、推广应用。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百八十七条", "text": "企业利用废弃物和从废弃物中回收原料生产产品，应当采用先进适用的技术、工艺和设备，提高回收利用率和加工利用水平。 对废弃电器电子产品、报废机动车船和飞机、废轮胎、废铅蓄电池、废旧动力电池等特定产品进行拆解、处置或者再利用，应当符合本法和《中华人民共和国循环经济促进法》等有关法律法规的规定，禁止使用国家明令淘汰或者不符合生态环境保护要求的落后拆解加工技术、工艺和设备。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百八十八条", "text": "国家对废弃电器电子产品等实行多渠道回收和集中处理制度。废弃电器电子产品等回收处理的具体管理办法由国务院制定。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百八十九条", "text": "国家支持企业开展机动车零部件、工程机械、机床、文化办公设备等产品的再制造和轮胎翻新，推动风电、光伏发电、航空等领域高端装备再制造产业发展，鼓励再制造产品推广使用。 再制造产品和翻新产品的质量应当符合国家规定的标准，并在显著位置标识为再制造产品或者翻新产品。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百九十条", "text": "国家鼓励再生材料推广应用，建立健全再生材料标准和认证制度，支持机动车、电器电子等产品的生产者提高再生材料使用比例。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百九十一条", "text": "依法利用废弃物和从废弃物中回收原料生产产品的，按照国家规定享受税收等优惠。 第四节 绿色消费"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百九十二条", "text": "国家建立健全绿色消费激励机制，扩大绿色低碳产品供给，加强绿色消费宣传教育，推广绿色低碳生活方式，推动消费模式绿色转型。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百九十三条", "text": "国家实行有利于资源节约和合理利用的价格、税收等政策，引导单位和个人节约和合理使用水、电、气等资源性产品。 县级以上人民政府应当采取有效措施，鼓励绿色低碳产品消费，按照国家规定支持消费品以旧换新。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百九十四条", "text": "国家建立健全政府绿色采购制度，鼓励、支持将再生材料和产品纳入政府绿色采购范围。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百九十五条", "text": "国家鼓励、支持二手商品流通交易，推动二手商品交易市场和平台建设。二手商品流通管理办法由国务院商务部门会同有关部门制定。 县级以上地方人民政府市场监督管理、商务等有关部门应当在各自职责范围内，加强对二手商品交易的监督管理。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百九十六条", "text": "国家鼓励、引导消费者使用绿色包装、减量包装。 对列入强制回收名录的产品和包装物，消费者应当将废弃的产品和包装物交给生产者或者其委托回收的销售者、其他组织。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百九十七条", "text": "国家在保障产品安全和卫生的前提下，限制一次性用品的生产和销售。 旅游、住宿等行业应当按照国家规定，不主动提供一次性用品。 机关、企业事业单位、社会团体等在办公场所应当减少使用一次性用品。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百九十八条", "text": "国家依法禁止和限制生产、销售、使用不可降解塑料袋等一次性塑料制品，鼓励、引导减少使用和积极回收一次性塑料制品，推广应用可循环、易回收、可降解且无害的替代产品。 商品零售场所开办单位、电子商务平台企业和快递企业、外卖企业应当按照国家规定，向商务、邮政管理等部门报告一次性塑料制品的使用、回收情况。"}, {"law": "中华人民共和国生态环境法典_20260312.docx", "no": "第九百九十九条", "text": "公民应当增强绿色消费意识，养成绿色消费习惯，积极购买和使用绿色低碳产品，主动减少使用一次性用品、一次性塑料制品，自觉抵制过度包装。 第一千条 企业应当按照国家规定实施绿色采购，建立绿色供应链，优先采购和使用节能、节水、节材等有利于保护生态环境的原材料、产品和服务，促进上下游企业协同绿色转型。 第一千零一条 餐饮、娱乐、宾馆等服务性企业应当按照国家规定，采用节能、节水、节材等有利于保护生态环境的技术、设备和设施，提供绿色低碳产品，减少使用或者不使用浪费资源、污染环境的消费品。 第三章 能源节约与绿色低碳转型 第一节 一般规定 第一千零二条 能源绿色低碳发展应当坚持节约优先、集约高效、创新驱动、保障安全、有序转型的原则。 第一千零三条 国家完善能源开发利用政策，优化能源供应结构和消费结构，积极推动能源绿色低碳发展。 第一千零四条 国家推动节约能源和提高能源利用效率，鼓励发展分布式能源和多能互补、多能联供综合能源服务，积极推广合同能源管理等市场化节约能源服务，通过完善阶梯价格、分时价格等制度，引导能源用户合理调整用能方式、时间、数量等，提高终端能源消费清洁化、低碳化、高效化、智能化水平。 第一千零五条 国家鼓励、支持化石能源清洁高效开发利用、可再生能源开发利用、核能安全利用以及储能、节约能源等能源绿色低碳发展相关领域基础性、关键性和前沿性重大技术、装备及相关新材料的研究开发、推广应用和产业化发展。能源绿色低碳科技创新应当纳入国家科技发展和高技术产业发展相关规划的重点支持领域。 国家支持先进信息技术在能源领域的应用，推动能源生产和供应的数字化、智能化发展，以及多种能源协同转换与集成互补。 第一千零六条 县级以上人民政府应当加强农业农村节能工作，增加对农业农村节能技术、节能产品推广应用的资金投入。 国家鼓励、支持农村地区的可再生能源综合开发利用，因地制宜推广应用生物质能、太阳能和风能等可再生能源利用技术。 第二节 能源节约 第一千零七条 国务院发展改革部门负责全国的节能监督管理工作。国务院有关部门在各自职责范围内负责节能监督管理工作，并接受国务院发展改革部门的指导。 县级以上地方人民政府节能主管部门负责本行政区域的节能监督管理工作。县级以上地方人民政府有关部门在各自职责范围内负责节能监督管理工作，并接受同级节能主管部门的指导。 第一千零八条 国务院标准化主管部门和国务院有关部门依法组织制定并适时修订有关节能的国家标准、行业标准。 第一千零九条 国家实行固定资产投资项目节能审查制度，对项目用能和碳排放情况开展综合评价。具体办法由国务院发展改革部门会同有关部门制定。 第一千零一十条 县级以上人民政府节能主管部门应当会同有关部门加强对重点用能单位的节能管理。 重点用能单位应当每年向节能主管部门报送能源利用状况报告。节能主管部门应当对重点用能单位报送的能源利用状况报告进行审查。 重点用能单位的范围适用《中华人民共和国节约能源法》的有关规定。 第一千零一十一条 国家对家用电器等使用面广、耗能量大的用能产品，实行能源效率标识管理。能源效率标识管理的产品目录和具体管理办法，由国务院发展改革部门会同国务院市场监督管理部门制定并公布。 第三节 能源绿色低碳转型 第一千零一十二条 国家支持优先开发利用可再生能源，合理开发、清洁高效利用化石能源，推进非化石能源安全可靠有序替代化石能源，提高非化石能源消费比重。 第一千零一十三条 国务院能源主管部门和国务院有关部门依照本法和《中华人民共和国能源法》、《中华人民共和国可再生能源法》等法律的规定，负责能源绿色低碳转型有关工作。 第一千零一十四条 国家建立健全煤炭清洁高效利用机制，支持洁净煤技术的研究开发、推广应用，积极有序推进散煤替代，推动煤炭清洁高效燃烧和转化，促进煤炭分质分级利用，提升煤炭清洁高效利用水平。 国家鼓励发展煤电联营，支持煤炭开采和上下游产业一体化布局，有序推进煤炭深加工产业发展，淘汰落后用煤技术和设备，采用先进煤电技术降低供电煤耗，推进煤电、钢铁、建材、化工等重点用煤行业节能降碳改造。 第一千零一十五条 国家鼓励、支持煤炭绿色智能开采，因地制宜采用保水开采、充填开采等绿色开采技术，减少对地质地貌和生态环境的影响。 煤矿企业应当按照国家规定提升煤炭洗选加工水平，提高原煤入选率。 县级以上地方人民政府和煤矿企业应当加强资源综合开发和系统治理，统筹开发利用煤炭共伴生资源，开展煤层气开采利用，提高煤矸石、煤泥等清洁利用水平，科学合理利用关闭煤矿残存资源和地下空间。 第一千零一十六条 国家鼓励石油、天然气绿色高效开发，支持石油、天然气勘探开发与可再生能源融合发展。 国家鼓励采用先进、集约的石油加工转换方式。 国家支持合理开发利用可替代石油、天然气的新型燃料和工业原料。 第一千零一十七条 国家推进风能、太阳能开发利用，坚持集中式与分布式并举，加快风电和光伏发电基地建设，支持分布式风电和光伏发电就近开发利用，合理有序开发海上风电，积极发展光热发电。 国家鼓励合理开发利用生物质能，促进海洋能规模化开发利用，因地制宜发展地热能。 国家统筹水电开发和生态保护，严格控制开发建设小型水电站。 国家积极安全有序发展核电。 第一千零一十八条 国务院能源主管部门会同有关部门制定非化石能源开发利用中长期发展目标，按年度监测非化石能源开发利用情况，并向社会公布。 第一千零一十九条 国务院能源主管部门会同有关部门制定并组织实施可再生能源在能源消费中的最低比重目标。 第一千零二十条 国家完善可再生能源电力消纳保障机制。供电企业、售电企业、相关电力用户和使用自备电厂供电的企业等应当按照国家规定，承担消纳可再生能源发电量的责任。 第一千零二十一条 国家建立健全绿色能源消费促进机制，实施可再生能源绿色电力证书等制度，鼓励能源用户优先使用可再生能源等清洁低碳能源。 第一千零二十二条 国家加快构建新型电力系统，加强电源电网协同建设，优化电力跨区域通道布局，发挥特高压输电通道稳定安全可靠作用，推进电网基础设施智能化改造和智能微电网建设，提高电网对可再生能源的接纳、配置和调控能力。 第一千零二十三条 国家合理布局、积极有序开发建设抽水蓄能电站，推进新型储能高质量发展，发挥各类储能在电力系统中的调节作用。 第一千零二十四条 国家积极有序推进氢能开发利用，促进氢能产业高质量发展。 第四章 应对气候变化 第一节 一般规定 第一千零二十五条 国家坚持减缓与适应并重，采取有效措施积极应对气候变化。 第一千零二十六条 国务院生态环境主管部门负责全国的应对气候变化工作。国务院发展改革部门负责全国碳达峰碳中和工作的管理协调。国务院其他有关部门在各自职责范围内，负责应对气候变化与碳达峰碳中和有关工作。 县级以上地方人民政府及其有关部门应当加强本行政区域的应对气候变化与碳达峰碳中和工作，采取减缓和适应措施，控制和减少温室气体排放。 第一千零二十七条 国家建立健全国务院有关部门参与的决策协调机制，统一部署应对气候变化与碳达峰碳中和有关工作，协调解决相关重大问题，督促重要目标任务落实。 第一千零二十八条 国家加强温室气体与气候系统监测，建立健全气候变化监测发布制度。 第一千零二十九条 国家建立应对气候变化信息共享机制，推动相关资源、数据交流共享。 第一千零三十条 国家通过加强生态系统保护、修复和可持续管理，发挥生态系统服务功能，增强应对气候变化的能力。 第一千零三十一条 国家强化应对气候变化基础研究和科技支撑，把应对气候变化作为国家基础研究和科技创新的重点领域，加强关键核心技术研究开发、推广应用。 第二节 减缓气候变化与碳达峰碳中和 第一千零三十二条 国家将碳达峰碳中和目标要求全面融入国家发展规划，通过碳达峰碳中和目标推动减缓气候变化。 国家实施碳排放总量和强度控制制度，基于碳达峰碳中和目标科学合理确定碳排放指标。 第一千零三十三条 推进碳达峰碳中和应当坚持全国统筹、节约优先、双轮驱动、内外通畅、防范风险的原则。 第一千零三十四条 国务院发展改革部门会同有关部门编制国家碳达峰碳中和行动方案并组织实施。省、自治区、直辖市人民政府结合实际情况，制定本行政区域碳达峰碳中和行动方案并组织实施。 第一千零三十五条 国家建立健全碳排放统计核算制度。 国务院统计部门负责组织开展全国碳排放统计核算工作。 国务院生态环境、市场监督管理部门会同有关部门组织制定重点行业的企业碳排放核算标准和技术规范。国务院生态环境、统计部门会同有关部门建立国家温室气体排放因子数据库并定期更新。 本法所称温室气体排放因子，是指单位生产或者消费活动量的温室气体排放的系数。 第一千零三十六条 国务院生态环境、市场监督管理、发展改革等有关部门在各自职责范围内开展产品碳足迹管理，制定产品碳足迹核算标准和技术规范，建立产品碳足迹核算、分级管理、标识认证和信息披露制度。 本法所称碳足迹，是指以二氧化碳当量表示的温室气体排放量和温室气体清除量的总和。 第一千零三十七条 国家建立全国碳排放权交易市场。纳入全国碳排放权交易市场的温室气体重点排放单位，应当按照国家规定履行强制减排责任。 碳排放权交易产品包括碳排放配额和经国务院批准的其他现货交易产品。国务院生态环境主管部门会同有关部门制定年度碳排放配额总量和分配方案，并组织实施。 温室气体重点排放单位应当采取有效措施控制温室气体排放，按照国家规定和国务院生态环境主管部门制定的技术规范，开展温室气体统计核算，编制温室气体年度排放报告，报省级人民政府生态环境主管部门核查后，按照规定的期限足额清缴碳排放配额。温室气体重点排放单位应当对排放统计核算数据、年度排放报告的真实性、准确性和完整性负责。 温室气体重点排放单位名录由省级人民政府生态环境主管部门会同有关部门，依据国务院生态环境主管部门确定的条件制定。 第一千零三十八条 国家建立全国温室气体自愿减排交易市场，鼓励温室气体自愿减排交易。 单位和个人可以按照国家规定，参与温室气体自愿减排交易。 申请温室气体自愿减排交易的项目应当有利于降碳增汇，能够避免、减少温室气体排放，或者实现温室气体的清除。 第一千零三十九条 国务院生态环境主管部门负责碳排放权交易、温室气体自愿减排交易及相关活动的监督管理。国务院有关部门在各自职责范围内，负责碳排放权交易、温室气体自愿减排交易及相关活动的监督管理。 第一千零四十条 国家建立健全生态系统碳汇监测核算体系，开展森林、草原、湿地、海洋、土壤等碳储量本底调查和评估，加强生态的保护与修复，巩固和提升生态系统碳汇能力。 第三节 适应气候变化 第一千零四十一条 国家制定实施适应气候变化战略，坚持预防为主、科学适应，采取有效措施降低气候变化不利影响和风险，建设气候适应型社会。 省、自治区、直辖市人民政府结合实际情况，制定本行政区域适应气候变化行动方案，确定适应气候变化的重点领域、区域和措施，并组织实施。 第一千零四十二条 国家根据不同区域特点开展区域适应气候变化行动，提升重大战略区域适应气候变化的能力。 第一千零四十三条 编制国土空间规划应当充分考虑气候变化的影响和风险，加强对气候资源条件、气候变化影响和风险的评估。 第一千零四十四条 国务院有关部门在各自职责范围内，加强对水、陆地、海洋等生态系统，以及农业与粮食安全、健康与公共卫生、基础设施与重大工程、城市与人居环境、气候变化敏感产业、文化遗产等经济社会重点领域的气候变化影响和风险评估，提升重点领域适应气候变化的能力。 第一千零四十五条 国家建立健全气候变化影响下灾害综合风险监测预警和评估制度，提升多灾种、灾害链风险综合预警和评估能力。 第一千零四十六条 国家加强对极端天气气候事件引发的自然灾害综合治理，采取有效措施改善城乡防灾基础条件，优化重大基础设施空间布局，强化应急指挥处置、抢险队伍建设，加强应急装备物资储备，提升极端天气气候事件下综合救援和公众安全保障能力。 第一千零四十七条 国家鼓励开展气候变化健康风险和适应能力评估，加强气候敏感疾病的监测预警和防控，推进气候变化健康适应行动，提高气候变化和极端天气气候事件下公众健康适应水平。 第四节 国际合作 第一千零四十八条 国家坚持共同但有区别的责任原则、公平原则、各自能力原则，积极参与和引领全球气候治理，推动构建公平合理、合作共赢的全球气候治理体系。 第一千零四十九条 国家根据国情、发展阶段和实际能力，承担应对气候变化领域相应的国际义务。 国务院生态环境主管部门会同有关部门定期编制国家自主贡献、国家温室气体清单和履约报告。 第一千零五十条 国务院有关部门在各自职责范围内开展应对气候变化多边、双边国际交流与合作，推动应对气候变化领域规则和标准衔接互认。 第一千零五十一条 国家加强应对气候变化领域的国际科学技术合作与交流，支持国内外优秀科学技术人才合作研究开发，鼓励企业、高等学校、科研机构开展可再生能源、储能、氢能、碳捕集利用与封存等技术交流。 第五编 法律责任和附则 第一章 法律责任通则 第一节 一般规定 第一千零五十二条 任何单位和个人有污染环境、破坏生态和违反绿色低碳义务的行为的，应当严格依法追究其法律责任。 法律责任的确定，应当与污染环境、破坏生态和违反绿色低碳义务的行为的事实、性质、情节、危害后果相当。 第一千零五十三条 实施污染环境、破坏生态等违法行为的，除有证据足以证明其没有过错外，应当承担行政责任。 实施污染环境、破坏生态等行为，造成他人民事权益损害的，不论有无过错，应当承担民事责任。 第一千零五十四条 造成环境污染、生态破坏等危害后果的违法行为在五年内被发现的，应当依法给予行政处罚；其他违法行为在二年内被发现的，应当依法给予行政处罚。上述期限自违法行为发生之日起计算，违法行为有连续或者继续状态的，从行为终了之日起计算。 提起生态环境民事诉讼的诉讼时效期间为五年。诉讼时效期间自当事人知道或者应当知道受到损害以及责任人之日起计算。 第一千零五十五条 同一个违法行为违反多个生态环境法律规范应当给予罚款处罚的，按照罚款数额高的规定处罚。 第一千零五十六条 实施污染环境、破坏生态等违法行为，有恶意损害生态环境、拒不改正违法行为、造成严重危害后果、多次实施违法行为被处罚等法定情形的，依法从重处罚。 实施污染环境、破坏生态等违法行为，有主动消除或者减轻危害后果、有效采取生态环境修复措施、及时缴纳赔偿金等法定情形的，依法从轻或者减轻处罚。违法行为轻微并及时改正，没有造成危害后果的，不予处罚；初次违法且危害后果轻微并及时改正的，可以不予处罚。 第一千零五十七条 实施行政处罚，适用违法行为发生时的生态环境法律、法规、规章的规定。但是，作出行政处罚决定时，生态环境法律、法规、规章已被修改或者废止，且新的规定处罚较轻或者不认为是违法的，适用新的规定。 第一千零五十八条 因污染环境、破坏生态等行为应当承担民事责任、行政责任、刑事责任的，承担行政责任或者刑事责任不影响承担民事责任。财产不足以支付的，优先承担民事责任。 污染环境、破坏生态等违法行为构成犯罪，人民法院判处拘役或者有期徒刑时，行政机关已经实施行政拘留的，应当依法折抵相应刑期；已经实施行政罚款的，应当依法折抵相应罚金。 第一千零五十九条 由于不可抗力造成污染环境、破坏生态损害的，不承担赔偿责任；法律另有规定的除外。对海洋环境造成污染损害的，适用本条第三款规定。 损害是由受害人故意造成的，有关责任人不承担赔偿责任；损害是由受害人重大过失造成的，可以减轻赔偿责任。 完全属于下列情形之一，经过及时采取合理措施，仍然不能避免对海洋环境造成污染损害的，造成污染损害的有关责任人免予承担责任： （一）战争； （二）不可抗拒的自然灾害； （三）负责灯塔或者其他助航设备的主管部门，在履行职责时的疏忽，或者其他过失行为。 第一千零六十条 企业事业单位和其他生产经营者违法排放、倾倒、处置污染物、废弃物或者其他物质，受到罚款处罚，被责令改正的，依法作出处罚决定的部门或者机构应当组织复查，发现其继续实施该违法行为、拒不改正或者拒绝、阻挠复查的，可以自责令改正之日的次日起，按照原罚款数额按日连续处罚，并及时采取措施制止违法行为。 前款规定的原罚款数额，在法定幅度内按照污染防治设施的运行成本、违法行为造成的直接损失或者违法所得等因素予以确定。 地方性法规可以根据生态环境保护的实际需要，增加第一款规定的按日连续处罚的违法行为的种类。 第二节 责任主体 第一千零六十一条 地方人民政府不依法履行职责，致使本地区生态环境质量问题突出、生态环境状况恶化的，应当对其负责人依法给予处分或者处理，并可以向社会公开。 第一千零六十二条 地方各级人民政府、负有生态环境保护监督管理职责的部门、机构有下列情形之一的，对负有责任的领导人员和直接责任人员给予记过、记大过或者降级处分；造成严重后果的，给予撤职或者开除处分： （一）未依法作出行政许可或者办理批准文件； （二）对生态环境违法行为进行包庇； （三）依法应当作出责令停业、关闭的决定而未作出； （四）对未按照许可证规定排放污染物、采用逃避监管的方式排放污染物、造成环境污染或者生态破坏事故以及不落实生态保护措施造成生态破坏等行为，发现或者接到举报未及时依法查处； （五）违法查封、扣押企业事业单位和其他生产经营者的有关场所、船舶、设施、设备、工具、物品； （六）篡改、伪造或者指使篡改、伪造监测数据； （七）应当依法公开生态环境信息而未公开； （八）违法收取费用，或者将依法收取的费用截留、挤占或者挪作他用； （九）对应当移送有关机关处理的案件不依法移送； （十）法律法规规定的其他违法情形。 第一千零六十三条 规划编制机关未依法组织生态环境影响评价，或者组织生态环境影响评价时弄虚作假或者有失职行为，造成生态环境影响评价严重失实的；规划审批机关对依法应当编写有关生态环境影响的篇章或者说明而未编写的规划草案，依法应当附送生态环境影响报告书而未附送的专项规划草案，违法予以批准的，对负有责任的领导人员和直接责任人员依法给予处分。 生态环境主管部门在生态环境影响报告书、报告表、登记表的审批、审核、备案等环节违法收取费用，索取、收受财物，或者谋取其他不正当利益的，应当责令退还或者予以没收；对负有责任的领导人员和直接责任人员依法给予处分。 第一千零六十四条 企业事业单位、其他生产经营者和个人污染环境、破坏生态或者有本法规定的其他违法情形的，应当依法承担法律责任；造成环境污染、生态破坏事故或者有其他法定情形的，企业事业单位、其他生产经营者的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员应当依法承担法律责任。 第一千零六十五条 企业事业单位、其他生产经营者和个人造成环境污染、生态破坏的，应当依法承担消除污染、修复受损生态环境的责任；无法消除或者修复的，实施替代性治理或者修复措施。 违法行为人变更的，由承继其权利义务的主体负责治理或者修复。 第一千零六十六条 土壤污染及其相关的地下水污染责任人无法认定，土地使用权人未依照本法规定履行污染风险管控和修复义务，造成他人民事权益损害的，应当依法承担民事侵权责任。 违反本法规定，销售的机动车船、非道路移动机械、发动机不符合污染物排放标准的，销售者应当负责修理、更换、退货；给购买者造成损失的，销售者应当赔偿损失。 第一千零六十七条 受委托从事生态环境服务活动的生态环境技术服务机构违反本法规定，对造成的环境污染、生态破坏等负有责任的，除依照本法及有关法律法规的规定予以处罚外，还应当与造成环境污染、生态破坏等的委托人承担连带责任。 第一千零六十八条 获准倾倒海洋废弃物的单位和产生工业固体废物的单位违反本法规定，未尽到核实、监督等义务委托他人实施废弃物海洋倾倒作业或者运输、利用、处置工业固体废物的，除依照本法及有关法律法规的规定予以处罚外，还应当与造成环境污染、生态破坏的受托人承担连带责任。 违反本法规定，将中华人民共和国境外的固体废物、放射性废物和被放射性污染的物品输入境内的，承运人对固体废物、放射性废物和被放射性污染的物品的退运、处置，与进口者承担连带责任。 第一千零六十九条 企业事业单位有本法规定的违法情形，其负有责任的领导人员和直接责任人员属于公职人员的，依法给予处分。 第一千零七十条 因污染环境、破坏生态等造成他人民事权益损害应当承担民事责任，本法未作规定的，依照《中华人民共和国民法典》的规定承担民事责任。 第一千零七十一条 违反本法规定，构成犯罪的，依法追究刑事责任。 第三节 责任追究 第一千零七十二条 负有生态环境保护监督管理职责的部门、机构应当按照职责分工及时查处生态环境违法案件，依法追究法律责任。 依法应当作出行政处罚而未作出的，上级人民政府负有生态环境保护监督管理职责的部门可以直接作出行政处罚的决定。 第一千零七十三条 违反法律规定，污染环境、破坏生态等给国家造成损失的，由设区的市级以上地方人民政府或者其指定的部门、机构与责任人按照有关规定进行磋商，要求其承担生态环境损害赔偿责任；磋商未达成一致的，可以向人民法院提起诉讼。 前款规定的地方人民政府、部门、机构不进行磋商，或者磋商未达成一致且不提起诉讼的，人民检察院可以对责任人依法向人民法院提起诉讼。 第一千零七十四条 污染海洋环境、破坏海洋生态给国家造成损失的，由依照本法规定行使海洋生态环境监督管理权的部门对责任人提出损害赔偿要求，可以向人民法院提起诉讼。 责任人不承担损害赔偿责任，前款规定的部门不提起诉讼的，人民检察院可以依法向人民法院提起诉讼。 第一千零七十五条 违反法律规定，污染环境、破坏生态等损害社会公共利益的，人民检察院或者符合本法规定的社会组织可以依法向人民法院提起诉讼。 第一千零七十六条 人民检察院在履行职责中发现地方人民政府或者负有生态环境保护监督管理职责的部门、机构违法行使职权或者不作为，给国家造成损失或者损害社会公共利益的，可以依法提起诉讼。 第一千零七十七条 污染环境、破坏生态等侵害他人合法权益的，可以由当事人协商解决，也可以向负有生态环境保护监督管理职责的部门、机构申请调解处理；调解不成的，可以向人民法院提起诉讼。当事人也可以直接向人民法院提起诉讼。 第一千零七十八条 国家鼓励排放噪声、油烟、异味的单位和公共场所管理者等与受到侵害的单位和个人友好协商，通过调整生产经营、施工作业时间等，采取预防、补救措施，支付补偿金、异地安置等方式，妥善解决纠纷。 第一千零七十九条 对正在实施或者即将实施的污染环境、破坏生态等行为，不及时制止将使当事人合法权益或者生态环境受到难以弥补的损害重大风险的，可以依照《中华人民共和国民事诉讼法》的有关规定，向人民法院申请采取禁止令保全措施，责令立即停止污染环境、破坏生态等行为。 第一千零八十条 因污染环境、破坏生态等造成他人损害的，行为人应当就法律规定的不承担责任或者减轻责任的情形，及其行为与损害之间不存在因果关系依法承担举证责任。 第一千零八十一条 依据本法第一千零七十三条、第一千零七十五条规定向人民法院提起诉讼的机关和组织，应当提供以下证明： （一）行为人实施了污染环境、破坏生态等行为； （二）行为违反法律规定； （三）生态环境损害情况； （四）生态环境损失费用、生态环境修复费用及其他费用； （五）其他应当证明的事项。 依据本法第一千零七十四条规定提起诉讼的，应当提供前款第一项、第三项至第五项规定的证明。 第一千零八十二条 负有生态环境保护监督管理职责的部门、机构以及人民检察院等，可以依法支持因污染环境、破坏生态受到损害的当事人向人民法院提起诉讼。 国家鼓励法律服务机构和律师为前款规定的当事人提供法律援助。 第一千零八十三条 相关部门在受理举报、监督检查或者在查处案件等工作中，发现违法线索或者案件属于负有生态环境保护监督管理职责的部门、机构职责的，应当及时移送。 负有生态环境保护监督管理职责的部门、机构，以及人民法院、人民检察院在依法查处生态环境违法行为或者办理相关案件过程中，发现存在涉嫌犯罪行为的，应当移送具有侦查、调查职权的机关。 第一千零八十四条 上级人民政府及其生态环境主管部门应当加强对下级人民政府及其有关部门、机构生态环境保护工作的监督。发现有关工作人员有违法行为，依法应当给予处分的，应当移送其任免机关、单位或者监察机关依法处理。 第二章 法律责任分则 第一节 违反生态环境监测管理规定 第一千零八十五条 违反本法第一编第四章等规定，适用本节规定予以行政处罚。 第一千零八十六条 违反本法规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处二万元以上二十万元以下的罚款；拒不改正的，可以责令限制生产、停产整治： （一）未对所排放的污染物、养殖尾水、土壤污染状况自行监测，未制定自行监测方案，未建立管理台账，未保存原始监测记录和管理台账，以及未如实报告； （二）未安装、使用、维护、正常运行污染物排放自动监测、监控设备，未与主管部门的监控设备联网，未保存原始监测记录，以及未如实报告； （三）未对排放有毒有害污染物的排污口和周边环境进行监测，以及未公开有毒有害污染物信息。 违反本法规定，生活垃圾处理单位未安装、使用污染物排放监测设备，实时监测污染物的排放情况并公开污染排放数据的，由生态环境主管部门责令改正，处五万元以上五十万元以下的罚款；拒不改正的，处五十万元以上一百万元以下的罚款。 第一千零八十七条 违反本法规定，企业事业单位和其他生产经营者开展生态环境监测使用不符合法律、行政法规规定和国家标准的监测设施、设备，或者未遵守监测规范导致监测数据失真的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处二万元以上二十万元以下的罚款；拒不改正的，责令限制生产、停产整治。 第一千零八十八条 违反本法规定，企业事业单位和其他生产经营者对生态环境监测数据弄虚作假，或者指使其委托的生态环境监测机构对监测数据弄虚作假的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处十万元以上一百万元以下的罚款，并对其直接负责的主管人员和其他直接责任人员处五万元以上二十万元以下的罚款；情节严重的，责令限制生产、停产整治。 第一千零八十九条 违反本法规定，生态环境监测机构不具备相应的设施、设备、技术人员、技术能力、管理能力，或者不依法备案的，由生态环境主管部门责令改正，没收违法所得，并处二万元以上二十万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业。 违反本法规定，从事放射性污染监测的生态环境监测机构未取得许可证或者未按照许可证规定开展监测业务的，由生态环境主管部门责令改正，没收违法所得，并处五万元以上五十万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业、关闭。 第一千零九十条 违反本法规定，生态环境监测机构使用不符合法律、行政法规规定和国家标准的监测设施、设备，或者未遵守监测规范导致监测数据失真的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，没收违法所得，并处二万元以上二十万元以下的罚款；拒不改正的，有许可证的吊销许可证，报经有批准权的人民政府批准，责令停业、关闭。 第一千零九十一条 违反本法规定，生态环境监测机构对监测数据弄虚作假的，由负有生态环境保护监督管理职责的部门、机构按照职责分工没收违法所得，并处十万元以上五十万元以下的罚款；情节严重的，并处五十万元以上二百万元以下的罚款，有许可证的吊销许可证，禁止从事监测业务，报经有批准权的人民政府批准，责令停业、关闭。 有前款规定情形的，由负有生态环境保护监督管理职责的部门、机构按照职责分工对直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款，五年内禁止从事前款规定的业务；情节严重的，十年内禁止从事前款规定的业务。 第一千零九十二条 违反本法规定，生产、进口、销售不符合法律、行政法规规定和国家标准的监测设施、设备的，由市场监督管理部门、海关按照职责分工责令停止生产、进口、销售，没收违法所得和违法生产、进口、销售的设施、设备，并处违法生产、进口、销售的设施、设备货值金额一倍以上五倍以下的罚款，货值金额不足五万元的，以五万元计算；情节严重的，吊销许可证。 第一千零九十三条 违反本法规定，单位和个人以侵占、损毁或者擅自移动、改变等方式干扰、破坏生态环境监测设施、设备或者指使干扰、破坏生态环境监测设施、设备的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处二万元以上二十万元以下的罚款；构成违反治安管理行为的，由公安机关依法予以处罚。 第二节 违反生态环境影响评价管理规定 第一千零九十四条 违反本法第一编第五章等规定，适用本节规定予以行政处罚。 第一千零九十五条 违反本法规定，建设单位未依法报批，或者未依照本法有关规定重新报批或者报请重新审核生态环境影响报告书、报告表，建设项目生态环境影响报告书、报告表未经批准或者未经原审批部门重新审核同意，擅自开工建设的，由生态环境主管部门、海警机构按照职责分工责令其停止建设，并可以责令恢复原状，报批、审核类型为生态环境影响报告书的，处二十万元以上一百万元以下的罚款，情节严重的，处一百万元以上一千万元以下的罚款；报批、审核类型为生态环境影响报告表的，处十万元以上五十万元以下的罚款，情节严重的，处五十万元以上五百万元以下的罚款。 建设单位有前款规定情形，被责令停止建设或者恢复原状，拒不执行的，由公安机关或者海警机构按照职责分工对其直接负责的主管人员和其他直接责任人员，处十日以上十五日以下拘留；情节较轻的，处五日以上十日以下拘留。 违反本法规定，建设单位未依法将建设项目生态环境影响登记表报生态环境主管部门备案的，由生态环境主管部门责令改正，可以处五万元以下的罚款。 违反本法规定，核设施选址、建造、运行、退役和核技术、铀（钍）矿、伴生放射性矿开发利用中有第一款至第三款规定的违法情形的，适用第一款至第三款的规定予以处罚。 第一千零九十六条 违反本法规定，建设项目生态环境影响报告书、报告表存在基础资料明显不实，内容存在重大缺陷、遗漏或者虚假，生态环境影响评价结论不正确或者不合理等严重质量问题的，由生态环境主管部门、海警机构按照职责分工对建设单位处五十万元以上二百万元以下的罚款，并对建设单位的法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员，处五万元以上二十万元以下的罚款；情节严重的，责令限制生产、停产整治。 建设单位自行编制生态环境影响报告书、报告表有前款规定的违法情形的，对编制主持人和主要编制人员处一万元以上五万元以下的罚款，五年内禁止从事生态环境影响报告书、报告表编制工作；情节严重的，十年内禁止从事生态环境影响报告书、报告表编制工作。 第一千零九十七条 违反本法规定，接受委托为建设单位编制建设项目生态环境影响报告书、报告表的技术单位违反国家有关生态环境影响评价标准和技术规范等规定，致使其编制的报告书、报告表存在基础资料明显不实，内容存在重大缺陷、遗漏或者虚假，生态环境影响评价结论不正确或者不合理等严重后果的，由生态环境主管部门、海警机构按照职责分工没收违法所得，并处十万元以上五十万元以下的罚款；情节严重的，并处五十万元以上二百万元以下的罚款，禁止从事生态环境影响报告书、报告表编制工作，报经有批准权的人民政府批准，责令停业。 技术单位有前款规定的违法情形的，主持编制的主要人员五年内禁止从事生态环境影响报告书、报告表编制工作；情节严重的，十年内禁止从事生态环境影响报告书、报告表编制工作。 第一千零九十八条 违反本法规定，接受委托为建设单位编制建设项目生态环境影响报告书、报告表的技术单位和人员，与负责审批的部门存在利益关系的，或者该技术单位未依法报生态环境主管部门备案的，由生态环境主管部门、海警机构按照职责分工责令改正，处二万元以上二十万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业。 第一千零九十九条 违反本法规定，在建设项目建设、运行过程中，未实施生态环境影响报告书、报告表及其审批部门审批意见中提出的生态环境保护对策措施的，由生态环境主管部门、海警机构按照职责分工对建设单位处五万元以上五十万元以下的罚款；情节严重的，处五十万元以上二百万元以下的罚款。本法另有规定的，适用其规定。 第一千一百条 违反本法规定，生态环境保护设施未与主体工程同时设计、同时施工、同时投产使用，或者生态环境保护设施未建成、未达到规定要求即投入生产、使用的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处二十万元以上一百万元以下的罚款，拒不改正的，处一百万元以上二百万元以下的罚款；对直接负责的主管人员和其他直接责任人员处五万元以上二十万元以下的罚款；造成重大环境污染、生态破坏的，责令其停止生产、使用，或者报经有批准权的人民政府批准，责令停业、关闭。 第三节 违反排污许可管理规定 第一千一百零一条 违反本法第二编第一分编第二章等规定，适用本节规定予以行政处罚。 第一千一百零二条 违反本法规定，未依法取得排污许可证排放污染物的，由生态环境主管部门责令改正，处二十万元以上一百万元以下的罚款，并可以责令限制生产、停产整治；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。其中，污染物为工业噪声的，罚款数额为二万元以上二十万元以下。拒不停止排放污染物的，由生态环境主管部门将案件移送公安机关，由公安机关对其直接负责的主管人员和其他直接责任人员，处十日以上十五日以下拘留；情节较轻的，处五日以上十日以下拘留。 第一千一百零三条 违反本法规定，未按照排污许可证载明的污染物排放种类，或者超过载明的许可排放浓度、许可排放量、许可排放限值排放污染物的，由生态环境主管部门责令改正，处十万元以上一百万元以下的罚款，并可以责令限制生产、停产整治；情节严重的，吊销排污许可证，报经有批准权的人民政府批准，责令停业、关闭。其中，污染物为工业噪声的，罚款数额为二万元以上二十万元以下。 第一千一百零四条 违反本法规定，未按照排污许可证的规定运行和维护污染防治设施的，由生态环境主管部门责令改正，处二万元以上五万元以下的罚款；致使污染防治设施不能正常发挥作用，但不属于以逃避监管方式排放污染物的，由生态环境主管部门责令改正，处五万元以上二十万元以下的罚款；情节严重的，责令限制生产、停产整治。 违反本法规定，擅自拆除污染防治设施的，由生态环境主管部门责令改正，处十万元以上一百万元以下的罚款；拒不改正的，责令限制生产、停产整治；情节严重的，吊销排污许可证，报经有批准权的人民政府批准，责令停业、关闭。 第一千一百零五条 违反本法规定，以欺骗、贿赂等不正当手段申请取得排污许可证的，由生态环境主管部门依法撤销其排污许可证，处二十万元以上五十万元以下的罚款。 第一千一百零六条 违反本法规定，需要填报排污登记表的企业事业单位和其他生产经营者未依法填报排污信息的，由生态环境主管部门责令改正，可以处五万元以下的罚款。 第一千一百零七条 违反本法规定，超过污染物排放标准或者超过重点污染物排放总量控制指标排放污染物的，由生态环境主管部门责令改正，处十万元以上一百万元以下的罚款，可以责令限制生产、停产整治；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。其中，污染物为工业噪声的，罚款数额为二万元以上二十万元以下。 第一千一百零八条 违反本法规定，通过暗管、渗井、渗坑、灌注、裂隙、溶洞、篡改或者伪造监测数据、以逃避现场检查为目的的临时停产、非紧急情况下开启应急排放通道、不正常运行污染防治设施等逃避监管的方式排放污染物的，由生态环境主管部门责令改正，处十万元以上一百万元以下的罚款，责令限制生产、停产整治，并将案件移送公安机关，由公安机关对其直接负责的主管人员和其他直接责任人员，处五日以上十日以下拘留；情节严重的，吊销排污许可证，报经有批准权的地方人民政府批准，责令停业、关闭，并由公安机关对其直接负责的主管人员和其他直接责任人员，处十日以上十五日以下拘留。 第一千一百零九条 违反本法和其他法律法规、国务院生态环境主管部门的规定、排污许可证规定设置排污口的，除本条第二款规定外，由生态环境主管部门责令限期拆除，逾期不拆除的，强制拆除，所需费用由违法者承担，处二万元以上十万元以下的罚款；情节严重的，处十万元以上五十万元以下的罚款，责令限制生产、停产整治。 违反本法规定，在饮用水水源保护区内设置排污口的，或者在自然保护地水体等具有特殊经济文化价值的水体、生态保护红线区域及其他需要特别保护的区域新设排污口的，由县级以上地方人民政府责令限期拆除，逾期不拆除的，强制拆除，所需费用由违法者承担，由生态环境主管部门处十万元以上五十万元以下的罚款；情节严重的，处五十万元以上一百万元以下的罚款，责令限制生产、停产整治。 违反本法规定，设置入海排污口未备案的，由生态环境主管部门责令改正，处二万元以上十万元以下的罚款。 第一千一百一十条 违反本法规定，未向社会公开或者不如实公开污染物排放信息、温室气体排放信息等生态环境信息的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处二万元以上二十万元以下的罚款；拒不改正的，责令限制生产、停产整治，并公告上述生态环境信息。 第一千一百一十一条 违反本法规定，建设单位未将污染防治所需资金列入工程造价的，由生态环境主管部门责令改正，处二万元以上十万元以下的罚款；拒不改正的，处十万元以上一百万元以下的罚款，责令停产整治。 第一千一百一十二条 违反本法规定，将中华人民共和国境外的固体废物、放射性废物和被放射性污染的物品输入境内的，由海关责令退运该固体废物、放射性废物和被放射性污染的物品，处五十万元以上五百万元以下的罚款。已经非法入境的，由省级以上人民政府生态环境主管部门依法向海关提出处理意见，由海关按照前述规定予以处理；已经造成环境污染的，由省级以上人民政府生态环境主管部门责令进口者消除污染。 违反本法规定，将中华人民共和国境外废弃物运进中华人民共和国管辖海域倾倒的，由海警机构责令改正，处五十万元以上五百万元以下的罚款。 第四节 违反大气污染防治规定 第一千一百一十三条 违反本法第二编第二分编规定，适用本节规定予以行政处罚。 第一千一百一十四条 违反本法规定，有下列情形之一的，由能源主管部门责令改正，处十万元以上一百万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业、关闭： （一）煤矿未配套建设煤炭洗选设施； （二）燃煤电厂和其他燃煤单位未配套建设除尘、脱硫、脱硝等装置或者未采取技术改造等其他控制大气污染物排放的措施； （三）生产过程中排放粉尘、硫化物和氮氧化物的钢铁、建材、有色金属、石油、化工等企业未配套建设除尘、脱硫、脱硝等装置或者未采取技术改造等其他控制大气污染物排放的措施。 违反本法规定，开采含放射性和砷等有毒有害物质超过规定标准的煤炭的，由县级以上人民政府按照国务院规定的权限责令停业、关闭。 第一千一百一十五条 违反本法规定，有下列情形之一的，由市场监督管理部门责令改正，没收原材料、产品和违法所得，并处货值金额一倍以上五倍以下的罚款： （一）销售不符合质量标准的煤炭、石油焦； （二）在禁燃区内销售高污染燃料； （三）生产、销售挥发性有机物含量不符合质量标准或者要求的原辅材料和产品； （四）生产、销售不符合标准的机动车船和非道路移动机械用燃料、发动机油、氮氧化物还原剂、燃料和润滑油添加剂以及其他添加剂。 第一千一百一十六条 违反本法规定，有下列情形之一的，由海关责令退运，没收违法所得，并处货值金额一倍以上五倍以下的罚款；无法退运的，没收原材料和产品： （一）进口不符合质量标准的煤炭、石油焦； （二）进口挥发性有机物含量不符合质量标准或者要求的原辅材料和产品； （三）进口不符合标准的机动车船和非道路移动机械用燃料、发动机油、氮氧化物还原剂、燃料和润滑油添加剂以及其他添加剂。 第一千一百一十七条 违反本法规定，单位燃用不符合质量标准的煤炭或者使用不符合质量标准的石油焦的，由生态环境主管部门责令改正，处货值金额一倍以上五倍以下的罚款。 第一千一百一十八条 违反本法规定，船舶使用不符合标准或者要求的燃油的，由海事管理机构、渔业渔政主管部门按照职责分工处一万元以上十万元以下的罚款。 第一千一百一十九条 违反本法规定，有下列情形之一的，由生态环境主管部门没收燃用高污染燃料的设施、燃煤供热锅炉并组织拆除，处二万元以上二十万元以下的罚款： （一）在禁燃区内新建、扩建燃用高污染燃料的设施； （二）在禁燃区内未停止燃用高污染燃料； （三）在城市集中供热管网覆盖地区新建、扩建分散燃煤供热锅炉； （四）未在要求期限内拆除已建成的不能达标排放的燃煤供热锅炉。 违反本法规定，生产、进口、销售不符合规定标准或者要求的锅炉的，由市场监督管理部门责令改正，没收违法所得，并处二万元以上二十万元以下的罚款；使用不符合规定标准或者要求的锅炉的，由生态环境主管部门责令改正，没收违法所得，并处二万元以上二十万元以下的罚款。 第一千一百二十条 违反本法规定，有下列情形之一的，由生态环境主管部门责令改正，处二万元以上二十万元以下的罚款；拒不改正的，责令停产整治： （一）工业涂装企业等未使用低挥发性有机物含量的原辅材料和产品； （二）生产和使用产生含挥发性有机物原辅材料和产品，未在密闭空间或者设备中进行并安装、使用污染防治设施或者未采取减少废气排放措施； （三）石油、化工以及其他生产和使用有机溶剂的企业，未采取措施对管道、设备进行日常维护、维修，或者对泄漏的物料未及时收集处理； （四）储油库、加油站和油罐车等，未按照国家规定安装并正常使用油气回收装置； （五）钢铁、建材、有色金属、石油、化工、制药、矿产开采企业和其他工业生产企业，未采取集中收集处理、密闭、围挡、遮盖、清扫、洒水等措施，控制、减少粉尘和气态污染物的排放； （六）工业生产、垃圾填埋或者其他活动产生的可燃性气体未回收利用，不具备回收利用条件未进行污染防治处理； （七）可燃性气体回收利用装置不能正常作业，未及时修复或者更新； （八）在可燃性气体回收利用装置不能正常作业期间排放可燃性气体，未采取控制大气污染物排放措施。 违反本法规定，原油成品油码头、原油成品油运输船舶、铁路罐车未按照国家规定安装并正常使用油气回收装置的，由生态环境、交通运输、海事管理等部门按照职责分工，依照前款规定予以处罚。 第一千一百二十一条 违反本法规定，生产不符合大气污染物排放标准的机动车船、非道路移动机械、发动机的，由省级以上人民政府生态环境主管部门责令改正，没收违法所得，并处货值金额三倍以下的罚款，没收销毁无法达到污染物排放标准的机动车船、非道路移动机械、发动机；拒不改正的，责令限制生产、停产整治，并由国务院有关生产主管部门按照职责分工责令停止生产该车（船、机）型。 违反本法规定，机动车、非道路移动机械、发动机生产企业对发动机、排放控制系统弄虚作假、以次充好，冒充排放检验合格产品出厂销售的，由省级以上人民政府生态环境主管部门责令停产整治，没收违法所得，并处货值金额一倍以上三倍以下的罚款，没收销毁无法达到污染物排放标准的机动车、非道路移动机械、发动机，并由国务院有关生产主管部门按照职责分工责令停止生产该车（机）型。 第一千一百二十二条 违反本法规定，进口、销售超过污染物排放标准的机动车船、非道路移动机械、发动机的，由市场监督管理部门、海关按照职责分工没收违法所得，并处货值金额三倍以下的罚款，没收销毁无法达到污染物排放标准的机动车船、非道路移动机械、发动机。 第一千一百二十三条 违反本法规定，机动车、非道路移动机械生产、进口企业未按照规定向社会公开其生产、进口机动车车型、非道路移动机械机型的排放检验信息或者污染控制技术信息的，由省级以上人民政府生态环境主管部门责令改正，处五万元以上五十万元以下的罚款。 违反本法规定，机动车、非道路移动机械生产、进口企业未按照规定向社会公开其生产、进口机动车车型、非道路移动机械机型的有关维修技术信息的，由省级以上人民政府交通运输主管部门责令改正，处五万元以上五十万元以下的罚款。 第一千一百二十四条 违反本法规定，以临时更换、篡改、屏蔽、伪造排放控制系统等弄虚作假的方式通过机动车船、非道路移动机械排放检验或者破坏、拆除、篡改、屏蔽、伪造机动车船、非道路移动机械排放控制系统的，由生态环境主管部门、海事管理机构、渔业渔政主管部门按照职责分工责令改正，对所有人处每辆（艘）五千元的罚款，对维修单位处每辆（艘）五千元的罚款。 第一千一百二十五条 违反本法规定，生产、进口或者销售能够篡改、屏蔽、伪造机动车船、非道路移动机械、发动机排放检验数据的装置或者为虚假排放检验提供条件的检验设备的，由生态环境主管部门、市场监督管理部门、海关按照职责分工没收违法所得，没收销毁违法装置和检验设备，并处货值金额一倍以上五倍以下的罚款，货值金额不足五万元的，以五万元计算；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。 第一千一百二十六条 违反本法规定，机动车驾驶人驾驶排放检验不合格的机动车上道路行驶的，由公安机关交通管理部门依法予以处罚。 第一千一百二十七条 违反本法规定，使用排放不合格的非道路移动机械、铁路内燃机车、船舶，或者在用重型汽车、船舶、非道路移动机械未加装、更换符合要求的排放控制系统或者采取其他有效措施的，由生态环境、海事管理、渔业渔政等部门按照职责分工责令改正，处每辆（艘）五千元的罚款。 违反本法规定，在禁止使用高排放非道路移动机械的区域使用高排放非道路移动机械的，由生态环境主管部门责令改正，处每辆五千元的罚款。 第一千一百二十八条 违反本法规定，施工单位有下列情形之一的，由住房城乡建设等部门按照职责分工责令改正，处一万元以上十万元以下的罚款；拒不改正的，责令停工整治： （一）施工工地未设置硬质围挡，或者未采取覆盖、分段作业、择时施工、洒水抑尘、冲洗地面和车辆等有效防尘降尘措施； （二）建筑土方未及时清运，或者在场地内堆存时未采用密闭式防尘网遮盖。 违反本法规定，建设单位未对暂时不能开工的建设用地的裸露地面进行覆盖，或者未对超过三个月不能开工的建设用地的裸露地面进行绿化、铺装或者遮盖的，由住房城乡建设等部门按照职责分工依照前款规定予以处罚。 第一千一百二十九条 违反本法规定，运输煤炭、垃圾、渣土、砂石、土方、灰浆等散装、流体物料的车辆和船舶，未采取密闭或者其他措施防止物料遗撒，或者未按照规定路线行驶的，由县级以上地方人民政府确定的监督管理部门、海事管理机构按照职责分工责令改正，处二千元以上二万元以下的罚款；拒不改正的，车辆不得上道路行驶。 第一千一百三十条 违反本法规定，有下列情形之一的，由生态环境等部门按照职责分工责令改正，处一万元以上十万元以下的罚款；拒不改正的，责令停工整治或者停业整治： （一）装卸物料未采取密闭或者喷淋等方式防治扬尘污染； （二）未密闭贮存煤炭、煤矸石、煤渣、煤灰、水泥、石灰、石膏、砂土、铁矿石等易产生扬尘的物料； （三）对不能密闭贮存的易产生扬尘的物料，未设置不低于堆放物高度的严密围挡，或者未采取有效覆盖措施防治扬尘污染； （四）单位存放煤炭、煤矸石、煤渣、煤灰等物料，未采取防燃措施； （五）码头、矿山、填埋场和消纳场未实施分区作业并采取有效措施防治扬尘污染； （六）排放有毒有害大气污染物名录中所列有毒有害大气污染物的企业事业单位，未建设环境风险预警体系、排查环境安全隐患并采取有效措施防范环境风险； （七）向大气排放持久性有机污染物的企业事业单位和其他生产经营者以及废弃物焚烧设施的运营单位，未采取有利于减少持久性有机污染物排放的技术方法和工艺，配备有效的净化装置； （八）未采取有效措施防止排放恶臭气体。 第一千一百三十一条 违反本法规定，在人口集中地区对树木、花草喷洒剧毒、高毒农药，或者在禁止焚烧的区域和时段露天焚烧秸秆、落叶等产生烟尘污染的物质的，由县级以上地方人民政府确定的监督管理部门责令改正，可以处五百元以上二千元以下的罚款。 违反本法规定，生产、使用国家明令禁止生产、使用的农药，被责令改正，拒不改正的，由农业农村主管部门依照有关法律法规的规定予以处罚，并将案件移送公安机关，由公安机关对其直接负责的主管人员和其他直接责任人员，处十日以上十五日以下拘留；情节较轻的，处五日以上十日以下拘留。 违反本法规定，在人口集中地区和其他依法需要特殊保护的区域内，焚烧沥青、油毡、橡胶、塑料、皮革、垃圾以及其他产生有毒有害烟尘和恶臭气体的物质的，由县级人民政府确定的监督管理部门责令改正，对单位处一万元以上十万元以下的罚款，对个人处五百元以上二千元以下的罚款。 违反本法规定，在禁止燃放的时段和区域内燃放烟花爆竹的，由县级以上地方人民政府确定的监督管理部门依法予以处罚。 第一千一百三十二条 违反本法规定，排放油烟的餐饮服务业经营者未安装油烟净化等污染防治设施，未保持正常使用油烟净化等污染防治设施，或者未采取其他油烟净化措施，致使超过排放标准排放油烟污染物的，由县级以上地方人民政府确定的监督管理部门责令改正，处五千元以上五万元以下的罚款；拒不改正的，责令停业整治。 违反本法规定，在居民住宅楼、未配套设立专用烟道的商住综合楼、商住综合楼内与居住层相邻的商业楼层内新建、改建、扩建产生油烟、异味、废气的餐饮服务项目的，由县级以上地方人民政府确定的监督管理部门责令改正；拒不改正的，责令关闭，并处一万元以上十万元以下的罚款。 违反本法规定，在当地人民政府禁止的时段和区域内露天烧烤食品或者为露天烧烤食品提供场地的，由县级以上地方人民政府确定的监督管理部门责令改正，没收烧烤工具和违法所得，并处五百元以上五千元以下的罚款；拒不改正的，处五千元以上二万元以下的罚款。 第一千一百三十三条 违反本法规定，从事服装干洗和机动车维修等服务活动，未设置异味和废气处理装置等污染防治设施并保持正常使用的，由生态环境主管部门责令改正，处二千元以上二万元以下的罚款；拒不改正的，责令停业整治。 第一千一百三十四条 违反本法规定，擅自向社会发布重污染天气预报预警信息，构成违反治安管理行为的，由公安机关依法予以处罚。 违反本法规定，拒不执行停止工地土石方作业或者建筑物拆除施工等重污染天气应对措施的，由县级以上地方人民政府确定的监督管理部门处一万元以上十万元以下的罚款。 第五节 违反水污染防治规定 第一千一百三十五条 违反本法第二编第三分编规定，适用本节规定予以行政处罚。 第一千一百三十六条 违反本法规定，有下列情形之一的，由生态环境主管部门责令停止违法行为，采取治理措施消除污染，处以罚款，可以责令采取限制生产、停产整治等措施；拒不采取治理措施的，可以指定有治理能力的单位代为治理，所需费用由违法者承担；情节严重的，报经有批准权的人民政府批准，责令停业、关闭： （一）向水体排放油类、酸液、碱液； （二）向水体排放剧毒废液，或者将含有汞、镉、砷、铬、铅、氰化物、黄磷等的可溶性剧毒废渣向水体排放、倾倒或者直接埋入地下； （三）在水体清洗装贮过油类、有毒有害污染物的车辆或者容器； （四）违反国家规定或者标准，向水体排放含热废水或者含病原体的污水； （五）向水体排放、倾倒工业废渣、城镇垃圾或者其他废弃物，或者向江河湖泊、运河、渠道、水库及其最高水位线以下的滩地、岸坡以及法律法规规定的其他地点倾倒、堆放、贮存固体废物或者其他污染物。 有前款第三项、第四项情形之一的，处二万元以上二十万元以下的罚款；有前款第一项、第五项情形之一的，处十万元以上一百万元以下的罚款；有前款第二项情形的，处二十万元以上二百万元以下的罚款。 第一千一百三十七条 违反本法规定，有下列情形之一的，由生态环境主管部门责令停止违法行为，采取治理措施消除污染，处以罚款，可以责令采取限制生产、停产整治等措施；拒不采取治理措施的，指定有治理能力的单位代为治理，所需费用由违法者承担；情节严重的，报经有批准权的人民政府批准，责令停业、关闭： （一）未采取防渗漏等措施，未建设地下水水质监测井进行监测； （二）加油站、采油厂等的地下油罐未使用双层罐或者采取建造防渗池等其他有效措施，或者未进行防渗漏监测； （三）利用无防渗漏措施的沟渠、坑塘等输送或者贮存含有毒有害污染物的废水、含病原体的污水或者其他废弃物； （四）未按照规定采取防护性措施。 有前款第一项、第二项情形之一的，处二万元以上二十万元以下的罚款；有前款第三项、第四项情形之一的，处十万元以上一百万元以下的罚款。 第一千一百三十八条 违反本法规定，在泉域保护范围以及岩溶强发育、存在较多落水洞和岩溶漏斗的区域内，新建、改建、扩建造成地下水污染的建设项目的，由生态环境主管部门处十万元以上五十万元以下的罚款，并报经有批准权的人民政府批准，责令拆除或者关闭。 第一千一百三十九条 违反本法规定，有下列情形之一的，由生态环境主管部门责令改正，处以罚款，可以责令采取限制生产、停产整治等措施；情节严重的，报经有批准权的人民政府批准，责令停业、关闭： （一）未采取有效措施，致使在处理安全生产事故过程中产生的可能严重污染水体的消防废物直接排入水体； （二）稀释排放含有毒有害水污染物的工业废水，但不属于以逃避监管方式排放污染物； （三）向农田灌溉渠道排放工业废水或者医疗污水； （四）向农田灌溉渠道排放城镇污水以及未综合利用的水产养殖尾水、农产品加工废水，致使其下游最近的灌溉取水点的水质不符合农田灌溉用水水质标准。 有前款第三项、第四项情形之一的，处二万元以上二十万元以下的罚款；有前款第一项、第二项情形之一的，处十万元以上一百万元以下的罚款。 第一千一百四十条 违反本法规定，向污水集中处理设施排放不符合处理工艺要求的工业废水的，由生态环境主管部门责令改正或者责令限制生产、停产整治，处十万元以上一百万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。 第一千一百四十一条 违反本法规定，建设不符合国家产业政策的小型造纸、制革、印染、染料、炼焦、炼硫、炼砷、炼汞、炼油、电镀、农药、石棉、水泥、玻璃、钢铁、火电以及其他严重污染水环境的生产项目的，由所在地设区的市、县级人民政府责令关闭。 第一千一百四十二条 违反本法规定，船舶未配备相应的防污设备和器材，或者未持有合法有效的防治水域环境污染的证书与文书的，由海事管理机构、渔业渔政主管部门按照职责分工责令限期改正，处五千元以上五万元以下的罚款；逾期不改正的，责令船舶临时停航。 违反本法规定，船舶进行涉及污染物、压载水等排放及操作，未遵守操作规程，未实施监测、监控，或者未如实记录并保存的，由海事管理机构、渔业渔政主管部门按照职责分工责令改正，处五千元以上五万元以下的罚款。 第一千一百四十三条 违反本法规定，有下列情形之一的，由海事管理机构、渔业渔政主管部门按照职责分工责令停止违法行为，处一万元以上十万元以下的罚款；造成水污染的，责令限期采取治理措施消除污染，处二万元以上二十万元以下的罚款；逾期不采取治理措施的，指定有治理能力的单位代为治理，所需费用由船舶承担： （一）船舶向水体倾倒垃圾或者排放船舶的残油、废油、含油污水、生活污水； （二）船舶装载运输油类或者有毒有害货物未采取防止溢流和渗漏的措施； （三）船舶及有关作业单位从事有污染风险的作业活动，未采取污染防治措施； （四）船舶进行散装液体污染危害性货物的过驳作业，未编制方案或者未按照规定报经批准。 违反本法规定，采取冲滩方式进行船舶拆解作业的，由海事管理机构、渔业渔政主管部门按照职责分工责令停止违法行为，处十万元以上一百万元以下的罚款。 违反本法规定，进入中华人民共和国内河的国际航线船舶，排放不符合规定的船舶压载水的，由海事管理机构、渔业渔政主管部门按照职责分工责令停止违法行为，处二万元以上二十万元以下的罚款。 第一千一百四十四条 违反本法规定，有下列情形之一的，由海事管理机构、渔业渔政主管部门按照职责分工责令改正，处二万元以上二十万元以下的罚款： （一）港口、码头、装卸站、船舶修造厂未按照规定配备或者有效运行船舶污染物、废弃物接收设施； （二）从事船舶污染物、废弃物接收和船舱清洗作业活动，不具备相应接收处理能力。 第一千一百四十五条 违反本法规定，有下列情形之一的，由生态环境主管部门责令停止违法行为，处十万元以上五十万元以下的罚款，并报经有批准权的人民政府批准，责令拆除或者关闭： （一）在饮用水水源一级保护区内新建、改建、扩建与供水设施和保护水源无关的建设项目； （二）在饮用水水源二级保护区内新建、改建、扩建排放污染物的建设项目； （三）在饮用水水源准保护区内新建、扩建对水体污染严重的建设项目，或者改建建设项目增加排污量。 违反本法规定，在饮用水水源一级保护区内从事网箱养殖或者组织进行旅游、垂钓或者其他可能污染饮用水水体的活动的，由生态环境主管部门责令停止违法行为，处二万元以上十万元以下的罚款。个人在饮用水水源一级保护区内游泳、垂钓或者从事其他可能污染饮用水水体的活动的，由生态环境主管部门责令停止违法行为，可以处五百元以下的罚款。 违反本法规定，饮用水供水单位供水水质不符合国家规定标准的，由供水主管部门责令改正，处二万元以上二十万元以下的罚款；情节严重的，报经有批准权的人民政府批准，可以责令停业整顿。 第六节 违反海洋污染防治规定 第一千一百四十六条 违反本法第二编第四分编规定，适用本节规定予以行政处罚。 第一千一百四十七条 违反本法规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款，可以责令采取限制生产、停产整治等措施；情节严重的，报经有批准权的人民政府批准，责令停业、关闭： （一）向海域排放油类、酸液、碱液； （二）向海域排放海洋油气装备的残油、废油； （三）向海域排放剧毒废液； （四）向海域排放钻井使用的油基泥浆和其他有毒复合泥浆； （五）向海域排放未达标的含油污水和油性混合物； （六）向海域处置含油的工业固体废物； （七）违反国家规定或者标准，向海域排放含热废水，含病原体的医疗污水、生活污水和工业废水，含不易降解的有机物、重金属的废水； （八）在岸滩弃置、堆放、处理固体废物。 有前款除第三项以外情形之一的，处十万元以上一百万元以下的罚款；有前款第三项情形的，处二十万元以上二百万元以下的罚款。 个人擅自在岸滩弃置、堆放和处理生活垃圾的，按次处一百元以上一千元以下的罚款。 第一千一百四十八条 违反本法规定，从事海水养殖活动有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处五千元以上五万元以下的罚款；情节严重的，处五万元以上二十万元以下的罚款，报经有批准权的人民政府批准，责令停业、关闭： （一）违反养殖规模、养殖密度规定； （二）违反投饵、投肥、投饲、投药规定。 第一千一百四十九条 违反本法规定，在依法划定的自然保护地、重要渔业水域及其他需要特别保护的区域建设污染环境、破坏生态的海岸工程和海洋工程建设项目或者从事其他活动，或者在沿海陆域建设不符合国家产业政策的生产项目的，由县级以上人民政府按照管理权限责令关闭。 第一千一百五十条 违反本法规定，海岸工程和海洋工程建设项目有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令停止违法行为、消除危害，处二十万元以上一百万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭： （一）使用含超标放射性物质或者易溶出有毒有害物质的材料； （二）造成领海基点及其周边环境的侵蚀、淤积或者损害； （三）危及领海基点稳定。 第一千一百五十一条 违反本法规定进行海洋油气勘探开发活动，造成海洋环境污染的，由海警机构责令改正，给予警告，并处二十万元以上一百万元以下的罚款。 第一千一百五十二条 违反本法规定，有下列情形之一的，由国务院生态环境主管部门及其海域派出机构、海事管理机构或者海警机构按照职责分工责令改正，处以罚款，暂扣或者吊销倾倒许可证，必要时可以扣押船舶；情节严重的，报经有批准权的人民政府批准，责令停业、关闭： （一）未取得倾倒许可证向海洋倾倒废弃物； （二）未按照倾倒许可证的规定倾倒废弃物； （三）未安装使用符合要求的海洋倾倒在线监控设备并与监管系统联网； （四）未按照规定报告倾倒情况； （五）倾倒废弃物的船舶驶出港口未报告； （六）获准倾倒废弃物的单位未依照本法规定委托实施废弃物海洋倾倒作业或者未监督实施； （七）海上焚烧废弃物。 有前款第五项情形的，对违法船舶的所有人、经营人或者管理人处三千元以上三万元以下的罚款，对船长、责任船员或者其他责任人员处五百元以上五千元以下的罚款；有前款第四项情形的，按次处五千元以上二万元以下的罚款；有前款第三项情形的，处二万元以上二十万元以下的罚款；有前款第六项情形的，处三万元以上三十万元以下的罚款；有前款第一项情形的，处二十万元以上二百万元以下的罚款；有前款第七项情形的，处五十万元以上五百万元以下的罚款。有前款第一项、第七项情形之一，二年内受到行政处罚三次以上的，三年内不得从事废弃物海洋倾倒活动；有前款第二项情形的，处二十万元以上一百万元以下的罚款，被吊销倾倒许可证的，三年内不得从事废弃物海洋倾倒活动。 违反本法规定，以欺骗、贿赂等不正当手段申请取得倾倒许可证的，由国务院生态环境主管部门及其海域派出机构依法撤销倾倒许可证，并处二十万元以上五十万元以下的罚款；三年内不得再次申请倾倒许可证。 第一千一百五十三条 违反本法规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款： （一）船舶向海域排放船舶垃圾、生活污水、含油污水、含有毒有害物质污水、废气等污染物、废弃物及其他有害物质； （二）向海洋排放不符合规定的船舶压载水和沉积物； （三）载运具有污染危害性货物的船舶未经批准进出港口或者装卸作业； （四）船舶进行散装液体污染危害性货物的过驳作业，未编制作业方案或者未按照规定报经批准； （五）装卸油类及有毒有害货物的作业，船岸双方未遵守安全防污操作规程。 有前款第二项至第五项情形之一的，处二万元以上十万元以下的罚款；有前款第一项情形的，处十万元以上五十万元以下的罚款。 第一千一百五十四条 违反本法规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款： （一）船舶的材料、结构、配备的防污设备和器材不符合国家防治船舶污染海洋环境规定或者未经检验合格； （二）船舶未持有防治海洋环境污染的证书、文书； （三）船舶进行涉及船舶污染物、压载水和沉积物等排放及操作，未按照规定监测、监控，或者未如实记录和保存； （四）未在船上备有有害材料清单，未在船舶建造、营运和维修过程中持续更新有害材料清单，或者未在船舶拆解前将有害材料清单提供给从事船舶拆解的单位； （五）船舶采取措施提高能效水平未达到有关规定； （六）进入船舶污染物排放控制区的船舶不符合船舶污染物排放相关控制要求； （七）具备岸电使用条件的船舶靠港，不按照国家规定使用岸电； （八）具备岸电供应能力的港口经营人、岸电供电企业未按照国家规定为具备岸电使用条件的船舶提供岸电。 有前款第四项情形的，处二万元以下的罚款；有前款第一项、第二项情形之一的，处一万元以上十万元以下的罚款，拒不改正的，责令船舶临时停航；有前款第三项、第五项情形之一的，处一万元以上十万元以下的罚款；有前款第六项情形的，处三万元以上三十万元以下的罚款；有前款第七项、第八项情形之一的，处一万元以上十万元以下的罚款，情节严重的，处十万元以上五十万元以下的罚款。 第一千一百五十五条 违反本法规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款： （一）从事船舶污染物、废弃物接收和船舶清舱、洗舱作业活动，不具备相应接收处理能力； （二）港口、码头、装卸站、船舶修造拆解单位未按照规定配备或者有效运行船舶污染物、废弃物接收设施； （三）从事船舶拆解、旧船改装、打捞和其他水上、水下施工作业，造成海洋环境污染损害； （四）采取冲滩方式在海岸进行船舶拆解作业。 有前款第一项、第二项情形之一的，处二万元以上二十万元以下的罚款；有前款第三项情形的，处五万元以上二十万元以下的罚款；有前款第四项情形的，处十万元以上一百万元以下的罚款。 第一千一百五十六条 违反本法规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款： （一）未报或者谎报船舶载运污染危害性货物事先申报事项； （二）托运人未将托运的污染危害性货物的正式名称、污染危害性以及应当采取的防护措施如实告知承运人； （三）托运人交付承运人的污染危害性货物的单证、包装、标志、数量限制等不符合对所交付货物的有关规定； （四）托运人在托运的普通货物中夹带污染危害性货物或者将污染危害性货物谎报为普通货物； （五）需要船舶载运污染危害性不明的货物，未按照规定事先进行评估。 有前款第一项情形的，处一万元以上五万元以下的罚款；有前款第三项、第五项情形之一的，处二万元以上十万元以下的罚款；有前款第二项情形的，处五万元以上十万元以下的罚款；有前款第四项情形的，处十万元以上二十万元以下的罚款。 第一千一百五十七条 违反本法规定，未按照国家规定缴纳倾倒费的，由国务院生态环境主管部门及其海域派出机构责令限期缴纳；逾期拒不缴纳的，处应缴纳倾倒费数额一倍以上三倍以下的罚款，并可以报经有批准权的人民政府批准，责令停业、关闭。 第七节 违反土壤污染防治规定 第一千一百五十八条 违反本法第二编第五分编规定，适用本节规定予以行政处罚。 第一千一百五十九条 违反本法规定，有下列情形之一的，由地方人民政府负有生态环境保护监督管理职责的部门按照职责分工责令改正，处以罚款；拒不改正的，责令限制生产、停产整治： （一）土壤污染重点监管单位未建立并实施土壤、地下水污染隐患排查整治制度； （二）土壤污染重点监管单位拆除设施、设备或者建筑物、构筑物未制定并实施土壤污染防治工作方案； （三）拆除设施、设备或者建筑物、构筑物未采取土壤污染防治措施； （四）尾矿库运营、管理单位未按照规定采取有效措施防止土壤污染，未针对风险隐患采取相应措施，或者需要重点监管的尾矿库的运营、管理单位未进行土壤污染状况监测或者定期评估； （五）建设和运行污水集中处理设施、固体废物处置设施，未依照法律法规和相关标准的要求采取有效措施防止土壤污染。 有前款情形之一的，处二万元以上二十万元以下的罚款；有前款第二项至第五项情形之一，造成严重后果的，处二十万元以上二百万元以下的罚款。 第一千一百六十条 违反本法规定，向农用地排放重金属或者其他有毒有害物质含量超标的污水、污泥，以及可能造成土壤污染的清淤底泥、尾矿、矿渣等的，由生态环境主管部门责令改正，没收违法所得，并处十万元以上五十万元以下的罚款；情节严重的，并处五十万元以上二百万元以下的罚款，并将案件移送公安机关，由公安机关对直接负责的主管人员和其他直接责任人员处五日以上十五日以下拘留。 第一千一百六十一条 违反本法规定，农业投入品生产者、销售者、使用者未及时回收农药、肥料等农业投入品的包装废弃物或者农用薄膜，或者未将农药包装废弃物交由专门的机构或者组织进行无害化处理的，由农业农村主管部门责令改正，处一万元以上十万元以下的罚款；农业投入品使用者为个人的，可以处二百元以上二千元以下的罚款。 第一千一百六十二条 违反本法规定，有下列情形之一的，由生态环境主管部门责令改正，没收违法所得，并处十万元以上五十万元以下的罚款；情节严重的，并处五十万元以上一百万元以下的罚款；对直接负责的主管人员和其他直接责任人员处五千元以上二万元以下的罚款： （一）在土壤中使用重金属含量超标的降阻产品； （二）未单独收集、存放开发建设过程中剥离的表土； （三）实施风险管控、修复活动未对产生的污染物采取处理、处置措施，或者对土壤、周边环境造成新的污染； （四）转运的污染土壤属于危险废物的，修复施工单位未依法进行处置； （五）转运污染土壤，未将运输时间、方式、线路和污染土壤数量、去向、最终处置措施等提前报所在地和接受地生态环境主管部门； （六）在永久基本农田集中区域新建可能造成土壤污染的建设项目； （七）未达到土壤污染风险评估报告确定的风险管控、修复目标或者未按照规定进行土壤污染状况调查和土壤污染风险评估、风险管控、修复、风险管控效果评估、修复效果评估的建设用地地块，开工建设与风险管控、修复无关的项目。 第一千一百六十三条 违反本法规定，将重金属或者其他有毒有害物质含量超标的工业固体废物、生活垃圾或者污染土壤用于土地复垦的，由生态环境主管部门责令改正，没收违法所得，并处十万元以上一百万元以下的罚款。 第一千一百六十四条 违反本法规定，土壤污染责任人或者土地使用权人未按照要求实施后期管理的，由负有生态环境保护监督管理职责的部门按照职责分工责令改正，处一万元以上五万元以下的罚款；情节严重的，处五万元以上五十万元以下的罚款。 第一千一百六十五条 违反本法规定，土壤污染责任人或者土地使用权人有下列情形之一的，由地方人民政府负有生态环境保护监督管理职责的部门按照职责分工责令改正，处二万元以上二十万元以下的罚款；拒不改正的，处二十万元以上一百万元以下的罚款，并委托他人代为履行，所需费用由土壤污染责任人或者土地使用权人承担；对直接负责的主管人员和其他直接责任人员处五千元以上二万元以下的罚款： （一）对土壤污染状况普查、详查和监测、现场检查表明有土壤污染风险的建设用地地块，用途变更为居住、公共管理与公共服务用地的地块等，未进行土壤污染状况调查； （二）土壤污染重点监管单位生产经营用地的用途变更或者在土地使用权收回、转让前，未进行土壤污染状况调查； （三）对土壤污染状况调查报告评审表明污染物含量超过土壤污染风险管控标准的建设用地地块等，未进行土壤污染风险评估； （四）对安全利用类和严格管控类农用地地块，建设用地土壤污染风险管控和修复名录中的地块等，未采取相应风险管控措施； （五）未按照规定实施修复； （六）风险管控、修复活动完成后，未另行委托有关单位对风险管控效果、修复效果进行评估。 土壤污染责任人或者土地使用权人有前款第四项、第五项情形之一，情节严重的，由负有生态环境保护监督管理职责的部门将案件移送公安机关，由公安机关对直接负责的主管人员和其他直接责任人员处五日以上十五日以下拘留。 第一千一百六十六条 违反本法规定，有下列情形之一的，由生态环境主管部门、农业农村主管部门、林业草原主管部门按照职责分工责令改正；拒不改正的，处二万元以上十万元以下的罚款： （一）土壤污染重点监管单位未按年度报告有毒有害物质排放情况； （二）土壤污染重点监管单位未将贮存有毒有害物质的地下储罐信息报生态环境主管部门； （三）土地使用权人未依法报送土壤污染调查报告； （四）土壤污染责任人、土地使用权人未依法报送土壤污染风险评估报告； （五）土壤污染责任人未依法报告风险管控措施； （六）土壤污染责任人、土地使用权人未依法将修复方案、效果评估报告备案。 第一千一百六十七条 违反本法规定，有下列情形之一的，由生态环境主管部门、工业和信息化主管部门按照职责分工责令改正；拒不改正的，处一万元以上五万元以下的罚款： （一）土壤污染重点监管单位未将土壤污染防治工作方案备案； （二）土地使用权人未将土壤污染状况调查报告备案。 第八节 违反固体废物污染防治规定 第一千一百六十八条 违反本法第二编第六分编规定，适用本节规定予以行政处罚。 第一千一百六十九条 违反本法规定，擅自倾倒、堆放、丢弃、抛撒、遗撒、焚烧固体废物的，由生态环境主管部门、城镇排水主管部门、环境卫生主管部门按照职责分工责令停止违法行为，采取治理措施消除污染，没收违法所得，并处十万元以上一百万元以下的罚款；情节严重的，责令限制生产、停产整治；拒不采取治理措施的，指定有治理能力的单位代为治理，所需费用由违法者承担。 前款规定的固体废物为危险废物、城镇污水处理设施产生的污泥和处理后的污泥的，处二十万元以上二百万元以下的罚款；对直接负责的主管人员和其他直接责任人员处二万元以上十万元以下的罚款；造成严重后果的，处二百万元以上五百万元以下的罚款。 个人擅自倾倒、堆放、丢弃、抛撒、遗撒、焚烧个人产生的生活垃圾、建筑垃圾的，由环境卫生主管部门责令改正，处一百元以上一千元以下的罚款。 第一千一百七十条 违反本法规定，未采取防范措施，造成工业固体废物扬散、流失、渗漏或者其他环境污染的，由生态环境主管部门责令改正，处十万元以上一百万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。工业固体废物为危险废物的，罚款数额为二十万元以上二百万元以下。 第一千一百七十一条 违反本法规定，有下列情形之一的，由生态环境主管部门责令改正，没收违法所得，并处以罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭： （一）在生态保护红线区域、永久基本农田集中区域和其他需要特别保护的区域内，建设工业固体废物、建筑垃圾、危险废物集中贮存、利用、处置的设施、场所和生活垃圾填埋场； （二）转移固体废物出省、自治区、直辖市行政区域贮存、处置未经批准； （三）转移固体废物出省、自治区、直辖市行政区域利用，未提前报送信息； （四）产生工业固体废物的单位违反本法规定委托他人运输、利用、处置工业固体废物； （五）贮存工业固体废物未采取符合国家生态环境保护标准的防护措施； （六）单位和其他生产经营者违反固体废物管理其他要求，污染环境、破坏生态。 有前款第三项情形的，处五万元以上五十万元以下的罚款；有前款除第三项以外情形之一的，处十万元以上一百万元以下的罚款。对前款第六项情形的处罚，有关法律、行政法规另有规定的，依照其规定。 违反本法规定，产生工业固体废物的单位未建立工业固体废物管理台账并如实记录的，由生态环境主管部门责令改正；拒不改正的，处五万元以上二十万元以下的罚款。 第一千一百七十二条 违反本法规定，城镇污水集中处理设施的运营单位或者污泥无害化处理处置单位对污泥流向、用途、用量等未进行跟踪、记录，或者处理处置后的污泥不符合国家标准的，由城镇排水主管部门责令改正，给予警告；造成严重后果的，并处十万元以上二十万元以下的罚款；拒不改正的，指定有治理能力的单位代为治理，所需费用由违法者承担。 第一千一百七十三条 违反本法规定，尾矿、煤矸石、废石等矿业固体废物贮存设施停止使用后，未按照国家有关生态环境保护等规定进行封场的，由生态环境主管部门责令改正，处二十万元以上一百万元以下的罚款。 第一千一百七十四条 违反本法规定，有下列情形之一的，由环境卫生主管部门责令改正，没收违法所得，并处以罚款： （一）擅自关闭、闲置或者拆除生活垃圾处理设施、场所； （二）产生、收集厨余垃圾的单位和其他生产经营者未将厨余垃圾交由具备相应资质条件的单位进行无害化处理； （三）工程施工单位未按照规定对工程施工过程中产生的建筑垃圾进行利用或者处置； （四）工程施工单位未编制建筑垃圾处理方案并报备案，或者未及时清运工程施工过程中产生的建筑垃圾。 单位有前款情形之一的，处十万元以上一百万元以下的罚款；个人有前款第二项情形的，处一百元以上五百元以下的罚款。 违反本法规定，未在指定的地点分类投放生活垃圾的，由环境卫生主管部门责令改正；拒不改正的，对单位处五万元以上五十万元以下的罚款，对个人依法处以罚款。 第一千一百七十五条 违反本法规定，有下列情形之一的，由生态环境主管部门责令改正，没收违法所得，并处以罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭： （一）未设置危险废物识别标志； （二）未制定危险废物管理计划，或者未申报危险废物有关资料； （三）未建立危险废物管理台账并如实记录； （四）未按照国家规定和生态环境保护标准贮存、利用、处置危险废物，或者将危险废物混入非危险废物中贮存； （五）将危险废物提供或者委托给无许可证的单位或者其他生产经营者从事相关活动； （六）未经安全性处置，混合收集、贮存、运输、处置性质不相容的危险废物； （七）未填写、运行危险废物转移联单； （八）未经批准擅自转移危险废物； （九）将危险废物与旅客在同一运输工具上载运； （十）未经过消除污染处理，将收集、贮存、运输、利用、处置危险废物的场所、设施、设备和容器、包装物及其他物品转作他用； （十一）未制定危险废物意外事故防范措施和应急预案。 有前款第一项、第二项、第三项、第四项、第六项、第七项、第九项、第十项、第十一项情形之一的，处五万元以上二十万元以下的罚款，拒不改正的，处二十万元以上一百万元以下的罚款；有前款第五项、第八项情形之一的，处二十万元以上二百万元以下的罚款。 第一千一百七十六条 生产、销售和使用有毒有害物质超过国家标准的建筑材料和装修材料的，依照《中华人民共和国产品质量法》和有关民事、刑事法律的规定追究法律责任。 第一千一百七十七条 违反本法规定，危险废物产生者未按照规定处置其产生的危险废物，被责令改正后拒不改正的，由生态环境主管部门组织代为处置，处置费用由危险废物产生者承担，处十万元以上一百万元以下的罚款。 第一千一百七十八条 违反本法规定，企业事业单位无许可证从事收集、贮存、利用、处置危险废物经营活动的，由生态环境主管部门责令改正，没收违法所得，对收集、贮存危险废物经营活动并处二十万元以上一百万元以下的罚款，对利用、处置危险废物经营活动并处一百万元以上五百万元以下的罚款，报经有批准权的人民政府批准，责令停业、关闭；对法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员，处十万元以上一百万元以下的罚款。 违反本法规定，企业事业单位未按照许可证规定从事收集、贮存、利用、处置危险废物经营活动的，由生态环境主管部门责令改正，没收违法所得，限制生产、停产整治，对收集、贮存危险废物经营活动并处十万元以上五十万元以下的罚款，对利用、处置危险废物经营活动并处五十万元以上二百万元以下的罚款；对法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员，处五万元以上五十万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭，由发证机关吊销许可证。 其他生产经营者有前两款违法情形的，由生态环境主管部门责令改正，没收违法所得，并处二万元以上十万元以下的罚款；情节严重的，并处十万元以上五十万元以下的罚款。 第一千一百七十九条 违反本法规定，有下列情形之一的，由公安机关对法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员处十日以上十五日以下拘留；情节较轻的，处五日以上十日以下拘留： （一）擅自倾倒、堆放、丢弃、抛撒、遗撒、焚烧固体废物，造成严重后果； （二）未采取防范措施，造成危险废物扬散、流失、渗漏或者其他严重后果； （三）未经批准擅自转移危险废物； （四）在生态保护红线区域、永久基本农田集中区域和其他需要特别保护的区域内，建设工业固体废物、建筑垃圾、危险废物集中贮存、利用、处置的设施、场所和生活垃圾填埋场； （五）无许可证或者未按照许可证规定从事收集、贮存、利用、处置危险废物经营活动； （六）将危险废物提供或者委托给无许可证的单位或者个人从事相关活动。 第一千一百八十条 执法过程中查获的固体废物无法确定责任人或者无法退运的，由所在地县级以上地方人民政府组织处理。 第九节 违反噪声污染防治规定 第一千一百八十一条 违反本法第二编第七分编规定，适用本节规定予以行政处罚。 第一千一百八十二条 违反本法规定，生产、进口、销售超过噪声限值的产品的，由市场监督管理部门、海关按照职责分工责令改正，没收违法所得，并处货值金额一倍以上五倍以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。 第一千一百八十三条 违反本法规定，建设单位建设噪声敏感建筑物不符合民用建筑隔声设计标准要求的，由住房城乡建设主管部门责令改正，处建设工程合同价款百分之二以上百分之四以下的罚款。 违反本法规定，建设单位在噪声敏感建筑物禁止建设区域新建与航空无关的噪声敏感建筑物的，由地方人民政府指定的部门责令停止违法行为，处建设工程合同价款百分之二以上百分之十以下的罚款，报经有批准权的人民政府批准，责令拆除。 第一千一百八十四条 违反本法规定，在噪声敏感建筑物集中区域新建排放噪声的工业企业的，由生态环境主管部门责令停止违法行为，处十万元以上五十万元以下的罚款，报经有批准权的人民政府批准，责令停业、关闭。 违反本法规定，在噪声敏感建筑物集中区域改建、扩建工业企业，未采取有效措施防止工业噪声污染的，由生态环境主管部门责令改正，处十万元以上五十万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业、关闭。 第一千一百八十五条 违反本法规定，建设单位、施工单位有下列情形之一的，由工程所在地人民政府指定的部门责令改正，处一万元以上十万元以下的罚款；拒不改正的，可以责令暂停施工： （一）超过噪声排放标准排放建筑施工噪声； （二）未依法取得连续施工作业证明，在噪声敏感建筑物集中区域夜间进行产生噪声的建筑施工作业。 第一千一百八十六条 违反本法规定，有下列情形之一的，由工程所在地人民政府指定的部门责令改正，处五千元以上五万元以下的罚款；拒不改正的，处五万元以上二十万元以下的罚款： （一）施工单位未按照规定制定噪声污染防治实施方案，或者未采取有效措施减少振动、降低噪声； （二）建设单位未监督施工单位落实噪声污染防治实施方案； （三）建设单位、施工单位依法取得连续施工作业证明但未按照规定公告附近居民。 第一千一百八十七条 违反本法规定，驾驶拆除或者损坏消声器、加装排气管等擅自改装的机动车轰鸣、疾驶，机动车运行时未按照规定使用声响装置，或者违反禁止机动车行驶和使用声响装置的路段和时间规定的，由公安机关交通管理部门给予警告，处二百元以上二千元以下的罚款、暂扣机动车驾驶证等处罚。 违反本法规定，铁路机车车辆、城市轨道交通车辆、机动船舶等交通运输工具运行时未按照规定使用声响装置的，由交通运输主管部门、铁路监督管理部门、海事管理机构或者地方人民政府指定的城市轨道交通有关部门按照职责分工责令改正，处五千元以上一万元以下的罚款。 第一千一百八十八条 违反本法规定，有下列情形之一的，由交通运输主管部门、铁路监督管理部门、民用航空主管部门或者地方人民政府指定的城市道路、城市轨道交通有关部门按照职责分工责令改正，处五千元以上五万元以下的罚款；拒不改正的，处五万元以上二十万元以下的罚款： （一）公路养护管理单位、城市道路养护维修单位、城市轨道交通运营单位、铁路运输企业未履行维护和保养义务，未保持减少振动、降低噪声设施正常运行； （二）在限制建设区域建设噪声敏感建筑物，建设单位未进行建筑隔声设计或者不符合民用建筑隔声设计标准要求； （三）民用机场管理机构、航空运输企业、通用航空企业未采取措施防止、减轻民用航空器噪声污染； （四）负有责任的企业事业单位未按照噪声污染综合治理方案的要求采取有效措施减轻噪声污染。 第一千一百八十九条 违反本法规定，有下列情形之一的，由地方人民政府指定的部门责令改正，处五千元以上五万元以下的罚款；拒不改正的，处五万元以上二十万元以下的罚款，并可以报经有批准权的人民政府批准，责令停业： （一）超过噪声排放标准排放社会生活噪声； （二）在商业经营活动中使用高音广播喇叭或者采用其他持续反复发出高噪声的方法进行广告宣传； （三）未对商业经营活动中产生的其他噪声采取有效措施造成噪声污染。 第一千一百九十条 违反本法规定，有下列情形之一的，由地方人民政府指定的部门说服教育，责令改正；拒不改正的，给予警告，对个人可以处二百元以上一千元以下的罚款，对单位可以处二千元以上二万元以下的罚款： （一）在噪声敏感建筑物集中区域使用高音广播喇叭； （二）在公共场所组织或者开展娱乐、健身等活动，未遵守公共场所管理者有关活动区域、时段、音量等规定，未采取有效措施造成噪声污染，或者违反规定使用音响器材产生过大音量； （三）对已竣工交付使用的建筑物进行室内装修活动，未在限定作业时间内进行，或者未采取有效措施造成噪声污染； （四）其他违反法律法规规定造成社会生活噪声污染。 第一千一百九十一条 违反本法规定，新建居民住房的房地产开发经营者未在销售场所公示住房可能受到噪声影响的情况以及采取或者拟采取的防治措施，或者未纳入买卖合同，未在买卖合同中明确住房的共用设施设备位置或者建筑隔声情况的，由住房城乡建设主管部门责令改正，处一万元以上五万元以下的罚款；拒不改正的，责令暂停销售。 违反本法规定，有下列情形之一的，由地方人民政府指定的部门责令改正，处五千元以上五万元以下的罚款；拒不改正的，处五万元以上二十万元以下的罚款： （一）居民住宅区安装共用设施设备，设置不合理或者未采取减少振动、降低噪声的措施，不符合民用建筑隔声设计标准要求； （二）对已建成使用的居民住宅区共用设施设备，未进行维护管理，不符合民用建筑隔声设计标准要求。 第一千一百九十二条 违反本法规定，产生社会生活噪声，经劝阻、调解和处理未能制止，持续干扰他人正常生活、工作和学习，或者有其他扰乱公共秩序、妨害社会管理等违反治安管理行为的，由公安机关依法给予治安管理处罚。 第十节 违反放射性污染防治规定 第一千一百九十三条 违反本法第二编第八分编等规定，适用本节规定予以行政处罚。 第一千一百九十四条 违反本法规定，向环境排放禁止排放的放射性废气、废液，倾倒放射性固体废物的，由生态环境主管部门责令停止违法行为，限期采取治理措施消除污染，处二十万元以上二百万元以下的罚款；逾期不采取治理措施的，指定有治理能力的单位代为治理，所需费用由违法者承担；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。 第一千一百九十五条 违反本法规定，在内河水域和海上处置放射性固体废物、放射性物质的，由生态环境主管部门责令停止违法行为，限期采取治理措施消除污染，处五十万元以上二百万元以下的罚款；逾期不采取治理措施的，指定有治理能力的单位代为治理，所需费用由违法者承担。 第一千一百九十六条 违反本法规定，有下列情形之一的，由生态环境主管部门、核工业主管部门按照职责分工责令限期改正，处二万元以上二十万元以下的罚款；逾期不改正的，责令限制生产、停产整治： （一）不按照规定设置放射性标识、标志、中文警示说明； （二）不按照规定建立健全安全保卫制度； （三）不按照规定单独存放放射性同位素； （四）不按照规定采取安全和防护措施； （五）未对其工作人员进行放射性安全教育、培训和采取有效的防护安全措施。 第一千一百九十七条 违反本法规定，未经核设施安全许可，核设施营运单位擅自进行核设施的选址、建造、运行、退役等活动的，依照《中华人民共和国核安全法》的规定追究法律责任。 第一千一百九十八条 违反本法规定，生产、销售、使用、转让、进出口、贮存放射性同位素和射线装置以及装备有放射性同位素的仪表的，由生态环境主管部门、市场监督管理部门、海关按照职责分工责令停止违法行为，限期改正，没收违法所得，并处五万元以上五十万元以下的罚款；逾期不改正的，处违法所得一倍以上五倍以下的罚款，违法所得不足五十万元的，以五十万元计算，责令限制生产、停产整治或者吊销许可证。 违反本法规定，在网络上销售放射性同位素和射线装置的，由市场监督管理部门责令停止违法行为，限期改正，没收违法所得，并处违法所得一倍以上五倍以下的罚款，违法所得不足五十万元的，以五十万元计算。 第一千一百九十九条 违反本法规定，有下列情形之一的，由生态环境主管部门责令停止违法行为，限期改正，处五万元以上五十万元以下的罚款；逾期不改正的，由原发证机关指定有处理能力的单位代为处理或者实施退役，费用由生产、销售、使用放射性同位素和射线装置的单位承担： （一）生产放射源的单位和其他生产经营者未按照规定回收和利用废旧放射源； （二）使用放射源的单位和其他生产经营者未按照规定交回、送交废旧放射源； （三）使用对人体健康和生态环境潜在危害程度较高的放射源的场所和生产放射性同位素的场所，以及终结运行后产生放射性污染的射线装置，未依法实施退役。 第一千二百条 违反本法规定，不按照规定报告放射源丢失、被盗情况的，由公安机关、卫生健康主管部门、生态环境主管部门按照职责分工责令限期改正，处五万元以上五十万元以下的罚款；情节严重的，责令限制生产、停产整治。 第一千二百零一条 违反本法规定，有下列情形之一的，由生态环境主管部门责令停止违法行为，限期改正，处以罚款： （一）生产、使用放射性同位素和射线装置的单位和其他生产经营者未按照规定对产生的放射性废物进行收集、包装、贮存； （二）未建造尾矿库等设施，或者建造尾矿库等设施不符合放射性污染防治的要求，贮存、处置铀（钍）矿和伴生放射性矿的尾矿等放射性固体废物； （三）不按照规定处理或者贮存不得向环境排放的放射性废液； （四）不按照规定的方式排放放射性废液； （五）将放射性废物提供或者委托给无许可证的单位或者个人贮存、处理和处置。 有前款第一项、第三项情形之一的，处五万元以上五十万元以下的罚款；有前款第二项、第四项、第五项情形之一的，处十万元以上一百万元以下的罚款。 第一千二百零二条 违反本法规定，放射性固体废物产生者，不按照国家规定对其产生的放射性固体废物进行处理和处置的，由生态环境主管部门责令停止违法行为，限期改正，处五万元以上二十万元以下的罚款；逾期不改正的，指定有处理能力的单位代为处理、处置，所需费用由放射性固体废物产生者承担，并处二十万元以上一百万元以下的罚款。 第一千二百零三条 违反本法规定，未经许可擅自从事贮存、处理和处置放射性废物活动的，由省级以上人民政府生态环境主管部门没收违法所得，并处一百万元以上五百万元以下的罚款，报经有批准权的人民政府批准，责令停业、关闭。 违反本法规定，未按照许可证规定从事贮存、处理和处置放射性废物活动的，由省级以上人民政府生态环境主管部门责令限期改正，没收违法所得，并处五十万元以上五百万元以下的罚款；情节严重的，责令限制生产、停产整治或者吊销许可证。 第十一节 违反化学物质污染风险管控、电磁辐射和光污染防治规定 第一千二百零四条 违反本法第二编第九分编规定，适用本节规定予以行政处罚。 第一千二百零五条 违反本法规定，未按照重点管控新污染物禁止或者限制环境风险管控措施要求，生产或者进口重点管控新污染物清单中的化学物质，或者使用重点管控新污染物清单中化学物质生产产品的，由生态环境主管部门或者其他负有化学物质生产、进口、使用监督管理职责的部门按照职责分工责令改正，处十万元以上五十万元以下的罚款；拒不改正的，处五十万元以上一百万元以下的罚款，责令限制生产、停产整治；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。 第一千二百零六条 违反本法规定，不按照新化学物质环境管理登记证的要求生产、进口新化学物质的，由生态环境主管部门或者其他负有化学物质生产、进口监督管理职责的部门按照职责分工责令改正，处二十万元以上一百万元以下的罚款；拒不改正的，处一百万元以上二百万元以下的罚款，责令限制生产、停产整治；情节严重的，吊销新化学物质环境管理登记证书，报经有批准权的人民政府批准，责令停业、关闭。 第一千二百零七条 违反本法规定，无新化学物质环境管理登记证，生产、进口新化学物质，或者使用无新化学物质环境管理登记证的企业事业单位生产、进口的新化学物质生产产品的，由生态环境主管部门或者其他负有化学物质生产、进口、使用监督管理职责的部门按照职责分工责令改正，处二十万元以上一百万元以下的罚款；拒不改正的，处一百万元以上二百万元以下的罚款，责令限制生产、停产整治；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。 第一千二百零八条 违反本法规定，未实行排污许可管理的企业事业单位，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处二万元以上二十万元以下的罚款；拒不改正的，可以责令限制生产、停产整治： （一）超过电磁辐射排放标准排放电磁辐射； （二）未依法采取电磁辐射污染防治措施防止、减轻电磁辐射污染。 第一千二百零九条 违反本法规定，生产、进口、销售超过电磁辐射限值的产品的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，没收违法所得，并处货值金额一倍以上五倍以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。 第一千二百一十条 违反本法规定，广告屏、广告牌、灯箱、媒体立面墙、道路、体育场、施工场地等，未采取有效措施防止、减轻光污染，干扰他人正常生活、交通出行的，由住房城乡建设主管部门、生态环境主管部门、交通运输主管部门、公安机关交通管理部门按照职责分工责令改正；拒不改正的，处五千元以上五万元以下的罚款。 第十二节 违反生态保护管理规定 第一千二百一十一条 违反本法规定，违反国土空间规划，在禁止开垦的范围内从事土地开发利用活动，或者未经批准，擅自改变土地或者海域用途的，由自然资源、林业草原等部门按照职责分工，依照《中华人民共和国土地管理法》、《中华人民共和国海域使用管理法》、《中华人民共和国水法》等法律法规的规定予以处罚。 第一千二百一十二条 违反本法规定，破坏森林、草原、湿地等重要生态系统，或者非法侵占、违法利用、违法占用江河湖泊水域或者岸线的，由林业草原、水行政、生态环境等部门按照职责分工，依照《中华人民共和国森林法》、《中华人民共和国草原法》、《中华人民共和国湿地保护法》等法律法规的规定予以处罚。 第一千二百一十三条 违反本法规定，擅自引进、释放或者丢弃外来物种的，由农业农村主管部门、林业草原主管部门、海关按照职责分工，依照《中华人民共和国生物安全法》、《中华人民共和国野生动物保护法》等法律法规的规定予以没收或者责令限期捕回、找回，并处以罚款。 第一千二百一十四条 违反本法规定，在长江、黄河等重要流域非法侵占、违法利用、违法占用江河湖泊岸线，或者未经批准在水土流失严重、生态脆弱区域开展可能造成水土流失的生产建设活动等的，依照《中华人民共和国长江保护法》、《中华人民共和国黄河保护法》等法律法规的规定予以处罚。 第一千二百一十五条 违反本法规定，在自然保护地、青藏高原等重要区域，有破坏保护界线标志、损害野生动植物等情形的，依照《中华人民共和国国家公园法》、《中华人民共和国青藏高原生态保护法》等法律法规的规定予以处罚。 第一千二百一十六条 违反本法有关海洋生态保护的规定，造成珊瑚礁等海洋生态系统破坏的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正、采取补救措施，处每平方米一千元以上一万元以下的罚款，有违法所得的，没收违法所得。 第一千二百一十七条 违反本法有关海洋生态保护的规定，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款： （一）占用、损害自然岸线； （二）在严格保护岸线范围内开采海砂； （三）在严格保护岸线范围以外的其他区域开发利用海砂资源，未依法采取严格措施保护海洋生态； （四）海砂开采者未依法为载运海砂的船舶提供合法来源证明； （五）未持有合法来源证明载运海砂资源。 有前款第一项情形的，处每米五百元以上一万元以下的罚款；有前款第二项情形的，处货值金额二倍以上二十倍以下的罚款，货值金额不足十万元的，处二十万元以上二百万元以下的罚款；有前款第三项、第四项、第五项情形之一的，处五万元以上五十万元以下的罚款。 第一千二百一十八条 违反本法和有关法律法规的规定，未经批准擅自取用地下水的，由水行政主管部门责令停止违法行为，限期采取补救措施，处二万元以上二十万元以下的罚款；其中，在地下水禁止开采区、限制开采区范围内擅自取用地下水的，处五万元以上五十万元以下的罚款。 第一千二百一十九条 违反本法有关生态保护义务，本节未规定行政处罚的，依照有关法律的规定予以处罚。 第十三节 违反绿色低碳发展管理规定 第一千二百二十条 违反本法规定，生产大型机电设备、机动运输工具以及国务院工业和信息化主管部门指定的其他产品的企业未注明产品材料成分或者不如实注明的，由市场监督管理部门责令限期改正；拒不改正的，处五万元以下的罚款。 第一千二百二十一条 违反本法规定，不实施强制性清洁生产审核或者在清洁生产审核中弄虚作假，或者实施强制性清洁生产审核的企业不报告或者不如实报告审核结果的，由发展改革部门、生态环境主管部门按照职责分工责令限期改正；拒不改正的，处五万元以上五十万元以下的罚款。 违反本法规定，承担评估验收工作的部门或者单位及其工作人员向被评估验收企业收取费用，不如实评估验收或者在评估验收中弄虚作假，或者利用职务上的便利谋取利益的，对负有责任的领导人员和直接责任人员依法给予处分。 第一千二百二十二条 违反本法规定，生产、进口、销售或者使用国家有关目录、名录中禁止或者淘汰的设备、材料、产品，采用国家有关目录、名录中禁止或者淘汰的技术、工艺，或者将淘汰或者限期淘汰的设备、材料、产品转让给他人使用的，由县级以上人民政府指定的部门、海关按照职责分工责令改正，没收违法所得，并处货值金额一倍以上五倍以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。 第一千二百二十三条 违反本法规定，电器电子、机动车、铅蓄电池、动力电池等产品的生产者未按照规定建立与产品销售量相匹配的废旧产品回收体系并向社会公开的，由工业和信息化、商务等部门按照职责分工责令改正；拒不改正的，处五万元以上五十万元以下的罚款。 第一千二百二十四条 违反本法规定，生产经营者未遵守限制商品过度包装的强制性标准的，由市场监督管理部门和有关部门按照职责分工责令改正；拒不改正的，处二千元以上二万元以下的罚款；情节严重的，处二万元以上十万元以下的罚款。 第一千二百二十五条 违反本法规定，未遵守国家有关禁止、限制生产、销售不可降解塑料袋等一次性塑料制品的规定的，由市场监督管理部门责令停止生产、销售，没收违法生产、销售的产品，并处违法生产、销售产品货值金额一倍以上三倍以下的罚款；有违法所得的，没收违法所得；情节严重的，吊销许可证。 违反本法规定，未遵守国家有关禁止、限制使用不可降解塑料袋等一次性塑料制品的规定的，由商务、邮政等部门按照职责分工责令改正，对企业事业单位处一万元以上十万元以下的罚款，对其他生产经营者处五百元以上五千元以下的罚款。 违反本法规定，未按照国家规定报告塑料袋等一次性塑料制品的使用、回收情况的，依照前款有关规定予以处罚。 第一千二百二十六条 违反本法规定，纳入全国碳排放权交易市场的温室气体重点排放单位未报送排放统计核算数据、年度排放报告的，由生态环境主管部门责令改正，处五万元以上五十万元以下的罚款；拒不改正的，可以责令停产整治。 违反本法规定，纳入全国碳排放权交易市场的温室气体重点排放单位未按照规定的期限足额清缴碳排放配额的，由生态环境主管部门责令限期改正，处一百万元以上五百万元以下的罚款；限期内未完成清缴的，处未清缴的碳排放配额清缴时限前一个月市场交易平均成交价格五倍以上十倍以下的罚款，可以责令停产整治。 第一千二百二十七条 违反本法有关绿色低碳义务，本节未规定行政处罚的，依照《中华人民共和国循环经济促进法》、《中华人民共和国能源法》、《中华人民共和国节约能源法》、《中华人民共和国可再生能源法》等法律法规的规定予以处罚。 第十四节 其他违法行为 第一千二百二十八条 除本章第一节至第十三节外，违反本法规定的，适用本节规定予以行政处罚。 第一千二百二十九条 违反本法规定，以拖延、围堵、滞留执法人员等方式拒绝、阻挠监督检查和突发生态环境事件调查处理，或者在接受监督检查和调查处理时弄虚作假或者拒不提供必要资料的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处五万元以上二十万元以下的罚款；对直接负责的主管人员和其他直接责任人员，处五千元以上五万元以下的罚款；构成违反治安管理行为的，由公安机关、海警机构按照职责分工依法予以处罚。 第一千二百三十条 违反本法规定，从事机动车船排放检验、土壤污染调查和评估、污染防治设施维护或者运营、固体废物或者危险废物鉴别等活动的生态环境技术服务机构，未使用符合法律、行政法规规定和国家标准的设施、设备，或者未遵守有关技术规范导致数据失真的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，没收违法所得，并处二万元以上二十万元以下的罚款；拒不改正的，报经有批准权的人民政府批准，责令停业。 违反本法规定，前款所列机构在生态环境服务活动中弄虚作假、出具虚假报告的，由负有生态环境保护监督管理职责的部门、机构按照职责分工没收违法所得，并处十万元以上五十万元以下的罚款；情节严重的，并处五十万元以上二百万元以下的罚款，有许可证的吊销许可证，禁止从事上述业务，报经有批准权的人民政府批准，责令停业、关闭。 有前款规定情形的，由负有生态环境保护监督管理职责的部门、机构按照职责分工对直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款，五年内禁止从事前款规定的业务；情节严重的，十年内禁止从事前款规定的业务。 第一千二百三十一条 违反本法规定，有下列情形之一的，由生态环境主管部门、环境卫生主管部门按照职责分工责令改正，可以处十万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭： （一）从事畜禽规模养殖未及时收集、贮存、清运、处理或者利用养殖过程中产生的畜禽粪污、尸体等废弃物； （二）畜禽养殖场利用未经无害化处理的厨余垃圾饲喂畜禽； （三）向农田灌溉渠道排放未综合利用的畜禽养殖粪污，致使其下游最近的灌溉取水点的水质不符合农田灌溉用水水质标准。 第一千二百三十二条 违反本法规定，经中华人民共和国过境转移危险废物，以及将放射性废物和被放射性污染的物品输入中华人民共和国境内或者经境内转移的，由海关、海事管理机构按照职责分工责令退运或者责令非法运输该危险废物的船舶退出中华人民共和国管辖海域，并处五十万元以上五百万元以下的罚款。 违反本法规定，未事先取得国务院生态环境主管部门书面同意，经中华人民共和国管辖的其他海域转移危险废物的，由海事管理机构责令非法运输该危险废物的船舶退出中华人民共和国管辖海域，处五十万元以上五百万元以下的罚款。 第一千二百三十三条 违反本法规定，排放污染物的企业事业单位未建立污染防治责任制度的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正；拒不改正的，处二万元以上二十万元以下的罚款；情节严重的，可以责令限制生产、停产整治。 第一千二百三十四条 违反本法规定，未按照生态环境准入清单的规定进行生产建设活动的，由生态环境主管部门、自然资源主管部门按照职责分工，责令停止违法行为，没收违法所得，限期拆除并恢复原状，所需费用由违法者承担，并处五十万元以上五百万元以下的罚款，对直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。 第一千二百三十五条 违反本法规定，企业事业单位和其他生产经营者有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正；情节严重的，处一万元以上五万元以下的罚款： （一）未制定环境污染、生态破坏事故或者突发生态环境事件的应急预案； （二）应急预案未报备案； （三）未配备应急设备、器材。 第一千二百三十六条 违反本法规定，造成环境污染、生态破坏事故的，除依法承担赔偿责任外，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令限期采取治理措施，适用本条第二款、第三款的规定处以罚款；对直接负责的主管人员和其他直接责任人员可以处上一年度从本企业事业单位取得收入百分之五十以下的罚款；对造成重大或者特别重大环境污染、生态破坏事故的，报经有批准权的人民政府批准，责令停业、关闭。未按照要求采取治理措施的，指定有治理能力的单位代为治理，所需费用由违法者承担。 对造成一般环境污染、生态破坏事故的，处三十万元以上一百万元以下的罚款；对造成较大环境污染、生态破坏事故的，处一百万元以上二百万元以下的罚款；对造成重大环境污染、生态破坏事故的，处二百万元以上一千万元以下的罚款；对造成特别重大环境污染、生态破坏事故的，处一千万元以上二千万元以下的罚款。 发生环境污染、生态破坏事故，情节特别严重、影响特别恶劣的，负有生态环境保护监督管理职责的部门、机构可以按照前款罚款数额的二倍以上五倍以下对负有责任的企业事业单位或者其他生产经营者处以罚款。 第一千二百三十七条 违反本法规定，因发生事故或者其他突发性事件，造成或者可能造成环境污染、生态破坏事件，有下列情形之一的，由负有生态环境保护监督管理职责的部门、机构按照职责分工责令改正，处以罚款： （一）未及时通报或者报告； （二）未立即采取有效措施或者逃逸； （三）未采取必要应对措施，造成生态灾害危害扩大。 有前款第一项情形的，处五万元以上五十万元以下的罚款，对直接负责的主管人员和其他直接责任人员处一万元以上十万元以下的罚款，并可以暂扣或者吊销相关任职资格许可；有前款第二项、第三项情形之一的，处二十万元以上二百万元以下的罚款。 第一千二百三十八条 违反本法规定，对举报人以解除、变更劳动合同、聘用合同或者以其他方式打击报复的，应当依照有关法律的规定承担责任。 第三章 附 则 第一千二百三十九条 其他法律对生态保护、绿色低碳发展等生态环境保护相关领域有具体或者进一步规定的，适用其规定。 第一千二百四十条 国家根据实际需要，对生态环境监督管理体制作出调整的，依照其规定。 第一千二百四十一条 国务院、中央军事委员会可以依照本法规定的原则制定有关军队生态环境保护工作的具体管理办法。 第一千二百四十二条 本法自2026年8月15日起施行。《中华人民共和国环境保护法》、《中华人民共和国环境影响评价法》、《中华人民共和国海洋环境保护法》、《中华人民共和国大气污染防治法》、《中华人民共和国水污染防治法》、《中华人民共和国土壤污染防治法》、《中华人民共和国固体废物污染环境防治法》、《中华人民共和国噪声污染防治法》、《中华人民共和国放射性污染防治法》、《中华人民共和国清洁生产促进法》同时废止。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第一条", "text": "为了预防、控制和消除职业病危害，防治职业病，保护劳动者健康及其相关权益，促进经济社会发展，根据宪法，制定本法。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二条", "text": "本法适用于中华人民共和国领域内的职业病防治活动。 本法所称职业病，是指企业、事业单位和个体经济组织等用人单位的劳动者在职业活动中，因接触粉尘、放射性物质和其他有毒、有害因素而引起的疾病。 职业病的分类和目录由国务院卫生行政部门会同国务院劳动保障行政部门制定、调整并公布。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第三条", "text": "职业病防治工作坚持预防为主、防治结合的方针，建立用人单位负责、行政机关监管、行业自律、职工参与和社会监督的机制，实行分类管理、综合治理。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第四条", "text": "劳动者依法享有职业卫生保护的权利。 用人单位应当为劳动者创造符合国家职业卫生标准和卫生要求的工作环境和条件，并采取措施保障劳动者获得职业卫生保护。 工会组织依法对职业病防治工作进行监督，维护劳动者的合法权益。用人单位制定或者修改有关职业病防治的规章制度，应当听取工会组织的意见。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第五条", "text": "用人单位应当建立、健全职业病防治责任制，加强对职业病防治的管理，提高职业病防治水平，对本单位产生的职业病危害承担责任。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第六条", "text": "用人单位的主要负责人对本单位的职业病防治工作全面负责。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第七条", "text": "用人单位必须依法参加工伤保险。 国务院和县级以上地方人民政府劳动保障行政部门应当加强对工伤保险的监督管理，确保劳动者依法享受工伤保险待遇。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第八条", "text": "国家鼓励和支持研制、开发、推广、应用有利于职业病防治和保护劳动者健康的新技术、新工艺、新设备、新材料，加强对职业病的机理和发生规律的基础研究，提高职业病防治科学技术水平；积极采用有效的职业病防治技术、工艺、设备、材料；限制使用或者淘汰职业病危害严重的技术、工艺、设备、材料。 国家鼓励和支持职业病医疗康复机构的建设。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第九条", "text": "国家实行职业卫生监督制度。 国务院卫生行政部门、劳动保障行政部门依照本法和国务院确定的职责，负责全国职业病防治的监督管理工作。国务院有关部门在各自的职责范围内负责职业病防治的有关监督管理工作。 县级以上地方人民政府卫生行政部门、劳动保障行政部门依据各自职责，负责本行政区域内职业病防治的监督管理工作。县级以上地方人民政府有关部门在各自的职责范围内负责职业病防治的有关监督管理工作。 县级以上人民政府卫生行政部门、劳动保障行政部门（以下统称职业卫生监督管理部门）应当加强沟通，密切配合，按照各自职责分工，依法行使职权，承担责任。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第十条", "text": "国务院和县级以上地方人民政府应当制定职业病防治规划，将其纳入国民经济和社会发展计划，并组织实施。 县级以上地方人民政府统一负责、领导、组织、协调本行政区域的职业病防治工作，建立健全职业病防治工作体制、机制，统一领导、指挥职业卫生突发事件应对工作；加强职业病防治能力建设和服务体系建设，完善、落实职业病防治工作责任制。 乡、民族乡、镇的人民政府应当认真执行本法，支持职业卫生监督管理部门依法履行职责。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第十一条", "text": "县级以上人民政府职业卫生监督管理部门应当加强对职业病防治的宣传教育，普及职业病防治的知识，增强用人单位的职业病防治观念，提高劳动者的职业健康意识、自我保护意识和行使职业卫生保护权利的能力。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第十二条", "text": "有关防治职业病的国家职业卫生标准，由国务院卫生行政部门组织制定并公布。 国务院卫生行政部门应当组织开展重点职业病监测和专项调查，对职业健康风险进行评估，为制定职业卫生标准和职业病防治政策提供科学依据。 县级以上地方人民政府卫生行政部门应当定期对本行政区域的职业病防治情况进行统计和调查分析。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第十三条", "text": "任何单位和个人有权对违反本法的行为进行检举和控告。有关部门收到相关的检举和控告后，应当及时处理。 对防治职业病成绩显著的单位和个人，给予奖励。 第二章 前期预防"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第十四条", "text": "用人单位应当依照法律、法规要求，严格遵守国家职业卫生标准，落实职业病预防措施，从源头上控制和消除职业病危害。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第十五条", "text": "产生职业病危害的用人单位的设立除应当符合法律、行政法规规定的设立条件外，其工作场所还应当符合下列职业卫生要求： （一）职业病危害因素的强度或者浓度符合国家职业卫生标准； （二）有与职业病危害防护相适应的设施； （三）生产布局合理，符合有害与无害作业分开的原则； （四）有配套的更衣间、洗浴间、孕妇休息间等卫生设施； （五）设备、工具、用具等设施符合保护劳动者生理、心理健康的要求； （六）法律、行政法规和国务院卫生行政部门关于保护劳动者健康的其他要求。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第十六条", "text": "国家建立职业病危害项目申报制度。 用人单位工作场所存在职业病目录所列职业病的危害因素的，应当及时、如实向所在地卫生行政部门申报危害项目，接受监督。 职业病危害因素分类目录由国务院卫生行政部门制定、调整并公布。职业病危害项目申报的具体办法由国务院卫生行政部门制定。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第十七条", "text": "新建、扩建、改建建设项目和技术改造、技术引进项目（以下统称建设项目）可能产生职业病危害的，建设单位在可行性论证阶段应当进行职业病危害预评价。 医疗机构建设项目可能产生放射性职业病危害的，建设单位应当向卫生行政部门提交放射性职业病危害预评价报告。卫生行政部门应当自收到预评价报告之日起三十日内，作出审核决定并书面通知建设单位。未提交预评价报告或者预评价报告未经卫生行政部门审核同意的，不得开工建设。 职业病危害预评价报告应当对建设项目可能产生的职业病危害因素及其对工作场所和劳动者健康的影响作出评价，确定危害类别和职业病防护措施。 建设项目职业病危害分类管理办法由国务院卫生行政部门制定。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第十八条", "text": "建设项目的职业病防护设施所需费用应当纳入建设项目工程预算，并与主体工程同时设计，同时施工，同时投入生产和使用。 建设项目的职业病防护设施设计应当符合国家职业卫生标准和卫生要求；其中，医疗机构放射性职业病危害严重的建设项目的防护设施设计，应当经卫生行政部门审查同意后，方可施工。 建设项目在竣工验收前，建设单位应当进行职业病危害控制效果评价。 医疗机构可能产生放射性职业病危害的建设项目竣工验收时，其放射性职业病防护设施经卫生行政部门验收合格后，方可投入使用；其他建设项目的职业病防护设施应当由建设单位负责依法组织验收，验收合格后，方可投入生产和使用。卫生行政部门应当加强对建设单位组织的验收活动和验收结果的监督核查。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第十九条", "text": "国家对从事放射性、高毒、高危粉尘等作业实行特殊管理。具体管理办法由国务院制定。 第三章 劳动过程中的防护与管理"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二十条", "text": "用人单位应当采取下列职业病防治管理措施： （一）设置或者指定职业卫生管理机构或者组织，配备专职或者兼职的职业卫生管理人员，负责本单位的职业病防治工作； （二）制定职业病防治计划和实施方案； （三）建立、健全职业卫生管理制度和操作规程； （四）建立、健全职业卫生档案和劳动者健康监护档案； （五）建立、健全工作场所职业病危害因素监测及评价制度； （六）建立、健全职业病危害事故应急救援预案。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二十一条", "text": "用人单位应当保障职业病防治所需的资金投入，不得挤占、挪用，并对因资金投入不足导致的后果承担责任。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二十二条", "text": "用人单位必须采用有效的职业病防护设施，并为劳动者提供个人使用的职业病防护用品。 用人单位为劳动者个人提供的职业病防护用品必须符合防治职业病的要求；不符合要求的，不得使用。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二十三条", "text": "用人单位应当优先采用有利于防治职业病和保护劳动者健康的新技术、新工艺、新设备、新材料，逐步替代职业病危害严重的技术、工艺、设备、材料。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二十四条", "text": "产生职业病危害的用人单位，应当在醒目位置设置公告栏，公布有关职业病防治的规章制度、操作规程、职业病危害事故应急救援措施和工作场所职业病危害因素检测结果。 对产生严重职业病危害的作业岗位，应当在其醒目位置，设置警示标识和中文警示说明。警示说明应当载明产生职业病危害的种类、后果、预防以及应急救治措施等内容。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二十五条", "text": "对可能发生急性职业损伤的有毒、有害工作场所，用人单位应当设置报警装置，配置现场急救用品、冲洗设备、应急撤离通道和必要的泄险区。 对放射工作场所和放射性同位素的运输、贮存，用人单位必须配置防护设备和报警装置，保证接触放射线的工作人员佩戴个人剂量计。 对职业病防护设备、应急救援设施和个人使用的职业病防护用品，用人单位应当进行经常性的维护、检修，定期检测其性能和效果，确保其处于正常状态，不得擅自拆除或者停止使用。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二十六条", "text": "用人单位应当实施由专人负责的职业病危害因素日常监测，并确保监测系统处于正常运行状态。 用人单位应当按照国务院卫生行政部门的规定，定期对工作场所进行职业病危害因素检测、评价。检测、评价结果存入用人单位职业卫生档案，定期向所在地卫生行政部门报告并向劳动者公布。 职业病危害因素检测、评价由依法设立的取得国务院卫生行政部门或者设区的市级以上地方人民政府卫生行政部门按照职责分工给予资质认可的职业卫生技术服务机构进行。职业卫生技术服务机构所作检测、评价应当客观、真实。 发现工作场所职业病危害因素不符合国家职业卫生标准和卫生要求时，用人单位应当立即采取相应治理措施，仍然达不到国家职业卫生标准和卫生要求的，必须停止存在职业病危害因素的作业；职业病危害因素经治理后，符合国家职业卫生标准和卫生要求的，方可重新作业。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二十七条", "text": "职业卫生技术服务机构依法从事职业病危害因素检测、评价工作，接受卫生行政部门的监督检查。卫生行政部门应当依法履行监督职责。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二十八条", "text": "向用人单位提供可能产生职业病危害的设备的，应当提供中文说明书，并在设备的醒目位置设置警示标识和中文警示说明。警示说明应当载明设备性能、可能产生的职业病危害、安全操作和维护注意事项、职业病防护以及应急救治措施等内容。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二十九条", "text": "向用人单位提供可能产生职业病危害的化学品、放射性同位素和含有放射性物质的材料的，应当提供中文说明书。说明书应当载明产品特性、主要成份、存在的有害因素、可能产生的危害后果、安全使用注意事项、职业病防护以及应急救治措施等内容。产品包装应当有醒目的警示标识和中文警示说明。贮存上述材料的场所应当在规定的部位设置危险物品标识或者放射性警示标识。 国内首次使用或者首次进口与职业病危害有关的化学材料，使用单位或者进口单位按照国家规定经国务院有关部门批准后，应当向国务院卫生行政部门报送该化学材料的毒性鉴定以及经有关部门登记注册或者批准进口的文件等资料。 进口放射性同位素、射线装置和含有放射性物质的物品的，按照国家有关规定办理。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第三十条", "text": "任何单位和个人不得生产、经营、进口和使用国家明令禁止使用的可能产生职业病危害的设备或者材料。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第三十一条", "text": "任何单位和个人不得将产生职业病危害的作业转移给不具备职业病防护条件的单位和个人。不具备职业病防护条件的单位和个人不得接受产生职业病危害的作业。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第三十二条", "text": "用人单位对采用的技术、工艺、设备、材料，应当知悉其产生的职业病危害，对有职业病危害的技术、工艺、设备、材料隐瞒其危害而采用的，对所造成的职业病危害后果承担责任。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第三十三条", "text": "用人单位与劳动者订立劳动合同（含聘用合同，下同）时，应当将工作过程中可能产生的职业病危害及其后果、职业病防护措施和待遇等如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗。 劳动者在已订立劳动合同期间因工作岗位或者工作内容变更，从事与所订立劳动合同中未告知的存在职业病危害的作业时，用人单位应当依照前款规定，向劳动者履行如实告知的义务，并协商变更原劳动合同相关条款。 用人单位违反前两款规定的，劳动者有权拒绝从事存在职业病危害的作业，用人单位不得因此解除与劳动者所订立的劳动合同。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第三十四条", "text": "用人单位的主要负责人和职业卫生管理人员应当接受职业卫生培训，遵守职业病防治法律、法规，依法组织本单位的职业病防治工作。 用人单位应当对劳动者进行上岗前的职业卫生培训和在岗期间的定期职业卫生培训，普及职业卫生知识，督促劳动者遵守职业病防治法律、法规、规章和操作规程，指导劳动者正确使用职业病防护设备和个人使用的职业病防护用品。 劳动者应当学习和掌握相关的职业卫生知识，增强职业病防范意识，遵守职业病防治法律、法规、规章和操作规程，正确使用、维护职业病防护设备和个人使用的职业病防护用品，发现职业病危害事故隐患应当及时报告。 劳动者不履行前款规定义务的，用人单位应当对其进行教育。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第三十五条", "text": "对从事接触职业病危害的作业的劳动者，用人单位应当按照国务院卫生行政部门的规定组织上岗前、在岗期间和离岗时的职业健康检查，并将检查结果书面告知劳动者。职业健康检查费用由用人单位承担。 用人单位不得安排未经上岗前职业健康检查的劳动者从事接触职业病危害的作业；不得安排有职业禁忌的劳动者从事其所禁忌的作业；对在职业健康检查中发现有与所从事的职业相关的健康损害的劳动者，应当调离原工作岗位，并妥善安置；对未进行离岗前职业健康检查的劳动者不得解除或者终止与其订立的劳动合同。 职业健康检查应当由取得《医疗机构执业许可证》的医疗卫生机构承担。卫生行政部门应当加强对职业健康检查工作的规范管理，具体管理办法由国务院卫生行政部门制定。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第三十六条", "text": "用人单位应当为劳动者建立职业健康监护档案，并按照规定的期限妥善保存。 职业健康监护档案应当包括劳动者的职业史、职业病危害接触史、职业健康检查结果和职业病诊疗等有关个人健康资料。 劳动者离开用人单位时，有权索取本人职业健康监护档案复印件，用人单位应当如实、无偿提供，并在所提供的复印件上签章。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第三十七条", "text": "发生或者可能发生急性职业病危害事故时，用人单位应当立即采取应急救援和控制措施，并及时报告所在地卫生行政部门和有关部门。卫生行政部门接到报告后，应当及时会同有关部门组织调查处理；必要时，可以采取临时控制措施。卫生行政部门应当组织做好医疗救治工作。 对遭受或者可能遭受急性职业病危害的劳动者，用人单位应当及时组织救治、进行健康检查和医学观察，所需费用由用人单位承担。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第三十八条", "text": "用人单位不得安排未成年工从事接触职业病危害的作业；不得安排孕期、哺乳期的女职工从事对本人和胎儿、婴儿有危害的作业。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第三十九条", "text": "劳动者享有下列职业卫生保护权利： （一）获得职业卫生教育、培训； （二）获得职业健康检查、职业病诊疗、康复等职业病防治服务； （三）了解工作场所产生或者可能产生的职业病危害因素、危害后果和应当采取的职业病防护措施； （四）要求用人单位提供符合防治职业病要求的职业病防护设施和个人使用的职业病防护用品，改善工作条件； （五）对违反职业病防治法律、法规以及危及生命健康的行为提出批评、检举和控告； （六）拒绝违章指挥和强令进行没有职业病防护措施的作业； （七）参与用人单位职业卫生工作的民主管理，对职业病防治工作提出意见和建议。 用人单位应当保障劳动者行使前款所列权利。因劳动者依法行使正当权利而降低其工资、福利等待遇或者解除、终止与其订立的劳动合同的，其行为无效。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第四十条", "text": "工会组织应当督促并协助用人单位开展职业卫生宣传教育和培训，有权对用人单位的职业病防治工作提出意见和建议，依法代表劳动者与用人单位签订劳动安全卫生专项集体合同，与用人单位就劳动者反映的有关职业病防治的问题进行协调并督促解决。 工会组织对用人单位违反职业病防治法律、法规，侵犯劳动者合法权益的行为，有权要求纠正；产生严重职业病危害时，有权要求采取防护措施，或者向政府有关部门建议采取强制性措施；发生职业病危害事故时，有权参与事故调查处理；发现危及劳动者生命健康的情形时，有权向用人单位建议组织劳动者撤离危险现场，用人单位应当立即作出处理。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第四十一条", "text": "用人单位按照职业病防治要求，用于预防和治理职业病危害、工作场所卫生检测、健康监护和职业卫生培训等费用，按照国家有关规定，在生产成本中据实列支。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第四十二条", "text": "职业卫生监督管理部门应当按照职责分工，加强对用人单位落实职业病防护管理措施情况的监督检查，依法行使职权，承担责任。 第四章 职业病诊断与职业病病人保障"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第四十三条", "text": "职业病诊断应当由取得《医疗机构执业许可证》的医疗卫生机构承担。卫生行政部门应当加强对职业病诊断工作的规范管理，具体管理办法由国务院卫生行政部门制定。 承担职业病诊断的医疗卫生机构还应当具备下列条件： （一）具有与开展职业病诊断相适应的医疗卫生技术人员； （二）具有与开展职业病诊断相适应的仪器、设备； （三）具有健全的职业病诊断质量管理制度。 承担职业病诊断的医疗卫生机构不得拒绝劳动者进行职业病诊断的要求。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第四十四条", "text": "劳动者可以在用人单位所在地、本人户籍所在地或者经常居住地依法承担职业病诊断的医疗卫生机构进行职业病诊断。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第四十五条", "text": "职业病诊断标准和职业病诊断、鉴定办法由国务院卫生行政部门制定。职业病伤残等级的鉴定办法由国务院劳动保障行政部门会同国务院卫生行政部门制定。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第四十六条", "text": "职业病诊断，应当综合分析下列因素： （一）病人的职业史； （二）职业病危害接触史和工作场所职业病危害因素情况； （三）临床表现以及辅助检查结果等。 没有证据否定职业病危害因素与病人临床表现之间的必然联系的，应当诊断为职业病。 职业病诊断证明书应当由参与诊断的取得职业病诊断资格的执业医师签署，并经承担职业病诊断的医疗卫生机构审核盖章。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第四十七条", "text": "用人单位应当如实提供职业病诊断、鉴定所需的劳动者职业史和职业病危害接触史、工作场所职业病危害因素检测结果等资料；卫生行政部门应当监督检查和督促用人单位提供上述资料；劳动者和有关机构也应当提供与职业病诊断、鉴定有关的资料。 职业病诊断、鉴定机构需要了解工作场所职业病危害因素情况时，可以对工作场所进行现场调查，也可以向卫生行政部门提出，卫生行政部门应当在十日内组织现场调查。用人单位不得拒绝、阻挠。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第四十八条", "text": "职业病诊断、鉴定过程中，用人单位不提供工作场所职业病危害因素检测结果等资料的，诊断、鉴定机构应当结合劳动者的临床表现、辅助检查结果和劳动者的职业史、职业病危害接触史，并参考劳动者的自述、卫生行政部门提供的日常监督检查信息等，作出职业病诊断、鉴定结论。 劳动者对用人单位提供的工作场所职业病危害因素检测结果等资料有异议，或者因劳动者的用人单位解散、破产，无用人单位提供上述资料的，诊断、鉴定机构应当提请卫生行政部门进行调查，卫生行政部门应当自接到申请之日起三十日内对存在异议的资料或者工作场所职业病危害因素情况作出判定；有关部门应当配合。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第四十九条", "text": "职业病诊断、鉴定过程中，在确认劳动者职业史、职业病危害接触史时，当事人对劳动关系、工种、工作岗位或者在岗时间有争议的，可以向当地的劳动人事争议仲裁委员会申请仲裁；接到申请的劳动人事争议仲裁委员会应当受理，并在三十日内作出裁决。 当事人在仲裁过程中对自己提出的主张，有责任提供证据。劳动者无法提供由用人单位掌握管理的与仲裁主张有关的证据的，仲裁庭应当要求用人单位在指定期限内提供；用人单位在指定期限内不提供的，应当承担不利后果。 劳动者对仲裁裁决不服的，可以依法向人民法院提起诉讼。 用人单位对仲裁裁决不服的，可以在职业病诊断、鉴定程序结束之日起十五日内依法向人民法院提起诉讼；诉讼期间，劳动者的治疗费用按照职业病待遇规定的途径支付。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第五十条", "text": "用人单位和医疗卫生机构发现职业病病人或者疑似职业病病人时，应当及时向所在地卫生行政部门报告。确诊为职业病的，用人单位还应当向所在地劳动保障行政部门报告。接到报告的部门应当依法作出处理。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第五十一条", "text": "县级以上地方人民政府卫生行政部门负责本行政区域内的职业病统计报告的管理工作，并按照规定上报。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第五十二条", "text": "当事人对职业病诊断有异议的，可以向作出诊断的医疗卫生机构所在地地方人民政府卫生行政部门申请鉴定。 职业病诊断争议由设区的市级以上地方人民政府卫生行政部门根据当事人的申请，组织职业病诊断鉴定委员会进行鉴定。 当事人对设区的市级职业病诊断鉴定委员会的鉴定结论不服的，可以向省、自治区、直辖市人民政府卫生行政部门申请再鉴定。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第五十三条", "text": "职业病诊断鉴定委员会由相关专业的专家组成。 省、自治区、直辖市人民政府卫生行政部门应当设立相关的专家库，需要对职业病争议作出诊断鉴定时，由当事人或者当事人委托有关卫生行政部门从专家库中以随机抽取的方式确定参加诊断鉴定委员会的专家。 职业病诊断鉴定委员会应当按照国务院卫生行政部门颁布的职业病诊断标准和职业病诊断、鉴定办法进行职业病诊断鉴定，向当事人出具职业病诊断鉴定书。职业病诊断、鉴定费用由用人单位承担。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第五十四条", "text": "职业病诊断鉴定委员会组成人员应当遵守职业道德，客观、公正地进行诊断鉴定，并承担相应的责任。职业病诊断鉴定委员会组成人员不得私下接触当事人，不得收受当事人的财物或者其他好处，与当事人有利害关系的，应当回避。 人民法院受理有关案件需要进行职业病鉴定时，应当从省、自治区、直辖市人民政府卫生行政部门依法设立的相关的专家库中选取参加鉴定的专家。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第五十五条", "text": "医疗卫生机构发现疑似职业病病人时，应当告知劳动者本人并及时通知用人单位。 用人单位应当及时安排对疑似职业病病人进行诊断；在疑似职业病病人诊断或者医学观察期间，不得解除或者终止与其订立的劳动合同。 疑似职业病病人在诊断、医学观察期间的费用，由用人单位承担。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第五十六条", "text": "用人单位应当保障职业病病人依法享受国家规定的职业病待遇。 用人单位应当按照国家有关规定，安排职业病病人进行治疗、康复和定期检查。 用人单位对不适宜继续从事原工作的职业病病人，应当调离原岗位，并妥善安置。 用人单位对从事接触职业病危害的作业的劳动者，应当给予适当岗位津贴。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第五十七条", "text": "职业病病人的诊疗、康复费用，伤残以及丧失劳动能力的职业病病人的社会保障，按照国家有关工伤保险的规定执行。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第五十八条", "text": "职业病病人除依法享有工伤保险外，依照有关民事法律，尚有获得赔偿的权利的，有权向用人单位提出赔偿要求。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第五十九条", "text": "劳动者被诊断患有职业病，但用人单位没有依法参加工伤保险的，其医疗和生活保障由该用人单位承担。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第六十条", "text": "职业病病人变动工作单位，其依法享有的待遇不变。 用人单位在发生分立、合并、解散、破产等情形时，应当对从事接触职业病危害的作业的劳动者进行健康检查，并按照国家有关规定妥善安置职业病病人。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第六十一条", "text": "用人单位已经不存在或者无法确认劳动关系的职业病病人，可以向地方人民政府医疗保障、民政部门申请医疗救助和生活等方面的救助。 地方各级人民政府应当根据本地区的实际情况，采取其他措施，使前款规定的职业病病人获得医疗救治。 第五章 监督检查"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第六十二条", "text": "县级以上人民政府职业卫生监督管理部门依照职业病防治法律、法规、国家职业卫生标准和卫生要求，依据职责划分，对职业病防治工作进行监督检查。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第六十三条", "text": "卫生行政部门履行监督检查职责时，有权采取下列措施： （一）进入被检查单位和职业病危害现场，了解情况，调查取证； （二）查阅或者复制与违反职业病防治法律、法规的行为有关的资料和采集样品； （三）责令违反职业病防治法律、法规的单位和个人停止违法行为。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第六十四条", "text": "发生职业病危害事故或者有证据证明危害状态可能导致职业病危害事故发生时，卫生行政部门可以采取下列临时控制措施： （一）责令暂停导致职业病危害事故的作业； （二）封存造成职业病危害事故或者可能导致职业病危害事故发生的材料和设备； （三）组织控制职业病危害事故现场。 在职业病危害事故或者危害状态得到有效控制后，卫生行政部门应当及时解除控制措施。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第六十五条", "text": "职业卫生监督执法人员依法执行职务时，应当出示监督执法证件。 职业卫生监督执法人员应当忠于职守，秉公执法，严格遵守执法规范；涉及用人单位的秘密的，应当为其保密。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第六十六条", "text": "职业卫生监督执法人员依法执行职务时，被检查单位应当接受检查并予以支持配合，不得拒绝和阻碍。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第六十七条", "text": "卫生行政部门及其职业卫生监督执法人员履行职责时，不得有下列行为： （一）对不符合法定条件的，发给建设项目有关证明文件、资质证明文件或者予以批准； （二）对已经取得有关证明文件的，不履行监督检查职责； （三）发现用人单位存在职业病危害的，可能造成职业病危害事故，不及时依法采取控制措施； （四）其他违反本法的行为。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第六十八条", "text": "职业卫生监督执法人员应当依法经过资格认定。 职业卫生监督管理部门应当加强队伍建设，提高职业卫生监督执法人员的政治、业务素质，依照本法和其他有关法律、法规的规定，建立、健全内部监督制度，对其工作人员执行法律、法规和遵守纪律的情况，进行监督检查。 第六章 法律责任"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第六十九条", "text": "建设单位违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正；逾期不改正的，处十万元以上五十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令停建、关闭： （一）未按照规定进行职业病危害预评价的； （二）医疗机构可能产生放射性职业病危害的建设项目未按照规定提交放射性职业病危害预评价报告，或者放射性职业病危害预评价报告未经卫生行政部门审核同意，开工建设的； （三）建设项目的职业病防护设施未按照规定与主体工程同时设计、同时施工、同时投入生产和使用的； （四）建设项目的职业病防护设施设计不符合国家职业卫生标准和卫生要求，或者医疗机构放射性职业病危害严重的建设项目的防护设施设计未经卫生行政部门审查同意擅自施工的； （五）未按照规定对职业病防护设施进行职业病危害控制效果评价的； （六）建设项目竣工投入生产和使用前，职业病防护设施未按照规定验收合格的。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第七十条", "text": "违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正；逾期不改正的，处十万元以下的罚款： （一）工作场所职业病危害因素检测、评价结果没有存档、上报、公布的； （二）未采取本法"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二十条", "text": "规定的职业病防治管理措施的； （三）未按照规定公布有关职业病防治的规章制度、操作规程、职业病危害事故应急救援措施的； （四）未按照规定组织劳动者进行职业卫生培训，或者未对劳动者个人职业病防护采取指导、督促措施的； （五）国内首次使用或者首次进口与职业病危害有关的化学材料，未按照规定报送毒性鉴定资料以及经有关部门登记注册或者批准进口的文件的。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第七十一条", "text": "用人单位违反本法规定，有下列行为之一的，由卫生行政部门责令限期改正，给予警告，可以并处五万元以上十万元以下的罚款： （一）未按照规定及时、如实向卫生行政部门申报产生职业病危害的项目的； （二）未实施由专人负责的职业病危害因素日常监测，或者监测系统不能正常监测的； （三）订立或者变更劳动合同时，未告知劳动者职业病危害真实情况的； （四）未按照规定组织职业健康检查、建立职业健康监护档案或者未将检查结果书面告知劳动者的； （五）未依照本法规定在劳动者离开用人单位时提供职业健康监护档案复印件的。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第七十二条", "text": "用人单位违反本法规定，有下列行为之一的，由卫生行政部门给予警告，责令限期改正，逾期不改正的，处五万元以上二十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭： （一）工作场所职业病危害因素的强度或者浓度超过国家职业卫生标准的； （二）未提供职业病防护设施和个人使用的职业病防护用品，或者提供的职业病防护设施和个人使用的职业病防护用品不符合国家职业卫生标准和卫生要求的； （三）对职业病防护设备、应急救援设施和个人使用的职业病防护用品未按照规定进行维护、检修、检测，或者不能保持正常运行、使用状态的； （四）未按照规定对工作场所职业病危害因素进行检测、评价的； （五）工作场所职业病危害因素经治理仍然达不到国家职业卫生标准和卫生要求时，未停止存在职业病危害因素的作业的； （六）未按照规定安排职业病病人、疑似职业病病人进行诊治的； （七）发生或者可能发生急性职业病危害事故时，未立即采取应急救援和控制措施或者未按照规定及时报告的； （八）未按照规定在产生严重职业病危害的作业岗位醒目位置设置警示标识和中文警示说明的； （九）拒绝职业卫生监督管理部门监督检查的； （十）隐瞒、伪造、篡改、毁损职业健康监护档案、工作场所职业病危害因素检测评价结果等相关资料，或者拒不提供职业病诊断、鉴定所需资料的； （十一）未按照规定承担职业病诊断、鉴定费用和职业病病人的医疗、生活保障费用的。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第七十三条", "text": "向用人单位提供可能产生职业病危害的设备、材料，未按照规定提供中文说明书或者设置警示标识和中文警示说明的，由卫生行政部门责令限期改正，给予警告，并处五万元以上二十万元以下的罚款。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第七十四条", "text": "用人单位和医疗卫生机构未按照规定报告职业病、疑似职业病的，由有关主管部门依据职责分工责令限期改正，给予警告，可以并处一万元以下的罚款；弄虚作假的，并处二万元以上五万元以下的罚款；对直接负责的主管人员和其他直接责任人员，可以依法给予降级或者撤职的处分。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第七十五条", "text": "违反本法规定，有下列情形之一的，由卫生行政部门责令限期治理，并处五万元以上三十万元以下的罚款；情节严重的，责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭： （一）隐瞒技术、工艺、设备、材料所产生的职业病危害而采用的； （二）隐瞒本单位职业卫生真实情况的； （三）可能发生急性职业损伤的有毒、有害工作场所、放射工作场所或者放射性同位素的运输、贮存不符合本法"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二十五条", "text": "规定的； （四）使用国家明令禁止使用的可能产生职业病危害的设备或者材料的； （五）将产生职业病危害的作业转移给没有职业病防护条件的单位和个人，或者没有职业病防护条件的单位和个人接受产生职业病危害的作业的； （六）擅自拆除、停止使用职业病防护设备或者应急救援设施的； （七）安排未经职业健康检查的劳动者、有职业禁忌的劳动者、未成年工或者孕期、哺乳期女职工从事接触职业病危害的作业或者禁忌作业的； （八）违章指挥和强令劳动者进行没有职业病防护措施的作业的。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第七十六条", "text": "生产、经营或者进口国家明令禁止使用的可能产生职业病危害的设备或者材料的，依照有关法律、行政法规的规定给予处罚。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第七十七条", "text": "用人单位违反本法规定，已经对劳动者生命健康造成严重损害的，由卫生行政部门责令停止产生职业病危害的作业，或者提请有关人民政府按照国务院规定的权限责令关闭，并处十万元以上五十万元以下的罚款。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第七十八条", "text": "用人单位违反本法规定，造成重大职业病危害事故或者其他严重后果，构成犯罪的，对直接负责的主管人员和其他直接责任人员，依法追究刑事责任。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第七十九条", "text": "未取得职业卫生技术服务资质认可擅自从事职业卫生技术服务的，由卫生行政部门责令立即停止违法行为，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上十倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上五万元以下的罚款；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职或者开除的处分。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第八十条", "text": "从事职业卫生技术服务的机构和承担职业病诊断的医疗卫生机构违反本法规定，有下列行为之一的，由卫生行政部门责令立即停止违法行为，给予警告，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上二万元以下的罚款；情节严重的，由原认可或者登记机关取消其相应的资格；对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职或者开除的处分；构成犯罪的，依法追究刑事责任： （一）超出资质认可或者诊疗项目登记范围从事职业卫生技术服务或者职业病诊断的； （二）不按照本法规定履行法定职责的； （三）出具虚假证明文件的。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第八十一条", "text": "职业病诊断鉴定委员会组成人员收受职业病诊断争议当事人的财物或者其他好处的，给予警告，没收收受的财物，可以并处三千元以上五万元以下的罚款，取消其担任职业病诊断鉴定委员会组成人员的资格，并从省、自治区、直辖市人民政府卫生行政部门设立的专家库中予以除名。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第八十二条", "text": "卫生行政部门不按照规定报告职业病和职业病危害事故的，由上一级行政部门责令改正，通报批评，给予警告；虚报、瞒报的，对单位负责人、直接负责的主管人员和其他直接责任人员依法给予降级、撤职或者开除的处分。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第八十三条", "text": "县级以上地方人民政府在职业病防治工作中未依照本法履行职责，本行政区域出现重大职业病危害事故、造成严重社会影响的，依法对直接负责的主管人员和其他直接责任人员给予记大过直至开除的处分。 县级以上人民政府职业卫生监督管理部门不履行本法规定的职责，滥用职权、玩忽职守、徇私舞弊，依法对直接负责的主管人员和其他直接责任人员给予记大过或者降级的处分；造成职业病危害事故或者其他严重后果的，依法给予撤职或者开除的处分。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第八十四条", "text": "违反本法规定，构成犯罪的，依法追究刑事责任。 第七章 附 则"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第八十五条", "text": "本法下列用语的含义： 职业病危害，是指对从事职业活动的劳动者可能导致职业病的各种危害。职业病危害因素包括：职业活动中存在的各种有害的化学、物理、生物因素以及在作业过程中产生的其他职业有害因素。 职业禁忌，是指劳动者从事特定职业或者接触特定职业病危害因素时，比一般职业人群更易于遭受职业病危害和罹患职业病或者可能导致原有自身疾病病情加重，或者在从事作业过程中诱发可能导致对他人生命健康构成危险的疾病的个人特殊生理或者病理状态。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第二条", "text": "规定的用人单位以外的单位，产生职业病危害的，其职业病防治活动可以参照本法执行。 劳务派遣用工单位应当履行本法规定的用人单位的义务。 中国人民解放军参照执行本法的办法，由国务院、中央军事委员会制定。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第八十七条", "text": "对医疗机构放射性职业病危害控制的监督管理，由卫生行政部门依照本法的规定实施。"}, {"law": "中华人民共和国职业病防治法_20181229.docx", "no": "第八十八条", "text": "本法自2002年5月1日起施行。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第一条", "text": "为了推动全社会节约能源，提高能源利用效率，保护和改善环境，促进经济社会全面协调可持续发展，制定本法。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第二条", "text": "本法所称能源，是指煤炭、石油、天然气、生物质能和电力、热力以及其他直接或者通过加工、转换而取得有用能的各种资源。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第三条", "text": "本法所称节约能源（以下简称节能），是指加强用能管理，采取技术上可行、经济上合理以及环境和社会可以承受的措施，从能源生产到消费的各个环节，降低消耗、减少损失和污染物排放、制止浪费，有效、合理地利用能源。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第四条", "text": "节约资源是我国的基本国策。国家实施节约与开发并举、把节约放在首位的能源发展战略。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五条", "text": "国务院和县级以上地方各级人民政府应当将节能工作纳入国民经济和社会发展规划、年度计划，并组织编制和实施节能中长期专项规划、年度节能计划。 国务院和县级以上地方各级人民政府每年向本级人民代表大会或者其常务委员会报告节能工作。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第六条", "text": "国家实行节能目标责任制和节能考核评价制度，将节能目标完成情况作为对地方人民政府及其负责人考核评价的内容。 省、自治区、直辖市人民政府每年向国务院报告节能目标责任的履行情况。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第七条", "text": "国家实行有利于节能和环境保护的产业政策，限制发展高耗能、高污染行业，发展节能环保型产业。 国务院和省、自治区、直辖市人民政府应当加强节能工作，合理调整产业结构、企业结构、产品结构和能源消费结构，推动企业降低单位产值能耗和单位产品能耗，淘汰落后的生产能力，改进能源的开发、加工、转换、输送、储存和供应，提高能源利用效率。 国家鼓励、支持开发和利用新能源、可再生能源。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第八条", "text": "国家鼓励、支持节能科学技术的研究、开发、示范和推广，促进节能技术创新与进步。 国家开展节能宣传和教育，将节能知识纳入国民教育和培训体系，普及节能科学知识，增强全民的节能意识，提倡节约型的消费方式。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第九条", "text": "任何单位和个人都应当依法履行节能义务，有权检举浪费能源的行为。 新闻媒体应当宣传节能法律、法规和政策，发挥舆论监督作用。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第十条", "text": "国务院管理节能工作的部门主管全国的节能监督管理工作。国务院有关部门在各自的职责范围内负责节能监督管理工作，并接受国务院管理节能工作的部门的指导。 县级以上地方各级人民政府管理节能工作的部门负责本行政区域内的节能监督管理工作。县级以上地方各级人民政府有关部门在各自的职责范围内负责节能监督管理工作，并接受同级管理节能工作的部门的指导。 第二章 节能管理"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第十一条", "text": "国务院和县级以上地方各级人民政府应当加强对节能工作的领导，部署、协调、监督、检查、推动节能工作。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第十二条", "text": "县级以上人民政府管理节能工作的部门和有关部门应当在各自的职责范围内，加强对节能法律、法规和节能标准执行情况的监督检查，依法查处违法用能行为。 履行节能监督管理职责不得向监督管理对象收取费用。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第十三条", "text": "国务院标准化主管部门和国务院有关部门依法组织制定并适时修订有关节能的国家标准、行业标准，建立健全节能标准体系。 国务院标准化主管部门会同国务院管理节能工作的部门和国务院有关部门制定强制性的用能产品、设备能源效率标准和生产过程中耗能高的产品的单位产品能耗限额标准。 国家鼓励企业制定严于国家标准、行业标准的企业节能标准。 省、自治区、直辖市制定严于强制性国家标准、行业标准的地方节能标准，由省、自治区、直辖市人民政府报经国务院批准；本法另有规定的除外。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第十四条", "text": "建筑节能的国家标准、行业标准由国务院建设主管部门组织制定，并依照法定程序发布。 省、自治区、直辖市人民政府建设主管部门可以根据本地实际情况，制定严于国家标准或者行业标准的地方建筑节能标准，并报国务院标准化主管部门和国务院建设主管部门备案。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第十五条", "text": "国家实行固定资产投资项目节能评估和审查制度。不符合强制性节能标准的项目，建设单位不得开工建设；已经建成的，不得投入生产、使用。政府投资项目不符合强制性节能标准的，依法负责项目审批的机关不得批准建设。具体办法由国务院管理节能工作的部门会同国务院有关部门制定。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第十六条", "text": "国家对落后的耗能过高的用能产品、设备和生产工艺实行淘汰制度。淘汰的用能产品、设备、生产工艺的目录和实施办法，由国务院管理节能工作的部门会同国务院有关部门制定并公布。 生产过程中耗能高的产品的生产单位，应当执行单位产品能耗限额标准。对超过单位产品能耗限额标准用能的生产单位，由管理节能工作的部门按照国务院规定的权限责令限期治理。 对高耗能的特种设备，按照国务院的规定实行节能审查和监管。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第十七条", "text": "禁止生产、进口、销售国家明令淘汰或者不符合强制性能源效率标准的用能产品、设备；禁止使用国家明令淘汰的用能设备、生产工艺。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第十八条", "text": "国家对家用电器等使用面广、耗能量大的用能产品，实行能源效率标识管理。实行能源效率标识管理的产品目录和实施办法，由国务院管理节能工作的部门会同国务院市场监督管理部门制定并公布。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第十九条", "text": "生产者和进口商应当对列入国家能源效率标识管理产品目录的用能产品标注能源效率标识，在产品包装物上或者说明书中予以说明，并按照规定报国务院市场监督管理部门和国务院管理节能工作的部门共同授权的机构备案。 生产者和进口商应当对其标注的能源效率标识及相关信息的准确性负责。禁止销售应当标注而未标注能源效率标识的产品。 禁止伪造、冒用能源效率标识或者利用能源效率标识进行虚假宣传。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第二十条", "text": "用能产品的生产者、销售者，可以根据自愿原则，按照国家有关节能产品认证的规定，向经国务院认证认可监督管理部门认可的从事节能产品认证的机构提出节能产品认证申请；经认证合格后，取得节能产品认证证书，可以在用能产品或者其包装物上使用节能产品认证标志。 禁止使用伪造的节能产品认证标志或者冒用节能产品认证标志。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第二十一条", "text": "县级以上各级人民政府统计部门应当会同同级有关部门，建立健全能源统计制度，完善能源统计指标体系，改进和规范能源统计方法，确保能源统计数据真实、完整。 国务院统计部门会同国务院管理节能工作的部门，定期向社会公布各省、自治区、直辖市以及主要耗能行业的能源消费和节能情况等信息。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第二十二条", "text": "国家鼓励节能服务机构的发展，支持节能服务机构开展节能咨询、设计、评估、检测、审计、认证等服务。 国家支持节能服务机构开展节能知识宣传和节能技术培训，提供节能信息、节能示范和其他公益性节能服务。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第二十三条", "text": "国家鼓励行业协会在行业节能规划、节能标准的制定和实施、节能技术推广、能源消费统计、节能宣传培训和信息咨询等方面发挥作用。 第三章 合理使用与节约能源 第一节 一般规定"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第二十四条", "text": "用能单位应当按照合理用能的原则，加强节能管理，制定并实施节能计划和节能技术措施，降低能源消耗。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第二十五条", "text": "用能单位应当建立节能目标责任制，对节能工作取得成绩的集体、个人给予奖励。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第二十六条", "text": "用能单位应当定期开展节能教育和岗位节能培训。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第二十七条", "text": "用能单位应当加强能源计量管理，按照规定配备和使用经依法检定合格的能源计量器具。 用能单位应当建立能源消费统计和能源利用状况分析制度，对各类能源的消费实行分类计量和统计，并确保能源消费统计数据真实、完整。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第二十八条", "text": "能源生产经营单位不得向本单位职工无偿提供能源。任何单位不得对能源消费实行包费制。 第二节 工业节能"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第二十九条", "text": "国务院和省、自治区、直辖市人民政府推进能源资源优化开发利用和合理配置，推进有利于节能的行业结构调整，优化用能结构和企业布局。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第三十条", "text": "国务院管理节能工作的部门会同国务院有关部门制定电力、钢铁、有色金属、建材、石油加工、化工、煤炭等主要耗能行业的节能技术政策，推动企业节能技术改造。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第三十一条", "text": "国家鼓励工业企业采用高效、节能的电动机、锅炉、窑炉、风机、泵类等设备，采用热电联产、余热余压利用、洁净煤以及先进的用能监测和控制等技术。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第三十二条", "text": "电网企业应当按照国务院有关部门制定的节能发电调度管理的规定，安排清洁、高效和符合规定的热电联产、利用余热余压发电的机组以及其他符合资源综合利用规定的发电机组与电网并网运行，上网电价执行国家有关规定。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第三十三条", "text": "禁止新建不符合国家规定的燃煤发电机组、燃油发电机组和燃煤热电机组。 第三节 建筑节能"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第三十四条", "text": "国务院建设主管部门负责全国建筑节能的监督管理工作。 县级以上地方各级人民政府建设主管部门负责本行政区域内建筑节能的监督管理工作。 县级以上地方各级人民政府建设主管部门会同同级管理节能工作的部门编制本行政区域内的建筑节能规划。建筑节能规划应当包括既有建筑节能改造计划。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第三十五条", "text": "建筑工程的建设、设计、施工和监理单位应当遵守建筑节能标准。 不符合建筑节能标准的建筑工程，建设主管部门不得批准开工建设；已经开工建设的，应当责令停止施工、限期改正；已经建成的，不得销售或者使用。 建设主管部门应当加强对在建建筑工程执行建筑节能标准情况的监督检查。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第三十六条", "text": "房地产开发企业在销售房屋时，应当向购买人明示所售房屋的节能措施、保温工程保修期等信息，在房屋买卖合同、质量保证书和使用说明书中载明，并对其真实性、准确性负责。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第三十七条", "text": "使用空调采暖、制冷的公共建筑应当实行室内温度控制制度。具体办法由国务院建设主管部门制定。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第三十八条", "text": "国家采取措施，对实行集中供热的建筑分步骤实行供热分户计量、按照用热量收费的制度。新建建筑或者对既有建筑进行节能改造，应当按照规定安装用热计量装置、室内温度调控装置和供热系统调控装置。具体办法由国务院建设主管部门会同国务院有关部门制定。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第三十九条", "text": "县级以上地方各级人民政府有关部门应当加强城市节约用电管理，严格控制公用设施和大型建筑物装饰性景观照明的能耗。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第四十条", "text": "国家鼓励在新建建筑和既有建筑节能改造中使用新型墙体材料等节能建筑材料和节能设备，安装和使用太阳能等可再生能源利用系统。 第四节 交通运输节能"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第四十一条", "text": "国务院有关交通运输主管部门按照各自的职责负责全国交通运输相关领域的节能监督管理工作。 国务院有关交通运输主管部门会同国务院管理节能工作的部门分别制定相关领域的节能规划。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第四十二条", "text": "国务院及其有关部门指导、促进各种交通运输方式协调发展和有效衔接，优化交通运输结构，建设节能型综合交通运输体系。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第四十三条", "text": "县级以上地方各级人民政府应当优先发展公共交通，加大对公共交通的投入，完善公共交通服务体系，鼓励利用公共交通工具出行；鼓励使用非机动交通工具出行。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第四十四条", "text": "国务院有关交通运输主管部门应当加强交通运输组织管理，引导道路、水路、航空运输企业提高运输组织化程度和集约化水平，提高能源利用效率。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第四十五条", "text": "国家鼓励开发、生产、使用节能环保型汽车、摩托车、铁路机车车辆、船舶和其他交通运输工具，实行老旧交通运输工具的报废、更新制度。 国家鼓励开发和推广应用交通运输工具使用的清洁燃料、石油替代燃料。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第四十六条", "text": "国务院有关部门制定交通运输营运车船的燃料消耗量限值标准；不符合标准的，不得用于营运。 国务院有关交通运输主管部门应当加强对交通运输营运车船燃料消耗检测的监督管理。 第五节 公共机构节能"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第四十七条", "text": "公共机构应当厉行节约，杜绝浪费，带头使用节能产品、设备，提高能源利用效率。 本法所称公共机构，是指全部或者部分使用财政性资金的国家机关、事业单位和团体组织。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第四十八条", "text": "国务院和县级以上地方各级人民政府管理机关事务工作的机构会同同级有关部门制定和组织实施本级公共机构节能规划。公共机构节能规划应当包括公共机构既有建筑节能改造计划。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第四十九条", "text": "公共机构应当制定年度节能目标和实施方案，加强能源消费计量和监测管理，向本级人民政府管理机关事务工作的机构报送上年度的能源消费状况报告。 国务院和县级以上地方各级人民政府管理机关事务工作的机构会同同级有关部门按照管理权限，制定本级公共机构的能源消耗定额，财政部门根据该定额制定能源消耗支出标准。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五十条", "text": "公共机构应当加强本单位用能系统管理，保证用能系统的运行符合国家相关标准。 公共机构应当按照规定进行能源审计，并根据能源审计结果采取提高能源利用效率的措施。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五十一条", "text": "公共机构采购用能产品、设备，应当优先采购列入节能产品、设备政府采购名录中的产品、设备。禁止采购国家明令淘汰的用能产品、设备。 节能产品、设备政府采购名录由省级以上人民政府的政府采购监督管理部门会同同级有关部门制定并公布。 第六节 重点用能单位节能"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五十二条", "text": "国家加强对重点用能单位的节能管理。 下列用能单位为重点用能单位： （一）年综合能源消费总量一万吨标准煤以上的用能单位； （二）国务院有关部门或者省、自治区、直辖市人民政府管理节能工作的部门指定的年综合能源消费总量五千吨以上不满一万吨标准煤的用能单位。 重点用能单位节能管理办法，由国务院管理节能工作的部门会同国务院有关部门制定。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五十三条", "text": "重点用能单位应当每年向管理节能工作的部门报送上年度的能源利用状况报告。能源利用状况包括能源消费情况、能源利用效率、节能目标完成情况和节能效益分析、节能措施等内容。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五十四条", "text": "管理节能工作的部门应当对重点用能单位报送的能源利用状况报告进行审查。对节能管理制度不健全、节能措施不落实、能源利用效率低的重点用能单位，管理节能工作的部门应当开展现场调查，组织实施用能设备能源效率检测，责令实施能源审计，并提出书面整改要求，限期整改。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五十五条", "text": "重点用能单位应当设立能源管理岗位，在具有节能专业知识、实际经验以及中级以上技术职称的人员中聘任能源管理负责人，并报管理节能工作的部门和有关部门备案。 能源管理负责人负责组织对本单位用能状况进行分析、评价，组织编写本单位能源利用状况报告，提出本单位节能工作的改进措施并组织实施。 能源管理负责人应当接受节能培训。 第四章 节能技术进步"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五十六条", "text": "国务院管理节能工作的部门会同国务院科技主管部门发布节能技术政策大纲，指导节能技术研究、开发和推广应用。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五十七条", "text": "县级以上各级人民政府应当把节能技术研究开发作为政府科技投入的重点领域，支持科研单位和企业开展节能技术应用研究，制定节能标准，开发节能共性和关键技术，促进节能技术创新与成果转化。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五十八条", "text": "国务院管理节能工作的部门会同国务院有关部门制定并公布节能技术、节能产品的推广目录，引导用能单位和个人使用先进的节能技术、节能产品。 国务院管理节能工作的部门会同国务院有关部门组织实施重大节能科研项目、节能示范项目、重点节能工程。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五十九条", "text": "县级以上各级人民政府应当按照因地制宜、多能互补、综合利用、讲求效益的原则，加强农业和农村节能工作，增加对农业和农村节能技术、节能产品推广应用的资金投入。 农业、科技等有关主管部门应当支持、推广在农业生产、农产品加工储运等方面应用节能技术和节能产品，鼓励更新和淘汰高耗能的农业机械和渔业船舶。 国家鼓励、支持在农村大力发展沼气，推广生物质能、太阳能和风能等可再生能源利用技术，按照科学规划、有序开发的原则发展小型水力发电，推广节能型的农村住宅和炉灶等，鼓励利用非耕地种植能源植物，大力发展薪炭林等能源林。 第五章 激励措施"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第六十条", "text": "中央财政和省级地方财政安排节能专项资金，支持节能技术研究开发、节能技术和产品的示范与推广、重点节能工程的实施、节能宣传培训、信息服务和表彰奖励等。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第六十一条", "text": "国家对生产、使用列入本法"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五十八条", "text": "规定的推广目录的需要支持的节能技术、节能产品，实行税收优惠等扶持政策。 国家通过财政补贴支持节能照明器具等节能产品的推广和使用。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第六十二条", "text": "国家实行有利于节约能源资源的税收政策，健全能源矿产资源有偿使用制度，促进能源资源的节约及其开采利用水平的提高。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第六十三条", "text": "国家运用税收等政策，鼓励先进节能技术、设备的进口，控制在生产过程中耗能高、污染重的产品的出口。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第六十四条", "text": "政府采购监督管理部门会同有关部门制定节能产品、设备政府采购名录，应当优先列入取得节能产品认证证书的产品、设备。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第六十五条", "text": "国家引导金融机构增加对节能项目的信贷支持，为符合条件的节能技术研究开发、节能产品生产以及节能技术改造等项目提供优惠贷款。 国家推动和引导社会有关方面加大对节能的资金投入，加快节能技术改造。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第六十六条", "text": "国家实行有利于节能的价格政策，引导用能单位和个人节能。 国家运用财税、价格等政策，支持推广电力需求侧管理、合同能源管理、节能自愿协议等节能办法。 国家实行峰谷分时电价、季节性电价、可中断负荷电价制度，鼓励电力用户合理调整用电负荷；对钢铁、有色金属、建材、化工和其他主要耗能行业的企业，分淘汰、限制、允许和鼓励类实行差别电价政策。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第六十七条", "text": "各级人民政府对在节能管理、节能科学技术研究和推广应用中有显著成绩以及检举严重浪费能源行为的单位和个人，给予表彰和奖励。 第六章 法律责任"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第六十八条", "text": "负责审批政府投资项目的机关违反本法规定，对不符合强制性节能标准的项目予以批准建设的，对直接负责的主管人员和其他直接责任人员依法给予处分。 固定资产投资项目建设单位开工建设不符合强制性节能标准的项目或者将该项目投入生产、使用的，由管理节能工作的部门责令停止建设或者停止生产、使用，限期改造；不能改造或者逾期不改造的生产性项目，由管理节能工作的部门报请本级人民政府按照国务院规定的权限责令关闭。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第六十九条", "text": "生产、进口、销售国家明令淘汰的用能产品、设备的，使用伪造的节能产品认证标志或者冒用节能产品认证标志的，依照《中华人民共和国产品质量法》的规定处罚。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第七十条", "text": "生产、进口、销售不符合强制性能源效率标准的用能产品、设备的，由市场监督管理部门责令停止生产、进口、销售，没收违法生产、进口、销售的用能产品、设备和违法所得，并处违法所得一倍以上五倍以下罚款；情节严重的，吊销营业执照。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第七十一条", "text": "使用国家明令淘汰的用能设备或者生产工艺的，由管理节能工作的部门责令停止使用，没收国家明令淘汰的用能设备；情节严重的，可以由管理节能工作的部门提出意见，报请本级人民政府按照国务院规定的权限责令停业整顿或者关闭。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第七十二条", "text": "生产单位超过单位产品能耗限额标准用能，情节严重，经限期治理逾期不治理或者没有达到治理要求的，可以由管理节能工作的部门提出意见，报请本级人民政府按照国务院规定的权限责令停业整顿或者关闭。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第七十三条", "text": "违反本法规定，应当标注能源效率标识而未标注的，由市场监督管理部门责令改正，处三万元以上五万元以下罚款。 违反本法规定，未办理能源效率标识备案，或者使用的能源效率标识不符合规定的，由市场监督管理部门责令限期改正；逾期不改正的，处一万元以上三万元以下罚款。 伪造、冒用能源效率标识或者利用能源效率标识进行虚假宣传的，由市场监督管理部门责令改正，处五万元以上十万元以下罚款；情节严重的，吊销营业执照。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第七十四条", "text": "用能单位未按照规定配备、使用能源计量器具的，由市场监督管理部门责令限期改正；逾期不改正的，处一万元以上五万元以下罚款。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第七十五条", "text": "瞒报、伪造、篡改能源统计资料或者编造虚假能源统计数据的，依照《中华人民共和国统计法》的规定处罚。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第七十六条", "text": "从事节能咨询、设计、评估、检测、审计、认证等服务的机构提供虚假信息的，由管理节能工作的部门责令改正，没收违法所得，并处五万元以上十万元以下罚款。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第七十七条", "text": "违反本法规定，无偿向本单位职工提供能源或者对能源消费实行包费制的，由管理节能工作的部门责令限期改正；逾期不改正的，处五万元以上二十万元以下罚款。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第七十八条", "text": "电网企业未按照本法规定安排符合规定的热电联产和利用余热余压发电的机组与电网并网运行，或者未执行国家有关上网电价规定的，由国家电力监管机构责令改正；造成发电企业经济损失的，依法承担赔偿责任。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第七十九条", "text": "建设单位违反建筑节能标准的，由建设主管部门责令改正，处二十万元以上五十万元以下罚款。 设计单位、施工单位、监理单位违反建筑节能标准的，由建设主管部门责令改正，处十万元以上五十万元以下罚款；情节严重的，由颁发资质证书的部门降低资质等级或者吊销资质证书；造成损失的，依法承担赔偿责任。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第八十条", "text": "房地产开发企业违反本法规定，在销售房屋时未向购买人明示所售房屋的节能措施、保温工程保修期等信息的，由建设主管部门责令限期改正，逾期不改正的，处三万元以上五万元以下罚款；对以上信息作虚假宣传的，由建设主管部门责令改正，处五万元以上二十万元以下罚款。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第八十一条", "text": "公共机构采购用能产品、设备，未优先采购列入节能产品、设备政府采购名录中的产品、设备，或者采购国家明令淘汰的用能产品、设备的，由政府采购监督管理部门给予警告，可以并处罚款；对直接负责的主管人员和其他直接责任人员依法给予处分，并予通报。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第八十二条", "text": "重点用能单位未按照本法规定报送能源利用状况报告或者报告内容不实的，由管理节能工作的部门责令限期改正；逾期不改正的，处一万元以上五万元以下罚款。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第八十三条", "text": "重点用能单位无正当理由拒不落实本法"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第五十四条", "text": "规定的整改要求或者整改没有达到要求的，由管理节能工作的部门处十万元以上三十万元以下罚款。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第八十四条", "text": "重点用能单位未按照本法规定设立能源管理岗位，聘任能源管理负责人，并报管理节能工作的部门和有关部门备案的，由管理节能工作的部门责令改正；拒不改正的，处一万元以上三万元以下罚款。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第八十五条", "text": "违反本法规定，构成犯罪的，依法追究刑事责任。"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第八十六条", "text": "国家工作人员在节能管理工作中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。 第七章 附 则"}, {"law": "中华人民共和国节约能源法_20181026.docx", "no": "第八十七条", "text": "本法自2008年4月1日起施行。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一条", "text": "为了维护道路交通秩序，预防和减少交通事故，保护人身安全，保护公民、法人和其他组织的财产安全及其他合法权益，提高通行效率，制定本法。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第二条", "text": "中华人民共和国境内的车辆驾驶人、行人、乘车人以及与道路交通活动有关的单位和个人，都应当遵守本法。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第三条", "text": "道路交通安全工作，应当遵循依法管理、方便群众的原则，保障道路交通有序、安全、畅通。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第四条", "text": "各级人民政府应当保障道路交通安全管理工作与经济建设和社会发展相适应。 县级以上地方各级人民政府应当适应道路交通发展的需要，依据道路交通安全法律、法规和国家有关政策，制定道路交通安全管理规划，并组织实施。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第五条", "text": "国务院公安部门负责全国道路交通安全管理工作。县级以上地方各级人民政府公安机关交通管理部门负责本行政区域内的道路交通安全管理工作。 县级以上各级人民政府交通、建设管理部门依据各自职责，负责有关的道路交通工作。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第六条", "text": "各级人民政府应当经常进行道路交通安全教育，提高公民的道路交通安全意识。 公安机关交通管理部门及其交通警察执行职务时，应当加强道路交通安全法律、法规的宣传，并模范遵守道路交通安全法律、法规。 机关、部队、企业事业单位、社会团体以及其他组织，应当对本单位的人员进行道路交通安全教育。 教育行政部门、学校应当将道路交通安全教育纳入法制教育的内容。 新闻、出版、广播、电视等有关单位，有进行道路交通安全教育的义务。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第七条", "text": "对道路交通安全管理工作，应当加强科学研究，推广、使用先进的管理方法、技术、设备。 第二章 车辆和驾驶人 第一节 机动车、非机动车"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第八条", "text": "国家对机动车实行登记制度。机动车经公安机关交通管理部门登记后，方可上道路行驶。尚未登记的机动车，需要临时上道路行驶的，应当取得临时通行牌证。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九条", "text": "申请机动车登记，应当提交以下证明、凭证： （一）机动车所有人的身份证明； （二）机动车来历证明； （三）机动车整车出厂合格证明或者进口机动车进口凭证； （四）车辆购置税的完税证明或者免税凭证； （五）法律、行政法规规定应当在机动车登记时提交的其他证明、凭证。 公安机关交通管理部门应当自受理申请之日起五个工作日内完成机动车登记审查工作，对符合前款规定条件的，应当发放机动车登记证书、号牌和行驶证；对不符合前款规定条件的，应当向申请人说明不予登记的理由。 公安机关交通管理部门以外的任何单位或者个人不得发放机动车号牌或者要求机动车悬挂其他号牌，本法另有规定的除外。 机动车登记证书、号牌、行驶证的式样由国务院公安部门规定并监制。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第十条", "text": "准予登记的机动车应当符合机动车国家安全技术标准。申请机动车登记时，应当接受对该机动车的安全技术检验。但是，经国家机动车产品主管部门依据机动车国家安全技术标准认定的企业生产的机动车型，该车型的新车在出厂时经检验符合机动车国家安全技术标准，获得检验合格证的，免予安全技术检验。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第十一条", "text": "驾驶机动车上道路行驶，应当悬挂机动车号牌，放置检验合格标志、保险标志，并随车携带机动车行驶证。 机动车号牌应当按照规定悬挂并保持清晰、完整，不得故意遮挡、污损。 任何单位和个人不得收缴、扣留机动车号牌。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第十二条", "text": "有下列情形之一的，应当办理相应的登记： （一）机动车所有权发生转移的； （二）机动车登记内容变更的； （三）机动车用作抵押的； （四）机动车报废的。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第十三条", "text": "对登记后上道路行驶的机动车，应当依照法律、行政法规的规定，根据车辆用途、载客载货数量、使用年限等不同情况，定期进行安全技术检验。对提供机动车行驶证和机动车第三者责任强制保险单的，机动车安全技术检验机构应当予以检验，任何单位不得附加其他条件。对符合机动车国家安全技术标准的，公安机关交通管理部门应当发给检验合格标志。 对机动车的安全技术检验实行社会化。具体办法由国务院规定。 机动车安全技术检验实行社会化的地方，任何单位不得要求机动车到指定的场所进行检验。 公安机关交通管理部门、机动车安全技术检验机构不得要求机动车到指定的场所进行维修、保养。 机动车安全技术检验机构对机动车检验收取费用，应当严格执行国务院价格主管部门核定的收费标准。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第十四条", "text": "国家实行机动车强制报废制度，根据机动车的安全技术状况和不同用途，规定不同的报废标准。 应当报废的机动车必须及时办理注销登记。 达到报废标准的机动车不得上道路行驶。报废的大型客、货车及其他营运车辆应当在公安机关交通管理部门的监督下解体。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第十五条", "text": "警车、消防车、救护车、工程救险车应当按照规定喷涂标志图案，安装警报器、标志灯具。其他机动车不得喷涂、安装、使用上述车辆专用的或者与其相类似的标志图案、警报器或者标志灯具。 警车、消防车、救护车、工程救险车应当严格按照规定的用途和条件使用。 公路监督检查的专用车辆，应当依照公路法的规定，设置统一的标志和示警灯。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第十六条", "text": "任何单位或者个人不得有下列行为： （一）拼装机动车或者擅自改变机动车已登记的结构、构造或者特征； （二）改变机动车型号、发动机号、车架号或者车辆识别代号； （三）伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、检验合格标志、保险标志； （四）使用其他机动车的登记证书、号牌、行驶证、检验合格标志、保险标志。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第十七条", "text": "国家实行机动车第三者责任强制保险制度，设立道路交通事故社会救助基金。具体办法由国务院规定。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第十八条", "text": "依法应当登记的非机动车，经公安机关交通管理部门登记后，方可上道路行驶。 依法应当登记的非机动车的种类，由省、自治区、直辖市人民政府根据当地实际情况规定。 非机动车的外形尺寸、质量、制动器、车铃和夜间反光装置，应当符合非机动车安全技术标准。 第二节 机动车驾驶人"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第十九条", "text": "驾驶机动车，应当依法取得机动车驾驶证。 申请机动车驾驶证，应当符合国务院公安部门规定的驾驶许可条件；经考试合格后，由公安机关交通管理部门发给相应类别的机动车驾驶证。 持有境外机动车驾驶证的人，符合国务院公安部门规定的驾驶许可条件，经公安机关交通管理部门考核合格的，可以发给中国的机动车驾驶证。 驾驶人应当按照驾驶证载明的准驾车型驾驶机动车；驾驶机动车时，应当随身携带机动车驾驶证。 公安机关交通管理部门以外的任何单位或者个人，不得收缴、扣留机动车驾驶证。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第二十条", "text": "机动车的驾驶培训实行社会化，由交通运输主管部门对驾驶培训学校、驾驶培训班实行备案管理，并对驾驶培训活动加强监督，其中专门的拖拉机驾驶培训学校、驾驶培训班由农业（农业机械）主管部门实行监督管理。 驾驶培训学校、驾驶培训班应当严格按照国家有关规定，对学员进行道路交通安全法律、法规、驾驶技能的培训，确保培训质量。 任何国家机关以及驾驶培训和考试主管部门不得举办或者参与举办驾驶培训学校、驾驶培训班。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第二十一条", "text": "驾驶人驾驶机动车上道路行驶前，应当对机动车的安全技术性能进行认真检查；不得驾驶安全设施不全或者机件不符合技术标准等具有安全隐患的机动车。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第二十二条", "text": "机动车驾驶人应当遵守道路交通安全法律、法规的规定，按照操作规范安全驾驶、文明驾驶。 饮酒、服用国家管制的精神药品或者麻醉药品，或者患有妨碍安全驾驶机动车的疾病，或者过度疲劳影响安全驾驶的，不得驾驶机动车。 任何人不得强迫、指使、纵容驾驶人违反道路交通安全法律、法规和机动车安全驾驶要求驾驶机动车。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第二十三条", "text": "公安机关交通管理部门依照法律、行政法规的规定，定期对机动车驾驶证实施审验。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第二十四条", "text": "公安机关交通管理部门对机动车驾驶人违反道路交通安全法律、法规的行为，除依法给予行政处罚外，实行累积记分制度。公安机关交通管理部门对累积记分达到规定分值的机动车驾驶人，扣留机动车驾驶证，对其进行道路交通安全法律、法规教育，重新考试；考试合格的，发还其机动车驾驶证。 对遵守道路交通安全法律、法规，在一年内无累积记分的机动车驾驶人，可以延长机动车驾驶证的审验期。具体办法由国务院公安部门规定。 第三章 道路通行条件"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第二十五条", "text": "全国实行统一的道路交通信号。 交通信号包括交通信号灯、交通标志、交通标线和交通警察的指挥。 交通信号灯、交通标志、交通标线的设置应当符合道路交通安全、畅通的要求和国家标准，并保持清晰、醒目、准确、完好。 根据通行需要，应当及时增设、调换、更新道路交通信号。增设、调换、更新限制性的道路交通信号，应当提前向社会公告，广泛进行宣传。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第二十六条", "text": "交通信号灯由红灯、绿灯、黄灯组成。红灯表示禁止通行，绿灯表示准许通行，黄灯表示警示。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第二十七条", "text": "铁路与道路平面交叉的道口，应当设置警示灯、警示标志或者安全防护设施。无人看守的铁路道口，应当在距道口一定距离处设置警示标志。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第二十八条", "text": "任何单位和个人不得擅自设置、移动、占用、损毁交通信号灯、交通标志、交通标线。 道路两侧及隔离带上种植的树木或者其他植物，设置的广告牌、管线等，应当与交通设施保持必要的距离，不得遮挡路灯、交通信号灯、交通标志，不得妨碍安全视距，不得影响通行。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第二十九条", "text": "道路、停车场和道路配套设施的规划、设计、建设，应当符合道路交通安全、畅通的要求，并根据交通需求及时调整。 公安机关交通管理部门发现已经投入使用的道路存在交通事故频发路段，或者停车场、道路配套设施存在交通安全严重隐患的，应当及时向当地人民政府报告，并提出防范交通事故、消除隐患的建议，当地人民政府应当及时作出处理决定。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第三十条", "text": "道路出现坍塌、坑漕、水毁、隆起等损毁或者交通信号灯、交通标志、交通标线等交通设施损毁、灭失的，道路、交通设施的养护部门或者管理部门应当设置警示标志并及时修复。 公安机关交通管理部门发现前款情形，危及交通安全，尚未设置警示标志的，应当及时采取安全措施，疏导交通，并通知道路、交通设施的养护部门或者管理部门。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第三十一条", "text": "未经许可，任何单位和个人不得占用道路从事非交通活动。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第三十二条", "text": "因工程建设需要占用、挖掘道路，或者跨越、穿越道路架设、增设管线设施，应当事先征得道路主管部门的同意；影响交通安全的，还应当征得公安机关交通管理部门的同意。 施工作业单位应当在经批准的路段和时间内施工作业，并在距离施工作业地点来车方向安全距离处设置明显的安全警示标志，采取防护措施；施工作业完毕，应当迅速清除道路上的障碍物，消除安全隐患，经道路主管部门和公安机关交通管理部门验收合格，符合通行要求后，方可恢复通行。 对未中断交通的施工作业道路，公安机关交通管理部门应当加强交通安全监督检查，维护道路交通秩序。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第三十三条", "text": "新建、改建、扩建的公共建筑、商业街区、居住区、大（中）型建筑等，应当配建、增建停车场；停车泊位不足的，应当及时改建或者扩建；投入使用的停车场不得擅自停止使用或者改作他用。 在城市道路范围内，在不影响行人、车辆通行的情况下，政府有关部门可以施划停车泊位。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第三十四条", "text": "学校、幼儿园、医院、养老院门前的道路没有行人过街设施的，应当施划人行横道线，设置提示标志。 城市主要道路的人行道，应当按照规划设置盲道。盲道的设置应当符合国家标准。 第四章 道路通行规定 第一节 一般规定"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第三十五条", "text": "机动车、非机动车实行右侧通行。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第三十六条", "text": "根据道路条件和通行需要，道路划分为机动车道、非机动车道和人行道的，机动车、非机动车、行人实行分道通行。没有划分机动车道、非机动车道和人行道的，机动车在道路中间通行，非机动车和行人在道路两侧通行。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第三十七条", "text": "道路划设专用车道的，在专用车道内，只准许规定的车辆通行，其他车辆不得进入专用车道内行驶。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第三十八条", "text": "车辆、行人应当按照交通信号通行；遇有交通警察现场指挥时，应当按照交通警察的指挥通行；在没有交通信号的道路上，应当在确保安全、畅通的原则下通行。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第三十九条", "text": "公安机关交通管理部门根据道路和交通流量的具体情况，可以对机动车、非机动车、行人采取疏导、限制通行、禁止通行等措施。遇有大型群众性活动、大范围施工等情况，需要采取限制交通的措施，或者作出与公众的道路交通活动直接有关的决定，应当提前向社会公告。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第四十条", "text": "遇有自然灾害、恶劣气象条件或者重大交通事故等严重影响交通安全的情形，采取其他措施难以保证交通安全时，公安机关交通管理部门可以实行交通管制。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第四十一条", "text": "有关道路通行的其他具体规定，由国务院规定。 第二节 机动车通行规定"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第四十二条", "text": "机动车上道路行驶，不得超过限速标志标明的最高时速。在没有限速标志的路段，应当保持安全车速。 夜间行驶或者在容易发生危险的路段行驶，以及遇有沙尘、冰雹、雨、雪、雾、结冰等气象条件时，应当降低行驶速度。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第四十三条", "text": "同车道行驶的机动车，后车应当与前车保持足以采取紧急制动措施的安全距离。有下列情形之一的，不得超车： （一）前车正在左转弯、掉头、超车的； （二）与对面来车有会车可能的； （三）前车为执行紧急任务的警车、消防车、救护车、工程救险车的； （四）行经铁路道口、交叉路口、窄桥、弯道、陡坡、隧道、人行横道、市区交通流量大的路段等没有超车条件的。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第四十四条", "text": "机动车通过交叉路口，应当按照交通信号灯、交通标志、交通标线或者交通警察的指挥通过；通过没有交通信号灯、交通标志、交通标线或者交通警察指挥的交叉路口时，应当减速慢行，并让行人和优先通行的车辆先行。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第四十五条", "text": "机动车遇有前方车辆停车排队等候或者缓慢行驶时，不得借道超车或者占用对面车道，不得穿插等候的车辆。 在车道减少的路段、路口，或者在没有交通信号灯、交通标志、交通标线或者交通警察指挥的交叉路口遇到停车排队等候或者缓慢行驶时，机动车应当依次交替通行。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第四十六条", "text": "机动车通过铁路道口时，应当按照交通信号或者管理人员的指挥通行；没有交通信号或者管理人员的，应当减速或者停车，在确认安全后通过。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第四十七条", "text": "机动车行经人行横道时，应当减速行驶；遇行人正在通过人行横道，应当停车让行。 机动车行经没有交通信号的道路时，遇行人横过道路，应当避让。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第四十八条", "text": "机动车载物应当符合核定的载质量，严禁超载；载物的长、宽、高不得违反装载要求，不得遗洒、飘散载运物。 机动车运载超限的不可解体的物品，影响交通安全的，应当按照公安机关交通管理部门指定的时间、路线、速度行驶，悬挂明显标志。在公路上运载超限的不可解体的物品，并应当依照公路法的规定执行。 机动车载运爆炸物品、易燃易爆化学物品以及剧毒、放射性等危险物品，应当经公安机关批准后，按指定的时间、路线、速度行驶，悬挂警示标志并采取必要的安全措施。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第四十九条", "text": "机动车载人不得超过核定的人数，客运机动车不得违反规定载货。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第五十条", "text": "禁止货运机动车载客。 货运机动车需要附载作业人员的，应当设置保护作业人员的安全措施。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第五十一条", "text": "机动车行驶时，驾驶人、乘坐人员应当按规定使用安全带，摩托车驾驶人及乘坐人员应当按规定戴安全头盔。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第五十二条", "text": "机动车在道路上发生故障，需要停车排除故障时，驾驶人应当立即开启危险报警闪光灯，将机动车移至不妨碍交通的地方停放；难以移动的，应当持续开启危险报警闪光灯，并在来车方向设置警告标志等措施扩大示警距离，必要时迅速报警。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第五十三条", "text": "警车、消防车、救护车、工程救险车执行紧急任务时，可以使用警报器、标志灯具；在确保安全的前提下，不受行驶路线、行驶方向、行驶速度和信号灯的限制，其他车辆和行人应当让行。 警车、消防车、救护车、工程救险车非执行紧急任务时，不得使用警报器、标志灯具，不享有前款规定的道路优先通行权。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第五十四条", "text": "道路养护车辆、工程作业车进行作业时，在不影响过往车辆通行的前提下，其行驶路线和方向不受交通标志、标线限制，过往车辆和人员应当注意避让。 洒水车、清扫车等机动车应当按照安全作业标准作业；在不影响其他车辆通行的情况下，可以不受车辆分道行驶的限制，但是不得逆向行驶。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第五十五条", "text": "高速公路、大中城市中心城区内的道路，禁止拖拉机通行。其他禁止拖拉机通行的道路，由省、自治区、直辖市人民政府根据当地实际情况规定。 在允许拖拉机通行的道路上，拖拉机可以从事货运，但是不得用于载人。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第五十六条", "text": "机动车应当在规定地点停放。禁止在人行道上停放机动车；但是，依照本法"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第三十三条", "text": "规定施划的停车泊位除外。 在道路上临时停车的，不得妨碍其他车辆和行人通行。 第三节 非机动车通行规定"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第五十七条", "text": "驾驶非机动车在道路上行驶应当遵守有关交通安全的规定。非机动车应当在非机动车道内行驶；在没有非机动车道的道路上，应当靠车行道的右侧行驶。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第五十八条", "text": "残疾人机动轮椅车、电动自行车在非机动车道内行驶时，最高时速不得超过十五公里。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第五十九条", "text": "非机动车应当在规定地点停放。未设停放地点的，非机动车停放不得妨碍其他车辆和行人通行。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第六十条", "text": "驾驭畜力车，应当使用驯服的牲畜；驾驭畜力车横过道路时，驾驭人应当下车牵引牲畜；驾驭人离开车辆时，应当拴系牲畜。 第四节 行人和乘车人通行规定"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第六十一条", "text": "行人应当在人行道内行走，没有人行道的靠路边行走。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第六十二条", "text": "行人通过路口或者横过道路，应当走人行横道或者过街设施；通过有交通信号灯的人行横道，应当按照交通信号灯指示通行；通过没有交通信号灯、人行横道的路口，或者在没有过街设施的路段横过道路，应当在确认安全后通过。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第六十三条", "text": "行人不得跨越、倚坐道路隔离设施，不得扒车、强行拦车或者实施妨碍道路交通安全的其他行为。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第六十四条", "text": "学龄前儿童以及不能辨认或者不能控制自己行为的精神疾病患者、智力障碍者在道路上通行，应当由其监护人、监护人委托的人或者对其负有管理、保护职责的人带领。 盲人在道路上通行，应当使用盲杖或者采取其他导盲手段，车辆应当避让盲人。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第六十五条", "text": "行人通过铁路道口时，应当按照交通信号或者管理人员的指挥通行；没有交通信号和管理人员的，应当在确认无火车驶临后，迅速通过。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第六十六条", "text": "乘车人不得携带易燃易爆等危险物品，不得向车外抛洒物品，不得有影响驾驶人安全驾驶的行为。 第五节 高速公路的特别规定"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第六十七条", "text": "行人、非机动车、拖拉机、轮式专用机械车、铰接式客车、全挂拖斗车以及其他设计最高时速低于七十公里的机动车，不得进入高速公路。高速公路限速标志标明的最高时速不得超过一百二十公里。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第六十八条", "text": "机动车在高速公路上发生故障时，应当依照本法"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第五十二条", "text": "的有关规定办理；但是，警告标志应当设置在故障车来车方向一百五十米以外，车上人员应当迅速转移到右侧路肩上或者应急车道内，并且迅速报警。 机动车在高速公路上发生故障或者交通事故，无法正常行驶的，应当由救援车、清障车拖曳、牵引。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第六十九条", "text": "任何单位、个人不得在高速公路上拦截检查行驶的车辆，公安机关的人民警察依法执行紧急公务除外。 第五章 交通事故处理"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第七十条", "text": "在道路上发生交通事故，车辆驾驶人应当立即停车，保护现场；造成人身伤亡的，车辆驾驶人应当立即抢救受伤人员，并迅速报告执勤的交通警察或者公安机关交通管理部门。因抢救受伤人员变动现场的，应当标明位置。乘车人、过往车辆驾驶人、过往行人应当予以协助。 在道路上发生交通事故，未造成人身伤亡，当事人对事实及成因无争议的，可以即行撤离现场，恢复交通，自行协商处理损害赔偿事宜；不即行撤离现场的，应当迅速报告执勤的交通警察或者公安机关交通管理部门。 在道路上发生交通事故，仅造成轻微财产损失，并且基本事实清楚的，当事人应当先撤离现场再进行协商处理。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第七十一条", "text": "车辆发生交通事故后逃逸的，事故现场目击人员和其他知情人员应当向公安机关交通管理部门或者交通警察举报。举报属实的，公安机关交通管理部门应当给予奖励。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第七十二条", "text": "公安机关交通管理部门接到交通事故报警后，应当立即派交通警察赶赴现场，先组织抢救受伤人员，并采取措施，尽快恢复交通。 交通警察应当对交通事故现场进行勘验、检查，收集证据；因收集证据的需要，可以扣留事故车辆，但是应当妥善保管，以备核查。 对当事人的生理、精神状况等专业性较强的检验，公安机关交通管理部门应当委托专门机构进行鉴定。鉴定结论应当由鉴定人签名。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第七十三条", "text": "公安机关交通管理部门应当根据交通事故现场勘验、检查、调查情况和有关的检验、鉴定结论，及时制作交通事故认定书，作为处理交通事故的证据。交通事故认定书应当载明交通事故的基本事实、成因和当事人的责任，并送达当事人。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第七十四条", "text": "对交通事故损害赔偿的争议，当事人可以请求公安机关交通管理部门调解，也可以直接向人民法院提起民事诉讼。 经公安机关交通管理部门调解，当事人未达成协议或者调解书生效后不履行的，当事人可以向人民法院提起民事诉讼。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第七十五条", "text": "医疗机构对交通事故中的受伤人员应当及时抢救，不得因抢救费用未及时支付而拖延救治。肇事车辆参加机动车第三者责任强制保险的，由保险公司在责任限额范围内支付抢救费用；抢救费用超过责任限额的，未参加机动车第三者责任强制保险或者肇事后逃逸的，由道路交通事故社会救助基金先行垫付部分或者全部抢救费用，道路交通事故社会救助基金管理机构有权向交通事故责任人追偿。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第七十六条", "text": "机动车发生交通事故造成人身伤亡、财产损失的，由保险公司在机动车第三者责任强制保险责任限额范围内予以赔偿；不足的部分，按照下列规定承担赔偿责任： （一）机动车之间发生交通事故的，由有过错的一方承担赔偿责任；双方都有过错的，按照各自过错的比例分担责任。 （二）机动车与非机动车驾驶人、行人之间发生交通事故，非机动车驾驶人、行人没有过错的，由机动车一方承担赔偿责任；有证据证明非机动车驾驶人、行人有过错的，根据过错程度适当减轻机动车一方的赔偿责任；机动车一方没有过错的，承担不超过百分之十的赔偿责任。 交通事故的损失是由非机动车驾驶人、行人故意碰撞机动车造成的，机动车一方不承担赔偿责任。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第七十七条", "text": "车辆在道路以外通行时发生的事故，公安机关交通管理部门接到报案的，参照本法有关规定办理。 第六章 执法监督"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第七十八条", "text": "公安机关交通管理部门应当加强对交通警察的管理，提高交通警察的素质和管理道路交通的水平。 公安机关交通管理部门应当对交通警察进行法制和交通安全管理业务培训、考核。交通警察经考核不合格的，不得上岗执行职务。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第七十九条", "text": "公安机关交通管理部门及其交通警察实施道路交通安全管理，应当依据法定的职权和程序，简化办事手续，做到公正、严格、文明、高效。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第八十条", "text": "交通警察执行职务时，应当按照规定着装，佩带人民警察标志，持有人民警察证件，保持警容严整，举止端庄，指挥规范。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第八十一条", "text": "依照本法发放牌证等收取工本费，应当严格执行国务院价格主管部门核定的收费标准，并全部上缴国库。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第八十二条", "text": "公安机关交通管理部门依法实施罚款的行政处罚，应当依照有关法律、行政法规的规定，实施罚款决定与罚款收缴分离；收缴的罚款以及依法没收的违法所得，应当全部上缴国库。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第八十三条", "text": "交通警察调查处理道路交通安全违法行为和交通事故，有下列情形之一的，应当回避： （一）是本案的当事人或者当事人的近亲属； （二）本人或者其近亲属与本案有利害关系； （三）与本案当事人有其他关系，可能影响案件的公正处理。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第八十四条", "text": "公安机关交通管理部门及其交通警察的行政执法活动，应当接受行政监察机关依法实施的监督。 公安机关督察部门应当对公安机关交通管理部门及其交通警察执行法律、法规和遵守纪律的情况依法进行监督。 上级公安机关交通管理部门应当对下级公安机关交通管理部门的执法活动进行监督。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第八十五条", "text": "公安机关交通管理部门及其交通警察执行职务，应当自觉接受社会和公民的监督。 任何单位和个人都有权对公安机关交通管理部门及其交通警察不严格执法以及违法违纪行为进行检举、控告。收到检举、控告的机关，应当依据职责及时查处。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第八十六条", "text": "任何单位不得给公安机关交通管理部门下达或者变相下达罚款指标；公安机关交通管理部门不得以罚款数额作为考核交通警察的标准。 公安机关交通管理部门及其交通警察对超越法律、法规规定的指令，有权拒绝执行，并同时向上级机关报告。 第七章 法律责任"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第八十七条", "text": "公安机关交通管理部门及其交通警察对道路交通安全违法行为，应当及时纠正。 公安机关交通管理部门及其交通警察应当依据事实和本法的有关规定对道路交通安全违法行为予以处罚。对于情节轻微，未影响道路通行的，指出违法行为，给予口头警告后放行。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第八十八条", "text": "对道路交通安全违法行为的处罚种类包括：警告、罚款、暂扣或者吊销机动车驾驶证、拘留。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第八十九条", "text": "行人、乘车人、非机动车驾驶人违反道路交通安全法律、法规关于道路通行规定的，处警告或者五元以上五十元以下罚款；非机动车驾驶人拒绝接受罚款处罚的，可以扣留其非机动车。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九十条", "text": "机动车驾驶人违反道路交通安全法律、法规关于道路通行规定的，处警告或者二十元以上二百元以下罚款。本法另有规定的，依照规定处罚。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九十一条", "text": "饮酒后驾驶机动车的，处暂扣六个月机动车驾驶证，并处一千元以上二千元以下罚款。因饮酒后驾驶机动车被处罚，再次饮酒后驾驶机动车的，处十日以下拘留，并处一千元以上二千元以下罚款，吊销机动车驾驶证。 醉酒驾驶机动车的，由公安机关交通管理部门约束至酒醒，吊销机动车驾驶证，依法追究刑事责任；五年内不得重新取得机动车驾驶证。 饮酒后驾驶营运机动车的，处十五日拘留，并处五千元罚款，吊销机动车驾驶证，五年内不得重新取得机动车驾驶证。 醉酒驾驶营运机动车的，由公安机关交通管理部门约束至酒醒，吊销机动车驾驶证，依法追究刑事责任；十年内不得重新取得机动车驾驶证，重新取得机动车驾驶证后，不得驾驶营运机动车。 饮酒后或者醉酒驾驶机动车发生重大交通事故，构成犯罪的，依法追究刑事责任，并由公安机关交通管理部门吊销机动车驾驶证，终生不得重新取得机动车驾驶证。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九十二条", "text": "公路客运车辆载客超过额定乘员的，处二百元以上五百元以下罚款；超过额定乘员百分之二十或者违反规定载货的，处五百元以上二千元以下罚款。 货运机动车超过核定载质量的，处二百元以上五百元以下罚款；超过核定载质量百分之三十或者违反规定载客的，处五百元以上二千元以下罚款。 有前两款行为的，由公安机关交通管理部门扣留机动车至违法状态消除。 运输单位的车辆有本条第一款、第二款规定的情形，经处罚不改的，对直接负责的主管人员处二千元以上五千元以下罚款。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九十三条", "text": "对违反道路交通安全法律、法规关于机动车停放、临时停车规定的，可以指出违法行为，并予以口头警告，令其立即驶离。 机动车驾驶人不在现场或者虽在现场但拒绝立即驶离，妨碍其他车辆、行人通行的，处二十元以上二百元以下罚款，并可以将该机动车拖移至不妨碍交通的地点或者公安机关交通管理部门指定的地点停放。公安机关交通管理部门拖车不得向当事人收取费用，并应当及时告知当事人停放地点。 因采取不正确的方法拖车造成机动车损坏的，应当依法承担补偿责任。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九十四条", "text": "机动车安全技术检验机构实施机动车安全技术检验超过国务院价格主管部门核定的收费标准收取费用的，退还多收取的费用，并由价格主管部门依照《中华人民共和国价格法》的有关规定给予处罚。 机动车安全技术检验机构不按照机动车国家安全技术标准进行检验，出具虚假检验结果的，由公安机关交通管理部门处所收检验费用五倍以上十倍以下罚款，并依法撤销其检验资格；构成犯罪的，依法追究刑事责任。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九十五条", "text": "上道路行驶的机动车未悬挂机动车号牌，未放置检验合格标志、保险标志，或者未随车携带行驶证、驾驶证的，公安机关交通管理部门应当扣留机动车，通知当事人提供相应的牌证、标志或者补办相应手续，并可以依照本法"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九十条", "text": "的规定予以处罚。当事人提供相应的牌证、标志或者补办相应手续的，应当及时退还机动车。 故意遮挡、污损或者不按规定安装机动车号牌的，依照本法"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九十条", "text": "的规定予以处罚。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九十六条", "text": "伪造、变造或者使用伪造、变造的机动车登记证书、号牌、行驶证、驾驶证的，由公安机关交通管理部门予以收缴，扣留该机动车，处十五日以下拘留，并处二千元以上五千元以下罚款；构成犯罪的，依法追究刑事责任。 伪造、变造或者使用伪造、变造的检验合格标志、保险标志的，由公安机关交通管理部门予以收缴，扣留该机动车，处十日以下拘留，并处一千元以上三千元以下罚款；构成犯罪的，依法追究刑事责任。 使用其他车辆的机动车登记证书、号牌、行驶证、检验合格标志、保险标志的，由公安机关交通管理部门予以收缴，扣留该机动车，处二千元以上五千元以下罚款。 当事人提供相应的合法证明或者补办相应手续的，应当及时退还机动车。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九十七条", "text": "非法安装警报器、标志灯具的，由公安机关交通管理部门强制拆除，予以收缴，并处二百元以上二千元以下罚款。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九十八条", "text": "机动车所有人、管理人未按照国家规定投保机动车第三者责任强制保险的，由公安机关交通管理部门扣留车辆至依照规定投保后，并处依照规定投保最低责任限额应缴纳的保险费的二倍罚款。 依照前款缴纳的罚款全部纳入道路交通事故社会救助基金。具体办法由国务院规定。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第九十九条", "text": "有下列行为之一的，由公安机关交通管理部门处二百元以上二千元以下罚款： （一）未取得机动车驾驶证、机动车驾驶证被吊销或者机动车驾驶证被暂扣期间驾驶机动车的； （二）将机动车交由未取得机动车驾驶证或者机动车驾驶证被吊销、暂扣的人驾驶的； （三）造成交通事故后逃逸，尚不构成犯罪的； （四）机动车行驶超过规定时速百分之五十的； （五）强迫机动车驾驶人违反道路交通安全法律、法规和机动车安全驾驶要求驾驶机动车，造成交通事故，尚不构成犯罪的； （六）违反交通管制的规定强行通行，不听劝阻的； （七）故意损毁、移动、涂改交通设施，造成危害后果，尚不构成犯罪的； （八）非法拦截、扣留机动车辆，不听劝阻，造成交通严重阻塞或者较大财产损失的。 行为人有前款第二项、第四项情形之一的，可以并处吊销机动车驾驶证；有第一项、第三项、第五项至第八项情形之一的，可以并处十五日以下拘留。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百条", "text": "驾驶拼装的机动车或者已达到报废标准的机动车上道路行驶的，公安机关交通管理部门应当予以收缴，强制报废。 对驾驶前款所列机动车上道路行驶的驾驶人，处二百元以上二千元以下罚款，并吊销机动车驾驶证。 出售已达到报废标准的机动车的，没收违法所得，处销售金额等额的罚款，对该机动车依照本条第一款的规定处理。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百零一条", "text": "违反道路交通安全法律、法规的规定，发生重大交通事故，构成犯罪的，依法追究刑事责任，并由公安机关交通管理部门吊销机动车驾驶证。 造成交通事故后逃逸的，由公安机关交通管理部门吊销机动车驾驶证，且终生不得重新取得机动车驾驶证。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百零二条", "text": "对六个月内发生二次以上特大交通事故负有主要责任或者全部责任的专业运输单位，由公安机关交通管理部门责令消除安全隐患，未消除安全隐患的机动车，禁止上道路行驶。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百零三条", "text": "国家机动车产品主管部门未按照机动车国家安全技术标准严格审查，许可不合格机动车型投入生产的，对负有责任的主管人员和其他直接责任人员给予降级或者撤职的行政处分。 机动车生产企业经国家机动车产品主管部门许可生产的机动车型，不执行机动车国家安全技术标准或者不严格进行机动车成品质量检验，致使质量不合格的机动车出厂销售的，由质量技术监督部门依照《中华人民共和国产品质量法》的有关规定给予处罚。 擅自生产、销售未经国家机动车产品主管部门许可生产的机动车型的，没收非法生产、销售的机动车成品及配件，可以并处非法产品价值三倍以上五倍以下罚款；有营业执照的，由工商行政管理部门吊销营业执照，没有营业执照的，予以查封。 生产、销售拼装的机动车或者生产、销售擅自改装的机动车的，依照本条第三款的规定处罚。 有本条第二款、第三款、第四款所列违法行为，生产或者销售不符合机动车国家安全技术标准的机动车，构成犯罪的，依法追究刑事责任。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百零四条", "text": "未经批准，擅自挖掘道路、占用道路施工或者从事其他影响道路交通安全活动的，由道路主管部门责令停止违法行为，并恢复原状，可以依法给予罚款；致使通行的人员、车辆及其他财产遭受损失的，依法承担赔偿责任。 有前款行为，影响道路交通安全活动的，公安机关交通管理部门可以责令停止违法行为，迅速恢复交通。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百零五条", "text": "道路施工作业或者道路出现损毁，未及时设置警示标志、未采取防护措施，或者应当设置交通信号灯、交通标志、交通标线而没有设置或者应当及时变更交通信号灯、交通标志、交通标线而没有及时变更，致使通行的人员、车辆及其他财产遭受损失的，负有相关职责的单位应当依法承担赔偿责任。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百零六条", "text": "在道路两侧及隔离带上种植树木、其他植物或者设置广告牌、管线等，遮挡路灯、交通信号灯、交通标志，妨碍安全视距的，由公安机关交通管理部门责令行为人排除妨碍；拒不执行的，处二百元以上二千元以下罚款，并强制排除妨碍，所需费用由行为人负担。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百零七条", "text": "对道路交通违法行为人予以警告、二百元以下罚款，交通警察可以当场作出行政处罚决定，并出具行政处罚决定书。 行政处罚决定书应当载明当事人的违法事实、行政处罚的依据、处罚内容、时间、地点以及处罚机关名称，并由执法人员签名或者盖章。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百零八条", "text": "当事人应当自收到罚款的行政处罚决定书之日起十五日内，到指定的银行缴纳罚款。 对行人、乘车人和非机动车驾驶人的罚款，当事人无异议的，可以当场予以收缴罚款。 罚款应当开具省、自治区、直辖市财政部门统一制发的罚款收据；不出具财政部门统一制发的罚款收据的，当事人有权拒绝缴纳罚款。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百零九条", "text": "当事人逾期不履行行政处罚决定的，作出行政处罚决定的行政机关可以采取下列措施： （一）到期不缴纳罚款的，每日按罚款数额的百分之三加处罚款； （二）申请人民法院强制执行。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百一十条", "text": "执行职务的交通警察认为应当对道路交通违法行为人给予暂扣或者吊销机动车驾驶证处罚的，可以先予扣留机动车驾驶证，并在二十四小时内将案件移交公安机关交通管理部门处理。 道路交通违法行为人应当在十五日内到公安机关交通管理部门接受处理。无正当理由逾期未接受处理的，吊销机动车驾驶证。 公安机关交通管理部门暂扣或者吊销机动车驾驶证的，应当出具行政处罚决定书。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百一十一条", "text": "对违反本法规定予以拘留的行政处罚，由县、市公安局、公安分局或者相当于县一级的公安机关裁决。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百一十二条", "text": "公安机关交通管理部门扣留机动车、非机动车，应当当场出具凭证，并告知当事人在规定期限内到公安机关交通管理部门接受处理。 公安机关交通管理部门对被扣留的车辆应当妥善保管，不得使用。 逾期不来接受处理，并且经公告三个月仍不来接受处理的，对扣留的车辆依法处理。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百一十三条", "text": "暂扣机动车驾驶证的期限从处罚决定生效之日起计算；处罚决定生效前先予扣留机动车驾驶证的，扣留一日折抵暂扣期限一日。 吊销机动车驾驶证后重新申请领取机动车驾驶证的期限，按照机动车驾驶证管理规定办理。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百一十四条", "text": "公安机关交通管理部门根据交通技术监控记录资料，可以对违法的机动车所有人或者管理人依法予以处罚。对能够确定驾驶人的，可以依照本法的规定依法予以处罚。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百一十五条", "text": "交通警察有下列行为之一的，依法给予行政处分： （一）为不符合法定条件的机动车发放机动车登记证书、号牌、行驶证、检验合格标志的； （二）批准不符合法定条件的机动车安装、使用警车、消防车、救护车、工程救险车的警报器、标志灯具，喷涂标志图案的； （三）为不符合驾驶许可条件、未经考试或者考试不合格人员发放机动车驾驶证的； （四）不执行罚款决定与罚款收缴分离制度或者不按规定将依法收取的费用、收缴的罚款及没收的违法所得全部上缴国库的； （五）举办或者参与举办驾驶学校或者驾驶培训班、机动车修理厂或者收费停车场等经营活动的； （六）利用职务上的便利收受他人财物或者谋取其他利益的； （七）违法扣留车辆、机动车行驶证、驾驶证、车辆号牌的； （八）使用依法扣留的车辆的； （九）当场收取罚款不开具罚款收据或者不如实填写罚款额的； （十）徇私舞弊，不公正处理交通事故的； （十一）故意刁难，拖延办理机动车牌证的； （十二）非执行紧急任务时使用警报器、标志灯具的； （十三）违反规定拦截、检查正常行驶的车辆的； （十四）非执行紧急公务时拦截搭乘机动车的； （十五）不履行法定职责的。 公安机关交通管理部门有前款所列行为之一的，对直接负责的主管人员和其他直接责任人员给予相应的行政处分。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百一十五条", "text": "的规定，给予交通警察行政处分的，在作出行政处分决定前，可以停止其执行职务；必要时，可以予以禁闭。 依照本法"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百一十五条", "text": "的规定，交通警察受到降级或者撤职行政处分的，可以予以辞退。 交通警察受到开除处分或者被辞退的，应当取消警衔；受到撤职以下行政处分的交通警察，应当降低警衔。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百一十七条", "text": "交通警察利用职权非法占有公共财物，索取、收受贿赂，或者滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百一十八条", "text": "公安机关交通管理部门及其交通警察有本法"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百一十五条", "text": "所列行为之一，给当事人造成损失的，应当依法承担赔偿责任。 第八章 附 则"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百一十九条", "text": "本法中下列用语的含义： （一）“道路”，是指公路、城市道路和虽在单位管辖范围但允许社会机动车通行的地方，包括广场、公共停车场等用于公众通行的场所。 （二）“车辆”，是指机动车和非机动车。 （三）“机动车”，是指以动力装置驱动或者牵引，上道路行驶的供人员乘用或者用于运送物品以及进行工程专项作业的轮式车辆。 （四）“非机动车”，是指以人力或者畜力驱动，上道路行驶的交通工具，以及虽有动力装置驱动但设计最高时速、空车质量、外形尺寸符合有关国家标准的残疾人机动轮椅车、电动自行车等交通工具。 （五）“交通事故”，是指车辆在道路上因过错或者意外造成的人身伤亡或者财产损失的事件。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百二十条", "text": "中国人民解放军和中国人民武装警察部队在编机动车牌证、在编机动车检验以及机动车驾驶人考核工作，由中国人民解放军、中国人民武装警察部队有关部门负责。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百二十一条", "text": "对上道路行驶的拖拉机，由农业（农业机械）主管部门行使本法"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第二十三条", "text": "规定的公安机关交通管理部门的管理职权。 农业（农业机械）主管部门依照前款规定行使职权，应当遵守本法有关规定，并接受公安机关交通管理部门的监督；对违反规定的，依照本法有关规定追究法律责任。 本法施行前由农业（农业机械）主管部门发放的机动车牌证，在本法施行后继续有效。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百二十二条", "text": "国家对入境的境外机动车的道路交通安全实施统一管理。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百二十三条", "text": "省、自治区、直辖市人民代表大会常务委员会可以根据本地区的实际情况，在本法规定的罚款幅度内，规定具体的执行标准。"}, {"law": "中华人民共和国道路交通安全法_20210429.docx", "no": "第一百二十四条", "text": "本法自2004年5月1日起施行。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一条", "text": "为了保证食品安全，保障公众身体健康和生命安全，制定本法。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第二条", "text": "在中华人民共和国境内从事下列活动，应当遵守本法： （一）食品生产和加工（以下称食品生产），食品销售和餐饮服务（以下称食品经营）； （二）食品添加剂的生产经营； （三）用于食品的包装材料、容器、洗涤剂、消毒剂和用于食品生产经营的工具、设备（以下称食品相关产品）的生产经营； （四）食品生产经营者使用食品添加剂、食品相关产品； （五）食品的贮存和运输； （六）对食品、食品添加剂、食品相关产品的安全管理。 供食用的源于农业的初级产品（以下称食用农产品）的质量安全管理，遵守《中华人民共和国农产品质量安全法》的规定。但是，食用农产品的市场销售、有关质量安全标准的制定、有关安全信息的公布和本法对农业投入品作出规定的，应当遵守本法的规定。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三条", "text": "食品安全工作实行预防为主、风险管理、全程控制、社会共治，建立科学、严格的监督管理制度。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第四条", "text": "食品生产经营者对其生产经营食品的安全负责。 食品生产经营者应当依照法律、法规和食品安全标准从事生产经营活动，保证食品安全，诚信自律，对社会和公众负责，接受社会监督，承担社会责任。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第五条", "text": "国务院设立食品安全委员会，其职责由国务院规定。 国务院食品安全监督管理部门依照本法和国务院规定的职责，对食品生产经营活动实施监督管理。 国务院卫生行政部门依照本法和国务院规定的职责，组织开展食品安全风险监测和风险评估，会同国务院食品安全监督管理部门制定并公布食品安全国家标准。 国务院其他有关部门依照本法和国务院规定的职责，承担有关食品安全工作。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六条", "text": "县级以上地方人民政府对本行政区域的食品安全监督管理工作负责，统一领导、组织、协调本行政区域的食品安全监督管理工作以及食品安全突发事件应对工作，建立健全食品安全全程监督管理工作机制和信息共享机制。 县级以上地方人民政府依照本法和国务院的规定，确定本级食品安全监督管理、卫生行政部门和其他有关部门的职责。有关部门在各自职责范围内负责本行政区域的食品安全监督管理工作。 县级人民政府食品安全监督管理部门可以在乡镇或者特定区域设立派出机构。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第七条", "text": "县级以上地方人民政府实行食品安全监督管理责任制。上级人民政府负责对下一级人民政府的食品安全监督管理工作进行评议、考核。县级以上地方人民政府负责对本级食品安全监督管理部门和其他有关部门的食品安全监督管理工作进行评议、考核。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第八条", "text": "县级以上人民政府应当将食品安全工作纳入本级国民经济和社会发展规划，将食品安全工作经费列入本级政府财政预算，加强食品安全监督管理能力建设，为食品安全工作提供保障。 县级以上人民政府食品安全监督管理部门和其他有关部门应当加强沟通、密切配合，按照各自职责分工，依法行使职权，承担责任。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第九条", "text": "食品行业协会应当加强行业自律，按照章程建立健全行业规范和奖惩机制，提供食品安全信息、技术等服务，引导和督促食品生产经营者依法生产经营，推动行业诚信建设，宣传、普及食品安全知识。 消费者协会和其他消费者组织对违反本法规定，损害消费者合法权益的行为，依法进行社会监督。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第十条", "text": "各级人民政府应当加强食品安全的宣传教育，普及食品安全知识，鼓励社会组织、基层群众性自治组织、食品生产经营者开展食品安全法律、法规以及食品安全标准和知识的普及工作，倡导健康的饮食方式，增强消费者食品安全意识和自我保护能力。 新闻媒体应当开展食品安全法律、法规以及食品安全标准和知识的公益宣传，并对食品安全违法行为进行舆论监督。有关食品安全的宣传报道应当真实、公正。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第十一条", "text": "国家鼓励和支持开展与食品安全有关的基础研究、应用研究，鼓励和支持食品生产经营者为提高食品安全水平采用先进技术和先进管理规范。 国家对农药的使用实行严格的管理制度，加快淘汰剧毒、高毒、高残留农药，推动替代产品的研发和应用，鼓励使用高效低毒低残留农药。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第十二条", "text": "任何组织或者个人有权举报食品安全违法行为，依法向有关部门了解食品安全信息，对食品安全监督管理工作提出意见和建议。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第十三条", "text": "对在食品安全工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。 第二章 食品安全风险监测和评估"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第十四条", "text": "国家建立食品安全风险监测制度，对食源性疾病、食品污染以及食品中的有害因素进行监测。 国务院卫生行政部门会同国务院食品安全监督管理等部门，制定、实施国家食品安全风险监测计划。 国务院食品安全监督管理部门和其他有关部门获知有关食品安全风险信息后，应当立即核实并向国务院卫生行政部门通报。对有关部门通报的食品安全风险信息以及医疗机构报告的食源性疾病等有关疾病信息，国务院卫生行政部门应当会同国务院有关部门分析研究，认为必要的，及时调整国家食品安全风险监测计划。 省、自治区、直辖市人民政府卫生行政部门会同同级食品安全监督管理等部门，根据国家食品安全风险监测计划，结合本行政区域的具体情况，制定、调整本行政区域的食品安全风险监测方案，报国务院卫生行政部门备案并实施。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第十五条", "text": "承担食品安全风险监测工作的技术机构应当根据食品安全风险监测计划和监测方案开展监测工作，保证监测数据真实、准确，并按照食品安全风险监测计划和监测方案的要求报送监测数据和分析结果。 食品安全风险监测工作人员有权进入相关食用农产品种植养殖、食品生产经营场所采集样品、收集相关数据。采集样品应当按照市场价格支付费用。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第十六条", "text": "食品安全风险监测结果表明可能存在食品安全隐患的，县级以上人民政府卫生行政部门应当及时将相关信息通报同级食品安全监督管理等部门，并报告本级人民政府和上级人民政府卫生行政部门。食品安全监督管理等部门应当组织开展进一步调查。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第十七条", "text": "国家建立食品安全风险评估制度，运用科学方法，根据食品安全风险监测信息、科学数据以及有关信息，对食品、食品添加剂、食品相关产品中生物性、化学性和物理性危害因素进行风险评估。 国务院卫生行政部门负责组织食品安全风险评估工作，成立由医学、农业、食品、营养、生物、环境等方面的专家组成的食品安全风险评估专家委员会进行食品安全风险评估。食品安全风险评估结果由国务院卫生行政部门公布。 对农药、肥料、兽药、饲料和饲料添加剂等的安全性评估，应当有食品安全风险评估专家委员会的专家参加。 食品安全风险评估不得向生产经营者收取费用，采集样品应当按照市场价格支付费用。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第十八条", "text": "有下列情形之一的，应当进行食品安全风险评估： （一）通过食品安全风险监测或者接到举报发现食品、食品添加剂、食品相关产品可能存在安全隐患的； （二）为制定或者修订食品安全国家标准提供科学依据需要进行风险评估的； （三）为确定监督管理的重点领域、重点品种需要进行风险评估的； （四）发现新的可能危害食品安全因素的； （五）需要判断某一因素是否构成食品安全隐患的； （六）国务院卫生行政部门认为需要进行风险评估的其他情形。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第十九条", "text": "国务院食品安全监督管理、农业行政等部门在监督管理工作中发现需要进行食品安全风险评估的，应当向国务院卫生行政部门提出食品安全风险评估的建议，并提供风险来源、相关检验数据和结论等信息、资料。属于本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第十八条", "text": "规定情形的，国务院卫生行政部门应当及时进行食品安全风险评估，并向国务院有关部门通报评估结果。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第二十条", "text": "省级以上人民政府卫生行政、农业行政部门应当及时相互通报食品、食用农产品安全风险监测信息。 国务院卫生行政、农业行政部门应当及时相互通报食品、食用农产品安全风险评估结果等信息。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第二十一条", "text": "食品安全风险评估结果是制定、修订食品安全标准和实施食品安全监督管理的科学依据。 经食品安全风险评估，得出食品、食品添加剂、食品相关产品不安全结论的，国务院食品安全监督管理等部门应当依据各自职责立即向社会公告，告知消费者停止食用或者使用，并采取相应措施，确保该食品、食品添加剂、食品相关产品停止生产经营；需要制定、修订相关食品安全国家标准的，国务院卫生行政部门应当会同国务院食品安全监督管理部门立即制定、修订。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第二十二条", "text": "国务院食品安全监督管理部门应当会同国务院有关部门，根据食品安全风险评估结果、食品安全监督管理信息，对食品安全状况进行综合分析。对经综合分析表明可能具有较高程度安全风险的食品，国务院食品安全监督管理部门应当及时提出食品安全风险警示，并向社会公布。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第二十三条", "text": "县级以上人民政府食品安全监督管理部门和其他有关部门、食品安全风险评估专家委员会及其技术机构，应当按照科学、客观、及时、公开的原则，组织食品生产经营者、食品检验机构、认证机构、食品行业协会、消费者协会以及新闻媒体等，就食品安全风险评估信息和食品安全监督管理信息进行交流沟通。 第三章 食品安全标准"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第二十四条", "text": "制定食品安全标准，应当以保障公众身体健康为宗旨，做到科学合理、安全可靠。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第二十五条", "text": "食品安全标准是强制执行的标准。除食品安全标准外，不得制定其他食品强制性标准。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第二十六条", "text": "食品安全标准应当包括下列内容： （一）食品、食品添加剂、食品相关产品中的致病性微生物，农药残留、兽药残留、生物毒素、重金属等污染物质以及其他危害人体健康物质的限量规定； （二）食品添加剂的品种、使用范围、用量； （三）专供婴幼儿和其他特定人群的主辅食品的营养成分要求； （四）对与卫生、营养等食品安全要求有关的标签、标志、说明书的要求； （五）食品生产经营过程的卫生要求； （六）与食品安全有关的质量要求； （七）与食品安全有关的食品检验方法与规程； （八）其他需要制定为食品安全标准的内容。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第二十七条", "text": "食品安全国家标准由国务院卫生行政部门会同国务院食品安全监督管理部门制定、公布，国务院标准化行政部门提供国家标准编号。 食品中农药残留、兽药残留的限量规定及其检验方法与规程由国务院卫生行政部门、国务院农业行政部门会同国务院食品安全监督管理部门制定。 屠宰畜、禽的检验规程由国务院农业行政部门会同国务院卫生行政部门制定。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第二十八条", "text": "制定食品安全国家标准，应当依据食品安全风险评估结果并充分考虑食用农产品安全风险评估结果，参照相关的国际标准和国际食品安全风险评估结果，并将食品安全国家标准草案向社会公布，广泛听取食品生产经营者、消费者、有关部门等方面的意见。 食品安全国家标准应当经国务院卫生行政部门组织的食品安全国家标准审评委员会审查通过。食品安全国家标准审评委员会由医学、农业、食品、营养、生物、环境等方面的专家以及国务院有关部门、食品行业协会、消费者协会的代表组成，对食品安全国家标准草案的科学性和实用性等进行审查。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第二十九条", "text": "对地方特色食品，没有食品安全国家标准的，省、自治区、直辖市人民政府卫生行政部门可以制定并公布食品安全地方标准，报国务院卫生行政部门备案。食品安全国家标准制定后，该地方标准即行废止。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十条", "text": "国家鼓励食品生产企业制定严于食品安全国家标准或者地方标准的企业标准，在本企业适用，并报省、自治区、直辖市人民政府卫生行政部门备案。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十一条", "text": "省级以上人民政府卫生行政部门应当在其网站上公布制定和备案的食品安全国家标准、地方标准和企业标准，供公众免费查阅、下载。 对食品安全标准执行过程中的问题，县级以上人民政府卫生行政部门应当会同有关部门及时给予指导、解答。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十二条", "text": "省级以上人民政府卫生行政部门应当会同同级食品安全监督管理、农业行政等部门，分别对食品安全国家标准和地方标准的执行情况进行跟踪评价，并根据评价结果及时修订食品安全标准。 省级以上人民政府食品安全监督管理、农业行政等部门应当对食品安全标准执行中存在的问题进行收集、汇总，并及时向同级卫生行政部门通报。 食品生产经营者、食品行业协会发现食品安全标准在执行中存在问题的，应当立即向卫生行政部门报告。 第四章 食品生产经营 第一节 一般规定"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十三条", "text": "食品生产经营应当符合食品安全标准，并符合下列要求： （一）具有与生产经营的食品品种、数量相适应的食品原料处理和食品加工、包装、贮存等场所，保持该场所环境整洁，并与有毒、有害场所以及其他污染源保持规定的距离； （二）具有与生产经营的食品品种、数量相适应的生产经营设备或者设施，有相应的消毒、更衣、盥洗、采光、照明、通风、防腐、防尘、防蝇、防鼠、防虫、洗涤以及处理废水、存放垃圾和废弃物的设备或者设施； （三）有专职或者兼职的食品安全专业技术人员、食品安全管理人员和保证食品安全的规章制度； （四）具有合理的设备布局和工艺流程，防止待加工食品与直接入口食品、原料与成品交叉污染，避免食品接触有毒物、不洁物； （五）餐具、饮具和盛放直接入口食品的容器，使用前应当洗净、消毒，炊具、用具用后应当洗净，保持清洁； （六）贮存、运输和装卸食品的容器、工具和设备应当安全、无害，保持清洁，防止食品污染，并符合保证食品安全所需的温度、湿度等特殊要求，不得将食品与有毒、有害物品一同贮存、运输； （七）直接入口的食品应当使用无毒、清洁的包装材料、餐具、饮具和容器； （八）食品生产经营人员应当保持个人卫生，生产经营食品时，应当将手洗净，穿戴清洁的工作衣、帽等；销售无包装的直接入口食品时，应当使用无毒、清洁的容器、售货工具和设备； （九）用水应当符合国家规定的生活饮用水卫生标准； （十）使用的洗涤剂、消毒剂应当对人体安全、无害； （十一）法律、法规规定的其他要求。 非食品生产经营者从事食品贮存、运输和装卸的，应当符合前款第六项的规定。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十四条", "text": "禁止生产经营下列食品、食品添加剂、食品相关产品： （一）用非食品原料生产的食品或者添加食品添加剂以外的化学物质和其他可能危害人体健康物质的食品，或者用回收食品作为原料生产的食品； （二）致病性微生物，农药残留、兽药残留、生物毒素、重金属等污染物质以及其他危害人体健康的物质含量超过食品安全标准限量的食品、食品添加剂、食品相关产品； （三）用超过保质期的食品原料、食品添加剂生产的食品、食品添加剂； （四）超范围、超限量使用食品添加剂的食品； （五）营养成分不符合食品安全标准的专供婴幼儿和其他特定人群的主辅食品； （六）腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物、掺假掺杂或者感官性状异常的食品、食品添加剂； （七）病死、毒死或者死因不明的禽、畜、兽、水产动物肉类及其制品； （八）未按规定进行检疫或者检疫不合格的肉类，或者未经检验或者检验不合格的肉类制品； （九）被包装材料、容器、运输工具等污染的食品、食品添加剂； （十）标注虚假生产日期、保质期或者超过保质期的食品、食品添加剂； （十一）无标签的预包装食品、食品添加剂； （十二）国家为防病等特殊需要明令禁止生产经营的食品； （十三）其他不符合法律、法规或者食品安全标准的食品、食品添加剂、食品相关产品。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十五条", "text": "国家对食品生产经营实行许可制度。从事食品生产、食品销售、餐饮服务，应当依法取得许可。但是，销售食用农产品和仅销售预包装食品的，不需要取得许可。仅销售预包装食品的，应当报所在地县级以上地方人民政府食品安全监督管理部门备案。 县级以上地方人民政府食品安全监督管理部门应当依照《中华人民共和国行政许可法》的规定，审核申请人提交的本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十三条", "text": "第一款第一项至第四项规定要求的相关资料，必要时对申请人的生产经营场所进行现场核查；对符合规定条件的，准予许可；对不符合规定条件的，不予许可并书面说明理由。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十六条", "text": "食品生产加工小作坊和食品摊贩等从事食品生产经营活动，应当符合本法规定的与其生产经营规模、条件相适应的食品安全要求，保证所生产经营的食品卫生、无毒、无害，食品安全监督管理部门应当对其加强监督管理。 县级以上地方人民政府应当对食品生产加工小作坊、食品摊贩等进行综合治理，加强服务和统一规划，改善其生产经营环境，鼓励和支持其改进生产经营条件，进入集中交易市场、店铺等固定场所经营，或者在指定的临时经营区域、时段经营。 食品生产加工小作坊和食品摊贩等的具体管理办法由省、自治区、直辖市制定。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十七条", "text": "利用新的食品原料生产食品，或者生产食品添加剂新品种、食品相关产品新品种，应当向国务院卫生行政部门提交相关产品的安全性评估材料。国务院卫生行政部门应当自收到申请之日起六十日内组织审查；对符合食品安全要求的，准予许可并公布；对不符合食品安全要求的，不予许可并书面说明理由。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十八条", "text": "生产经营的食品中不得添加药品，但是可以添加按照传统既是食品又是中药材的物质。按照传统既是食品又是中药材的物质目录由国务院卫生行政部门会同国务院食品安全监督管理部门制定、公布。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十九条", "text": "国家对食品添加剂生产实行许可制度。从事食品添加剂生产，应当具有与所生产食品添加剂品种相适应的场所、生产设备或者设施、专业技术人员和管理制度，并依照本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十五条", "text": "第二款规定的程序，取得食品添加剂生产许可。 生产食品添加剂应当符合法律、法规和食品安全国家标准。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第四十条", "text": "食品添加剂应当在技术上确有必要且经过风险评估证明安全可靠，方可列入允许使用的范围；有关食品安全国家标准应当根据技术必要性和食品安全风险评估结果及时修订。 食品生产经营者应当按照食品安全国家标准使用食品添加剂。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第四十一条", "text": "生产食品相关产品应当符合法律、法规和食品安全国家标准。对直接接触食品的包装材料等具有较高风险的食品相关产品，按照国家有关工业产品生产许可证管理的规定实施生产许可。食品安全监督管理部门应当加强对食品相关产品生产活动的监督管理。 国家对重点液态食品道路散装运输实行许可制度。道路运输经营者从事重点液态食品散装运输，应当有符合保障食品安全要求的专用运输容器、作业人员和管理制度等，依法取得县级以上地方人民政府食品安全监督管理部门核发的准运证。 道路散装运输重点液态食品，发货方应当查验承运的道路运输经营者的准运证，核验运输容器是否符合保障食品安全的要求；收货方应当查验承运的道路运输经营者的准运证、运输记录，核验运输容器铅封是否完整；承运的道路运输经营者应当在运输容器显著位置喷涂食品专用标识，按照国家有关规定使用运输容器并及时清洗，严禁装运食品以外的其他物质。 任何单位和个人不得伪造、变造或者使用伪造、变造的重点液态食品道路散装运输记录、运输容器清洗凭证等单据。 重点液态食品道路散装运输的具体管理规定由国务院食品安全监督管理部门会同国务院有关部门制定。重点液态食品目录由国务院食品安全监督管理部门会同国务院有关部门制定、调整，报国务院批准后公布。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第四十二条", "text": "国家建立食品安全全程追溯制度。 食品生产经营者应当依照本法的规定，建立食品安全追溯体系，保证食品可追溯。国家鼓励食品生产经营者采用信息化手段采集、留存生产经营信息，建立食品安全追溯体系。 国务院食品安全监督管理部门会同国务院农业行政等有关部门建立食品安全全程追溯协作机制。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第四十三条", "text": "地方各级人民政府应当采取措施鼓励食品规模化生产和连锁经营、配送。 国家鼓励食品生产经营企业参加食品安全责任保险。 第二节 生产经营过程控制"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第四十四条", "text": "食品生产经营企业应当建立健全食品安全管理制度，对职工进行食品安全知识培训，加强食品检验工作，依法从事生产经营活动。 食品生产经营企业的主要负责人应当落实企业食品安全管理制度，对本企业的食品安全工作全面负责。 食品生产经营企业应当配备食品安全管理人员，加强对其培训和考核。经考核不具备食品安全管理能力的，不得上岗。食品安全监督管理部门应当对企业食品安全管理人员随机进行监督抽查考核并公布考核情况。监督抽查考核不得收取费用。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第四十五条", "text": "食品生产经营者应当建立并执行从业人员健康管理制度。患有国务院卫生行政部门规定的有碍食品安全疾病的人员，不得从事接触直接入口食品的工作。 从事接触直接入口食品工作的食品生产经营人员应当每年进行健康检查，取得健康证明后方可上岗工作。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第四十六条", "text": "食品生产企业应当就下列事项制定并实施控制要求，保证所生产的食品符合食品安全标准： （一）原料采购、原料验收、投料等原料控制； （二）生产工序、设备、贮存、包装等生产关键环节控制； （三）原料检验、半成品检验、成品出厂检验等检验控制； （四）运输和交付控制。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第四十七条", "text": "食品生产经营者应当建立食品安全自查制度，定期对食品安全状况进行检查评价。生产经营条件发生变化，不再符合食品安全要求的，食品生产经营者应当立即采取整改措施；有发生食品安全事故潜在风险的，应当立即停止食品生产经营活动，并向所在地县级人民政府食品安全监督管理部门报告。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第四十八条", "text": "国家鼓励食品生产经营企业符合良好生产规范要求，实施危害分析与关键控制点体系，提高食品安全管理水平。 对通过良好生产规范、危害分析与关键控制点体系认证的食品生产经营企业，认证机构应当依法实施跟踪调查；对不再符合认证要求的企业，应当依法撤销认证，及时向县级以上人民政府食品安全监督管理部门通报，并向社会公布。认证机构实施跟踪调查不得收取费用。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第四十九条", "text": "食用农产品生产者应当按照食品安全标准和国家有关规定使用农药、肥料、兽药、饲料和饲料添加剂等农业投入品，严格执行农业投入品使用安全间隔期或者休药期的规定，不得使用国家明令禁止的农业投入品。禁止将剧毒、高毒农药用于蔬菜、瓜果、茶叶和中草药材等国家规定的农作物。 食用农产品的生产企业和农民专业合作经济组织应当建立农业投入品使用记录制度。 县级以上人民政府农业行政部门应当加强对农业投入品使用的监督管理和指导，建立健全农业投入品安全使用制度。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第五十条", "text": "食品生产者采购食品原料、食品添加剂、食品相关产品，应当查验供货者的许可证和产品合格证明；对无法提供合格证明的食品原料，应当按照食品安全标准进行检验；不得采购或者使用不符合食品安全标准的食品原料、食品添加剂、食品相关产品。 食品生产企业应当建立食品原料、食品添加剂、食品相关产品进货查验记录制度，如实记录食品原料、食品添加剂、食品相关产品的名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限不得少于产品保质期满后六个月；没有明确保质期的，保存期限不得少于二年。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第五十一条", "text": "食品生产企业应当建立食品出厂检验记录制度，查验出厂食品的检验合格证和安全状况，如实记录食品的名称、规格、数量、生产日期或者生产批号、保质期、检验合格证号、销售日期以及购货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限应当符合本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第五十二条", "text": "食品、食品添加剂、食品相关产品的生产者，应当按照食品安全标准对所生产的食品、食品添加剂、食品相关产品进行检验，检验合格后方可出厂或者销售。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第五十三条", "text": "食品经营者采购食品，应当查验供货者的许可证和食品出厂检验合格证或者其他合格证明（以下称合格证明文件）。 食品经营企业应当建立食品进货查验记录制度，如实记录食品的名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限应当符合本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第五十条", "text": "第二款的规定。 实行统一配送经营方式的食品经营企业，可以由企业总部统一查验供货者的许可证和食品合格证明文件，进行食品进货查验记录。 从事食品批发业务的经营企业应当建立食品销售记录制度，如实记录批发食品的名称、规格、数量、生产日期或者生产批号、保质期、销售日期以及购货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限应当符合本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第五十四条", "text": "食品经营者应当按照保证食品安全的要求贮存食品，定期检查库存食品，及时清理变质或者超过保质期的食品。 食品经营者贮存散装食品，应当在贮存位置标明食品的名称、生产日期或者生产批号、保质期、生产者名称及联系方式等内容。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第五十五条", "text": "餐饮服务提供者应当制定并实施原料控制要求，不得采购不符合食品安全标准的食品原料。倡导餐饮服务提供者公开加工过程，公示食品原料及其来源等信息。 餐饮服务提供者在加工过程中应当检查待加工的食品及原料，发现有本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十四条", "text": "第六项规定情形的，不得加工或者使用。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第五十六条", "text": "餐饮服务提供者应当定期维护食品加工、贮存、陈列等设施、设备；定期清洗、校验保温设施及冷藏、冷冻设施。 餐饮服务提供者应当按照要求对餐具、饮具进行清洗消毒，不得使用未经清洗消毒的餐具、饮具；餐饮服务提供者委托清洗消毒餐具、饮具的，应当委托符合本法规定条件的餐具、饮具集中消毒服务单位。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第五十七条", "text": "学校、托幼机构、养老机构、建筑工地等集中用餐单位的食堂应当严格遵守法律、法规和食品安全标准；从供餐单位订餐的，应当从取得食品生产经营许可的企业订购，并按照要求对订购的食品进行查验。供餐单位应当严格遵守法律、法规和食品安全标准，当餐加工，确保食品安全。 学校、托幼机构、养老机构、建筑工地等集中用餐单位的主管部门应当加强对集中用餐单位的食品安全教育和日常管理，降低食品安全风险，及时消除食品安全隐患。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第五十八条", "text": "餐具、饮具集中消毒服务单位应当具备相应的作业场所、清洗消毒设备或者设施，用水和使用的洗涤剂、消毒剂应当符合相关食品安全国家标准和其他国家标准、卫生规范。 餐具、饮具集中消毒服务单位应当对消毒餐具、饮具进行逐批检验，检验合格后方可出厂，并应当随附消毒合格证明。消毒后的餐具、饮具应当在独立包装上标注单位名称、地址、联系方式、消毒日期以及使用期限等内容。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第五十九条", "text": "食品添加剂生产者应当建立食品添加剂出厂检验记录制度，查验出厂产品的检验合格证和安全状况，如实记录食品添加剂的名称、规格、数量、生产日期或者生产批号、保质期、检验合格证号、销售日期以及购货者名称、地址、联系方式等相关内容，并保存相关凭证。记录和凭证保存期限应当符合本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十条", "text": "食品添加剂经营者采购食品添加剂，应当依法查验供货者的许可证和产品合格证明文件，如实记录食品添加剂的名称、规格、数量、生产日期或者生产批号、保质期、进货日期以及供货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限应当符合本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十一条", "text": "集中交易市场的开办者、柜台出租者和展销会举办者，应当依法审查入场食品经营者的许可证，明确其食品安全管理责任，定期对其经营环境和条件进行检查，发现其有违反本法规定行为的，应当及时制止并立即报告所在地县级人民政府食品安全监督管理部门。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十二条", "text": "网络食品交易第三方平台提供者应当对入网食品经营者进行实名登记，明确其食品安全管理责任；依法应当取得许可证的，还应当审查其许可证。 网络食品交易第三方平台提供者发现入网食品经营者有违反本法规定行为的，应当及时制止并立即报告所在地县级人民政府食品安全监督管理部门；发现严重违法行为的，应当立即停止提供网络交易平台服务。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十三条", "text": "国家建立食品召回制度。食品生产者发现其生产的食品不符合食品安全标准或者有证据证明可能危害人体健康的，应当立即停止生产，召回已经上市销售的食品，通知相关生产经营者和消费者，并记录召回和通知情况。 食品经营者发现其经营的食品有前款规定情形的，应当立即停止经营，通知相关生产经营者和消费者，并记录停止经营和通知情况。食品生产者认为应当召回的，应当立即召回。由于食品经营者的原因造成其经营的食品有前款规定情形的，食品经营者应当召回。 食品生产经营者应当对召回的食品采取无害化处理、销毁等措施，防止其再次流入市场。但是，对因标签、标志或者说明书不符合食品安全标准而被召回的食品，食品生产者在采取补救措施且能保证食品安全的情况下可以继续销售；销售时应当向消费者明示补救措施。 食品生产经营者应当将食品召回和处理情况向所在地县级人民政府食品安全监督管理部门报告；需要对召回的食品进行无害化处理、销毁的，应当提前报告时间、地点。食品安全监督管理部门认为必要的，可以实施现场监督。 食品生产经营者未依照本条规定召回或者停止经营的，县级以上人民政府食品安全监督管理部门可以责令其召回或者停止经营。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十四条", "text": "食用农产品批发市场应当配备检验设备和检验人员或者委托符合本法规定的食品检验机构，对进入该批发市场销售的食用农产品进行抽样检验；发现不符合食品安全标准的，应当要求销售者立即停止销售，并向食品安全监督管理部门报告。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十五条", "text": "食用农产品销售者应当建立食用农产品进货查验记录制度，如实记录食用农产品的名称、数量、进货日期以及供货者名称、地址、联系方式等内容，并保存相关凭证。记录和凭证保存期限不得少于六个月。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十六条", "text": "进入市场销售的食用农产品在包装、保鲜、贮存、运输中使用保鲜剂、防腐剂等食品添加剂和包装材料等食品相关产品，应当符合食品安全国家标准。 第三节 标签、说明书和广告"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十七条", "text": "预包装食品的包装上应当有标签。标签应当标明下列事项： （一）名称、规格、净含量、生产日期； （二）成分或者配料表； （三）生产者的名称、地址、联系方式； （四）保质期； （五）产品标准代号； （六）贮存条件； （七）所使用的食品添加剂在国家标准中的通用名称； （八）生产许可证编号； （九）法律、法规或者食品安全标准规定应当标明的其他事项。 专供婴幼儿和其他特定人群的主辅食品，其标签还应当标明主要营养成分及其含量。 食品安全国家标准对标签标注事项另有规定的，从其规定。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十八条", "text": "食品经营者销售散装食品，应当在散装食品的容器、外包装上标明食品的名称、生产日期或者生产批号、保质期以及生产经营者名称、地址、联系方式等内容。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十九条", "text": "生产经营转基因食品应当按照规定显著标示。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第七十条", "text": "食品添加剂应当有标签、说明书和包装。标签、说明书应当载明本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十七条", "text": "第一款第一项至第六项、第八项、第九项规定的事项，以及食品添加剂的使用范围、用量、使用方法，并在标签上载明“食品添加剂”字样。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第七十一条", "text": "食品和食品添加剂的标签、说明书，不得含有虚假内容，不得涉及疾病预防、治疗功能。生产经营者对其提供的标签、说明书的内容负责。 食品和食品添加剂的标签、说明书应当清楚、明显，生产日期、保质期等事项应当显著标注，容易辨识。 食品和食品添加剂与其标签、说明书的内容不符的，不得上市销售。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第七十二条", "text": "食品经营者应当按照食品标签标示的警示标志、警示说明或者注意事项的要求销售食品。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第七十三条", "text": "食品广告的内容应当真实合法，不得含有虚假内容，不得涉及疾病预防、治疗功能。食品生产经营者对食品广告内容的真实性、合法性负责。 县级以上人民政府食品安全监督管理部门和其他有关部门以及食品检验机构、食品行业协会不得以广告或者其他形式向消费者推荐食品。消费者组织不得以收取费用或者其他牟取利益的方式向消费者推荐食品。 第四节 特殊食品"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第七十四条", "text": "国家对保健食品、特殊医学用途配方食品和婴幼儿配方食品等特殊食品实行严格监督管理。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第七十五条", "text": "保健食品声称保健功能，应当具有科学依据，不得对人体产生急性、亚急性或者慢性危害。 保健食品原料目录和允许保健食品声称的保健功能目录，由国务院食品安全监督管理部门会同国务院卫生行政部门、国家中医药管理部门制定、调整并公布。 保健食品原料目录应当包括原料名称、用量及其对应的功效；列入保健食品原料目录的原料只能用于保健食品生产，不得用于其他食品生产。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第七十六条", "text": "使用保健食品原料目录以外原料的保健食品和首次进口的保健食品应当经国务院食品安全监督管理部门注册。但是，首次进口的保健食品中属于补充维生素、矿物质等营养物质的，应当报国务院食品安全监督管理部门备案。其他保健食品应当报省、自治区、直辖市人民政府食品安全监督管理部门备案。 进口的保健食品应当是出口国（地区）主管部门准许上市销售的产品。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第七十七条", "text": "依法应当注册的保健食品，注册时应当提交保健食品的研发报告、产品配方、生产工艺、安全性和保健功能评价、标签、说明书等材料及样品，并提供相关证明文件。国务院食品安全监督管理部门经组织技术审评，对符合安全和功能声称要求的，准予注册；对不符合要求的，不予注册并书面说明理由。对使用保健食品原料目录以外原料的保健食品作出准予注册决定的，应当及时将该原料纳入保健食品原料目录。 依法应当备案的保健食品，备案时应当提交产品配方、生产工艺、标签、说明书以及表明产品安全性和保健功能的材料。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第七十八条", "text": "保健食品的标签、说明书不得涉及疾病预防、治疗功能，内容应当真实，与注册或者备案的内容相一致，载明适宜人群、不适宜人群、功效成分或者标志性成分及其含量等，并声明“本品不能代替药物”。保健食品的功能和成分应当与标签、说明书相一致。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第七十九条", "text": "保健食品广告除应当符合本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第七十三条", "text": "第一款的规定外，还应当声明“本品不能代替药物”；其内容应当经生产企业所在地省、自治区、直辖市人民政府食品安全监督管理部门审查批准，取得保健食品广告批准文件。省、自治区、直辖市人民政府食品安全监督管理部门应当公布并及时更新已经批准的保健食品广告目录以及批准的广告内容。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第八十条", "text": "特殊医学用途配方食品应当经国务院食品安全监督管理部门注册。注册时，应当提交产品配方、生产工艺、标签、说明书以及表明产品安全性、营养充足性和特殊医学用途临床效果的材料。 特殊医学用途配方食品广告适用《中华人民共和国广告法》和其他法律、行政法规关于药品广告管理的规定。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第八十一条", "text": "婴幼儿配方食品生产企业应当实施从原料进厂到成品出厂的全过程质量控制，对出厂的婴幼儿配方食品实施逐批检验，保证食品安全。 生产婴幼儿配方食品使用的生鲜乳、辅料等食品原料、食品添加剂等，应当符合法律、行政法规的规定和食品安全国家标准，保证婴幼儿生长发育所需的营养成分。 婴幼儿配方食品生产企业应当将食品原料、食品添加剂、产品配方及标签等事项向省、自治区、直辖市人民政府食品安全监督管理部门备案。 婴幼儿配方乳粉、婴幼儿配方液态乳的产品配方应当经国务院食品安全监督管理部门注册。注册时，应当提交配方研发报告和其他表明配方科学性、安全性的材料。 不得以分装方式生产婴幼儿配方乳粉、婴幼儿配方液态乳，同一企业不得用同一配方生产不同品牌的婴幼儿配方乳粉、婴幼儿配方液态乳。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第八十二条", "text": "保健食品、特殊医学用途配方食品、婴幼儿配方乳粉、婴幼儿配方液态乳的注册人或者备案人应当对其提交材料的真实性负责。 省级以上人民政府食品安全监督管理部门应当及时公布注册或者备案的保健食品、特殊医学用途配方食品、婴幼儿配方乳粉、婴幼儿配方液态乳目录，并对注册或者备案中获知的企业商业秘密予以保密。 保健食品、特殊医学用途配方食品、婴幼儿配方乳粉、婴幼儿配方液态乳生产企业应当按照注册或者备案的产品配方、生产工艺等技术要求组织生产。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第八十三条", "text": "生产保健食品，特殊医学用途配方食品、婴幼儿配方食品和其他专供特定人群的主辅食品的企业，应当按照良好生产规范的要求建立与所生产食品相适应的生产质量管理体系，定期对该体系的运行情况进行自查，保证其有效运行，并向所在地县级人民政府食品安全监督管理部门提交自查报告。 第五章 食品检验"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第八十四条", "text": "食品检验机构按照国家有关认证认可的规定取得资质认定后，方可从事食品检验活动。但是，法律另有规定的除外。 食品检验机构的资质认定条件和检验规范，由国务院食品安全监督管理部门规定。 符合本法规定的食品检验机构出具的检验报告具有同等效力。 县级以上人民政府应当整合食品检验资源，实现资源共享。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第八十五条", "text": "食品检验由食品检验机构指定的检验人独立进行。 检验人应当依照有关法律、法规的规定，并按照食品安全标准和检验规范对食品进行检验，尊重科学，恪守职业道德，保证出具的检验数据和结论客观、公正，不得出具虚假检验报告。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第八十六条", "text": "食品检验实行食品检验机构与检验人负责制。食品检验报告应当加盖食品检验机构公章，并有检验人的签名或者盖章。食品检验机构和检验人对出具的食品检验报告负责。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第八十七条", "text": "县级以上人民政府食品安全监督管理部门应当对食品进行定期或者不定期的抽样检验，并依据有关规定公布检验结果，不得免检。进行抽样检验，应当购买抽取的样品，委托符合本法规定的食品检验机构进行检验，并支付相关费用；不得向食品生产经营者收取检验费和其他费用。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第八十八条", "text": "对依照本法规定实施的检验结论有异议的，食品生产经营者可以自收到检验结论之日起七个工作日内向实施抽样检验的食品安全监督管理部门或者其上一级食品安全监督管理部门提出复检申请，由受理复检申请的食品安全监督管理部门在公布的复检机构名录中随机确定复检机构进行复检。复检机构出具的复检结论为最终检验结论。复检机构与初检机构不得为同一机构。复检机构名录由国务院认证认可监督管理、食品安全监督管理、卫生行政、农业行政等部门共同公布。 采用国家规定的快速检测方法对食用农产品进行抽查检测，被抽查人对检测结果有异议的，可以自收到检测结果时起四小时内申请复检。复检不得采用快速检测方法。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第八十九条", "text": "食品生产企业可以自行对所生产的食品进行检验，也可以委托符合本法规定的食品检验机构进行检验。 食品行业协会和消费者协会等组织、消费者需要委托食品检验机构对食品进行检验的，应当委托符合本法规定的食品检验机构进行。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第九十条", "text": "食品添加剂的检验，适用本法有关食品检验的规定。 第六章 食品进出口"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第九十一条", "text": "国家出入境检验检疫部门对进出口食品安全实施监督管理。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第九十二条", "text": "进口的食品、食品添加剂、食品相关产品应当符合我国食品安全国家标准。 进口的食品、食品添加剂应当经出入境检验检疫机构依照进出口商品检验相关法律、行政法规的规定检验合格。 进口的食品、食品添加剂应当按照国家出入境检验检疫部门的要求随附合格证明材料。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第九十三条", "text": "进口尚无食品安全国家标准的食品，由境外出口商、境外生产企业或者其委托的进口商向国务院卫生行政部门提交所执行的相关国家（地区）标准或者国际标准。国务院卫生行政部门对相关标准进行审查，认为符合食品安全要求的，决定暂予适用，并及时制定相应的食品安全国家标准。进口利用新的食品原料生产的食品或者进口食品添加剂新品种、食品相关产品新品种，依照本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第三十七条", "text": "的规定办理。 出入境检验检疫机构按照国务院卫生行政部门的要求，对前款规定的食品、食品添加剂、食品相关产品进行检验。检验结果应当公开。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第九十四条", "text": "境外出口商、境外生产企业应当保证向我国出口的食品、食品添加剂、食品相关产品符合本法以及我国其他有关法律、行政法规的规定和食品安全国家标准的要求，并对标签、说明书的内容负责。 进口商应当建立境外出口商、境外生产企业审核制度，重点审核前款规定的内容；审核不合格的，不得进口。 发现进口食品不符合我国食品安全国家标准或者有证据证明可能危害人体健康的，进口商应当立即停止进口，并依照本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第九十五条", "text": "境外发生的食品安全事件可能对我国境内造成影响，或者在进口食品、食品添加剂、食品相关产品中发现严重食品安全问题的，国家出入境检验检疫部门应当及时采取风险预警或者控制措施，并向国务院食品安全监督管理、卫生行政、农业行政部门通报。接到通报的部门应当及时采取相应措施。 县级以上人民政府食品安全监督管理部门对国内市场上销售的进口食品、食品添加剂实施监督管理。发现存在严重食品安全问题的，国务院食品安全监督管理部门应当及时向国家出入境检验检疫部门通报。国家出入境检验检疫部门应当及时采取相应措施。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第九十六条", "text": "向我国境内出口食品的境外出口商或者代理商、进口食品的进口商应当向国家出入境检验检疫部门备案。向我国境内出口食品的境外食品生产企业应当经国家出入境检验检疫部门注册。已经注册的境外食品生产企业提供虚假材料，或者因其自身的原因致使进口食品发生重大食品安全事故的，国家出入境检验检疫部门应当撤销注册并公告。 国家出入境检验检疫部门应当定期公布已经备案的境外出口商、代理商、进口商和已经注册的境外食品生产企业名单。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第九十七条", "text": "进口的预包装食品、食品添加剂应当有中文标签；依法应当有说明书的，还应当有中文说明书。标签、说明书应当符合本法以及我国其他有关法律、行政法规的规定和食品安全国家标准的要求，并载明食品的原产地以及境内代理商的名称、地址、联系方式。预包装食品没有中文标签、中文说明书或者标签、说明书不符合本条规定的，不得进口。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第九十八条", "text": "进口商应当建立食品、食品添加剂进口和销售记录制度，如实记录食品、食品添加剂的名称、规格、数量、生产日期、生产或者进口批号、保质期、境外出口商和购货者名称、地址及联系方式、交货日期等内容，并保存相关凭证。记录和凭证保存期限应当符合本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第九十九条", "text": "出口食品生产企业应当保证其出口食品符合进口国（地区）的标准或者合同要求。 出口食品生产企业和出口食品原料种植、养殖场应当向国家出入境检验检疫部门备案。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百条", "text": "国家出入境检验检疫部门应当收集、汇总下列进出口食品安全信息，并及时通报相关部门、机构和企业： （一）出入境检验检疫机构对进出口食品实施检验检疫发现的食品安全信息； （二）食品行业协会和消费者协会等组织、消费者反映的进口食品安全信息； （三）国际组织、境外政府机构发布的风险预警信息及其他食品安全信息，以及境外食品行业协会等组织、消费者反映的食品安全信息； （四）其他食品安全信息。 国家出入境检验检疫部门应当对进出口食品的进口商、出口商和出口食品生产企业实施信用管理，建立信用记录，并依法向社会公布。对有不良记录的进口商、出口商和出口食品生产企业，应当加强对其进出口食品的检验检疫。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百零一条", "text": "国家出入境检验检疫部门可以对向我国境内出口食品的国家（地区）的食品安全管理体系和食品安全状况进行评估和审查，并根据评估和审查结果，确定相应检验检疫要求。 第七章 食品安全事故处置"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百零二条", "text": "国务院组织制定国家食品安全事故应急预案。 县级以上地方人民政府应当根据有关法律、法规的规定和上级人民政府的食品安全事故应急预案以及本行政区域的实际情况，制定本行政区域的食品安全事故应急预案，并报上一级人民政府备案。 食品安全事故应急预案应当对食品安全事故分级、事故处置组织指挥体系与职责、预防预警机制、处置程序、应急保障措施等作出规定。 食品生产经营企业应当制定食品安全事故处置方案，定期检查本企业各项食品安全防范措施的落实情况，及时消除事故隐患。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百零三条", "text": "发生食品安全事故的单位应当立即采取措施，防止事故扩大。事故单位和接收病人进行治疗的单位应当及时向事故发生地县级人民政府食品安全监督管理、卫生行政部门报告。 县级以上人民政府农业行政等部门在日常监督管理中发现食品安全事故或者接到事故举报，应当立即向同级食品安全监督管理部门通报。 发生食品安全事故，接到报告的县级人民政府食品安全监督管理部门应当按照应急预案的规定向本级人民政府和上级人民政府食品安全监督管理部门报告。县级人民政府和上级人民政府食品安全监督管理部门应当按照应急预案的规定上报。 任何单位和个人不得对食品安全事故隐瞒、谎报、缓报，不得隐匿、伪造、毁灭有关证据。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百零四条", "text": "医疗机构发现其接收的病人属于食源性疾病病人或者疑似病人的，应当按照规定及时将相关信息向所在地县级人民政府卫生行政部门报告。县级人民政府卫生行政部门认为与食品安全有关的，应当及时通报同级食品安全监督管理部门。 县级以上人民政府卫生行政部门在调查处理传染病或者其他突发公共卫生事件中发现与食品安全相关的信息，应当及时通报同级食品安全监督管理部门。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百零五条", "text": "县级以上人民政府食品安全监督管理部门接到食品安全事故的报告后，应当立即会同同级卫生行政、农业行政等部门进行调查处理，并采取下列措施，防止或者减轻社会危害： （一）开展应急救援工作，组织救治因食品安全事故导致人身伤害的人员； （二）封存可能导致食品安全事故的食品及其原料，并立即进行检验；对确认属于被污染的食品及其原料，责令食品生产经营者依照本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十三条", "text": "的规定召回或者停止经营； （三）封存被污染的食品相关产品，并责令进行清洗消毒； （四）做好信息发布工作，依法对食品安全事故及其处理情况进行发布，并对可能产生的危害加以解释、说明。 发生食品安全事故需要启动应急预案的，县级以上人民政府应当立即成立事故处置指挥机构，启动应急预案，依照前款和应急预案的规定进行处置。 发生食品安全事故，县级以上疾病预防控制机构应当对事故现场进行卫生处理，并对与事故有关的因素开展流行病学调查，有关部门应当予以协助。县级以上疾病预防控制机构应当向同级食品安全监督管理、卫生行政部门提交流行病学调查报告。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百零六条", "text": "发生食品安全事故，设区的市级以上人民政府食品安全监督管理部门应当立即会同有关部门进行事故责任调查，督促有关部门履行职责，向本级人民政府和上一级人民政府食品安全监督管理部门提出事故责任调查处理报告。 涉及两个以上省、自治区、直辖市的重大食品安全事故由国务院食品安全监督管理部门依照前款规定组织事故责任调查。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百零七条", "text": "调查食品安全事故，应当坚持实事求是、尊重科学的原则，及时、准确查清事故性质和原因，认定事故责任，提出整改措施。 调查食品安全事故，除了查明事故单位的责任，还应当查明有关监督管理部门、食品检验机构、认证机构及其工作人员的责任。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百零八条", "text": "食品安全事故调查部门有权向有关单位和个人了解与事故有关的情况，并要求提供相关资料和样品。有关单位和个人应当予以配合，按照要求提供相关资料和样品，不得拒绝。 任何单位和个人不得阻挠、干涉食品安全事故的调查处理。 第八章 监督管理"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百零九条", "text": "县级以上人民政府食品安全监督管理部门根据食品安全风险监测、风险评估结果和食品安全状况等，确定监督管理的重点、方式和频次，实施风险分级管理。 县级以上地方人民政府组织本级食品安全监督管理、农业行政等部门制定本行政区域的食品安全年度监督管理计划，向社会公布并组织实施。 食品安全年度监督管理计划应当将下列事项作为监督管理的重点： （一）专供婴幼儿和其他特定人群的主辅食品； （二）保健食品生产过程中的添加行为和按照注册或者备案的技术要求组织生产的情况，保健食品标签、说明书以及宣传材料中有关功能宣传的情况； （三）发生食品安全事故风险较高的食品生产经营者； （四）食品安全风险监测结果表明可能存在食品安全隐患的事项。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百一十条", "text": "县级以上人民政府食品安全监督管理部门履行食品安全监督管理职责，有权采取下列措施，对生产经营者遵守本法的情况进行监督检查： （一）进入生产经营场所实施现场检查； （二）对生产经营的食品、食品添加剂、食品相关产品进行抽样检验； （三）查阅、复制有关合同、票据、账簿以及其他有关资料； （四）查封、扣押有证据证明不符合食品安全标准或者有证据证明存在安全隐患以及用于违法生产经营的食品、食品添加剂、食品相关产品； （五）查封违法从事生产经营活动的场所。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百一十一条", "text": "对食品安全风险评估结果证明食品存在安全隐患，需要制定、修订食品安全标准的，在制定、修订食品安全标准前，国务院卫生行政部门应当及时会同国务院有关部门规定食品中有害物质的临时限量值和临时检验方法，作为生产经营和监督管理的依据。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百一十二条", "text": "县级以上人民政府食品安全监督管理部门在食品安全监督管理工作中可以采用国家规定的快速检测方法对食品进行抽查检测。 对抽查检测结果表明可能不符合食品安全标准的食品，应当依照本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第八十七条", "text": "的规定进行检验。抽查检测结果确定有关食品不符合食品安全标准的，可以作为行政处罚的依据。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百一十三条", "text": "县级以上人民政府食品安全监督管理部门应当建立食品生产经营者食品安全信用档案，记录许可颁发、日常监督检查结果、违法行为查处等情况，依法向社会公布并实时更新；对有不良信用记录的食品生产经营者增加监督检查频次，对违法行为情节严重的食品生产经营者，可以通报投资主管部门、证券监督管理机构和有关的金融机构。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百一十四条", "text": "食品生产经营过程中存在食品安全隐患，未及时采取措施消除的，县级以上人民政府食品安全监督管理部门可以对食品生产经营者的法定代表人或者主要负责人进行责任约谈。食品生产经营者应当立即采取措施，进行整改，消除隐患。责任约谈情况和整改情况应当纳入食品生产经营者食品安全信用档案。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百一十五条", "text": "县级以上人民政府食品安全监督管理等部门应当公布本部门的电子邮件地址或者电话，接受咨询、投诉、举报。接到咨询、投诉、举报，对属于本部门职责的，应当受理并在法定期限内及时答复、核实、处理；对不属于本部门职责的，应当移交有权处理的部门并书面通知咨询、投诉、举报人。有权处理的部门应当在法定期限内及时处理，不得推诿。对查证属实的举报，给予举报人奖励。 有关部门应当对举报人的信息予以保密，保护举报人的合法权益。举报人举报所在企业的，该企业不得以解除、变更劳动合同或者其他方式对举报人进行打击报复。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百一十六条", "text": "县级以上人民政府食品安全监督管理等部门应当加强对执法人员食品安全法律、法规、标准和专业知识与执法能力等的培训，并组织考核。不具备相应知识和能力的，不得从事食品安全执法工作。 食品生产经营者、食品行业协会、消费者协会等发现食品安全执法人员在执法过程中有违反法律、法规规定的行为以及不规范执法行为的，可以向本级或者上级人民政府食品安全监督管理等部门或者监察机关投诉、举报。接到投诉、举报的部门或者机关应当进行核实，并将经核实的情况向食品安全执法人员所在部门通报；涉嫌违法违纪的，按照本法和有关规定处理。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百一十七条", "text": "县级以上人民政府食品安全监督管理等部门未及时发现食品安全系统性风险，未及时消除监督管理区域内的食品安全隐患的，本级人民政府可以对其主要负责人进行责任约谈。 地方人民政府未履行食品安全职责，未及时消除区域性重大食品安全隐患的，上级人民政府可以对其主要负责人进行责任约谈。 被约谈的食品安全监督管理等部门、地方人民政府应当立即采取措施，对食品安全监督管理工作进行整改。 责任约谈情况和整改情况应当纳入地方人民政府和有关部门食品安全监督管理工作评议、考核记录。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百一十八条", "text": "国家建立统一的食品安全信息平台，实行食品安全信息统一公布制度。国家食品安全总体情况、食品安全风险警示信息、重大食品安全事故及其调查处理信息和国务院确定需要统一公布的其他信息由国务院食品安全监督管理部门统一公布。食品安全风险警示信息和重大食品安全事故及其调查处理信息的影响限于特定区域的，也可以由有关省、自治区、直辖市人民政府食品安全监督管理部门公布。未经授权不得发布上述信息。 县级以上人民政府食品安全监督管理、农业行政部门依据各自职责公布食品安全日常监督管理信息。 公布食品安全信息，应当做到准确、及时，并进行必要的解释说明，避免误导消费者和社会舆论。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百一十九条", "text": "县级以上地方人民政府食品安全监督管理、卫生行政、农业行政部门获知本法规定需要统一公布的信息，应当向上级主管部门报告，由上级主管部门立即报告国务院食品安全监督管理部门；必要时，可以直接向国务院食品安全监督管理部门报告。 县级以上人民政府食品安全监督管理、卫生行政、农业行政部门应当相互通报获知的食品安全信息。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十条", "text": "任何单位和个人不得编造、散布虚假食品安全信息。 县级以上人民政府食品安全监督管理部门发现可能误导消费者和社会舆论的食品安全信息，应当立即组织有关部门、专业机构、相关食品生产经营者等进行核实、分析，并及时公布结果。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十一条", "text": "县级以上人民政府食品安全监督管理等部门发现涉嫌食品安全犯罪的，应当按照有关规定及时将案件移送公安机关。对移送的案件，公安机关应当及时审查；认为有犯罪事实需要追究刑事责任的，应当立案侦查。 公安机关在食品安全犯罪案件侦查过程中认为没有犯罪事实，或者犯罪事实显著轻微，不需要追究刑事责任，但依法应当追究行政责任的，应当及时将案件移送食品安全监督管理等部门和监察机关，有关部门应当依法处理。 公安机关商请食品安全监督管理、生态环境等部门提供检验结论、认定意见以及对涉案物品进行无害化处理等协助的，有关部门应当及时提供，予以协助。 第九章 法律责任"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十二条", "text": "违反本法规定，未取得食品生产经营许可从事食品生产经营活动，或者未取得食品添加剂生产许可从事食品添加剂生产活动的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品、食品添加剂以及用于违法生产经营的工具、设备、原料等物品；违法生产经营的食品、食品添加剂货值金额不足一万元的，并处五万元以上十万元以下罚款；货值金额一万元以上的，并处货值金额十倍以上二十倍以下罚款。 明知从事前款规定的违法行为，仍为其提供生产经营场所或者其他条件的，由县级以上人民政府食品安全监督管理部门责令停止违法行为，没收违法所得，并处五万元以上十万元以下罚款；使消费者的合法权益受到损害的，应当与食品、食品添加剂生产经营者承担连带责任。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十三条", "text": "违反本法规定，有下列情形之一，尚不构成犯罪的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品，并可以没收用于违法生产经营的工具、设备、原料等物品；违法生产经营的食品货值金额不足一万元的，并处十万元以上十五万元以下罚款；货值金额一万元以上的，并处货值金额十五倍以上三十倍以下罚款；情节严重的，吊销许可证，并可以由公安机关对其直接负责的主管人员和其他直接责任人员处五日以上十五日以下拘留： （一）用非食品原料生产食品、在食品中添加食品添加剂以外的化学物质和其他可能危害人体健康的物质，或者用回收食品作为原料生产食品，或者经营上述食品； （二）生产经营营养成分不符合食品安全标准的专供婴幼儿和其他特定人群的主辅食品； （三）经营病死、毒死或者死因不明的禽、畜、兽、水产动物肉类，或者生产经营其制品； （四）经营未按规定进行检疫或者检疫不合格的肉类，或者生产经营未经检验或者检验不合格的肉类制品； （五）生产经营国家为防病等特殊需要明令禁止生产经营的食品； （六）生产经营添加药品的食品。 明知从事前款规定的违法行为，仍为其提供生产经营场所或者其他条件的，由县级以上人民政府食品安全监督管理部门责令停止违法行为，没收违法所得，并处十万元以上二十万元以下罚款；使消费者的合法权益受到损害的，应当与食品生产经营者承担连带责任。 违法使用剧毒、高毒农药的，除依照有关法律、法规规定给予处罚外，可以由公安机关依照第一款规定给予拘留。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十四条", "text": "违反本法规定，有下列情形之一，尚不构成犯罪的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品、食品添加剂，并可以没收用于违法生产经营的工具、设备、原料等物品；违法生产经营的食品、食品添加剂货值金额不足一万元的，并处五万元以上十万元以下罚款；货值金额一万元以上的，并处货值金额十倍以上二十倍以下罚款；情节严重的，吊销许可证： （一）生产经营致病性微生物，农药残留、兽药残留、生物毒素、重金属等污染物质以及其他危害人体健康的物质含量超过食品安全标准限量的食品、食品添加剂； （二）用超过保质期的食品原料、食品添加剂生产食品、食品添加剂，或者经营上述食品、食品添加剂； （三）生产经营超范围、超限量使用食品添加剂的食品； （四）生产经营腐败变质、油脂酸败、霉变生虫、污秽不洁、混有异物、掺假掺杂或者感官性状异常的食品、食品添加剂； （五）生产经营标注虚假生产日期、保质期或者超过保质期的食品、食品添加剂； （六）生产经营未按规定注册的保健食品、特殊医学用途配方食品、婴幼儿配方乳粉、婴幼儿配方液态乳，或者未按注册的产品配方、生产工艺等技术要求组织生产； （七）以分装方式生产婴幼儿配方乳粉、婴幼儿配方液态乳，或者同一企业以同一配方生产不同品牌的婴幼儿配方乳粉、婴幼儿配方液态乳； （八）利用新的食品原料生产食品，或者生产食品添加剂新品种，未通过安全性评估； （九）食品生产经营者在食品安全监督管理部门责令其召回或者停止经营后，仍拒不召回或者停止经营。 除前款和本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十五条", "text": "规定的情形外，生产经营不符合法律、法规或者食品安全标准的食品、食品添加剂的，依照前款规定给予处罚。 生产食品相关产品新品种，未通过安全性评估，或者生产不符合食品安全标准的食品相关产品的，由县级以上人民政府食品安全监督管理部门依照第一款规定给予处罚。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十五条", "text": "违反本法规定，有下列情形之一的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法生产经营的食品、食品添加剂，并可以没收用于违法生产经营的工具、设备、原料等物品；违法生产经营的食品、食品添加剂货值金额不足一万元的，并处五千元以上五万元以下罚款；货值金额一万元以上的，并处货值金额五倍以上十倍以下罚款；情节严重的，责令停产停业，直至吊销许可证： （一）生产经营被包装材料、容器、运输工具等污染的食品、食品添加剂； （二）生产经营无标签的预包装食品、食品添加剂或者标签、说明书不符合本法规定的食品、食品添加剂； （三）生产经营转基因食品未按规定进行标示； （四）食品生产经营者采购或者使用不符合食品安全标准的食品原料、食品添加剂、食品相关产品。 生产经营的食品、食品添加剂的标签、说明书存在瑕疵但不影响食品安全且不会对消费者造成误导的，由县级以上人民政府食品安全监督管理部门责令改正；拒不改正的，处二千元以下罚款。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十六条", "text": "违反本法规定，有下列情形之一的，由县级以上人民政府食品安全监督管理部门责令改正，给予警告；拒不改正的，处五千元以上五万元以下罚款；情节严重的，责令停产停业，直至吊销许可证： （一）食品、食品添加剂生产者未按规定对采购的食品原料和生产的食品、食品添加剂进行检验； （二）食品生产经营企业未按规定建立食品安全管理制度，或者未按规定配备或者培训、考核食品安全管理人员； （三）食品、食品添加剂生产经营者进货时未查验许可证和相关证明文件，或者未按规定建立并遵守进货查验记录、出厂检验记录和销售记录制度； （四）食品生产经营企业未制定食品安全事故处置方案； （五）餐具、饮具和盛放直接入口食品的容器，使用前未经洗净、消毒或者清洗消毒不合格，或者餐饮服务设施、设备未按规定定期维护、清洗、校验； （六）食品生产经营者安排未取得健康证明或者患有国务院卫生行政部门规定的有碍食品安全疾病的人员从事接触直接入口食品的工作； （七）食品经营者未按规定要求销售食品； （八）保健食品生产企业未按规定向食品安全监督管理部门备案，或者未按备案的产品配方、生产工艺等技术要求组织生产； （九）婴幼儿配方食品生产企业未将食品原料、食品添加剂、产品配方、标签等向食品安全监督管理部门备案； （十）特殊食品生产企业未按规定建立生产质量管理体系并有效运行，或者未定期提交自查报告； （十一）食品生产经营者未定期对食品安全状况进行检查评价，或者生产经营条件发生变化，未按规定处理； （十二）学校、托幼机构、养老机构、建筑工地等集中用餐单位未按规定履行食品安全管理责任； （十三）食品生产企业、餐饮服务提供者未按规定制定、实施生产经营过程控制要求。 餐具、饮具集中消毒服务单位违反本法规定用水，使用洗涤剂、消毒剂，或者出厂的餐具、饮具未按规定检验合格并随附消毒合格证明，或者未按规定在独立包装上标注相关内容的，由县级以上人民政府卫生行政部门依照前款规定给予处罚。 食品相关产品生产者未按规定对生产的食品相关产品进行检验的，由县级以上人民政府食品安全监督管理部门依照第一款规定给予处罚。 食用农产品销售者违反本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十五条", "text": "规定的，由县级以上人民政府食品安全监督管理部门依照第一款规定给予处罚。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十七条", "text": "对食品生产加工小作坊、食品摊贩等的违法行为的处罚，依照省、自治区、直辖市制定的具体管理办法执行。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十八条", "text": "违反本法规定，事故单位在发生食品安全事故后未进行处置、报告的，由有关主管部门按照各自职责分工责令改正，给予警告；隐匿、伪造、毁灭有关证据的，责令停产停业，没收违法所得，并处十万元以上五十万元以下罚款；造成严重后果的，吊销许可证。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十九条", "text": "违反本法规定，有下列情形之一的，由出入境检验检疫机构依照本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十四条", "text": "的规定给予处罚： （一）提供虚假材料，进口不符合我国食品安全国家标准的食品、食品添加剂、食品相关产品； （二）进口尚无食品安全国家标准的食品，未提交所执行的标准并经国务院卫生行政部门审查，或者进口利用新的食品原料生产的食品或者进口食品添加剂新品种、食品相关产品新品种，未通过安全性评估； （三）未遵守本法的规定出口食品； （四）进口商在有关主管部门责令其依照本法规定召回进口的食品后，仍拒不召回。 违反本法规定，进口商未建立并遵守食品、食品添加剂进口和销售记录制度、境外出口商或者生产企业审核制度的，由出入境检验检疫机构依照本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百二十六条", "text": "的规定给予处罚。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百三十条", "text": "违反本法规定，集中交易市场的开办者、柜台出租者、展销会的举办者允许未依法取得许可的食品经营者进入市场销售食品，或者未履行检查、报告等义务的，由县级以上人民政府食品安全监督管理部门责令改正，没收违法所得，并处五万元以上二十万元以下罚款；造成严重后果的，责令停业，直至由原发证部门吊销许可证；使消费者的合法权益受到损害的，应当与食品经营者承担连带责任。 食用农产品批发市场违反本法"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第六十四条", "text": "规定的，依照前款规定承担责任。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百三十一条", "text": "违反本法规定，网络食品交易第三方平台提供者未对入网食品经营者进行实名登记、审查许可证，或者未履行报告、停止提供网络交易平台服务等义务的，由县级以上人民政府食品安全监督管理部门责令改正，没收违法所得，并处五万元以上二十万元以下罚款；造成严重后果的，责令停业，直至由原发证部门吊销许可证；使消费者的合法权益受到损害的，应当与食品经营者承担连带责任。 消费者通过网络食品交易第三方平台购买食品，其合法权益受到损害的，可以向入网食品经营者或者食品生产者要求赔偿。网络食品交易第三方平台提供者不能提供入网食品经营者的真实名称、地址和有效联系方式的，由网络食品交易第三方平台提供者赔偿。网络食品交易第三方平台提供者赔偿后，有权向入网食品经营者或者食品生产者追偿。网络食品交易第三方平台提供者作出更有利于消费者承诺的，应当履行其承诺。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百三十二条", "text": "违反本法规定，未按要求进行食品贮存、运输和装卸的，由县级以上人民政府食品安全监督管理等部门按照各自职责分工责令改正，给予警告；拒不改正的，责令停产停业，并处一万元以上五万元以下罚款；情节严重的，吊销许可证。 违反本法规定，道路运输经营者未按要求进行重点液态食品散装运输的，依照前款规定给予处罚；情节严重的，除吊销许可证外，还应当处五万元以上五十万元以下罚款。 违反本法规定，未取得准运证从事重点液态食品道路散装运输的，由县级以上人民政府食品安全监督管理部门责令停止重点液态食品道路散装运输经营，没收违法所得，并处五万元以上五十万元以下罚款。 违反本法规定，伪造、变造或者使用伪造、变造的重点液态食品道路散装运输记录、运输容器清洗凭证等单据，或者未履行重点液态食品道路散装运输相关查验、核验义务的，由县级以上人民政府食品安全监督管理等部门按照各自职责分工责令改正，给予警告；拒不改正的，处一万元以上十万元以下罚款。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百三十三条", "text": "违反本法规定，拒绝、阻挠、干涉有关部门、机构及其工作人员依法开展食品安全监督检查、事故调查处理、风险监测和风险评估的，由有关主管部门按照各自职责分工责令停产停业，并处二千元以上五万元以下罚款；情节严重的，吊销许可证；构成违反治安管理行为的，由公安机关依法给予治安管理处罚。 违反本法规定，对举报人以解除、变更劳动合同或者其他方式打击报复的，应当依照有关法律的规定承担责任。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百三十四条", "text": "食品生产经营者在一年内累计三次因违反本法规定受到责令停产停业、吊销许可证以外处罚的，由食品安全监督管理部门责令停产停业，直至吊销许可证。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百三十五条", "text": "被吊销许可证的食品生产经营者及其法定代表人、直接负责的主管人员和其他直接责任人员自处罚决定作出之日起五年内不得申请食品生产经营许可，或者从事食品生产经营管理工作、担任食品生产经营企业食品安全管理人员。 因食品安全犯罪被判处有期徒刑以上刑罚的，终身不得从事食品生产经营管理工作，也不得担任食品生产经营企业食品安全管理人员。 食品生产经营者聘用人员违反前两款规定的，由县级以上人民政府食品安全监督管理部门吊销许可证。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百三十六条", "text": "食品经营者履行了本法规定的进货查验等义务，有充分证据证明其不知道所采购的食品不符合食品安全标准，并能如实说明其进货来源的，可以免予处罚，但应当依法没收其不符合食品安全标准的食品；造成人身、财产或者其他损害的，依法承担赔偿责任。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百三十七条", "text": "违反本法规定，承担食品安全风险监测、风险评估工作的技术机构、技术人员提供虚假监测、评估信息的，依法对技术机构直接负责的主管人员和技术人员给予撤职、开除处分；有执业资格的，由授予其资格的主管部门吊销执业证书。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百三十八条", "text": "违反本法规定，食品检验机构、食品检验人员出具虚假检验报告的，由授予其资质的主管部门或者机构撤销该食品检验机构的检验资质，没收所收取的检验费用，并处检验费用五倍以上十倍以下罚款，检验费用不足一万元的，并处五万元以上十万元以下罚款；依法对食品检验机构直接负责的主管人员和食品检验人员给予撤职或者开除处分；导致发生重大食品安全事故的，对直接负责的主管人员和食品检验人员给予开除处分。 违反本法规定，受到开除处分的食品检验机构人员，自处分决定作出之日起十年内不得从事食品检验工作；因食品安全违法行为受到刑事处罚或者因出具虚假检验报告导致发生重大食品安全事故受到开除处分的食品检验机构人员，终身不得从事食品检验工作。食品检验机构聘用不得从事食品检验工作的人员的，由授予其资质的主管部门或者机构撤销该食品检验机构的检验资质。 食品检验机构出具虚假检验报告，使消费者的合法权益受到损害的，应当与食品生产经营者承担连带责任。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百三十九条", "text": "违反本法规定，认证机构出具虚假认证结论，由认证认可监督管理部门没收所收取的认证费用，并处认证费用五倍以上十倍以下罚款，认证费用不足一万元的，并处五万元以上十万元以下罚款；情节严重的，责令停业，直至撤销认证机构批准文件，并向社会公布；对直接负责的主管人员和负有直接责任的认证人员，撤销其执业资格。 认证机构出具虚假认证结论，使消费者的合法权益受到损害的，应当与食品生产经营者承担连带责任。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百四十条", "text": "违反本法规定，在广告中对食品作虚假宣传，欺骗消费者，或者发布未取得批准文件、广告内容与批准文件不一致的保健食品广告的，依照《中华人民共和国广告法》的规定给予处罚。 广告经营者、发布者设计、制作、发布虚假食品广告，使消费者的合法权益受到损害的，应当与食品生产经营者承担连带责任。 社会团体或者其他组织、个人在虚假广告或者其他虚假宣传中向消费者推荐食品，使消费者的合法权益受到损害的，应当与食品生产经营者承担连带责任。 违反本法规定，食品安全监督管理等部门、食品检验机构、食品行业协会以广告或者其他形式向消费者推荐食品，消费者组织以收取费用或者其他牟取利益的方式向消费者推荐食品的，由有关主管部门没收违法所得，依法对直接负责的主管人员和其他直接责任人员给予记大过、降级或者撤职处分；情节严重的，给予开除处分。 对食品作虚假宣传且情节严重的，由省级以上人民政府食品安全监督管理部门决定暂停销售该食品，并向社会公布；仍然销售该食品的，由县级以上人民政府食品安全监督管理部门没收违法所得和违法销售的食品，并处二万元以上五万元以下罚款。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百四十一条", "text": "违反本法规定，编造、散布虚假食品安全信息，构成违反治安管理行为的，由公安机关依法给予治安管理处罚。 媒体编造、散布虚假食品安全信息的，由有关主管部门依法给予处罚，并对直接负责的主管人员和其他直接责任人员给予处分；使公民、法人或者其他组织的合法权益受到损害的，依法承担消除影响、恢复名誉、赔偿损失、赔礼道歉等民事责任。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百四十二条", "text": "违反本法规定，县级以上地方人民政府有下列行为之一的，对直接负责的主管人员和其他直接责任人员给予记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分；造成严重后果的，其主要负责人还应当引咎辞职： （一）对发生在本行政区域内的食品安全事故，未及时组织协调有关部门开展有效处置，造成不良影响或者损失； （二）对本行政区域内涉及多环节的区域性食品安全问题，未及时组织整治，造成不良影响或者损失； （三）隐瞒、谎报、缓报食品安全事故； （四）本行政区域内发生特别重大食品安全事故，或者连续发生重大食品安全事故。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百四十三条", "text": "违反本法规定，县级以上地方人民政府有下列行为之一的，对直接负责的主管人员和其他直接责任人员给予警告、记过或者记大过处分；造成严重后果的，给予降级或者撤职处分： （一）未确定有关部门的食品安全监督管理职责，未建立健全食品安全全程监督管理工作机制和信息共享机制，未落实食品安全监督管理责任制； （二）未制定本行政区域的食品安全事故应急预案，或者发生食品安全事故后未按规定立即成立事故处置指挥机构、启动应急预案。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百四十四条", "text": "违反本法规定，县级以上人民政府食品安全监督管理、卫生行政、农业行政等部门有下列行为之一的，对直接负责的主管人员和其他直接责任人员给予记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分；造成严重后果的，其主要负责人还应当引咎辞职： （一）隐瞒、谎报、缓报食品安全事故； （二）未按规定查处食品安全事故，或者接到食品安全事故报告未及时处理，造成事故扩大或者蔓延； （三）经食品安全风险评估得出食品、食品添加剂、食品相关产品不安全结论后，未及时采取相应措施，造成食品安全事故或者不良社会影响； （四）对不符合条件的申请人准予许可，或者超越法定职权准予许可； （五）不履行食品安全监督管理职责，导致发生食品安全事故。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百四十五条", "text": "违反本法规定，县级以上人民政府食品安全监督管理、卫生行政、农业行政等部门有下列行为之一，造成不良后果的，对直接负责的主管人员和其他直接责任人员给予警告、记过或者记大过处分；情节较重的，给予降级或者撤职处分；情节严重的，给予开除处分： （一）在获知有关食品安全信息后，未按规定向上级主管部门和本级人民政府报告，或者未按规定相互通报； （二）未按规定公布食品安全信息； （三）不履行法定职责，对查处食品安全违法行为不配合，或者滥用职权、玩忽职守、徇私舞弊。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百四十六条", "text": "食品安全监督管理等部门在履行食品安全监督管理职责过程中，违法实施检查、强制等执法措施，给生产经营者造成损失的，应当依法予以赔偿，对直接负责的主管人员和其他直接责任人员依法给予处分。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百四十七条", "text": "违反本法规定，造成人身、财产或者其他损害的，依法承担赔偿责任。生产经营者财产不足以同时承担民事赔偿责任和缴纳罚款、罚金时，先承担民事赔偿责任。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百四十八条", "text": "消费者因不符合食品安全标准的食品受到损害的，可以向经营者要求赔偿损失，也可以向生产者要求赔偿损失。接到消费者赔偿要求的生产经营者，应当实行首负责任制，先行赔付，不得推诿；属于生产者责任的，经营者赔偿后有权向生产者追偿；属于经营者责任的，生产者赔偿后有权向经营者追偿。 生产不符合食品安全标准的食品或者经营明知是不符合食品安全标准的食品，消费者除要求赔偿损失外，还可以向生产者或者经营者要求支付价款十倍或者损失三倍的赔偿金；增加赔偿的金额不足一千元的，为一千元。但是，食品的标签、说明书存在不影响食品安全且不会对消费者造成误导的瑕疵的除外。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百四十九条", "text": "违反本法规定，构成犯罪的，依法追究刑事责任。 第十章 附 则"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百五十条", "text": "本法下列用语的含义： 食品，指各种供人食用或者饮用的成品和原料以及按照传统既是食品又是中药材的物品，但是不包括以治疗为目的的物品。 食品安全，指食品无毒、无害，符合应当有的营养要求，对人体健康不造成任何急性、亚急性或者慢性危害。 预包装食品，指预先定量包装或者制作在包装材料、容器中的食品。 食品添加剂，指为改善食品品质和色、香、味以及为防腐、保鲜和加工工艺的需要而加入食品中的人工合成或者天然物质，包括营养强化剂。 用于食品的包装材料和容器，指包装、盛放食品或者食品添加剂用的纸、竹、木、金属、搪瓷、陶瓷、塑料、橡胶、天然纤维、化学纤维、玻璃等制品和直接接触食品或者食品添加剂的涂料。 用于食品生产经营的工具、设备，指在食品或者食品添加剂生产、销售、使用过程中直接接触食品或者食品添加剂的机械、管道、传送带、容器、用具、餐具等。 用于食品的洗涤剂、消毒剂，指直接用于洗涤或者消毒食品、餐具、饮具以及直接接触食品的工具、设备或者食品包装材料和容器的物质。 食品保质期，指食品在标明的贮存条件下保持品质的期限。 食源性疾病，指食品中致病因素进入人体引起的感染性、中毒性等疾病，包括食物中毒。 食品安全事故，指食源性疾病、食品污染等源于食品，对人体健康有危害或者可能有危害的事故。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百五十一条", "text": "转基因食品和食盐的食品安全管理，本法未作规定的，适用其他法律、行政法规的规定。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百五十二条", "text": "铁路、民航运营中食品安全的管理办法由国务院食品安全监督管理部门会同国务院有关部门依照本法制定。 保健食品的具体管理办法由国务院食品安全监督管理部门依照本法制定。 食品相关产品生产活动的具体管理办法由国务院食品安全监督管理部门依照本法制定。 国境口岸食品的监督管理由出入境检验检疫机构依照本法以及有关法律、行政法规的规定实施。 军队专用食品和自供食品的食品安全管理办法由中央军事委员会依照本法制定。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百五十三条", "text": "国务院根据实际需要，可以对食品安全监督管理体制作出调整。"}, {"law": "中华人民共和国食品安全法_20250912.docx", "no": "第一百五十四条", "text": "本法自2015年10月1日起施行。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第一条", "text": "为加强企业安全生产费用管理，建立企业安全生产投入长效机制，维护企业、职工以及社会公共利益，依据《 HYPERLINK &quot;https://baike.baidu.com/item/%E4%B8%AD%E5%8D%8E%E4%BA%BA%E6%B0%91%E5%85%B1%E5%92%8C%E5%9B%BD%E5%AE%89%E5%85%A8%E7%94%9F%E4%BA%A7%E6%B3%95&quot; \\t &quot;_blank&quot; 中华人民共和国安全生产法》等有关法律法规和 HYPERLINK &quot;http://www.gov.cn/zhengce/2016-12/18/content_5149663.htm&quot; \\t &quot;_blank&quot; 《中共中央 国务院关于推进安全生产领域改革发展的意见》、《国务院关于进一步加强安全生产工作的决定》（国发〔2004〕2号）、《 HYPERLINK &quot;https://baike.baidu.com/item/%E5%9B%BD%E5%8A%A1%E9%99%A2%E5%85%B3%E4%BA%8E%E8%BF%9B%E4%B8%80%E6%AD%A5%E5%8A%A0%E5%BC%BA%E4%BC%81%E4%B8%9A%E5%AE%89%E5%85%A8%E7%94%9F%E4%BA%A7%E5%B7%A5%E4%BD%9C%E7%9A%84%E9%80%9A%E7%9F%A5&quot; \\t &quot;_blank&quot; 国务院关于进一步加强企业安全生产工作的通知》（国发〔2010〕23号）等，制定本办法。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第二条", "text": "本办法适用于在中华人民共和国境内直接从事煤炭生产、非煤矿山开采、石油天然气开采、建设工程施工、危险品生产与储存、交通运输、烟花爆竹生产、民用爆炸物品生产、冶金、机械制造、武器装备研制生产与试验（含民用航空及核燃料）、电力生产与供应的企业及其他经济组织（以下统称企业）。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第三条", "text": "本办法所称企业安全生产费用是指企业按照规定标准提取，在成本（费用）中列支，专门用于完善和改进企业或者项目安全生产条件的资金。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第四条", "text": "企业安全生产费用管理遵循以下原则： （一）筹措有章。统筹发展和安全，依法落实企业安全生产投入主体责任，足额提取。 （二）支出有据。企业根据生产经营实际需要，据实开支符合规定的安全生产费用。 （三）管理有序。企业专项核算和归集安全生产费用，真实反映安全生产条件改善投入，不得挤占、挪用。 （四）监督有效。建立健全企业安全生产费用提取和使用的内外部监督机制，按规定开展信息披露和社会责任报告。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第五条", "text": "企业安全生产费用可由企业用于以下范围的支出： （一）购置购建、更新改造、检测检验、检定校准、运行维护安全防护和紧急避险设施、设备支出[不含按照“建设项目安全设施必须与主体工程同时设计、同时施工、同时投入生产和使用”（以下简称“三同时”）规定投入的安全设施、设备]； （二）购置、开发、推广应用、更新升级、运行维护安全生产信息系统、软件、网络安全、技术支出； （三）配备、更新、维护、保养安全防护用品和应急救援器材、设备支出； （四）企业应急救援队伍建设（含建设应急救援队伍所需应急救援物资储备、人员培训等方面）、安全生产宣传教育培训、从业人员发现报告事故隐患的奖励支出； （五）安全生产责任保险、承运人责任险等与安全生产直接相关的法定保险支出； （六）安全生产检查检测、评估评价（不含新建、改建、扩建项目安全评价）、评审、咨询、标准化建设、应急预案制修订、应急演练支出； （七）与安全生产直接相关的其他支出。 第二章 企业安全生产费用的提取和使用 第一节 煤炭生产企业"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第六条", "text": "煤炭生产是指煤炭资源开采作业有关活动。 批准进行联合试运转的基本建设煤矿，按照本节规定提取使用企业安全生产费用。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第七条", "text": "煤炭生产企业依据当月开采的原煤产量，于月末提取企业安全生产费用。提取标准如下： （一）煤（岩）与瓦斯（二氧化碳）突出矿井、冲击地压矿井吨煤50元； （二）高瓦斯矿井，水文地质类型复杂、极复杂矿井，容易自燃煤层矿井吨煤30元； （三）其他井工矿吨煤15元； （四）露天矿吨煤5元。 矿井瓦斯等级划分执行《煤矿安全规程》（应急管理部令第8号）和《煤矿瓦斯等级鉴定办法》（煤安监技装〔2018〕9号）的规定；矿井冲击地压判定执行《煤矿安全规程》（应急管理部令第8号）和《防治煤矿冲击地压细则》（煤安监技装〔2018〕8号）的规定；矿井水文地质类型划分执行《煤矿安全规程》（应急管理部令第8号）和《煤矿防治水细则》（煤安监调查〔2018〕14号）的规定。 多种灾害并存矿井，从高提取企业安全生产费用。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第八条", "text": "煤炭生产企业安全生产费用应当用于以下支出： （一）煤与瓦斯突出及高瓦斯矿井落实综合防突措施支出，包括瓦斯区域预抽、保护层开采区域防突措施、开展突出区域和局部预测、实施局部补充防突措施等两个“四位一体”综合防突措施，以及更新改造防突设备和设施、建立突出防治实验室等支出； （二）冲击地压矿井落实防冲措施支出，包括开展冲击地压危险性预测、监测预警、防范治理、效果检验、安全防护等防治措施，更新改造防冲设备和设施，建立防冲实验室等支出； （三）煤矿安全生产改造和重大事故隐患治理支出，包括通风、防瓦斯、防煤尘、防灭火、防治水、顶板、供电、运输等系统设备改造和灾害治理工程，实施煤矿机械化改造、智能化建设，实施矿压、热害、露天煤矿边坡治理等支出； （四）完善煤矿井下监测监控、人员位置监测、紧急避险、压风自救、供水施救和通信联络等安全避险设施设备支出，应急救援技术装备、设施配置和维护保养支出，事故逃生和紧急避难设施设备的配置和应急救援队伍建设、应急预案制修订与应急演练支出； （五）开展重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，安全生产信息化建设、运维和网络安全支出； （六）安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询、标准化建设支出； （七）配备和更新现场作业人员安全防护用品支出； （八）安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出； （九）安全生产适用新技术、新标准、新工艺、煤矿智能装备及煤矿机器人等新装备的推广应用支出； （十）安全设施及特种设备检测检验、检定校准支出； （十一）安全生产责任保险支出； （十二）与安全生产直接相关的其他支出。 第二节 非煤矿山开采企业"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第九条", "text": "非煤矿山开采是指金属矿、非金属矿及其他矿产资源的勘探作业和生产、选矿、闭坑及尾矿库运行、回采、闭库等有关活动。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第十条", "text": "非煤矿山开采企业依据当月开采的原矿产量，于月末提取企业安全生产费用。提取标准如下： （一）金属矿山，其中露天矿山每吨5元，地下矿山每吨15元； （二）核工业矿山，每吨25元； （三）非金属矿山，其中露天矿山每吨3元，地下矿山每吨8元； （四）小型露天采石场，即年生产规模不超过50万吨的山坡型露天采石场，每吨2元。 上款所称原矿产量，不含金属、非金属矿山尾矿库和废石场中用于综合利用的尾砂和低品位矿石。 地质勘探单位按地质勘查项目或工程总费用的2%，在项目或工程实施期内逐月提取企业安全生产费用。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第十一条", "text": "尾矿库运行按当月入库尾矿量计提企业安全生产费用，其中三等及三等以上尾矿库每吨4元，四等及五等尾矿库每吨5元。 尾矿库回采按当月回采尾矿量计提企业安全生产费用，其中三等及三等以上尾矿库每吨1元，四等及五等尾矿库每吨1.5元。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第十二条", "text": "非煤矿山开采企业安全生产费用应当用于以下支出： （一）完善、改造和维护安全防护设施设备（不含“三同时”要求初期投入的安全设施）和重大事故隐患治理支出，包括矿山综合防尘、防灭火、防治水、危险气体监测、通风系统、支护及防治边帮滑坡、防冒顶片帮设备、机电设备、供配电系统、运输（提升）系统和尾矿库等完善、改造和维护支出以及实施地压监测监控、露天矿边坡治理等支出； （二）完善非煤矿山监测监控、人员位置监测、紧急避险、压风自救、供水施救和通信联络等安全避险设施设备支出，完善尾矿库全过程在线监测监控系统支出，应急救援技术装备、设施配置及维护保养支出，事故逃生和紧急避难设施设备的配置和应急救援队伍建设、应急预案制修订与应急演练支出； （三）开展重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，机械化、智能化建设，安全生产信息化建设、运维和网络安全支出； （四）安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询、标准化建设支出； （五）配备和更新现场作业人员安全防护用品支出； （六）安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出； （七）安全生产适用的新技术、新标准、新工艺、智能化、机器人等新装备的推广应用支出； （八）安全设施及特种设备检测检验、检定校准支出； （九）尾矿库闭库、销库费用支出； （十）地质勘探单位野外应急食品、应急器械、应急药品支出； （十一）安全生产责任保险支出； （十二）与安全生产直接相关的其他支出。 第三节 石油天然气开采企业"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第十三条", "text": "石油天然气（包括页岩油、页岩气）开采是指陆上采油（气）、海上采油（气）、钻井、物探、测井、录井、井下作业、油建、海油工程等活动。 煤层气（地面开采）企业参照陆上采油（气）企业执行。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第十四条", "text": "陆上采油（气）、海上采油（气）企业依据当月开采的石油、天然气产量，于月末提取企业安全生产费用。其中每吨原油20元，每千立方米原气7.5元。 钻井、物探、测井、录井、井下作业、油建、海油工程等企业按照项目或工程造价中的直接工程成本的2%逐月提取企业安全生产费用。工程发包单位应当在合同中单独约定并及时向工程承包单位支付企业安全生产费用。 石油天然气开采企业的储备油、地下储气库参照危险品储存企业执行。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第十五条", "text": "石油天然气开采企业安全生产费用应当用于以下支出： （一）完善、改造和维护安全防护设施设备支出（不含“三同时”要求初期投入的安全设施），包括油气井（场）、管道、站场、海洋石油生产设施、作业设施等设施设备的监测、监控、防井喷、防灭火、防坍塌、防爆炸、防泄漏、防腐蚀、防颠覆、防漂移、防雷、防静电、防台风、防中毒、防坠落等设施设备支出； （二）事故逃生和紧急避难设施设备的配置及维护保养支出，应急救援器材、设备配置及维护保养支出，应急救援队伍建设、应急预案制修订与应急演练支出； （三）开展重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，安全生产信息化、智能化建设、运维和网络安全支出； （四）安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询、标准化建设支出； （五）配备和更新现场作业人员安全防护用品支出； （六）安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出； （七）安全生产适用的新技术、新标准、新工艺、新装备的推广应用支出； （八）安全设施及特种设备检测检验、检定校准支出； （九）野外或海上作业应急食品、应急器械、应急药品支出； （十）安全生产责任保险支出； （十一）与安全生产直接相关的其他支出。 第四节 建设工程施工企业"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第十六条", "text": "建设工程是指土木工程、建筑工程、线路管道和设备安装及装修工程，包括新建、扩建、改建。 井巷工程、矿山建设参照建设工程执行。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第十七条", "text": "建设工程施工企业以建筑安装工程造价为依据，于月末按工程进度计算提取企业安全生产费用。提取标准如下： （一）矿山工程3.5%； （二）铁路工程、房屋建筑工程、城市轨道交通工程3%； （三）水利水电工程、电力工程2.5%； （四）冶炼工程、机电安装工程、化工石油工程、通信工程2%； （五）市政公用工程、港口与航道工程、公路工程1.5%。 建设工程施工企业编制投标报价应当包含并单列企业安全生产费用，竞标时不得删减。国家对基本建设投资概算另有规定的，从其规定。 本办法实施前建设工程项目已经完成招投标并签订合同的，企业安全生产费用按照原规定提取标准执行。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第十八条", "text": "建设单位应当在合同中单独约定并于工程开工日一个月内向承包单位支付至少50%企业安全生产费用。 总包单位应当在合同中单独约定并于分包工程开工日一个月内将至少50%企业安全生产费用直接支付分包单位并监督使用，分包单位不再重复提取。 工程竣工决算后结余的企业安全生产费用，应当退回建设单位。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第十九条", "text": "建设工程施工企业安全生产费用应当用于以下支出： （一）完善、改造和维护安全防护设施设备支出（不含“三同时”要求初期投入的安全设施），包括施工现场临时用电系统、洞口或临边防护、高处作业或交叉作业防护、临时安全防护、支护及防治边坡滑坡、工程有害气体监测和通风、保障安全的机械设备、防火、防爆、防触电、防尘、防毒、防雷、防台风、防地质灾害等设施设备支出； （二）应急救援技术装备、设施配置及维护保养支出，事故逃生和紧急避难设施设备的配置和应急救援队伍建设、应急预案制修订与应急演练支出； （三）开展施工现场重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，工程项目安全生产信息化建设、运维和网络安全支出； （四）安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询和标准化建设支出； （五）配备和更新现场作业人员安全防护用品支出； （六）安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出； （七）安全生产适用的新技术、新标准、新工艺、新装备的推广应用支出； （八）安全设施及特种设备检测检验、检定校准支出； （九）安全生产责任保险支出； （十）与安全生产直接相关的其他支出。 第五节 危险品生产与储存企业"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第二十条", "text": "危险品生产与储存是指经批准开展列入国家标准《危险货物品名表》（GB12268）、《危险化学品目录》物品，以及列入国家有关规定危险品直接生产和聚积保存的活动（不含销售和使用）。 危险品运输适用第六节规定。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第二十一条", "text": "危险品生产与储存企业以上一年度营业收入为依据，采取超额累退方式确定本年度应计提金额，并逐月平均提取。具体如下： （一）上一年度营业收入不超过1000万元的，按照4.5%提取； （二）上一年度营业收入超过1000万元至1亿元的部分，按照2.25%提取； （三）上一年度营业收入超过1亿元至10亿元的部分，按照0.55%提取； （四）上一年度营业收入超过10亿元的部分，按照0.2%提取。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第二十二条", "text": "危险品生产与储存企业安全生产费用应当用于以下支出： （一）完善、改造和维护安全防护设施设备支出（不含“三同时”要求初期投入的安全设施），包括车间、库房、罐区等作业场所的监控、监测、通风、防晒、调温、防火、灭火、防爆、泄压、防毒、消毒、中和、防潮、防雷、防静电、防腐、防渗漏、防护围堤和隔离操作等设施设备支出； （二）配备、维护、保养应急救援器材、设备支出和应急救援队伍建设、应急预案制修订与应急演练支出； （三）开展重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，安全生产风险监测预警系统等安全生产信息系统建设、运维和网络安全支出； （四）安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询和标准化建设支出； （五）配备和更新现场作业人员安全防护用品支出； （六）安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出； （七）安全生产适用的新技术、新标准、新工艺、新装备的推广应用支出； （八）安全设施及特种设备检测检验、检定校准支出； （九）安全生产责任保险支出； （十）与安全生产直接相关的其他支出。 第六节 交通运输企业"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第二十三条", "text": "交通运输包括道路运输、铁路运输、城市轨道交通、水路运输、管道运输。 道路运输是指《中华人民共和国道路运输条例》规定的道路旅客运输和道路货物运输；铁路运输是指《中华人民共和国铁路法》规定的铁路旅客运输和货物运输；城市轨道交通是指依规定批准建设的，采用专用轨道导向运行的城市公共客运交通系统，包括地铁、轻轨、单轨、有轨电车、磁浮、自动导向轨道、市域快速轨道系统；水路运输是指以运输船舶为工具的经营性旅客和货物运输及港口装卸、过驳、仓储；管道运输是指以管道为工具的液体和气体物资运输。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第二十四条", "text": "交通运输企业以上一年度营业收入为依据，确定本年度应计提金额，并逐月平均提取。具体如下： （一）普通货运业务1%； （二）客运业务、管道运输、危险品等特殊货运业务1.5%。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第二十五条", "text": "交通运输企业安全生产费用应当用于以下支出： （一）完善、改造和维护安全防护设施设备支出（不含“三同时”要求初期投入的安全设施），包括道路、水路、铁路、城市轨道交通、管道运输设施设备和装卸工具安全状况检测及维护系统、运输设施设备和装卸工具附属安全设备等支出； （二）购置、安装和使用具有行驶记录功能的车辆卫星定位装置、视频监控装置、船舶通信导航定位和自动识别系统、电子海图等支出； （三）铁路和城市轨道交通防灾监测预警设备及铁路周界入侵报警系统、铁路危险品运输安全监测设备支出； （四）配备、维护、保养应急救援器材、设备支出和应急救援队伍建设、应急预案制修订与应急演练支出； （五）开展重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，安全生产信息化、智能化建设、运维和网络安全支出； （六）安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询和标准化建设支出； （七）配备和更新现场作业人员安全防护用品支出； （八）安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出； （九）安全生产适用的新技术、新标准、新工艺、新装备的推广应用支出； （十）安全设施及特种设备检测检验、检定校准、铁路和城市轨道交通基础设备安全检测支出； （十一）安全生产责任保险及承运人责任保险支出； （十二）与安全生产直接相关的其他支出。 第七节 冶金企业"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第二十六条", "text": "冶金是指黑色金属和有色金属冶炼及压延加工等生产活动。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第二十七条", "text": "冶金企业以上一年度营业收入为依据，采取超额累退方式确定本年度应计提金额，并逐月平均提取。具体如下： （一）上一年度营业收入不超过1000万元的，按照3%提取； （二）上一年度营业收入超过1000万元至1亿元的部分，按照1.5%提取； （三）上一年度营业收入超过1亿元至10亿元的部分，按照0.5%提取； （四）上一年度营业收入超过10亿元至50亿元的部分，按照0.2%提取； （五）上一年度营业收入超过50亿元至100亿元的部分，按照0.1%提取； （六）上一年度营业收入超过100亿元的部分，按照0.05%提取。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第二十八条", "text": "冶金企业安全生产费用应当用于以下支出： （一）完善、改造和维护安全防护设备设施支出（不含“三同时”要求初期投入的安全设施），包括车间、站、库房等作业场所的监控、监测、防高温、防火、防爆、防坠落、防尘、防毒、防雷、防窒息、防触电、防噪声与振动、防辐射和隔离操作等设施设备支出； （二）配备、维护、保养应急救援器材、设备支出和应急救援队伍建设、应急预案制修订与应急演练支出； （三）开展重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，安全生产信息化、智能化建设、运维和网络安全支出； （四）安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）和咨询及标准化建设支出； （五）安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出； （六）配备和更新现场作业人员安全防护用品支出； （七）安全生产适用的新技术、新标准、新工艺、新装备的推广应用支出； （八）安全设施及特种设备检测检验、检定校准支出； （九）安全生产责任保险支出； （十）与安全生产直接相关的其他支出。 第八节 机械制造企业"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第二十九条", "text": "机械制造是指各种动力机械、矿山机械、运输机械、农业机械、仪器、仪表、特种设备、大中型船舶、海洋工程装备、石油炼化装备、建筑施工机械及其他机械设备的制造活动。 按照《国民经济行业分类与代码》（GB/T4754），本办法所称机械制造企业包括通用设备制造业，专用设备制造业，汽车制造业，铁路、船舶、航空航天和其他运输设备制造业（不含第十一节民用航空设备制造），电气机械和器材制造业，计算机、通信和其他电子设备制造业，仪器仪表制造业，金属制品、机械和设备修理业等8类企业。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第三十条", "text": "机械制造企业以上一年度营业收入为依据，采取超额累退方式确定本年度应计提金额，并逐月平均提取。具体如下： （一）上一年度营业收入不超过1000万元的，按照2.35%提取； （二）上一年度营业收入超过1000万元至1亿元的部分，按照1.25%提取； （三）上一年度营业收入超过1亿元至10亿元的部分，按照0.25%提取； （四）上一年度营业收入超过10亿元至50亿元的部分，按照0.1%提取； （五）上一年度营业收入超过50亿元的部分，按照0.05%提取。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第三十一条", "text": "机械制造企业安全生产费用应当用于以下支出： （一）完善、改造和维护安全防护设施设备支出（不含“三同时”要求初期投入的安全设施），包括生产作业场所的防火、防爆、防坠落、防毒、防静电、防腐、防尘、防噪声与振动、防辐射和隔离操作等设施设备支出，大型起重机械安装安全监控管理系统支出； （二）配备、维护、保养应急救援器材、设备支出和应急救援队伍建设、应急预案制修订与应急演练支出； （三）开展重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，安全生产信息化、智能化建设、运维和网络安全支出； （四）安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询和标准化建设支出； （五）安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出； （六）配备和更新现场作业人员安全防护用品支出； （七）安全生产适用的新技术、新标准、新工艺、新装备的推广应用支出； （八）安全设施及特种设备检测检验、检定校准支出； （九）安全生产责任保险支出； （十）与安全生产直接相关的其他支出。 第九节 烟花爆竹生产企业"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第三十二条", "text": "烟花爆竹是指烟花爆竹制品和用于生产烟花爆竹的民用黑火药、烟火药、引火线等物品。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第三十三条", "text": "烟花爆竹生产企业以上一年度营业收入为依据，采取超额累退方式确定本年度应计提金额，并逐月平均提取。具体如下： （一）上一年度营业收入不超过1000万元的，按照4%提取； （二）上一年度营业收入超过1000万元至2000万元的部分，按照3%提取； （三）上一年度营业收入超过2000万元的部分，按照2.5%提取。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第三十四条", "text": "烟花爆竹生产企业安全生产费用应当用于以下支出： （一）完善、改造和维护安全设备设施支出（不含“三同时”要求初期投入的安全设施），包括作业场所的防火、防爆（含防护屏障）、防雷、防静电、防护围墙（网）与栏杆、防高温、防潮、防山体滑坡、监测、检测、监控等设施设备支出； （二）配备、维护、保养防爆机械电器设备支出； （三）配备、维护、保养应急救援器材、设备支出和应急救援队伍建设、应急预案制修订与应急演练支出； （四）开展重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，安全生产信息化、智能化建设、运维和网络安全支出； （五）安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询和标准化建设支出； （六）安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出； （七）配备和更新现场作业人员安全防护用品支出； （八）安全生产适用新技术、新标准、新工艺、新装备的推广应用支出； （九）安全设施及特种设备检测检验、检定校准支出； （十）安全生产责任保险支出； （十一）与安全生产直接相关的其他支出。 第十节 民用爆炸物品生产企业"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第三十五条", "text": "民用爆炸物品是指列入《民用爆炸物品品名表》的物品。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第三十六条", "text": "民用爆炸物品生产企业以上一年度营业收入为依据，采取超额累退方式确定本年度应计提金额，并逐月平均提取。具体如下： （一）上一年度营业收入不超过1000万元的，按照4%提取； （二）上一年度营业收入超过1000万元至1亿元的部分，按照2%提取； （三）上一年度营业收入超过1亿元至10亿元的部分，按照0.5%提取； （四）上一年度营业收入超过10亿元的部分，按照0.2%提取。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第三十七条", "text": "民用爆炸物品生产企业安全生产费用应当用于以下支出： （一）完善、改造和维护安全防护设施设备（不含“三同时”要求初期投入的安全设施），包括车间、库房、罐区等作业场所的监控、监测、通风、防晒、调温、防火、灭火、防爆、泄压、防毒、消毒、中和、防潮、防雷、防静电、防腐、防渗漏、防护屏障、隔离操作等设施设备支出； （二）配备、维护、保养应急救援器材、设备支出和应急救援队伍建设、应急预案制修订与应急演练支出； （三）开展重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，安全生产信息化、智能化建设、运维和网络安全支出； （四）安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询和标准化建设支出； （五）配备和更新现场作业人员安全防护用品支出； （六）安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出； （七）安全生产适用的新技术、新标准、新工艺、新设备的推广应用支出； （八）安全设施及特种设备检测检验、检定校准支出； （九）安全生产责任保险支出； （十）与安全生产直接相关的其他支出。 第十一节 武器装备研制生产与试验企业"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第三十八条", "text": "武器装备研制生产与试验，包括武器装备和军工危险化学品的科研、生产、试验、储运、销毁、维修保障等。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第三十九条", "text": "武器装备研制生产与试验企业以上一年度军品营业收入为依据，采取超额累退方式确定本年度应计提金额，并逐月平均提取。 （一）军工危险化学品研制、生产与试验企业，包括火炸药、推进剂、弹药（含战斗部、引信、火工品）、火箭导弹发动机、燃气发生器等，提取标准如下： 1.上一年度营业收入不超过1000万元的，按照5%提取； 2.上一年度营业收入超过1000万元至1亿元的部分，按照3%提取； 3.上一年度营业收入超过1亿元至10亿元的部分，按照1%提取； 4.上一年度营业收入超过10亿元的部分，按照0.5%提取。 （二）核装备及核燃料研制、生产与试验企业，提取标准如下： 1.上一年度营业收入不超过1000万元的，按照3%提取； 2.上一年度营业收入超过1000万元至1亿元的部分，按照2%提取； 3.上一年度营业收入超过1亿元至10亿元的部分，按照0.5%提取； 4.上一年度营业收入超过10亿元的部分，按照0.2%提取。 （三）军用舰船（含修理）研制、生产与试验企业，提取标准如下： 1.上一年度营业收入不超过1000万元的，按照2.5%提取； 2.上一年度营业收入超过1000万元至1亿元的部分，按照1.75%提取； 3.上一年度营业收入超过1亿元至10亿元的部分，按照0.8%提取； 4.上一年度营业收入超过10亿元的部分，按照0.4%提取。 （四）飞船、卫星、军用飞机、坦克车辆、火炮、轻武器、大型天线等产品的总体、部分和元器件研制、生产与试验企业，提取标准如下： 1.上一年度营业收入不超过1000万元的，按照2%提取； 2.上一年度营业收入超过1000万元至1亿元的部分，按照1.5%提取； 3.上一年度营业收入超过1亿元至10亿元的部分，按照0.5%提取； 4.上一年度营业收入超过10亿元至100亿元的部分，按照0.2%提取； 5.上一年度营业收入超过100亿元的部分，按照0.1%提取。 （五）其他军用危险品研制、生产与试验企业，提取标准如下： 1.上一年度营业收入不超过1000万元的，按照4%提取； 2.上一年度营业收入超过1000万元至1亿元的部分，按照2%提取； 3.上一年度营业收入超过1亿元至10亿元的部分，按照0.5%提取； 4.上一年度营业收入超过10亿元的部分，按照0.2%提取。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第四十条", "text": "核工程按照工程造价3%提取企业安全生产费用。企业安全生产费用在竞标时列为标外管理。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第四十一条", "text": "武器装备研制生产与试验企业安全生产费用应当用于以下支出： （一）完善、改造和维护安全防护设施设备支出（不含“三同时”要求初期投入的安全设施），包括研究室、车间、库房、储罐区、外场试验区等作业场所监控、监测、防触电、防坠落、防爆、泄压、防火、灭火、通风、防晒、调温、防毒、防雷、防静电、防腐、防尘、防噪声与振动、防辐射、防护围堤和隔离操作等设施设备支出； （二）配备、维护、保养应急救援、应急处置、特种个人防护器材、设备、设施支出和应急救援队伍建设、应急预案制修订与应急演练支出； （三）开展重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出，安全生产信息化、智能化建设、运维和网络安全支出； （四）高新技术和特种专用设备安全鉴定评估、安全性能检验检测及操作人员上岗培训支出； （五）安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询和标准化建设支出； （六）安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出； （七）军工核设施（含核废物）防泄漏、防辐射的设施设备支出； （八）军工危险化学品、放射性物品及武器装备科研、试验、生产、储运、销毁、维修保障过程中的安全技术措施改造费和安全防护（不含工作服）费用支出； （九）大型复杂武器装备制造、安装、调试的特殊工种和特种作业人员培训支出； （十）武器装备大型试验安全专项论证与安全防护费用支出； （十一）特殊军工电子元器件制造过程中有毒有害物质监测及特种防护支出； （十二）安全生产适用新技术、新标准、新工艺、新装备的推广应用支出； （十三）安全生产责任保险支出； （十四）与安全生产直接相关的其他支出。 第十二节 电力生产与供应企业"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第四十二条", "text": "电力生产是指利用火力、水力、核力、风力、太阳能、生物质能以及地热、潮汐能等其他能源转换成电能的活动。 电力供应是指经营和运行电网，从事输电、变电、配电等电能输送与分配的活动。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第四十三条", "text": "电力生产与供应企业以上一年度营业收入为依据，采取超额累退方式确定本年度应计提金额，并逐月平均提取。 （一）电力生产企业，提取标准如下： 1.上一年度营业收入不超过1000万元的，按照3%提取； 2.上一年度营业收入超过1000万元至1亿元的部分，按照1.5%提取； 3.上一年度营业收入超过1亿元至10亿元的部分，按照1%提取； 4.上一年度营业收入超过10亿元至50亿元的部分，按照0.8%提取； 5.上一年度营业收入超过50亿元至100亿元的部分，按照0.6%提取； 6.上一年度营业收入超过100亿元的部分，按照0.2%提取。 （二）电力供应企业，提取标准如下： 1.上一年度营业收入不超过500亿元的，按照0.5%提取； 2.上一年度营业收入超过500亿元至1000亿元的部分，按照0.4%提取； 3.上一年度营业收入超过1000亿元至2000亿元的部分，按照0.3%提取； 4.上一年度营业收入超过2000亿元的部分，按照0.2%提取。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第四十四条", "text": "电力生产与供应企业安全生产费用应当用于以下支出： （一）完善、改造和维护安全防护设备、设施支出（不含“三同时”要求初期投入的安全设施），包括发电、输电、变电、配电等设备设施的安全防护及安全状况的完善、改造、检测、监测及维护，作业场所的安全监控、监测以及防触电、防坠落、防物体打击、防火、防爆、防毒、防窒息、防雷、防误操作、临边、封闭等设施设备支出； （二）配备、维护、保养应急救援器材、设备设施支出和应急救援队伍建设、应急预案制修订与应急演练支出； （三）开展重大危险源检测、评估、监控支出，安全风险分级管控和事故隐患排查整改支出（不含水电站大坝重大隐患除险加固支出、燃煤发电厂贮灰场重大隐患除险加固治理支出），安全生产信息化、智能化建设、运维和网路安全支出； （四）安全生产检查、评估评价（不含新建、改建、扩建项目安全评价）、咨询和标准化建设支出； （五）安全生产宣传、教育、培训和从业人员发现并报告事故隐患的奖励支出； （六）配备和更新现场作业人员安全防护用品支出； （七）安全生产适用的新技术、新标准、新工艺、新设备的推广应用支出； （八）安全设施及特种设备检测检验、检定校准支出； （九）安全生产责任保险支出； （十）与安全生产直接相关的其他支出。 第三章 企业安全生产费用的管理和监督"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第四十五条", "text": "企业应当建立健全内部企业安全生产费用管理制度，明确企业安全生产费用提取和使用的程序、职责及权限，落实责任，确保按规定提取和使用企业安全生产费用。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第四十六条", "text": "企业应当加强安全生产费用管理，编制年度企业安全生产费用提取和使用计划，纳入企业财务预算，确保资金投入。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第四十七条", "text": "企业提取的安全生产费用从成本（费用）中列支并专项核算。符合本办法规定的企业安全生产费用支出应当取得发票、收据、转账凭证等真实凭证。 本企业职工薪酬、福利不得从企业安全生产费用中支出。企业从业人员发现报告事故隐患的奖励支出从企业安全生产费用中列支。 企业安全生产费用年度结余资金结转下年度使用。企业安全生产费用出现赤字（即当年计提企业安全生产费用加上年初结余小于年度实际支出）的，应当于年末补提企业安全生产费用。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第四十八条", "text": "以上一年度营业收入为依据提取安全生产费用的企业，新建和投产不足一年的，当年企业安全生产费用据实列支，年末以当年营业收入为依据，按照规定标准计算提取企业安全生产费用。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第四十九条", "text": "企业按本办法规定标准连续两年补提安全生产费用的，可以按照最近一年补提数提高提取标准。 本办法公布前，地方各级人民政府已制定下发企业安全生产费用提取使用办法且其提取标准低于本办法规定标准的，应当按照本办法进行调整。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第五十条", "text": "企业安全生产费用月初结余达到上一年应计提金额三倍及以上的，自当月开始暂停提取企业安全生产费用，直至企业安全生产费用结余低于上一年应计提金额三倍时恢复提取。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第五十一条", "text": "企业当年实际使用的安全生产费用不足年度应计提金额60%的，除按规定进行信息披露外，还应当于下一年度4月底前，按照属地监管权限向县级以上人民政府负有安全生产监督管理职责的部门提交经企业董事会、股东会等机构审议的书面说明。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第五十二条", "text": "企业同时开展两项及两项以上以营业收入为安全生产费用计提依据的业务，能够按业务类别分别核算的，按各项业务计提标准分别提取企业安全生产费用；不能分别核算的，按营业收入占比最高业务对应的提取标准对各项合计营业收入计提企业安全生产费用。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第五十三条", "text": "企业作为承揽人或承运人向客户提供纳入本办法规定范围的服务，且外购材料和服务成本高于自客户取得营业收入85%以上的，可以将营业收入扣除相关外购材料和服务成本的净额，作为企业安全生产费用计提依据。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第五十四条", "text": "企业内部有两个及两个以上独立核算的非法人主体，主体之间生产和转移产品和服务按本办法规定需提取企业安全生产费用的，各主体可以以本主体营业收入扣除自其它主体采购产品和服务的成本（即剔除内部互供收入）的净额，作为企业安全生产费用计提依据。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第五十五条", "text": "承担集团安全生产责任的企业集团母公司（一级，以下简称集团总部），可以对全资及控股子公司提取的企业安全生产费用按照一定比例集中管理，统筹使用。子公司转出资金作为企业安全生产费用支出处理，集团总部收到资金作为专项储备管理，不计入集团总部收入。 集团总部统筹的企业安全生产费用应当用于本办法规定的应急救援队伍建设、应急预案制修订与应急演练，安全生产检查、咨询和标准化建设，安全生产宣传、教育、培训，安全生产适用的新技术、新标准、新工艺、新装备的推广应用等安全生产直接相关支出。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第五十六条", "text": "在本办法规定的使用范围内，企业安全生产费用应当优先用于达到法定安全生产标准所需支出和按各级应急管理部门、矿山安全监察机构及其他负有安全生产监督管理职责的部门要求开展的安全生产整改支出。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第五十七条", "text": "煤炭生产企业和非煤矿山企业已提取维持简单再生产费用的，应当继续提取，但不得重复开支本办法规定的企业安全生产费用。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第五十八条", "text": "企业由于产权转让、公司制改建等变更股权结构或者组织形式的，其结余的企业安全生产费用应当继续按照本办法管理使用。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第五十九条", "text": "企业调整业务、终止经营或者依法清算的，其结余的企业安全生产费用应当结转本期收益或者清算收益。下列情形除外： （一）矿山企业转产、停产、停业或者解散的，应当将企业安全生产费用结余用于矿山闭坑、尾矿库闭库后可能的危害治理和损失赔偿； （二）危险品生产与储存企业转产、停产、停业或者解散的，应当将企业安全生产费用结余用于处理转产、停产、停业或者解散前的危险品生产或者储存设备、库存产品及生产原料支出。 第（一）和（二）项企业安全生产费用结余，有存续企业的，由存续企业管理；无存续企业的，由清算前全部股东共同管理或者委托第三方管理。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第六十条", "text": "企业提取的安全生产费用属于企业自提自用资金，除集团总部按规定统筹使用外，任何单位和个人不得采取收取、代管等形式对其进行集中管理和使用。法律、行政法规另有规定的，从其规定。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第六十一条", "text": "各级应急管理部门、矿山安全监察机构及其他负有安全生产监督管理职责的部门和财政部门依法对企业安全生产费用提取、使用和管理进行监督检查。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第六十二条", "text": "企业未按本办法提取和使用安全生产费用的，由县级以上应急管理部门、矿山安全监察机构及其他负有安全生产监督管理职责的部门和财政部门按照职责分工，责令限期改正 ，并依照《中华人民共和国安全生产法》、《中华人民共和国会计法》和相关法律法规进行处理、处罚。情节严重、性质恶劣的，依照有关规定实施联合惩戒。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第六十三条", "text": "建设单位未按规定及时向施工单位支付企业安全生产费用、建设工程施工总承包单位未向分包单位支付必要的企业安全生产费用以及承包单位挪用企业安全生产费用的，由建设、交通运输、铁路、水利、应急管理、矿山安全监察等部门按职责分工依法进行处理、处罚。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第六十四条", "text": "各级应急管理部门、矿山安全监察机构及其他负有安全生产监督管理职责的部门和财政部门及其工作人员，在企业安全生产费用监督管理中存在滥用职权、玩忽职守、徇私舞弊等违法违纪行为的，按照《中华人民共和国安全生产法》、《中华人民共和国监察法》等有关规定追究相应责任。构成犯罪的，依法追究刑事责任。 第四章 附则"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第六十五条", "text": "企业安全生产费用的会计处理，应当符合国家统一的会计制度规定。 企业安全生产费用财务处理与税收规定不一致的，纳税时应当依法进行调整。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第二条", "text": "规定范围以外的企业为达到应当具备的安全生产条件所需的资金投入，从成本（费用）中列支。 自营烟花爆竹储存仓库的烟花爆竹销售企业、自营民用爆炸物品储存仓库的民用爆炸物品销售企业，分别参照烟花爆竹生产企业、民用爆炸物品生产企业执行。 实行企业化管理的事业单位参照本办法执行。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第六十七条", "text": "各省级应急管理部门、矿山安全监察机构可以结合本地区实际情况，会同相关部门制定特定行业具体办法，报省级人民政府批准后实施。 县级以上应急管理部门应当将本地区企业安全生产费用提取使用情况纳入定期统计分析。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第六十八条", "text": "本办法由财政部、应急部负责解释。"}, {"law": "企业安全生产费用提取和使用管理办法_20221121.docx", "no": "第六十九条", "text": "本办法自印发之日起施行。《企业安全生产费用提取和使用管理办法》（财企〔2012〕16号）同时废止。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第一条", "text": "为了保证作业场所安全使用有毒物品，预防、控制和消除职业中毒危害，保护劳动者的生命安全、身体健康及其相关权益，根据职业病防治法和其他有关法律、行政法规的规定，制定本条例。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第二条", "text": "作业场所使用有毒物品可能产生职业中毒危害的劳动保护，适用本条例。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第三条", "text": "按照有毒物品产生的职业中毒危害程度，有毒物品分为一般有毒物品和高毒物品。国家对作业场所使用高毒物品实行特殊管理。 一般有毒物品目录、高毒物品目录由国务院卫生行政部门会同有关部门依据国家标准制定、调整并公布。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第四条", "text": "从事使用有毒物品作业的用人单位（以下简称用人单位）应当使用符合国家标准的有毒物品，不得在作业场所使用国家明令禁止使用的有毒物品或者使用不符合国家标准的有毒物品。 用人单位应当尽可能使用无毒物品；需要使用有毒物品的，应当优先选择使用低毒物品。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第五条", "text": "用人单位应当依照本条例和其他有关法律、行政法规的规定，采取有效的防护措施，预防职业中毒事故的发生，依法参加工伤保险，保障劳动者的生命安全和身体健康。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第六条", "text": "国家鼓励研制、开发、推广、应用有利于预防、控制、消除职业中毒危害和保护劳动者健康的新技术、新工艺、新材料；限制使用或者淘汰有关职业中毒危害严重的技术、工艺、材料；加强对有关职业病的机理和发生规律的基础研究，提高有关职业病防治科学技术水平。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第七条", "text": "禁止使用童工。 用人单位不得安排未成年人和孕期、哺乳期的女职工从事使用有毒物品的作业。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第八条", "text": "工会组织应当督促并协助用人单位开展职业卫生宣传教育和培训，对用人单位的职业卫生工作提出意见和建议，与用人单位就劳动者反映的职业病防治问题进行协调并督促解决。 工会组织对用人单位违反法律、法规，侵犯劳动者合法权益的行为，有权要求纠正；产生严重职业中毒危害时，有权要求用人单位采取防护措施，或者向政府有关部门建议采取强制性措施；发生职业中毒事故时，有权参与事故调查处理；发现危及劳动者生命、健康的情形时，有权建议用人单位组织劳动者撤离危险现场，用人单位应当立即作出处理。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第九条", "text": "县级以上人民政府卫生行政、疾病预防控制部门及其他有关行政部门应当依据各自的职责，监督用人单位严格遵守本条例和其他有关法律、法规的规定，加强作业场所使用有毒物品的劳动保护，防止职业中毒事故发生，确保劳动者依法享有的权利。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第十条", "text": "各级人民政府应当加强对使用有毒物品作业场所职业卫生安全及相关劳动保护工作的领导，督促、支持卫生行政、疾病预防控制部门及其他有关行政部门依法履行监督检查职责，及时协调、解决有关重大问题；在发生职业中毒事故时，应当采取有效措施，控制事故危害的蔓延并消除事故危害，并妥善处理有关善后工作。 第二章 作业场所的预防措施"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第十一条", "text": "用人单位的设立，应当符合有关法律、行政法规规定的设立条件，并依法办理有关手续，取得营业执照。 用人单位的使用有毒物品作业场所，除应当符合职业病防治法规定的职业卫生要求外，还必须符合下列要求： （一）作业场所与生活场所分开，作业场所不得住人； （二）有害作业与无害作业分开，高毒作业场所与其他作业场所隔离； （三）设置有效的通风装置；可能突然泄漏大量有毒物品或者易造成急性中毒的作业场所，设置自动报警装置和事故通风设施； （四）高毒作业场所设置应急撤离通道和必要的泄险区。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第十二条", "text": "使用有毒物品作业场所应当设置黄色区域警示线、警示标识和中文警示说明。警示说明应当载明产生职业中毒危害的种类、后果、预防以及应急救治措施等内容。 高毒作业场所应当设置红色区域警示线、警示标识和中文警示说明，并设置通讯报警设备。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第十三条", "text": "新建、扩建、改建的建设项目和技术改造、技术引进项目（以下统称建设项目），可能产生职业中毒危害的，应当依照职业病防治法的规定进行职业中毒危害预评价；可能产生职业中毒危害的建设项目的职业中毒危害防护设施应当与主体工程同时设计，同时施工，同时投入生产和使用；建设项目竣工验收前，应当进行职业中毒危害控制效果评价；建设项目的职业中毒危害防护设施经依法组织验收合格后，方可投入生产和使用。 可能产生职业中毒危害的建设项目的职业中毒危害防护设施设计应当符合国家职业卫生标准和卫生要求。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第十四条", "text": "用人单位应当按照国务院卫生行政部门的规定，向卫生行政部门及时、如实申报存在职业中毒危害项目。 从事使用高毒物品作业的用人单位，在申报使用高毒物品作业项目时，应当向卫生行政部门提交下列有关资料： （一）职业中毒危害控制效果评价报告； （二）职业卫生管理制度和操作规程等材料； （三）职业中毒事故应急救援预案。 从事使用高毒物品作业的用人单位变更所使用的高毒物品品种的，应当依照前款规定向原受理申报的卫生行政部门重新申报。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第十五条", "text": "用人单位变更名称、法定代表人或者负责人的，应当向原受理申报的卫生行政部门备案。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第十六条", "text": "从事使用高毒物品作业的用人单位，应当配备应急救援人员和必要的应急救援器材、设备，制定事故应急救援预案，并根据实际情况变化对应急救援预案适时进行修订，定期组织演练。事故应急救援预案和演练记录应当报当地卫生行政部门、应急管理部门和公安部门备案。 第三章 劳动过程的防护"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第十七条", "text": "用人单位应当依照职业病防治法的有关规定，采取有效的职业卫生防护管理措施，加强劳动过程中的防护与管理。 从事使用高毒物品作业的用人单位，应当配备专职的或者兼职的职业卫生医师和护士；不具备配备专职的或者兼职的职业卫生医师和护士条件的，应当与依法取得资质认证的职业卫生技术服务机构签订合同，由其提供职业卫生服务。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第十八条", "text": "用人单位应当与劳动者订立劳动合同，将工作过程中可能产生的职业中毒危害及其后果、职业中毒危害防护措施和待遇等如实告知劳动者，并在劳动合同中写明，不得隐瞒或者欺骗。 劳动者在已订立劳动合同期间因工作岗位或者工作内容变更，从事劳动合同中未告知的存在职业中毒危害的作业时，用人单位应当依照前款规定，如实告知劳动者，并协商变更原劳动合同有关条款。 用人单位违反前两款规定的，劳动者有权拒绝从事存在职业中毒危害的作业，用人单位不得因此单方面解除或者终止与劳动者所订立的劳动合同。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第十九条", "text": "用人单位有关管理人员应当熟悉有关职业病防治的法律、法规以及确保劳动者安全使用有毒物品作业的知识。 用人单位应当对劳动者进行上岗前的职业卫生培训和在岗期间的定期职业卫生培训，普及有关职业卫生知识，督促劳动者遵守有关法律、法规和操作规程，指导劳动者正确使用职业中毒危害防护设备和个人使用的职业中毒危害防护用品。 劳动者经培训考核合格，方可上岗作业。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第二十条", "text": "用人单位应当确保职业中毒危害防护设备、应急救援设施、通讯报警装置处于正常适用状态，不得擅自拆除或者停止运行。 用人单位应当对前款所列设施进行经常性的维护、检修，定期检测其性能和效果，确保其处于良好运行状态。 职业中毒危害防护设备、应急救援设施和通讯报警装置处于不正常状态时，用人单位应当立即停止使用有毒物品作业；恢复正常状态后，方可重新作业。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第二十一条", "text": "用人单位应当为从事使用有毒物品作业的劳动者提供符合国家职业卫生标准的防护用品，并确保劳动者正确使用。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第二十二条", "text": "有毒物品必须附具说明书，如实载明产品特性、主要成分、存在的职业中毒危害因素、可能产生的危害后果、安全使用注意事项、职业中毒危害防护以及应急救治措施等内容；没有说明书或者说明书不符合要求的，不得向用人单位销售。 用人单位有权向生产、经营有毒物品的单位索取说明书。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第二十三条", "text": "有毒物品的包装应当符合国家标准，并以易于劳动者理解的方式加贴或者拴挂有毒物品安全标签。有毒物品的包装必须有醒目的警示标识和中文警示说明。 经营、使用有毒物品的单位，不得经营、使用没有安全标签、警示标识和中文警示说明的有毒物品。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第二十四条", "text": "用人单位维护、检修存在高毒物品的生产装置，必须事先制订维护、检修方案，明确职业中毒危害防护措施，确保维护、检修人员的生命安全和身体健康。 维护、检修存在高毒物品的生产装置，必须严格按照维护、检修方案和操作规程进行。维护、检修现场应当有专人监护，并设置警示标志。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第二十五条", "text": "需要进入存在高毒物品的设备、容器或者狭窄封闭场所作业时，用人单位应当事先采取下列措施： （一）保持作业场所良好的通风状态，确保作业场所职业中毒危害因素浓度符合国家职业卫生标准； （二）为劳动者配备符合国家职业卫生标准的防护用品； （三）设置现场监护人员和现场救援设备。 未采取前款规定措施或者采取的措施不符合要求的，用人单位不得安排劳动者进入存在高毒物品的设备、容器或者狭窄封闭场所作业。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第二十六条", "text": "用人单位应当按照国务院卫生行政部门的规定，定期对使用有毒物品作业场所职业中毒危害因素进行检测、评价。检测、评价结果存入用人单位职业卫生档案，定期向所在地卫生行政部门报告并向劳动者公布。 从事使用高毒物品作业的用人单位应当至少每一个月对高毒作业场所进行一次职业中毒危害因素检测；至少每半年进行一次职业中毒危害控制效果评价。 高毒作业场所职业中毒危害因素不符合国家职业卫生标准和卫生要求时，用人单位必须立即停止高毒作业，并采取相应的治理措施；经治理，职业中毒危害因素符合国家职业卫生标准和卫生要求的，方可重新作业。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第二十七条", "text": "从事使用高毒物品作业的用人单位应当设置淋浴间和更衣室，并设置清洗、存放或者处理从事使用高毒物品作业劳动者的工作服、工作鞋帽等物品的专用间。 劳动者结束作业时，其使用的工作服、工作鞋帽等物品必须存放在高毒作业区域内，不得穿戴到非高毒作业区域。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第二十八条", "text": "用人单位应当按照规定对从事使用高毒物品作业的劳动者进行岗位轮换。 用人单位应当为从事使用高毒物品作业的劳动者提供岗位津贴。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第二十九条", "text": "用人单位转产、停产、停业或者解散、破产的，应当采取有效措施，妥善处理留存或者残留有毒物品的设备、包装物和容器。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第三十条", "text": "用人单位应当对本单位执行本条例规定的情况进行经常性的监督检查；发现问题，应当及时依照本条例规定的要求进行处理。 第四章 职业健康监护"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第三十一条", "text": "用人单位应当组织从事使用有毒物品作业的劳动者进行上岗前职业健康检查。 用人单位不得安排未经上岗前职业健康检查的劳动者从事使用有毒物品的作业，不得安排有职业禁忌的劳动者从事其所禁忌的作业。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第三十二条", "text": "用人单位应当对从事使用有毒物品作业的劳动者进行定期职业健康检查。 用人单位发现有职业禁忌或者有与所从事职业相关的健康损害的劳动者，应当将其及时调离原工作岗位，并妥善安置。 用人单位对需要复查和医学观察的劳动者，应当按照体检机构的要求安排其复查和医学观察。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第三十三条", "text": "用人单位应当对从事使用有毒物品作业的劳动者进行离岗时的职业健康检查；对离岗时未进行职业健康检查的劳动者，不得解除或者终止与其订立的劳动合同。 用人单位发生分立、合并、解散、破产等情形的，应当对从事使用有毒物品作业的劳动者进行健康检查，并按照国家有关规定妥善安置职业病病人。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第三十四条", "text": "用人单位对受到或者可能受到急性职业中毒危害的劳动者，应当及时组织进行健康检查和医学观察。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第三十五条", "text": "劳动者职业健康检查和医学观察的费用，由用人单位承担。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第三十六条", "text": "用人单位应当建立职业健康监护档案。 职业健康监护档案应当包括下列内容： （一）劳动者的职业史和职业中毒危害接触史； （二）相应作业场所职业中毒危害因素监测结果； （三）职业健康检查结果及处理情况； （四）职业病诊疗等劳动者健康资料。 第五章 劳动者的权利与义务"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第三十七条", "text": "从事使用有毒物品作业的劳动者在存在威胁生命安全或者身体健康危险的情况下，有权通知用人单位并从使用有毒物品造成的危险现场撤离。 用人单位不得因劳动者依据前款规定行使权利，而取消或者减少劳动者在正常工作时享有的工资、福利待遇。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第三十八条", "text": "劳动者享有下列职业卫生保护权利： （一）获得职业卫生教育、培训； （二）获得职业健康检查、职业病诊疗、康复等职业病防治服务； （三）了解工作场所产生或者可能产生的职业中毒危害因素、危害后果和应当采取的职业中毒危害防护措施； （四）要求用人单位提供符合防治职业病要求的职业中毒危害防护设施和个人使用的职业中毒危害防护用品，改善工作条件； （五）对违反职业病防治法律、法规，危及生命、健康的行为提出批评、检举和控告； （六）拒绝违章指挥和强令进行没有职业中毒危害防护措施的作业； （七）参与用人单位职业卫生工作的民主管理，对职业病防治工作提出意见和建议。 用人单位应当保障劳动者行使前款所列权利。禁止因劳动者依法行使正当权利而降低其工资、福利等待遇或者解除、终止与其订立的劳动合同。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第三十九条", "text": "劳动者有权在正式上岗前从用人单位获得下列资料： （一）作业场所使用的有毒物品的特性、有害成分、预防措施、教育和培训资料； （二）有毒物品的标签、标识及有关资料； （三）有毒物品安全使用说明书； （四）可能影响安全使用有毒物品的其他有关资料。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第四十条", "text": "劳动者有权查阅、复印其本人职业健康监护档案。 劳动者离开用人单位时，有权索取本人健康监护档案复印件；用人单位应当如实、无偿提供，并在所提供的复印件上签章。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第四十一条", "text": "用人单位按照国家规定参加工伤保险的，患职业病的劳动者有权按照国家有关工伤保险的规定，享受下列工伤保险待遇： （一）医疗费：因患职业病进行诊疗所需费用，由工伤保险基金按照规定标准支付； （二）住院伙食补助费：由用人单位按照当地因公出差伙食标准的一定比例支付； （三）康复费：由工伤保险基金按照规定标准支付； （四）残疾用具费：因残疾需要配置辅助器具的，所需费用由工伤保险基金按照普及型辅助器具标准支付； （五）停工留薪期待遇：原工资、福利待遇不变，由用人单位支付； （六）生活护理补助费：经评残并确认需要生活护理的，生活护理补助费由工伤保险基金按照规定标准支付； （七）一次性伤残补助金：经鉴定为十级至一级伤残的，按照伤残等级享受相当于6个月至24个月的本人工资的一次性伤残补助金，由工伤保险基金支付； （八）伤残津贴：经鉴定为四级至一级伤残的，按照规定享受相当于本人工资75%至90%的伤残津贴，由工伤保险基金支付； （九）死亡补助金：因职业中毒死亡的，由工伤保险基金按照不低于48个月的统筹地区上年度职工月平均工资的标准一次支付； （十）丧葬补助金：因职业中毒死亡的，由工伤保险基金按照6个月的统筹地区上年度职工月平均工资的标准一次支付； （十一）供养亲属抚恤金：因职业中毒死亡的，对由死者生前提供主要生活来源的亲属由工伤保险基金支付抚恤金：对其配偶每月按照统筹地区上年度职工月平均工资的40%发给，对其生前供养的直系亲属每人每月按照统筹地区上年度职工月平均工资的30%发给； （十二）国家规定的其他工伤保险待遇。 本条例施行后，国家对工伤保险待遇的项目和标准作出调整时，从其规定。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第四十二条", "text": "用人单位未参加工伤保险的，其劳动者从事有毒物品作业患职业病的，用人单位应当按照国家有关工伤保险规定的项目和标准，保证劳动者享受工伤待遇。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第四十三条", "text": "用人单位无营业执照以及被依法吊销营业执照，其劳动者从事使用有毒物品作业患职业病的，应当按照国家有关工伤保险规定的项目和标准，给予劳动者一次性赔偿。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第四十四条", "text": "用人单位分立、合并的，承继单位应当承担由原用人单位对患职业病的劳动者承担的补偿责任。 用人单位解散、破产的，应当依法从其清算财产中优先支付患职业病的劳动者的补偿费用。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第四十五条", "text": "劳动者除依法享有工伤保险外，依照有关民事法律的规定，尚有获得赔偿的权利的，有权向用人单位提出赔偿要求。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第四十六条", "text": "劳动者应当学习和掌握相关职业卫生知识，遵守有关劳动保护的法律、法规和操作规程，正确使用和维护职业中毒危害防护设施及其用品；发现职业中毒事故隐患时，应当及时报告。 作业场所出现使用有毒物品产生的危险时，劳动者应当采取必要措施，按照规定正确使用防护设施，将危险加以消除或者减少到最低限度。 第六章 监督管理"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第四十七条", "text": "县级以上人民政府卫生行政、疾病预防控制部门应当依照本条例的规定和国家有关职业卫生要求，依据职责划分，对作业场所使用有毒物品作业及职业中毒危害检测、评价活动进行监督检查。 卫生行政、疾病预防控制部门实施监督检查，不得收取费用，不得接受用人单位的财物或者其他利益。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第四十八条", "text": "卫生行政、疾病预防控制部门应当建立、健全监督制度，核查反映用人单位有关劳动保护的材料，履行监督责任。 用人单位应当向卫生行政、疾病预防控制部门如实、具体提供反映有关劳动保护的材料；必要时，卫生行政、疾病预防控制部门可以查阅或者要求用人单位报送有关材料。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第四十九条", "text": "卫生行政、疾病预防控制部门应当监督用人单位严格执行有关职业卫生规范。 卫生行政、疾病预防控制部门应当依照本条例的规定对使用有毒物品作业场所的职业卫生防护设备、设施的防护性能进行定期检验和不定期的抽查；发现职业卫生防护设备、设施存在隐患时，应当责令用人单位立即消除隐患；消除隐患期间，应当责令其停止作业。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第五十条", "text": "卫生行政、疾病预防控制部门应当采取措施，鼓励对用人单位的违法行为进行举报、投诉、检举和控告。 卫生行政、疾病预防控制部门对举报、投诉、检举和控告应当及时核实，依法作出处理，并将处理结果予以公布。 卫生行政、疾病预防控制部门对举报人、投诉人、检举人和控告人负有保密的义务。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第五十一条", "text": "职业卫生监督执法人员依法执行职务时，应当出示执法证件。 职业卫生监督执法人员应当忠于职守，秉公执法；涉及用人单位秘密的，应当为其保密。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第五十二条", "text": "疾病预防控制部门依法实施罚款的行政处罚，应当依照有关法律、行政法规的规定，实施罚款决定与罚款收缴分离；收缴的罚款以及依法没收的经营所得，必须全部上缴国库。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第五十三条", "text": "卫生行政、疾病预防控制部门履行监督检查职责时，有权采取下列措施： （一）进入用人单位和使用有毒物品作业场所现场，了解情况，调查取证，进行抽样检查、检测、检验，进行实地检查； （二）查阅或者复制与违反本条例行为有关的资料，采集样品； （三）责令违反本条例规定的单位和个人停止违法行为。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第五十四条", "text": "发生职业中毒事故或者有证据证明职业中毒危害状态可能导致事故发生时，卫生行政、疾病预防控制部门有权采取下列临时控制措施： （一）责令暂停导致职业中毒事故的作业； （二）封存造成职业中毒事故或者可能导致事故发生的物品； （三）组织控制职业中毒事故现场。 在职业中毒事故或者危害状态得到有效控制后，卫生行政、疾病预防控制部门应当及时解除控制措施。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第五十五条", "text": "职业卫生监督执法人员依法执行职务时，被检查单位应当接受检查并予以支持、配合，不得拒绝和阻碍。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第五十六条", "text": "疾病预防控制部门应当加强队伍建设，提高职业卫生监督执法人员的政治、业务素质，依照本条例的规定，建立、健全内部监督制度，对职业卫生监督执法人员执行法律、法规和遵守纪律的情况进行监督检查。 第七章 罚 则"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第五十七条", "text": "卫生行政、疾病预防控制部门的工作人员有下列行为之一，导致职业中毒事故发生的，依照刑法关于滥用职权罪、玩忽职守罪或者其他罪的规定，依法追究刑事责任；造成职业中毒危害但尚未导致职业中毒事故发生，不够刑事处罚的，根据不同情节，依法给予降级、撤职或者开除的处分： （一）对用人单位不履行监督检查职责，或者发现用人单位存在违反本条例的行为不予查处的； （二）发现用人单位存在职业中毒危害，可能造成职业中毒事故，不及时依法采取控制措施的。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第五十八条", "text": "用人单位违反本条例的规定，有下列情形之一的，由疾病预防控制部门给予警告，责令限期改正；逾期不改正的，处10万元以上50万元以下的罚款；情节严重的，提请有关人民政府按照国务院规定的权限责令停建、予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大劳动安全事故罪或者其他罪的规定，依法追究刑事责任： （一）可能产生职业中毒危害的建设项目，未依照职业病防治法的规定进行职业中毒危害预评价的； （二）职业中毒危害防护设施未与主体工程同时设计，同时施工，同时投入生产和使用的； （三）建设项目竣工验收前，未进行职业中毒危害控制效果评价，或者职业中毒危害防护设施未经依法组织验收合格，擅自投入生产和使用的； （四）可能产生职业中毒危害的建设项目，其职业中毒危害防护设施设计不符合国家职业卫生标准和卫生要求的。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第五十九条", "text": "用人单位违反本条例的规定，有下列情形之一的，由疾病预防控制部门给予警告，责令限期改正；逾期不改正的，处5万元以上20万元以下的罚款；情节严重的，提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大劳动安全事故罪或者其他罪的规定，依法追究刑事责任： （一）使用有毒物品作业场所未按照规定设置警示标识和中文警示说明的； （二）未对职业卫生防护设备、应急救援设施、通讯报警装置进行维护、检修和定期检测，导致上述设施处于不正常状态的； （三）未依照本条例的规定进行职业中毒危害因素检测和职业中毒危害控制效果评价的； （四）未向从事使用有毒物品作业的劳动者提供符合国家职业卫生标准的防护用品，或者未保证劳动者正确使用的。 用人单位违反本条例的规定，有下列情形之一的，由疾病预防控制部门给予警告，责令限期改正，处5万元以上20万元以下的罚款；逾期不改正的，提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大劳动安全事故罪或者其他罪的规定，依法追究刑事责任： （一）高毒作业场所未按照规定设置撤离通道和泄险区的； （二）高毒作业场所未按照规定设置警示线的。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第六十条", "text": "用人单位违反本条例的规定，有下列情形之一的，由疾病预防控制部门给予警告，责令限期改正，处5万元以上30万元以下的罚款；逾期不改正的，提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大责任事故罪、重大劳动安全事故罪或者其他罪的规定，依法追究刑事责任： （一）使用有毒物品作业场所未设置有效通风装置的，或者可能突然泄漏大量有毒物品或者易造成急性中毒的作业场所未设置自动报警装置或者事故通风设施的； （二）职业卫生防护设备、应急救援设施、通讯报警装置处于不正常状态而不停止作业，或者擅自拆除或者停止运行职业卫生防护设备、应急救援设施、通讯报警装置的。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第六十一条", "text": "从事使用高毒物品作业的用人单位违反本条例的规定，有下列行为之一的，由疾病预防控制部门给予警告，责令限期改正，处5万元以上20万元以下的罚款；逾期不改正的，提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大责任事故罪或者其他罪的规定，依法追究刑事责任： （一）作业场所职业中毒危害因素不符合国家职业卫生标准和卫生要求而不立即停止高毒作业并采取相应的治理措施的，或者职业中毒危害因素治理不符合国家职业卫生标准和卫生要求重新作业的； （二）未依照本条例的规定维护、检修存在高毒物品的生产装置的； （三）未采取本条例规定的措施，安排劳动者进入存在高毒物品的设备、容器或者狭窄封闭场所作业的。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第六十二条", "text": "在作业场所使用国家明令禁止使用的有毒物品或者使用不符合国家标准的有毒物品的，由疾病预防控制部门责令立即停止使用，处5万元以上30万元以下的罚款；情节严重的，责令停止使用有毒物品作业，或者提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于危险物品肇事罪、重大责任事故罪或者其他罪的规定，依法追究刑事责任。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第六十三条", "text": "用人单位违反本条例的规定，有下列行为之一的，由疾病预防控制部门责令限期改正，处5万元以上30万元以下的罚款；情节严重的，责令停止使用有毒物品作业，或者提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大责任事故罪或者其他罪的规定，依法追究刑事责任： （一）未组织从事使用有毒物品作业的劳动者进行上岗前职业健康检查，安排未经上岗前职业健康检查的劳动者从事使用有毒物品作业的； （二）使用未经培训考核合格的劳动者从事高毒作业的； （三）安排有职业禁忌的劳动者从事所禁忌的作业的； （四）发现有职业禁忌或者有与所从事职业相关的健康损害的劳动者，未及时调离原工作岗位，并妥善安置的； （五）安排未成年人或者孕期、哺乳期的女职工从事使用有毒物品作业的； （六）使用童工的。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第六十四条", "text": "从事使用有毒物品作业的用人单位违反本条例的规定，在转产、停产、停业或者解散、破产时未采取有效措施，妥善处理留存或者残留高毒物品的设备、包装物和容器的，由疾病预防控制部门责令改正，处2万元以上10万元以下的罚款；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于污染环境罪、危险物品肇事罪或者其他罪的规定，依法追究刑事责任。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第六十五条", "text": "用人单位违反本条例的规定，有下列情形之一的，由疾病预防控制部门给予警告，责令限期改正，处5000元以上2万元以下的罚款；逾期不改正的，责令停止使用有毒物品作业，或者提请有关人民政府按照国务院规定的权限予以关闭；造成严重职业中毒危害或者导致职业中毒事故发生的，对负有责任的主管人员和其他直接责任人员依照刑法关于重大劳动安全事故罪、危险物品肇事罪或者其他罪的规定，依法追究刑事责任： （一）使用有毒物品作业场所未与生活场所分开或者在作业场所住人的； （二）未将有害作业与无害作业分开的； （三）高毒作业场所未与其他作业场所有效隔离的； （四）从事高毒作业未按照规定配备应急救援设施或者制定事故应急救援预案的。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第六十六条", "text": "用人单位违反本条例的规定，有下列情形之一的，由疾病预防控制部门给予警告，责令限期改正，处2万元以上5万元以下的罚款；逾期不改正的，提请有关人民政府按照国务院规定的权限予以关闭： （一）未按照规定向卫生行政部门申报高毒作业项目的； （二）变更使用高毒物品品种，未按照规定向原受理申报的卫生行政部门重新申报，或者申报不及时、有虚假的。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第六十七条", "text": "用人单位违反本条例的规定，有下列行为之一的，由疾病预防控制部门给予警告，责令限期改正，可以并处5万元以上10万元以下的罚款；逾期不改正的，责令停止使用有毒物品作业，或者提请有关人民政府按照国务院规定的权限予以关闭： （一）未组织从事使用有毒物品作业的劳动者进行定期职业健康检查的； （二）未组织从事使用有毒物品作业的劳动者进行离岗职业健康检查的； （三）对未进行离岗职业健康检查的劳动者，解除或者终止与其订立的劳动合同的； （四）发生分立、合并、解散、破产情形，未对从事使用有毒物品作业的劳动者进行健康检查，并按照国家有关规定妥善安置职业病病人的； （五）对受到或者可能受到急性职业中毒危害的劳动者，未及时组织进行健康检查和医学观察的； （六）未建立职业健康监护档案的； （七）劳动者离开用人单位时，用人单位未如实、无偿提供职业健康监护档案的； （八）未依照职业病防治法和本条例的规定将工作过程中可能产生的职业中毒危害及其后果、有关职业卫生防护措施和待遇等如实告知劳动者并在劳动合同中写明的； （九）劳动者在存在威胁生命、健康危险的情况下，从危险现场中撤离，而被取消或者减少应当享有的待遇的。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第六十八条", "text": "用人单位违反本条例的规定，有下列行为之一的，由疾病预防控制部门给予警告，责令限期改正，处5000元以上2万元以下的罚款；逾期不改正的，责令停止使用有毒物品作业，或者提请有关人民政府按照国务院规定的权限予以关闭： （一）未按照规定配备或者聘请职业卫生医师和护士的； （二）未为从事使用高毒物品作业的劳动者设置淋浴间、更衣室或者未设置清洗、存放和处理工作服、工作鞋帽等物品的专用间，或者不能正常使用的； （三）未安排从事使用高毒物品作业一定年限的劳动者进行岗位轮换的。 第八章 附 则"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第六十九条", "text": "涉及作业场所使用有毒物品可能产生职业中毒危害的劳动保护的有关事项，本条例未作规定的，依照职业病防治法和其他有关法律、行政法规的规定执行。 有毒物品的生产、经营、储存、运输、使用和废弃处置的安全管理，依照危险化学品安全管理条例执行。"}, {"law": "使用有毒物品作业场所劳动保护条例_20241206.docx", "no": "第七十条", "text": "本条例自公布之日起施行。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第一条", "text": "为了加强危险化学品的安全管理，预防和减少危险化学品事故，保障人民群众生命财产安全，保护环境，制定本条例。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二条", "text": "危险化学品生产、储存、使用、经营和运输的安全管理，适用本条例。 废弃危险化学品的处置，依照有关环境保护的法律、行政法规和国家有关规定执行。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三条", "text": "本条例所称危险化学品，是指具有毒害、腐蚀、爆炸、燃烧、助燃等性质，对人体、设施、环境具有危害的剧毒化学品和其他化学品。 危险化学品目录，由国务院安全生产监督管理部门会同国务院工业和信息化、公安、环境保护、卫生、质量监督检验检疫、交通运输、铁路、民用航空、农业主管部门，根据化学品危险特性的鉴别和分类标准确定、公布，并适时调整。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第四条", "text": "危险化学品安全管理，应当坚持安全第一、预防为主、综合治理的方针，强化和落实企业的主体责任。 生产、储存、使用、经营、运输危险化学品的单位(以下统称危险化学品单位)的主要负责人对本单位的危险化学品安全管理工作全面负责。 危险化学品单位应当具备法律、行政法规规定和国家标准、行业标准要求的安全条件，建立、健全安全管理规章制度和岗位安全责任制度，对从业人员进行安全教育、法制教育和岗位技术培训。从业人员应当接受教育和培训，考核合格后上岗作业；对有资格要求的岗位，应当配备依法取得相应资格的人员。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第五条", "text": "任何单位和个人不得生产、经营、使用国家禁止生产、经营、使用的危险化学品。 国家对危险化学品的使用有限制性规定的，任何单位和个人不得违反限制性规定使用危险化学品。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第六条", "text": "对危险化学品的生产、储存、使用、经营、运输实施安全监督管理的有关部门(以下统称负有危险化学品安全监督管理职责的部门)，依照下列规定履行职责： (一)安全生产监督管理部门负责危险化学品安全监督管理综合工作，组织确定、公布、调整危险化学品目录，对新建、改建、扩建生产、储存危险化学品(包括使用长输管道输送危险化学品，下同)的建设项目进行安全条件审查，核发危险化学品安全生产许可证、危险化学品安全使用许可证和危险化学品经营许可证，并负责危险化学品登记工作。 (二)公安机关负责危险化学品的公共安全管理，核发剧毒化学品购买许可证、剧毒化学品道路运输通行证，并负责危险化学品运输车辆的道路交通安全管理。 (三)质量监督检验检疫部门负责核发危险化学品及其包装物、容器(不包括储存危险化学品的固定式大型储罐，下同)生产企业的工业产品生产许可证，并依法对其产品质量实施监督，负责对进出口危险化学品及其包装实施检验。 (四)环境保护主管部门负责废弃危险化学品处置的监督管理，组织危险化学品的环境危害性鉴定和环境风险程度评估，确定实施重点环境管理的危险化学品，负责危险化学品环境管理登记和新化学物质环境管理登记；依照职责分工调查相关危险化学品环境污染事故和生态破坏事件，负责危险化学品事故现场的应急环境监测。 (五)交通运输主管部门负责危险化学品道路运输、水路运输的许可以及运输工具的安全管理，对危险化学品水路运输安全实施监督，负责危险化学品道路运输企业、水路运输企业驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员的资格认定。铁路监管部门负责危险化学品铁路运输及其运输工具的安全管理。民用航空主管部门负责危险化学品航空运输以及航空运输企业及其运输工具的安全管理。 (六)卫生主管部门负责危险化学品毒性鉴定的管理，负责组织、协调危险化学品事故受伤人员的医疗卫生救援工作。 (七)工商行政管理部门依据有关部门的许可证件，核发危险化学品生产、储存、经营、运输企业营业执照，查处危险化学品经营企业违法采购危险化学品的行为。 (八)邮政管理部门负责依法查处寄递危险化学品的行为。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第七条", "text": "负有危险化学品安全监督管理职责的部门依法进行监督检查，可以采取下列措施： (一)进入危险化学品作业场所实施现场检查，向有关单位和人员了解情况，查阅、复制有关文件、资料； (二)发现危险化学品事故隐患，责令立即消除或者限期消除； (三)对不符合法律、行政法规、规章规定或者国家标准、行业标准要求的设施、设备、装置、器材、运输工具，责令立即停止使用； (四)经本部门主要负责人批准，查封违法生产、储存、使用、经营危险化学品的场所，扣押违法生产、储存、使用、经营、运输的危险化学品以及用于违法生产、使用、运输危险化学品的原材料、设备、运输工具； (五)发现影响危险化学品安全的违法行为，当场予以纠正或者责令限期改正。 负有危险化学品安全监督管理职责的部门依法进行监督检查，监督检查人员不得少于2人，并应当出示执法证件；有关单位和个人对依法进行的监督检查应当予以配合，不得拒绝、阻碍。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第八条", "text": "县级以上人民政府应当建立危险化学品安全监督管理工作协调机制，支持、督促负有危险化学品安全监督管理职责的部门依法履行职责，协调、解决危险化学品安全监督管理工作中的重大问题。 负有危险化学品安全监督管理职责的部门应当相互配合、密切协作，依法加强对危险化学品的安全监督管理。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第九条", "text": "任何单位和个人对违反本条例规定的行为，有权向负有危险化学品安全监督管理职责的部门举报。负有危险化学品安全监督管理职责的部门接到举报，应当及时依法处理；对不属于本部门职责的，应当及时移送有关部门处理。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第十条", "text": "国家鼓励危险化学品生产企业和使用危险化学品从事生产的企业采用有利于提高安全保障水平的先进技术、工艺、设备以及自动控制系统，鼓励对危险化学品实行专门储存、统一配送、集中销售。 第二章 生产、储存安全"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第十一条", "text": "国家对危险化学品的生产、储存实行统筹规划、合理布局。 国务院工业和信息化主管部门以及国务院其他有关部门依据各自职责，负责危险化学品生产、储存的行业规划和布局。 地方人民政府组织编制城乡规划，应当根据本地区的实际情况，按照确保安全的原则，规划适当区域专门用于危险化学品的生产、储存。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第十二条", "text": "新建、改建、扩建生产、储存危险化学品的建设项目(以下简称建设项目)，应当由安全生产监督管理部门进行安全条件审查。 建设单位应当对建设项目进行安全条件论证，委托具备国家规定的资质条件的机构对建设项目进行安全评价，并将安全条件论证和安全评价的情况报告报建设项目所在地设区的市级以上人民政府安全生产监督管理部门；安全生产监督管理部门应当自收到报告之日起45日内作出审查决定，并书面通知建设单位。具体办法由国务院安全生产监督管理部门制定。 新建、改建、扩建储存、装卸危险化学品的港口建设项目，由港口行政管理部门按照国务院交通运输主管部门的规定进行安全条件审查。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第十三条", "text": "生产、储存危险化学品的单位，应当对其铺设的危险化学品管道设置明显标志，并对危险化学品管道定期检查、检测。 进行可能危及危险化学品管道安全的施工作业，施工单位应当在开工的7日前书面通知管道所属单位，并与管道所属单位共同制定应急预案，采取相应的安全防护措施。管道所属单位应当指派专门人员到现场进行管道安全保护指导。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第十四条", "text": "危险化学品生产企业进行生产前，应当依照《安全生产许可证条例》的规定，取得危险化学品安全生产许可证。 生产列入国家实行生产许可证制度的工业产品目录的危险化学品的企业，应当依照《中华人民共和国工业产品生产许可证管理条例》的规定，取得工业产品生产许可证。 负责颁发危险化学品安全生产许可证、工业产品生产许可证的部门，应当将其颁发许可证的情况及时向同级工业和信息化主管部门、环境保护主管部门和公安机关通报。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第十五条", "text": "危险化学品生产企业应当提供与其生产的危险化学品相符的化学品安全技术说明书，并在危险化学品包装(包括外包装件)上粘贴或者拴挂与包装内危险化学品相符的化学品安全标签。化学品安全技术说明书和化学品安全标签所载明的内容应当符合国家标准的要求。 危险化学品生产企业发现其生产的危险化学品有新的危险特性的，应当立即公告，并及时修订其化学品安全技术说明书和化学品安全标签。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第十六条", "text": "生产实施重点环境管理的危险化学品的企业，应当按照国务院环境保护主管部门的规定，将该危险化学品向环境中释放等相关信息向环境保护主管部门报告。环境保护主管部门可以根据情况采取相应的环境风险控制措施。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第十七条", "text": "危险化学品的包装应当符合法律、行政法规、规章的规定以及国家标准、行业标准的要求。 危险化学品包装物、容器的材质以及危险化学品包装的型式、规格、方法和单件质量(重量)，应当与所包装的危险化学品的性质和用途相适应。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第十八条", "text": "生产列入国家实行生产许可证制度的工业产品目录的危险化学品包装物、容器的企业，应当依照《中华人民共和国工业产品生产许可证管理条例》的规定，取得工业产品生产许可证；其生产的危险化学品包装物、容器经国务院质量监督检验检疫部门认定的检验机构检验合格，方可出厂销售。 运输危险化学品的船舶及其配载的容器，应当按照国家船舶检验规范进行生产，并经海事管理机构认定的船舶检验机构检验合格，方可投入使用。 对重复使用的危险化学品包装物、容器，使用单位在重复使用前应当进行检查；发现存在安全隐患的，应当维修或者更换。使用单位应当对检查情况作出记录，记录的保存期限不得少于2年。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第十九条", "text": "危险化学品生产装置或者储存数量构成重大危险源的危险化学品储存设施(运输工具加油站、加气站除外)，与下列场所、设施、区域的距离应当符合国家有关规定： (一)居住区以及商业中心、公园等人员密集场所； (二)学校、医院、影剧院、体育场(馆)等公共设施； (三)饮用水源、水厂以及水源保护区； (四)车站、码头(依法经许可从事危险化学品装卸作业的除外)、机场以及通信干线、通信枢纽、铁路线路、道路交通干线、水路交通干线、地铁风亭以及地铁站出入口； (五)基本农田保护区、基本草原、畜禽遗传资源保护区、畜禽规模化养殖场(养殖小区)、渔业水域以及种子、种畜禽、水产苗种生产基地； (六)河流、湖泊、风景名胜区、自然保护区； (七)军事禁区、军事管理区； (八)法律、行政法规规定的其他场所、设施、区域。 已建的危险化学品生产装置或者储存数量构成重大危险源的危险化学品储存设施不符合前款规定的，由所在地设区的市级人民政府安全生产监督管理部门会同有关部门监督其所属单位在规定期限内进行整改；需要转产、停产、搬迁、关闭的，由本级人民政府决定并组织实施。 储存数量构成重大危险源的危险化学品储存设施的选址，应当避开地震活动断层和容易发生洪灾、地质灾害的区域。 本条例所称重大危险源，是指生产、储存、使用或者搬运危险化学品，且危险化学品的数量等于或者超过临界量的单元(包括场所和设施)。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十条", "text": "生产、储存危险化学品的单位，应当根据其生产、储存的危险化学品的种类和危险特性，在作业场所设置相应的监测、监控、通风、防晒、调温、防火、灭火、防爆、泄压、防毒、中和、防潮、防雷、防静电、防腐、防泄漏以及防护围堤或者隔离操作等安全设施、设备，并按照国家标准、行业标准或者国家有关规定对安全设施、设备进行经常性维护、保养，保证安全设施、设备的正常使用。 生产、储存危险化学品的单位，应当在其作业场所和安全设施、设备上设置明显的安全警示标志。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十一条", "text": "生产、储存危险化学品的单位，应当在其作业场所设置通信、报警装置，并保证处于适用状态。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十二条", "text": "生产、储存危险化学品的企业，应当委托具备国家规定的资质条件的机构，对本企业的安全生产条件每3年进行一次安全评价，提出安全评价报告。安全评价报告的内容应当包括对安全生产条件存在的问题进行整改的方案。 生产、储存危险化学品的企业，应当将安全评价报告以及整改方案的落实情况报所在地县级人民政府安全生产监督管理部门备案。在港区内储存危险化学品的企业，应当将安全评价报告以及整改方案的落实情况报港口行政管理部门备案。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十三条", "text": "生产、储存剧毒化学品或者国务院公安部门规定的可用于制造爆炸物品的危险化学品(以下简称易制爆危险化学品)的单位，应当如实记录其生产、储存的剧毒化学品、易制爆危险化学品的数量、流向，并采取必要的安全防范措施，防止剧毒化学品、易制爆危险化学品丢失或者被盗；发现剧毒化学品、易制爆危险化学品丢失或者被盗的，应当立即向当地公安机关报告。 生产、储存剧毒化学品、易制爆危险化学品的单位，应当设置治安保卫机构，配备专职治安保卫人员。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十四条", "text": "危险化学品应当储存在专用仓库、专用场地或者专用储存室(以下统称专用仓库)内，并由专人负责管理；剧毒化学品以及储存数量构成重大危险源的其他危险化学品，应当在专用仓库内单独存放，并实行双人收发、双人保管制度。 危险化学品的储存方式、方法以及储存数量应当符合国家标准或者国家有关规定。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十五条", "text": "储存危险化学品的单位应当建立危险化学品出入库核查、登记制度。 对剧毒化学品以及储存数量构成重大危险源的其他危险化学品，储存单位应当将其储存数量、储存地点以及管理人员的情况，报所在地县级人民政府安全生产监督管理部门(在港区内储存的，报港口行政管理部门)和公安机关备案。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十六条", "text": "危险化学品专用仓库应当符合国家标准、行业标准的要求，并设置明显的标志。储存剧毒化学品、易制爆危险化学品的专用仓库，应当按照国家有关规定设置相应的技术防范设施。 储存危险化学品的单位应当对其危险化学品专用仓库的安全设施、设备定期进行检测、检验。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十七条", "text": "生产、储存危险化学品的单位转产、停产、停业或者解散的，应当采取有效措施，及时、妥善处置其危险化学品生产装置、储存设施以及库存的危险化学品，不得丢弃危险化学品；处置方案应当报所在地县级人民政府安全生产监督管理部门、工业和信息化主管部门、环境保护主管部门和公安机关备案。安全生产监督管理部门应当会同环境保护主管部门和公安机关对处置情况进行监督检查，发现未依照规定处置的，应当责令其立即处置。 第三章 使用安全"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十八条", "text": "使用危险化学品的单位，其使用条件(包括工艺)应当符合法律、行政法规的规定和国家标准、行业标准的要求，并根据所使用的危险化学品的种类、危险特性以及使用量和使用方式，建立、健全使用危险化学品的安全管理规章制度和安全操作规程，保证危险化学品的安全使用。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十九条", "text": "使用危险化学品从事生产并且使用量达到规定数量的化工企业(属于危险化学品生产企业的除外，下同)，应当依照本条例的规定取得危险化学品安全使用许可证。 前款规定的危险化学品使用量的数量标准，由国务院安全生产监督管理部门会同国务院公安部门、农业主管部门确定并公布。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十条", "text": "申请危险化学品安全使用许可证的化工企业，除应当符合本条例"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十八条", "text": "的规定外，还应当具备下列条件： (一)有与所使用的危险化学品相适应的专业技术人员； (二)有安全管理机构和专职安全管理人员； (三)有符合国家规定的危险化学品事故应急预案和必要的应急救援器材、设备； (四)依法进行了安全评价。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十一条", "text": "申请危险化学品安全使用许可证的化工企业，应当向所在地设区的市级人民政府安全生产监督管理部门提出申请，并提交其符合本条例"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十条", "text": "规定条件的证明材料。设区的市级人民政府安全生产监督管理部门应当依法进行审查，自收到证明材料之日起45日内作出批准或者不予批准的决定。予以批准的，颁发危险化学品安全使用许可证；不予批准的，书面通知申请人并说明理由。 安全生产监督管理部门应当将其颁发危险化学品安全使用许可证的情况及时向同级环境保护主管部门和公安机关通报。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第十六条", "text": "关于生产实施重点环境管理的危险化学品的企业的规定，适用于使用实施重点环境管理的危险化学品从事生产的企业；"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十七条", "text": "关于生产、储存危险化学品的单位的规定，适用于使用危险化学品的单位；"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第二十二条", "text": "关于生产、储存危险化学品的企业的规定，适用于使用危险化学品从事生产的企业。 第四章 经营安全"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十三条", "text": "国家对危险化学品经营(包括仓储经营，下同)实行许可制度。未经许可，任何单位和个人不得经营危险化学品。 依法设立的危险化学品生产企业在其厂区范围内销售本企业生产的危险化学品，不需要取得危险化学品经营许可。 依照《中华人民共和国港口法》的规定取得港口经营许可证的港口经营人，在港区内从事危险化学品仓储经营，不需要取得危险化学品经营许可。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十四条", "text": "从事危险化学品经营的企业应当具备下列条件： (一)有符合国家标准、行业标准的经营场所，储存危险化学品的，还应当有符合国家标准、行业标准的储存设施； (二)从业人员经过专业技术培训并经考核合格； (三)有健全的安全管理规章制度； (四)有专职安全管理人员； (五)有符合国家规定的危险化学品事故应急预案和必要的应急救援器材、设备； (六)法律、法规规定的其他条件。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十五条", "text": "从事剧毒化学品、易制爆危险化学品经营的企业，应当向所在地设区的市级人民政府安全生产监督管理部门提出申请，从事其他危险化学品经营的企业，应当向所在地县级人民政府安全生产监督管理部门提出申请(有储存设施的，应当向所在地设区的市级人民政府安全生产监督管理部门提出申请)。申请人应当提交其符合本条例"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十四条", "text": "规定条件的证明材料。设区的市级人民政府安全生产监督管理部门或者县级人民政府安全生产监督管理部门应当依法进行审查，并对申请人的经营场所、储存设施进行现场核查，自收到证明材料之日起30日内作出批准或者不予批准的决定。予以批准的，颁发危险化学品经营许可证；不予批准的，书面通知申请人并说明理由。 设区的市级人民政府安全生产监督管理部门和县级人民政府安全生产监督管理部门应当将其颁发危险化学品经营许可证的情况及时向同级环境保护主管部门和公安机关通报。 申请人持危险化学品经营许可证向工商行政管理部门办理登记手续后，方可从事危险化学品经营活动。法律、行政法规或者国务院规定经营危险化学品还需要经其他有关部门许可的，申请人向工商行政管理部门办理登记手续时还应当持相应的许可证件。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十六条", "text": "危险化学品经营企业储存危险化学品的，应当遵守本条例第二章关于储存危险化学品的规定。危险化学品商店内只能存放民用小包装的危险化学品。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十七条", "text": "危险化学品经营企业不得向未经许可从事危险化学品生产、经营活动的企业采购危险化学品，不得经营没有化学品安全技术说明书或者化学品安全标签的危险化学品。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十八条", "text": "依法取得危险化学品安全生产许可证、危险化学品安全使用许可证、危险化学品经营许可证的企业，凭相应的许可证件购买剧毒化学品、易制爆危险化学品。民用爆炸物品生产企业凭民用爆炸物品生产许可证购买易制爆危险化学品。 前款规定以外的单位购买剧毒化学品的，应当向所在地县级人民政府公安机关申请取得剧毒化学品购买许可证；购买易制爆危险化学品的，应当持本单位出具的合法用途说明。 个人不得购买剧毒化学品(属于剧毒化学品的农药除外)和易制爆危险化学品。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十九条", "text": "申请取得剧毒化学品购买许可证，申请人应当向所在地县级人民政府公安机关提交下列材料： (一)营业执照或者法人证书(登记证书)的复印件； (二)拟购买的剧毒化学品品种、数量的说明； (三)购买剧毒化学品用途的说明； (四)经办人的身份证明。 县级人民政府公安机关应当自收到前款规定的材料之日起3日内，作出批准或者不予批准的决定。予以批准的，颁发剧毒化学品购买许可证；不予批准的，书面通知申请人并说明理由。 剧毒化学品购买许可证管理办法由国务院公安部门制定。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第四十条", "text": "危险化学品生产企业、经营企业销售剧毒化学品、易制爆危险化学品，应当查验本条例"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十八条", "text": "第一款、第二款规定的相关许可证件或者证明文件，不得向不具有相关许可证件或者证明文件的单位销售剧毒化学品、易制爆危险化学品。对持剧毒化学品购买许可证购买剧毒化学品的，应当按照许可证载明的品种、数量销售。 禁止向个人销售剧毒化学品(属于剧毒化学品的农药除外)和易制爆危险化学品。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第四十一条", "text": "危险化学品生产企业、经营企业销售剧毒化学品、易制爆危险化学品，应当如实记录购买单位的名称、地址、经办人的姓名、身份证号码以及所购买的剧毒化学品、易制爆危险化学品的品种、数量、用途。销售记录以及经办人的身份证明复印件、相关许可证件复印件或者证明文件的保存期限不得少于1年。 剧毒化学品、易制爆危险化学品的销售企业、购买单位应当在销售、购买后5日内，将所销售、购买的剧毒化学品、易制爆危险化学品的品种、数量以及流向信息报所在地县级人民政府公安机关备案，并输入计算机系统。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第四十二条", "text": "使用剧毒化学品、易制爆危险化学品的单位不得出借、转让其购买的剧毒化学品、易制爆危险化学品；因转产、停产、搬迁、关闭等确需转让的，应当向具有本条例"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十八条", "text": "第一款、第二款规定的相关许可证件或者证明文件的单位转让，并在转让后将有关情况及时向所在地县级人民政府公安机关报告。 第五章 运输安全"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第四十三条", "text": "从事危险化学品道路运输、水路运输的，应当分别依照有关道路运输、水路运输的法律、行政法规的规定，取得危险货物道路运输许可、危险货物水路运输许可，并向工商行政管理部门办理登记手续。 危险化学品道路运输企业、水路运输企业应当配备专职安全管理人员。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第四十四条", "text": "危险化学品道路运输企业、水路运输企业的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员应当经交通运输主管部门考核合格，取得从业资格。具体办法由国务院交通运输主管部门制定。 危险化学品的装卸作业应当遵守安全作业标准、规程和制度，并在装卸管理人员的现场指挥或者监控下进行。水路运输危险化学品的集装箱装箱作业应当在集装箱装箱现场检查员的指挥或者监控下进行，并符合积载、隔离的规范和要求；装箱作业完毕后，集装箱装箱现场检查员应当签署装箱证明书。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第四十五条", "text": "运输危险化学品，应当根据危险化学品的危险特性采取相应的安全防护措施，并配备必要的防护用品和应急救援器材。 用于运输危险化学品的槽罐以及其他容器应当封口严密，能够防止危险化学品在运输过程中因温度、湿度或者压力的变化发生渗漏、洒漏；槽罐以及其他容器的溢流和泄压装置应当设置准确、起闭灵活。 运输危险化学品的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员，应当了解所运输的危险化学品的危险特性及其包装物、容器的使用要求和出现危险情况时的应急处置方法。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第四十六条", "text": "通过道路运输危险化学品的，托运人应当委托依法取得危险货物道路运输许可的企业承运。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第四十七条", "text": "通过道路运输危险化学品的，应当按照运输车辆的核定载质量装载危险化学品，不得超载。 危险化学品运输车辆应当符合国家标准要求的安全技术条件，并按照国家有关规定定期进行安全技术检验。 危险化学品运输车辆应当悬挂或者喷涂符合国家标准要求的警示标志。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第四十八条", "text": "通过道路运输危险化学品的，应当配备押运人员，并保证所运输的危险化学品处于押运人员的监控之下。 运输危险化学品途中因住宿或者发生影响正常运输的情况，需要较长时间停车的，驾驶人员、押运人员应当采取相应的安全防范措施；运输剧毒化学品或者易制爆危险化学品的，还应当向当地公安机关报告。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第四十九条", "text": "未经公安机关批准，运输危险化学品的车辆不得进入危险化学品运输车辆限制通行的区域。危险化学品运输车辆限制通行的区域由县级人民政府公安机关划定，并设置明显的标志。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第五十条", "text": "通过道路运输剧毒化学品的，托运人应当向运输始发地或者目的地县级人民政府公安机关申请剧毒化学品道路运输通行证。 申请剧毒化学品道路运输通行证，托运人应当向县级人民政府公安机关提交下列材料： (一)拟运输的剧毒化学品品种、数量的说明； (二)运输始发地、目的地、运输时间和运输路线的说明； (三)承运人取得危险货物道路运输许可、运输车辆取得营运证以及驾驶人员、押运人员取得上岗资格的证明文件； (四)本条例"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十八条", "text": "第一款、第二款规定的购买剧毒化学品的相关许可证件，或者海关出具的进出口证明文件。 县级人民政府公安机关应当自收到前款规定的材料之日起7日内，作出批准或者不予批准的决定。予以批准的，颁发剧毒化学品道路运输通行证；不予批准的，书面通知申请人并说明理由。 剧毒化学品道路运输通行证管理办法由国务院公安部门制定。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第五十一条", "text": "剧毒化学品、易制爆危险化学品在道路运输途中丢失、被盗、被抢或者出现流散、泄漏等情况的，驾驶人员、押运人员应当立即采取相应的警示措施和安全措施，并向当地公安机关报告。公安机关接到报告后，应当根据实际情况立即向安全生产监督管理部门、环境保护主管部门、卫生主管部门通报。有关部门应当采取必要的应急处置措施。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第五十二条", "text": "通过水路运输危险化学品的，应当遵守法律、行政法规以及国务院交通运输主管部门关于危险货物水路运输安全的规定。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第五十三条", "text": "海事管理机构应当根据危险化学品的种类和危险特性，确定船舶运输危险化学品的相关安全运输条件。 拟交付船舶运输的化学品的相关安全运输条件不明确的，货物所有人或者代理人应当委托相关技术机构进行评估，明确相关安全运输条件并经海事管理机构确认后，方可交付船舶运输。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第五十四条", "text": "禁止通过内河封闭水域运输剧毒化学品以及国家规定禁止通过内河运输的其他危险化学品。 前款规定以外的内河水域，禁止运输国家规定禁止通过内河运输的剧毒化学品以及其他危险化学品。 禁止通过内河运输的剧毒化学品以及其他危险化学品的范围，由国务院交通运输主管部门会同国务院环境保护主管部门、工业和信息化主管部门、安全生产监督管理部门，根据危险化学品的危险特性、危险化学品对人体和水环境的危害程度以及消除危害后果的难易程度等因素规定并公布。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第五十五条", "text": "国务院交通运输主管部门应当根据危险化学品的危险特性，对通过内河运输本条例"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第五十四条", "text": "规定以外的危险化学品(以下简称通过内河运输危险化学品)实行分类管理，对各类危险化学品的运输方式、包装规范和安全防护措施等分别作出规定并监督实施。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第五十六条", "text": "通过内河运输危险化学品，应当由依法取得危险货物水路运输许可的水路运输企业承运，其他单位和个人不得承运。托运人应当委托依法取得危险货物水路运输许可的水路运输企业承运，不得委托其他单位和个人承运。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第五十七条", "text": "通过内河运输危险化学品，应当使用依法取得危险货物适装证书的运输船舶。水路运输企业应当针对所运输的危险化学品的危险特性，制定运输船舶危险化学品事故应急救援预案，并为运输船舶配备充足、有效的应急救援器材和设备。 通过内河运输危险化学品的船舶，其所有人或者经营人应当取得船舶污染损害责任保险证书或者财务担保证明。船舶污染损害责任保险证书或者财务担保证明的副本应当随船携带。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第五十八条", "text": "通过内河运输危险化学品，危险化学品包装物的材质、型式、强度以及包装方法应当符合水路运输危险化学品包装规范的要求。国务院交通运输主管部门对单船运输的危险化学品数量有限制性规定的，承运人应当按照规定安排运输数量。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第五十九条", "text": "用于危险化学品运输作业的内河码头、泊位应当符合国家有关安全规范，与饮用水取水口保持国家规定的距离。有关管理单位应当制定码头、泊位危险化学品事故应急预案，并为码头、泊位配备充足、有效的应急救援器材和设备。 用于危险化学品运输作业的内河码头、泊位，经交通运输主管部门按照国家有关规定验收合格后方可投入使用。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第六十条", "text": "船舶载运危险化学品进出内河港口，应当将危险化学品的名称、危险特性、包装以及进出港时间等事项，事先报告海事管理机构。海事管理机构接到报告后，应当在国务院交通运输主管部门规定的时间内作出是否同意的决定，通知报告人，同时通报港口行政管理部门。定船舶、定航线、定货种的船舶可以定期报告。 在内河港口内进行危险化学品的装卸、过驳作业，应当将危险化学品的名称、危险特性、包装和作业的时间、地点等事项报告港口行政管理部门。港口行政管理部门接到报告后，应当在国务院交通运输主管部门规定的时间内作出是否同意的决定，通知报告人，同时通报海事管理机构。 载运危险化学品的船舶在内河航行，通过过船建筑物的，应当提前向交通运输主管部门申报，并接受交通运输主管部门的管理。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第六十一条", "text": "载运危险化学品的船舶在内河航行、装卸或者停泊，应当悬挂专用的警示标志，按照规定显示专用信号。 载运危险化学品的船舶在内河航行，按照国务院交通运输主管部门的规定需要引航的，应当申请引航。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第六十二条", "text": "载运危险化学品的船舶在内河航行，应当遵守法律、行政法规和国家其他有关饮用水水源保护的规定。内河航道发展规划应当与依法经批准的饮用水水源保护区划定方案相协调。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第六十三条", "text": "托运危险化学品的，托运人应当向承运人说明所托运的危险化学品的种类、数量、危险特性以及发生危险情况的应急处置措施，并按照国家有关规定对所托运的危险化学品妥善包装，在外包装上设置相应的标志。 运输危险化学品需要添加抑制剂或者稳定剂的，托运人应当添加，并将有关情况告知承运人。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第六十四条", "text": "托运人不得在托运的普通货物中夹带危险化学品，不得将危险化学品匿报或者谎报为普通货物托运。 任何单位和个人不得交寄危险化学品或者在邮件、快件内夹带危险化学品，不得将危险化学品匿报或者谎报为普通物品交寄。邮政企业、快递企业不得收寄危险化学品。 对涉嫌违反本条第一款、第二款规定的，交通运输主管部门、邮政管理部门可以依法开拆查验。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第六十五条", "text": "通过铁路、航空运输危险化学品的安全管理，依照有关铁路、航空运输的法律、行政法规、规章的规定执行。 第六章 危险化学品登记与事故应急救援"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第六十六条", "text": "国家实行危险化学品登记制度，为危险化学品安全管理以及危险化学品事故预防和应急救援提供技术、信息支持。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第六十七条", "text": "危险化学品生产企业、进口企业，应当向国务院安全生产监督管理部门负责危险化学品登记的机构(以下简称危险化学品登记机构)办理危险化学品登记。 危险化学品登记包括下列内容： (一)分类和标签信息； (二)物理、化学性质； (三)主要用途； (四)危险特性； (五)储存、使用、运输的安全要求； (六)出现危险情况的应急处置措施。 对同一企业生产、进口的同一品种的危险化学品，不进行重复登记。危险化学品生产企业、进口企业发现其生产、进口的危险化学品有新的危险特性的，应当及时向危险化学品登记机构办理登记内容变更手续。 危险化学品登记的具体办法由国务院安全生产监督管理部门制定。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第六十八条", "text": "危险化学品登记机构应当定期向工业和信息化、环境保护、公安、卫生、交通运输、铁路、质量监督检验检疫等部门提供危险化学品登记的有关信息和资料。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第六十九条", "text": "县级以上地方人民政府安全生产监督管理部门应当会同工业和信息化、环境保护、公安、卫生、交通运输、铁路、质量监督检验检疫等部门，根据本地区实际情况，制定危险化学品事故应急预案，报本级人民政府批准。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第七十条", "text": "危险化学品单位应当制定本单位危险化学品事故应急预案，配备应急救援人员和必要的应急救援器材、设备，并定期组织应急救援演练。 危险化学品单位应当将其危险化学品事故应急预案报所在地设区的市级人民政府安全生产监督管理部门备案。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第七十一条", "text": "发生危险化学品事故，事故单位主要负责人应当立即按照本单位危险化学品应急预案组织救援，并向当地安全生产监督管理部门和环境保护、公安、卫生主管部门报告；道路运输、水路运输过程中发生危险化学品事故的，驾驶人员、船员或者押运人员还应当向事故发生地交通运输主管部门报告。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第七十二条", "text": "发生危险化学品事故，有关地方人民政府应当立即组织安全生产监督管理、环境保护、公安、卫生、交通运输等有关部门，按照本地区危险化学品事故应急预案组织实施救援，不得拖延、推诿。 有关地方人民政府及其有关部门应当按照下列规定，采取必要的应急处置措施，减少事故损失，防止事故蔓延、扩大： (一)立即组织营救和救治受害人员，疏散、撤离或者采取其他措施保护危害区域内的其他人员； (二)迅速控制危害源，测定危险化学品的性质、事故的危害区域及危害程度； (三)针对事故对人体、动植物、土壤、水源、大气造成的现实危害和可能产生的危害，迅速采取封闭、隔离、洗消等措施； (四)对危险化学品事故造成的环境污染和生态破坏状况进行监测、评估，并采取相应的环境污染治理和生态修复措施。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第七十三条", "text": "有关危险化学品单位应当为危险化学品事故应急救援提供技术指导和必要的协助。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第七十四条", "text": "危险化学品事故造成环境污染的，由设区的市级以上人民政府环境保护主管部门统一发布有关信息。 第七章 法律责任"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第七十五条", "text": "生产、经营、使用国家禁止生产、经营、使用的危险化学品的，由安全生产监督管理部门责令停止生产、经营、使用活动，处20万元以上50万元以下的罚款，有违法所得的，没收违法所得；构成犯罪的，依法追究刑事责任。 有前款规定行为的，安全生产监督管理部门还应当责令其对所生产、经营、使用的危险化学品进行无害化处理。 违反国家关于危险化学品使用的限制性规定使用危险化学品的，依照本条第一款的规定处理。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第七十六条", "text": "未经安全条件审查，新建、改建、扩建生产、储存危险化学品的建设项目的，由安全生产监督管理部门责令停止建设，限期改正；逾期不改正的，处50万元以上100万元以下的罚款；构成犯罪的，依法追究刑事责任。 未经安全条件审查，新建、改建、扩建储存、装卸危险化学品的港口建设项目的，由港口行政管理部门依照前款规定予以处罚。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第七十七条", "text": "未依法取得危险化学品安全生产许可证从事危险化学品生产，或者未依法取得工业产品生产许可证从事危险化学品及其包装物、容器生产的，分别依照《安全生产许可证条例》、《中华人民共和国工业产品生产许可证管理条例》的规定处罚。 违反本条例规定，化工企业未取得危险化学品安全使用许可证，使用危险化学品从事生产的，由安全生产监督管理部门责令限期改正，处10万元以上20万元以下的罚款；逾期不改正的，责令停产整顿。 违反本条例规定，未取得危险化学品经营许可证从事危险化学品经营的，由安全生产监督管理部门责令停止经营活动，没收违法经营的危险化学品以及违法所得，并处10万元以上20万元以下的罚款；构成犯罪的，依法追究刑事责任。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第七十八条", "text": "有下列情形之一的，由安全生产监督管理部门责令改正，可以处5万元以下的罚款；拒不改正的，处5万元以上10万元以下的罚款；情节严重的，责令停产停业整顿： (一)生产、储存危险化学品的单位未对其铺设的危险化学品管道设置明显的标志，或者未对危险化学品管道定期检查、检测的； (二)进行可能危及危险化学品管道安全的施工作业，施工单位未按照规定书面通知管道所属单位，或者未与管道所属单位共同制定应急预案、采取相应的安全防护措施，或者管道所属单位未指派专门人员到现场进行管道安全保护指导的； (三)危险化学品生产企业未提供化学品安全技术说明书，或者未在包装(包括外包装件)上粘贴、拴挂化学品安全标签的； (四)危险化学品生产企业提供的化学品安全技术说明书与其生产的危险化学品不相符，或者在包装(包括外包装件)粘贴、拴挂的化学品安全标签与包装内危险化学品不相符，或者化学品安全技术说明书、化学品安全标签所载明的内容不符合国家标准要求的； (五)危险化学品生产企业发现其生产的危险化学品有新的危险特性不立即公告，或者不及时修订其化学品安全技术说明书和化学品安全标签的； (六)危险化学品经营企业经营没有化学品安全技术说明书和化学品安全标签的危险化学品的； (七)危险化学品包装物、容器的材质以及包装的型式、规格、方法和单件质量(重量)与所包装的危险化学品的性质和用途不相适应的； (八)生产、储存危险化学品的单位未在作业场所和安全设施、设备上设置明显的安全警示标志，或者未在作业场所设置通信、报警装置的； (九)危险化学品专用仓库未设专人负责管理，或者对储存的剧毒化学品以及储存数量构成重大危险源的其他危险化学品未实行双人收发、双人保管制度的； (十)储存危险化学品的单位未建立危险化学品出入库核查、登记制度的； (十一)危险化学品专用仓库未设置明显标志的； (十二)危险化学品生产企业、进口企业不办理危险化学品登记，或者发现其生产、进口的危险化学品有新的危险特性不办理危险化学品登记内容变更手续的。 从事危险化学品仓储经营的港口经营人有前款规定情形的，由港口行政管理部门依照前款规定予以处罚。储存剧毒化学品、易制爆危险化学品的专用仓库未按照国家有关规定设置相应的技术防范设施的，由公安机关依照前款规定予以处罚。 生产、储存剧毒化学品、易制爆危险化学品的单位未设置治安保卫机构、配备专职治安保卫人员的，依照《企业事业单位内部治安保卫条例》的规定处罚。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第七十九条", "text": "危险化学品包装物、容器生产企业销售未经检验或者经检验不合格的危险化学品包装物、容器的，由质量监督检验检疫部门责令改正，处10万元以上20万元以下的罚款，有违法所得的，没收违法所得；拒不改正的，责令停产停业整顿；构成犯罪的，依法追究刑事责任。 将未经检验合格的运输危险化学品的船舶及其配载的容器投入使用的，由海事管理机构依照前款规定予以处罚。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第八十条", "text": "生产、储存、使用危险化学品的单位有下列情形之一的，由安全生产监督管理部门责令改正，处5万元以上10万元以下的罚款；拒不改正的，责令停产停业整顿直至由原发证机关吊销其相关许可证件，并由工商行政管理部门责令其办理经营范围变更登记或者吊销其营业执照；有关责任人员构成犯罪的，依法追究刑事责任： (一)对重复使用的危险化学品包装物、容器，在重复使用前不进行检查的； (二)未根据其生产、储存的危险化学品的种类和危险特性，在作业场所设置相关安全设施、设备，或者未按照国家标准、行业标准或者国家有关规定对安全设施、设备进行经常性维护、保养的； (三)未依照本条例规定对其安全生产条件定期进行安全评价的； (四)未将危险化学品储存在专用仓库内，或者未将剧毒化学品以及储存数量构成重大危险源的其他危险化学品在专用仓库内单独存放的； (五)危险化学品的储存方式、方法或者储存数量不符合国家标准或者国家有关规定的； (六)危险化学品专用仓库不符合国家标准、行业标准的要求的； (七)未对危险化学品专用仓库的安全设施、设备定期进行检测、检验的。 从事危险化学品仓储经营的港口经营人有前款规定情形的，由港口行政管理部门依照前款规定予以处罚。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第八十一条", "text": "有下列情形之一的，由公安机关责令改正，可以处1万元以下的罚款；拒不改正的，处1万元以上5万元以下的罚款： (一)生产、储存、使用剧毒化学品、易制爆危险化学品的单位不如实记录生产、储存、使用的剧毒化学品、易制爆危险化学品的数量、流向的； (二)生产、储存、使用剧毒化学品、易制爆危险化学品的单位发现剧毒化学品、易制爆危险化学品丢失或者被盗，不立即向公安机关报告的； (三)储存剧毒化学品的单位未将剧毒化学品的储存数量、储存地点以及管理人员的情况报所在地县级人民政府公安机关备案的； (四)危险化学品生产企业、经营企业不如实记录剧毒化学品、易制爆危险化学品购买单位的名称、地址、经办人的姓名、身份证号码以及所购买的剧毒化学品、易制爆危险化学品的品种、数量、用途，或者保存销售记录和相关材料的时间少于1年的； (五)剧毒化学品、易制爆危险化学品的销售企业、购买单位未在规定的时限内将所销售、购买的剧毒化学品、易制爆危险化学品的品种、数量以及流向信息报所在地县级人民政府公安机关备案的； (六)使用剧毒化学品、易制爆危险化学品的单位依照本条例规定转让其购买的剧毒化学品、易制爆危险化学品，未将有关情况向所在地县级人民政府公安机关报告的。 生产、储存危险化学品的企业或者使用危险化学品从事生产的企业未按照本条例规定将安全评价报告以及整改方案的落实情况报安全生产监督管理部门或者港口行政管理部门备案，或者储存危险化学品的单位未将其剧毒化学品以及储存数量构成重大危险源的其他危险化学品的储存数量、储存地点以及管理人员的情况报安全生产监督管理部门或者港口行政管理部门备案的，分别由安全生产监督管理部门或者港口行政管理部门依照前款规定予以处罚。 生产实施重点环境管理的危险化学品的企业或者使用实施重点环境管理的危险化学品从事生产的企业未按照规定将相关信息向环境保护主管部门报告的，由环境保护主管部门依照本条第一款的规定予以处罚。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第八十二条", "text": "生产、储存、使用危险化学品的单位转产、停产、停业或者解散，未采取有效措施及时、妥善处置其危险化学品生产装置、储存设施以及库存的危险化学品，或者丢弃危险化学品的，由安全生产监督管理部门责令改正，处5万元以上10万元以下的罚款；构成犯罪的，依法追究刑事责任。 生产、储存、使用危险化学品的单位转产、停产、停业或者解散，未依照本条例规定将其危险化学品生产装置、储存设施以及库存危险化学品的处置方案报有关部门备案的，分别由有关部门责令改正，可以处1万元以下的罚款；拒不改正的，处1万元以上5万元以下的罚款。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第八十三条", "text": "危险化学品经营企业向未经许可违法从事危险化学品生产、经营活动的企业采购危险化学品的，由工商行政管理部门责令改正，处10万元以上20万元以下的罚款；拒不改正的，责令停业整顿直至由原发证机关吊销其危险化学品经营许可证，并由工商行政管理部门责令其办理经营范围变更登记或者吊销其营业执照。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第八十四条", "text": "危险化学品生产企业、经营企业有下列情形之一的，由安全生产监督管理部门责令改正，没收违法所得，并处10万元以上20万元以下的罚款；拒不改正的，责令停产停业整顿直至吊销其危险化学品安全生产许可证、危险化学品经营许可证，并由工商行政管理部门责令其办理经营范围变更登记或者吊销其营业执照： (一)向不具有本条例"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十八条", "text": "第一款、第二款规定的相关许可证件或者证明文件的单位销售剧毒化学品、易制爆危险化学品的； (二)不按照剧毒化学品购买许可证载明的品种、数量销售剧毒化学品的； (三)向个人销售剧毒化学品(属于剧毒化学品的农药除外)、易制爆危险化学品的。 不具有本条例"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十八条", "text": "第一款、第二款规定的相关许可证件或者证明文件的单位购买剧毒化学品、易制爆危险化学品，或者个人购买剧毒化学品(属于剧毒化学品的农药除外)、易制爆危险化学品的，由公安机关没收所购买的剧毒化学品、易制爆危险化学品，可以并处5000元以下的罚款。 使用剧毒化学品、易制爆危险化学品的单位出借或者向不具有本条例"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三十八条", "text": "第一款、第二款规定的相关许可证件的单位转让其购买的剧毒化学品、易制爆危险化学品，或者向个人转让其购买的剧毒化学品(属于剧毒化学品的农药除外)、易制爆危险化学品的，由公安机关责令改正，处10万元以上20万元以下的罚款；拒不改正的，责令停产停业整顿。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第八十五条", "text": "未依法取得危险货物道路运输许可、危险货物水路运输许可，从事危险化学品道路运输、水路运输的，分别依照有关道路运输、水路运输的法律、行政法规的规定处罚。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第八十六条", "text": "有下列情形之一的，由交通运输主管部门责令改正，处5万元以上10万元以下的罚款；拒不改正的，责令停产停业整顿；构成犯罪的，依法追究刑事责任： (一)危险化学品道路运输企业、水路运输企业的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员未取得从业资格上岗作业的； (二)运输危险化学品，未根据危险化学品的危险特性采取相应的安全防护措施，或者未配备必要的防护用品和应急救援器材的； (三)使用未依法取得危险货物适装证书的船舶，通过内河运输危险化学品的； (四)通过内河运输危险化学品的承运人违反国务院交通运输主管部门对单船运输的危险化学品数量的限制性规定运输危险化学品的； (五)用于危险化学品运输作业的内河码头、泊位不符合国家有关安全规范，或者未与饮用水取水口保持国家规定的安全距离，或者未经交通运输主管部门验收合格投入使用的； (六)托运人不向承运人说明所托运的危险化学品的种类、数量、危险特性以及发生危险情况的应急处置措施，或者未按照国家有关规定对所托运的危险化学品妥善包装并在外包装上设置相应标志的； (七)运输危险化学品需要添加抑制剂或者稳定剂，托运人未添加或者未将有关情况告知承运人的。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第八十七条", "text": "有下列情形之一的，由交通运输主管部门责令改正，处10万元以上20万元以下的罚款，有违法所得的，没收违法所得；拒不改正的，责令停产停业整顿；构成犯罪的，依法追究刑事责任： (一)委托未依法取得危险货物道路运输许可、危险货物水路运输许可的企业承运危险化学品的； (二)通过内河封闭水域运输剧毒化学品以及国家规定禁止通过内河运输的其他危险化学品的； (三)通过内河运输国家规定禁止通过内河运输的剧毒化学品以及其他危险化学品的； (四)在托运的普通货物中夹带危险化学品，或者将危险化学品谎报或者匿报为普通货物托运的。 在邮件、快件内夹带危险化学品，或者将危险化学品谎报为普通物品交寄的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。 邮政企业、快递企业收寄危险化学品的，依照《中华人民共和国邮政法》的规定处罚。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第八十八条", "text": "有下列情形之一的，由公安机关责令改正，处5万元以上10万元以下的罚款；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任： (一)超过运输车辆的核定载质量装载危险化学品的； (二)使用安全技术条件不符合国家标准要求的车辆运输危险化学品的； (三)运输危险化学品的车辆未经公安机关批准进入危险化学品运输车辆限制通行的区域的； (四)未取得剧毒化学品道路运输通行证，通过道路运输剧毒化学品的。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第八十九条", "text": "有下列情形之一的，由公安机关责令改正，处1万元以上5万元以下的罚款；构成违反治安管理行为的，依法给予治安管理处罚： (一)危险化学品运输车辆未悬挂或者喷涂警示标志，或者悬挂或者喷涂的警示标志不符合国家标准要求的； (二)通过道路运输危险化学品，不配备押运人员的； (三)运输剧毒化学品或者易制爆危险化学品途中需要较长时间停车，驾驶人员、押运人员不向当地公安机关报告的； (四)剧毒化学品、易制爆危险化学品在道路运输途中丢失、被盗、被抢或者发生流散、泄露等情况，驾驶人员、押运人员不采取必要的警示措施和安全措施，或者不向当地公安机关报告的。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第九十条", "text": "对发生交通事故负有全部责任或者主要责任的危险化学品道路运输企业，由公安机关责令消除安全隐患，未消除安全隐患的危险化学品运输车辆，禁止上道路行驶。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第九十一条", "text": "有下列情形之一的，由交通运输主管部门责令改正，可以处1万元以下的罚款；拒不改正的，处1万元以上5万元以下的罚款： (一)危险化学品道路运输企业、水路运输企业未配备专职安全管理人员的； (二)用于危险化学品运输作业的内河码头、泊位的管理单位未制定码头、泊位危险化学品事故应急救援预案，或者未为码头、泊位配备充足、有效的应急救援器材和设备的。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第九十二条", "text": "有下列情形之一的，依照《中华人民共和国内河交通安全管理条例》的规定处罚： (一)通过内河运输危险化学品的水路运输企业未制定运输船舶危险化学品事故应急救援预案，或者未为运输船舶配备充足、有效的应急救援器材和设备的； (二)通过内河运输危险化学品的船舶的所有人或者经营人未取得船舶污染损害责任保险证书或者财务担保证明的； (三)船舶载运危险化学品进出内河港口，未将有关事项事先报告海事管理机构并经其同意的； (四)载运危险化学品的船舶在内河航行、装卸或者停泊，未悬挂专用的警示标志，或者未按照规定显示专用信号，或者未按照规定申请引航的。 未向港口行政管理部门报告并经其同意，在港口内进行危险化学品的装卸、过驳作业的，依照《中华人民共和国港口法》的规定处罚。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第九十三条", "text": "伪造、变造或者出租、出借、转让危险化学品安全生产许可证、工业产品生产许可证，或者使用伪造、变造的危险化学品安全生产许可证、工业产品生产许可证的，分别依照《安全生产许可证条例》、《中华人民共和国工业产品生产许可证管理条例》的规定处罚。 伪造、变造或者出租、出借、转让本条例规定的其他许可证，或者使用伪造、变造的本条例规定的其他许可证的，分别由相关许可证的颁发管理机关处10万元以上20万元以下的罚款，有违法所得的，没收违法所得；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第九十四条", "text": "危险化学品单位发生危险化学品事故，其主要负责人不立即组织救援或者不立即向有关部门报告的，依照《生产安全事故报告和调查处理条例》的规定处罚。 危险化学品单位发生危险化学品事故，造成他人人身伤害或者财产损失的，依法承担赔偿责任。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第九十五条", "text": "发生危险化学品事故，有关地方人民政府及其有关部门不立即组织实施救援，或者不采取必要的应急处置措施减少事故损失，防止事故蔓延、扩大的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第九十六条", "text": "负有危险化学品安全监督管理职责的部门的工作人员，在危险化学品安全监督管理工作中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。 第八章 附则"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第九十七条", "text": "监控化学品、属于危险化学品的药品和农药的安全管理，依照本条例的规定执行；法律、行政法规另有规定的，依照其规定。 民用爆炸物品、烟花爆竹、放射性物品、核能物质以及用于国防科研生产的危险化学品的安全管理，不适用本条例。 法律、行政法规对燃气的安全管理另有规定的，依照其规定。 危险化学品容器属于特种设备的，其安全管理依照有关特种设备安全的法律、行政法规的规定执行。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第九十八条", "text": "危险化学品的进出口管理，依照有关对外贸易的法律、行政法规、规章的规定执行；进口的危险化学品的储存、使用、经营、运输的安全管理，依照本条例的规定执行。 危险化学品环境管理登记和新化学物质环境管理登记，依照有关环境保护的法律、行政法规、规章的规定执行。危险化学品环境管理登记，按照国家有关规定收取费用。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第九十九条", "text": "公众发现、捡拾的无主危险化学品，由公安机关接收。公安机关接收或者有关部门依法没收的危险化学品，需要进行无害化处理的，交由环境保护主管部门组织其认定的专业单位进行处理，或者交由有关危险化学品生产企业进行处理。处理所需费用由国家财政负担。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第一百条", "text": "化学品的危险特性尚未确定的，由国务院安全生产监督管理部门、国务院环境保护主管部门、国务院卫生主管部门分别负责组织对该化学品的物理危险性、环境危害性、毒理特性进行鉴定。根据鉴定结果，需要调整危险化学品目录的，依照本条例"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第三条", "text": "第二款的规定办理。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第一百零一条", "text": "本条例施行前已经使用危险化学品从事生产的化工企业，依照本条例规定需要取得危险化学品安全使用许可证的，应当在国务院安全生产监督管理部门规定的期限内，申请取得危险化学品安全使用许可证。"}, {"law": "危险化学品安全管理条例_20131207.docx", "no": "第一百零二条", "text": "本条例自2011年12月1日起施行。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第一条", "text": "为了加强对危险废物收集、贮存和处置经营活动的监督管理，防治危险废物污染环境，根据《中华人民共和国固体废物污染环境防治法》，制定本办法。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第二条", "text": "在中华人民共和国境内从事危险废物收集、贮存、处置经营活动的单位，应当依照本办法的规定，领取危险废物经营许可证。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第三条", "text": "危险废物经营许可证按照经营方式，分为危险废物收集、贮存、处置综合经营许可证和危险废物收集经营许可证。 领取危险废物综合经营许可证的单位，可以从事各类别危险废物的收集、贮存、处置经营活动；领取危险废物收集经营许可证的单位，只能从事机动车维修活动中产生的废矿物油和居民日常生活中产生的废镉镍电池的危险废物收集经营活动。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第四条", "text": "县级以上人民政府环境保护主管部门依照本办法的规定，负责危险废物经营许可证的审批颁发与监督管理工作。 第二章 申请领取危险废物经营许可证的条件"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第五条", "text": "申请领取危险废物收集、贮存、处置综合经营许可证，应当具备下列条件： (一)有3名以上环境工程专业或者相关专业中级以上职称，并有3年以上固体废物污染治理经历的技术人员； (二)有符合国务院交通主管部门有关危险货物运输安全要求的运输工具； (三)有符合国家或者地方环境保护标准和安全要求的包装工具，中转和临时存放设施、设备以及经验收合格的贮存设施、设备； (四)有符合国家或者省、自治区、直辖市危险废物处置设施建设规划，符合国家或者地方环境保护标准和安全要求的处置设施、设备和配套的污染防治设施；其中，医疗废物集中处置设施，还应当符合国家有关医疗废物处置的卫生标准和要求； (五)有与所经营的危险废物类别相适应的处置技术和工艺； (六)有保证危险废物经营安全的规章制度、污染防治措施和事故应急救援措施； (七)以填埋方式处置危险废物的，应当依法取得填埋场所的土地使用权。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第六条", "text": "申请领取危险废物收集经营许可证，应当具备下列条件： (一)有防雨、防渗的运输工具； (二)有符合国家或者地方环境保护标准和安全要求的包装工具，中转和临时存放设施、设备； (三)有保证危险废物经营安全的规章制度、污染防治措施和事故应急救援措施。 第三章 申请领取危险废物经营许可证的程序"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第七条", "text": "国家对危险废物经营许可证实行分级审批颁发。 医疗废物集中处置单位的危险废物经营许可证，由医疗废物集中处置设施所在地设区的市级人民政府环境保护主管部门审批颁发。 危险废物收集经营许可证，由县级人民政府环境保护主管部门审批颁发。 本条第二款、第三款规定之外的危险废物经营许可证，由省、自治区、直辖市人民政府环境保护主管部门审批颁发。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第八条", "text": "申请领取危险废物经营许可证的单位，应当在从事危险废物经营活动前向发证机关提出申请，并附具本办法"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第六条", "text": "规定条件的证明材料。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第九条", "text": "发证机关应当自受理申请之日起20个工作日内，对申请单位提交的证明材料进行审查，并对申请单位的经营设施进行现场核查。符合条件的，颁发危险废物经营许可证，并予以公告；不符合条件的，书面通知申请单位并说明理由。 发证机关在颁发危险废物经营许可证前，可以根据实际需要征求卫生、城乡规划等有关主管部门和专家的意见。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十条", "text": "危险废物经营许可证包括下列主要内容： (一)法人名称、法定代表人、住所； (二)危险废物经营方式； (三)危险废物类别； (四)年经营规模； (五)有效期限； (六)发证日期和证书编号。 危险废物综合经营许可证的内容，还应当包括贮存、处置设施的地址。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十一条", "text": "危险废物经营单位变更法人名称、法定代表人和住所的，应当自工商变更登记之日起15个工作日内，向原发证机关申请办理危险废物经营许可证变更手续。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十二条", "text": "有下列情形之一的，危险废物经营单位应当按照原申请程序，重新申请领取危险废物经营许可证： (一)改变危险废物经营方式的； (二)增加危险废物类别的； (三)新建或者改建、扩建原有危险废物经营设施的； (四)经营危险废物超过原批准年经营规模20%以上的。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十三条", "text": "危险废物综合经营许可证有效期为5年；危险废物收集经营许可证有效期为3年。 危险废物经营许可证有效期届满，危险废物经营单位继续从事危险废物经营活动的，应当于危险废物经营许可证有效期届满30个工作日前向原发证机关提出换证申请。原发证机关应当自受理换证申请之日起20个工作日内进行审查，符合条件的，予以换证；不符合条件的，书面通知申请单位并说明理由。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十四条", "text": "危险废物经营单位终止从事收集、贮存、处置危险废物经营活动的，应当对经营设施、场所采取污染防治措施，并对未处置的危险废物作出妥善处理。 危险废物经营单位应当在采取前款规定措施之日起20个工作日内向原发证机关提出注销申请，由原发证机关进行现场核查合格后注销危险废物经营许可证。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十五条", "text": "禁止无经营许可证或者不按照经营许可证规定从事危险废物收集、贮存、处置经营活动。 禁止从中华人民共和国境外进口或者经中华人民共和国过境转移电子类危险废物。 禁止将危险废物提供或者委托给无经营许可证的单位从事收集、贮存、处置经营活动。 禁止伪造、变造、转让危险废物经营许可证。 第四章 监督管理"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十六条", "text": "县级以上地方人民政府环境保护主管部门应当于每年3月31日前将上一年度危险废物经营许可证颁发情况报上一级人民政府环境保护主管部门备案。 上级环境保护主管部门应当加强对下级环境保护主管部门审批颁发危险废物经营许可证情况的监督检查，及时纠正下级环境保护主管部门审批颁发危险废物经营许可证过程中的违法行为。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十七条", "text": "县级以上人民政府环境保护主管部门应当通过书面核查和实地检查等方式，加强对危险废物经营单位的监督检查，并将监督检查情况和处理结果予以记录，由监督检查人员签字后归档。 公众有权查阅县级以上人民政府环境保护主管部门的监督检查记录。 县级以上人民政府环境保护主管部门发现危险废物经营单位在经营活动中有不符合原发证条件的情形的，应当责令其限期整改。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十八条", "text": "县级以上人民政府环境保护主管部门有权要求危险废物经营单位定期报告危险废物经营活动情况。危险废物经营单位应当建立危险废物经营情况记录簿，如实记载收集、贮存、处置危险废物的类别、来源、去向和有无事故等事项。 危险废物经营单位应当将危险废物经营情况记录簿保存10年以上，以填埋方式处置危险废物的经营情况记录簿应当永久保存。终止经营活动的，应当将危险废物经营情况记录簿移交所在地县级以上地方人民政府环境保护主管部门存档管理。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十九条", "text": "县级以上人民政府环境保护主管部门应当建立、健全危险废物经营许可证的档案管理制度，并定期向社会公布审批颁发危险废物经营许可证的情况。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第二十条", "text": "领取危险废物收集经营许可证的单位，应当与处置单位签订接收合同，并将收集的废矿物油和废镉镍电池在90个工作日内提供或者委托给处置单位进行处置。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第二十一条", "text": "危险废物的经营设施在废弃或者改作其他用途前，应当进行无害化处理。 填埋危险废物的经营设施服役期届满后，危险废物经营单位应当按照有关规定对填埋过危险废物的土地采取封闭措施，并在划定的封闭区域设置永久性标记。 第五章 法律责任"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十一条", "text": "规定的，由县级以上地方人民政府环境保护主管部门责令限期改正，给予警告；逾期不改正的，由原发证机关暂扣危险废物经营许可证。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十三条", "text": "第二款规定的，由县级以上地方人民政府环境保护主管部门责令停止违法行为；有违法所得的，没收违法所得；违法所得超过10万元的，并处违法所得1倍以上2倍以下的罚款；没有违法所得或者违法所得不足10万元的，处5万元以上10万元以下的罚款。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第二十一条", "text": "规定的，由县级以上地方人民政府环境保护主管部门责令限期改正；逾期不改正的，处5万元以上10万元以下的罚款；造成污染事故，构成犯罪的，依法追究刑事责任。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十五条", "text": "第一款、第二款、第三款规定的，依照《中华人民共和国固体废物污染环境防治法》的规定予以处罚。 违反本办法"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十五条", "text": "第四款规定的，由县级以上地方人民政府环境保护主管部门收缴危险废物经营许可证或者由原发证机关吊销危险废物经营许可证，并处5万元以上10万元以下的罚款；构成犯罪的，依法追究刑事责任。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第十八条", "text": "规定的，由县级以上地方人民政府环境保护主管部门责令限期改正，给予警告；逾期不改正的，由原发证机关暂扣或者吊销危险废物经营许可证。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第二十条", "text": "规定的，由县级以上地方人民政府环境保护主管部门责令限期改正，给予警告；逾期不改正的，处1万元以上5万元以下的罚款，并可以由原发证机关暂扣或者吊销危险废物经营许可证。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第二十八条", "text": "危险废物经营单位被责令限期整改，逾期不整改或者经整改仍不符合原发证条件的，由原发证机关暂扣或者吊销危险废物经营许可证。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第二十九条", "text": "被依法吊销或者收缴危险废物经营许可证的单位，5年内不得再申请领取危险废物经营许可证。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第三十条", "text": "县级以上人民政府环境保护主管部门的工作人员，有下列行为之一的，依法给予行政处分；构成犯罪的，依法追究刑事责任： (一)向不符合本办法规定条件的单位颁发危险废物经营许可证的； (二)发现未依法取得危险废物经营许可证的单位和个人擅自从事危险废物经营活动不予查处或者接到举报后不依法处理的； (三)对依法取得危险废物经营许可证的单位不履行监督管理职责或者发现违反本办法规定的行为不予查处的； (四)在危险废物经营许可证管理工作中有其他渎职行为的。 第六章 附则"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第三十一条", "text": "本办法下列用语的含义： (一)危险废物，是指列入国家危险废物名录或者根据国家规定的危险废物鉴别标准和鉴别方法认定的具有危险性的废物。 (二)收集，是指危险废物经营单位将分散的危险废物进行集中的活动。 (三)贮存，是指危险废物经营单位在危险废物处置前，将其放置在符合环境保护标准的场所或者设施中，以及为了将分散的危险废物进行集中，在自备的临时设施或者场所每批置放重量超过5000千克或者置放时间超过90个工作日的活动。 (四)处置，是指危险废物经营单位将危险废物焚烧、煅烧、熔融、烧结、裂解、中和、消毒、蒸馏、萃取、沉淀、过滤、拆解以及用其他改变危险废物物理、化学、生物特性的方法，达到减少危险废物数量、缩小危险废物体积、减少或者消除其危险成分的活动，或者将危险废物最终置于符合环境保护规定要求的场所或者设施并不再回取的活动。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第三十二条", "text": "本办法施行前，依照地方性法规、规章或者其他文件的规定已经取得危险废物经营许可证的单位，应当在原危险废物经营许可证有效期届满30个工作日前，依照本办法的规定重新申请领取危险废物经营许可证。逾期不办理的，不得继续从事危险废物经营活动。"}, {"law": "危险废物经营许可证管理办法_20160206.docx", "no": "第三十三条", "text": "本办法自2004年7月1日起施行。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第一条", "text": "为加强对危险废物转移活动的监督管理，防止污染环境，根据《中华人民共和国固体废物污染环境防治法》等有关法律法规，制定本办法。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第二条", "text": "本办法适用于在中华人民共和国境内转移危险废物及其监督管理活动。 转移符合豁免要求的危险废物的，按照国家相关规定实行豁免管理。 在海洋转移危险废物的，不适用本办法。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第三条", "text": "危险废物转移应当遵循就近原则。 跨省、自治区、直辖市转移（以下简称跨省转移）处置危险废物的，应当以转移至相邻或者开展区域合作的省、自治区、直辖市的危险废物处置设施，以及全国统筹布局的危险废物处置设施为主。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第四条", "text": "生态环境主管部门依法对危险废物转移污染环境防治工作以及危险废物转移联单运行实施监督管理，查处危险废物污染环境违法行为。 各级交通运输主管部门依法查处危险废物运输违反危险货物运输管理相关规定的违法行为。 公安机关依法查处危险废物运输车辆的交通违法行为，打击涉危险废物污染环境犯罪行为。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第五条", "text": "生态环境主管部门、交通运输主管部门和公安机关应当建立健全协作机制，共享危险废物转移联单信息、运输车辆行驶轨迹动态信息和运输车辆限制通行区域信息，加强联合监管执法。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第六条", "text": "转移危险废物的，应当执行危险废物转移联单制度，法律法规另有规定的除外。 危险废物转移联单的格式和内容由生态环境部另行制定。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第七条", "text": "转移危险废物的，应当通过国家危险废物信息管理系统（以下简称信息系统）填写、运行危险废物电子转移联单，并依照国家有关规定公开危险废物转移相关污染环境防治信息。 生态环境部负责建设、运行和维护信息系统。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第八条", "text": "运输危险废物的，应当遵守国家有关危险货物运输管理的规定。未经公安机关批准，危险废物运输车辆不得进入危险货物运输车辆限制通行的区域。 第二章 相关方责任"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第九条", "text": "危险废物移出人、危险废物承运人、危险废物接受人（以下分别简称移出人、承运人和接受人）在危险废物转移过程中应当采取防扬散、防流失、防渗漏或者其他防止污染环境的措施，不得擅自倾倒、堆放、丢弃、遗撒危险废物，并对所造成的环境污染及生态破坏依法承担责任。 移出人、承运人、接受人应当依法制定突发环境事件的防范措施和应急预案，并报有关部门备案；发生危险废物突发环境事件时，应当立即采取有效措施消除或者减轻对环境的污染危害，并按相关规定向事故发生地有关部门报告，接受调查处理。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第十条", "text": "移出人应当履行以下义务： （一）对承运人或者接受人的主体资格和技术能力进行核实，依法签订书面合同，并在合同中约定运输、贮存、利用、处置危险废物的污染防治要求及相关责任； （二）制定危险废物管理计划，明确拟转移危险废物的种类、重量（数量）和流向等信息； （三）建立危险废物管理台账，对转移的危险废物进行计量称重，如实记录、妥善保管转移危险废物的种类、重量（数量）和接受人等相关信息； （四）填写、运行危险废物转移联单，在危险废物转移联单中如实填写移出人、承运人、接受人信息，转移危险废物的种类、重量（数量）、危险特性等信息，以及突发环境事件的防范措施等； （五）及时核实接受人贮存、利用或者处置相关危险废物情况； （六）法律法规规定的其他义务。 移出人应当按照国家有关要求开展危险废物鉴别。禁止将危险废物以副产品等名义提供或者委托给无危险废物经营许可证的单位或者其他生产经营者从事收集、贮存、利用、处置活动。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第十一条", "text": "承运人应当履行以下义务： （一）核实危险废物转移联单，没有转移联单的，应当拒绝运输； （二）填写、运行危险废物转移联单，在危险废物转移联单中如实填写承运人名称、运输工具及其营运证件号，以及运输起点和终点等运输相关信息，并与危险货物运单一并随运输工具携带； （三）按照危险废物污染环境防治和危险货物运输相关规定运输危险废物，记录运输轨迹，防范危险废物丢失、包装破损、泄漏或者发生突发环境事件； （四）将运输的危险废物运抵接受人地址，交付给危险废物转移联单上指定的接受人，并将运输情况及时告知移出人； （五）法律法规规定的其他义务。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第十二条", "text": "接受人应当履行以下义务： （一）核实拟接受的危险废物的种类、重量（数量）、包装、识别标志等相关信息； （二）填写、运行危险废物转移联单，在危险废物转移联单中如实填写是否接受的意见，以及利用、处置方式和接受量等信息； （三）按照国家和地方有关规定和标准，对接受的危险废物进行贮存、利用或者处置； （四）将危险废物接受情况、利用或者处置结果及时告知移出人； （五）法律法规规定的其他义务。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第十三条", "text": "危险废物托运人（以下简称托运人）应当按照国家危险货物相关标准确定危险废物对应危险货物的类别、项别、编号等，并委托具备相应危险货物运输资质的单位承运危险废物，依法签订运输合同。 采用包装方式运输危险废物的，应当妥善包装，并按照国家有关标准在外包装上设置相应的识别标志。 装载危险废物时，托运人应当核实承运人、运输工具及收运人员是否具有相应经营范围的有效危险货物运输许可证件，以及待转移的危险废物识别标志中的相关信息与危险废物转移联单是否相符；不相符的，应当不予装载。装载采用包装方式运输的危险废物的，应当确保将包装完好的危险废物交付承运人。 第三章 危险废物转移联单的运行和管理"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第十四条", "text": "危险废物转移联单应当根据危险废物管理计划中填报的危险废物转移等备案信息填写、运行。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第十五条", "text": "危险废物转移联单实行全国统一编号，编号由十四位阿拉伯数字组成。第一至四位数字为年份代码；第五、六位数字为移出地省级行政区划代码；第七、八位数字为移出地设区的市级行政区划代码；其余六位数字以移出地设区的市级行政区域为单位进行流水编号。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第十六条", "text": "移出人每转移一车（船或者其他运输工具）次同类危险废物，应当填写、运行一份危险废物转移联单；每车（船或者其他运输工具）次转移多类危险废物的，可以填写、运行一份危险废物转移联单，也可以每一类危险废物填写、运行一份危险废物转移联单。 使用同一车（船或者其他运输工具）一次为多个移出人转移危险废物的，每个移出人应当分别填写、运行危险废物转移联单。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第十七条", "text": "采用联运方式转移危险废物的，前一承运人和后一承运人应当明确运输交接的时间和地点。后一承运人应当核实危险废物转移联单确定的移出人信息、前一承运人信息及危险废物相关信息。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第十八条", "text": "接受人应当对运抵的危险废物进行核实验收，并在接受之日起五个工作日内通过信息系统确认接受。 运抵的危险废物的名称、数量、特性、形态、包装方式与危险废物转移联单填写内容不符的，接受人应当及时告知移出人，视情况决定是否接受，同时向接受地生态环境主管部门报告。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第十九条", "text": "对不通过车（船或者其他运输工具），且无法按次对危险废物计量的其他方式转移危险废物的，移出人和接受人应当分别配备计量记录设备，将每天危险废物转移的种类、重量（数量）、形态和危险特性等信息纳入相关台账记录，并根据所在地设区的市级以上地方生态环境主管部门的要求填写、运行危险废物转移联单。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第二十条", "text": "危险废物电子转移联单数据应当在信息系统中至少保存十年。 因特殊原因无法运行危险废物电子转移联单的，可以先使用纸质转移联单，并于转移活动完成后十个工作日内在信息系统中补录电子转移联单。 第四章 危险废物跨省转移管理"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第二十一条", "text": "跨省转移危险废物的，应当向危险废物移出地省级生态环境主管部门提出申请。移出地省级生态环境主管部门应当商经接受地省级生态环境主管部门同意后，批准转移该危险废物。未经批准的，不得转移。 鼓励开展区域合作的移出地和接受地省级生态环境主管部门按照合作协议简化跨省转移危险废物审批程序。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第二十二条", "text": "申请跨省转移危险废物的，移出人应当填写危险废物跨省转移申请表，并提交下列材料： （一）接受人的危险废物经营许可证复印件； （二）接受人提供的贮存、利用或者处置危险废物方式的说明； （三）移出人与接受人签订的委托协议、意向或者合同； （四）危险废物移出地的地方性法规规定的其他材料。 移出人应当在危险废物跨省转移申请表中提出拟开展危险废物转移活动的时间期限。 省级生态环境主管部门应当向社会公开办理危险废物跨省转移需要的申请材料。 危险废物跨省转移申请表的格式和内容，由生态环境部另行制定。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第二十三条", "text": "对于申请材料齐全、符合要求的，受理申请的省级生态环境主管部门应当立即予以受理；申请材料存在可以当场更正的错误的，应当允许申请人当场更正；申请材料不齐全或者不符合要求的，应当当场或者在五个工作日内一次性告知移出人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第二十四条", "text": "危险废物移出地省级生态环境主管部门应当自受理申请之日起五个工作日内，根据移出人提交的申请材料和危险废物管理计划等信息，提出初步审核意见。初步审核同意移出的，通过信息系统向危险废物接受地省级生态环境主管部门发出跨省转移商请函；不同意移出的，书面答复移出人，并说明理由。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第二十五条", "text": "危险废物接受地省级生态环境主管部门应当自收到移出地省级生态环境主管部门的商请函之日起十个工作日内，出具是否同意接受的意见，并通过信息系统函复移出地省级生态环境主管部门；不同意接受的，应当说明理由。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第二十六条", "text": "危险废物移出地省级生态环境主管部门应当自收到接受地省级生态环境主管部门复函之日起五个工作日内作出是否批准转移该危险废物的决定；不同意转移的，应当说明理由。危险废物移出地省级生态环境主管部门应当将批准信息通报移出地省级交通运输主管部门和移入地等相关省级生态环境主管部门和交通运输主管部门。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第二十七条", "text": "批准跨省转移危险废物的决定，应当包括批准转移危险废物的名称，类别，废物代码，重量（数量），移出人，接受人，贮存、利用或者处置方式等信息。 批准跨省转移危险废物的决定的有效期为十二个月，但不得超过移出人申请开展危险废物转移活动的时间期限和接受人危险废物经营许可证的剩余有效期限。 跨省转移危险废物的申请经批准后，移出人应当按照批准跨省转移危险废物的决定填写、运行危险废物转移联单，实施危险废物转移活动。移出人可以按照批准跨省转移危险废物的决定在有效期内多次转移危险废物。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第二十八条", "text": "发生下列情形之一的，移出人应当重新提出危险废物跨省转移申请： （一）计划转移的危险废物的种类发生变化或者重量（数量）超过原批准重量（数量）的； （二）计划转移的危险废物的贮存、利用、处置方式发生变化的； （三）接受人发生变更或者接受人不再具备拟接受危险废物的贮存、利用或者处置条件的。 第五章 法律责任"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第二十九条", "text": "违反本办法规定，未填写、运行危险废物转移联单，将危险废物以副产品等名义提供或者委托给无危险废物经营许可证的单位或者其他生产经营者从事收集、贮存、利用、处置活动，或者未经批准擅自跨省转移危险废物的，由生态环境主管部门和公安机关依照《中华人民共和国固体废物污染环境防治法》有关规定进行处罚。 违反危险货物运输管理相关规定运输危险废物的，由交通运输主管部门、公安机关和生态环境主管部门依法进行处罚。 违反本办法规定，未规范填写、运行危险废物转移联单，及时改正，且没有造成危害后果的，依法不予行政处罚；主动消除或者减轻危害后果的，生态环境主管部门可以依法从轻或者减轻行政处罚。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第三十条", "text": "违反本办法规定，构成违反治安管理行为的，由公安机关依法进行处罚；构成犯罪的，依法追究刑事责任。 生态环境主管部门、交通运输主管部门在监督检查时，发现涉嫌犯罪的案件，应当按照行政执法和刑事司法相衔接相关规定及时移送公安机关。 第六章 附 则"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第三十一条", "text": "本办法下列用语的含义： （一）转移，是指以贮存、利用或者处置危险废物为目的，将危险废物从移出人的场所移出，交付承运人并移入接受人场所的活动。 （二）移出人，是指危险废物转移的起始单位，包括危险废物产生单位、危险废物收集单位等。 （三）承运人，是指承担危险废物运输作业任务的单位。 （四）接受人，是指危险废物转移的目的地单位，即危险货物的收货人。 （五）托运人，是指委托承运人运输危险废物的单位，只能由移出人或者接受人担任。"}, {"law": "危险废物转移管理办法_20220101.docx", "no": "第三十二条", "text": "本办法自2022年1月1日起施行。《危险废物转移联单管理办法》（原国家环境保护总局令第5号）同时废止。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第一条", "text": "为了减少和解决女职工在劳动中因生理特点造成的特殊困难，保护女职工健康，制定本规定。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第二条", "text": "中华人民共和国境内的国家机关、企业、事业单位、社会团体、个体经济组织以及其他社会组织等用人单位及其女职工，适用本规定。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第三条", "text": "用人单位应当加强女职工劳动保护，采取措施改善女职工劳动安全卫生条件，对女职工进行劳动安全卫生知识培训。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第四条", "text": "用人单位应当遵守女职工禁忌从事的劳动范围的规定。用人单位应当将本单位属于女职工禁忌从事的劳动范围的岗位书面告知女职工。 女职工禁忌从事的劳动范围由本规定附录列示。国务院安全生产监督管理部门会同国务院人力资源社会保障行政部门、国务院卫生行政部门根据经济社会发展情况，对女职工禁忌从事的劳动范围进行调整。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第五条", "text": "用人单位不得因女职工怀孕、生育、哺乳降低其工资、予以辞退、与其解除劳动或者聘用合同。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第六条", "text": "女职工在孕期不能适应原劳动的，用人单位应当根据医疗机构的证明，予以减轻劳动量或者安排其他能够适应的劳动。 对怀孕7个月以上的女职工，用人单位不得延长劳动时间或者安排夜班劳动，并应当在劳动时间内安排一定的休息时间。 怀孕女职工在劳动时间内进行产前检查，所需时间计入劳动时间。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第七条", "text": "女职工生育享受98天产假，其中产前可以休假15天；难产的，增加产假15天；生育多胞胎的，每多生育1个婴儿，增加产假15天。 女职工怀孕未满4个月流产的，享受15天产假；怀孕满4个月流产的，享受42天产假。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第八条", "text": "女职工产假期间的生育津贴，对已经参加生育保险的，按照用人单位上年度职工月平均工资的标准由生育保险基金支付；对未参加生育保险的，按照女职工产假前工资的标准由用人单位支付。 女职工生育或者流产的医疗费用，按照生育保险规定的项目和标准，对已经参加生育保险的，由生育保险基金支付；对未参加生育保险的，由用人单位支付。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第九条", "text": "对哺乳未满1周岁婴儿的女职工，用人单位不得延长劳动时间或者安排夜班劳动。 用人单位应当在每天的劳动时间内为哺乳期女职工安排1小时哺乳时间；女职工生育多胞胎的，每多哺乳1个婴儿每天增加1小时哺乳时间。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第十条", "text": "女职工比较多的用人单位应当根据女职工的需要，建立女职工卫生室、孕妇休息室、哺乳室等设施，妥善解决女职工在生理卫生、哺乳方面的困难。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第十一条", "text": "在劳动场所，用人单位应当预防和制止对女职工的性骚扰。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第十二条", "text": "县级以上人民政府人力资源社会保障行政部门、安全生产监督管理部门按照各自职责负责对用人单位遵守本规定的情况进行监督检查。 工会、妇女组织依法对用人单位遵守本规定的情况进行监督。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第十三条", "text": "用人单位违反本规定"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第九条", "text": "第一款规定的，由县级以上人民政府人力资源社会保障行政部门责令限期改正，按照受侵害女职工每人1000元以上5000元以下的标准计算，处以罚款。 用人单位违反本规定附录"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第二条", "text": "规定的，由县级以上人民政府安全生产监督管理部门责令限期改正，按照受侵害女职工每人1000元以上5000元以下的标准计算，处以罚款。用人单位违反本规定附录"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第四条", "text": "规定的，由县级以上人民政府安全生产监督管理部门责令限期治理，处5万元以上30万元以下的罚款；情节严重的，责令停止有关作业，或者提请有关人民政府按照国务院规定的权限责令关闭。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第十四条", "text": "用人单位违反本规定，侵害女职工合法权益的，女职工可以依法投诉、举报、申诉，依法向劳动人事争议调解仲裁机构申请调解仲裁，对仲裁裁决不服的，依法向人民法院提起诉讼。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第十五条", "text": "用人单位违反本规定，侵害女职工合法权益，造成女职工损害的，依法给予赔偿；用人单位及其直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任。"}, {"law": "女职工劳动保护特别规定_20120428.docx", "no": "第十六条", "text": "本规定自公布之日起施行。1988年7月21日国务院发布的《女职工劳动保护规定》同时废止。 附录： 女职工禁忌从事的劳动范围 一、女职工禁忌从事的劳动范围： (一)矿山井下作业； (二)体力劳动强度分级标准中规定的第四级体力劳动强度的作业； (三)每小时负重6次以上、每次负重超过20公斤的作业，或者间断负重、每次负重超过25公斤的作业。 二、女职工在经期禁忌从事的劳动范围： (一)冷水作业分级标准中规定的第二级、第三级、第四级冷水作业； (二)低温作业分级标准中规定的第二级、第三级、第四级低温作业； (三)体力劳动强度分级标准中规定的第三级、第四级体力劳动强度的作业； (四)高处作业分级标准中规定的第三级、第四级高处作业。 三、女职工在孕期禁忌从事的劳动范围： (一)作业场所空气中铅及其化合物、汞及其化合物、苯、镉、铍、砷、氰化物、氮氧化物、一氧化碳、二硫化碳、氯、己内酰胺、氯丁二烯、氯乙烯、环氧乙烷、苯胺、甲醛等有毒物质浓度超过国家职业卫生标准的作业； (二)从事抗癌药物、己烯雌酚生产，接触麻醉剂气体等的作业； (三)非密封源放射性物质的操作，核事故与放射事故的应急处置； (四)高处作业分级标准中规定的高处作业； (五)冷水作业分级标准中规定的冷水作业； (六)低温作业分级标准中规定的低温作业； (七)高温作业分级标准中规定的第三级、第四级的作业； (八)噪声作业分级标准中规定的第三级、第四级的作业； (九)体力劳动强度分级标准中规定的第三级、第四级体力劳动强度的作业； (十)在密闭空间、高压室作业或者潜水作业，伴有强烈振动的作业，或者需要频繁弯腰、攀高、下蹲的作业。 四、女职工在哺乳期禁忌从事的劳动范围： (一)孕期禁忌从事的劳动范围的第一项、第三项、第九项； (二)作业场所空气中锰、氟、溴、甲醇、有机磷化合物、有机氯化合物等有毒物质浓度超过国家职业卫生标准的作业。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第一条", "text": "为了严格规范安全生产条件，进一步加强安全生产监督管理，防止和减少生产安全事故，根据《中华人民共和国安全生产法》的有关规定，制定本条例。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第二条", "text": "国家对矿山企业、建筑施工企业和危险化学品、烟花爆竹、民用爆炸物品生产企业(以下统称企业)实行安全生产许可制度。 企业未取得安全生产许可证的，不得从事生产活动。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第三条", "text": "国务院安全生产监督管理部门负责中央管理的非煤矿矿山企业和危险化学品、烟花爆竹生产企业安全生产许可证的颁发和管理。 省、自治区、直辖市人民政府安全生产监督管理部门负责前款规定以外的非煤矿矿山企业和危险化学品、烟花爆竹生产企业安全生产许可证的颁发和管理，并接受国务院安全生产监督管理部门的指导和监督。 国家煤矿安全监察机构负责中央管理的煤矿企业安全生产许可证的颁发和管理。 在省、自治区、直辖市设立的煤矿安全监察机构负责前款规定以外的其他煤矿企业安全生产许可证的颁发和管理，并接受国家煤矿安全监察机构的指导和监督。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第四条", "text": "省、自治区、直辖市人民政府建设主管部门负责建筑施工企业安全生产许可证的颁发和管理，并接受国务院建设主管部门的指导和监督。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第五条", "text": "省、自治区、直辖市人民政府民用爆炸物品行业主管部门负责民用爆炸物品生产企业安全生产许可证的颁发和管理，并接受国务院民用爆炸物品行业主管部门的指导和监督。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第六条", "text": "企业取得安全生产许可证，应当具备下列安全生产条件： (一)建立、健全安全生产责任制，制定完备的安全生产规章制度和操作规程； (二)安全投入符合安全生产要求； (三)设置安全生产管理机构，配备专职安全生产管理人员； (四)主要负责人和安全生产管理人员经考核合格； (五)特种作业人员经有关业务主管部门考核合格，取得特种作业操作资格证书； (六)从业人员经安全生产教育和培训合格； (七)依法参加工伤保险，为从业人员缴纳保险费； (八)厂房、作业场所和安全设施、设备、工艺符合有关安全生产法律、法规、标准和规程的要求； (九)有职业危害防治措施，并为从业人员配备符合国家标准或者行业标准的劳动防护用品； (十)依法进行安全评价； (十一)有重大危险源检测、评估、监控措施和应急预案； (十二)有生产安全事故应急救援预案、应急救援组织或者应急救援人员，配备必要的应急救援器材、设备； (十三)法律、法规规定的其他条件。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第七条", "text": "企业进行生产前，应当依照本条例的规定向安全生产许可证颁发管理机关申请领取安全生产许可证，并提供本条例"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第六条", "text": "规定的相关文件、资料。安全生产许可证颁发管理机关应当自收到申请之日起45日内审查完毕，经审查符合本条例规定的安全生产条件的，颁发安全生产许可证；不符合本条例规定的安全生产条件的，不予颁发安全生产许可证，书面通知企业并说明理由。 煤矿企业应当以矿(井)为单位，依照本条例的规定取得安全生产许可证。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第八条", "text": "安全生产许可证由国务院安全生产监督管理部门规定统一的式样。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第九条", "text": "安全生产许可证的有效期为3年。安全生产许可证有效期满需要延期的，企业应当于期满前3个月向原安全生产许可证颁发管理机关办理延期手续。 企业在安全生产许可证有效期内，严格遵守有关安全生产的法律法规，未发生死亡事故的，安全生产许可证有效期届满时，经原安全生产许可证颁发管理机关同意，不再审查，安全生产许可证有效期延期3年。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第十条", "text": "安全生产许可证颁发管理机关应当建立、健全安全生产许可证档案管理制度，并定期向社会公布企业取得安全生产许可证的情况。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第十一条", "text": "煤矿企业安全生产许可证颁发管理机关、建筑施工企业安全生产许可证颁发管理机关、民用爆炸物品生产企业安全生产许可证颁发管理机关，应当每年向同级安全生产监督管理部门通报其安全生产许可证颁发和管理情况。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第十二条", "text": "国务院安全生产监督管理部门和省、自治区、直辖市人民政府安全生产监督管理部门对建筑施工企业、民用爆炸物品生产企业、煤矿企业取得安全生产许可证的情况进行监督。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第十三条", "text": "企业不得转让、冒用安全生产许可证或者使用伪造的安全生产许可证。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第十四条", "text": "企业取得安全生产许可证后，不得降低安全生产条件，并应当加强日常安全生产管理，接受安全生产许可证颁发管理机关的监督检查。 安全生产许可证颁发管理机关应当加强对取得安全生产许可证的企业的监督检查，发现其不再具备本条例规定的安全生产条件的，应当暂扣或者吊销安全生产许可证。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第十五条", "text": "安全生产许可证颁发管理机关工作人员在安全生产许可证颁发、管理和监督检查工作中，不得索取或者接受企业的财物，不得谋取其他利益。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第十六条", "text": "监察机关依照《中华人民共和国行政监察法》的规定，对安全生产许可证颁发管理机关及其工作人员履行本条例规定的职责实施监察。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第十七条", "text": "任何单位或者个人对违反本条例规定的行为，有权向安全生产许可证颁发管理机关或者监察机关等有关部门举报。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第十八条", "text": "安全生产许可证颁发管理机关工作人员有下列行为之一的，给予降级或者撤职的行政处分；构成犯罪的，依法追究刑事责任： (一)向不符合本条例规定的安全生产条件的企业颁发安全生产许可证的； (二)发现企业未依法取得安全生产许可证擅自从事生产活动，不依法处理的； (三)发现取得安全生产许可证的企业不再具备本条例规定的安全生产条件，不依法处理的； (四)接到对违反本条例规定行为的举报后，不及时处理的； (五)在安全生产许可证颁发、管理和监督检查工作中，索取或者接受企业的财物，或者谋取其他利益的。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第十九条", "text": "违反本条例规定，未取得安全生产许可证擅自进行生产的，责令停止生产，没收违法所得，并处10万元以上50万元以下的罚款；造成重大事故或者其他严重后果，构成犯罪的，依法追究刑事责任。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第二十条", "text": "违反本条例规定，安全生产许可证有效期满未办理延期手续，继续进行生产的，责令停止生产，限期补办延期手续，没收违法所得，并处5万元以上10万元以下的罚款；逾期仍不办理延期手续，继续进行生产的，依照本条例"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第二十一条", "text": "违反本条例规定，转让安全生产许可证的，没收违法所得，处10万元以上50万元以下的罚款，并吊销其安全生产许可证；构成犯罪的，依法追究刑事责任；接受转让的，依照本条例"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第十九条", "text": "的规定处罚。 冒用安全生产许可证或者使用伪造的安全生产许可证的，依照本条例"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第二十二条", "text": "本条例施行前已经进行生产的企业，应当自本条例施行之日起1年内，依照本条例的规定向安全生产许可证颁发管理机关申请办理安全生产许可证；逾期不办理安全生产许可证，或者经审查不符合本条例规定的安全生产条件，未取得安全生产许可证，继续进行生产的，依照本条例"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第二十三条", "text": "本条例规定的行政处罚，由安全生产许可证颁发管理机关决定。"}, {"law": "安全生产许可证条例_20140729.docx", "no": "第二十四条", "text": "本条例自公布之日起施行。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第一条", "text": "为了规范发展安全生产责任保险（以下简称安责险），保障保险合同当事人的合法权益，切实发挥保险机构参与风险评估管控和事故预防功能，根据《中共中央 国务院关于推进安全生产领域改革发展的意见》和《中华人民共和国保险法》《中华人民共和国安全生产法》有关规定，制定本办法。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第二条", "text": "在中华人民共和国领域内从事矿山、危险化学品、烟花爆竹、交通运输、建筑施工、民用爆炸物品、金属冶炼、渔业生产等高危行业、领域生产经营活动的单位（以下简称高危行业、领域单位），应当投保安责险。 本办法适用于高危行业、领域单位安责险的投保与承保、事故预防服务、理赔、监督与管理。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第三条", "text": "安责险的赔偿范围包括被保险人因生产安全事故造成的依法应负的从业人员人身伤亡赔偿，第三者人身伤亡和财产损失赔偿，及相关事故抢险救援、医疗救护、事故鉴定、法律诉讼等费用。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第四条", "text": "保险机构为高危行业、领域单位承保安责险，应当按照相关规定和合同约定提供事故预防服务。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第五条", "text": "规范安责险和道路运输承运人责任险的衔接，优化保险产品设计，避免重复投保。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第六条", "text": "生产经营单位应当及时足额缴纳安责险保费，不得以任何方式摊派给从业人员个人。保费可以据实从企业安全生产费用中列支。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第七条", "text": "保险机构应当做好保险承保理赔和事故预防服务，依法承担保险赔偿责任，积极参与社会管理，安全生产的主体责任由生产经营单位负责。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第八条", "text": "保险机构为被保险人开展事故预防服务，应当委托具有相应资质或能力的安全生产技术服务机构。保险机构可以投资安全生产技术服务机构开展事故预防服务。 受保险机构委托开展事故预防服务的安全生产技术服务机构应当依法提供专业技术服务，参与安全生产社会化治理。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第九条", "text": "国务院应急管理部门负责综合协调、统筹推动各高危行业、领域单位安责险实施工作，对本行业、领域单位安责险投保情况等实施监督管理；与国务院财政部门和保险监督管理机构、负有安全生产监督管理职责的相关行业主管部门（以下简称相关行业主管部门）建立联合工作机制，制定实施管理制度和标准规范，建立全国安责险事故预防服务信息管理系统；会同国务院相关行业主管部门指导监督高危行业、领域单位安责险事故预防服务情况。 国务院保险监督管理机构负责依法对开展安责险的保险机构及其实施的承保、理赔和事故预防服务支出等有关业务活动实施监督管理。 国务院相关行业主管部门依法对本行业、领域单位安责险投保情况等实施监督管理。 各省级应急管理部门、相关行业主管部门及国务院保险监督管理机构省级派出机构按照前款对应的职责开展相关工作。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第十条", "text": "坚持风险防控、费率合理、理赔及时的原则，按照政府监管、市场运作的方式实施安责险工作。 第二章 投保与承保"}, {"law": "安全生产责任保险实施办法.docx", "no": "第十一条", "text": "承保安责险的保险机构应当符合相关法律法规和标准规范要求，具有相应的专业资质和能力，并满足以下条件： （一）商业信誉良好，业务开展地的营业机构近三年安责险经营活动无重大违法违规记录； （二）有配套的营业机构网点； （三）有充足的偿付能力； （四）配备组织开展事故预防服务的管理人员； （五）满足保险监督管理机构规定的其他条件。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第十二条", "text": "国务院保险监督管理机构指导中国保险行业协会在充分征求国务院应急管理部门等相关部门、单位意见的基础上，制定发布安责险行业标准条款。 保险机构应当严格执行行业标准条款，不得以签订补充协议等形式改变条款内容。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第十三条", "text": "安责险费率实行行业差别费率和浮动费率。 国务院保险监督管理机构省级派出机构会同本级应急管理部门和相关行业主管部门，指导有关保险行业组织制定发布本地区各行业、领域单位的安责险纯风险损失率，并根据安责险业务的总体盈利亏损情况和市场实际风险情况及时调整，供保险机构参考使用；指导保险机构建立费率动态调整机制，费率调整可以根据被保险人的事故记录和等级、安全生产标准化建设情况、安全生产违法失信行为、配合整改事故隐患情况等因素综合确定。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第十四条", "text": "保险机构应当根据安责险纯风险损失率，科学运用差别费率和浮动费率，按照公平、合理、充足的原则厘定承保费率，促进生产经营单位持续改进安全生产工作，不得恶意低价承保妨碍市场公平竞争。 保险机构承保高危行业、领域单位的安责险，支付佣金比例不得高于5%。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第十五条", "text": "每人死亡伤残责任限额不得低于40万元。各地区可根据实际情况确定安责险中涉及人员死亡的最低责任限额，并按本地区城镇居民人均可支配收入的变化适时调整。 法律、行政法规对生产经营单位的赔偿责任限额另有规定的，从其规定。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第十六条", "text": "生产经营单位应当自主选择符合条件的保险机构足额投保。 安责险的保障范围应当覆盖全体从业人员，保险金额实行同一标准，不得因用工方式、工作岗位等差别对待。 除被依法关闭取缔、完全停止生产经营活动外，应当投保安责险的生产经营单位不得退保、延迟续保。 第三章 事故预防服务"}, {"law": "安全生产责任保险实施办法.docx", "no": "第十七条", "text": "各省级应急管理部门可以会同本级相关行业主管部门、国务院保险监督管理机构省级派出机构根据本地区各行业、领域单位特点和被保险人实际，制定事故预防服务的细则或标准，规范事故预防服务行为，提高服务质量。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第十八条", "text": "应急管理部门和相关部门应当加强对事故预防服务的监督指导，可以按规定通过政府购买服务等方式委托具有专业技术能力和管理经验的社会组织、企事业单位等机构参与事故预防服务的管理工作。 支持生产经营单位、保险机构、有关社会组织及企事业单位等机构建立三方合作机制，加强事故预防服务自主管理和自我约束，确保公平公正合规运行。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第十九条", "text": "保险机构应当与投保人在保险合同中或单独签订服务合同约定事故预防服务的具体内容及频次，协助被保险人降低安全风险。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第二十条", "text": "事故预防服务应当符合被保险人安全生产工作实际，确保适用可行，并根据被保险人合理的意见和需求及时改进，可以参照以下内容选择一项或多项服务项目，协助被保险人开展事故预防工作： （一）安全生产宣传教育培训； （二）安全风险辨识、评估、评价； （三）安全生产标准化管理体系建设； （四）生产安全重大事故隐患排查； （五）安全生产应急预案编制和应急救援演练； （六）安全生产科技创新、装备研发推广应用； （七）其他有关事故预防工作。 保险机构每年至少为大中型被保险人提供1次上述第（二）项或第（四）项服务，各地区通过制定事故预防服务细则或标准明确不同类型被保险人的服务项目及频次。 国务院相关行业主管部门对事故预防服务另有规定的，按其规定执行。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第二十一条", "text": "保险机构应当加强事故预防服务风控团队和专业能力建设，建立管理制度，规范服务流程，完善内部控制，管理人员数量和专业能力应当与所承保安责险业务相匹配。 从事事故预防服务的机构应当遵守应急管理部门和相关行业主管部门的规定，按照合同约定开展服务，不得弄虚作假、出具虚假服务报告。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第二十二条", "text": "保险机构应当保证事故预防服务费用投入，依据相关规定和合同约定，按照不高于安责险实际收取保费的21%投入事故预防服务费用，制定专项预算，据实支出，不得挤占、挪用。 各省级应急管理部门可以会同本级相关行业主管部门、国务院保险监督管理机构省级派出机构根据本地区各行业、领域单位特点和被保险人实际，合理制定事故预防服务费用的年度预算目标。 事故预防服务费用应当专门用于被保险人的事故预防及相关技术支持工作，以降低生产安全事故风险或减少事故损失为主要目的，不得随意扩大使用范围。 保险机构应当严格遵守有关财经政策，按照企业会计准则对事故预防服务费用进行账务处理，建立专门台账，确保数据真实准确，并接受应急管理部门、财政部门、保险监督管理机构和相关行业主管部门的监督。保险机构应当据实开支事故预防服务费用，不得通过事故预防服务套取费用或从事其他违法违规行为。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第二十三条", "text": "被保险人应当配合保险机构开展事故预防服务，并对服务中发现的生产安全事故隐患及时进行整改；对未按时限整改重大事故隐患的，保险机构应当将重大事故隐患情况及时上报应急管理部门、保险监督管理机构和相关行业主管部门，并可以按照法律规定或合同约定向投保人要求增加保险费或者解除保险合同；保险机构主动解除合同的，应当及时将有关信息向应急管理部门、保险监督管理机构和相关行业主管部门报告。 事故预防服务不得影响被保险人正常的生产经营活动，不得泄露被保险人的职工信息、技术秘密和商业秘密。 被保险人应当遵守国家有关安全、消防、生产操作、劳动保护等方面的规定，切实履行安全生产主体责任，提高安全生产水平。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第二十四条", "text": "保险机构应当为被保险人建立事故预防服务档案，确保服务过程可追溯。 保险机构和被保险人应当留存事故预防服务档案，妥善保管，留存期限不少于5年，期间不得篡改、隐匿或销毁。 鼓励保险机构建立事故预防服务信息管理系统，对事故预防服务业务数据、费用台账、制度标准、服务档案进行采集和存储。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第二十五条", "text": "保险机构应当按照被保险人所在地省级应急管理部门、保险监督管理机构和相关行业主管部门规定，提供事故预防服务相关数据。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第二十六条", "text": "支持有关保险行业组织建设全国安责险信息共享平台，对安责险信息进行归集和分析，为国务院相关部门、省级政府相关部门和投保企业提供保险机构和保单信息查询等服务，为安责险规范发展提供信息支持，并保障数据安全。 第四章 理赔"}, {"law": "安全生产责任保险实施办法.docx", "no": "第二十七条", "text": "保险事故发生后，保险机构应当严格按照法律规定和合同约定及时赔偿保险金，并建立重大或典型事故快速理赔机制和预付赔款机制，在事故发生后按照法律规定和合同约定快速支付或先行支付已确定的赔偿保险金。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第二十八条", "text": "保险事故发生后，被保险人应当及时通知保险机构，保险机构应当及时给予答复，告知被保险人具体的赔偿程序等有关事项。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第二十九条", "text": "保险机构对被保险人给从业人员或第三者造成的损害，可以依照法律规定或合同约定，直接向受害者赔偿保险金。被保险人怠于请求的，受害者有权就其应获赔偿部分直接向保险机构请求赔付。 被保险人给从业人员或第三者造成损害，被保险人未向受害者赔偿的，保险机构不得向被保险人赔偿保险金。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第三十条", "text": "应急管理部门和相关行业主管部门应当为生产安全事故的认定、保险机构赔偿保险金或先行支付赔偿保险金等有关工作提供必要的条件支持。 第五章 监督与管理"}, {"law": "安全生产责任保险实施办法.docx", "no": "第三十一条", "text": "应急管理部门、财政部门、保险监督管理机构和相关行业主管部门应当依据工作职责依法加强对生产经营单位、保险机构和安全生产技术服务机构的监督管理。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第三十二条", "text": "应急管理部门、相关行业主管部门和保险监督管理机构应当建立安责险信息共享机制，对高危行业、领域单位的基础信息、安全生产技术服务机构信息、保险机构承保赔款信息、事故预防服务信息、事故预防服务支出信息等进行数据交互共享。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第三十三条", "text": "各地区应当将实施安责险制度情况，列入本级政府有关部门和下级人民政府及其有关部门安全生产工作重点并督促落实到位。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第三十四条", "text": "中央企业或集团型企业分支机构安责险的投保和事故预防服务工作，应当依法接受实际生产经营所在地市级及以上应急管理部门、相关行业主管部门的监督管理。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第三十五条", "text": "保险机构在经营安责险业务中，违反本办法相关规定，有下列情形之一的，保险监督管理机构可以依法采取监管谈话、限期整改、行政处罚等监管措施。应急管理部门和相关行业主管部门发现保险机构开展事故预防服务有下列有关情形的，应当及时通报保险监督管理机构，并可以视严重程度和危害程度采取约谈、限期整改。 （一）违反《中华人民共和国保险法》规定无正当理由拖延承保、拒绝承保、解除安责险合同的； （二）为谋取交易机会或竞争优势，存在超出佣金比例上限、返还手续费、恶意低价承保、商业贿赂、虚假宣传等扰乱市场秩序行为的； （三）以故意夸大事故隐患引诱生产经营单位与其订立安责险合同的； （四）未依据合同约定及时支付或预付赔偿保险金的； （五）未依据相关规定或合同约定足额投入事故预防服务费用的，事故预防服务费用管理和使用不规范的； （六）未按相关规定或合同约定开展事故预防服务，以及无正当理由拖欠受委托机构事故预防服务费用的； （七）不如实提供安责险相关业务数据或档案资料的； （八）泄露被保险人职工信息或技术秘密、商业秘密的； （九）违反相关法律、行政法规的其他情形。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第三十六条", "text": "受保险机构委托开展事故预防服务的安全生产技术服务机构，未按相关规定或委托合同约定开展事故预防服务或事故预防服务报告弄虚作假的，保险机构可以终止委托合同，并将相关情形报告应急管理部门、保险监督管理机构和相关行业主管部门，相关部门可以依法采取约谈、限期整改等措施；违反相关法律法规的，依法追究其法律责任。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第三十七条", "text": "应急管理部门和相关行业主管部门应当加大执法检查力度，对生产经营单位未依法投保安责险的，依照《中华人民共和国安全生产法》有关规定予以处罚。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第三十八条", "text": "生产经营单位有下列情形之一的，应急管理部门和相关行业主管部门应当责令限期整改；对拒不整改的，加大执法检查频次；对违反相关法律法规规定的，依法追究其法律责任。 （一）将保费以各种形式摊派给从业人员个人的； （二）未全员投保或未足额投保的； （三）对事故预防服务不予配合的； （四）违反相关法律法规和标准规范的其他情形。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第三十九条", "text": "应急管理部门、保险监督管理机构和相关行业主管部门不得滥用行政权力，排斥、限制市场公平竞争或对市场份额进行分割、分配。对于因政府干预导致市场垄断现象发生的，严格依规依纪依法处理。 对各类参与主体违反《中华人民共和国反垄断法》规定，滥用市场支配地位或者达成垄断协议，破坏公平竞争、损害投保生产经营单位或者其他主体合法权益的行为，依据《中华人民共和国反垄断法》等法律法规移送有关主管部门予以查处。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第四十条", "text": "应急管理部门、保险监督管理机构和相关行业主管部门及其工作人员不得滥用行政权力违规干预安责险市场经营活动，不得违规挪用、占用事故预防服务费用。对在监管过程中收取贿赂、滥用职权、玩忽职守、徇私舞弊的，依法依规对相关责任人严肃追责；涉嫌犯罪的，移交司法机关依法处理。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第四十一条", "text": "加强社会监督，建立事故预防服务评估公示制度，应急管理部门和相关行业主管部门应当会同保险监督管理机构定期对事故预防服务工作进行评估，形成评估报告，并将评估结果向社会公示。 应急管理部门、相关行业主管部门和保险监督管理机构应当按职责依法受理安责险投保和事故预防服务有关违法违规行为投诉举报，并及时依法依规处理。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第四十二条", "text": "应急管理部门和相关行业主管部门、保险监督管理机构应当加大安责险宣传力度，总结推广事故预防服务优秀案例，发挥先进典型的示范带动作用。 第六章 附则"}, {"law": "安全生产责任保险实施办法.docx", "no": "第二条", "text": "所指应当投保安责险的高危行业、领域单位的用语含义是： 矿山行业、领域单位是指在依法批准的矿区范围内从事矿产资源勘探和矿山建设、生产、闭坑及有关活动的单位。矿山行业、领域单位包括的石油天然气（包括页岩油、页岩气）开采单位，是指从事陆上采油（气）、海洋采油（气）、物探、钻井、测井、录井、井下作业、油建、海油工程等活动的单位。 危险化学品行业、领域单位是指从事危险化学品生产、经营（无储存设施的除外）等活动的单位。危险化学品是指列入《危险化学品目录》的化学品。 烟花爆竹行业、领域单位是指从事烟花爆竹制品和用于生产烟花爆竹的民用黑火药、烟火药、引火线等物品有关的生产、经营等活动的单位。 交通运输行业、领域单位包括道路运输、水路运输、管道运输等行业、领域的单位。道路运输单位是指从事《中华人民共和国道路运输条例》规定的道路旅客运输和危险货物道路运输的单位；水路运输单位是指从事《中华人民共和国港口法》规定的旅客和危险货物港口作业的单位；管道运输单位是指从事以管道为工具的液体和气体物资运输的单位。 建筑施工行业、领域单位是指从事土木工程、建筑工程、线路管道、设备安装、装修工程、井巷工程、矿山建设、水利工程建设、交通建设工程等的单位，包括从事新建、扩建、改建、拆除的单位。 民用爆炸物品行业、领域单位是指从事列入《民用爆炸物品品名表》的物品有关的生产、储存、销售、运输、爆破作业和销毁等活动的单位。 金属冶炼行业、领域单位是指从事纳入《金属冶炼目录（2015年版）》等生产活动的单位。 渔业生产行业、领域单位是指在海洋开放水域从事水生动植物养殖、捕捞及运输等作业活动的单位，包含以个体工商户、合作社、家庭和渔船从事渔业生产经营活动的单位。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第十四条", "text": "所使用下列用语的含义是： 从业人员是指被保险人的员工、临时聘用人员和被派遣劳动者等有用工关系的人员，第三者是指除前述从业人员以外的人员。 佣金是指保险代理人、保险经纪人为投保人与保险机构订立保险合同提供中介服务的，保险机构按照保险费的一定比例支付给保险代理人或保险经纪人的报酬。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第四十五条", "text": "鼓励本办法规定的高危行业、领域以外的生产经营单位投保安责险。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第四十六条", "text": "各省级应急管理部门、财政部门、保险监督管理机构和相关行业主管部门可以依据本办法制定具体实施细则。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第四十七条", "text": "本办法由国务院应急管理部门会同国务院财政部门、国务院保险监督管理机构和国务院相关行业主管部门负责解释。"}, {"law": "安全生产责任保险实施办法.docx", "no": "第四十八条", "text": "本办法自发布之日起施行。原国家安全生产监督管理总局、原中国保险监督管理委员会、财政部2017年12月12日公布的《安全生产责任保险实施办法》（安监总办〔2017〕140号）同时废止。"}, {"law": "工伤保险条例_20101220.docx", "no": "第一条", "text": "为了保障因工作遭受事故伤害或者患职业病的职工获得医疗救治和经济补偿，促进工伤预防和职业康复，分散用人单位的工伤风险，制定本条例。"}, {"law": "工伤保险条例_20101220.docx", "no": "第二条", "text": "中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织和有雇工的个体工商户(以下称用人单位)应当依照本条例规定参加工伤保险，为本单位全部职工或者雇工(以下称职工)缴纳工伤保险费。 中华人民共和国境内的企业、事业单位、社会团体、民办非企业单位、基金会、律师事务所、会计师事务所等组织的职工和个体工商户的雇工，均有依照本条例的规定享受工伤保险待遇的权利。"}, {"law": "工伤保险条例_20101220.docx", "no": "第三条", "text": "工伤保险费的征缴按照《社会保险费征缴暂行条例》关于基本养老保险费、基本医疗保险费、失业保险费的征缴规定执行。"}, {"law": "工伤保险条例_20101220.docx", "no": "第四条", "text": "用人单位应当将参加工伤保险的有关情况在本单位内公示。 用人单位和职工应当遵守有关安全生产和职业病防治的法律法规，执行安全卫生规程和标准，预防工伤事故发生，避免和减少职业病危害。 职工发生工伤时，用人单位应当采取措施使工伤职工得到及时救治。"}, {"law": "工伤保险条例_20101220.docx", "no": "第五条", "text": "国务院社会保险行政部门负责全国的工伤保险工作。 县级以上地方各级人民政府社会保险行政部门负责本行政区域内的工伤保险工作。 社会保险行政部门按照国务院有关规定设立的社会保险经办机构(以下称经办机构)具体承办工伤保险事务。"}, {"law": "工伤保险条例_20101220.docx", "no": "第六条", "text": "社会保险行政部门等部门制定工伤保险的政策、标准，应当征求工会组织、用人单位代表的意见。 第二章 工伤保险基金"}, {"law": "工伤保险条例_20101220.docx", "no": "第七条", "text": "工伤保险基金由用人单位缴纳的工伤保险费、工伤保险基金的利息和依法纳入工伤保险基金的其他资金构成。"}, {"law": "工伤保险条例_20101220.docx", "no": "第八条", "text": "工伤保险费根据以支定收、收支平衡的原则，确定费率。 国家根据不同行业的工伤风险程度确定行业的差别费率，并根据工伤保险费使用、工伤发生率等情况在每个行业内确定若干费率档次。行业差别费率及行业内费率档次由国务院社会保险行政部门制定，报国务院批准后公布施行。 统筹地区经办机构根据用人单位工伤保险费使用、工伤发生率等情况，适用所属行业内相应的费率档次确定单位缴费费率。"}, {"law": "工伤保险条例_20101220.docx", "no": "第九条", "text": "国务院社会保险行政部门应当定期了解全国各统筹地区工伤保险基金收支情况，及时提出调整行业差别费率及行业内费率档次的方案，报国务院批准后公布施行。"}, {"law": "工伤保险条例_20101220.docx", "no": "第十条", "text": "用人单位应当按时缴纳工伤保险费。职工个人不缴纳工伤保险费。 用人单位缴纳工伤保险费的数额为本单位职工工资总额乘以单位缴费费率之积。 对难以按照工资总额缴纳工伤保险费的行业，其缴纳工伤保险费的具体方式，由国务院社会保险行政部门规定。"}, {"law": "工伤保险条例_20101220.docx", "no": "第十一条", "text": "工伤保险基金逐步实行省级统筹。 跨地区、生产流动性较大的行业，可以采取相对集中的方式异地参加统筹地区的工伤保险。具体办法由国务院社会保险行政部门会同有关行业的主管部门制定。"}, {"law": "工伤保险条例_20101220.docx", "no": "第十二条", "text": "工伤保险基金存入社会保障基金财政专户，用于本条例规定的工伤保险待遇，劳动能力鉴定，工伤预防的宣传、培训等费用，以及法律、法规规定的用于工伤保险的其他费用的支付。 工伤预防费用的提取比例、使用和管理的具体办法，由国务院社会保险行政部门会同国务院财政、卫生行政、安全生产监督管理等部门规定。 任何单位或者个人不得将工伤保险基金用于投资运营、兴建或者改建办公场所、发放奖金，或者挪作其他用途。"}, {"law": "工伤保险条例_20101220.docx", "no": "第十三条", "text": "工伤保险基金应当留有一定比例的储备金，用于统筹地区重大事故的工伤保险待遇支付；储备金不足支付的，由统筹地区的人民政府垫付。储备金占基金总额的具体比例和储备金的使用办法，由省、自治区、直辖市人民政府规定。 第三章 工伤认定"}, {"law": "工伤保险条例_20101220.docx", "no": "第十四条", "text": "职工有下列情形之一的，应当认定为工伤： (一)在工作时间和工作场所内，因工作原因受到事故伤害的； (二)工作时间前后在工作场所内，从事与工作有关的预备性或者收尾性工作受到事故伤害的； (三)在工作时间和工作场所内，因履行工作职责受到暴力等意外伤害的； (四)患职业病的； (五)因工外出期间，由于工作原因受到伤害或者发生事故下落不明的； (六)在上下班途中，受到非本人主要责任的交通事故或者城市轨道交通、客运轮渡、火车事故伤害的； (七)法律、行政法规规定应当认定为工伤的其他情形。"}, {"law": "工伤保险条例_20101220.docx", "no": "第十五条", "text": "职工有下列情形之一的，视同工伤： (一)在工作时间和工作岗位，突发疾病死亡或者在48小时之内经抢救无效死亡的； (二)在抢险救灾等维护国家利益、公共利益活动中受到伤害的； (三)职工原在军队服役，因战、因公负伤致残，已取得革命伤残军人证，到用人单位后旧伤复发的。 职工有前款第(一)项、第(二)项情形的，按照本条例的有关规定享受工伤保险待遇；职工有前款第(三)项情形的，按照本条例的有关规定享受除一次性伤残补助金以外的工伤保险待遇。"}, {"law": "工伤保险条例_20101220.docx", "no": "第十五条", "text": "的规定，但是有下列情形之一的，不得认定为工伤或者视同工伤： (一)故意犯罪的； (二)醉酒或者吸毒的； (三)自残或者自杀的。"}, {"law": "工伤保险条例_20101220.docx", "no": "第十七条", "text": "职工发生事故伤害或者按照职业病防治法规定被诊断、鉴定为职业病，所在单位应当自事故伤害发生之日或者被诊断、鉴定为职业病之日起30日内，向统筹地区社会保险行政部门提出工伤认定申请。遇有特殊情况，经报社会保险行政部门同意，申请时限可以适当延长。 用人单位未按前款规定提出工伤认定申请的，工伤职工或者其近亲属、工会组织在事故伤害发生之日或者被诊断、鉴定为职业病之日起1年内，可以直接向用人单位所在地统筹地区社会保险行政部门提出工伤认定申请。 按照本条第一款规定应当由省级社会保险行政部门进行工伤认定的事项，根据属地原则由用人单位所在地的设区的市级社会保险行政部门办理。 用人单位未在本条第一款规定的时限内提交工伤认定申请，在此期间发生符合本条例规定的工伤待遇等有关费用由该用人单位负担。"}, {"law": "工伤保险条例_20101220.docx", "no": "第十八条", "text": "提出工伤认定申请应当提交下列材料： (一)工伤认定申请表； (二)与用人单位存在劳动关系(包括事实劳动关系)的证明材料； (三)医疗诊断证明或者职业病诊断证明书(或者职业病诊断鉴定书)。 工伤认定申请表应当包括事故发生的时间、地点、原因以及职工伤害程度等基本情况。 工伤认定申请人提供材料不完整的，社会保险行政部门应当一次性书面告知工伤认定申请人需要补正的全部材料。申请人按照书面告知要求补正材料后，社会保险行政部门应当受理。"}, {"law": "工伤保险条例_20101220.docx", "no": "第十九条", "text": "社会保险行政部门受理工伤认定申请后，根据审核需要可以对事故伤害进行调查核实，用人单位、职工、工会组织、医疗机构以及有关部门应当予以协助。职业病诊断和诊断争议的鉴定，依照职业病防治法的有关规定执行。对依法取得职业病诊断证明书或者职业病诊断鉴定书的，社会保险行政部门不再进行调查核实。 职工或者其近亲属认为是工伤，用人单位不认为是工伤的，由用人单位承担举证责任。"}, {"law": "工伤保险条例_20101220.docx", "no": "第二十条", "text": "社会保险行政部门应当自受理工伤认定申请之日起60日内作出工伤认定的决定，并书面通知申请工伤认定的职工或者其近亲属和该职工所在单位。 社会保险行政部门对受理的事实清楚、权利义务明确的工伤认定申请，应当在15日内作出工伤认定的决定。 作出工伤认定决定需要以司法机关或者有关行政主管部门的结论为依据的，在司法机关或者有关行政主管部门尚未作出结论期间，作出工伤认定决定的时限中止。 社会保险行政部门工作人员与工伤认定申请人有利害关系的，应当回避。 第四章 劳动能力鉴定"}, {"law": "工伤保险条例_20101220.docx", "no": "第二十一条", "text": "职工发生工伤，经治疗伤情相对稳定后存在残疾、影响劳动能力的，应当进行劳动能力鉴定。"}, {"law": "工伤保险条例_20101220.docx", "no": "第二十二条", "text": "劳动能力鉴定是指劳动功能障碍程度和生活自理障碍程度的等级鉴定。 劳动功能障碍分为十个伤残等级，最重的为一级，最轻的为十级。 生活自理障碍分为三个等级：生活完全不能自理、生活大部分不能自理和生活部分不能自理。 劳动能力鉴定标准由国务院社会保险行政部门会同国务院卫生行政部门等部门制定。"}, {"law": "工伤保险条例_20101220.docx", "no": "第二十三条", "text": "劳动能力鉴定由用人单位、工伤职工或者其近亲属向设区的市级劳动能力鉴定委员会提出申请，并提供工伤认定决定和职工工伤医疗的有关资料。"}, {"law": "工伤保险条例_20101220.docx", "no": "第二十四条", "text": "省、自治区、直辖市劳动能力鉴定委员会和设区的市级劳动能力鉴定委员会分别由省、自治区、直辖市和设区的市级社会保险行政部门、卫生行政部门、工会组织、经办机构代表以及用人单位代表组成。 劳动能力鉴定委员会建立医疗卫生专家库。列入专家库的医疗卫生专业技术人员应当具备下列条件： (一)具有医疗卫生高级专业技术职务任职资格； (二)掌握劳动能力鉴定的相关知识； (三)具有良好的职业品德。"}, {"law": "工伤保险条例_20101220.docx", "no": "第二十五条", "text": "设区的市级劳动能力鉴定委员会收到劳动能力鉴定申请后，应当从其建立的医疗卫生专家库中随机抽取3名或者5名相关专家组成专家组，由专家组提出鉴定意见。设区的市级劳动能力鉴定委员会根据专家组的鉴定意见作出工伤职工劳动能力鉴定结论；必要时，可以委托具备资格的医疗机构协助进行有关的诊断。 设区的市级劳动能力鉴定委员会应当自收到劳动能力鉴定申请之日起60日内作出劳动能力鉴定结论，必要时，作出劳动能力鉴定结论的期限可以延长30日。劳动能力鉴定结论应当及时送达申请鉴定的单位和个人。"}, {"law": "工伤保险条例_20101220.docx", "no": "第二十六条", "text": "申请鉴定的单位或者个人对设区的市级劳动能力鉴定委员会作出的鉴定结论不服的，可以在收到该鉴定结论之日起15日内向省、自治区、直辖市劳动能力鉴定委员会提出再次鉴定申请。省、自治区、直辖市劳动能力鉴定委员会作出的劳动能力鉴定结论为最终结论。"}, {"law": "工伤保险条例_20101220.docx", "no": "第二十七条", "text": "劳动能力鉴定工作应当客观、公正。劳动能力鉴定委员会组成人员或者参加鉴定的专家与当事人有利害关系的，应当回避。"}, {"law": "工伤保险条例_20101220.docx", "no": "第二十八条", "text": "自劳动能力鉴定结论作出之日起1年后，工伤职工或者其近亲属、所在单位或者经办机构认为伤残情况发生变化的，可以申请劳动能力复查鉴定。"}, {"law": "工伤保险条例_20101220.docx", "no": "第二十九条", "text": "劳动能力鉴定委员会依照本条例"}, {"law": "工伤保险条例_20101220.docx", "no": "第二十八条", "text": "的规定进行再次鉴定和复查鉴定的期限，依照本条例"}, {"law": "工伤保险条例_20101220.docx", "no": "第二十五条", "text": "第二款的规定执行。 第五章 工伤保险待遇"}, {"law": "工伤保险条例_20101220.docx", "no": "第三十条", "text": "职工因工作遭受事故伤害或者患职业病进行治疗，享受工伤医疗待遇。 职工治疗工伤应当在签订服务协议的医疗机构就医，情况紧急时可以先到就近的医疗机构急救。 治疗工伤所需费用符合工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准的，从工伤保险基金支付。工伤保险诊疗项目目录、工伤保险药品目录、工伤保险住院服务标准，由国务院社会保险行政部门会同国务院卫生行政部门、食品药品监督管理部门等部门规定。 职工住院治疗工伤的伙食补助费，以及经医疗机构出具证明，报经办机构同意，工伤职工到统筹地区以外就医所需的交通、食宿费用从工伤保险基金支付，基金支付的具体标准由统筹地区人民政府规定。 工伤职工治疗非工伤引发的疾病，不享受工伤医疗待遇，按照基本医疗保险办法处理。 工伤职工到签订服务协议的医疗机构进行工伤康复的费用，符合规定的，从工伤保险基金支付。"}, {"law": "工伤保险条例_20101220.docx", "no": "第三十一条", "text": "社会保险行政部门作出认定为工伤的决定后发生行政复议、行政诉讼的，行政复议和行政诉讼期间不停止支付工伤职工治疗工伤的医疗费用。"}, {"law": "工伤保险条例_20101220.docx", "no": "第三十二条", "text": "工伤职工因日常生活或者就业需要，经劳动能力鉴定委员会确认，可以安装假肢、矫形器、假眼、假牙和配置轮椅等辅助器具，所需费用按照国家规定的标准从工伤保险基金支付。"}, {"law": "工伤保险条例_20101220.docx", "no": "第三十三条", "text": "职工因工作遭受事故伤害或者患职业病需要暂停工作接受工伤医疗的，在停工留薪期内，原工资福利待遇不变，由所在单位按月支付。 停工留薪期一般不超过12个月。伤情严重或者情况特殊，经设区的市级劳动能力鉴定委员会确认，可以适当延长，但延长不得超过12个月。工伤职工评定伤残等级后，停发原待遇，按照本章的有关规定享受伤残待遇。工伤职工在停工留薪期满后仍需治疗的，继续享受工伤医疗待遇。 生活不能自理的工伤职工在停工留薪期需要护理的，由所在单位负责。"}, {"law": "工伤保险条例_20101220.docx", "no": "第三十四条", "text": "工伤职工已经评定伤残等级并经劳动能力鉴定委员会确认需要生活护理的，从工伤保险基金按月支付生活护理费。 生活护理费按照生活完全不能自理、生活大部分不能自理或者生活部分不能自理3个不同等级支付，其标准分别为统筹地区上年度职工月平均工资的50%、40%或者30%。"}, {"law": "工伤保险条例_20101220.docx", "no": "第三十五条", "text": "职工因工致残被鉴定为一级至四级伤残的，保留劳动关系，退出工作岗位，享受以下待遇： (一)从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：一级伤残为27个月的本人工资，二级伤残为25个月的本人工资，三级伤残为23个月的本人工资，四级伤残为21个月的本人工资； (二)从工伤保险基金按月支付伤残津贴，标准为：一级伤残为本人工资的90%，二级伤残为本人工资的85%，三级伤残为本人工资的80%，四级伤残为本人工资的75%。伤残津贴实际金额低于当地最低工资标准的，由工伤保险基金补足差额； (三)工伤职工达到退休年龄并办理退休手续后，停发伤残津贴，按照国家有关规定享受基本养老保险待遇。基本养老保险待遇低于伤残津贴的，由工伤保险基金补足差额。 职工因工致残被鉴定为一级至四级伤残的，由用人单位和职工个人以伤残津贴为基数，缴纳基本医疗保险费。"}, {"law": "工伤保险条例_20101220.docx", "no": "第三十六条", "text": "职工因工致残被鉴定为五级、六级伤残的，享受以下待遇： (一)从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：五级伤残为18个月的本人工资，六级伤残为16个月的本人工资； (二)保留与用人单位的劳动关系，由用人单位安排适当工作。难以安排工作的，由用人单位按月发给伤残津贴，标准为：五级伤残为本人工资的70%，六级伤残为本人工资的60%，并由用人单位按照规定为其缴纳应缴纳的各项社会保险费。伤残津贴实际金额低于当地最低工资标准的，由用人单位补足差额。 经工伤职工本人提出，该职工可以与用人单位解除或者终止劳动关系，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。一次性工伤医疗补助金和一次性伤残就业补助金的具体标准由省、自治区、直辖市人民政府规定。"}, {"law": "工伤保险条例_20101220.docx", "no": "第三十七条", "text": "职工因工致残被鉴定为七级至十级伤残的，享受以下待遇： (一)从工伤保险基金按伤残等级支付一次性伤残补助金，标准为：七级伤残为13个月的本人工资，八级伤残为11个月的本人工资，九级伤残为9个月的本人工资，十级伤残为7个月的本人工资； (二)劳动、聘用合同期满终止，或者职工本人提出解除劳动、聘用合同的，由工伤保险基金支付一次性工伤医疗补助金，由用人单位支付一次性伤残就业补助金。一次性工伤医疗补助金和一次性伤残就业补助金的具体标准由省、自治区、直辖市人民政府规定。"}, {"law": "工伤保险条例_20101220.docx", "no": "第三十八条", "text": "工伤职工工伤复发，确认需要治疗的，享受本条例"}, {"law": "工伤保险条例_20101220.docx", "no": "第三十三条", "text": "规定的工伤待遇。"}, {"law": "工伤保险条例_20101220.docx", "no": "第三十九条", "text": "职工因工死亡，其近亲属按照下列规定从工伤保险基金领取丧葬补助金、供养亲属抚恤金和一次性工亡补助金： (一)丧葬补助金为6个月的统筹地区上年度职工月平均工资； (二)供养亲属抚恤金按照职工本人工资的一定比例发给由因工死亡职工生前提供主要生活来源、无劳动能力的亲属。标准为：配偶每月40%，其他亲属每人每月30%，孤寡老人或者孤儿每人每月在上述标准的基础上增加10%。核定的各供养亲属的抚恤金之和不应高于因工死亡职工生前的工资。供养亲属的具体范围由国务院社会保险行政部门规定； (三)一次性工亡补助金标准为上一年度全国城镇居民人均可支配收入的20倍。 伤残职工在停工留薪期内因工伤导致死亡的，其近亲属享受本条第一款规定的待遇。 一级至四级伤残职工在停工留薪期满后死亡的，其近亲属可以享受本条第一款第(一)项、第(二)项规定的待遇。"}, {"law": "工伤保险条例_20101220.docx", "no": "第四十条", "text": "伤残津贴、供养亲属抚恤金、生活护理费由统筹地区社会保险行政部门根据职工平均工资和生活费用变化等情况适时调整。调整办法由省、自治区、直辖市人民政府规定。"}, {"law": "工伤保险条例_20101220.docx", "no": "第四十一条", "text": "职工因工外出期间发生事故或者在抢险救灾中下落不明的，从事故发生当月起3个月内照发工资，从第4个月起停发工资，由工伤保险基金向其供养亲属按月支付供养亲属抚恤金。生活有困难的，可以预支一次性工亡补助金的50%。职工被人民法院宣告死亡的，按照本条例"}, {"law": "工伤保险条例_20101220.docx", "no": "第三十九条", "text": "职工因工死亡的规定处理。"}, {"law": "工伤保险条例_20101220.docx", "no": "第四十二条", "text": "工伤职工有下列情形之一的，停止享受工伤保险待遇： (一)丧失享受待遇条件的； (二)拒不接受劳动能力鉴定的； (三)拒绝治疗的。"}, {"law": "工伤保险条例_20101220.docx", "no": "第四十三条", "text": "用人单位分立、合并、转让的，承继单位应当承担原用人单位的工伤保险责任；原用人单位已经参加工伤保险的，承继单位应当到当地经办机构办理工伤保险变更登记。 用人单位实行承包经营的，工伤保险责任由职工劳动关系所在单位承担。 职工被借调期间受到工伤事故伤害的，由原用人单位承担工伤保险责任，但原用人单位与借调单位可以约定补偿办法。 企业破产的，在破产清算时依法拨付应当由单位支付的工伤保险待遇费用。"}, {"law": "工伤保险条例_20101220.docx", "no": "第四十四条", "text": "职工被派遣出境工作，依据前往国家或者地区的法律应当参加当地工伤保险的，参加当地工伤保险，其国内工伤保险关系中止；不能参加当地工伤保险的，其国内工伤保险关系不中止。"}, {"law": "工伤保险条例_20101220.docx", "no": "第四十五条", "text": "职工再次发生工伤，根据规定应当享受伤残津贴的，按照新认定的伤残等级享受伤残津贴待遇。 第六章 监督管理"}, {"law": "工伤保险条例_20101220.docx", "no": "第四十六条", "text": "经办机构具体承办工伤保险事务，履行下列职责： (一)根据省、自治区、直辖市人民政府规定，征收工伤保险费； (二)核查用人单位的工资总额和职工人数，办理工伤保险登记，并负责保存用人单位缴费和职工享受工伤保险待遇情况的记录； (三)进行工伤保险的调查、统计； (四)按照规定管理工伤保险基金的支出； (五)按照规定核定工伤保险待遇； (六)为工伤职工或者其近亲属免费提供咨询服务。"}, {"law": "工伤保险条例_20101220.docx", "no": "第四十七条", "text": "经办机构与医疗机构、辅助器具配置机构在平等协商的基础上签订服务协议，并公布签订服务协议的医疗机构、辅助器具配置机构的名单。具体办法由国务院社会保险行政部门分别会同国务院卫生行政部门、民政部门等部门制定。"}, {"law": "工伤保险条例_20101220.docx", "no": "第四十八条", "text": "经办机构按照协议和国家有关目录、标准对工伤职工医疗费用、康复费用、辅助器具费用的使用情况进行核查，并按时足额结算费用。"}, {"law": "工伤保险条例_20101220.docx", "no": "第四十九条", "text": "经办机构应当定期公布工伤保险基金的收支情况，及时向社会保险行政部门提出调整费率的建议。"}, {"law": "工伤保险条例_20101220.docx", "no": "第五十条", "text": "社会保险行政部门、经办机构应当定期听取工伤职工、医疗机构、辅助器具配置机构以及社会各界对改进工伤保险工作的意见。"}, {"law": "工伤保险条例_20101220.docx", "no": "第五十一条", "text": "社会保险行政部门依法对工伤保险费的征缴和工伤保险基金的支付情况进行监督检查。 财政部门和审计机关依法对工伤保险基金的收支、管理情况进行监督。"}, {"law": "工伤保险条例_20101220.docx", "no": "第五十二条", "text": "任何组织和个人对有关工伤保险的违法行为，有权举报。社会保险行政部门对举报应当及时调查，按照规定处理，并为举报人保密。"}, {"law": "工伤保险条例_20101220.docx", "no": "第五十三条", "text": "工会组织依法维护工伤职工的合法权益，对用人单位的工伤保险工作实行监督。"}, {"law": "工伤保险条例_20101220.docx", "no": "第五十四条", "text": "职工与用人单位发生工伤待遇方面的争议，按照处理劳动争议的有关规定处理。"}, {"law": "工伤保险条例_20101220.docx", "no": "第五十五条", "text": "有下列情形之一的，有关单位或者个人可以依法申请行政复议，也可以依法向人民法院提起行政诉讼： (一)申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定申请不予受理的决定不服的； (二)申请工伤认定的职工或者其近亲属、该职工所在单位对工伤认定结论不服的； (三)用人单位对经办机构确定的单位缴费费率不服的； (四)签订服务协议的医疗机构、辅助器具配置机构认为经办机构未履行有关协议或者规定的； (五)工伤职工或者其近亲属对经办机构核定的工伤保险待遇有异议的。 第七章 法律责任"}, {"law": "工伤保险条例_20101220.docx", "no": "第五十六条", "text": "单位或者个人违反本条例"}, {"law": "工伤保险条例_20101220.docx", "no": "第十二条", "text": "规定挪用工伤保险基金，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分或者纪律处分。被挪用的基金由社会保险行政部门追回，并入工伤保险基金；没收的违法所得依法上缴国库。"}, {"law": "工伤保险条例_20101220.docx", "no": "第五十七条", "text": "社会保险行政部门工作人员有下列情形之一的，依法给予处分；情节严重，构成犯罪的，依法追究刑事责任： (一)无正当理由不受理工伤认定申请，或者弄虚作假将不符合工伤条件的人员认定为工伤职工的； (二)未妥善保管申请工伤认定的证据材料，致使有关证据灭失的； (三)收受当事人财物的。"}, {"law": "工伤保险条例_20101220.docx", "no": "第五十八条", "text": "经办机构有下列行为之一的，由社会保险行政部门责令改正，对直接负责的主管人员和其他责任人员依法给予纪律处分；情节严重，构成犯罪的，依法追究刑事责任；造成当事人经济损失的，由经办机构依法承担赔偿责任： (一)未按规定保存用人单位缴费和职工享受工伤保险待遇情况记录的； (二)不按规定核定工伤保险待遇的； (三)收受当事人财物的。"}, {"law": "工伤保险条例_20101220.docx", "no": "第五十九条", "text": "医疗机构、辅助器具配置机构不按服务协议提供服务的，经办机构可以解除服务协议。 经办机构不按时足额结算费用的，由社会保险行政部门责令改正；医疗机构、辅助器具配置机构可以解除服务协议。"}, {"law": "工伤保险条例_20101220.docx", "no": "第六十条", "text": "用人单位、工伤职工或者其近亲属骗取工伤保险待遇，医疗机构、辅助器具配置机构骗取工伤保险基金支出的，由社会保险行政部门责令退还，处骗取金额2倍以上5倍以下的罚款；情节严重，构成犯罪的，依法追究刑事责任。"}, {"law": "工伤保险条例_20101220.docx", "no": "第六十一条", "text": "从事劳动能力鉴定的组织或者个人有下列情形之一的，由社会保险行政部门责令改正，处2000元以上1万元以下的罚款；情节严重，构成犯罪的，依法追究刑事责任： (一)提供虚假鉴定意见的； (二)提供虚假诊断证明的； (三)收受当事人财物的。"}, {"law": "工伤保险条例_20101220.docx", "no": "第六十二条", "text": "用人单位依照本条例规定应当参加工伤保险而未参加的，由社会保险行政部门责令限期参加，补缴应当缴纳的工伤保险费，并自欠缴之日起，按日加收万分之五的滞纳金；逾期仍不缴纳的，处欠缴数额1倍以上3倍以下的罚款。 依照本条例规定应当参加工伤保险而未参加工伤保险的用人单位职工发生工伤的，由该用人单位按照本条例规定的工伤保险待遇项目和标准支付费用。 用人单位参加工伤保险并补缴应当缴纳的工伤保险费、滞纳金后，由工伤保险基金和用人单位依照本条例的规定支付新发生的费用。"}, {"law": "工伤保险条例_20101220.docx", "no": "第六十三条", "text": "用人单位违反本条例"}, {"law": "工伤保险条例_20101220.docx", "no": "第十九条", "text": "的规定，拒不协助社会保险行政部门对事故进行调查核实的，由社会保险行政部门责令改正，处2000元以上2万元以下的罚款。 第八章 附则"}, {"law": "工伤保险条例_20101220.docx", "no": "第六十四条", "text": "本条例所称工资总额，是指用人单位直接支付给本单位全部职工的劳动报酬总额。 本条例所称本人工资，是指工伤职工因工作遭受事故伤害或者患职业病前12个月平均月缴费工资。本人工资高于统筹地区职工平均工资300%的，按照统筹地区职工平均工资的300%计算；本人工资低于统筹地区职工平均工资60%的，按照统筹地区职工平均工资的60%计算。"}, {"law": "工伤保险条例_20101220.docx", "no": "第六十五条", "text": "公务员和参照公务员法管理的事业单位、社会团体的工作人员因工作遭受事故伤害或者患职业病的，由所在单位支付费用。具体办法由国务院社会保险行政部门会同国务院财政部门规定。"}, {"law": "工伤保险条例_20101220.docx", "no": "第六十六条", "text": "无营业执照或者未经依法登记、备案的单位以及被依法吊销营业执照或者撤销登记、备案的单位的职工受到事故伤害或者患职业病的，由该单位向伤残职工或者死亡职工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇；用人单位不得使用童工，用人单位使用童工造成童工伤残、死亡的，由该单位向童工或者童工的近亲属给予一次性赔偿，赔偿标准不得低于本条例规定的工伤保险待遇。具体办法由国务院社会保险行政部门规定。 前款规定的伤残职工或者死亡职工的近亲属就赔偿数额与单位发生争议的，以及前款规定的童工或者童工的近亲属就赔偿数额与单位发生争议的，按照处理劳动争议的有关规定处理。"}, {"law": "工伤保险条例_20101220.docx", "no": "第六十七条", "text": "本条例自2004年1月1日起施行。本条例施行前已受到事故伤害或者患职业病的职工尚未完成工伤认定的，按照本条例的规定执行。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第一条", "text": "为了加强职业卫生管理工作，强化用人 单位职业病防治的主体责任，预防、控制职业病危害， 保障劳动者健康和相关权益，根据《中华人民共和国 职业病防治法》等法律、行政法规，制定本规定。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第二条", "text": "用人单位的职业病防治和卫生健康主 管部门对其实施监督管理，适用本规定。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第三条", "text": "用人单位应当加强职业病防治工作，为 劳动者提供符合法律、法规、规章、国家职业卫生标 国家卫生健康委员会规章 国家卫生健康委员会发布 - 2 - 准和卫生要求的工作环境和条件，并采取有效措施保 障劳动者的职业健康。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第四条", "text": "用人单位是职业病防治的责任主体，并 对本单位产生的职业病危害承担责任。 用人单位的主要负责人对本单位的职业病防治 工作全面负责。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第五条", "text": "国家卫生健康委依照《中华人民共和国 职业病防治法》和国务院规定的职责，负责全国用人 单位职业卫生的监督管理工作。 县级以上地方卫生健康主管部门依照《中华人民 共和国职业病防治法》和本级人民政府规定的职责， 负责本行政区域内用人单位职业卫生的监督管理工 作。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第六条", "text": "为职业病防治提供技术服务的职业卫 生技术服务机构，应当依照国家有关职业卫生技术服 务机构管理的相关法律法规及标准、规范的要求，为 用人单位提供技术服务。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 3 -"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第七条", "text": "任何单位和个人均有权向卫生健康主 管部门举报用人单位违反本规定的行为和职业病危 害事故。 第二章用人单位的职责"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第八条", "text": "职业病危害严重的用人单位，应当设置 或者指定职业卫生管理机构或者组织，配备专职职业 卫生管理人员。 其他存在职业病危害的用人单位，劳动者超过一 百人的，应当设置或者指定职业卫生管理机构或者组 织，配备专职职业卫生管理人员；劳动者在一百人以 下的，应当配备专职或者兼职的职业卫生管理人员， 负责本单位的职业病防治工作。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第九条", "text": "用人单位的主要负责人和职业卫生管 理人员应当具备与本单位所从事的生产经营活动相 国家卫生健康委员会规章 国家卫生健康委员会发布 - 4 - 适应的职业卫生知识和管理能力，并接受职业卫生培 训。 对用人单位主要负责人、职业卫生管理人员的职 业卫生培训，应当包括下列主要内容： （一）职业卫生相关法律、法规、规章和国家职 业卫生标准； （二）职业病危害预防和控制的基本知识； （三）职业卫生管理相关知识； （四）国家卫生健康委规定的其他内容。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第十条", "text": "用人单位应当对劳动者进行上岗前的 职业卫生培训和在岗期间的定期职业卫生培训，普及 职业卫生知识，督促劳动者遵守职业病防治的法律、 法规、规章、国家职业卫生标准和操作规程。 用人单位应当对职业病危害严重的岗位的劳动 者，进行专门的职业卫生培训，经培训合格后方可上 岗作业。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 5 - 因变更工艺、技术、设备、材料，或者岗位调整 导致劳动者接触的职业病危害因素发生变化的，用人 单位应当重新对劳动者进行上岗前的职业卫生培训。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第十一条", "text": "存在职业病危害的用人单位应当制 定职业病危害防治计划和实施方案，建立、健全下列 职业卫生管理制度和操作规程： （一）职业病危害防治责任制度； （二）职业病危害警示与告知制度； （三）职业病危害项目申报制度； （四）职业病防治宣传教育培训制度； （五）职业病防护设施维护检修制度； （六）职业病防护用品管理制度； （七）职业病危害监测及评价管理制度； （八）建设项目职业病防护设施“三同时”管理 制度； （九）劳动者职业健康监护及其档案管理制度； （十）职业病危害事故处置与报告制度； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 6 - （十一）职业病危害应急救援与管理制度； （十二）岗位职业卫生操作规程； （十三）法律、法规、规章规定的其他职业病防 治制度。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第十二条", "text": "产生职业病危害的用人单位的工作 场所应当符合下列基本要求： （一）生产布局合理，有害作业与无害作业分开； （二）工作场所与生活场所分开，工作场所不得 住人； （三）有与职业病防治工作相适应的有效防护设 施； （四）职业病危害因素的强度或者浓度符合国家 职业卫生标准； （五）有配套的更衣间、洗浴间、孕妇休息间等 卫生设施； （六）设备、工具、用具等设施符合保护劳动者 生理、心理健康的要求； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 7 - （七）法律、法规、规章和国家职业卫生标准的 其他规定。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第十三条", "text": "用人单位工作场所存在职业病目录 所列职业病的危害因素的，应当按照《职业病危害项 目申报办法》的规定，及时、如实向所在地卫生健康 主管部门申报职业病危害项目，并接受卫生健康主管 部门的监督检查。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第十四条", "text": "新建、改建、扩建的工程建设项目和 技术改造、技术引进项目（以下统称建设项目）可能 产生职业病危害的，建设单位应当按照国家有关建设 项目职业病防护设施“三同时”监督管理的规定，进 行职业病危害预评价、职业病防护设施设计、职业病 危害控制效果评价及相应的评审，组织职业病防护设 施验收。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第十五条", "text": "产生职业病危害的用人单位，应当在 醒目位置设置公告栏，公布有关职业病防治的规章制 国家卫生健康委员会规章 国家卫生健康委员会发布 - 8 - 度、操作规程、职业病危害事故应急救援措施和工作 场所职业病危害因素检测结果。 存在或者产生职业病危害的工作场所、作业岗 位、设备、设施，应当按照《工作场所职业病危害警 示标识》（GBZ158）的规定，在醒目位置设置图形、 警示线、警示语句等警示标识和中文警示说明。警示 说明应当载明产生职业病危害的种类、后果、预防和 应急处置措施等内容。 存在或者产生高毒物品的作业岗位，应当按照 《高毒物品作业岗位职业病危害告知规范》 （GBZ/T203）的规定，在醒目位置设置高毒物品告知 卡，告知卡应当载明高毒物品的名称、理化特性、健 康危害、防护措施及应急处理等告知内容与警示标 识。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第十六条", "text": "用人单位应当为劳动者提供符合国 家职业卫生标准的职业病防护用品，并督促、指导劳 国家卫生健康委员会规章 国家卫生健康委员会发布 - 9 - 动者按照使用规则正确佩戴、使用，不得发放钱物替 代发放职业病防护用品。 用人单位应当对职业病防护用品进行经常性的 维护、保养，确保防护用品有效，不得使用不符合国 家职业卫生标准或者已经失效的职业病防护用品。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第十七条", "text": "在可能发生急性职业损伤的有毒、有 害工作场所，用人单位应当设置报警装置，配置现场 急救用品、冲洗设备、应急撤离通道和必要的泄险区。 现场急救用品、冲洗设备等应当设在可能发生急 性职业损伤的工作场所或者临近地点，并在醒目位置 设置清晰的标识。 在可能突然泄漏或者逸出大量有害物质的密闭 或者半密闭工作场所，除遵守本条第一款、第二款规 定外，用人单位还应当安装事故通风装置以及与事故 排风系统相连锁的泄漏报警装置。 生产、销售、使用、贮存放射性同位素和射线装 置的场所，应当按照国家有关规定设置明显的放射性 国家卫生健康委员会规章 国家卫生健康委员会发布 - 10 - 标志，其入口处应当按照国家有关安全和防护标准的 要求，设置安全和防护设施以及必要的防护安全联 锁、报警装置或者工作信号。放射性装置的生产调试 和使用场所，应当具有防止误操作、防止工作人员受 到意外照射的安全措施。用人单位必须配备与辐射类 型和辐射水平相适应的防护用品和监测仪器，包括个 人剂量测量报警、固定式和便携式辐射监测、表面污 染监测、流出物监测等设备，并保证可能接触放射线 的工作人员佩戴个人剂量计。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第十八条", "text": "用人单位应当对职业病防护设备、应 急救援设施进行经常性的维护、检修和保养，定期检 测其性能和效果，确保其处于正常状态，不得擅自拆 除或者停止使用。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第十九条", "text": "存在职业病危害的用人单位，应当实 施由专人负责的工作场所职业病危害因素日常监测， 确保监测系统处于正常工作状态。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 11 -"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第二十条", "text": "职业病危害严重的用人单位，应当委 托具有相应资质的职业卫生技术服务机构，每年至少 进行一次职业病危害因素检测，每三年至少进行一次 职业病危害现状评价。 职业病危害一般的用人单位，应当委托具有相应 资质的职业卫生技术服务机构，每三年至少进行一次 职业病危害因素检测。 检测、评价结果应当存入本单位职业卫生档案， 并向卫生健康主管部门报告和劳动者公布。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第二十一条", "text": "存在职业病危害的用人单位发生 职业病危害事故或者国家卫生健康委规定的其他情 形的，应当及时委托具有相应资质的职业卫生技术服 务机构进行职业病危害现状评价。 用人单位应当落实职业病危害现状评价报告中 提出的建议和措施，并将职业病危害现状评价结果及 整改情况存入本单位职业卫生档案。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 12 -"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第二十二条", "text": "用人单位在日常的职业病危害监 测或者定期检测、现状评价过程中，发现工作场所职 业病危害因素不符合国家职业卫生标准和卫生要求 时，应当立即采取相应治理措施，确保其符合职业卫 生环境和条件的要求；仍然达不到国家职业卫生标准 和卫生要求的，必须停止存在职业病危害因素的作 业；职业病危害因素经治理后，符合国家职业卫生标 准和卫生要求的，方可重新作业。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第二十三条", "text": "向用人单位提供可能产生职业病 危害的设备的，应当提供中文说明书，并在设备的醒 目位置设置警示标识和中文警示说明。警示说明应当 载明设备性能、可能产生的职业病危害、安全操作和 维护注意事项、职业病防护措施等内容。 用人单位应当检查前款规定的事项，不得使用不 符合要求的设备。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第二十四条", "text": "向用人单位提供可能产生职业病 危害的化学品、放射性同位素和含有放射性物质的材 国家卫生健康委员会规章 国家卫生健康委员会发布 - 13 - 料的，应当提供中文说明书。说明书应当载明产品特 性、主要成份、存在的有害因素、可能产生的危害后 果、安全使用注意事项、职业病防护和应急救治措施 等内容。产品包装应当有醒目的警示标识和中文警示 说明。贮存上述材料的场所应当在规定的部位设置危 险物品标识或者放射性警示标识。 用人单位应当检查前款规定的事项，不得使用不 符合要求的材料。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第二十五条", "text": "任何用人单位不得使用国家明令 禁止使用的可能产生职业病危害的设备或者材料。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第二十六条", "text": "任何单位和个人不得将产生职业 病危害的作业转移给不具备职业病防护条件的单位 和个人。不具备职业病防护条件的单位和个人不得接 受产生职业病危害的作业。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第二十七条", "text": "用人单位应当优先采用有利于防 治职业病危害和保护劳动者健康的新技术、新工艺、 国家卫生健康委员会规章 国家卫生健康委员会发布 - 14 - 新材料、新设备，逐步替代产生职业病危害的技术、 工艺、材料、设备。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第二十八条", "text": "用人单位对采用的技术、工艺、材 料、设备，应当知悉其可能产生的职业病危害，并采 取相应的防护措施。对有职业病危害的技术、工艺、 设备、材料，故意隐瞒其危害而采用的，用人单位对 其所造成的职业病危害后果承担责任。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第二十九条", "text": "用人单位与劳动者订立劳动合同 时，应当将工作过程中可能产生的职业病危害及其后 果、职业病防护措施和待遇等如实告知劳动者，并在 劳动合同中写明，不得隐瞒或者欺骗。 劳动者在履行劳动合同期间因工作岗位或者工 作内容变更，从事与所订立劳动合同中未告知的存在 职业病危害的作业时，用人单位应当依照前款规定， 向劳动者履行如实告知的义务，并协商变更原劳动合 同相关条款。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 15 - 用人单位违反本条规定的，劳动者有权拒绝从事 存在职业病危害的作业，用人单位不得因此解除与劳 动者所订立的劳动合同。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第三十条", "text": "对从事接触职业病危害因素作业的 劳动者，用人单位应当按照《用人单位职业健康监护 监督管理办法》、《放射工作人员职业健康管理办法》、 《职业健康监护技术规范》（GBZ188）、《放射工作人 员职业健康监护技术规范》（GBZ235）等有关规定组 织上岗前、在岗期间、离岗时的职业健康检查，并将 检查结果书面如实告知劳动者。 职业健康检查费用由用人单位承担。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第三十一条", "text": "用人单位应当按照《用人单位职业 健康监护监督管理办法》的规定，为劳动者建立职业 健康监护档案，并按照规定的期限妥善保存。 职业健康监护档案应当包括劳动者的职业史、职 业病危害接触史、职业健康检查结果、处理结果和职 业病诊疗等有关个人健康资料。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 16 - 劳动者离开用人单位时，有权索取本人职业健康 监护档案复印件，用人单位应当如实、无偿提供，并 在所提供的复印件上签章。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第三十二条", "text": "劳动者健康出现损害需要进行职 业病诊断、鉴定的，用人单位应当如实提供职业病诊 断、鉴定所需的劳动者职业史和职业病危害接触史、 工作场所职业病危害因素检测结果和放射工作人员 个人剂量监测结果等资料。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第三十三条", "text": "用人单位不得安排未成年工从事 接触职业病危害的作业，不得安排有职业禁忌的劳动 者从事其所禁忌的作业，不得安排孕期、哺乳期女职 工从事对本人和胎儿、婴儿有危害的作业。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第三十四条", "text": "用人单位应当建立健全下列职业 卫生档案资料： （一）职业病防治责任制文件； （二）职业卫生管理规章制度、操作规程； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 17 - （三）工作场所职业病危害因素种类清单、岗位 分布以及作业人员接触情况等资料； （四）职业病防护设施、应急救援设施基本信息， 以及其配置、使用、维护、检修与更换等记录； （五）工作场所职业病危害因素检测、评价报告 与记录； （六）职业病防护用品配备、发放、维护与更换 等记录； （七）主要负责人、职业卫生管理人员和职业病 危害严重工作岗位的劳动者等相关人员职业卫生培 训资料； （八）职业病危害事故报告与应急处置记录； （九）劳动者职业健康检查结果汇总资料，存在 职业禁忌证、职业健康损害或者职业病的劳动者处理 和安置情况记录； （十）建设项目职业病防护设施“三同时”有关 资料； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 18 - （十一）职业病危害项目申报等有关回执或者批 复文件； （十二）其他有关职业卫生管理的资料或者文 件。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第三十五条", "text": "用人单位发生职业病危害事故，应 当及时向所在地卫生健康主管部门和有关部门报告， 并采取有效措施，减少或者消除职业病危害因素，防 止事故扩大。对遭受或者可能遭受急性职业病危害的 劳动者，用人单位应当及时组织救治、进行健康检查 和医学观察，并承担所需费用。 用人单位不得故意破坏事故现场、毁灭有关证 据，不得迟报、漏报、谎报或者瞒报职业病危害事故。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第三十六条", "text": "用人单位发现职业病病人或者疑 似职业病病人时，应当按照国家规定及时向所在地卫 生健康主管部门和有关部门报告。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 19 -"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第三十七条", "text": "用人单位在卫生健康主管部门行 政执法人员依法履行监督检查职责时，应当予以配 合，不得拒绝、阻挠。 第三章监督管理"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第三十八条", "text": "卫生健康主管部门应当依法对用 人单位执行有关职业病防治的法律、法规、规章和国 家职业卫生标准的情况进行监督检查，重点监督检查 下列内容： （一）设置或者指定职业卫生管理机构或者组 织，配备专职或者兼职的职业卫生管理人员情况； （二）职业卫生管理制度和操作规程的建立、落 实及公布情况； （三）主要负责人、职业卫生管理人员和职业病 危害严重的工作岗位的劳动者职业卫生培训情况； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 20 - （四）建设项目职业病防护设施“三同时”制度 落实情况； （五）工作场所职业病危害项目申报情况； （六）工作场所职业病危害因素监测、检测、评 价及结果报告和公布情况； （七）职业病防护设施、应急救援设施的配置、 维护、保养情况，以及职业病防护用品的发放、管理 及劳动者佩戴使用情况； （八）职业病危害因素及危害后果警示、告知情 况； （九）劳动者职业健康监护、放射工作人员个人 剂量监测情况； （十）职业病危害事故报告情况； （十一）提供劳动者健康损害与职业史、职业病 危害接触关系等相关资料的情况； （十二）依法应当监督检查的其他情况。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 21 -"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第三十九条", "text": "卫生健康主管部门应当建立健全 职业卫生监督检查制度，加强行政执法人员职业卫生 知识的培训，提高行政执法人员的业务素质。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第四十条", "text": "卫生健康主管部门应当加强建设项 目职业病防护设施“三同时”的监督管理，建立健全 相关资料的档案管理制度。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第四十一条", "text": "卫生健康主管部门应当加强职业 卫生技术服务机构的资质认可管理和技术服务工作 的监督检查，督促职业卫生技术服务机构公平、公正、 客观、科学地开展职业卫生技术服务。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第四十二条", "text": "卫生健康主管部门应当建立健全 职业病危害防治信息统计分析制度，加强对用人单位 职业病危害因素检测、评价结果、劳动者职业健康监 护信息以及职业卫生监督检查信息等资料的统计、汇 总和分析。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 22 -"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第四十三条", "text": "卫生健康主管部门应当按照有关 规定，支持、配合有关部门和机构开展职业病的诊断、 鉴定工作。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第四十四条", "text": "卫生健康主管部门行政执法人员 依法履行监督检查职责时，应当出示有效的执法证 件。 行政执法人员应当忠于职守，秉公执法，严格遵 守执法规范；涉及被检查单位的技术秘密、业务秘密 以及个人隐私的，应当为其保密。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第四十五条", "text": "卫生健康主管部门履行监督检查 职责时，有权采取下列措施： （一）进入被检查单位及工作场所，进行职业病 危害检测，了解情况，调查取证； （二）查阅、复制被检查单位有关职业病危害防 治的文件、资料，采集有关样品； （三）责令违反职业病防治法律、法规的单位和 个人停止违法行为； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 23 - （四）责令暂停导致职业病危害事故的作业，封 存造成职业病危害事故或者可能导致职业病危害事 故发生的材料和设备； （五）组织控制职业病危害事故现场。 在职业病危害事故或者危害状态得到有效控制 后，卫生健康主管部门应当及时解除前款第四项、第 五项规定的控制措施。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第四十六条", "text": "发生职业病危害事故，卫生健康主 管部门应当依照国家有关规定报告事故和组织事故 的调查处理。 第四章法律责任"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第四十七条", "text": "用人单位有下列情形之一的，责令 限期改正，给予警告，可以并处五千元以上二万元以 下的罚款： 国家卫生健康委员会规章 国家卫生健康委员会发布 - 24 - （一）未按照规定实行有害作业与无害作业分 开、工作场所与生活场所分开的； （二）用人单位的主要负责人、职业卫生管理人 员未接受职业卫生培训的； （三）其他违反本规定的行为。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第四十八条", "text": "用人单位有下列情形之一的，责令 限期改正，给予警告；逾期未改正的，处十万元以下 的罚款： （一）未按照规定制定职业病防治计划和实施方 案的； （二）未按照规定设置或者指定职业卫生管理机 构或者组织，或者未配备专职或者兼职的职业卫生管 理人员的； （三）未按照规定建立、健全职业卫生管理制度 和操作规程的； （四）未按照规定建立、健全职业卫生档案和劳 动者健康监护档案的； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 25 - （五）未建立、健全工作场所职业病危害因素监 测及评价制度的； （六）未按照规定公布有关职业病防治的规章制 度、操作规程、职业病危害事故应急救援措施的； （七）未按照规定组织劳动者进行职业卫生培 训，或者未对劳动者个体防护采取有效的指导、督促 措施的； （八）工作场所职业病危害因素检测、评价结果 未按照规定存档、上报和公布的。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第四十九条", "text": "用人单位有下列情形之一的，责令 限期改正，给予警告，可以并处五万元以上十万元以 下的罚款： （一）未按照规定及时、如实申报产生职业病危 害的项目的； （二）未实施由专人负责职业病危害因素日常监 测，或者监测系统不能正常监测的； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 26 - （三）订立或者变更劳动合同时，未告知劳动者 职业病危害真实情况的； （四）未按照规定组织劳动者进行职业健康检 查、建立职业健康监护档案或者未将检查结果书面告 知劳动者的； （五）未按照规定在劳动者离开用人单位时提供 职业健康监护档案复印件的。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第五十条", "text": "用人单位有下列情形之一的，责令限 期改正，给予警告；逾期未改正的，处五万元以上二 十万元以下的罚款；情节严重的，责令停止产生职业 病危害的作业，或者提请有关人民政府按照国务院规 定的权限责令关闭： （一）工作场所职业病危害因素的强度或者浓度 超过国家职业卫生标准的； （二）未提供职业病防护设施和劳动者使用的职 业病防护用品，或者提供的职业病防护设施和劳动者 国家卫生健康委员会规章 国家卫生健康委员会发布 - 27 - 使用的职业病防护用品不符合国家职业卫生标准和 卫生要求的； （三）未按照规定对职业病防护设备、应急救援 设施和劳动者职业病防护用品进行维护、检修、检测， 或者不能保持正常运行、使用状态的； （四）未按照规定对工作场所职业病危害因素进 行检测、现状评价的； （五）工作场所职业病危害因素经治理仍然达不 到国家职业卫生标准和卫生要求时，未停止存在职业 病危害因素的作业的； （六）发生或者可能发生急性职业病危害事故， 未立即采取应急救援和控制措施或者未按照规定及 时报告的； （七）未按照规定在产生严重职业病危害的作业 岗位醒目位置设置警示标识和中文警示说明的； （八）拒绝卫生健康主管部门监督检查的； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 28 - （九）隐瞒、伪造、篡改、毁损职业健康监护档 案、工作场所职业病危害因素检测评价结果等相关资 料，或者不提供职业病诊断、鉴定所需要资料的； （十）未按照规定承担职业病诊断、鉴定费用和 职业病病人的医疗、生活保障费用的。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第五十一条", "text": "用人单位有下列情形之一的，依法 责令限期改正，并处五万元以上三十万元以下的罚 款；情节严重的，责令停止产生职业病危害的作业， 或者提请有关人民政府按照国务院规定的权限责令 关闭： （一）隐瞒技术、工艺、设备、材料所产生的职 业病危害而采用的； （二）隐瞒本单位职业卫生真实情况的； （三）可能发生急性职业损伤的有毒、有害工作 场所或者放射工作场所不符合法律有关规定的； （四）使用国家明令禁止使用的可能产生职业病 危害的设备或者材料的； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 29 - （五）将产生职业病危害的作业转移给没有职业 病防护条件的单位和个人，或者没有职业病防护条件 的单位和个人接受产生职业病危害的作业的； （六）擅自拆除、停止使用职业病防护设备或者 应急救援设施的； （七）安排未经职业健康检查的劳动者、有职业 禁忌的劳动者、未成年工或者孕期、哺乳期女职工从 事接触产生职业病危害的作业或者禁忌作业的； （八）违章指挥和强令劳动者进行没有职业病防 护措施的作业的。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第五十二条", "text": "用人单位违反《中华人民共和国职 业病防治法》的规定，已经对劳动者生命健康造成严 重损害的，责令停止产生职业病危害的作业，或者提 请有关人民政府按照国务院规定的权限责令关闭，并 处十万元以上五十万元以下的罚款。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 30 - 造成重大职业病危害事故或者其他严重后果，构 成犯罪的，对直接负责的主管人员和其他直接责任人 员，依法追究刑事责任。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第五十三条", "text": "向用人单位提供可能产生职业病 危害的设备或者材料，未按照规定提供中文说明书或 者设置警示标识和中文警示说明的，责令限期改正， 给予警告，并处五万元以上二十万元以下的罚款。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第五十四条", "text": "用人单位未按照规定报告职业病、 疑似职业病的，责令限期改正，给予警告，可以并处 一万元以下的罚款；弄虚作假的，并处二万元以上五 万元以下的罚款。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第五十五条", "text": "卫生健康主管部门及其行政执法 人员未按照规定报告职业病危害事故的，依照有关规 定给予处理；构成犯罪的，依法追究刑事责任。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第五十六条", "text": "本规定所规定的行政处罚，由县级 以上地方卫生健康主管部门决定。法律、行政法规和 国家卫生健康委员会规章 国家卫生健康委员会发布 - 31 - 国务院有关规定对行政处罚决定机关另有规定的，依 照其规定。 第五章附则"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第五十七条", "text": "本规定下列用语的含义： 工作场所，是指劳动者进行职业活动的所有地 点，包括建设单位施工场所。 职业病危害严重的用人单位，是指建设项目职业 病危害风险分类管理目录中所列职业病危害严重行 业的用人单位。建设项目职业病危害风险分类管理目 录由国家卫生健康委公布。各省级卫生健康主管部门 可以根据本地区实际情况，对分类管理目录作出补充 规定。 建设项目职业病防护设施“三同时”，是指建设 项目的职业病防护设施与主体工程同时设计、同时施 工、同时投入生产和使用。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 32 -"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第五十八条", "text": "本规定未规定的其他有关职业病 防治事项，依照《中华人民共和国职业病防治法》和 其他有关法律、法规、规章的规定执行。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第五十九条", "text": "医疗机构放射卫生管理按照放射 诊疗管理相关规定执行。"}, {"law": "工作场所职业卫生管理规定_20210201.pdf", "no": "第六十条", "text": "本规定自2021 年2 月1 日起施行。 原国家安全生产监督管理总局2012 年4 月27 日公布 的《工作场所职业卫生监督管理规定》同时废止。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第一条", "text": "为了保障有限空间作业安全，预防和减少生产安全事故，根据《中华人民共和国安全生产法》等法律法规，制定本规定。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第二条", "text": "冶金、有色、建材、机械、轻工、纺织、烟草、商贸等行业的生产经营单位（以下统称工贸企业）有限空间作业的安全管理与监督，适用本规定。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第三条", "text": "本规定所称有限空间，是指封闭或者部分封闭，未被设计为固定工作场所，人员可以进入作业，易造成有毒有害、易燃易爆物质积聚或者氧含量不足的空间。 本规定所称有限空间作业，是指人员进入有限空间实施的作业。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第四条", "text": "工贸企业主要负责人是有限空间作业安全第一责任人，应当组织制定有限空间作业安全管理制度，明确有限空间作业审批人、监护人员、作业人员的职责，以及安全培训、作业审批、防护用品、应急救援装备、操作规程和应急处置等方面的要求。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第五条", "text": "工贸企业应当实行有限空间作业监护制，明确专职或者兼职的监护人员，负责监督有限空间作业安全措施的落实。 监护人员应当具备与监督有限空间作业相适应的安全知识和应急处置能力，能够正确使用气体检测、机械通风、呼吸防护、应急救援等用品、装备。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第六条", "text": "工贸企业应当对有限空间进行辨识，建立有限空间管理台账，明确有限空间数量、位置以及危险因素等信息，并及时更新。 鼓励工贸企业采用信息化、数字化和智能化技术，提升有限空间作业安全风险管控水平。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第七条", "text": "工贸企业应当根据有限空间作业安全风险大小，明确审批要求。 对于存在硫化氢、一氧化碳、二氧化碳等中毒和窒息等风险的有限空间作业，应当由工贸企业主要负责人或者其书面委托的人员进行审批，委托进行审批的，相关责任仍由工贸企业主要负责人承担。 未经工贸企业确定的作业审批人批准，不得实施有限空间作业。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第八条", "text": "工贸企业将有限空间作业依法发包给其他单位实施的，应当与承包单位在合同或者协议中约定各自的安全生产管理职责。工贸企业对其发包的有限空间作业统一协调、管理，并对现场作业进行安全检查，督促承包单位有效落实各项安全措施。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第九条", "text": "工贸企业应当每年至少组织一次有限空间作业专题安全培训，对作业审批人、监护人员、作业人员和应急救援人员培训有限空间作业安全知识和技能，并如实记录。 未经培训合格不得参与有限空间作业。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第十条", "text": "工贸企业应当制定有限空间作业现场处置方案，按规定组织演练，并进行演练效果评估。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第十一条", "text": "工贸企业应当在有限空间出入口等醒目位置设置明显的安全警示标志，并在具备条件的场所设置安全风险告知牌。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第十二条", "text": "工贸企业应当对可能产生有毒物质的有限空间采取上锁、隔离栏、防护网或者其他物理隔离措施，防止人员未经审批进入。监护人员负责在作业前解除物理隔离措施。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第十三条", "text": "工贸企业应当根据有限空间危险因素的特点，配备符合国家标准或者行业标准的气体检测报警仪器、机械通风设备、呼吸防护用品、全身式安全带等防护用品和应急救援装备，并对相关用品、装备进行经常性维护、保养和定期检测，确保能够正常使用。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第十四条", "text": "有限空间作业应当严格遵守 要求。存在爆炸风险的，应当采取消除或者控制措施，相关电气设施设备、照明灯具、应急救援装备等应当符合防爆安全要求。 作业前，应当组织对作业人员进行安全交底，监护人员应当对通风、检测和必要的隔断、清除、置换等风险管控措施逐项进行检查，确认防护用品能够正常使用且作业现场配备必要的应急救援装备，确保各项作业条件符合安全要求。有专业救援队伍的工贸企业，应急救援人员应当做好应急救援准备，确保及时有效处置突发情况。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第十五条", "text": "监护人员应当全程进行监护，与作业人员保持实时联络，不得离开作业现场或者进入有限空间参与作业。 发现异常情况时 监护人员应当立即组织作业人员撤离现场。发生有限空间作业事故后，应当立即按照现场处置方案进行应急处置，组织科学施救。未做好安全措施盲目施救的，监护人员应当予以制止。 作业过程中，工贸企业应当安排专人对作业区域持续进行通风和气体浓度检测。作业中断的，作业人员再次进入有限空间作业前，应当重新通风、气体检测合格后方可进入。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第十六条", "text": "存在硫化氢、一氧化碳、二氧化碳等中毒和窒息风险、需要重点监督管理的有限空间，实行目录管理。 监管目录由应急管理部确定、调整并公布。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第十七条", "text": "负责工贸企业安全生产监督管理的部门应当加强对工贸企业有限空间作业的监督检查，将检查纳入年度监督检查计划。对发现的事故隐患和违法行为，依法作出处理。 负责工贸企业安全生产监督管理的部门应当将存在硫化氢、一氧化碳、二氧化碳等中毒和窒息风险的有限空间作业工贸企业纳入重点检查范围，突出对监护人员配备和履职情况、作业审批、防护用品和应急救援装备配备等事项的检查。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第十八条", "text": "负责工贸企业安全生产监督管理的部门及其行政执法人员发现有限空间作业存在重大事故隐患的，应当责令立即或者限期整改；重大事故隐患排除前或者排除过程中无法保证安全的，应当责令暂时停止作业，撤出作业人员；重大事故隐患排除后，经审查同意，方可恢复作业。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第十九条", "text": "工贸企业有下列行为之一的，责令限期改正，处5万元以下的罚款；逾期未改正的，处5万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款；情节严重的，责令停产停业整顿；构成犯罪的，依照刑法有关规定追究刑事责任 一）未按照规定设置明显的有限空间安全警示标志的； （二）未按照规定配备、使用符合国家标准或者行业标准的有限空间作业安全仪器、设备、装备和器材的，或者未对其进行经常性维护、保养和定期检测的。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第二十条", "text": "工贸企业有下列行为之一的，责令限期改正，处10万元以下的罚款；逾期未改正的，责令停产停业整顿，并处10万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款： （一）未按照规定开展有限空间作业专题安全培训或者未如实记录安全培训情况的； （二）未按照规定制定有限空间作业现场处置方案或者未按照规定组织演练的。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第二十一条", "text": "违反本规定，有下列情形之一的，责令限期改正，对工贸企业处5万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以下的罚款： （一）未配备监护人员，或者监护人员未按规定履行岗位职责的； （二）未对有限空间进行辨识，或者未建立有限空间管理台账的； （三）未落实有限空间作业审批，或者作业未执行 要求的； （四）未按要求进行通风和气体检测的。"}, {"law": "工贸企业有限空间作业安全规定_20240101.doc", "no": "第二十二条", "text": "本规定自2024年1月1日起施行。原国家安全生产监督管理总局2013年5月20日公布的《工贸企业有限空间作业安全管理与监督暂行规定》（国家安全生产监督管理总局令第59号）同时废止。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第一条", "text": "为了加强工贸企业粉尘防爆安全工作，预防和减少粉尘爆炸事故，保障从业人员生命安全，根据《中华人民共和国安全生产法》等法律法规，制定本规定。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第二条", "text": "存在可燃性粉尘爆炸危险的冶金、有色、建材、机械、轻工、纺织、烟草、商贸等工贸企业（以下简称粉尘涉爆企业）的粉尘防爆安全工作及其监督管理，适用本规定。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第三条", "text": "本规定所称可燃性粉尘，是指在大气条件下，能与气态氧化剂（主要是空气）发生剧烈氧化反应的粉尘、纤维或者飞絮。 本规定所称粉尘爆炸危险场所，是指存在可燃性粉尘和气态氧化剂（主要是空气）的场所，根据爆炸性环境出现的频率或者持续的时间，可划分为不同危险区域。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第四条", "text": "粉尘涉爆企业对粉尘防爆安全工作负主体责任，应当具备有关法律法规、规章、国家标准或者行业标准规定的粉尘防爆安全生产条件，建立健全全员安全生产责任制和相关规章制度，加强安全生产标准化、信息化建设，构建安全风险分级管控和隐患排查治理双重预防机制，健全风险防范化解机制，确保安全生产。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第五条", "text": "县级以上地方人民政府负责粉尘涉爆企业安全生产监督管理的部门（以下统称负责粉尘涉爆企业安全监管的部门），根据本级人民政府规定的职责，按照分级属地的原则，对本行政区域内粉尘涉爆企业的粉尘防爆安全工作实施监督管理。 国务院应急管理部门应当加强指导监督。 第二章 安全生产保障"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第六条", "text": "粉尘涉爆企业主要负责人是粉尘防爆安全工作的第一责任人，其他负责人在各自职责范围内对粉尘防爆安全工作负责。 粉尘涉爆企业应当在本单位安全生产责任制中明确主要负责人、相关部门负责人、生产车间负责人及粉尘作业岗位人员粉尘防爆安全职责。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第七条", "text": "粉尘涉爆企业应当结合企业实际情况建立和落实粉尘防爆安全管理制度。粉尘防爆安全管理制度应当包括下列内容： （一）粉尘爆炸风险辨识评估和管控； （二）粉尘爆炸事故隐患排查治理； （三）粉尘作业岗位安全操作规程； （四）粉尘防爆专项安全生产教育和培训； （五）粉尘清理和处置； （六）除尘系统和相关安全设施设备运行、维护及检修、维修管理； （七）粉尘爆炸事故应急处置和救援。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第八条", "text": "粉尘涉爆企业应当组织对涉及粉尘防爆的生产、设备、安全管理等有关负责人和粉尘作业岗位等相关从业人员进行粉尘防爆专项安全生产教育和培训，使其了解作业场所和工作岗位存在的爆炸风险，掌握粉尘爆炸事故防范和应急措施；未经教育培训合格的，不得上岗作业。 粉尘涉爆企业应当如实记录粉尘防爆专项安全生产教育和培训的时间、内容及考核等情况，纳入员工教育和培训档案。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第九条", "text": "粉尘涉爆企业应当为粉尘作业岗位从业人员提供符合国家标准或者行业标准的劳动防护用品，并监督、教育从业人员按照使用规则佩戴、使用。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第十条", "text": "粉尘涉爆企业应当制定有关粉尘爆炸事故应急救援预案，并依法定期组织演练。发生火灾或者粉尘爆炸事故后，粉尘涉爆企业应当立即启动应急响应并撤离疏散全部作业人员至安全场所，不得采用可能引起扬尘的应急处置措施。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第十一条", "text": "粉尘涉爆企业应当定期辨识粉尘云、点燃源等粉尘爆炸危险因素，确定粉尘爆炸危险场所的位置、范围，并根据粉尘爆炸特性和涉粉作业人数等关键要素，评估确定有关危险场所安全风险等级，制定并落实管控措施，明确责任部门和责任人员，建立安全风险清单，及时维护安全风险辨识、评估、管控过程的信息档案。 粉尘涉爆企业应当在粉尘爆炸较大危险因素的工艺、场所、设施设备和岗位，设置安全警示标志。 涉及粉尘爆炸危险的工艺、场所、设施设备等发生变更的，粉尘涉爆企业应当重新进行安全风险辨识评估。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第十二条", "text": "粉尘涉爆企业应当根据《粉尘防爆安全规程》等有关国家标准或者行业标准，结合粉尘爆炸风险管控措施，建立事故隐患排查清单，明确和细化排查事项、具体内容、排查周期及责任人员，及时组织开展事故隐患排查治理，如实记录隐患排查治理情况，并向从业人员通报。 构成工贸行业重大事故隐患判定标准规定的重大事故隐患的，应当按照有关规定制定治理方案，落实措施、责任、资金、时限和应急预案，及时消除事故隐患。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第十三条", "text": "粉尘涉爆企业新建、改建、扩建涉及粉尘爆炸危险的工程项目安全设施的设计、施工应当按照《粉尘防爆安全规程》等有关国家标准或者行业标准，在安全设施设计文件、施工方案中明确粉尘防爆的相关内容。 设计单位应当对安全设施粉尘防爆相关的设计负责，施工单位应当按照设计进行施工，并对施工质量负责。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第十四条", "text": "粉尘涉爆企业存在粉尘爆炸危险场所的建（构）筑物的结构和布局应当符合《粉尘防爆安全规程》等有关国家标准或者行业标准要求，采取防火防爆、防雷等措施，单层厂房屋顶一般应当采用轻型结构，多层厂房应当为框架结构，并设置符合有关标准要求的泄压面积。 粉尘涉爆企业应当严格控制粉尘爆炸危险场所内作业人员数量，在粉尘爆炸危险场所内不得设置员工宿舍、休息室、办公室、会议室等，粉尘爆炸危险场所与其他厂房、仓库、民用建筑的防火间距应当符合《建筑设计防火规范》的规定。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第十五条", "text": "粉尘涉爆企业应当按照《粉尘防爆安全规程》等有关国家标准或者行业标准规定，将粉尘爆炸危险场所除尘系统按照不同工艺分区域相对独立设置，可燃性粉尘不得与可燃气体等易加剧爆炸危险的介质共用一套除尘系统，不同防火分区的除尘系统禁止互联互通。存在粉尘爆炸危险的工艺设备应当采用泄爆、隔爆、惰化、抑爆、抗爆等一种或者多种控爆措施，但不得单独采取隔爆措施。禁止采用粉尘沉降室除尘或者采用巷道式构筑物作为除尘风道。铝镁等金属粉尘应当采用负压方式除尘，其他粉尘受工艺条件限制，采用正压方式吹送时，应当采取可靠的防范点燃源的措施。 采用干式除尘系统的粉尘涉爆企业应当按照《粉尘防爆安全规程》等有关国家标准或者行业标准规定，结合工艺实际情况，安装使用锁气卸灰、火花探测熄灭、风压差监测等装置，以及相关安全设备的监测预警信息系统，加强对可能存在点燃源和粉尘云的粉尘爆炸危险场所的实时监控。铝镁等金属粉尘湿式除尘系统应当安装与打磨抛光设备联锁的液位、流速监测报警装置，并保持作业场所和除尘器本体良好通风，防止氢气积聚，及时规范清理沉淀的粉尘泥浆。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第十六条", "text": "针对粉碎、研磨、造粒、砂光等易产生机械点燃源的工艺，粉尘涉爆企业应当规范采取杂物去除或者火花探测消除等防范点燃源措施，并定期清理维护，做好相关记录。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第十七条", "text": "粉尘防爆相关的泄爆、隔爆、抑爆、惰化、锁气卸灰、除杂、监测、报警、火花探测消除等安全设备的设计、制造、安装、使用、检测、维修、改造和报废，应当符合《粉尘防爆安全规程》等有关国家标准或者行业标准，相关设计、制造、安装单位应当提供相关设备安全性能和使用说明等资料，对安全设备的安全性能负责。 粉尘涉爆企业应当对粉尘防爆安全设备进行经常性维护、保养，并按照《粉尘防爆安全规程》等有关国家标准或者行业标准定期检测或者检查，保证正常运行，做好相关记录，不得关闭、破坏直接关系粉尘防爆安全的监控、报警、防控等设备、设施，或者篡改、隐瞒、销毁其相关数据、信息。粉尘涉爆企业应当规范选用与爆炸危险区域相适应的防爆型电气设备。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第十八条", "text": "粉尘涉爆企业应当按照《粉尘防爆安全规程》等有关国家标准或者行业标准，制定并严格落实粉尘爆炸危险场所的粉尘清理制度，明确清理范围、清理周期、清理方式和责任人员，并在相关粉尘爆炸危险场所醒目位置张贴。相关责任人员应当定期清理粉尘并如实记录，确保可能积尘的粉尘作业区域和设备设施全面及时规范清理。粉尘作业区域应当保证每班清理。 铝镁等金属粉尘和镁合金废屑的收集、贮存等处置环节，应当避免粉尘废屑大量堆积或者装袋后多层堆垛码放；需要临时存放的，应当设置相对独立的暂存场所，远离作业现场等人员密集场所，并采取防水防潮、通风、氢气监测等必要的防火防爆措施。含水镁合金废屑应当优先采用机械压块处理方式，镁合金粉尘应当优先采用大量水浸泡方式暂存。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第十九条", "text": "粉尘涉爆企业对粉尘爆炸危险场所设备设施或者除尘系统的检修维修作业，应当实行专项作业审批。作业前，应当制定专项方案；对存在粉尘沉积的除尘器、管道等设施设备进行动火作业前，应当清理干净内部积尘和作业区域的可燃性粉尘。作业时，生产设备应当处于停止运行状态，检修维修工具应当采用防止产生火花的防爆工具。作业后，应当妥善清理现场，作业点最高温度恢复到常温后方可重新开始生产。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第二十条", "text": "粉尘涉爆企业应当做好粉尘爆炸危险场所设施设备的维护保养，加强对检修承包单位的安全管理，在承包协议中明确规定双方的安全生产权利义务，对检修承包单位的检修方案中涉及粉尘防爆的安全措施和应急处置措施进行审核，并监督承包单位落实。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第二十一条", "text": "安全生产技术服务机构为粉尘涉爆企业提供粉尘防爆相关的安全评价、检测、检验、风险评估、隐患排查等安全生产技术服务，应当按照法律、法规、规章和《粉尘防爆安全规程》等有关国家标准或者行业标准开展工作，保证其出具的报告和作出的结果真实、准确、完整，不得弄虚作假。 第三章 监督检查"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第二十二条", "text": "负责粉尘涉爆企业安全监管的部门应当按照分级属地原则，加强对企业粉尘防爆安全工作的监督检查，制定并落实年度监督检查计划，将粉尘作业人数多、爆炸风险较高的企业作为重点检查对象。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第二十三条", "text": "负责粉尘涉爆企业安全监管的部门对企业实施监督检查时，应当重点检查下列内容 五）粉尘防爆专项安全生产教育和培训记录； （六）粉尘爆炸危险场所检修、维修、动火等作业安全管理情况； （七）安全设备定期维护保养、检测或者检查等情况； （八）涉及粉尘爆炸危险的安全设施与主体工程同时设计、同时施工、同时投入生产和使用情况； （九）应急预案的制定、演练情况。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第二十四条", "text": "负责粉尘涉爆企业安全监管的部门应当按照工贸行业重大事故隐患判定标准、执法检查重点事项等有关标准和规定，对企业除尘系统、防火防爆、粉尘清理处置等重点部位和关键环节的粉尘防爆安全措施落实情况进行监督检查，督促企业落实粉尘防爆安全生产主体责任。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第二十五条", "text": "负责粉尘涉爆企业安全监管的部门可以根据需要，委托安全生产技术服务机构提供安全评价、检测、检验、隐患排查等技术服务，并承担相关费用。安全生产技术服务机构对其出具的有关报告和作出的结果负责。 安全生产技术服务机构出具的有关报告或者作出的结果可以作为行政执法的依据之一。 粉尘涉爆企业不得拒绝、阻挠负责粉尘涉爆企业安全监管的部门委托的安全生产技术服务机构开展技术服务工作。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第二十六条", "text": "负责粉尘涉爆企业安全监管的部门应当加强对监督检查人员的粉尘防爆专业知识培训，使其了解相关法律法规和标准要求，掌握执法检查重点事项和重大事故隐患判定标准，提高其行政执法能力。 第四章 法律责任"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第二十七条", "text": "粉尘涉爆企业有下列行为之一的，由负责粉尘涉爆企业安全监管的部门依照《中华人民共和国安全生产法》有关规定，责令限期改正，处5万元以下的罚款；逾期未改正的，处5万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款；情节严重的，责令停产停业整顿；构成犯罪的，依照刑法有关规定追究刑事责任： （一）未在产生、输送、收集、贮存可燃性粉尘，并且有较大危险因素的场所、设施和设备上设置明显的安全警示标志的； （二）粉尘防爆安全设备的安装、使用、检测、改造和报废不符合国家标准或者行业标准的； （三）未对粉尘防爆安全设备进行经常性维护、保养和定期检测或者检查的； （四）未为粉尘作业岗位相关从业人员提供符合国家标准或者行业标准的劳动防护用品的； （五）关闭、破坏直接关系粉尘防爆安全的监控、报警、防控等设备、设施，或者篡改、隐瞒、销毁其相关数据、信息的。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第二十八条", "text": "粉尘涉爆企业有下列行为之一的，由负责粉尘涉爆企业安全监管的部门依照《中华人民共和国安全生产法》有关规定，责令限期改正，处10万元以下的罚款；逾期未改正的，责令停产停业整顿，并处10万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款： （一）未按照规定对有关负责人和粉尘作业岗位相关从业人员进行粉尘防爆专项安全生产教育和培训，或者未如实记录专项安全生产教育和培训情况的； （二）未如实记录粉尘防爆隐患排查治理情况或者未向从业人员通报的； （三）未制定有关粉尘爆炸事故应急救援预案或者未定期组织演练的。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第二十九条", "text": "粉尘涉爆企业违反本规定"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第十九条", "text": "的规定，同时构成事故隐患，未采取措施消除的，依照《中华人民共和国安全生产法》有关规定，由负责粉尘涉爆企业安全监管的部门责令立即消除或者限期消除，处5万元以下的罚款；企业拒不执行的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处5万元以上10万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第三十条", "text": "粉尘涉爆企业有下列情形之一的，由负责粉尘涉爆企业安全监管的部门责令限期改正，处3万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处1万元以下的罚款： （一）企业新建、改建、扩建工程项目安全设施没有进行粉尘防爆安全设计，或者未按照设计进行施工的； （二）未按照规定建立粉尘防爆安全管理制度或者内容不符合企业实际的； （三）未按照规定辨识评估管控粉尘爆炸安全风险，未建立安全风险清单或者未及时维护相关信息档案的； （四）粉尘防爆安全设备未正常运行的。"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第三十一条", "text": "安全生产技术服务机构接受委托开展技术服务工作，出具失实报告的，依照《中华人民共和国安全生产法》有关规定，责令停业整顿，并处3万元以上10万元以下的罚款；给他人造成损害的，依法承担赔偿责任。 安全生产技术服务机构接受委托开展技术服务工作，出具虚假报告的，依照《中华人民共和国安全生产法》有关规定，没收违法所得；违法所得在10万元以上的，并处违法所得2倍以上5倍以下的罚款；没有违法所得或者违法所得不足10万元的，单处或者并处10万元以上20万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处5万元以上10万元以下的罚款；给他人造成损害的，与粉尘涉爆企业承担连带赔偿责任；构成犯罪的，依照刑法有关规定追究刑事责任。 对有前款违法行为的安全生产技术服务机构及其直接责任人员，吊销其相应资质和资格，5年内不得从事安全评价、认证、检测、检验等工作，情节严重的，实行终身行业和职业禁入。 第五章 附则"}, {"law": "工贸企业粉尘防爆安全规定_20210901.doc", "no": "第三十二条", "text": "本规定自2021年9月1日起施行。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第一条", "text": "为了规范废弃电器电子产品的回收处理活动，促进资源综合利用和循环经济发展，保护环境，保障人体健康，根据《中华人民共和国清洁生产促进法》和《中华人民共和国固体废物污染环境防治法》的有关规定，制定本条例。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第二条", "text": "本条例所称废弃电器电子产品的处理活动，是指将废弃电器电子产品进行拆解，从中提取物质作为原材料或者燃料，用改变废弃电器电子产品物理、化学特性的方法减少已产生的废弃电器电子产品数量，减少或者消除其危害成分，以及将其最终置于符合环境保护要求的填埋场的活动，不包括产品维修、翻新以及经维修、翻新后作为旧货再使用的活动。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第三条", "text": "列入《废弃电器电子产品处理目录》(以下简称《目录》)的废弃电器电子产品的回收处理及相关活动，适用本条例。 国务院资源综合利用主管部门会同国务院生态环境、工业信息产业等主管部门制订和调整《目录》，报国务院批准后实施。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第四条", "text": "国务院生态环境主管部门会同国务院资源综合利用、工业信息产业主管部门负责组织拟订废弃电器电子产品回收处理的政策措施并协调实施，负责废弃电器电子产品处理的监督管理工作。国务院商务主管部门负责废弃电器电子产品回收的管理工作。国务院财政、市场监督管理、税务、海关等主管部门在各自职责范围内负责相关管理工作。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第五条", "text": "国家对废弃电器电子产品实行多渠道回收和集中处理制度。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第六条", "text": "国家对废弃电器电子产品处理实行资格许可制度。设区的市级人民政府生态环境主管部门审批废弃电器电子产品处理企业(以下简称处理企业)资格。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第七条", "text": "国家建立废弃电器电子产品处理基金，用于废弃电器电子产品回收处理费用的补贴。电器电子产品生产者、进口电器电子产品的收货人或者其代理人应当按照规定履行废弃电器电子产品处理基金的缴纳义务。 废弃电器电子产品处理基金应当纳入预算管理，其征收、使用、管理的具体办法由国务院财政部门会同国务院生态环境、资源综合利用、工业信息产业主管部门制订，报国务院批准后施行。 制订废弃电器电子产品处理基金的征收标准和补贴标准，应当充分听取电器电子产品生产企业、处理企业、有关行业协会及专家的意见。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第八条", "text": "国家鼓励和支持废弃电器电子产品处理的科学研究、技术开发、相关技术标准的研究以及新技术、新工艺、新设备的示范、推广和应用。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第九条", "text": "属于国家禁止进口的废弃电器电子产品，不得进口。 第二章 相关方责任"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第十条", "text": "电器电子产品生产者、进口电器电子产品的收货人或者其代理人生产、进口的电器电子产品应当符合国家有关电器电子产品污染控制的规定，采用有利于资源综合利用和无害化处理的设计方案，使用无毒无害或者低毒低害以及便于回收利用的材料。 电器电子产品上或者产品说明书中应当按照规定提供有关有毒有害物质含量、回收处理提示性说明等信息。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第十一条", "text": "国家鼓励电器电子产品生产者自行或者委托销售者、维修机构、售后服务机构、废弃电器电子产品回收经营者回收废弃电器电子产品。电器电子产品销售者、维修机构、售后服务机构应当在其营业场所显著位置标注废弃电器电子产品回收处理提示性信息。 回收的废弃电器电子产品应当由有废弃电器电子产品处理资格的处理企业处理。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第十二条", "text": "废弃电器电子产品回收经营者应当采取多种方式为电器电子产品使用者提供方便、快捷的回收服务。 废弃电器电子产品回收经营者对回收的废弃电器电子产品进行处理，应当依照本条例规定取得废弃电器电子产品处理资格；未取得处理资格的，应当将回收的废弃电器电子产品交有废弃电器电子产品处理资格的处理企业处理。 回收的电器电子产品经过修复后销售的，必须符合保障人体健康和人身、财产安全等国家技术规范的强制性要求，并在显著位置标识为旧货。具体管理办法由国务院商务主管部门制定。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第十三条", "text": "机关、团体、企事业单位将废弃电器电子产品交有废弃电器电子产品处理资格的处理企业处理的，依照国家有关规定办理资产核销手续。 处理涉及国家秘密的废弃电器电子产品，依照国家保密规定办理。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第十四条", "text": "国家鼓励处理企业与相关电器电子产品生产者、销售者以及废弃电器电子产品回收经营者等建立长期合作关系，回收处理废弃电器电子产品。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第十五条", "text": "处理废弃电器电子产品，应当符合国家有关资源综合利用、环境保护、劳动安全和保障人体健康的要求。 禁止采用国家明令淘汰的技术和工艺处理废弃电器电子产品。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第十六条", "text": "处理企业应当建立废弃电器电子产品处理的日常环境监测制度。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第十七条", "text": "处理企业应当建立废弃电器电子产品的数据信息管理系统，向所在地的设区的市级人民政府生态环境主管部门报送废弃电器电子产品处理的基本数据和有关情况。废弃电器电子产品处理的基本数据的保存期限不得少于3年。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第十八条", "text": "处理企业处理废弃电器电子产品，依照国家有关规定享受税收优惠。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第十九条", "text": "回收、储存、运输、处理废弃电器电子产品的单位和个人，应当遵守国家有关环境保护和环境卫生管理的规定。 第三章 监督管理"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第二十条", "text": "国务院资源综合利用、市场监督管理、生态环境、工业信息产业等主管部门，依照规定的职责制定废弃电器电子产品处理的相关政策和技术规范。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第二十一条", "text": "省级人民政府生态环境主管部门会同同级资源综合利用、商务、工业信息产业主管部门编制本地区废弃电器电子产品处理发展规划，报国务院生态环境主管部门备案。 地方人民政府应当将废弃电器电子产品回收处理基础设施建设纳入城乡规划。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第二十二条", "text": "取得废弃电器电子产品处理资格，依照《中华人民共和国公司登记管理条例》等规定办理登记并在其经营范围中注明废弃电器电子产品处理的企业，方可从事废弃电器电子产品处理活动。 除本条例"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第三十四条", "text": "规定外，禁止未取得废弃电器电子产品处理资格的单位和个人处理废弃电器电子产品。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第二十三条", "text": "申请废弃电器电子产品处理资格，应当具备下列条件： (一)具备完善的废弃电器电子产品处理设施； (二)具有对不能完全处理的废弃电器电子产品的妥善利用或者处置方案； (三)具有与所处理的废弃电器电子产品相适应的分拣、包装以及其他设备； (四)具有相关安全、质量和环境保护的专业技术人员。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第二十四条", "text": "申请废弃电器电子产品处理资格，应当向所在地的设区的市级人民政府生态环境主管部门提交书面申请，并提供相关证明材料。受理申请的生态环境主管部门应当自收到完整的申请材料之日起60日内完成审查，作出准予许可或者不予许可的决定。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第二十五条", "text": "县级以上地方人民政府生态环境主管部门应当通过书面核查和实地检查等方式，加强对废弃电器电子产品处理活动的监督检查。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第二十六条", "text": "任何单位和个人都有权对违反本条例规定的行为向有关部门检举。有关部门应当为检举人保密，并依法及时处理。 第四章 法律责任"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第二十七条", "text": "违反本条例规定，电器电子产品生产者、进口电器电子产品的收货人或者其代理人生产、进口的电器电子产品上或者产品说明书中未按照规定提供有关有毒有害物质含量、回收处理提示性说明等信息的，由县级以上地方人民政府市场监督管理部门责令限期改正，处5万元以下的罚款。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第二十八条", "text": "违反本条例规定，未取得废弃电器电子产品处理资格擅自从事废弃电器电子产品处理活动的，由县级以上人民政府生态环境主管部门责令停业、关闭，没收违法所得，并处5万元以上50万元以下的罚款。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第二十九条", "text": "违反本条例规定，采用国家明令淘汰的技术和工艺处理废弃电器电子产品的，由县级以上人民政府生态环境主管部门责令限期改正；情节严重的，由设区的市级人民政府生态环境主管部门依法暂停直至撤销其废弃电器电子产品处理资格。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第三十条", "text": "处理废弃电器电子产品造成环境污染的，由县级以上人民政府生态环境主管部门按照固体废物污染环境防治的有关规定予以处罚。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第三十一条", "text": "违反本条例规定，处理企业未建立废弃电器电子产品的数据信息管理系统，未按规定报送基本数据和有关情况或者报送基本数据、有关情况不真实，或者未按规定期限保存基本数据的，由所在地的设区的市级人民政府生态环境主管部门责令限期改正，可以处5万元以下的罚款。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第三十二条", "text": "违反本条例规定，处理企业未建立日常环境监测制度或者未开展日常环境监测的，由县级以上人民政府生态环境主管部门责令限期改正，可以处5万元以下的罚款。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第三十三条", "text": "违反本条例规定，有关行政主管部门的工作人员滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。 第五章 附则"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第三十四条", "text": "经省级人民政府批准，可以设立废弃电器电子产品集中处理场。废弃电器电子产品集中处理场应当具有完善的污染物集中处理设施，确保符合国家或者地方制定的污染物排放标准和固体废物污染环境防治技术标准，并应当遵守本条例的有关规定。 废弃电器电子产品集中处理场应当符合国家和当地工业区设置规划，与当地土地利用规划和城乡规划相协调，并应当加快实现产业升级。"}, {"law": "废弃电器电子产品回收处理管理条例_20190302.docx", "no": "第三十五条", "text": "本条例自2011年1月1日起施行。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第一条", "text": "为了加强建设工程安全生产监督管理，保障人民群众生命和财产安全，根据《中华人民共和国建筑法》、《中华人民共和国安全生产法》，制定本条例。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第二条", "text": "在中华人民共和国境内从事建设工程的新建、扩建、改建和拆除等有关活动及实施对建设工程安全生产的监督管理，必须遵守本条例。 本条例所称建设工程，是指土木工程、建筑工程、线路管道和设备安装工程及装修工程。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第三条", "text": "建设工程安全生产管理，坚持安全第一、预防为主的方针。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第四条", "text": "建设单位、勘察单位、设计单位、施工单位、工程监理单位及其他与建设工程安全生产有关的单位，必须遵守安全生产法律、法规的规定，保证建设工程安全生产，依法承担建设工程安全生产责任。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第五条", "text": "国家鼓励建设工程安全生产的科学技术研究和先进技术的推广应用，推进建设工程安全生产的科学管理。 第二章 建设单位的安全责任"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第六条", "text": "建设单位应当向施工单位提供施工现场及毗邻区域内供水、排水、供电、供气、供热、通信、广播电视等地下管线资料，气象和水文观测资料，相邻建筑物和构筑物、地下工程的有关资料，并保证资料的真实、准确、完整。 建设单位因建设工程需要，向有关部门或者单位查询前款规定的资料时，有关部门或者单位应当及时提供。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第七条", "text": "建设单位不得对勘察、设计、施工、工程监理等单位提出不符合建设工程安全生产法律、法规和强制性标准规定的要求，不得压缩合同约定的工期。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第八条", "text": "建设单位在编制工程概算时，应当确定建设工程安全作业环境及安全施工措施所需费用。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第九条", "text": "建设单位不得明示或者暗示施工单位购买、租赁、使用不符合安全施工要求的安全防护用具、机械设备、施工机具及配件、消防设施和器材。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第十条", "text": "建设单位在申请领取施工许可证时，应当提供建设工程有关安全施工措施的资料。 依法批准开工报告的建设工程，建设单位应当自开工报告批准之日起15日内，将保证安全施工的措施报送建设工程所在地的县级以上地方人民政府建设行政主管部门或者其他有关部门备案。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第十一条", "text": "建设单位应当将拆除工程发包给具有相应资质等级的施工单位。 建设单位应当在拆除工程施工15日前，将下列资料报送建设工程所在地的县级以上地方人民政府建设行政主管部门或者其他有关部门备案： (一)施工单位资质等级证明； (二)拟拆除建筑物、构筑物及可能危及毗邻建筑的说明； (三)拆除施工组织方案； (四)堆放、清除废弃物的措施。 实施爆破作业的，应当遵守国家有关民用爆炸物品管理的规定。 第三章 勘察、设计、工程监理及其他有关单位的安全责任"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第十二条", "text": "勘察单位应当按照法律、法规和工程建设强制性标准进行勘察，提供的勘察文件应当真实、准确，满足建设工程安全生产的需要。 勘察单位在勘察作业时，应当严格执行操作规程，采取措施保证各类管线、设施和周边建筑物、构筑物的安全。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第十三条", "text": "设计单位应当按照法律、法规和工程建设强制性标准进行设计，防止因设计不合理导致生产安全事故的发生。 设计单位应当考虑施工安全操作和防护的需要，对涉及施工安全的重点部位和环节在设计文件中注明，并对防范生产安全事故提出指导意见。 采用新结构、新材料、新工艺的建设工程和特殊结构的建设工程，设计单位应当在设计中提出保障施工作业人员安全和预防生产安全事故的措施建议。 设计单位和注册建筑师等注册执业人员应当对其设计负责。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第十四条", "text": "工程监理单位应当审查施工组织设计中的安全技术措施或者专项施工方案是否符合工程建设强制性标准。 工程监理单位在实施监理过程中，发现存在安全事故隐患的，应当要求施工单位整改；情况严重的，应当要求施工单位暂时停止施工，并及时报告建设单位。施工单位拒不整改或者不停止施工的，工程监理单位应当及时向有关主管部门报告。 工程监理单位和监理工程师应当按照法律、法规和工程建设强制性标准实施监理，并对建设工程安全生产承担监理责任。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第十五条", "text": "为建设工程提供机械设备和配件的单位，应当按照安全施工的要求配备齐全有效的保险、限位等安全设施和装置。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第十六条", "text": "出租的机械设备和施工机具及配件，应当具有生产(制造)许可证、产品合格证。 出租单位应当对出租的机械设备和施工机具及配件的安全性能进行检测，在签订租赁协议时，应当出具检测合格证明。 禁止出租检测不合格的机械设备和施工机具及配件。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第十七条", "text": "在施工现场安装、拆卸施工起重机械和整体提升脚手架、模板等自升式架设设施，必须由具有相应资质的单位承担。 安装、拆卸施工起重机械和整体提升脚手架、模板等自升式架设设施，应当编制拆装方案、制定安全施工措施，并由专业技术人员现场监督。 施工起重机械和整体提升脚手架、模板等自升式架设设施安装完毕后，安装单位应当自检，出具自检合格证明，并向施工单位进行安全使用说明，办理验收手续并签字。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第十八条", "text": "施工起重机械和整体提升脚手架、模板等自升式架设设施的使用达到国家规定的检验检测期限的，必须经具有专业资质的检验检测机构检测。经检测不合格的，不得继续使用。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第十九条", "text": "检验检测机构对检测合格的施工起重机械和整体提升脚手架、模板等自升式架设设施，应当出具安全合格证明文件，并对检测结果负责。 第四章 施工单位的安全责任"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第二十条", "text": "施工单位从事建设工程的新建、扩建、改建和拆除等活动，应当具备国家规定的注册资本、专业技术人员、技术装备和安全生产等条件，依法取得相应等级的资质证书，并在其资质等级许可的范围内承揽工程。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第二十一条", "text": "施工单位主要负责人依法对本单位的安全生产工作全面负责。施工单位应当建立健全安全生产责任制度和安全生产教育培训制度，制定安全生产规章制度和操作规程，保证本单位安全生产条件所需资金的投入，对所承担的建设工程进行定期和专项安全检查，并做好安全检查记录。 施工单位的项目负责人应当由取得相应执业资格的人员担任，对建设工程项目的安全施工负责，落实安全生产责任制度、安全生产规章制度和操作规程，确保安全生产费用的有效使用，并根据工程的特点组织制定安全施工措施，消除安全事故隐患，及时、如实报告生产安全事故。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第二十二条", "text": "施工单位对列入建设工程概算的安全作业环境及安全施工措施所需费用，应当用于施工安全防护用具及设施的采购和更新、安全施工措施的落实、安全生产条件的改善，不得挪作他用。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第二十三条", "text": "施工单位应当设立安全生产管理机构，配备专职安全生产管理人员。 专职安全生产管理人员负责对安全生产进行现场监督检查。发现安全事故隐患，应当及时向项目负责人和安全生产管理机构报告；对于违章指挥、违章操作的，应当立即制止。 专职安全生产管理人员的配备办法由国务院建设行政主管部门会同国务院其他有关部门制定。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第二十四条", "text": "建设工程实行施工总承包的，由总承包单位对施工现场的安全生产负总责。 总承包单位应当自行完成建设工程主体结构的施工。 总承包单位依法将建设工程分包给其他单位的，分包合同中应当明确各自的安全生产方面的权利、义务。总承包单位和分包单位对分包工程的安全生产承担连带责任。 分包单位应当服从总承包单位的安全生产管理，分包单位不服从管理导致生产安全事故的，由分包单位承担主要责任。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第二十五条", "text": "垂直运输机械作业人员、安装拆卸工、爆破作业人员、起重信号工、登高架设作业人员等特种作业人员，必须按照国家有关规定经过专门的安全作业培训，并取得特种作业操作资格证书后，方可上岗作业。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第二十六条", "text": "施工单位应当在施工组织设计中编制安全技术措施和施工现场临时用电方案，对下列达到一定规模的危险性较大的分部分项工程编制专项施工方案，并附具安全验算结果，经施工单位技术负责人、总监理工程师签字后实施，由专职安全生产管理人员进行现场监督： (一)基坑支护与降水工程； (二)土方开挖工程； (三)模板工程； (四)起重吊装工程； (五)脚手架工程； (六)拆除、爆破工程； (七)国务院建设行政主管部门或者其他有关部门规定的其他危险性较大的工程。 对前款所列工程中涉及深基坑、地下暗挖工程、高大模板工程的专项施工方案，施工单位还应当组织专家进行论证、审查。 本条第一款规定的达到一定规模的危险性较大工程的标准，由国务院建设行政主管部门会同国务院其他有关部门制定。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第二十七条", "text": "建设工程施工前，施工单位负责项目管理的技术人员应当对有关安全施工的技术要求向施工作业班组、作业人员作出详细说明，并由双方签字确认。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第二十八条", "text": "施工单位应当在施工现场入口处、施工起重机械、临时用电设施、脚手架、出入通道口、楼梯口、电梯井口、孔洞口、桥梁口、隧道口、基坑边沿、爆破物及有害危险气体和液体存放处等危险部位，设置明显的安全警示标志。安全警示标志必须符合国家标准。 施工单位应当根据不同施工阶段和周围环境及季节、气候的变化，在施工现场采取相应的安全施工措施。施工现场暂时停止施工的，施工单位应当做好现场防护，所需费用由责任方承担，或者按照合同约定执行。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第二十九条", "text": "施工单位应当将施工现场的办公、生活区与作业区分开设置，并保持安全距离；办公、生活区的选址应当符合安全性要求。职工的膳食、饮水、休息场所等应当符合卫生标准。施工单位不得在尚未竣工的建筑物内设置员工集体宿舍。 施工现场临时搭建的建筑物应当符合安全使用要求。施工现场使用的装配式活动房屋应当具有产品合格证。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第三十条", "text": "施工单位对因建设工程施工可能造成损害的毗邻建筑物、构筑物和地下管线等，应当采取专项防护措施。 施工单位应当遵守有关环境保护法律、法规的规定，在施工现场采取措施，防止或者减少粉尘、废气、废水、固体废物、噪声、振动和施工照明对人和环境的危害和污染。 在城市市区内的建设工程，施工单位应当对施工现场实行封闭围挡。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第三十一条", "text": "施工单位应当在施工现场建立消防安全责任制度，确定消防安全责任人，制定用火、用电、使用易燃易爆材料等各项消防安全管理制度和操作规程，设置消防通道、消防水源，配备消防设施和灭火器材，并在施工现场入口处设置明显标志。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第三十二条", "text": "施工单位应当向作业人员提供安全防护用具和安全防护服装，并书面告知危险岗位的操作规程和违章操作的危害。 作业人员有权对施工现场的作业条件、作业程序和作业方式中存在的安全问题提出批评、检举和控告，有权拒绝违章指挥和强令冒险作业。 在施工中发生危及人身安全的紧急情况时，作业人员有权立即停止作业或者在采取必要的应急措施后撤离危险区域。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第三十三条", "text": "作业人员应当遵守安全施工的强制性标准、规章制度和操作规程，正确使用安全防护用具、机械设备等。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第三十四条", "text": "施工单位采购、租赁的安全防护用具、机械设备、施工机具及配件，应当具有生产(制造)许可证、产品合格证，并在进入施工现场前进行查验。 施工现场的安全防护用具、机械设备、施工机具及配件必须由专人管理，定期进行检查、维修和保养，建立相应的资料档案，并按照国家有关规定及时报废。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第三十五条", "text": "施工单位在使用施工起重机械和整体提升脚手架、模板等自升式架设设施前，应当组织有关单位进行验收，也可以委托具有相应资质的检验检测机构进行验收；使用承租的机械设备和施工机具及配件的，由施工总承包单位、分包单位、出租单位和安装单位共同进行验收。验收合格的方可使用。 《特种设备安全监察条例》规定的施工起重机械，在验收前应当经有相应资质的检验检测机构监督检验合格。 施工单位应当自施工起重机械和整体提升脚手架、模板等自升式架设设施验收合格之日起30日内，向建设行政主管部门或者其他有关部门登记。登记标志应当置于或者附着于该设备的显著位置。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第三十六条", "text": "施工单位的主要负责人、项目负责人、专职安全生产管理人员应当经建设行政主管部门或者其他有关部门考核合格后方可任职。 施工单位应当对管理人员和作业人员每年至少进行一次安全生产教育培训，其教育培训情况记入个人工作档案。安全生产教育培训考核不合格的人员，不得上岗。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第三十七条", "text": "作业人员进入新的岗位或者新的施工现场前，应当接受安全生产教育培训。未经教育培训或者教育培训考核不合格的人员，不得上岗作业。 施工单位在采用新技术、新工艺、新设备、新材料时，应当对作业人员进行相应的安全生产教育培训。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第三十八条", "text": "施工单位应当为施工现场从事危险作业的人员办理意外伤害保险。 意外伤害保险费由施工单位支付。实行施工总承包的，由总承包单位支付意外伤害保险费。意外伤害保险期限自建设工程开工之日起至竣工验收合格止。 第五章 监督管理"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第三十九条", "text": "国务院负责安全生产监督管理的部门依照《中华人民共和国安全生产法》的规定，对全国建设工程安全生产工作实施综合监督管理。 县级以上地方人民政府负责安全生产监督管理的部门依照《中华人民共和国安全生产法》的规定，对本行政区域内建设工程安全生产工作实施综合监督管理。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第四十条", "text": "国务院建设行政主管部门对全国的建设工程安全生产实施监督管理。国务院铁路、交通、水利等有关部门按照国务院规定的职责分工，负责有关专业建设工程安全生产的监督管理。 县级以上地方人民政府建设行政主管部门对本行政区域内的建设工程安全生产实施监督管理。县级以上地方人民政府交通、水利等有关部门在各自的职责范围内，负责本行政区域内的专业建设工程安全生产的监督管理。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第四十一条", "text": "建设行政主管部门和其他有关部门应当将本条例"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第十一条", "text": "规定的有关资料的主要内容抄送同级负责安全生产监督管理的部门。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第四十二条", "text": "建设行政主管部门在审核发放施工许可证时，应当对建设工程是否有安全施工措施进行审查，对没有安全施工措施的，不得颁发施工许可证。 建设行政主管部门或者其他有关部门对建设工程是否有安全施工措施进行审查时，不得收取费用。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第四十三条", "text": "县级以上人民政府负有建设工程安全生产监督管理职责的部门在各自的职责范围内履行安全监督检查职责时，有权采取下列措施： (一)要求被检查单位提供有关建设工程安全生产的文件和资料； (二)进入被检查单位施工现场进行检查； (三)纠正施工中违反安全生产要求的行为； (四)对检查中发现的安全事故隐患，责令立即排除；重大安全事故隐患排除前或者排除过程中无法保证安全的，责令从危险区域内撤出作业人员或者暂时停止施工。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第四十四条", "text": "建设行政主管部门或者其他有关部门可以将施工现场的监督检查委托给建设工程安全监督机构具体实施。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第四十五条", "text": "国家对严重危及施工安全的工艺、设备、材料实行淘汰制度。具体目录由国务院建设行政主管部门会同国务院其他有关部门制定并公布。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第四十六条", "text": "县级以上人民政府建设行政主管部门和其他有关部门应当及时受理对建设工程生产安全事故及安全事故隐患的检举、控告和投诉。 第六章 生产安全事故的应急救援和调查处理"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第四十七条", "text": "县级以上地方人民政府建设行政主管部门应当根据本级人民政府的要求，制定本行政区域内建设工程特大生产安全事故应急救援预案。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第四十八条", "text": "施工单位应当制定本单位生产安全事故应急救援预案，建立应急救援组织或者配备应急救援人员，配备必要的应急救援器材、设备，并定期组织演练。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第四十九条", "text": "施工单位应当根据建设工程施工的特点、范围，对施工现场易发生重大事故的部位、环节进行监控，制定施工现场生产安全事故应急救援预案。实行施工总承包的，由总承包单位统一组织编制建设工程生产安全事故应急救援预案，工程总承包单位和分包单位按照应急救援预案，各自建立应急救援组织或者配备应急救援人员，配备救援器材、设备，并定期组织演练。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第五十条", "text": "施工单位发生生产安全事故，应当按照国家有关伤亡事故报告和调查处理的规定，及时、如实地向负责安全生产监督管理的部门、建设行政主管部门或者其他有关部门报告；特种设备发生事故的，还应当同时向特种设备安全监督管理部门报告。接到报告的部门应当按照国家有关规定，如实上报。 实行施工总承包的建设工程，由总承包单位负责上报事故。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第五十一条", "text": "发生生产安全事故后，施工单位应当采取措施防止事故扩大，保护事故现场。需要移动现场物品时，应当做出标记和书面记录，妥善保管有关证物。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第五十二条", "text": "建设工程生产安全事故的调查、对事故责任单位和责任人的处罚与处理，按照有关法律、法规的规定执行。 第七章 法律责任"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第五十三条", "text": "违反本条例的规定，县级以上人民政府建设行政主管部门或者其他有关行政管理部门的工作人员，有下列行为之一的，给予降级或者撤职的行政处分；构成犯罪的，依照刑法有关规定追究刑事责任： (一)对不具备安全生产条件的施工单位颁发资质证书的； (二)对没有安全施工措施的建设工程颁发施工许可证的； (三)发现违法行为不予查处的； (四)不依法履行监督管理职责的其他行为。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第五十四条", "text": "违反本条例的规定，建设单位未提供建设工程安全生产作业环境及安全施工措施所需费用的，责令限期改正；逾期未改正的，责令该建设工程停止施工。 建设单位未将保证安全施工的措施或者拆除工程的有关资料报送有关部门备案的，责令限期改正，给予警告。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第五十五条", "text": "违反本条例的规定，建设单位有下列行为之一的，责令限期改正，处20万元以上50万元以下的罚款；造成重大安全事故，构成犯罪的，对直接责任人员，依照刑法有关规定追究刑事责任；造成损失的，依法承担赔偿责任： (一)对勘察、设计、施工、工程监理等单位提出不符合安全生产法律、法规和强制性标准规定的要求的； (二)要求施工单位压缩合同约定的工期的； (三)将拆除工程发包给不具有相应资质等级的施工单位的。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第五十六条", "text": "违反本条例的规定，勘察单位、设计单位有下列行为之一的，责令限期改正，处10万元以上30万元以下的罚款；情节严重的，责令停业整顿，降低资质等级，直至吊销资质证书；造成重大安全事故，构成犯罪的，对直接责任人员，依照刑法有关规定追究刑事责任；造成损失的，依法承担赔偿责任： (一)未按照法律、法规和工程建设强制性标准进行勘察、设计的； (二)采用新结构、新材料、新工艺的建设工程和特殊结构的建设工程，设计单位未在设计中提出保障施工作业人员安全和预防生产安全事故的措施建议的。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第五十七条", "text": "违反本条例的规定，工程监理单位有下列行为之一的，责令限期改正；逾期未改正的，责令停业整顿，并处10万元以上30万元以下的罚款；情节严重的，降低资质等级，直至吊销资质证书；造成重大安全事故，构成犯罪的，对直接责任人员，依照刑法有关规定追究刑事责任；造成损失的，依法承担赔偿责任： (一)未对施工组织设计中的安全技术措施或者专项施工方案进行审查的； (二)发现安全事故隐患未及时要求施工单位整改或者暂时停止施工的； (三)施工单位拒不整改或者不停止施工，未及时向有关主管部门报告的； (四)未依照法律、法规和工程建设强制性标准实施监理的。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第五十八条", "text": "注册执业人员未执行法律、法规和工程建设强制性标准的，责令停止执业3个月以上1年以下；情节严重的，吊销执业资格证书，5年内不予注册；造成重大安全事故的，终身不予注册；构成犯罪的，依照刑法有关规定追究刑事责任。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第五十九条", "text": "违反本条例的规定，为建设工程提供机械设备和配件的单位，未按照安全施工的要求配备齐全有效的保险、限位等安全设施和装置的，责令限期改正，处合同价款1倍以上3倍以下的罚款；造成损失的，依法承担赔偿责任。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第六十条", "text": "违反本条例的规定，出租单位出租未经安全性能检测或者经检测不合格的机械设备和施工机具及配件的，责令停业整顿，并处5万元以上10万元以下的罚款；造成损失的，依法承担赔偿责任。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第六十一条", "text": "违反本条例的规定，施工起重机械和整体提升脚手架、模板等自升式架设设施安装、拆卸单位有下列行为之一的，责令限期改正，处5万元以上10万元以下的罚款；情节严重的，责令停业整顿，降低资质等级，直至吊销资质证书；造成损失的，依法承担赔偿责任： (一)未编制拆装方案、制定安全施工措施的； (二)未由专业技术人员现场监督的； (三)未出具自检合格证明或者出具虚假证明的； (四)未向施工单位进行安全使用说明，办理移交手续的。 施工起重机械和整体提升脚手架、模板等自升式架设设施安装、拆卸单位有前款规定的第(一)项、第(三)项行为，经有关部门或者单位职工提出后，对事故隐患仍不采取措施，因而发生重大伤亡事故或者造成其他严重后果，构成犯罪的，对直接责任人员，依照刑法有关规定追究刑事责任。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第六十二条", "text": "违反本条例的规定，施工单位有下列行为之一的，责令限期改正；逾期未改正的，责令停业整顿，依照《中华人民共和国安全生产法》的有关规定处以罚款；造成重大安全事故，构成犯罪的，对直接责任人员，依照刑法有关规定追究刑事责任： (一)未设立安全生产管理机构、配备专职安全生产管理人员或者分部分项工程施工时无专职安全生产管理人员现场监督的； (二)施工单位的主要负责人、项目负责人、专职安全生产管理人员、作业人员或者特种作业人员，未经安全教育培训或者经考核不合格即从事相关工作的； (三)未在施工现场的危险部位设置明显的安全警示标志，或者未按照国家有关规定在施工现场设置消防通道、消防水源、配备消防设施和灭火器材的； (四)未向作业人员提供安全防护用具和安全防护服装的； (五)未按照规定在施工起重机械和整体提升脚手架、模板等自升式架设设施验收合格后登记的； (六)使用国家明令淘汰、禁止使用的危及施工安全的工艺、设备、材料的。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第六十三条", "text": "违反本条例的规定，施工单位挪用列入建设工程概算的安全生产作业环境及安全施工措施所需费用的，责令限期改正，处挪用费用20%以上50%以下的罚款；造成损失的，依法承担赔偿责任。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第六十四条", "text": "违反本条例的规定，施工单位有下列行为之一的，责令限期改正；逾期未改正的，责令停业整顿，并处5万元以上10万元以下的罚款；造成重大安全事故，构成犯罪的，对直接责任人员，依照刑法有关规定追究刑事责任： (一)施工前未对有关安全施工的技术要求作出详细说明的； (二)未根据不同施工阶段和周围环境及季节、气候的变化，在施工现场采取相应的安全施工措施，或者在城市市区内的建设工程的施工现场未实行封闭围挡的； (三)在尚未竣工的建筑物内设置员工集体宿舍的； (四)施工现场临时搭建的建筑物不符合安全使用要求的； (五)未对因建设工程施工可能造成损害的毗邻建筑物、构筑物和地下管线等采取专项防护措施的。 施工单位有前款规定第(四)项、第(五)项行为，造成损失的，依法承担赔偿责任。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第六十五条", "text": "违反本条例的规定，施工单位有下列行为之一的，责令限期改正；逾期未改正的，责令停业整顿，并处10万元以上30万元以下的罚款；情节严重的，降低资质等级，直至吊销资质证书；造成重大安全事故，构成犯罪的，对直接责任人员，依照刑法有关规定追究刑事责任；造成损失的，依法承担赔偿责任： (一)安全防护用具、机械设备、施工机具及配件在进入施工现场前未经查验或者查验不合格即投入使用的； (二)使用未经验收或者验收不合格的施工起重机械和整体提升脚手架、模板等自升式架设设施的； (三)委托不具有相应资质的单位承担施工现场安装、拆卸施工起重机械和整体提升脚手架、模板等自升式架设设施的； (四)在施工组织设计中未编制安全技术措施、施工现场临时用电方案或者专项施工方案的。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第六十六条", "text": "违反本条例的规定，施工单位的主要负责人、项目负责人未履行安全生产管理职责的，责令限期改正；逾期未改正的，责令施工单位停业整顿；造成重大安全事故、重大伤亡事故或者其他严重后果，构成犯罪的，依照刑法有关规定追究刑事责任。 作业人员不服管理、违反规章制度和操作规程冒险作业造成重大伤亡事故或者其他严重后果，构成犯罪的，依照刑法有关规定追究刑事责任。 施工单位的主要负责人、项目负责人有前款违法行为，尚不够刑事处罚的，处2万元以上20万元以下的罚款或者按照管理权限给予撤职处分；自刑罚执行完毕或者受处分之日起，5年内不得担任任何施工单位的主要负责人、项目负责人。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第六十七条", "text": "施工单位取得资质证书后，降低安全生产条件的，责令限期改正；经整改仍未达到与其资质等级相适应的安全生产条件的，责令停业整顿，降低其资质等级直至吊销资质证书。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第六十八条", "text": "本条例规定的行政处罚，由建设行政主管部门或者其他有关部门依照法定职权决定。 违反消防安全管理规定的行为，由公安消防机构依法处罚。 有关法律、行政法规对建设工程安全生产违法行为的行政处罚决定机关另有规定的，从其规定。 第八章 附则"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第六十九条", "text": "抢险救灾和农民自建低层住宅的安全生产管理，不适用本条例。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第七十条", "text": "军事建设工程的安全生产管理，按照中央军事委员会的有关规定执行。"}, {"law": "建设工程安全生产管理条例_20031124.docx", "no": "第七十一条", "text": "本条例自2004年2月1日起施行。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第一条", "text": "为加强建设项目安全管理，预防和减少生产安全事故，保障从业人员生命和财产安全，根据《中华人民共和国安全生产法》和《国务院关于进一步加强企业安全生产工作的通知》等法律、行政法规和规定，制定本办法。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第二条", "text": "经县级以上人民政府及其有关主管部门依法审批、核准或者备案的生产经营单位新建、改建、扩建工程项目（以下统称建设项目）安全设施的建设及其监督管理，适用本办法。 法律、行政法规及国务院对建设项目安全设施建设及其监督管理另有规定的，依照其规定。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第三条", "text": "本办法所称的建设项目安全设施，是指生产经营单位在生产经营活动中用于预防生产安全事故的设备、设施、装置、构（建）筑物和其他技术措施的总称。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第四条", "text": "生产经营单位是建设项目安全设施建设的责任主体。建设项目安全设施必须与主体工程同时设计、同时施工、同时投入生产和使用（以下简称“三同时”）。安全设施投资应当纳入建设项目概算。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第五条", "text": "国家安全生产监督管理总局对全国建设项目安全设施“三同时”实施综合监督管理，并在国务院规定的职责范围内承担有关建设项目安全设施“三同时”的监督管理。 县级以上地方各级安全生产监督管理部门对本行政区域内的建设项目安全设施“三同时”实施综合监督管理，并在本级人民政府规定的职责范围内承担本级人民政府及其有关主管部门审批、核准或者备案的建设项目安全设施“三同时”的监督管理。 跨两个及两个以上行政区域的建设项目安全设施“三同时”由其共同的上一级人民政府安全生产监督管理部门实施监督管理。 上一级人民政府安全生产监督管理部门根据工作需要，可以将其负责监督管理的建设项目安全设施“三同时”工作委托下一级人民政府安全生产监督管理部门实施监督管理。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第六条", "text": "安全生产监督管理部门应当加强建设项目安全设施建设的日常安全监管，落实有关行政许可及其监管责任，督促生产经营单位落实安全设施建设责任。 第二章 建设项目安全预评价"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第七条", "text": "下列建设项目在进行可行性研究时，生产经营单位应当按照国家规定，进行安全预评价： （一）非煤矿矿山建设项目； （二）生产、储存危险化学品（包括使用长输管道输送危险化学品，下同）的建设项目； （三）生产、储存烟花爆竹的建设项目； （四）金属冶炼建设项目； （五）使用危险化学品从事生产并且使用量达到规定数量的化工建设项目（属于危险化学品生产的除外，下同）； （六）法律、行政法规和国务院规定的其他建设项目。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第八条", "text": "生产经营单位应当委托具有相应资质的安全评价机构，对其建设项目进行安全预评价，并编制安全预评价报告。 建设项目安全预评价报告应当符合国家标准或者行业标准的规定。 生产、储存危险化学品的建设项目和化工建设项目安全预评价报告除符合本条第二款的规定外，还应当符合有关危险化学品建设项目的规定。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第七条", "text": "规定以外的其他建设项目，生产经营单位应当对其安全生产条件和设施进行综合分析，形成书面报告备查。 第三章 建设项目安全设施设计审查"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第十条", "text": "生产经营单位在建设项目初步设计时，应当委托有相应资质的设计单位对建设项目安全设施同时进行设计，编制安全设施设计。 安全设施设计必须符合有关法律、法规、规章和国家标准或者行业标准、技术规范的规定，并尽可能采用先进适用的工艺、技术和可靠的设备、设施。本办法"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第七条", "text": "规定的建设项目安全设施设计还应当充分考虑建设项目安全预评价报告提出的安全对策措施。 安全设施设计单位、设计人应当对其编制的设计文件负责。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第十一条", "text": "建设项目安全设施设计应当包括下列内容： （一）设计依据； （二）建设项目概述； （三）建设项目潜在的危险、有害因素和危险、有害程度及周边环境安全分析； （四）建筑及场地布置； （五）重大危险源分析及检测监控； （六）安全设施设计采取的防范措施； （七）安全生产管理机构设置或者安全生产管理人员配备要求； （八）从业人员安全生产教育和培训要求； （九）工艺、技术和设备、设施的先进性和可靠性分析； （十）安全设施专项投资概算； （十一）安全预评价报告中的安全对策及建议采纳情况； （十二）预期效果以及存在的问题与建议； （十三）可能出现的事故预防及应急救援措施； （十四）法律、法规、规章、标准规定需要说明的其他事项。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第七条", "text": "第（一）项、第（二）项、第（三）项、第（四）项规定的建设项目安全设施设计完成后，生产经营单位应当按照本办法"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第五条", "text": "的规定向安全生产监督管理部门提出审查申请，并提交下列文件资料： （一）建设项目审批、核准或者备案的文件； （二）建设项目安全设施设计审查申请； （三）设计单位的设计资质证明文件； （四）建设项目安全设施设计； （五）建设项目安全预评价报告及相关文件资料； （六）法律、行政法规、规章规定的其他文件资料。 安全生产监督管理部门收到申请后，对属于本部门职责范围内的，应当及时进行审查，并在收到申请后5个工作日内作出受理或者不予受理的决定，书面告知申请人；对不属于本部门职责范围内的，应当将有关文件资料转送有审查权的安全生产监督管理部门，并书面告知申请人。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第十三条", "text": "对已经受理的建设项目安全设施设计审查申请，安全生产监督管理部门应当自受理之日起20个工作日内作出是否批准的决定，并书面告知申请人。20个工作日内不能作出决定的，经本部门负责人批准，可以延长10个工作日，并应当将延长期限的理由书面告知申请人。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第十四条", "text": "建设项目安全设施设计有下列情形之一的，不予批准，并不得开工建设： （一）无建设项目审批、核准或者备案文件的； （二）未委托具有相应资质的设计单位进行设计的； （三）安全预评价报告由未取得相应资质的安全评价机构编制的； （四）设计内容不符合有关安全生产的法律、法规、规章和国家标准或者行业标准、技术规范的规定的； （五）未采纳安全预评价报告中的安全对策和建议，且未作充分论证说明的； （六）不符合法律、行政法规规定的其他条件的。 建设项目安全设施设计审查未予批准的，生产经营单位经过整改后可以向原审查部门申请再审。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第十五条", "text": "已经批准的建设项目及其安全设施设计有下列情形之一的，生产经营单位应当报原批准部门审查同意；未经审查同意的，不得开工建设： （一）建设项目的规模、生产工艺、原料、设备发生重大变更的； （二）改变安全设施设计且可能降低安全性能的； （三）在施工期间重新设计的。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第七条", "text": "第（一）项、第（二）项、第（三）项和第（四）项规定以外的建设项目安全设施设计，由生产经营单位组织审查，形成书面报告备查。 第四章 建设项目安全设施施工和竣工验收"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第十七条", "text": "建设项目安全设施的施工应当由取得相应资质的施工单位进行，并与建设项目主体工程同时施工。 施工单位应当在施工组织设计中编制安全技术措施和施工现场临时用电方案，同时对危险性较大的分部分项工程依法编制专项施工方案，并附具安全验算结果，经施工单位技术负责人、总监理工程师签字后实施。 施工单位应当严格按照安全设施设计和相关施工技术标准、规范施工，并对安全设施的工程质量负责。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第十八条", "text": "施工单位发现安全设施设计文件有错漏的，应当及时向生产经营单位、设计单位提出。生产经营单位、设计单位应当及时处理。 施工单位发现安全设施存在重大事故隐患时，应当立即停止施工并报告生产经营单位进行整改。整改合格后，方可恢复施工。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第十九条", "text": "工程监理单位应当审查施工组织设计中的安全技术措施或者专项施工方案是否符合工程建设强制性标准。 工程监理单位在实施监理过程中，发现存在事故隐患的，应当要求施工单位整改；情况严重的，应当要求施工单位暂时停止施工，并及时报告生产经营单位。施工单位拒不整改或者不停止施工的，工程监理单位应当及时向有关主管部门报告。 工程监理单位、监理人员应当按照法律、法规和工程建设强制性标准实施监理，并对安全设施工程的工程质量承担监理责任。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第二十条", "text": "建设项目安全设施建成后，生产经营单位应当对安全设施进行检查，对发现的问题及时整改。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第七条", "text": "规定的建设项目竣工后，根据规定建设项目需要试运行（包括生产、使用，下同）的，应当在正式投入生产或者使用前进行试运行。 试运行时间应当不少于30日，最长不得超过180日，国家有关部门有规定或者特殊要求的行业除外。 生产、储存危险化学品的建设项目和化工建设项目，应当在建设项目试运行前将试运行方案报负责建设项目安全许可的安全生产监督管理部门备案。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第七条", "text": "规定的建设项目安全设施竣工或者试运行完成后，生产经营单位应当委托具有相应资质的安全评价机构对安全设施进行验收评价，并编制建设项目安全验收评价报告。 建设项目安全验收评价报告应当符合国家标准或者行业标准的规定。 生产、储存危险化学品的建设项目和化工建设项目安全验收评价报告除符合本条第二款的规定外，还应当符合有关危险化学品建设项目的规定。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第二十三条", "text": "建设项目竣工投入生产或者使用前，生产经营单位应当组织对安全设施进行竣工验收，并形成书面报告备查。安全设施竣工验收合格后，方可投入生产和使用。 安全监管部门应当按照下列方式之一对本办法"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第七条", "text": "第（一）项、第（二）项、第（三）项和第（四）项规定建设项目的竣工验收活动和验收结果的监督核查： （一）对安全设施竣工验收报告按照不少于总数10%的比例进行随机抽查； （二）在实施有关安全许可时，对建设项目安全设施竣工验收报告进行审查。 抽查和审查以书面方式为主。对竣工验收报告的实质内容存在疑问，需要到现场核查的，安全监管部门应当指派两名以上工作人员对有关内容进行现场核查。工作人员应当提出现场核查意见，并如实记录在案。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第二十四条", "text": "建设项目的安全设施有下列情形之一的，建设单位不得通过竣工验收，并不得投入生产或者使用： （一）未选择具有相应资质的施工单位施工的； （二）未按照建设项目安全设施设计文件施工或者施工质量未达到建设项目安全设施设计文件要求的； （三）建设项目安全设施的施工不符合国家有关施工技术标准的； （四）未选择具有相应资质的安全评价机构进行安全验收评价或者安全验收评价不合格的； （五）安全设施和安全生产条件不符合有关安全生产法律、法规、规章和国家标准或者行业标准、技术规范规定的； （六）发现建设项目试运行期间存在事故隐患未整改的； （七）未依法设置安全生产管理机构或者配备安全生产管理人员的； （八）从业人员未经过安全生产教育和培训或者不具备相应资格的； （九）不符合法律、行政法规规定的其他条件的。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第二十五条", "text": "生产经营单位应当按照档案管理的规定，建立建设项目安全设施“三同时”文件资料档案，并妥善保存。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第二十六条", "text": "建设项目安全设施未与主体工程同时设计、同时施工或者同时投入使用的，安全生产监督管理部门对与此有关的行政许可一律不予审批，同时责令生产经营单位立即停止施工、限期改正违法行为，对有关生产经营单位和人员依法给予行政处罚。 第五章 法律责任"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第二十七条", "text": "建设项目安全设施“三同时”违反本办法的规定，安全生产监督管理部门及其工作人员给予审批通过或者颁发有关许可证的，依法给予行政处分。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第二十八条", "text": "生产经营单位对本办法"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第七条", "text": "第（一）项、第（二）项、第（三）项和第（四）项规定的建设项目有下列情形之一的，责令停止建设或者停产停业整顿，限期改正；逾期未改正的，处50万元以上100万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款；构成犯罪的，依照刑法有关规定追究刑事责任： （一）未按照本办法规定对建设项目进行安全评价的； （二）没有安全设施设计或者安全设施设计未按照规定报经安全生产监督管理部门审查同意，擅自开工的； （三）施工单位未按照批准的安全设施设计施工的； （四）投入生产或者使用前，安全设施未经验收合格的。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第二十九条", "text": "已经批准的建设项目安全设施设计发生重大变更，生产经营单位未报原批准部门审查同意擅自开工建设的，责令限期改正，可以并处1万元以上3万元以下的罚款。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第七条", "text": "第（一）项、第（二）项、第（三）项和第（四）项规定以外的建设项目有下列情形之一的，对有关生产经营单位责令限期改正，可以并处5000元以上3万元以下的罚款： （一）没有安全设施设计的； （二）安全设施设计未组织审查，并形成书面审查报告的； （三）施工单位未按照安全设施设计施工的； （四）投入生产或者使用前，安全设施未经竣工验收合格，并形成书面报告的。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第三十一条", "text": "承担建设项目安全评价的机构弄虚作假、出具虚假报告，尚未构成犯罪的，没收违法所得，违法所得在10万元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足10万元的，单处或者并处10万元以上20万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款；给他人造成损害的，与生产经营单位承担连带赔偿责任。 对有前款违法行为的机构，吊销其相应资质。"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第三十二条", "text": "本办法规定的行政处罚由安全生产监督管理部门决定。法律、行政法规对行政处罚的种类、幅度和决定机关另有规定的，依照其规定。 安全生产监督管理部门对应当由其他有关部门进行处理的“三同时”问题，应当及时移送有关部门并形成记录备查。 第六章 附则"}, {"law": "建设项目安全设施“三同时”监督管理办法.docx", "no": "第三十三条", "text": "本办法自2011年2月1日起施行。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第一条", "text": "为了防止建设项目产生新的污染、破坏生态环境，制定本条例。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第二条", "text": "在中华人民共和国领域和中华人民共和国管辖的其他海域内建设对环境有影响的建设项目，适用本条例。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第三条", "text": "建设产生污染的建设项目，必须遵守污染物排放的国家标准和地方标准；在实施重点污染物排放总量控制的区域内，还必须符合重点污染物排放总量控制的要求。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第四条", "text": "工业建设项目应当采用能耗物耗小、污染物产生量少的清洁生产工艺，合理利用自然资源，防止环境污染和生态破坏。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第五条", "text": "改建、扩建项目和技术改造项目必须采取措施，治理与该项目有关的原有环境污染和生态破坏。 第二章 环境影响评价"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第六条", "text": "国家实行建设项目环境影响评价制度。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第七条", "text": "国家根据建设项目对环境的影响程度，按照下列规定对建设项目的环境保护实行分类管理： (一)建设项目对环境可能造成重大影响的，应当编制环境影响报告书，对建设项目产生的污染和对环境的影响进行全面、详细的评价； (二)建设项目对环境可能造成轻度影响的，应当编制环境影响报告表，对建设项目产生的污染和对环境的影响进行分析或者专项评价； (三)建设项目对环境影响很小，不需要进行环境影响评价的，应当填报环境影响登记表。 建设项目环境影响评价分类管理名录，由国务院环境保护行政主管部门在组织专家进行论证和征求有关部门、行业协会、企事业单位、公众等意见的基础上制定并公布。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第八条", "text": "建设项目环境影响报告书，应当包括下列内容： (一)建设项目概况； (二)建设项目周围环境现状； (三)建设项目对环境可能造成影响的分析和预测； (四)环境保护措施及其经济、技术论证； (五)环境影响经济损益分析； (六)对建设项目实施环境监测的建议； (七)环境影响评价结论。 建设项目环境影响报告表、环境影响登记表的内容和格式，由国务院环境保护行政主管部门规定。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第九条", "text": "依法应当编制环境影响报告书、环境影响报告表的建设项目，建设单位应当在开工建设前将环境影响报告书、环境影响报告表报有审批权的环境保护行政主管部门审批；建设项目的环境影响评价文件未依法经审批部门审查或者审查后未予批准的，建设单位不得开工建设。 环境保护行政主管部门审批环境影响报告书、环境影响报告表，应当重点审查建设项目的环境可行性、环境影响分析预测评估的可靠性、环境保护措施的有效性、环境影响评价结论的科学性等，并分别自收到环境影响报告书之日起60日内、收到环境影响报告表之日起30日内，作出审批决定并书面通知建设单位。 环境保护行政主管部门可以组织技术机构对建设项目环境影响报告书、环境影响报告表进行技术评估，并承担相应费用；技术机构应当对其提出的技术评估意见负责，不得向建设单位、从事环境影响评价工作的单位收取任何费用。 依法应当填报环境影响登记表的建设项目，建设单位应当按照国务院环境保护行政主管部门的规定将环境影响登记表报建设项目所在地县级环境保护行政主管部门备案。 环境保护行政主管部门应当开展环境影响评价文件网上审批、备案和信息公开。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第十条", "text": "国务院环境保护行政主管部门负责审批下列建设项目环境影响报告书、环境影响报告表： (一)核设施、绝密工程等特殊性质的建设项目； (二)跨省、自治区、直辖市行政区域的建设项目； (三)国务院审批的或者国务院授权有关部门审批的建设项目。 前款规定以外的建设项目环境影响报告书、环境影响报告表的审批权限，由省、自治区、直辖市人民政府规定。 建设项目造成跨行政区域环境影响，有关环境保护行政主管部门对环境影响评价结论有争议的，其环境影响报告书或者环境影响报告表由共同上一级环境保护行政主管部门审批。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第十一条", "text": "建设项目有下列情形之一的，环境保护行政主管部门应当对环境影响报告书、环境影响报告表作出不予批准的决定： (一)建设项目类型及其选址、布局、规模等不符合环境保护法律法规和相关法定规划； (二)所在区域环境质量未达到国家或者地方环境质量标准，且建设项目拟采取的措施不能满足区域环境质量改善目标管理要求； (三)建设项目采取的污染防治措施无法确保污染物排放达到国家和地方排放标准，或者未采取必要措施预防和控制生态破坏； (四)改建、扩建和技术改造项目，未针对项目原有环境污染和生态破坏提出有效防治措施； (五)建设项目的环境影响报告书、环境影响报告表的基础资料数据明显不实，内容存在重大缺陷、遗漏，或者环境影响评价结论不明确、不合理。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第十二条", "text": "建设项目环境影响报告书、环境影响报告表经批准后，建设项目的性质、规模、地点、采用的生产工艺或者防治污染、防止生态破坏的措施发生重大变动的，建设单位应当重新报批建设项目环境影响报告书、环境影响报告表。 建设项目环境影响报告书、环境影响报告表自批准之日起满5年，建设项目方开工建设的，其环境影响报告书、环境影响报告表应当报原审批部门重新审核。原审批部门应当自收到建设项目环境影响报告书、环境影响报告表之日起10日内，将审核意见书面通知建设单位；逾期未通知的，视为审核同意。 审核、审批建设项目环境影响报告书、环境影响报告表及备案环境影响登记表，不得收取任何费用。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第十三条", "text": "建设单位可以采取公开招标的方式，选择从事环境影响评价工作的单位，对建设项目进行环境影响评价。 任何行政机关不得为建设单位指定从事环境影响评价工作的单位，进行环境影响评价。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第十四条", "text": "建设单位编制环境影响报告书，应当依照有关法律规定，征求建设项目所在地有关单位和居民的意见。 第三章 环境保护设施建设"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第十五条", "text": "建设项目需要配套建设的环境保护设施，必须与主体工程同时设计、同时施工、同时投产使用。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第十六条", "text": "建设项目的初步设计，应当按照环境保护设计规范的要求，编制环境保护篇章，落实防治环境污染和生态破坏的措施以及环境保护设施投资概算。 建设单位应当将环境保护设施建设纳入施工合同，保证环境保护设施建设进度和资金，并在项目建设过程中同时组织实施环境影响报告书、环境影响报告表及其审批部门审批决定中提出的环境保护对策措施。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第十七条", "text": "编制环境影响报告书、环境影响报告表的建设项目竣工后，建设单位应当按照国务院环境保护行政主管部门规定的标准和程序，对配套建设的环境保护设施进行验收，编制验收报告。 建设单位在环境保护设施验收过程中，应当如实查验、监测、记载建设项目环境保护设施的建设和调试情况，不得弄虚作假。 除按照国家规定需要保密的情形外，建设单位应当依法向社会公开验收报告。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第十八条", "text": "分期建设、分期投入生产或者使用的建设项目，其相应的环境保护设施应当分期验收。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第十九条", "text": "编制环境影响报告书、环境影响报告表的建设项目，其配套建设的环境保护设施经验收合格，方可投入生产或者使用；未经验收或者验收不合格的，不得投入生产或者使用。 前款规定的建设项目投入生产或者使用后，应当按照国务院环境保护行政主管部门的规定开展环境影响后评价。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第二十条", "text": "环境保护行政主管部门应当对建设项目环境保护设施设计、施工、验收、投入生产或者使用情况，以及有关环境影响评价文件确定的其他环境保护措施的落实情况，进行监督检查。 环境保护行政主管部门应当将建设项目有关环境违法信息记入社会诚信档案，及时向社会公开违法者名单。 第四章 法律责任"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第二十一条", "text": "建设单位有下列行为之一的，依照《中华人民共和国环境影响评价法》的规定处罚： (一)建设项目环境影响报告书、环境影响报告表未依法报批或者报请重新审核，擅自开工建设； (二)建设项目环境影响报告书、环境影响报告表未经批准或者重新审核同意，擅自开工建设； (三)建设项目环境影响登记表未依法备案。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第二十二条", "text": "违反本条例规定，建设单位编制建设项目初步设计未落实防治环境污染和生态破坏的措施以及环境保护设施投资概算，未将环境保护设施建设纳入施工合同，或者未依法开展环境影响后评价的，由建设项目所在地县级以上环境保护行政主管部门责令限期改正，处5万元以上20万元以下的罚款；逾期不改正的，处20万元以上100万元以下的罚款。 违反本条例规定，建设单位在项目建设过程中未同时组织实施环境影响报告书、环境影响报告表及其审批部门审批决定中提出的环境保护对策措施的，由建设项目所在地县级以上环境保护行政主管部门责令限期改正，处20万元以上100万元以下的罚款；逾期不改正的，责令停止建设。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第二十三条", "text": "违反本条例规定，需要配套建设的环境保护设施未建成、未经验收或者验收不合格，建设项目即投入生产或者使用，或者在环境保护设施验收中弄虚作假的，由县级以上环境保护行政主管部门责令限期改正，处20万元以上100万元以下的罚款；逾期不改正的，处100万元以上200万元以下的罚款；对直接负责的主管人员和其他责任人员，处5万元以上20万元以下的罚款；造成重大环境污染或者生态破坏的，责令停止生产或者使用，或者报经有批准权的人民政府批准，责令关闭。 违反本条例规定，建设单位未依法向社会公开环境保护设施验收报告的，由县级以上环境保护行政主管部门责令公开，处5万元以上20万元以下的罚款，并予以公告。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第二十四条", "text": "违反本条例规定，技术机构向建设单位、从事环境影响评价工作的单位收取费用的，由县级以上环境保护行政主管部门责令退还所收费用，处所收费用1倍以上3倍以下的罚款。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第二十五条", "text": "从事建设项目环境影响评价工作的单位，在环境影响评价工作中弄虚作假的，由县级以上环境保护行政主管部门处所收费用1倍以上3倍以下的罚款。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第二十六条", "text": "环境保护行政主管部门的工作人员徇私舞弊、滥用职权、玩忽职守，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予行政处分。 第五章 附则"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第二十七条", "text": "流域开发、开发区建设、城市新区建设和旧区改建等区域性开发，编制建设规划时，应当进行环境影响评价。具体办法由国务院环境保护行政主管部门会同国务院有关部门另行规定。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第二十八条", "text": "海洋工程建设项目的环境保护管理，按照国务院关于海洋工程环境保护管理的规定执行。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第二十九条", "text": "军事设施建设项目的环境保护管理，按照中央军事委员会的有关规定执行。"}, {"law": "建设项目环境保护管理条例_20170716.docx", "no": "第三十条", "text": "本条例自发布之日起施行。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第一条", "text": "为了规范排污许可管理，根据《中华人民共和国环境保护法》《中华人民共和国海洋环境保护法》和大气、水、固体废 物、土壤、噪声等专项污染防治法律，以及《排污许可管理条例》（以下简称《条例》），制定本办法。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第二条", "text": "排污许可证的申请、审批、执行以及与排污许可相关的监督管理等行为，适用本办法。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第三条", "text": "依照法律规定实行排污许可管理的企业事业单位和其他生产经营者（以下简称排污单位），应当依法申请取得排污许可 证，并按照排污许可证的规定排放污染物；未取得排污许可证的，不得排放污染物。 依法需要填报排污登记表的企业事业单位和其他生产经营者（以下简称排污登记单位），应当在全国排污许可证管理信息平台进 行排污登记。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第四条", "text": "根据污染物产生量、排放量、对环境的影响程度等因素，对企业事业单位和其他生产经营者实行排污许可重点管理、简化 管理和排污登记管理。 实行排污许可重点管理、简化管理的排污单位具体范围，依照固定污染源排污许可分类管理名录规定执行。实行排污登记管理的 排污登记单位具体范围由国务院生态环境主管部门制定并公布。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第五条", "text": "国务院生态环境主管部门负责全国排污许可的统一监督管理。 省级生态环境主管部门和设区的市级生态环境主管部门负责本行政区域排污许可的监督管理。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第六条", "text": "生态环境主管部门对排污单位的大气污染物、水污染物、工业固体废物、工业噪声等污染物排放行为实行综合许可管理。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第七条", "text": "国务院生态环境主管部门对排污单位及其生产设施、污染防治设施和排放口实行统一编码管理。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第八条", "text": "国务院生态环境主管部门负责建设、运行、维护、管理全国排污许可证管理信息平台。 排污许可证的申请、受理、审查、审批决定、变更、延续、注销、撤销、信息公开等应当通过全国排污许可证管理信息平台办 理。排污单位申请取得排污许可证的，也可以通过信函等方式提交书面申请。 全国排污许可证管理信息平台中记录的排污许可证相关电子信息与排污许可证正本、副本记载的信息依法具有同等效力。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第九条", "text": "排污许可证执行报告中报告的污染物实际排放量，可以作为开展年度生态环境统计、重点污染物排放总量考核、污染源排 放清单编制等工作的依据。 排污许可证应当作为排污权的确认凭证和排污权交易的管理载体。 第二章 排污许可证和排污登记表内容"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十条", "text": "排污许可证由正本和副本构成。 设区的市级以上地方人民政府生态环境主管部门可以依据地方性法规，增加需要在排污许可证中记载的内容。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十一条", "text": "排污许可证正本应当记载《条例》"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十三条", "text": "第一、二项规定的基本信息，排污许可证副本应当记载《条例》"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十三条", "text": "规 定的所有信息。 法律法规规定的排污单位应当遵守的大气污染物、水污染物、工业固体废物、工业噪声等控制污染物排放的要求，重污染天气等 特殊时段禁止或者限制污染物排放的要求，以及土壤污染重点监管单位的控制有毒有害物质排放、土壤污染隐患排查、自行监测等要 求，应当在排污许可证副本中记载。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十二条", "text": "排污单位承诺执行更加严格的排放限值的，应当在排污许可证副本中记载。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十三条", "text": "排污登记表应当记载下列信息： （一）排污登记单位名称、统一社会信用代码、生产经营场所所在地、行业类别、法定代表人或者实际负责人等基本信息； （二）污染物排放去向、执行的污染物排放标准及采取的污染防治措施等。 第三章 申请与审批"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十四条", "text": "排污单位应当在实际排污行为发生之前，向其生产经营场所所在地设区的市级以上地方人民政府生态环境主管部门（以 下简称审批部门）申请取得排污许可证。 海洋工程排污单位申请取得排污许可证的，依照有关法律、行政法规的规定执行。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十五条", "text": "排污单位有两个以上生产经营场所排放污染物的，应当分别向生产经营场所所在地的审批部门申请取得排污许可证。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十六条", "text": "实行排污许可重点管理的排污单位在提交排污许可证首次申请或者重新申请材料前，应当通过全国排污许可证管理信息 平台向社会公开基本信息和拟申请许可事项，并提交说明材料。公开时间不得少于五个工作日。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十七条", "text": "排污单位在填报排污许可证申请表时，应当承诺排污许可证申请材料的完整性、真实性和合法性，承诺按照排污许可证 的规定排放污染物，落实排污许可证规定的环境管理要求，并由法定代表人或者主要负责人签字或者盖章。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十八条", "text": "排污单位应当依照《条例》"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第八条", "text": "规定提交相应材料，并可以对申请材料进行补充说明，一并提交审批部门。 排污单位申请许可排放量的，应当一并提交排放量限值计算过程。重点污染物排放总量控制指标通过排污权交易获取的，还应当 提交排污权交易指标的证明材料。 污染物排放口已经建成的排污单位，应当提交有关排放口规范化的情况说明。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十九条", "text": "排污单位在申请排污许可证时，应当按照自行监测技术指南，编制自行监测方案。 自行监测方案应当包括以下内容： （一）监测点位及示意图、监测指标、监测频次； （二）使用的监测分析方法； （三）监测质量保证与质量控制要求； （四）监测数据记录、整理、存档要求； （五）监测数据信息公开要求。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第二十条", "text": "审批部门收到排污单位提交的申请材料后，依照《条例》"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十条", "text": "要求作出处理。 审批部门可以组织技术机构对排污许可证申请材料进行技术评估，并承担相应费用。技术机构应当遵循科学、客观、公正的原 则，提出技术评估意见，并对技术评估意见负责，不得向排污单位收取任何费用。 技术机构开展技术评估应当遵守国家相关法律法规、标准规范，保守排污单位商业秘密。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第二十一条", "text": "排污单位采用相应污染防治可行技术的，或者新建、改建、扩建建设项目排污单位采用环境影响报告书（表）批准文 件要求的污染防治技术的，审批部门可以认为排污单位采用的污染防治设施或者措施能够达到许可排放浓度要求。 不符合前款规定情形的，排污单位可以通过提供监测数据证明其采用的污染防治设施可以达到许可排放浓度要求。监测数据应当 通过使用符合国家有关环境监测、计量认证规定和技术规范的监测设备取得；对于国内首次采用的污染防治技术，应当提供工程试验 数据予以证明。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第二十二条", "text": "对具备下列条件的排污单位，颁发排污许可证： （一）依法取得建设项目环境影响报告书（表）批准文件，或者已经办理环境影响登记表备案手续； （二）污染物排放符合污染物排放标准要求，重点污染物排放符合排污许可证申请与核发技术规范、环境影响报告书（表）批准 文件、重点污染物排放总量控制要求；其中，排污单位生产经营场所位于未达到国家环境质量标准的重点区域、流域的，还应当符合 有关地方人民政府关于改善生态环境质量的特别要求； （三）采用污染防治设施可以达到许可排放浓度要求或者符合污染防治可行技术； （四）自行监测方案的监测点位、指标、频次等符合国家自行监测规范。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第二十三条", "text": "审批部门应当在法定审批期限内作出审批决定，对符合条件的颁发排污许可证；对不符合条件的应当出具不予许可决 定书，书面告知排污单位不予许可的理由，以及依法申请行政复议或者提起行政诉讼的权利。 依法需要听证、检验、检测、专家评审的，所需时间不计算在审批期限内，审批部门应当将所需时间书面告知排污单位。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第二十四条", "text": "排污单位依照《条例》"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十四条", "text": "第二款规定提出延续排污许可证时，应当按照规定提交延续申请表。审批部门作出延 续排污许可证决定的，延续后的排污许可证有效期自原排污许可证有效期届满的次日起计算。 排污单位未依照《条例》"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十四条", "text": "第二款规定提前六十日提交延续申请表，审批部门依法在原排污许可证有效期届满之后作出延 续排污许可证决定的，延续后的排污许可证有效期自作出延续决定之日起计算；审批部门依法在原排污许可证有效期届满之前作出延 续排污许可证决定的，延续后的排污许可证有效期自原排污许可证有效期届满的次日起计算。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第十五条", "text": "规定的应当重新申请排污许可证情形的，排污单位应当在实际排污行为变化之前重新申请取 得排污许可证。排污单位应当提交排污许可证申请表、由排污单位法定代表人或者主要负责人签字或者盖章的承诺书以及与重新申请 排污许可证有关的其他材料，并说明重新申请原因。 重新申请的排污许可证有效期自审批部门作出重新申请审批决定之日起计算。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第二十六条", "text": "排污单位名称、住所、法定代表人或者主要负责人等排污许可证正本中记载的基本信息发生变更的，排污单位应当自 变更之日起三十日内，向审批部门提交变更排污许可证申请表以及与变更排污许可证有关的其他材料。 审批部门应当自受理之日起十个工作日内作出变更决定，按规定换发排污许可证正本，相关变更内容载入排污许可证副本中的变 更、延续记录。 排污许可证记载信息的变更，不影响排污许可证的有效期。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第二十七条", "text": "排污单位适用的污染物排放标准、重点污染物排放总量控制要求发生变化，需要对排污许可证进行变更的，审批部门 应当在标准生效之前和总量控制指标变化后依法对排污许可证相应事项进行变更。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第二十七条", "text": "规定情形外，排污许可证记载内容发生变化的，排污单位可以主动向 审批部门提出调整排污许可证内容的申请，审批部门应当及时对排污许可证记载内容进行调整。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第二十九条", "text": "有下列情形之一的，审批部门应当依法办理排污许可证的注销手续，并在全国排污许可证管理信息平台上公告： （一）排污许可证有效期届满未延续的； （二）排污单位依法终止的； （三）排污许可证依法被撤销、吊销的； （四）应当注销的其他情形。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第三十条", "text": "有下列情形之一的，可以依法撤销排污许可证，并在全国排污许可证管理信息平台上公告： （一）超越法定职权审批排污许可证的； （二）违反法定程序审批排污许可证的； （三）审批部门工作人员滥用职权、玩忽职守审批排污许可证的； （四）对不具备申请资格或者不符合法定条件的排污单位审批排污许可证的； （五）依法可以撤销排污许可证的其他情形。 排污单位以欺骗、贿赂等不正当手段取得排污许可证的，应当依法予以撤销。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第三十一条", "text": "上级生态环境主管部门可以对具有审批权限的下级生态环境主管部门的排污许可证审批和执行情况进行监督检查和指 导，发现属于《条例》"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第三十二条", "text": "规定违法情形的，上级生态环境主管部门应当责令改正。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第三十二条", "text": "排污许可证发生遗失、损毁的，排污单位可以向审批部门申请补领。已经办理排污许可证电子证照的排污单位可以根 据需要自行打印排污许可证。 第四章 排污管理"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第三十三条", "text": "排污单位应当依照《条例》规定，严格落实环境保护主体责任，建立健全环境管理制度，按照排污许可证规定严格控 制污染物排放。 排污登记单位应当依照国家生态环境保护法律法规规章等管理规定运行和维护污染防治设施，建设规范化排放口，落实排污主体 责任，控制污染物排放。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第三十四条", "text": "排污单位应当按照排污许可证规定和有关标准规范，依法开展自行监测，保存原始监测记录。原始监测记录保存期限 不得少于五年。 排污单位对自行监测数据的真实性、准确性负责，不得篡改、伪造。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第三十五条", "text": "实行排污许可重点管理的排污单位，应当依法安装、使用、维护污染物排放自动监测设备，并与生态环境主管部门的 监控设备联网。 排污单位发现污染物排放自动监测设备传输数据异常的，应当及时报告生态环境主管部门，并进行检查、修复。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第三十六条", "text": "排污单位应当按照排污许可证规定的格式、内容和频次要求记录环境管理台账，主要包括以下内容： （一）与污染物排放相关的主要生产设施运行情况；发生异常情况的，应当记录原因和采取的措施。 （二）污染防治设施运行情况及管理信息；发生异常情况的，应当记录原因和采取的措施。 （三）污染物实际排放浓度和排放量；发生超标排放情况的，应当记录超标原因和采取的措施。 （四）其他按照相关技术规范应当记录的信息。 环境管理台账记录保存期限不得少于五年。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第三十七条", "text": "排污单位应当按照排污许可证规定的执行报告内容、频次和时间要求，在全国排污许可证管理信息平台上填报、提交 排污许可证执行报告。 排污许可证执行报告包括年度执行报告、季度执行报告和月执行报告。 季度执行报告和月执行报告应当包括以下内容： （一）根据自行监测结果说明污染物实际排放浓度和排放量及达标判定分析； （二）排污单位超标排放或者污染防治设施异常情况的说明。 年度执行报告可以替代当季度或者当月的执行报告，并增加以下内容： （一）排污单位基本生产信息； （二）污染防治设施运行情况； （三）自行监测执行情况； （四）环境管理台账记录执行情况； （五）信息公开情况； （六）排污单位内部环境管理体系建设与运行情况； （七）其他排污许可证规定的内容执行情况。 建设项目竣工环境保护设施验收报告中污染源监测数据等与污染物排放相关的主要内容，应当由排污单位记载在该项目竣工环境 保护设施验收完成当年的排污许可证年度执行报告中。排污许可证执行情况应当作为环境影响后评价的重要依据。 排污单位发生污染事故排放时，应当依照相关法律法规规章的规定及时报告。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第三十八条", "text": "排污单位应当按照排污许可证规定，如实在全国排污许可证管理信息平台上公开污染物排放信息。 污染物排放信息应当包括污染物排放种类、排放浓度和排放量，以及污染防治设施的建设运行情况、排污许可证执行报告、自行 监测数据等；水污染物排入市政排水管网的，还应当包括污水接入市政排水管网位置、排放方式等信息。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第三十九条", "text": "排污登记单位应当在实际排污行为发生之前，通过全国排污许可证管理信息平台填报排污登记表，提交后即时生成登 记编号和回执，由排污登记单位自行留存。排污登记单位应当对填报信息的真实性、准确性、完整性负责。 排污登记表自获得登记编号之日起生效，有效期限依照相关法律法规规定执行。 排污登记信息发生变动的，排污登记单位应当自发生变动之日起二十日内进行变更登记。 排污登记单位因关闭等原因不再排污的，应当及时在全国排污许可证管理信息平台注销排污登记表。 排污登记单位因生产和排污情况发生变化等原因，依法需要申领排污许可证的，应当依照相关法律法规和本办法的规定及时申请 取得排污许可证并注销排污登记表。 第五章 监督检查"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第四十条", "text": "生态环境主管部门应当将排污许可证和排污登记信息纳入执法监管数据库，将排污许可执法检查纳入生态环境执法年度 计划，加强对排污许可证记载事项的清单式执法检查。 对未取得排污许可证排放污染物、不按照排污许可证要求排放污染物、未按规定填报排污登记表等违反排污许可管理的行为，依 照相关法律法规和《条例》有关规定进行处理。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第四十一条", "text": "生态环境主管部门应当定期组织开展排污许可证执行报告落实情况的检查，重点检查排污单位提交执行报告的及时 性、报告内容的完整性、排污行为的合规性、污染物排放量数据的准确性以及各项管理要求的落实情况等内容。 排污许可证执行报告检查依托全国排污许可证管理信息平台开展。生态环境主管部门可以要求排污单位补充提供环境管理台账记 录、自行监测数据等相关材料，必要时可以组织开展现场核查。 字号：[大] [中] [小] [打印] 仅打印内容"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第四十二条", "text": "生态环境主管部门应当加强排污许可证质量管理，建立质量审核机制，定期开展排污许可证质量核查。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第四十三条", "text": "排污单位应当树立持证排污、按证排污意识，及时公开排污信息，自觉接受公众监督。 鼓励社会公众依法参与监督排污单位和排污登记单位排污行为。任何单位和个人对违反本办法规定的行为，均有权向生态环境主 管部门举报。接到举报的生态环境主管部门应当依法处理，按照有关规定向举报人反馈处理结果，并为举报人保密。 第六章 附 则"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第四十四条", "text": "排污许可证正本、副本、承诺书样本和申请、延续、变更排污许可证申请表格式，由国务院生态环境主管部门制定。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第四十五条", "text": "排污单位涉及国家秘密的，其排污许可、排污登记及相关的监督管理等应当遵守国家有关保密法律法规的规定。"}, {"law": "排污许可管理办法_20240701.pdf", "no": "第四十六条", "text": "本办法自2024年7月1日起施行。原环境保护部发布的《排污许可管理办法（试行）》（环境保护部令第48号）同时 废止。 解读：1.生态环境部环评司、法规司有关负责人就《排污许可管理办法》有关问题答记者问 2.一图读懂《排污许可管理办法》"}, {"law": "排污许可管理条例_20210124.docx", "no": "第一条", "text": "为了加强排污许可管理，规范企业事业单位和其他生产经营者排污行为，控制污染物排放，保护和改善生态环境，根据《中华人民共和国环境保护法》等有关法律，制定本条例。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第二条", "text": "依照法律规定实行排污许可管理的企业事业单位和其他生产经营者(以下称排污单位)，应当依照本条例规定申请取得排污许可证；未取得排污许可证的，不得排放污染物。 根据污染物产生量、排放量、对环境的影响程度等因素，对排污单位实行排污许可分类管理： (一)污染物产生量、排放量或者对环境的影响程度较大的排污单位，实行排污许可重点管理； (二)污染物产生量、排放量和对环境的影响程度都较小的排污单位，实行排污许可简化管理。 实行排污许可管理的排污单位范围、实施步骤和管理类别名录，由国务院生态环境主管部门拟订并报国务院批准后公布实施。制定实行排污许可管理的排污单位范围、实施步骤和管理类别名录，应当征求有关部门、行业协会、企业事业单位和社会公众等方面的意见。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第三条", "text": "国务院生态环境主管部门负责全国排污许可的统一监督管理。 设区的市级以上地方人民政府生态环境主管部门负责本行政区域排污许可的监督管理。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第四条", "text": "国务院生态环境主管部门应当加强全国排污许可证管理信息平台建设和管理，提高排污许可在线办理水平。 排污许可证审查与决定、信息公开等应当通过全国排污许可证管理信息平台办理。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第五条", "text": "设区的市级以上人民政府应当将排污许可管理工作所需经费列入本级预算。 第二章 申请与审批"}, {"law": "排污许可管理条例_20210124.docx", "no": "第六条", "text": "排污单位应当向其生产经营场所所在地设区的市级以上地方人民政府生态环境主管部门(以下称审批部门)申请取得排污许可证。 排污单位有两个以上生产经营场所排放污染物的，应当按照生产经营场所分别申请取得排污许可证。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第七条", "text": "申请取得排污许可证，可以通过全国排污许可证管理信息平台提交排污许可证申请表，也可以通过信函等方式提交。 排污许可证申请表应当包括下列事项： (一)排污单位名称、住所、法定代表人或者主要负责人、生产经营场所所在地、统一社会信用代码等信息； (二)建设项目环境影响报告书(表)批准文件或者环境影响登记表备案材料； (三)按照污染物排放口、主要生产设施或者车间、厂界申请的污染物排放种类、排放浓度和排放量，执行的污染物排放标准和重点污染物排放总量控制指标； (四)污染防治设施、污染物排放口位置和数量，污染物排放方式、排放去向、自行监测方案等信息； (五)主要生产设施、主要产品及产能、主要原辅材料、产生和排放污染物环节等信息，及其是否涉及商业秘密等不宜公开情形的情况说明。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第八条", "text": "有下列情形之一的，申请取得排污许可证还应当提交相应材料： (一)属于实行排污许可重点管理的，排污单位在提出申请前已通过全国排污许可证管理信息平台公开单位基本信息、拟申请许可事项的说明材料； (二)属于城镇和工业污水集中处理设施的，排污单位的纳污范围、管网布置、最终排放去向等说明材料； (三)属于排放重点污染物的新建、改建、扩建项目以及实施技术改造项目的，排污单位通过污染物排放量削减替代获得重点污染物排放总量控制指标的说明材料。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第九条", "text": "审批部门对收到的排污许可证申请，应当根据下列情况分别作出处理： (一)依法不需要申请取得排污许可证的，应当即时告知不需要申请取得排污许可证； (二)不属于本审批部门职权范围的，应当即时作出不予受理的决定，并告知排污单位向有审批权的生态环境主管部门申请； (三)申请材料存在可以当场更正的错误的，应当允许排污单位当场更正； (四)申请材料不齐全或者不符合法定形式的，应当当场或者在3日内出具告知单，一次性告知排污单位需要补正的全部材料；逾期不告知的，自收到申请材料之日起即视为受理； (五)属于本审批部门职权范围，申请材料齐全、符合法定形式，或者排污单位按照要求补正全部申请材料的，应当受理。 审批部门应当在全国排污许可证管理信息平台上公开受理或者不予受理排污许可证申请的决定，同时向排污单位出具加盖本审批部门专用印章和注明日期的书面凭证。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第十条", "text": "审批部门应当对排污单位提交的申请材料进行审查，并可以对排污单位的生产经营场所进行现场核查。 审批部门可以组织技术机构对排污许可证申请材料进行技术评估，并承担相应费用。 技术机构应当对其提出的技术评估意见负责，不得向排污单位收取任何费用。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第十一条", "text": "对具备下列条件的排污单位，颁发排污许可证： (一)依法取得建设项目环境影响报告书(表)批准文件，或者已经办理环境影响登记表备案手续； (二)污染物排放符合污染物排放标准要求，重点污染物排放符合排污许可证申请与核发技术规范、环境影响报告书(表)批准文件、重点污染物排放总量控制要求；其中，排污单位生产经营场所位于未达到国家环境质量标准的重点区域、流域的，还应当符合有关地方人民政府关于改善生态环境质量的特别要求； (三)采用污染防治设施可以达到许可排放浓度要求或者符合污染防治可行技术； (四)自行监测方案的监测点位、指标、频次等符合国家自行监测规范。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第十二条", "text": "对实行排污许可简化管理的排污单位，审批部门应当自受理申请之日起20日内作出审批决定；对符合条件的颁发排污许可证，对不符合条件的不予许可并书面说明理由。 对实行排污许可重点管理的排污单位，审批部门应当自受理申请之日起30日内作出审批决定；需要进行现场核查的，应当自受理申请之日起45日内作出审批决定；对符合条件的颁发排污许可证，对不符合条件的不予许可并书面说明理由。 审批部门应当通过全国排污许可证管理信息平台生成统一的排污许可证编号。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第十三条", "text": "排污许可证应当记载下列信息： (一)排污单位名称、住所、法定代表人或者主要负责人、生产经营场所所在地等； (二)排污许可证有效期限、发证机关、发证日期、证书编号和二维码等； (三)产生和排放污染物环节、污染防治设施等； (四)污染物排放口位置和数量、污染物排放方式和排放去向等； (五)污染物排放种类、许可排放浓度、许可排放量等； (六)污染防治设施运行和维护要求、污染物排放口规范化建设要求等； (七)特殊时段禁止或者限制污染物排放的要求； (八)自行监测、环境管理台账记录、排污许可证执行报告的内容和频次等要求； (九)排污单位环境信息公开要求； (十)存在大气污染物无组织排放情形时的无组织排放控制要求； (十一)法律法规规定排污单位应当遵守的其他控制污染物排放的要求。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第十四条", "text": "排污许可证有效期为5年。 排污许可证有效期届满，排污单位需要继续排放污染物的，应当于排污许可证有效期届满60日前向审批部门提出申请。审批部门应当自受理申请之日起20日内完成审查；对符合条件的予以延续，对不符合条件的不予延续并书面说明理由。 排污单位变更名称、住所、法定代表人或者主要负责人的，应当自变更之日起30日内，向审批部门申请办理排污许可证变更手续。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第十五条", "text": "在排污许可证有效期内，排污单位有下列情形之一的，应当重新申请取得排污许可证： (一)新建、改建、扩建排放污染物的项目； (二)生产经营场所、污染物排放口位置或者污染物排放方式、排放去向发生变化； (三)污染物排放口数量或者污染物排放种类、排放量、排放浓度增加。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第十六条", "text": "排污单位适用的污染物排放标准、重点污染物总量控制要求发生变化，需要对排污许可证进行变更的，审批部门可以依法对排污许可证相应事项进行变更。 第三章 排污管理"}, {"law": "排污许可管理条例_20210124.docx", "no": "第十七条", "text": "排污许可证是对排污单位进行生态环境监管的主要依据。 排污单位应当遵守排污许可证规定，按照生态环境管理要求运行和维护污染防治设施，建立环境管理制度，严格控制污染物排放。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第十八条", "text": "排污单位应当按照生态环境主管部门的规定建设规范化污染物排放口，并设置标志牌。 污染物排放口位置和数量、污染物排放方式和排放去向应当与排污许可证规定相符。 实施新建、改建、扩建项目和技术改造的排污单位，应当在建设污染防治设施的同时，建设规范化污染物排放口。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第十九条", "text": "排污单位应当按照排污许可证规定和有关标准规范，依法开展自行监测，并保存原始监测记录。原始监测记录保存期限不得少于5年。 排污单位应当对自行监测数据的真实性、准确性负责，不得篡改、伪造。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第二十条", "text": "实行排污许可重点管理的排污单位，应当依法安装、使用、维护污染物排放自动监测设备，并与生态环境主管部门的监控设备联网。 排污单位发现污染物排放自动监测设备传输数据异常的，应当及时报告生态环境主管部门，并进行检查、修复。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第二十一条", "text": "排污单位应当建立环境管理台账记录制度，按照排污许可证规定的格式、内容和频次，如实记录主要生产设施、污染防治设施运行情况以及污染物排放浓度、排放量。环境管理台账记录保存期限不得少于5年。 排污单位发现污染物排放超过污染物排放标准等异常情况时，应当立即采取措施消除、减轻危害后果，如实进行环境管理台账记录，并报告生态环境主管部门，说明原因。超过污染物排放标准等异常情况下的污染物排放计入排污单位的污染物排放量。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第二十二条", "text": "排污单位应当按照排污许可证规定的内容、频次和时间要求，向审批部门提交排污许可证执行报告，如实报告污染物排放行为、排放浓度、排放量等。 排污许可证有效期内发生停产的，排污单位应当在排污许可证执行报告中如实报告污染物排放变化情况并说明原因。 排污许可证执行报告中报告的污染物排放量可以作为年度生态环境统计、重点污染物排放总量考核、污染源排放清单编制的依据。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第二十三条", "text": "排污单位应当按照排污许可证规定，如实在全国排污许可证管理信息平台上公开污染物排放信息。 污染物排放信息应当包括污染物排放种类、排放浓度和排放量，以及污染防治设施的建设运行情况、排污许可证执行报告、自行监测数据等；其中，水污染物排入市政排水管网的，还应当包括污水接入市政排水管网位置、排放方式等信息。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第二十四条", "text": "污染物产生量、排放量和对环境的影响程度都很小的企业事业单位和其他生产经营者，应当填报排污登记表，不需要申请取得排污许可证。 需要填报排污登记表的企业事业单位和其他生产经营者范围名录，由国务院生态环境主管部门制定并公布。制定需要填报排污登记表的企业事业单位和其他生产经营者范围名录，应当征求有关部门、行业协会、企业事业单位和社会公众等方面的意见。 需要填报排污登记表的企业事业单位和其他生产经营者，应当在全国排污许可证管理信息平台上填报基本信息、污染物排放去向、执行的污染物排放标准以及采取的污染防治措施等信息；填报的信息发生变动的，应当自发生变动之日起20日内进行变更填报。 第四章 监督检查"}, {"law": "排污许可管理条例_20210124.docx", "no": "第二十五条", "text": "生态环境主管部门应当加强对排污许可的事中事后监管，将排污许可执法检查纳入生态环境执法年度计划，根据排污许可管理类别、排污单位信用记录和生态环境管理需要等因素，合理确定检查频次和检查方式。 生态环境主管部门应当在全国排污许可证管理信息平台上记录执法检查时间、内容、结果以及处罚决定，同时将处罚决定纳入国家有关信用信息系统向社会公布。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第二十六条", "text": "排污单位应当配合生态环境主管部门监督检查，如实反映情况，并按照要求提供排污许可证、环境管理台账记录、排污许可证执行报告、自行监测数据等相关材料。 禁止伪造、变造、转让排污许可证。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第二十七条", "text": "生态环境主管部门可以通过全国排污许可证管理信息平台监控排污单位的污染物排放情况，发现排污单位的污染物排放浓度超过许可排放浓度的，应当要求排污单位提供排污许可证、环境管理台账记录、排污许可证执行报告、自行监测数据等相关材料进行核查，必要时可以组织开展现场监测。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第二十八条", "text": "生态环境主管部门根据行政执法过程中收集的监测数据，以及排污单位的排污许可证、环境管理台账记录、排污许可证执行报告、自行监测数据等相关材料，对排污单位在规定周期内的污染物排放量，以及排污单位污染防治设施运行和维护是否符合排污许可证规定进行核查。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第二十九条", "text": "生态环境主管部门依法通过现场监测、排污单位污染物排放自动监测设备、全国排污许可证管理信息平台获得的排污单位污染物排放数据，可以作为判定污染物排放浓度是否超过许可排放浓度的证据。 排污单位自行监测数据与生态环境主管部门及其所属监测机构在行政执法过程中收集的监测数据不一致的，以生态环境主管部门及其所属监测机构收集的监测数据作为行政执法依据。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第三十条", "text": "国家鼓励排污单位采用污染防治可行技术。国务院生态环境主管部门制定并公布污染防治可行技术指南。 排污单位未采用污染防治可行技术的，生态环境主管部门应当根据排污许可证、环境管理台账记录、排污许可证执行报告、自行监测数据等相关材料，以及生态环境主管部门及其所属监测机构在行政执法过程中收集的监测数据，综合判断排污单位采用的污染防治技术能否稳定达到排污许可证规定；对不能稳定达到排污许可证规定的，应当提出整改要求，并可以增加检查频次。 制定污染防治可行技术指南，应当征求有关部门、行业协会、企业事业单位和社会公众等方面的意见。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第三十一条", "text": "任何单位和个人对排污单位违反本条例规定的行为，均有向生态环境主管部门举报的权利。 接到举报的生态环境主管部门应当依法处理，按照有关规定向举报人反馈处理结果，并为举报人保密。 第五章 法律责任"}, {"law": "排污许可管理条例_20210124.docx", "no": "第三十二条", "text": "违反本条例规定，生态环境主管部门在排污许可证审批或者监督管理中有下列行为之一的，由上级机关责令改正；对直接负责的主管人员和其他直接责任人员依法给予处分： (一)对符合法定条件的排污许可证申请不予受理或者不在法定期限内审批； (二)向不符合法定条件的排污单位颁发排污许可证； (三)违反审批权限审批排污许可证； (四)发现违法行为不予查处； (五)不依法履行监督管理职责的其他行为。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第三十三条", "text": "违反本条例规定，排污单位有下列行为之一的，由生态环境主管部门责令改正或者限制生产、停产整治，处20万元以上100万元以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭： (一)未取得排污许可证排放污染物； (二)排污许可证有效期届满未申请延续或者延续申请未经批准排放污染物； (三)被依法撤销、注销、吊销排污许可证后排放污染物； (四)依法应当重新申请取得排污许可证，未重新申请取得排污许可证排放污染物。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第三十四条", "text": "违反本条例规定，排污单位有下列行为之一的，由生态环境主管部门责令改正或者限制生产、停产整治，处20万元以上100万元以下的罚款；情节严重的，吊销排污许可证，报经有批准权的人民政府批准，责令停业、关闭： (一)超过许可排放浓度、许可排放量排放污染物； (二)通过暗管、渗井、渗坑、灌注或者篡改、伪造监测数据，或者不正常运行污染防治设施等逃避监管的方式违法排放污染物。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第三十五条", "text": "违反本条例规定，排污单位有下列行为之一的，由生态环境主管部门责令改正，处5万元以上20万元以下的罚款；情节严重的，处20万元以上100万元以下的罚款，责令限制生产、停产整治： (一)未按照排污许可证规定控制大气污染物无组织排放； (二)特殊时段未按照排污许可证规定停止或者限制排放污染物。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第三十六条", "text": "违反本条例规定，排污单位有下列行为之一的，由生态环境主管部门责令改正，处2万元以上20万元以下的罚款；拒不改正的，责令停产整治： (一)污染物排放口位置或者数量不符合排污许可证规定； (二)污染物排放方式或者排放去向不符合排污许可证规定； (三)损毁或者擅自移动、改变污染物排放自动监测设备； (四)未按照排污许可证规定安装、使用污染物排放自动监测设备并与生态环境主管部门的监控设备联网，或者未保证污染物排放自动监测设备正常运行； (五)未按照排污许可证规定制定自行监测方案并开展自行监测； (六)未按照排污许可证规定保存原始监测记录； (七)未按照排污许可证规定公开或者不如实公开污染物排放信息； (八)发现污染物排放自动监测设备传输数据异常或者污染物排放超过污染物排放标准等异常情况不报告； (九)违反法律法规规定的其他控制污染物排放要求的行为。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第三十七条", "text": "违反本条例规定，排污单位有下列行为之一的，由生态环境主管部门责令改正，处每次5千元以上2万元以下的罚款；法律另有规定的，从其规定： (一)未建立环境管理台账记录制度，或者未按照排污许可证规定记录； (二)未如实记录主要生产设施及污染防治设施运行情况或者污染物排放浓度、排放量； (三)未按照排污许可证规定提交排污许可证执行报告； (四)未如实报告污染物排放行为或者污染物排放浓度、排放量。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第三十八条", "text": "排污单位违反本条例规定排放污染物，受到罚款处罚，被责令改正的，生态环境主管部门应当组织复查，发现其继续实施该违法行为或者拒绝、阻挠复查的，依照《中华人民共和国环境保护法》的规定按日连续处罚。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第三十九条", "text": "排污单位拒不配合生态环境主管部门监督检查，或者在接受监督检查时弄虚作假的，由生态环境主管部门责令改正，处2万元以上20万元以下的罚款。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第四十条", "text": "排污单位以欺骗、贿赂等不正当手段申请取得排污许可证的，由审批部门依法撤销其排污许可证，处20万元以上50万元以下的罚款，3年内不得再次申请排污许可证。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第四十一条", "text": "违反本条例规定，伪造、变造、转让排污许可证的，由生态环境主管部门没收相关证件或者吊销排污许可证，处10万元以上30万元以下的罚款，3年内不得再次申请排污许可证。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第四十二条", "text": "违反本条例规定，接受审批部门委托的排污许可技术机构弄虚作假的，由审批部门解除委托关系，将相关信息记入其信用记录，在全国排污许可证管理信息平台上公布，同时纳入国家有关信用信息系统向社会公布；情节严重的，禁止从事排污许可技术服务。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第四十三条", "text": "需要填报排污登记表的企业事业单位和其他生产经营者，未依照本条例规定填报排污信息的，由生态环境主管部门责令改正，可以处5万元以下的罚款。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第四十四条", "text": "排污单位有下列行为之一，尚不构成犯罪的，除依照本条例规定予以处罚外，对其直接负责的主管人员和其他直接责任人员，依照《中华人民共和国环境保护法》的规定处以拘留： (一)未取得排污许可证排放污染物，被责令停止排污，拒不执行； (二)通过暗管、渗井、渗坑、灌注或者篡改、伪造监测数据，或者不正常运行污染防治设施等逃避监管的方式违法排放污染物。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第四十五条", "text": "违反本条例规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。 第六章 附 则"}, {"law": "排污许可管理条例_20210124.docx", "no": "第四十六条", "text": "本条例施行前已经实际排放污染物的排污单位，不符合本条例规定条件的，应当在国务院生态环境主管部门规定的期限内进行整改，达到本条例规定的条件并申请取得排污许可证；逾期未取得排污许可证的，不得继续排放污染物。整改期限内，生态环境主管部门应当向其下达排污限期整改通知书，明确整改内容、整改期限等要求。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第四十七条", "text": "排污许可证申请表、环境管理台账记录、排污许可证执行报告等文件的格式和内容要求，以及排污许可证申请与核发技术规范等，由国务院生态环境主管部门制定。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第四十八条", "text": "企业事业单位和其他生产经营者涉及国家秘密的，其排污许可、监督管理等应当遵守保密法律法规的规定。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第四十九条", "text": "飞机、船舶、机动车、列车等移动污染源的污染物排放管理，依照相关法律法规的规定执行。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第五十条", "text": "排污单位应当遵守安全生产规定，按照安全生产管理要求运行和维护污染防治设施，建立安全生产管理制度。 在运行和维护污染防治设施过程中违反安全生产规定，发生安全生产事故的，对负有责任的排污单位依照《中华人民共和国安全生产法》的有关规定予以处罚。"}, {"law": "排污许可管理条例_20210124.docx", "no": "第五十一条", "text": "本条例自2021年3月1日起施行。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第一条", "text": "为了加强易制毒化学品管理，规范易制毒化学品的生产、经营、购买、运输和进口、出口行为，防止易制毒化学品被用于制造毒品，维护经济和社会秩序，制定本条例。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第二条", "text": "国家对易制毒化学品的生产、经营、购买、运输和进口、出口实行分类管理和许可制度。 易制毒化学品分为三类。第一类是可以用于制毒的主要原料，第二类、第三类是可以用于制毒的化学配剂。易制毒化学品的具体分类和品种，由本条例附表列示。 易制毒化学品的分类和品种需要调整的，由国务院公安部门会同国务院药品监督管理部门、安全生产监督管理部门、商务主管部门、卫生主管部门和海关总署提出方案，报国务院批准。 省、自治区、直辖市人民政府认为有必要在本行政区域内调整分类或者增加本条例规定以外的品种的，应当向国务院公安部门提出，由国务院公安部门会同国务院有关行政主管部门提出方案，报国务院批准。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第三条", "text": "国务院公安部门、药品监督管理部门、安全生产监督管理部门、商务主管部门、卫生主管部门、海关总署、价格主管部门、铁路主管部门、交通主管部门、市场监督管理部门、生态环境主管部门在各自的职责范围内，负责全国的易制毒化学品有关管理工作；县级以上地方各级人民政府有关行政主管部门在各自的职责范围内，负责本行政区域内的易制毒化学品有关管理工作。 县级以上地方各级人民政府应当加强对易制毒化学品管理工作的领导，及时协调解决易制毒化学品管理工作中的问题。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第四条", "text": "易制毒化学品的产品包装和使用说明书，应当标明产品的名称(含学名和通用名)、化学分子式和成分。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第五条", "text": "易制毒化学品的生产、经营、购买、运输和进口、出口，除应当遵守本条例的规定外，属于药品和危险化学品的，还应当遵守法律、其他行政法规对药品和危险化学品的有关规定。 禁止走私或者非法生产、经营、购买、转让、运输易制毒化学品。 禁止使用现金或者实物进行易制毒化学品交易。但是，个人合法购买第一类中的药品类易制毒化学品药品制剂和第三类易制毒化学品的除外。 生产、经营、购买、运输和进口、出口易制毒化学品的单位，应当建立单位内部易制毒化学品管理制度。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第六条", "text": "国家鼓励向公安机关等有关行政主管部门举报涉及易制毒化学品的违法行为。接到举报的部门应当为举报者保密。对举报属实的，县级以上人民政府及有关行政主管部门应当给予奖励。 第二章 生产、经营管理"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第七条", "text": "申请生产第一类易制毒化学品，应当具备下列条件，并经本条例"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第八条", "text": "规定的行政主管部门审批，取得生产许可证后，方可进行生产： (一)属依法登记的化工产品生产企业或者药品生产企业； (二)有符合国家标准的生产设备、仓储设施和污染物处理设施； (三)有严格的安全生产管理制度和环境突发事件应急预案； (四)企业法定代表人和技术、管理人员具有安全生产和易制毒化学品的有关知识，无毒品犯罪记录； (五)法律、法规、规章规定的其他条件。 申请生产第一类中的药品类易制毒化学品，还应当在仓储场所等重点区域设置电视监控设施以及与公安机关联网的报警装置。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第八条", "text": "申请生产第一类中的药品类易制毒化学品的，由省、自治区、直辖市人民政府药品监督管理部门审批；申请生产第一类中的非药品类易制毒化学品的，由省、自治区、直辖市人民政府安全生产监督管理部门审批。 前款规定的行政主管部门应当自收到申请之日起60日内，对申请人提交的申请材料进行审查。对符合规定的，发给生产许可证，或者在企业已经取得的有关生产许可证件上标注；不予许可的，应当书面说明理由。 审查第一类易制毒化学品生产许可申请材料时，根据需要，可以进行实地核查和专家评审。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第九条", "text": "申请经营第一类易制毒化学品，应当具备下列条件，并经本条例"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十条", "text": "规定的行政主管部门审批，取得经营许可证后，方可进行经营： (一)属依法登记的化工产品经营企业或者药品经营企业； (二)有符合国家规定的经营场所，需要储存、保管易制毒化学品的，还应当有符合国家技术标准的仓储设施； (三)有易制毒化学品的经营管理制度和健全的销售网络； (四)企业法定代表人和销售、管理人员具有易制毒化学品的有关知识，无毒品犯罪记录； (五)法律、法规、规章规定的其他条件。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十条", "text": "申请经营第一类中的药品类易制毒化学品的，由省、自治区、直辖市人民政府药品监督管理部门审批；申请经营第一类中的非药品类易制毒化学品的，由省、自治区、直辖市人民政府安全生产监督管理部门审批。 前款规定的行政主管部门应当自收到申请之日起30日内，对申请人提交的申请材料进行审查。对符合规定的，发给经营许可证，或者在企业已经取得的有关经营许可证件上标注；不予许可的，应当书面说明理由。 审查第一类易制毒化学品经营许可申请材料时，根据需要，可以进行实地核查。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十一条", "text": "取得第一类易制毒化学品生产许可或者依照本条例"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十三条", "text": "第一款规定已经履行第二类、第三类易制毒化学品备案手续的生产企业，可以经销自产的易制毒化学品。但是，在厂外设立销售网点经销第一类易制毒化学品的，应当依照本条例的规定取得经营许可。 第一类中的药品类易制毒化学品药品单方制剂，由麻醉药品定点经营企业经销，且不得零售。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十二条", "text": "取得第一类易制毒化学品生产、经营许可的企业，应当凭生产、经营许可证到市场监督管理部门办理经营范围变更登记。未经变更登记，不得进行第一类易制毒化学品的生产、经营。 第一类易制毒化学品生产、经营许可证被依法吊销的，行政主管部门应当自作出吊销决定之日起5日内通知市场监督管理部门；被吊销许可证的企业，应当及时到市场监督管理部门办理经营范围变更或者企业注销登记。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十三条", "text": "生产第二类、第三类易制毒化学品的，应当自生产之日起30日内，将生产的品种、数量等情况，向所在地的设区的市级人民政府安全生产监督管理部门备案。 经营第二类易制毒化学品的，应当自经营之日起30日内，将经营的品种、数量、主要流向等情况，向所在地的设区的市级人民政府安全生产监督管理部门备案；经营第三类易制毒化学品的，应当自经营之日起30日内，将经营的品种、数量、主要流向等情况，向所在地的县级人民政府安全生产监督管理部门备案。 前两款规定的行政主管部门应当于收到备案材料的当日发给备案证明。 第三章 购买管理"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十四条", "text": "申请购买第一类易制毒化学品，应当提交下列证件，经本条例"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十五条", "text": "规定的行政主管部门审批，取得购买许可证： (一)经营企业提交企业营业执照和合法使用需要证明； (二)其他组织提交登记证书(成立批准文件)和合法使用需要证明。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十五条", "text": "申请购买第一类中的药品类易制毒化学品的，由所在地的省、自治区、直辖市人民政府药品监督管理部门审批；申请购买第一类中的非药品类易制毒化学品的，由所在地的省、自治区、直辖市人民政府公安机关审批。 前款规定的行政主管部门应当自收到申请之日起10日内，对申请人提交的申请材料和证件进行审查。对符合规定的，发给购买许可证；不予许可的，应当书面说明理由。 审查第一类易制毒化学品购买许可申请材料时，根据需要，可以进行实地核查。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十六条", "text": "持有麻醉药品、第一类精神药品购买印鉴卡的医疗机构购买第一类中的药品类易制毒化学品的，无须申请第一类易制毒化学品购买许可证。 个人不得购买第一类、第二类易制毒化学品。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十七条", "text": "购买第二类、第三类易制毒化学品的，应当在购买前将所需购买的品种、数量，向所在地的县级人民政府公安机关备案。个人自用购买少量高锰酸钾的，无须备案。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十八条", "text": "经营单位销售第一类易制毒化学品时，应当查验购买许可证和经办人的身份证明。对委托代购的，还应当查验购买人持有的委托文书。 经营单位在查验无误、留存上述证明材料的复印件后，方可出售第一类易制毒化学品；发现可疑情况的，应当立即向当地公安机关报告。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第十九条", "text": "经营单位应当建立易制毒化学品销售台账，如实记录销售的品种、数量、日期、购买方等情况。销售台账和证明材料复印件应当保存2年备查。 第一类易制毒化学品的销售情况，应当自销售之日起5日内报当地公安机关备案；第一类易制毒化学品的使用单位，应当建立使用台账，并保存2年备查。 第二类、第三类易制毒化学品的销售情况，应当自销售之日起30日内报当地公安机关备案。 第四章 运输管理"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第二十条", "text": "跨设区的市级行政区域(直辖市为跨市界)或者在国务院公安部门确定的禁毒形势严峻的重点地区跨县级行政区域运输第一类易制毒化学品的，由运出地的设区的市级人民政府公安机关审批；运输第二类易制毒化学品的，由运出地的县级人民政府公安机关审批。经审批取得易制毒化学品运输许可证后，方可运输。 运输第三类易制毒化学品的，应当在运输前向运出地的县级人民政府公安机关备案。公安机关应当于收到备案材料的当日发给备案证明。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第二十一条", "text": "申请易制毒化学品运输许可，应当提交易制毒化学品的购销合同，货主是企业的，应当提交营业执照；货主是其他组织的，应当提交登记证书(成立批准文件)；货主是个人的，应当提交其个人身份证明。经办人还应当提交本人的身份证明。 公安机关应当自收到第一类易制毒化学品运输许可申请之日起10日内，收到第二类易制毒化学品运输许可申请之日起3日内，对申请人提交的申请材料进行审查。对符合规定的，发给运输许可证；不予许可的，应当书面说明理由。 审查第一类易制毒化学品运输许可申请材料时，根据需要，可以进行实地核查。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第二十二条", "text": "对许可运输第一类易制毒化学品的，发给一次有效的运输许可证。 对许可运输第二类易制毒化学品的，发给3个月有效的运输许可证；6个月内运输安全状况良好的，发给12个月有效的运输许可证。 易制毒化学品运输许可证应当载明拟运输的易制毒化学品的品种、数量、运入地、货主及收货人、承运人情况以及运输许可证种类。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第二十三条", "text": "运输供教学、科研使用的100克以下的麻黄素样品和供医疗机构制剂配方使用的小包装麻黄素以及医疗机构或者麻醉药品经营企业购买麻黄素片剂6万片以下、注射剂1.5万支以下，货主或者承运人持有依法取得的购买许可证明或者麻醉药品调拨单的，无须申请易制毒化学品运输许可。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第二十四条", "text": "接受货主委托运输的，承运人应当查验货主提供的运输许可证或者备案证明，并查验所运货物与运输许可证或者备案证明载明的易制毒化学品品种等情况是否相符；不相符的，不得承运。 运输易制毒化学品，运输人员应当自启运起全程携带运输许可证或者备案证明。公安机关应当在易制毒化学品的运输过程中进行检查。 运输易制毒化学品，应当遵守国家有关货物运输的规定。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第二十五条", "text": "因治疗疾病需要，患者、患者近亲属或者患者委托的人凭医疗机构出具的医疗诊断书和本人的身份证明，可以随身携带第一类中的药品类易制毒化学品药品制剂，但是不得超过医用单张处方的最大剂量。 医用单张处方最大剂量，由国务院卫生主管部门规定、公布。 第五章 进口、出口管理"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第二十六条", "text": "申请进口或者出口易制毒化学品，应当提交下列材料，经国务院商务主管部门或者其委托的省、自治区、直辖市人民政府商务主管部门审批，取得进口或者出口许可证后，方可从事进口、出口活动： (一)对外贸易经营者备案登记证明复印件； (二)营业执照副本； (三)易制毒化学品生产、经营、购买许可证或者备案证明； (四)进口或者出口合同(协议)副本； (五)经办人的身份证明。 申请易制毒化学品出口许可的，还应当提交进口方政府主管部门出具的合法使用易制毒化学品的证明或者进口方合法使用的保证文件。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第二十七条", "text": "受理易制毒化学品进口、出口申请的商务主管部门应当自收到申请材料之日起20日内，对申请材料进行审查，必要时可以进行实地核查。对符合规定的，发给进口或者出口许可证；不予许可的，应当书面说明理由。 对进口第一类中的药品类易制毒化学品的，有关的商务主管部门在作出许可决定前，应当征得国务院药品监督管理部门的同意。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第二十八条", "text": "麻黄素等属于重点监控物品范围的易制毒化学品，由国务院商务主管部门会同国务院有关部门核定的企业进口、出口。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第二十九条", "text": "国家对易制毒化学品的进口、出口实行国际核查制度。易制毒化学品国际核查目录及核查的具体办法，由国务院商务主管部门会同国务院公安部门规定、公布。 国际核查所用时间不计算在许可期限之内。 对向毒品制造、贩运情形严重的国家或者地区出口易制毒化学品以及本条例规定品种以外的化学品的，可以在国际核查措施以外实施其他管制措施，具体办法由国务院商务主管部门会同国务院公安部门、海关总署等有关部门规定、公布。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第三十条", "text": "进口、出口或者过境、转运、通运易制毒化学品的，应当如实向海关申报，并提交进口或者出口许可证。海关凭许可证办理通关手续。 易制毒化学品在境外与保税区、出口加工区等海关特殊监管区域、保税场所之间进出的，适用前款规定。 易制毒化学品在境内与保税区、出口加工区等海关特殊监管区域、保税场所之间进出的，或者在上述海关特殊监管区域、保税场所之间进出的，无须申请易制毒化学品进口或者出口许可证。 进口第一类中的药品类易制毒化学品，还应当提交药品监督管理部门出具的进口药品通关单。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第三十一条", "text": "进出境人员随身携带第一类中的药品类易制毒化学品药品制剂和高锰酸钾，应当以自用且数量合理为限，并接受海关监管。 进出境人员不得随身携带前款规定以外的易制毒化学品。 第六章 监督检查"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第三十二条", "text": "县级以上人民政府公安机关、负责药品监督管理的部门、安全生产监督管理部门、商务主管部门、卫生主管部门、价格主管部门、铁路主管部门、交通主管部门、市场监督管理部门、生态环境主管部门和海关，应当依照本条例和有关法律、行政法规的规定，在各自的职责范围内，加强对易制毒化学品生产、经营、购买、运输、价格以及进口、出口的监督检查；对非法生产、经营、购买、运输易制毒化学品，或者走私易制毒化学品的行为，依法予以查处。 前款规定的行政主管部门在进行易制毒化学品监督检查时，可以依法查看现场、查阅和复制有关资料、记录有关情况、扣押相关的证据材料和违法物品；必要时，可以临时查封有关场所。 被检查的单位或者个人应当如实提供有关情况和材料、物品，不得拒绝或者隐匿。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第三十三条", "text": "对依法收缴、查获的易制毒化学品，应当在省、自治区、直辖市或者设区的市级人民政府公安机关、海关或者生态环境主管部门的监督下，区别易制毒化学品的不同情况进行保管、回收，或者依照环境保护法律、行政法规的有关规定，由有资质的单位在生态环境主管部门的监督下销毁。其中，对收缴、查获的第一类中的药品类易制毒化学品，一律销毁。 易制毒化学品违法单位或者个人无力提供保管、回收或者销毁费用的，保管、回收或者销毁的费用在回收所得中开支，或者在有关行政主管部门的禁毒经费中列支。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第三十四条", "text": "易制毒化学品丢失、被盗、被抢的，发案单位应当立即向当地公安机关报告，并同时报告当地的县级人民政府负责药品监督管理的部门、安全生产监督管理部门、商务主管部门或者卫生主管部门。接到报案的公安机关应当及时立案查处，并向上级公安机关报告；有关行政主管部门应当逐级上报并配合公安机关的查处。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第三十五条", "text": "有关行政主管部门应当将易制毒化学品许可以及依法吊销许可的情况通报有关公安机关和市场监督管理部门；市场监督管理部门应当将生产、经营易制毒化学品企业依法变更或者注销登记的情况通报有关公安机关和行政主管部门。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第三十六条", "text": "生产、经营、购买、运输或者进口、出口易制毒化学品的单位，应当于每年3月31日前向许可或者备案的行政主管部门和公安机关报告本单位上年度易制毒化学品的生产、经营、购买、运输或者进口、出口情况；有条件的生产、经营、购买、运输或者进口、出口单位，可以与有关行政主管部门建立计算机联网，及时通报有关经营情况。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第三十七条", "text": "县级以上人民政府有关行政主管部门应当加强协调合作，建立易制毒化学品管理情况、监督检查情况以及案件处理情况的通报、交流机制。 第七章 法律责任"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第三十八条", "text": "违反本条例规定，未经许可或者备案擅自生产、经营、购买、运输易制毒化学品，伪造申请材料骗取易制毒化学品生产、经营、购买或者运输许可证，使用他人的或者伪造、变造、失效的许可证生产、经营、购买、运输易制毒化学品的，由公安机关没收非法生产、经营、购买或者运输的易制毒化学品、用于非法生产易制毒化学品的原料以及非法生产、经营、购买或者运输易制毒化学品的设备、工具，处非法生产、经营、购买或者运输的易制毒化学品货值10倍以上20倍以下的罚款，货值的20倍不足1万元的，按1万元罚款；有违法所得的，没收违法所得；有营业执照的，由市场监督管理部门吊销营业执照；构成犯罪的，依法追究刑事责任。 对有前款规定违法行为的单位或者个人，有关行政主管部门可以自作出行政处罚决定之日起3年内，停止受理其易制毒化学品生产、经营、购买、运输或者进口、出口许可申请。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第三十九条", "text": "违反本条例规定，走私易制毒化学品的，由海关没收走私的易制毒化学品；有违法所得的，没收违法所得，并依照海关法律、行政法规给予行政处罚；构成犯罪的，依法追究刑事责任。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第四十条", "text": "违反本条例规定，有下列行为之一的，由负有监督管理职责的行政主管部门给予警告，责令限期改正，处1万元以上5万元以下的罚款；对违反规定生产、经营、购买的易制毒化学品可以予以没收；逾期不改正的，责令限期停产停业整顿；逾期整顿不合格的，吊销相应的许可证： (一)易制毒化学品生产、经营、购买、运输或者进口、出口单位未按规定建立安全管理制度的； (二)将许可证或者备案证明转借他人使用的； (三)超出许可的品种、数量生产、经营、购买易制毒化学品的； (四)生产、经营、购买单位不记录或者不如实记录交易情况、不按规定保存交易记录或者不如实、不及时向公安机关和有关行政主管部门备案销售情况的； (五)易制毒化学品丢失、被盗、被抢后未及时报告，造成严重后果的； (六)除个人合法购买第一类中的药品类易制毒化学品药品制剂以及第三类易制毒化学品外，使用现金或者实物进行易制毒化学品交易的； (七)易制毒化学品的产品包装和使用说明书不符合本条例规定要求的； (八)生产、经营易制毒化学品的单位不如实或者不按时向有关行政主管部门和公安机关报告年度生产、经销和库存等情况的。 企业的易制毒化学品生产经营许可被依法吊销后，未及时到市场监督管理部门办理经营范围变更或者企业注销登记的，依照前款规定，对易制毒化学品予以没收，并处罚款。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第四十一条", "text": "运输的易制毒化学品与易制毒化学品运输许可证或者备案证明载明的品种、数量、运入地、货主及收货人、承运人等情况不符，运输许可证种类不当，或者运输人员未全程携带运输许可证或者备案证明的，由公安机关责令停运整改，处5000元以上5万元以下的罚款；有危险物品运输资质的，运输主管部门可以依法吊销其运输资质。 个人携带易制毒化学品不符合品种、数量规定的，没收易制毒化学品，处1000元以上5000元以下的罚款。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第四十二条", "text": "生产、经营、购买、运输或者进口、出口易制毒化学品的单位或者个人拒不接受有关行政主管部门监督检查的，由负有监督管理职责的行政主管部门责令改正，对直接负责的主管人员以及其他直接责任人员给予警告；情节严重的，对单位处1万元以上5万元以下的罚款，对直接负责的主管人员以及其他直接责任人员处1000元以上5000元以下的罚款；有违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第四十三条", "text": "易制毒化学品行政主管部门工作人员在管理工作中有应当许可而不许可、不应当许可而滥许可，不依法受理备案，以及其他滥用职权、玩忽职守、徇私舞弊行为的，依法给予行政处分；构成犯罪的，依法追究刑事责任。 第八章 附则"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第四十四条", "text": "易制毒化学品生产、经营、购买、运输和进口、出口许可证，由国务院有关行政主管部门根据各自的职责规定式样并监制。"}, {"law": "易制毒化学品管理条例_20180918.docx", "no": "第四十五条", "text": "本条例自2005年11月1日起施行。 本条例施行前已经从事易制毒化学品生产、经营、购买、运输或者进口、出口业务的，应当自本条例施行之日起6个月内，依照本条例的规定重新申请许可。 附表 易制毒化学品的分类和品种目录 第一类 1．1—苯基—2—丙酮 2．3，4—亚甲基二氧苯基—2—丙酮 3．胡椒醛 4．黄樟素 5．黄樟油 6．异黄樟素 7．N—乙酰邻氨基苯酸 8．邻氨基苯甲酸 9．麦角酸* 10．麦角胺* 11．麦角新碱* 12．麻黄素、伪麻黄素、消旋麻黄素、去甲麻黄素、甲基麻黄素、麻黄浸膏、麻黄浸膏粉等麻黄素类物质* 第二类 1．苯乙酸 2．醋酸酐 3．三氯甲烷 4．乙醚 5．哌啶 第三类 1．甲苯 2．丙酮 3．甲基乙基酮 4．高锰酸钾 5．硫酸 6．盐酸 说明： 一、第一类、第二类所列物质可能存在的盐类，也纳入管制。 二、带有*标记的品种为第一类中的药品类易制毒化学品，第一类中的药品类易制毒化学品包括原料药及其单方制剂。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第一条", "text": "为加强易制毒化学品管理，规范购销和运输易制毒化学品行为，防 止易制毒化学品被用于制造毒品，维护经济和社会秩序，根据《易制毒化学品管 理条例》，制定本办法。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第二条", "text": "公安部是全国易制毒化学品购销、运输管理和监督检查的主管部 门。 县级以上地方人民政府公安机关负责本辖区内易制毒化学品购销、运输管理 和监督检查工作。 各省、自治区、直辖市和设区的市级人民政府公安机关禁毒部门应当设立易 制毒化学品管理专门机构，县级人民政府公安机关应当设专门人员，负责易制毒 化学品的购买、运输许可或者备案和监督检查工作。 第二章 购销管理"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第三条", "text": "购买第一类中的非药品类易制毒化学品的，应当向所在地省级人民 政府公安机关申请购买许可证；购买第二类、第三类易制毒化学品的，应当向所 在地县级人民政府公安机关备案。取得购买许可证或者购买备案证明后，方可购 买易制毒化学品。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第四条", "text": "个人不得购买第一类易制毒化学品和第二类易制毒化学品。 禁止使用现金或者实物进行易制毒化学品交易，但是个人合法购买第一类中 的药品类易制毒化学品药品制剂和第三类易制毒化学品的除外。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第五条", "text": "申请购买第一类中的非药品类易制毒化学品和第二类、第三类易制 毒化学品的，应当提交下列申请材料： （一）经营企业的营业执照（副本和复印件），其他组织的登记证书或者成 立批准文件（原件和复印件），或者个人的身份证明（原件和复印件）； （二）合法使用需要证明（原件）。 合法使用需要证明由购买单位或者个人出具，注明拟购买易制毒化学品的品 种、数量和用途，并加盖购买单位印章或者个人签名。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第六条", "text": "申请购买第一类中的非药品类易制毒化学品的，由申请人所在地的 省级人民政府公安机关审批。负责审批的公安机关应当自收到申请之日起10日 内，对申请人提交的申请材料进行审查。对符合规定的，发给购买许可证；不予 许可的，应当书面说明理由。 负责审批的公安机关对购买许可证的申请能够当场予以办理的，应当当场办 理；对材料不齐备需要补充的，应当1次告知申请人需补充的内容；对提供材料不 符合规定不予受理的，应当书面说明理由。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第七条", "text": "公安机关审查第一类易制毒化学品购买许可申请材料时，根据需 要，可以进行实地核查。遇有下列情形之一的，应当进行实地核查： （一）购买单位第一次申请的； （二）购买单位提供的申请材料不符合要求的； （三）对购买单位提供的申请材料有疑问的。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第八条", "text": "购买第二类、第三类易制毒化学品的，应当在购买前将所需购买的 品种、数量，向所在地的县级人民政府公安机关备案。公安机关受理备案后，应 当于当日出具购买备案证明。 自用一次性购买5公斤以下且年用量50公斤以下高锰酸钾的，无须备案。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第九条", "text": "易制毒化学品购买许可证一次使用有效，有效期1个月。 易制毒化学品购买备案证明一次使用有效，有效期1个月。对备案后1年内无 违规行为的单位，可以发给多次使用有效的备案证明，有效期6个月。 对个人购买的，只办理一次使用有效的备案证明。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第十条", "text": "经营单位销售第一类易制毒化学品时，应当查验购买许可证和经办 人的身份证明。对委托代购的，还应当查验购买人持有的委托文书。 委托文书应当载明委托人与被委托人双方情况、委托购买的品种、数量等事 项。 经营单位在查验无误、留存前两款规定的证明材料的复印件后，方可出售第 一类易制毒化学品；发现可疑情况的，应当立即向当地公安机关报告。 经营单位在查验购买方提供的许可证和身份证明时，对不能确定其真实性 的，可以请当地公安机关协助核查。公安机关应当当场予以核查，对于不能当场 核实的，应当于3日内将核查结果告知经营单位。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第十一条", "text": "经营单位应当建立易制毒化学品销售台账，如实记录销售的品 种、数量、日期、购买方等情况。经营单位销售易制毒化学品时，还应当留存购 买许可证或者购买备案证明以及购买经办人的身份证明的复印件。 销售台账和证明材料复印件应当保存2年备查。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第十二条", "text": "经营单位应当将第一类易制毒化学品的销售情况于销售之日起5日 内报当地县级人民政府公安机关备案，将第二类、第三类易制毒化学品的销售情 况于30日内报当地县级人民政府公安机关备案。 备案的销售情况应当包括销售单位、地址，销售易制毒化学品的种类、数量 等，并同时提交留存的购买方的证明材料复印件。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第十三条", "text": "第一类易制毒化学品的使用单位，应当建立使用台账，如实记录 购进易制毒化学品的种类、数量、使用情况和库存等，并保存2年备查。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第十四条", "text": "购买、销售和使用易制毒化学品的单位，应当在易制毒化学品的 出入库登记、易制毒化学品管理岗位责任分工以及企业从业人员的易制毒化学品 知识培训等方面建立单位内部管理制度。 第三章 运输管理"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第十五条", "text": "运输易制毒化学品，有下列情形之一的，应当申请运输许可证或 者进行备案： （一）跨设区的市级行政区域（直辖市为跨市界）运输的； （二）在禁毒形势严峻的重点地区跨县级行政区域运输的。禁毒形势严峻的 重点地区由公安部确定和调整，名单另行公布。 运输第一类易制毒化学品的，应当向运出地的设区的市级人民政府公安机关 申请运输许可证。 运输第二类易制毒化学品的，应当向运出地县级人民政府公安机关申请运输 许可证。 运输第三类易制毒化学品的，应当向运出地县级人民政府公安机关备案。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第十六条", "text": "运输供教学、科研使用的100克以下的麻黄素样品和供医疗机构制 剂配方使用的小包装麻黄素以及医疗机构或者麻醉药品经营企业购买麻黄素片剂6 万片以下、注射剂1.5万支以下，货主或者承运人持有依法取得的购买许可证明或 者麻醉药品调拨单的，无须申请易制毒化学品运输许可。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第十七条", "text": "因治疗疾病需要，患者、患者近亲属或者患者委托的人凭医疗机 构出具的医疗诊断书和本人的身份证明，可以随身携带第一类中的药品类易制毒 化学品药品制剂，但是不得超过医用单张处方的最大剂量。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第十八条", "text": "运输易制毒化学品，应当由货主向公安机关申请运输许可证或者 进行备案。 申请易制毒化学品运输许可证或者进行备案，应当提交下列材料： （一）经营企业的营业执照（副本和复印件），其他组织的登记证书或者成 立批准文件（原件和复印件），个人的身份证明（原件和复印件）； （二）易制毒化学品购销合同（复印件）； （三）经办人的身份证明（原件和复印件）。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第十九条", "text": "负责审批的公安机关应当自收到第一类易制毒化学品运输许可申 请之日起10日内，收到第二类易制毒化学品运输许可申请之日起3日内，对申请人 提交的申请材料进行审查。对符合规定的，发给运输许可证；不予许可的，应当 书面说明理由。 负责审批的公安机关对运输许可申请能够当场予以办理的，应当当场办理； 对材料不齐备需要补充的，应当一次告知申请人需补充的内容；对提供材料不符 合规定不予受理的，应当书面说明理由。 运输第三类易制毒化学品的，应当在运输前向运出地的县级人民政府公安机 关备案。公安机关应当在收到备案材料的当日发给备案证明。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第二十条", "text": "负责审批的公安机关对申请人提交的申请材料，应当核查其真实 性和有效性，其中查验购销合同时，可以要求申请人出示购买许可证或者备案证 明，核对是否相符；对营业执照和登记证书（或者成立批准文件），应当核查其 生产范围、经营范围、使用范围、证照有效期等内容。 公安机关审查第一类易制毒化学品运输许可申请材料时，根据需要，可以进 行实地核查。遇有下列情形之一的，应当进行实地核查： （一）申请人第一次申请的； （二）提供的申请材料不符合要求的； （三）对提供的申请材料有疑问的。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第二十一条", "text": "对许可运输第一类易制毒化学品的，发给一次有效的运输许可 证，有效期1个月。 对许可运输第二类易制毒化学品的，发给3个月多次使用有效的运输许可证； 对第三类易制毒化学品运输备案的，发给3个月多次使用有效的备案证明；对于领 取运输许可证或者运输备案证明后6个月内按照规定运输并保证运输安全的，可以 发给有效期12个月的运输许可证或者运输备案证明。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第二十二条", "text": "承运人接受货主委托运输，对应当凭证运输的，应当查验货主 提供的运输许可证或者备案证明，并查验所运货物与运输许可证或者备案证明载 明的易制毒化学品的品种、数量等情况是否相符；不相符的，不得承运。 承运人查验货主提供的运输许可证或者备案证明时，对不能确定其真实性 的，可以请当地人民政府公安机关协助核查。公安机关应当当场予以核查，对于 不能当场核实的，应当于3日内将核查结果告知承运人。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第二十三条", "text": "运输易制毒化学品时，运输车辆应当在明显部位张贴易制毒化 学品标识；属于危险化学品的，应当由有危险化学品运输资质的单位运输；应当 凭证运输的，运输人员应当自启运起全程携带运输许可证或者备案证明。承运单 位应当派人押运或者采取其他有效措施，防止易制毒化学品丢失、被盗、被抢。 运输易制毒化学品时，还应当遵守国家有关货物运输的规定。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第二十四条", "text": "公安机关在易制毒化学品运输过程中应当对运输情况与运输许 可证或者备案证明所载内容是否相符等情况进行检查。交警、治安、禁毒、边防 等部门应当在交通重点路段和边境地区等加强易制毒化学品运输的检查。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第二十五条", "text": "易制毒化学品运出地与运入地公安机关应当建立情况通报制 度。运出地负责审批或者备案的公安机关应当每季度末将办理的易制毒化学品运 输许可或者备案情况通报运入地同级公安机关，运入地同级公安机关应当核查货 物的实际运达情况后通报运出地公安机关。 第四章 监督检查"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第二十六条", "text": "县级以上人民政府公安机关应当加强对易制毒化学品购销和运 输等情况的监督检查，有关单位和个人应当积极配合。对发现非法购销和运输行 为的，公安机关应当依法查处。 公安机关在进行易制毒化学品监督检查时，可以依法查看现场、查阅和复制 有关资料、记录有关情况、扣押相关的证据材料和违法物品；必要时，可以临时 查封有关场所。 被检查的单位或者个人应当如实提供有关情况和材料、物品，不得拒绝或者 隐匿。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第二十七条", "text": "公安机关应当对依法收缴、查获的易制毒化学品安全保管。对 于可以回收的，应当予以回收；对于不能回收的，应当依照环境保护法律、行政 法规的有关规定，交由有资质的单位予以销毁，防止造成环境污染和人身伤亡。 对收缴、查获的第一类中的药品类易制毒化学品的，一律销毁。 保管和销毁费用由易制毒化学品违法单位或者个人承担。违法单位或者个人 无力承担的，该费用在回收所得中开支，或者在公安机关的禁毒经费中列支。 第二十八"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第二十八条", "text": "购买、销售和运输易制毒化学品的单位应当于每年3月31日前向 所在地县级公安机关报告上年度的购买、销售和运输情况。公安机关发现可疑情 况的，应当及时予以核对和检查，必要时可以进行实地核查。 有条件的购买、销售和运输单位，可以与当地公安机关建立计算机联网，及 时通报有关情况。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第二十九条", "text": "易制毒化学品丢失、被盗、被抢的，发案单位应当立即向当地 公安机关报告。接到报案的公安机关应当及时立案查处，并向上级公安机关报 告。 第五章 法律责任"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第三十条", "text": "违反规定购买易制毒化学品，有下列情形之一的，公安机关应当 没收非法购买的易制毒化学品，对购买方处非法购买易制毒化学品货值10倍以上 20倍以下的罚款，货值的20倍不足1万元的，按1万元罚款；构成犯罪的，依法追 究刑事责任： （一）未经许可或者备案擅自购买易制毒化学品的； （二）使用他人的或者伪造、变造、失效的许可证或者备案证明购买易制毒 化学品的。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第三十一条", "text": "违反规定销售易制毒化学品，有下列情形之一的，公安机关应 当对销售单位处1万元以下罚款；有违法所得的，处3万元以下罚款，并对违法所 得依法予以追缴；构成犯罪的，依法追究刑事责任： （一）向无购买许可证或者备案证明的单位或者个人销售易制毒化学品的； （二）超出购买许可证或者备案证明的品种、数量销售易制毒化学品的。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第三十二条", "text": "货主违反规定运输易制毒化学品，有下列情形之一的，公安机 关应当没收非法运输的易制毒化学品或者非法运输易制毒化学品的设备、工具； 处非法运输易制毒化学品货值10倍以上20倍以下罚款，货值的20倍不足1万元的， 按1万元罚款；有违法所得的，没收违法所得；构成犯罪的，依法追究刑事责任： （一）未经许可或者备案擅自运输易制毒化学品的； （二）使用他人的或者伪造、变造、失效的许可证运输易制毒化学品的。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第三十三条", "text": "承运人违反规定运输易制毒化学品，有下列情形之一的，公安 机关应当责令停运整改，处5000元以上5万元以下罚款： （一）与易制毒化学品运输许可证或者备案证明载明的品种、数量、运入 地、货主及收货人、承运人等情况不符的； （二）运输许可证种类不当的； （三）运输人员未全程携带运输许可证或者备案证明的。 个人携带易制毒化学品不符合品种、数量规定的，公安机关应当没收易制毒 化学品，处1000元以上5000元以下罚款。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第三十四条", "text": "伪造申请材料骗取易制毒化学品购买、运输许可证或者备案证 明的，公安机关应当处1万元罚款，并撤销许可证或者备案证明。 使用以伪造的申请材料骗取的易制毒化学品购买、运输许可证或者备案证明 购买、运输易制毒化学品的，分别按照"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第三十二条", "text": "第一项的规 定处罚。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第三十四条", "text": "规定违法行为的单 位或个人，自作出行政处罚决定之日起3年内，公安机关可以停止受理其易制毒化 学品购买或者运输许可申请。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第三十六条", "text": "违反易制毒化学品管理规定，有下列行为之一的，公安机关应 当给予警告，责令限期改正，处1万元以上5万元以下罚款；对违反规定购买的易 制毒化学品予以没收；逾期不改正的，责令限期停产停业整顿；逾期整顿不合格 的，吊销相应的许可证： （一）将易制毒化学品购买或运输许可证或者备案证明转借他人使用的； （二）超出许可的品种、数量购买易制毒化学品的； （三）销售、购买易制毒化学品的单位不记录或者不如实记录交易情况、不 按规定保存交易记录或者不如实、不及时向公安机关备案销售情况的； （四）易制毒化学品丢失、被盗、被抢后未及时报告，造成严重后果的； （五）除个人合法购买第一类中的药品类易制毒化学品药品制剂以及第三类 易制毒化学品外，使用现金或者实物进行易制毒化学品交易的； （六）经营易制毒化学品的单位不如实或者不按时报告易制毒化学品年度经 销和库存情况的。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第三十七条", "text": "经营、购买、运输易制毒化学品的单位或者个人拒不接受公安 机关监督检查的，公安机关应当责令其改正，对直接负责的主管人员以及其他直 接责任人员给予警告；情节严重的，对单位处1万元以上5万元以下罚款，对直接 负责的主管人员以及其他直接责任人员处1000元以上5000元以下罚款；有违反治 安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第三十八条", "text": "公安机关易制毒化学品管理工作人员在管理工作中有应当许可 而不许可、不应当许可而滥许可，不依法受理备案，以及其他滥用职权、玩忽职 守、徇私舞弊行为的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第三十九条", "text": "公安机关实施本章处罚，同时应当由其他行政主管机关实施处 罚的，应当通报其他行政机关处理。 第六章 附 则"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第四十条", "text": "本办法所称“经营单位”，是指经营易制毒化学品的经销单位和 经销自产易制毒化学品的生产单位。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第四十一条", "text": "本办法所称“运输”，是指通过公路、铁路、水上和航空等各 种运输途径，使用车、船、航空器等各种运输工具，以及人力、畜力携带、搬运 等各种运输方式使易制毒化学品货物发生空间位置的移动。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第四十二条", "text": "易制毒化学品购买许可证和备案证明、运输许可证和备案证 明、易制毒化学品管理专用印章由公安部统一规定式样并监制。"}, {"law": "易制毒化学品购销和运输管理办法_20061001.pdf", "no": "第四十三条", "text": "本办法自2006年10月1日起施行。《麻黄素运输许可证管理规 定》（公安部令第52号）同时废止。 附件： 附件： 易制毒化学品的分类和品种目录 易制毒化学品的分类和品种目录 第 一 类 第 一 类 1.1—苯基—2—丙酮 2.3,4—亚甲基二氧苯基—2—丙酮 3.胡椒醛 4.黄樟素 5.黄樟油 6.异黄樟素 7.N—乙酰邻氨基苯酸 8.邻氨基苯甲酸 9.麦角酸* 10.麦角胺* 11.麦角新碱* 12.麻黄素、伪麻黄素、消旋麻黄素、去甲麻黄素、甲基麻黄素、麻黄浸膏、 麻黄浸膏粉等麻黄素类物质* 第 二 类 第 二 类 1.苯乙酸 2.醋酸酐 3.三氯甲烷 4.乙醚 5.哌啶 第 三 类 第 三 类 1.甲苯 2.丙酮 3.甲基乙基酮 4.高锰酸钾 5.硫酸 6.盐酸 说明： 一、第一类、第二类所列物质可能存在的盐类，也纳入管制。 二、带有*标记的品种为第一类中的药品类易制毒化学品，第一类中的药品类 易制毒化学品包括原料药及其单方制剂。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第一条", "text": "为了加强特种设备的安全监察，防止和减少事故，保障人民群众生命和财产安全，促进经济发展，制定本条例。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二条", "text": "本条例所称特种设备是指涉及生命安全、危险性较大的锅炉、压力容器(含气瓶，下同)、压力管道、电梯、起重机械、客运索道、大型游乐设施和场(厂)内专用机动车辆。 前款特种设备的目录由国务院负责特种设备安全监督管理的部门(以下简称国务院特种设备安全监督管理部门)制订，报国务院批准后执行。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第三条", "text": "特种设备的生产(含设计、制造、安装、改造、维修，下同)、使用、检验检测及其监督检查，应当遵守本条例，但本条例另有规定的除外。 军事装备、核设施、航空航天器、铁路机车、海上设施和船舶以及矿山井下使用的特种设备、民用机场专用设备的安全监察不适用本条例。 房屋建筑工地和市政工程工地用起重机械、场(厂)内专用机动车辆的安装、使用的监督管理，由建设行政主管部门依照有关法律、法规的规定执行。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第四条", "text": "国务院特种设备安全监督管理部门负责全国特种设备的安全监察工作，县以上地方负责特种设备安全监督管理的部门对本行政区域内特种设备实施安全监察(以下统称特种设备安全监督管理部门)。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第五条", "text": "特种设备生产、使用单位应当建立健全特种设备安全、节能管理制度和岗位安全、节能责任制度。 特种设备生产、使用单位的主要负责人应当对本单位特种设备的安全和节能全面负责。 特种设备生产、使用单位和特种设备检验检测机构，应当接受特种设备安全监督管理部门依法进行的特种设备安全监察。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第六条", "text": "特种设备检验检测机构，应当依照本条例规定，进行检验检测工作，对其检验检测结果、鉴定结论承担法律责任。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第七条", "text": "县级以上地方人民政府应当督促、支持特种设备安全监督管理部门依法履行安全监察职责，对特种设备安全监察中存在的重大问题及时予以协调、解决。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第八条", "text": "国家鼓励推行科学的管理方法，采用先进技术，提高特种设备安全性能和管理水平，增强特种设备生产、使用单位防范事故的能力，对取得显著成绩的单位和个人，给予奖励。 国家鼓励特种设备节能技术的研究、开发、示范和推广，促进特种设备节能技术创新和应用。 特种设备生产、使用单位和特种设备检验检测机构，应当保证必要的安全和节能投入。 国家鼓励实行特种设备责任保险制度，提高事故赔付能力。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第九条", "text": "任何单位和个人对违反本条例规定的行为，有权向特种设备安全监督管理部门和行政监察等有关部门举报。 特种设备安全监督管理部门应当建立特种设备安全监察举报制度，公布举报电话、信箱或者电子邮件地址，受理对特种设备生产、使用和检验检测违法行为的举报，并及时予以处理。 特种设备安全监督管理部门和行政监察等有关部门应当为举报人保密，并按照国家有关规定给予奖励。 第二章 特种设备的生产"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第十条", "text": "特种设备生产单位，应当依照本条例规定以及国务院特种设备安全监督管理部门制订并公布的安全技术规范(以下简称安全技术规范)的要求，进行生产活动。 特种设备生产单位对其生产的特种设备的安全性能和能效指标负责，不得生产不符合安全性能要求和能效指标的特种设备，不得生产国家产业政策明令淘汰的特种设备。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第十一条", "text": "压力容器的设计单位应当经国务院特种设备安全监督管理部门许可，方可从事压力容器的设计活动。 压力容器的设计单位应当具备下列条件： (一)有与压力容器设计相适应的设计人员、设计审核人员； (二)有与压力容器设计相适应的场所和设备； (三)有与压力容器设计相适应的健全的管理制度和责任制度。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第十二条", "text": "锅炉、压力容器中的气瓶(以下简称气瓶)、氧舱和客运索道、大型游乐设施以及高耗能特种设备的设计文件，应当经国务院特种设备安全监督管理部门核准的检验检测机构鉴定，方可用于制造。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第十三条", "text": "按照安全技术规范的要求，应当进行型式试验的特种设备产品、部件或者试制特种设备新产品、新部件、新材料，必须进行型式试验和能效测试。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第十四条", "text": "锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施及其安全附件、安全保护装置的制造、安装、改造单位，以及压力管道用管子、管件、阀门、法兰、补偿器、安全保护装置等(以下简称压力管道元件)的制造单位和场(厂)内专用机动车辆的制造、改造单位，应当经国务院特种设备安全监督管理部门许可，方可从事相应的活动。 前款特种设备的制造、安装、改造单位应当具备下列条件： (一)有与特种设备制造、安装、改造相适应的专业技术人员和技术工人； (二)有与特种设备制造、安装、改造相适应的生产条件和检测手段； (三)有健全的质量管理制度和责任制度。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第十五条", "text": "特种设备出厂时，应当附有安全技术规范要求的设计文件、产品质量合格证明、安装及使用维修说明、监督检验证明等文件。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第十六条", "text": "锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施、场(厂)内专用机动车辆的维修单位，应当有与特种设备维修相适应的专业技术人员和技术工人以及必要的检测手段，并经省、自治区、直辖市特种设备安全监督管理部门许可，方可从事相应的维修活动。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第十七条", "text": "锅炉、压力容器、起重机械、客运索道、大型游乐设施的安装、改造、维修以及场(厂)内专用机动车辆的改造、维修，必须由依照本条例取得许可的单位进行。 电梯的安装、改造、维修，必须由电梯制造单位或者其通过合同委托、同意的依照本条例取得许可的单位进行。电梯制造单位对电梯质量以及安全运行涉及的质量问题负责。 特种设备安装、改造、维修的施工单位应当在施工前将拟进行的特种设备安装、改造、维修情况书面告知直辖市或者设区的市的特种设备安全监督管理部门，告知后即可施工。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第十八条", "text": "电梯井道的土建工程必须符合建筑工程质量要求。电梯安装施工过程中，电梯安装单位应当遵守施工现场的安全生产要求，落实现场安全防护措施。电梯安装施工过程中，施工现场的安全生产监督，由有关部门依照有关法律、行政法规的规定执行。 电梯安装施工过程中，电梯安装单位应当服从建筑施工总承包单位对施工现场的安全生产管理，并订立合同，明确各自的安全责任。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第十九条", "text": "电梯的制造、安装、改造和维修活动，必须严格遵守安全技术规范的要求。电梯制造单位委托或者同意其他单位进行电梯安装、改造、维修活动的，应当对其安装、改造、维修活动进行安全指导和监控。电梯的安装、改造、维修活动结束后，电梯制造单位应当按照安全技术规范的要求对电梯进行校验和调试，并对校验和调试的结果负责。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二十条", "text": "锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施的安装、改造、维修以及场(厂)内专用机动车辆的改造、维修竣工后，安装、改造、维修的施工单位应当在验收后30日内将有关技术资料移交使用单位，高耗能特种设备还应当按照安全技术规范的要求提交能效测试报告。使用单位应当将其存入该特种设备的安全技术档案。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二十一条", "text": "锅炉、压力容器、压力管道元件、起重机械、大型游乐设施的制造过程和锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施的安装、改造、重大维修过程，必须经国务院特种设备安全监督管理部门核准的检验检测机构按照安全技术规范的要求进行监督检验；未经监督检验合格的不得出厂或者交付使用。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二十二条", "text": "移动式压力容器、气瓶充装单位应当经省、自治区、直辖市的特种设备安全监督管理部门许可，方可从事充装活动。 充装单位应当具备下列条件： (一)有与充装和管理相适应的管理人员和技术人员； (二)有与充装和管理相适应的充装设备、检测手段、场地厂房、器具、安全设施； (三)有健全的充装管理制度、责任制度、紧急处理措施。 气瓶充装单位应当向气体使用者提供符合安全技术规范要求的气瓶，对使用者进行气瓶安全使用指导，并按照安全技术规范的要求办理气瓶使用登记，提出气瓶的定期检验要求。 第三章 特种设备的使用"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二十三条", "text": "特种设备使用单位，应当严格执行本条例和有关安全生产的法律、行政法规的规定，保证特种设备的安全使用。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二十四条", "text": "特种设备使用单位应当使用符合安全技术规范要求的特种设备。特种设备投入使用前，使用单位应当核对其是否附有本条例"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第十五条", "text": "规定的相关文件。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二十五条", "text": "特种设备在投入使用前或者投入使用后30日内，特种设备使用单位应当向直辖市或者设区的市的特种设备安全监督管理部门登记。登记标志应当置于或者附着于该特种设备的显著位置。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二十六条", "text": "特种设备使用单位应当建立特种设备安全技术档案。安全技术档案应当包括以下内容： (一)特种设备的设计文件、制造单位、产品质量合格证明、使用维护说明等文件以及安装技术文件和资料； (二)特种设备的定期检验和定期自行检查的记录； (三)特种设备的日常使用状况记录； (四)特种设备及其安全附件、安全保护装置、测量调控装置及有关附属仪器仪表的日常维护保养记录； (五)特种设备运行故障和事故记录； (六)高耗能特种设备的能效测试报告、能耗状况记录以及节能改造技术资料。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二十七条", "text": "特种设备使用单位应当对在用特种设备进行经常性日常维护保养，并定期自行检查。 特种设备使用单位对在用特种设备应当至少每月进行一次自行检查，并作出记录。特种设备使用单位在对在用特种设备进行自行检查和日常维护保养时发现异常情况的，应当及时处理。 特种设备使用单位应当对在用特种设备的安全附件、安全保护装置、测量调控装置及有关附属仪器仪表进行定期校验、检修，并作出记录。 锅炉使用单位应当按照安全技术规范的要求进行锅炉水(介)质处理，并接受特种设备检验检测机构实施的水(介)质处理定期检验。 从事锅炉清洗的单位，应当按照安全技术规范的要求进行锅炉清洗，并接受特种设备检验检测机构实施的锅炉清洗过程监督检验。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二十八条", "text": "特种设备使用单位应当按照安全技术规范的定期检验要求，在安全检验合格有效期届满前1个月向特种设备检验检测机构提出定期检验要求。 检验检测机构接到定期检验要求后，应当按照安全技术规范的要求及时进行安全性能检验和能效测试。 未经定期检验或者检验不合格的特种设备，不得继续使用。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二十九条", "text": "特种设备出现故障或者发生异常情况，使用单位应当对其进行全面检查，消除事故隐患后，方可重新投入使用。 特种设备不符合能效指标的，特种设备使用单位应当采取相应措施进行整改。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第三十条", "text": "特种设备存在严重事故隐患，无改造、维修价值，或者超过安全技术规范规定使用年限，特种设备使用单位应当及时予以报废，并应当向原登记的特种设备安全监督管理部门办理注销。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第三十一条", "text": "电梯的日常维护保养必须由依照本条例取得许可的安装、改造、维修单位或者电梯制造单位进行。 电梯应当至少每15日进行一次清洁、润滑、调整和检查。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第三十二条", "text": "电梯的日常维护保养单位应当在维护保养中严格执行国家安全技术规范的要求，保证其维护保养的电梯的安全技术性能，并负责落实现场安全防护措施，保证施工安全。 电梯的日常维护保养单位，应当对其维护保养的电梯的安全性能负责。接到故障通知后，应当立即赶赴现场，并采取必要的应急救援措施。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第三十三条", "text": "电梯、客运索道、大型游乐设施等为公众提供服务的特种设备运营使用单位，应当设置特种设备安全管理机构或者配备专职的安全管理人员；其他特种设备使用单位，应当根据情况设置特种设备安全管理机构或者配备专职、兼职的安全管理人员。 特种设备的安全管理人员应当对特种设备使用状况进行经常性检查，发现问题的应当立即处理；情况紧急时，可以决定停止使用特种设备并及时报告本单位有关负责人。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第三十四条", "text": "客运索道、大型游乐设施的运营使用单位在客运索道、大型游乐设施每日投入使用前，应当进行试运行和例行安全检查，并对安全装置进行检查确认。 电梯、客运索道、大型游乐设施的运营使用单位应当将电梯、客运索道、大型游乐设施的安全注意事项和警示标志置于易于为乘客注意的显著位置。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第三十五条", "text": "客运索道、大型游乐设施的运营使用单位的主要负责人应当熟悉客运索道、大型游乐设施的相关安全知识，并全面负责客运索道、大型游乐设施的安全使用。 客运索道、大型游乐设施的运营使用单位的主要负责人至少应当每月召开一次会议，督促、检查客运索道、大型游乐设施的安全使用工作。 客运索道、大型游乐设施的运营使用单位，应当结合本单位的实际情况，配备相应数量的营救装备和急救物品。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第三十六条", "text": "电梯、客运索道、大型游乐设施的乘客应当遵守使用安全注意事项的要求，服从有关工作人员的指挥。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第三十七条", "text": "电梯投入使用后，电梯制造单位应当对其制造的电梯的安全运行情况进行跟踪调查和了解，对电梯的日常维护保养单位或者电梯的使用单位在安全运行方面存在的问题，提出改进建议，并提供必要的技术帮助。发现电梯存在严重事故隐患的，应当及时向特种设备安全监督管理部门报告。电梯制造单位对调查和了解的情况，应当作出记录。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第三十八条", "text": "锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施、场(厂)内专用机动车辆的作业人员及其相关管理人员(以下统称特种设备作业人员)，应当按照国家有关规定经特种设备安全监督管理部门考核合格，取得国家统一格式的特种作业人员证书，方可从事相应的作业或者管理工作。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第三十九条", "text": "特种设备使用单位应当对特种设备作业人员进行特种设备安全、节能教育和培训，保证特种设备作业人员具备必要的特种设备安全、节能知识。 特种设备作业人员在作业中应当严格执行特种设备的操作规程和有关的安全规章制度。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第四十条", "text": "特种设备作业人员在作业过程中发现事故隐患或者其他不安全因素，应当立即向现场安全管理人员和单位有关负责人报告。 第四章 检验检测"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第四十一条", "text": "从事本条例规定的监督检验、定期检验、型式试验以及专门为特种设备生产、使用、检验检测提供无损检测服务的特种设备检验检测机构，应当经国务院特种设备安全监督管理部门核准。 特种设备使用单位设立的特种设备检验检测机构，经国务院特种设备安全监督管理部门核准，负责本单位核准范围内的特种设备定期检验工作。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第四十二条", "text": "特种设备检验检测机构，应当具备下列条件： (一)有与所从事的检验检测工作相适应的检验检测人员； (二)有与所从事的检验检测工作相适应的检验检测仪器和设备； (三)有健全的检验检测管理制度、检验检测责任制度。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第四十三条", "text": "特种设备的监督检验、定期检验、型式试验和无损检测应当由依照本条例经核准的特种设备检验检测机构进行。 特种设备检验检测工作应当符合安全技术规范的要求。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第四十四条", "text": "从事本条例规定的监督检验、定期检验、型式试验和无损检测的特种设备检验检测人员应当经国务院特种设备安全监督管理部门组织考核合格，取得检验检测人员证书，方可从事检验检测工作。 检验检测人员从事检验检测工作，必须在特种设备检验检测机构执业，但不得同时在两个以上检验检测机构中执业。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第四十五条", "text": "特种设备检验检测机构和检验检测人员进行特种设备检验检测，应当遵循诚信原则和方便企业的原则，为特种设备生产、使用单位提供可靠、便捷的检验检测服务。 特种设备检验检测机构和检验检测人员对涉及的被检验检测单位的商业秘密，负有保密义务。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第四十六条", "text": "特种设备检验检测机构和检验检测人员应当客观、公正、及时地出具检验检测结果、鉴定结论。检验检测结果、鉴定结论经检验检测人员签字后，由检验检测机构负责人签署。 特种设备检验检测机构和检验检测人员对检验检测结果、鉴定结论负责。 国务院特种设备安全监督管理部门应当组织对特种设备检验检测机构的检验检测结果、鉴定结论进行监督抽查。县以上地方负责特种设备安全监督管理的部门在本行政区域内也可以组织监督抽查，但是要防止重复抽查。监督抽查结果应当向社会公布。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第四十七条", "text": "特种设备检验检测机构和检验检测人员不得从事特种设备的生产、销售，不得以其名义推荐或者监制、监销特种设备。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第四十八条", "text": "特种设备检验检测机构进行特种设备检验检测，发现严重事故隐患或者能耗严重超标的，应当及时告知特种设备使用单位，并立即向特种设备安全监督管理部门报告。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第四十九条", "text": "特种设备检验检测机构和检验检测人员利用检验检测工作故意刁难特种设备生产、使用单位，特种设备生产、使用单位有权向特种设备安全监督管理部门投诉，接到投诉的特种设备安全监督管理部门应当及时进行调查处理。 第五章 监督检查"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第五十条", "text": "特种设备安全监督管理部门依照本条例规定，对特种设备生产、使用单位和检验检测机构实施安全监察。 对学校、幼儿园以及车站、客运码头、商场、体育场馆、展览馆、公园等公众聚集场所的特种设备，特种设备安全监督管理部门应当实施重点安全监察。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第五十一条", "text": "特种设备安全监督管理部门根据举报或者取得的涉嫌违法证据，对涉嫌违反本条例规定的行为进行查处时，可以行使下列职权： (一)向特种设备生产、使用单位和检验检测机构的法定代表人、主要负责人和其他有关人员调查、了解与涉嫌从事违反本条例的生产、使用、检验检测有关的情况； (二)查阅、复制特种设备生产、使用单位和检验检测机构的有关合同、发票、账簿以及其他有关资料； (三)对有证据表明不符合安全技术规范要求的或者有其他严重事故隐患、能耗严重超标的特种设备，予以查封或者扣押。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第五十二条", "text": "依照本条例规定实施许可、核准、登记的特种设备安全监督管理部门，应当严格依照本条例规定条件和安全技术规范要求对有关事项进行审查；不符合本条例规定条件和安全技术规范要求的，不得许可、核准、登记；在申请办理许可、核准期间，特种设备安全监督管理部门发现申请人未经许可从事特种设备相应活动或者伪造许可、核准证书的，不予受理或者不予许可、核准，并在1年内不再受理其新的许可、核准申请。 未依法取得许可、核准、登记的单位擅自从事特种设备的生产、使用或者检验检测活动的，特种设备安全监督管理部门应当依法予以处理。 违反本条例规定，被依法撤销许可的，自撤销许可之日起3年内，特种设备安全监督管理部门不予受理其新的许可申请。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第五十三条", "text": "特种设备安全监督管理部门在办理本条例规定的有关行政审批事项时，其受理、审查、许可、核准的程序必须公开，并应当自受理申请之日起30日内，作出许可、核准或者不予许可、核准的决定；不予许可、核准的，应当书面向申请人说明理由。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第五十四条", "text": "地方各级特种设备安全监督管理部门不得以任何形式进行地方保护和地区封锁，不得对已经依照本条例规定在其他地方取得许可的特种设备生产单位重复进行许可，也不得要求对依照本条例规定在其他地方检验检测合格的特种设备，重复进行检验检测。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第五十五条", "text": "特种设备安全监督管理部门的安全监察人员(以下简称特种设备安全监察人员)应当熟悉相关法律、法规、规章和安全技术规范，具有相应的专业知识和工作经验，并经国务院特种设备安全监督管理部门考核，取得特种设备安全监察人员证书。 特种设备安全监察人员应当忠于职守、坚持原则、秉公执法。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第五十六条", "text": "特种设备安全监督管理部门对特种设备生产、使用单位和检验检测机构实施安全监察时，应当有两名以上特种设备安全监察人员参加，并出示有效的特种设备安全监察人员证件。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第五十七条", "text": "特种设备安全监督管理部门对特种设备生产、使用单位和检验检测机构实施安全监察，应当对每次安全监察的内容、发现的问题及处理情况，作出记录，并由参加安全监察的特种设备安全监察人员和被检查单位的有关负责人签字后归档。被检查单位的有关负责人拒绝签字的，特种设备安全监察人员应当将情况记录在案。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第五十八条", "text": "特种设备安全监督管理部门对特种设备生产、使用单位和检验检测机构进行安全监察时，发现有违反本条例规定和安全技术规范要求的行为或者在用的特种设备存在事故隐患、不符合能效指标的，应当以书面形式发出特种设备安全监察指令，责令有关单位及时采取措施，予以改正或者消除事故隐患。紧急情况下需要采取紧急处置措施的，应当随后补发书面通知。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第五十九条", "text": "特种设备安全监督管理部门对特种设备生产、使用单位和检验检测机构进行安全监察，发现重大违法行为或者严重事故隐患时，应当在采取必要措施的同时，及时向上级特种设备安全监督管理部门报告。接到报告的特种设备安全监督管理部门应当采取必要措施，及时予以处理。 对违法行为、严重事故隐患或者不符合能效指标的处理需要当地人民政府和有关部门的支持、配合时，特种设备安全监督管理部门应当报告当地人民政府，并通知其他有关部门。当地人民政府和其他有关部门应当采取必要措施，及时予以处理。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第六十条", "text": "国务院特种设备安全监督管理部门和省、自治区、直辖市特种设备安全监督管理部门应当定期向社会公布特种设备安全以及能效状况。 公布特种设备安全以及能效状况，应当包括下列内容： (一)特种设备质量安全状况； (二)特种设备事故的情况、特点、原因分析、防范对策； (三)特种设备能效状况； (四)其他需要公布的情况。 第六章 事故预防和调查处理"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第六十一条", "text": "有下列情形之一的，为特别重大事故： (一)特种设备事故造成30人以上死亡，或者100人以上重伤(包括急性工业中毒，下同)，或者1亿元以上直接经济损失的； (二)600兆瓦以上锅炉爆炸的； (三)压力容器、压力管道有毒介质泄漏，造成15万人以上转移的； (四)客运索道、大型游乐设施高空滞留100人以上并且时间在48小时以上的。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第六十二条", "text": "有下列情形之一的，为重大事故： (一)特种设备事故造成10人以上30人以下死亡，或者50人以上100人以下重伤，或者5000万元以上1亿元以下直接经济损失的； (二)600兆瓦以上锅炉因安全故障中断运行240小时以上的； (三)压力容器、压力管道有毒介质泄漏，造成5万人以上15万人以下转移的； (四)客运索道、大型游乐设施高空滞留100人以上并且时间在24小时以上48小时以下的。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第六十三条", "text": "有下列情形之一的，为较大事故： (一)特种设备事故造成3人以上10人以下死亡，或者10人以上50人以下重伤，或者1000万元以上5000万元以下直接经济损失的； (二)锅炉、压力容器、压力管道爆炸的； (三)压力容器、压力管道有毒介质泄漏，造成1万人以上5万人以下转移的； (四)起重机械整体倾覆的； (五)客运索道、大型游乐设施高空滞留人员12小时以上的。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第六十四条", "text": "有下列情形之一的，为一般事故： (一)特种设备事故造成3人以下死亡，或者10人以下重伤，或者1万元以上1000万元以下直接经济损失的； (二)压力容器、压力管道有毒介质泄漏，造成500人以上1万人以下转移的； (三)电梯轿厢滞留人员2小时以上的； (四)起重机械主要受力结构件折断或者起升机构坠落的； (五)客运索道高空滞留人员3.5小时以上12小时以下的； (六)大型游乐设施高空滞留人员1小时以上12小时以下的。 除前款规定外，国务院特种设备安全监督管理部门可以对一般事故的其他情形做出补充规定。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第六十五条", "text": "特种设备安全监督管理部门应当制定特种设备应急预案。特种设备使用单位应当制定事故应急专项预案，并定期进行事故应急演练。 压力容器、压力管道发生爆炸或者泄漏，在抢险救援时应当区分介质特性，严格按照相关预案规定程序处理，防止二次爆炸。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第六十六条", "text": "特种设备事故发生后，事故发生单位应当立即启动事故应急预案，组织抢救，防止事故扩大，减少人员伤亡和财产损失，并及时向事故发生地县以上特种设备安全监督管理部门和有关部门报告。 县以上特种设备安全监督管理部门接到事故报告，应当尽快核实有关情况，立即向所在地人民政府报告，并逐级上报事故情况。必要时，特种设备安全监督管理部门可以越级上报事故情况。对特别重大事故、重大事故，国务院特种设备安全监督管理部门应当立即报告国务院并通报国务院安全生产监督管理部门等有关部门。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第六十七条", "text": "特别重大事故由国务院或者国务院授权有关部门组织事故调查组进行调查。 重大事故由国务院特种设备安全监督管理部门会同有关部门组织事故调查组进行调查。 较大事故由省、自治区、直辖市特种设备安全监督管理部门会同有关部门组织事故调查组进行调查。 一般事故由设区的市的特种设备安全监督管理部门会同有关部门组织事故调查组进行调查。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第六十八条", "text": "事故调查报告应当由负责组织事故调查的特种设备安全监督管理部门的所在地人民政府批复，并报上一级特种设备安全监督管理部门备案。 有关机关应当按照批复，依照法律、行政法规规定的权限和程序，对事故责任单位和有关人员进行行政处罚，对负有事故责任的国家工作人员进行处分。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第六十九条", "text": "特种设备安全监督管理部门应当在有关地方人民政府的领导下，组织开展特种设备事故调查处理工作。 有关地方人民政府应当支持、配合上级人民政府或者特种设备安全监督管理部门的事故调查处理工作，并提供必要的便利条件。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第七十条", "text": "特种设备安全监督管理部门应当对发生事故的原因进行分析，并根据特种设备的管理和技术特点、事故情况对相关安全技术规范进行评估；需要制定或者修订相关安全技术规范的，应当及时制定或者修订。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第七十一条", "text": "本章所称的“以上”包括本数，所称的“以下”不包括本数。 第七章 法律责任"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第七十二条", "text": "未经许可，擅自从事压力容器设计活动的，由特种设备安全监督管理部门予以取缔，处5万元以上20万元以下罚款；有违法所得的，没收违法所得；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于非法经营罪或者其他罪的规定，依法追究刑事责任。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第七十三条", "text": "锅炉、气瓶、氧舱和客运索道、大型游乐设施以及高耗能特种设备的设计文件，未经国务院特种设备安全监督管理部门核准的检验检测机构鉴定，擅自用于制造的，由特种设备安全监督管理部门责令改正，没收非法制造的产品，处5万元以上20万元以下罚款；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于生产、销售伪劣产品罪、非法经营罪或者其他罪的规定，依法追究刑事责任。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第七十四条", "text": "按照安全技术规范的要求应当进行型式试验的特种设备产品、部件或者试制特种设备新产品、新部件，未进行整机或者部件型式试验的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，处2万元以上10万元以下罚款。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第七十五条", "text": "未经许可，擅自从事锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施、场(厂)内专用机动车辆及其安全附件、安全保护装置的制造、安装、改造以及压力管道元件的制造活动的，由特种设备安全监督管理部门予以取缔，没收非法制造的产品，已经实施安装、改造的，责令恢复原状或者责令限期由取得许可的单位重新安装、改造，处10万元以上50万元以下罚款；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于生产、销售伪劣产品罪、非法经营罪、重大责任事故罪或者其他罪的规定，依法追究刑事责任。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第七十六条", "text": "特种设备出厂时，未按照安全技术规范的要求附有设计文件、产品质量合格证明、安装及使用维修说明、监督检验证明等文件的，由特种设备安全监督管理部门责令改正；情节严重的，责令停止生产、销售，处违法生产、销售货值金额30%以下罚款；有违法所得的，没收违法所得。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第七十七条", "text": "未经许可，擅自从事锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施、场(厂)内专用机动车辆的维修或者日常维护保养的，由特种设备安全监督管理部门予以取缔，处1万元以上5万元以下罚款；有违法所得的，没收违法所得；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于非法经营罪、重大责任事故罪或者其他罪的规定，依法追究刑事责任。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第七十八条", "text": "锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施的安装、改造、维修的施工单位以及场(厂)内专用机动车辆的改造、维修单位，在施工前未将拟进行的特种设备安装、改造、维修情况书面告知直辖市或者设区的市的特种设备安全监督管理部门即行施工的，或者在验收后30日内未将有关技术资料移交锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施的使用单位的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，处2000元以上1万元以下罚款。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第七十九条", "text": "锅炉、压力容器、压力管道元件、起重机械、大型游乐设施的制造过程和锅炉、压力容器、电梯、起重机械、客运索道、大型游乐设施的安装、改造、重大维修过程，以及锅炉清洗过程，未经国务院特种设备安全监督管理部门核准的检验检测机构按照安全技术规范的要求进行监督检验的，由特种设备安全监督管理部门责令改正，已经出厂的，没收违法生产、销售的产品，已经实施安装、改造、重大维修或者清洗的，责令限期进行监督检验，处5万元以上20万元以下罚款；有违法所得的，没收违法所得；情节严重的，撤销制造、安装、改造或者维修单位已经取得的许可，并由工商行政管理部门吊销其营业执照；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于生产、销售伪劣产品罪或者其他罪的规定，依法追究刑事责任。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第八十条", "text": "未经许可，擅自从事移动式压力容器或者气瓶充装活动的，由特种设备安全监督管理部门予以取缔，没收违法充装的气瓶，处10万元以上50万元以下罚款；有违法所得的，没收违法所得；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于非法经营罪或者其他罪的规定，依法追究刑事责任。 移动式压力容器、气瓶充装单位未按照安全技术规范的要求进行充装活动的，由特种设备安全监督管理部门责令改正，处2万元以上10万元以下罚款；情节严重的，撤销其充装资格。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第八十一条", "text": "电梯制造单位有下列情形之一的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，予以通报批评： (一)未依照本条例"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第十九条", "text": "的规定对电梯进行校验、调试的； (二)对电梯的安全运行情况进行跟踪调查和了解时，发现存在严重事故隐患，未及时向特种设备安全监督管理部门报告的。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第八十二条", "text": "已经取得许可、核准的特种设备生产单位、检验检测机构有下列行为之一的，由特种设备安全监督管理部门责令改正，处2万元以上10万元以下罚款；情节严重的，撤销其相应资格： (一)未按照安全技术规范的要求办理许可证变更手续的； (二)不再符合本条例规定或者安全技术规范要求的条件，继续从事特种设备生产、检验检测的； (三)未依照本条例规定或者安全技术规范要求进行特种设备生产、检验检测的； (四)伪造、变造、出租、出借、转让许可证书或者监督检验报告的。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第八十三条", "text": "特种设备使用单位有下列情形之一的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，处2000元以上2万元以下罚款；情节严重的，责令停止使用或者停产停业整顿： (一)特种设备投入使用前或者投入使用后30日内，未向特种设备安全监督管理部门登记，擅自将其投入使用的； (二)未依照本条例"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二十六条", "text": "的规定，建立特种设备安全技术档案的； (三)未依照本条例"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第二十七条", "text": "的规定，对在用特种设备进行经常性日常维护保养和定期自行检查的，或者对在用特种设备的安全附件、安全保护装置、测量调控装置及有关附属仪器仪表进行定期校验、检修，并作出记录的； (四)未按照安全技术规范的定期检验要求，在安全检验合格有效期届满前1个月向特种设备检验检测机构提出定期检验要求的； (五)使用未经定期检验或者检验不合格的特种设备的； (六)特种设备出现故障或者发生异常情况，未对其进行全面检查、消除事故隐患，继续投入使用的； (七)未制定特种设备事故应急专项预案的； (八)未依照本条例"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第三十一条", "text": "第二款的规定，对电梯进行清洁、润滑、调整和检查的； (九)未按照安全技术规范要求进行锅炉水(介)质处理的； (十)特种设备不符合能效指标，未及时采取相应措施进行整改的。 特种设备使用单位使用未取得生产许可的单位生产的特种设备或者将非承压锅炉、非压力容器作为承压锅炉、压力容器使用的，由特种设备安全监督管理部门责令停止使用，予以没收，处2万元以上10万元以下罚款。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第八十四条", "text": "特种设备存在严重事故隐患，无改造、维修价值，或者超过安全技术规范规定的使用年限，特种设备使用单位未予以报废，并向原登记的特种设备安全监督管理部门办理注销的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，处5万元以上20万元以下罚款。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第八十五条", "text": "电梯、客运索道、大型游乐设施的运营使用单位有下列情形之一的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，责令停止使用或者停产停业整顿，处1万元以上5万元以下罚款： (一)客运索道、大型游乐设施每日投入使用前，未进行试运行和例行安全检查，并对安全装置进行检查确认的； (二)未将电梯、客运索道、大型游乐设施的安全注意事项和警示标志置于易于为乘客注意的显著位置的。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第八十六条", "text": "特种设备使用单位有下列情形之一的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，责令停止使用或者停产停业整顿，处2000元以上2万元以下罚款： (一)未依照本条例规定设置特种设备安全管理机构或者配备专职、兼职的安全管理人员的； (二)从事特种设备作业的人员，未取得相应特种作业人员证书，上岗作业的； (三)未对特种设备作业人员进行特种设备安全教育和培训的。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第八十七条", "text": "发生特种设备事故，有下列情形之一的，对单位，由特种设备安全监督管理部门处5万元以上20万元以下罚款；对主要负责人，由特种设备安全监督管理部门处4000元以上2万元以下罚款；属于国家工作人员的，依法给予处分；触犯刑律的，依照刑法关于重大责任事故罪或者其他罪的规定，依法追究刑事责任： (一)特种设备使用单位的主要负责人在本单位发生特种设备事故时，不立即组织抢救或者在事故调查处理期间擅离职守或者逃匿的； (二)特种设备使用单位的主要负责人对特种设备事故隐瞒不报、谎报或者拖延不报的。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第八十八条", "text": "对事故发生负有责任的单位，由特种设备安全监督管理部门依照下列规定处以罚款： (一)发生一般事故的，处10万元以上20万元以下罚款； (二)发生较大事故的，处20万元以上50万元以下罚款； (三)发生重大事故的，处50万元以上200万元以下罚款。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第八十九条", "text": "对事故发生负有责任的单位的主要负责人未依法履行职责，导致事故发生的，由特种设备安全监督管理部门依照下列规定处以罚款；属于国家工作人员的，并依法给予处分；触犯刑律的，依照刑法关于重大责任事故罪或者其他罪的规定，依法追究刑事责任： (一)发生一般事故的，处上一年年收入30%的罚款； (二)发生较大事故的，处上一年年收入40%的罚款； (三)发生重大事故的，处上一年年收入60%的罚款。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第九十条", "text": "特种设备作业人员违反特种设备的操作规程和有关的安全规章制度操作，或者在作业过程中发现事故隐患或者其他不安全因素，未立即向现场安全管理人员和单位有关负责人报告的，由特种设备使用单位给予批评教育、处分；情节严重的，撤销特种设备作业人员资格；触犯刑律的，依照刑法关于重大责任事故罪或者其他罪的规定，依法追究刑事责任。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第九十一条", "text": "未经核准，擅自从事本条例所规定的监督检验、定期检验、型式试验以及无损检测等检验检测活动的，由特种设备安全监督管理部门予以取缔，处5万元以上20万元以下罚款；有违法所得的，没收违法所得；触犯刑律的，对负有责任的主管人员和其他直接责任人员依照刑法关于非法经营罪或者其他罪的规定，依法追究刑事责任。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第九十二条", "text": "特种设备检验检测机构，有下列情形之一的，由特种设备安全监督管理部门处2万元以上10万元以下罚款；情节严重的，撤销其检验检测资格： (一)聘用未经特种设备安全监督管理部门组织考核合格并取得检验检测人员证书的人员，从事相关检验检测工作的； (二)在进行特种设备检验检测中，发现严重事故隐患或者能耗严重超标，未及时告知特种设备使用单位，并立即向特种设备安全监督管理部门报告的。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第九十三条", "text": "特种设备检验检测机构和检验检测人员，出具虚假的检验检测结果、鉴定结论或者检验检测结果、鉴定结论严重失实的，由特种设备安全监督管理部门对检验检测机构没收违法所得，处5万元以上20万元以下罚款，情节严重的，撤销其检验检测资格；对检验检测人员处5000元以上5万元以下罚款，情节严重的，撤销其检验检测资格，触犯刑律的，依照刑法关于中介组织人员提供虚假证明文件罪、中介组织人员出具证明文件重大失实罪或者其他罪的规定，依法追究刑事责任。 特种设备检验检测机构和检验检测人员，出具虚假的检验检测结果、鉴定结论或者检验检测结果、鉴定结论严重失实，造成损害的，应当承担赔偿责任。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第九十四条", "text": "特种设备检验检测机构或者检验检测人员从事特种设备的生产、销售，或者以其名义推荐或者监制、监销特种设备的，由特种设备安全监督管理部门撤销特种设备检验检测机构和检验检测人员的资格，处5万元以上20万元以下罚款；有违法所得的，没收违法所得。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第九十五条", "text": "特种设备检验检测机构和检验检测人员利用检验检测工作故意刁难特种设备生产、使用单位，由特种设备安全监督管理部门责令改正；拒不改正的，撤销其检验检测资格。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第九十六条", "text": "检验检测人员，从事检验检测工作，不在特种设备检验检测机构执业或者同时在两个以上检验检测机构中执业的，由特种设备安全监督管理部门责令改正，情节严重的，给予停止执业6个月以上2年以下的处罚；有违法所得的，没收违法所得。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第九十七条", "text": "特种设备安全监督管理部门及其特种设备安全监察人员，有下列违法行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予降级或者撤职的处分；触犯刑律的，依照刑法关于受贿罪、滥用职权罪、玩忽职守罪或者其他罪的规定，依法追究刑事责任： (一)不按照本条例规定的条件和安全技术规范要求，实施许可、核准、登记的； (二)发现未经许可、核准、登记擅自从事特种设备的生产、使用或者检验检测活动不予取缔或者不依法予以处理的； (三)发现特种设备生产、使用单位不再具备本条例规定的条件而不撤销其原许可，或者发现特种设备生产、使用违法行为不予查处的； (四)发现特种设备检验检测机构不再具备本条例规定的条件而不撤销其原核准，或者对其出具虚假的检验检测结果、鉴定结论或者检验检测结果、鉴定结论严重失实的行为不予查处的； (五)对依照本条例规定在其他地方取得许可的特种设备生产单位重复进行许可，或者对依照本条例规定在其他地方检验检测合格的特种设备，重复进行检验检测的； (六)发现有违反本条例和安全技术规范的行为或者在用的特种设备存在严重事故隐患，不立即处理的； (七)发现重大的违法行为或者严重事故隐患，未及时向上级特种设备安全监督管理部门报告，或者接到报告的特种设备安全监督管理部门不立即处理的； (八)迟报、漏报、瞒报或者谎报事故的； (九)妨碍事故救援或者事故调查处理的。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第九十八条", "text": "特种设备的生产、使用单位或者检验检测机构，拒不接受特种设备安全监督管理部门依法实施的安全监察的，由特种设备安全监督管理部门责令限期改正；逾期未改正的，责令停产停业整顿，处2万元以上10万元以下罚款；触犯刑律的，依照刑法关于妨害公务罪或者其他罪的规定，依法追究刑事责任。 特种设备生产、使用单位擅自动用、调换、转移、损毁被查封、扣押的特种设备或者其主要部件的，由特种设备安全监督管理部门责令改正，处5万元以上20万元以下罚款；情节严重的，撤销其相应资格。 第八章 附则"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第九十九条", "text": "本条例下列用语的含义是： (一)锅炉，是指利用各种燃料、电或者其他能源，将所盛装的液体加热到一定的参数，并对外输出热能的设备，其范围规定为容积大于或者等于30L的承压蒸汽锅炉；出口水压大于或者等于0.1MPa(表压)，且额定功率大于或者等于0.1MW的承压热水锅炉；有机热载体锅炉。 (二)压力容器，是指盛装气体或者液体，承载一定压力的密闭设备，其范围规定为最高工作压力大于或者等于0.1MPa(表压)，且压力与容积的乘积大于或者等于2.5MPa·L的气体、液化气体和最高工作温度高于或者等于标准沸点的液体的固定式容器和移动式容器；盛装公称工作压力大于或者等于0.2MPa(表压)，且压力与容积的乘积大于或者等于1.0MPa·L的气体、液化气体和标准沸点等于或者低于60℃液体的气瓶；氧舱等。 (三)压力管道，是指利用一定的压力，用于输送气体或者液体的管状设备，其范围规定为最高工作压力大于或者等于0.1MPa(表压)的气体、液化气体、蒸汽介质或者可燃、易爆、有毒、有腐蚀性、最高工作温度高于或者等于标准沸点的液体介质，且公称直径大于25mm的管道。 (四)电梯，是指动力驱动，利用沿刚性导轨运行的箱体或者沿固定线路运行的梯级(踏步)，进行升降或者平行运送人、货物的机电设备，包括载人(货)电梯、自动扶梯、自动人行道等。 (五)起重机械，是指用于垂直升降或者垂直升降并水平移动重物的机电设备，其范围规定为额定起重量大于或者等于0.5t的升降机；额定起重量大于或者等于1t，且提升高度大于或者等于2m的起重机和承重形式固定的电动葫芦等。 (六)客运索道，是指动力驱动，利用柔性绳索牵引箱体等运载工具运送人员的机电设备，包括客运架空索道、客运缆车、客运拖牵索道等。 (七)大型游乐设施，是指用于经营目的，承载乘客游乐的设施，其范围规定为设计最大运行线速度大于或者等于2m/s，或者运行高度距地面高于或者等于2m的载人大型游乐设施。 (八)场(厂)内专用机动车辆，是指除道路交通、农用车辆以外仅在工厂厂区、旅游景区、游乐场所等特定区域使用的专用机动车辆。 特种设备包括其所用的材料、附属的安全附件、安全保护装置和与安全保护装置相关的设施。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第一百条", "text": "压力管道设计、安装、使用的安全监督管理办法由国务院另行制定。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第一百零一条", "text": "国务院特种设备安全监督管理部门可以授权省、自治区、直辖市特种设备安全监督管理部门负责本条例规定的特种设备行政许可工作，具体办法由国务院特种设备安全监督管理部门制定。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第一百零二条", "text": "特种设备行政许可、检验检测，应当按照国家有关规定收取费用。"}, {"law": "特种设备安全监察条例_20090124.docx", "no": "第一百零三条", "text": "本条例自2003年6月1日起施行。1982年2月6日国务院发布的《锅炉压力容器安全监察暂行条例》同时废止。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第一条", "text": "为了规范生产安全事故应急工作，保障人民群众生命和财产安全，根据《中华人民共和国安全生产法》和《中华人民共和国突发事件应对法》，制定本条例。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第二条", "text": "本条例适用于生产安全事故应急工作；法律、行政法规另有规定的，适用其规定。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第三条", "text": "国务院统一领导全国的生产安全事故应急工作，县级以上地方人民政府统一领导本行政区域内的生产安全事故应急工作。生产安全事故应急工作涉及两个以上行政区域的，由有关行政区域共同的上一级人民政府负责，或者由各有关行政区域的上一级人民政府共同负责。 县级以上人民政府应急管理部门和其他对有关行业、领域的安全生产工作实施监督管理的部门(以下统称负有安全生产监督管理职责的部门)在各自职责范围内，做好有关行业、领域的生产安全事故应急工作。 县级以上人民政府应急管理部门指导、协调本级人民政府其他负有安全生产监督管理职责的部门和下级人民政府的生产安全事故应急工作。 乡、镇人民政府以及街道办事处等地方人民政府派出机关应当协助上级人民政府有关部门依法履行生产安全事故应急工作职责。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第四条", "text": "生产经营单位应当加强生产安全事故应急工作，建立、健全生产安全事故应急工作责任制，其主要负责人对本单位的生产安全事故应急工作全面负责。 第二章 应急准备"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第五条", "text": "县级以上人民政府及其负有安全生产监督管理职责的部门和乡、镇人民政府以及街道办事处等地方人民政府派出机关，应当针对可能发生的生产安全事故的特点和危害，进行风险辨识和评估，制定相应的生产安全事故应急救援预案，并依法向社会公布。 生产经营单位应当针对本单位可能发生的生产安全事故的特点和危害，进行风险辨识和评估，制定相应的生产安全事故应急救援预案，并向本单位从业人员公布。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第六条", "text": "生产安全事故应急救援预案应当符合有关法律、法规、规章和标准的规定，具有科学性、针对性和可操作性，明确规定应急组织体系、职责分工以及应急救援程序和措施。 有下列情形之一的，生产安全事故应急救援预案制定单位应当及时修订相关预案： (一)制定预案所依据的法律、法规、规章、标准发生重大变化； (二)应急指挥机构及其职责发生调整； (三)安全生产面临的风险发生重大变化； (四)重要应急资源发生重大变化； (五)在预案演练或者应急救援中发现需要修订预案的重大问题； (六)其他应当修订的情形。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第七条", "text": "县级以上人民政府负有安全生产监督管理职责的部门应当将其制定的生产安全事故应急救援预案报送本级人民政府备案；易燃易爆物品、危险化学品等危险物品的生产、经营、储存、运输单位，矿山、金属冶炼、城市轨道交通运营、建筑施工单位，以及宾馆、商场、娱乐场所、旅游景区等人员密集场所经营单位，应当将其制定的生产安全事故应急救援预案按照国家有关规定报送县级以上人民政府负有安全生产监督管理职责的部门备案，并依法向社会公布。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第八条", "text": "县级以上地方人民政府以及县级以上人民政府负有安全生产监督管理职责的部门，乡、镇人民政府以及街道办事处等地方人民政府派出机关，应当至少每2年组织1次生产安全事故应急救援预案演练。 易燃易爆物品、危险化学品等危险物品的生产、经营、储存、运输单位，矿山、金属冶炼、城市轨道交通运营、建筑施工单位，以及宾馆、商场、娱乐场所、旅游景区等人员密集场所经营单位，应当至少每半年组织1次生产安全事故应急救援预案演练，并将演练情况报送所在地县级以上地方人民政府负有安全生产监督管理职责的部门。 县级以上地方人民政府负有安全生产监督管理职责的部门应当对本行政区域内前款规定的重点生产经营单位的生产安全事故应急救援预案演练进行抽查；发现演练不符合要求的，应当责令限期改正。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第九条", "text": "县级以上人民政府应当加强对生产安全事故应急救援队伍建设的统一规划、组织和指导。 县级以上人民政府负有安全生产监督管理职责的部门根据生产安全事故应急工作的实际需要，在重点行业、领域单独建立或者依托有条件的生产经营单位、社会组织共同建立应急救援队伍。 国家鼓励和支持生产经营单位和其他社会力量建立提供社会化应急救援服务的应急救援队伍。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第十条", "text": "易燃易爆物品、危险化学品等危险物品的生产、经营、储存、运输单位，矿山、金属冶炼、城市轨道交通运营、建筑施工单位，以及宾馆、商场、娱乐场所、旅游景区等人员密集场所经营单位，应当建立应急救援队伍；其中，小型企业或者微型企业等规模较小的生产经营单位，可以不建立应急救援队伍，但应当指定兼职的应急救援人员，并且可以与邻近的应急救援队伍签订应急救援协议。 工业园区、开发区等产业聚集区域内的生产经营单位，可以联合建立应急救援队伍。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第十一条", "text": "应急救援队伍的应急救援人员应当具备必要的专业知识、技能、身体素质和心理素质。 应急救援队伍建立单位或者兼职应急救援人员所在单位应当按照国家有关规定对应急救援人员进行培训；应急救援人员经培训合格后，方可参加应急救援工作。 应急救援队伍应当配备必要的应急救援装备和物资，并定期组织训练。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第十二条", "text": "生产经营单位应当及时将本单位应急救援队伍建立情况按照国家有关规定报送县级以上人民政府负有安全生产监督管理职责的部门，并依法向社会公布。 县级以上人民政府负有安全生产监督管理职责的部门应当定期将本行业、本领域的应急救援队伍建立情况报送本级人民政府，并依法向社会公布。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第十三条", "text": "县级以上地方人民政府应当根据本行政区域内可能发生的生产安全事故的特点和危害，储备必要的应急救援装备和物资，并及时更新和补充。 易燃易爆物品、危险化学品等危险物品的生产、经营、储存、运输单位，矿山、金属冶炼、城市轨道交通运营、建筑施工单位，以及宾馆、商场、娱乐场所、旅游景区等人员密集场所经营单位，应当根据本单位可能发生的生产安全事故的特点和危害，配备必要的灭火、排水、通风以及危险物品稀释、掩埋、收集等应急救援器材、设备和物资，并进行经常性维护、保养，保证正常运转。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第十四条", "text": "下列单位应当建立应急值班制度，配备应急值班人员： (一)县级以上人民政府及其负有安全生产监督管理职责的部门； (二)危险物品的生产、经营、储存、运输单位以及矿山、金属冶炼、城市轨道交通运营、建筑施工单位； (三)应急救援队伍。 规模较大、危险性较高的易燃易爆物品、危险化学品等危险物品的生产、经营、储存、运输单位应当成立应急处置技术组，实行24小时应急值班。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第十五条", "text": "生产经营单位应当对从业人员进行应急教育和培训，保证从业人员具备必要的应急知识，掌握风险防范技能和事故应急措施。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第十六条", "text": "国务院负有安全生产监督管理职责的部门应当按照国家有关规定建立生产安全事故应急救援信息系统，并采取有效措施，实现数据互联互通、信息共享。 生产经营单位可以通过生产安全事故应急救援信息系统办理生产安全事故应急救援预案备案手续，报送应急救援预案演练情况和应急救援队伍建设情况；但依法需要保密的除外。 第三章 应急救援"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第十七条", "text": "发生生产安全事故后，生产经营单位应当立即启动生产安全事故应急救援预案，采取下列一项或者多项应急救援措施，并按照国家有关规定报告事故情况： (一)迅速控制危险源，组织抢救遇险人员； (二)根据事故危害程度，组织现场人员撤离或者采取可能的应急措施后撤离； (三)及时通知可能受到事故影响的单位和人员； (四)采取必要措施，防止事故危害扩大和次生、衍生灾害发生； (五)根据需要请求邻近的应急救援队伍参加救援，并向参加救援的应急救援队伍提供相关技术资料、信息和处置方法； (六)维护事故现场秩序，保护事故现场和相关证据； (七)法律、法规规定的其他应急救援措施。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第十八条", "text": "有关地方人民政府及其部门接到生产安全事故报告后，应当按照国家有关规定上报事故情况，启动相应的生产安全事故应急救援预案，并按照应急救援预案的规定采取下列一项或者多项应急救援措施： (一)组织抢救遇险人员，救治受伤人员，研判事故发展趋势以及可能造成的危害； (二)通知可能受到事故影响的单位和人员，隔离事故现场，划定警戒区域，疏散受到威胁的人员，实施交通管制； (三)采取必要措施，防止事故危害扩大和次生、衍生灾害发生，避免或者减少事故对环境造成的危害； (四)依法发布调用和征用应急资源的决定； (五)依法向应急救援队伍下达救援命令； (六)维护事故现场秩序，组织安抚遇险人员和遇险遇难人员亲属； (七)依法发布有关事故情况和应急救援工作的信息； (八)法律、法规规定的其他应急救援措施。 有关地方人民政府不能有效控制生产安全事故的，应当及时向上级人民政府报告。上级人民政府应当及时采取措施，统一指挥应急救援。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第十九条", "text": "应急救援队伍接到有关人民政府及其部门的救援命令或者签有应急救援协议的生产经营单位的救援请求后，应当立即参加生产安全事故应急救援。 应急救援队伍根据救援命令参加生产安全事故应急救援所耗费用，由事故责任单位承担；事故责任单位无力承担的，由有关人民政府协调解决。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第二十条", "text": "发生生产安全事故后，有关人民政府认为有必要的，可以设立由本级人民政府及其有关部门负责人、应急救援专家、应急救援队伍负责人、事故发生单位负责人等人员组成的应急救援现场指挥部，并指定现场指挥部总指挥。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第二十一条", "text": "现场指挥部实行总指挥负责制，按照本级人民政府的授权组织制定并实施生产安全事故现场应急救援方案，协调、指挥有关单位和个人参加现场应急救援。 参加生产安全事故现场应急救援的单位和个人应当服从现场指挥部的统一指挥。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第二十二条", "text": "在生产安全事故应急救援过程中，发现可能直接危及应急救援人员生命安全的紧急情况时，现场指挥部或者统一指挥应急救援的人民政府应当立即采取相应措施消除隐患，降低或者化解风险，必要时可以暂时撤离应急救援人员。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第二十三条", "text": "生产安全事故发生地人民政府应当为应急救援人员提供必需的后勤保障，并组织通信、交通运输、医疗卫生、气象、水文、地质、电力、供水等单位协助应急救援。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第二十四条", "text": "现场指挥部或者统一指挥生产安全事故应急救援的人民政府及其有关部门应当完整、准确地记录应急救援的重要事项，妥善保存相关原始资料和证据。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第二十五条", "text": "生产安全事故的威胁和危害得到控制或者消除后，有关人民政府应当决定停止执行依照本条例和有关法律、法规采取的全部或者部分应急救援措施。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第二十六条", "text": "有关人民政府及其部门根据生产安全事故应急救援需要依法调用和征用的财产，在使用完毕或者应急救援结束后，应当及时归还。财产被调用、征用或者调用、征用后毁损、灭失的，有关人民政府及其部门应当按照国家有关规定给予补偿。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第二十七条", "text": "按照国家有关规定成立的生产安全事故调查组应当对应急救援工作进行评估，并在事故调查报告中作出评估结论。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第二十八条", "text": "县级以上地方人民政府应当按照国家有关规定，对在生产安全事故应急救援中伤亡的人员及时给予救治和抚恤；符合烈士评定条件的，按照国家有关规定评定为烈士。 第四章 法律责任"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第二十九条", "text": "地方各级人民政府和街道办事处等地方人民政府派出机关以及县级以上人民政府有关部门违反本条例规定的，由其上级行政机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第三十条", "text": "生产经营单位未制定生产安全事故应急救援预案、未定期组织应急救援预案演练、未对从业人员进行应急教育和培训，生产经营单位的主要负责人在本单位发生生产安全事故时不立即组织抢救的，由县级以上人民政府负有安全生产监督管理职责的部门依照《中华人民共和国安全生产法》有关规定追究法律责任。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第三十一条", "text": "生产经营单位未对应急救援器材、设备和物资进行经常性维护、保养，导致发生严重生产安全事故或者生产安全事故危害扩大，或者在本单位发生生产安全事故后未立即采取相应的应急救援措施，造成严重后果的，由县级以上人民政府负有安全生产监督管理职责的部门依照《中华人民共和国突发事件应对法》有关规定追究法律责任。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第三十二条", "text": "生产经营单位未将生产安全事故应急救援预案报送备案、未建立应急值班制度或者配备应急值班人员的，由县级以上人民政府负有安全生产监督管理职责的部门责令限期改正；逾期未改正的，处3万元以上5万元以下的罚款，对直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第三十三条", "text": "违反本条例规定，构成违反治安管理行为的，由公安机关依法给予处罚；构成犯罪的，依法追究刑事责任。 第五章 附则"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第三十四条", "text": "储存、使用易燃易爆物品、危险化学品等危险物品的科研机构、学校、医院等单位的安全事故应急工作，参照本条例有关规定执行。"}, {"law": "生产安全事故应急条例_20190217.docx", "no": "第三十五条", "text": "本条例自2019年4月1日起施行。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第一条", "text": "为规范生产安全事故应急预案管理工作，迅速有效处置生产安全事故，依据《中华人民共和国突发事件应对法》《中华人民共和国安全生产法》《生产安全事故应急条例》等法律、行政法规和《突发事件应急预案管理办法》（国办发〔2013〕101号），制定本办法。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第二条", "text": "生产安全事故应急预案（以下简称应急预案）的编制、评审、公布、备案、实施及监督管理工作，适用本办法。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第三条", "text": "应急预案的管理实行属地为主、分级负责、分类指导、综合协调、动态管理的原则。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第四条", "text": "应急管理部负责全国应急预案的综合协调管理工作。国务院其他负有安全生产监督管理职责的部门在各自职责范围内，负责相关行业、领域应急预案的管理工作。 县级以上地方各级人民政府应急管理部门负责本行政区域内应急预案的综合协调管理工作。县级以上地方各级人民政府其他负有安全生产监督管理职责的部门按照各自的职责负责有关行业、领域应急预案的管理工作。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第五条", "text": "生产经营单位主要负责人负责组织编制和实施本单位的应急预案，并对应急预案的真实性和实用性负责；各分管负责人应当按照职责分工落实应急预案规定的职责。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第六条", "text": "生产经营单位应急预案分为综合应急预案、专项应急预案和现场处置方案。 综合应急预案，是指生产经营单位为应对各种生产安全事故而制定的综合性工作方案，是本单位应对生产安全事故的总体工作程序、措施和应急预案体系的总纲。 专项应急预案，是指生产经营单位为应对某一种或者多种类型生产安全事故，或者针对重要生产设施、重大危险源、重大活动防止生产安全事故而制定的专项性工作方案。 现场处置方案，是指生产经营单位根据不同生产安全事故类型，针对具体场所、装置或者设施所制定的应急处置措施。 第二章 应急预案的编制"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第七条", "text": "应急预案的编制应当遵循以人为本、依法依规、符合实际、注重实效的原则，以应急处置为核心，明确应急职责、规范应急程序、细化保障措施。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第八条", "text": "应急预案的编制应当符合下列基本要求： （一）有关法律、法规、规章和标准的规定； （二）本地区、本部门、本单位的安全生产实际情况； （三）本地区、本部门、本单位的危险性分析情况； （四）应急组织和人员的职责分工明确，并有具体的落实措施； （五）有明确、具体的应急程序和处置措施，并与其应急能力相适应； （六）有明确的应急保障措施，满足本地区、本部门、本单位的应急工作需要； （七）应急预案基本要素齐全、完整，应急预案附件提供的信息准确； （八）应急预案内容与相关应急预案相互衔接。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第九条", "text": "编制应急预案应当成立编制工作小组，由本单位有关负责人任组长，吸收与应急预案有关的职能部门和单位的人员，以及有现场处置经验的人员参加。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第十条", "text": "编制应急预案前，编制单位应当进行事故风险辨识、评估和应急资源调查。 事故风险辨识、评估，是指针对不同事故种类及特点，识别存在的危险危害因素，分析事故可能产生的直接后果以及次生、衍生后果，评估各种后果的危害程度和影响范围，提出防范和控制事故风险措施的过程。 应急资源调查，是指全面调查本地区、本单位第一时间可以调用的应急资源状况和合作区域内可以请求援助的应急资源状况，并结合事故风险辨识评估结论制定应急措施的过程。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第十一条", "text": "地方各级人民政府应急管理部门和其他负有安全生产监督管理职责的部门应当根据法律、法规、规章和同级人民政府以及上一级人民政府应急管理部门和其他负有安全生产监督管理职责的部门的应急预案，结合工作实际，组织编制相应的部门应急预案。 部门应急预案应当根据本地区、本部门的实际情况，明确信息报告、响应分级、指挥权移交、警戒疏散等内容。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第十二条", "text": "生产经营单位应当根据有关法律、法规、规章和相关标准，结合本单位组织管理体系、生产规模和可能发生的事故特点，与相关预案保持衔接，确立本单位的应急预案体系，编制相应的应急预案，并体现自救互救和先期处置等特点。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第十三条", "text": "生产经营单位风险种类多、可能发生多种类型事故的，应当组织编制综合应急预案。 综合应急预案应当规定应急组织机构及其职责、应急预案体系、事故风险描述、预警及信息报告、应急响应、保障措施、应急预案管理等内容。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第十四条", "text": "对于某一种或者多种类型的事故风险，生产经营单位可以编制相应的专项应急预案，或将专项应急预案并入综合应急预案。 专项应急预案应当规定应急指挥机构与职责、处置程序和措施等内容。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第十五条", "text": "对于危险性较大的场所、装置或者设施，生产经营单位应当编制现场处置方案。 现场处置方案应当规定应急工作职责、应急处置措施和注意事项等内容。 事故风险单一、危险性小的生产经营单位，可以只编制现场处置方案。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第十六条", "text": "生产经营单位应急预案应当包括向上级应急管理机构报告的内容、应急组织机构和人员的联系方式、应急物资储备清单等附件信息。附件信息发生变化时，应当及时更新，确保准确有效。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第十七条", "text": "生产经营单位组织应急预案编制过程中，应当根据法律、法规、规章的规定或者实际需要，征求相关应急救援队伍、公民、法人或其他组织的意见。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第十八条", "text": "生产经营单位编制的各类应急预案之间应当相互衔接，并与相关人民政府及其部门、应急救援队伍和涉及的其他单位的应急预案相衔接。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第十九条", "text": "生产经营单位应当在编制应急预案的基础上，针对工作场所、岗位的特点，编制简明、实用、有效的应急处置卡。 应急处置卡应当规定重点岗位、人员的应急处置程序和措施，以及相关联络人员和联系方式，便于从业人员携带。 第三章 应急预案的评审、公布和备案"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第二十条", "text": "地方各级人民政府应急管理部门应当组织有关专家对本部门编制的部门应急预案进行审定；必要时，可以召开听证会，听取社会有关方面的意见。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第二十一条", "text": "矿山、金属冶炼企业和易燃易爆物品、危险化学品的生产、经营（带储存设施的，下同）、储存、运输企业，以及使用危险化学品达到国家规定数量的化工企业、烟花爆竹生产、批发经营企业和中型规模以上的其他生产经营单位，应当对本单位编制的应急预案进行评审，并形成书面评审纪要。 前款规定以外的其他生产经营单位可以根据自身需要，对本单位编制的应急预案进行论证。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第二十二条", "text": "参加应急预案评审的人员应当包括有关安全生产及应急管理方面的专家。 评审人员与所评审应急预案的生产经营单位有利害关系的，应当回避。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第二十三条", "text": "应急预案的评审或者论证应当注重基本要素的完整性、组织体系的合理性、应急处置程序和措施的针对性、应急保障措施的可行性、应急预案的衔接性等内容。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第二十四条", "text": "生产经营单位的应急预案经评审或者论证后，由本单位主要负责人签署，向本单位从业人员公布，并及时发放到本单位有关部门、岗位和相关应急救援队伍。 事故风险可能影响周边其他单位、人员的，生产经营单位应当将有关事故风险的性质、影响范围和应急防范措施告知周边的其他单位和人员。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第二十五条", "text": "地方各级人民政府应急管理部门的应急预案，应当报同级人民政府备案，同时抄送上一级人民政府应急管理部门，并依法向社会公布。 地方各级人民政府其他负有安全生产监督管理职责的部门的应急预案，应当抄送同级人民政府应急管理部门。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第二十六条", "text": "易燃易爆物品、危险化学品等危险物品的生产、经营、储存、运输单位，矿山、金属冶炼、城市轨道交通运营、建筑施工单位，以及宾馆、商场、娱乐场所、旅游景区等人员密集场所经营单位，应当在应急预案公布之日起20个工作日内，按照分级属地原则，向县级以上人民政府应急管理部门和其他负有安全生产监督管理职责的部门进行备案，并依法向社会公布。 前款所列单位属于中央企业的，其总部（上市公司）的应急预案，报国务院主管的负有安全生产监督管理职责的部门备案，并抄送应急管理部；其所属单位的应急预案报所在地的省、自治区、直辖市或者设区的市级人民政府主管的负有安全生产监督管理职责的部门备案，并抄送同级人民政府应急管理部门。 本条第一款所列单位不属于中央企业的，其中非煤矿山、金属冶炼和危险化学品生产、经营、储存、运输企业，以及使用危险化学品达到国家规定数量的化工企业、烟花爆竹生产、批发经营企业的应急预案，按照隶属关系报所在地县级以上地方人民政府应急管理部门备案；本款前述单位以外的其他生产经营单位应急预案的备案，由省、自治区、直辖市人民政府负有安全生产监督管理职责的部门确定。 油气输送管道运营单位的应急预案，除按照本条第一款、第二款的规定备案外，还应当抄送所经行政区域的县级人民政府应急管理部门。 海洋石油开采企业的应急预案，除按照本条第一款、第二款的规定备案外，还应当抄送所经行政区域的县级人民政府应急管理部门和海洋石油安全监管机构。 煤矿企业的应急预案除按照本条第一款、第二款的规定备案外，还应当抄送所在地的煤矿安全监察机构。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第二十七条", "text": "生产经营单位申报应急预案备案，应当提交下列材料： （一）应急预案备案申报表； （二）本办法"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第二十一条", "text": "所列单位，应当提供应急预案评审意见； （三）应急预案电子文档； （四）风险评估结果和应急资源调查清单。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第二十八条", "text": "受理备案登记的负有安全生产监督管理职责的部门应当在5个工作日内对应急预案材料进行核对，材料齐全的，应当予以备案并出具应急预案备案登记表；材料不齐全的，不予备案并一次性告知需要补齐的材料。逾期不予备案又不说明理由的，视为已经备案。 对于实行安全生产许可的生产经营单位，已经进行应急预案备案的，在申请安全生产许可证时，可以不提供相应的应急预案，仅提供应急预案备案登记表。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第二十九条", "text": "各级人民政府负有安全生产监督管理职责的部门应当建立应急预案备案登记建档制度，指导、督促生产经营单位做好应急预案的备案登记工作。 第四章 应急预案的实施"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第三十条", "text": "各级人民政府应急管理部门、各类生产经营单位应当采取多种形式开展应急预案的宣传教育，普及生产安全事故避险、自救和互救知识，提高从业人员和社会公众的安全意识与应急处置技能。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第三十一条", "text": "各级人民政府应急管理部门应当将本部门应急预案的培训纳入安全生产培训工作计划，并组织实施本行政区域内重点生产经营单位的应急预案培训工作。 生产经营单位应当组织开展本单位的应急预案、应急知识、自救互救和避险逃生技能的培训活动，使有关人员了解应急预案内容，熟悉应急职责、应急处置程序和措施。 应急培训的时间、地点、内容、师资、参加人员和考核结果等情况应当如实记入本单位的安全生产教育和培训档案。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第三十二条", "text": "各级人民政府应急管理部门应当至少每两年组织一次应急预案演练，提高本部门、本地区生产安全事故应急处置能力。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第三十三条", "text": "生产经营单位应当制定本单位的应急预案演练计划，根据本单位的事故风险特点，每年至少组织一次综合应急预案演练或者专项应急预案演练，每半年至少组织一次现场处置方案演练。 易燃易爆物品、危险化学品等危险物品的生产、经营、储存、运输单位，矿山、金属冶炼、城市轨道交通运营、建筑施工单位，以及宾馆、商场、娱乐场所、旅游景区等人员密集场所经营单位，应当至少每半年组织一次生产安全事故应急预案演练，并将演练情况报送所在地县级以上地方人民政府负有安全生产监督管理职责的部门。 县级以上地方人民政府负有安全生产监督管理职责的部门应当对本行政区域内前款规定的重点生产经营单位的生产安全事故应急救援预案演练进行抽查；发现演练不符合要求的，应当责令限期改正。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第三十四条", "text": "应急预案演练结束后，应急预案演练组织单位应当对应急预案演练效果进行评估，撰写应急预案演练评估报告，分析存在的问题，并对应急预案提出修订意见。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第三十五条", "text": "应急预案编制单位应当建立应急预案定期评估制度，对预案内容的针对性和实用性进行分析，并对应急预案是否需要修订作出结论。 矿山、金属冶炼、建筑施工企业和易燃易爆物品、危险化学品等危险物品的生产、经营、储存、运输企业、使用危险化学品达到国家规定数量的化工企业、烟花爆竹生产、批发经营企业和中型规模以上的其他生产经营单位，应当每三年进行一次应急预案评估。 应急预案评估可以邀请相关专业机构或者有关专家、有实际应急救援工作经验的人员参加，必要时可以委托安全生产技术服务机构实施。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第三十六条", "text": "有下列情形之一的，应急预案应当及时修订并归档： （一）依据的法律、法规、规章、标准及上位预案中的有关规定发生重大变化的； （二）应急指挥机构及其职责发生调整的； （三）安全生产面临的风险发生重大变化的； （四）重要应急资源发生重大变化的； （五）在应急演练和事故应急救援中发现需要修订预案的重大问题的； （六）编制单位认为应当修订的其他情况。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第三十七条", "text": "应急预案修订涉及组织指挥体系与职责、应急处置程序、主要处置措施、应急响应分级等内容变更的，修订工作应当参照本办法规定的应急预案编制程序进行，并按照有关应急预案报备程序重新备案。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第三十八条", "text": "生产经营单位应当按照应急预案的规定，落实应急指挥体系、应急救援队伍、应急物资及装备，建立应急物资、装备配备及其使用档案，并对应急物资、装备进行定期检测和维护，使其处于适用状态。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第三十九条", "text": "生产经营单位发生事故时，应当第一时间启动应急响应，组织有关力量进行救援，并按照规定将事故信息及应急响应启动情况报告事故发生地县级以上人民政府应急管理部门和其他负有安全生产监督管理职责的部门。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第四十条", "text": "生产安全事故应急处置和应急救援结束后，事故发生单位应当对应急预案实施情况进行总结评估。 第五章 监督管理"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第四十一条", "text": "各级人民政府应急管理部门和煤矿安全监察机构应当将生产经营单位应急预案工作纳入年度监督检查计划，明确检查的重点内容和标准，并严格按照计划开展执法检查。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第四十二条", "text": "地方各级人民政府应急管理部门应当每年对应急预案的监督管理工作情况进行总结，并报上一级人民政府应急管理部门。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第四十三条", "text": "对于在应急预案管理工作中做出显著成绩的单位和人员，各级人民政府应急管理部门、生产经营单位可以给予表彰和奖励。 第六章 法律责任"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第四十四条", "text": "生产经营单位有下列情形之一的，由县级以上人民政府应急管理等部门依照《中华人民共和国安全生产法》"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第九十四条", "text": "的规定，责令限期改正，可以处5万元以下罚款；逾期未改正的，责令停产停业整顿，并处5万元以上10万元以下的罚款，对直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款： （一）未按照规定编制应急预案的； （二）未按照规定定期组织应急预案演练的。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第四十五条", "text": "生产经营单位有下列情形之一的，由县级以上人民政府应急管理部门责令限期改正，可以处1万元以上3万元以下罚款： （一）在应急预案编制前未按照规定开展风险辨识、评估和应急资源调查的； （二）未按照规定开展应急预案评审的； （三）事故风险可能影响周边单位、人员的，未将事故风险的性质、影响范围和应急防范措施告知周边单位和人员的； （四）未按照规定开展应急预案评估的； （五）未按照规定进行应急预案修订的； （六）未落实应急预案规定的应急物资及装备的。 生产经营单位未按照规定进行应急预案备案的，由县级以上人民政府应急管理等部门依照职责责令限期改正；逾期未改正的，处3万元以上5万元以下的罚款，对直接负责的主管人员和其他直接责任人员处1万元以上2万元以下的罚款。 第七章 附 则"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第四十六条", "text": "《生产经营单位生产安全事故应急预案备案申报表》和《生产经营单位生产安全事故应急预案备案登记表》由应急管理部统一制定。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第四十七条", "text": "各省、自治区、直辖市应急管理部门可以依据本办法的规定，结合本地区实际制定实施细则。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第四十八条", "text": "对储存、使用易燃易爆物品、危险化学品等危险物品的科研机构、学校、医院等单位的安全事故应急预案的管理，参照本办法的有关规定执行。"}, {"law": "生产安全事故应急预案管理办法_20190711.docx", "no": "第四十九条", "text": "本办法自2016年7月1日起施行。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第一条", "text": "为了规范生产安全事故的报告和调查处理，落实生产安全事故责任追究制度，防止和减少生产安全事故，根据《中华人民共和国安全生产法》和有关法律，制定本条例。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第二条", "text": "生产经营活动中发生的造成人身伤亡或者直接经济损失的生产安全事故的报告和调查处理，适用本条例；环境污染事故、核设施事故、国防科研生产事故的报告和调查处理不适用本条例。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第三条", "text": "根据生产安全事故(以下简称事故)造成的人员伤亡或者直接经济损失，事故一般分为以下等级： (一)特别重大事故，是指造成30人以上死亡，或者100人以上重伤(包括急性工业中毒，下同)，或者1亿元以上直接经济损失的事故； (二)重大事故，是指造成10人以上30人以下死亡，或者50人以上100人以下重伤，或者5000万元以上1亿元以下直接经济损失的事故； (三)较大事故，是指造成3人以上10人以下死亡，或者10人以上50人以下重伤，或者1000万元以上5000万元以下直接经济损失的事故； (四)一般事故，是指造成3人以下死亡，或者10人以下重伤，或者1000万元以下直接经济损失的事故。 国务院安全生产监督管理部门可以会同国务院有关部门，制定事故等级划分的补充性规定。 本条第一款所称的“以上”包括本数，所称的“以下”不包括本数。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第四条", "text": "事故报告应当及时、准确、完整，任何单位和个人对事故不得迟报、漏报、谎报或者瞒报。 事故调查处理应当坚持实事求是、尊重科学的原则，及时、准确地查清事故经过、事故原因和事故损失，查明事故性质，认定事故责任，总结事故教训，提出整改措施，并对事故责任者依法追究责任。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第五条", "text": "县级以上人民政府应当依照本条例的规定，严格履行职责，及时、准确地完成事故调查处理工作。 事故发生地有关地方人民政府应当支持、配合上级人民政府或者有关部门的事故调查处理工作，并提供必要的便利条件。 参加事故调查处理的部门和单位应当互相配合，提高事故调查处理工作的效率。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第六条", "text": "工会依法参加事故调查处理，有权向有关部门提出处理意见。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第七条", "text": "任何单位和个人不得阻挠和干涉对事故的报告和依法调查处理。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第八条", "text": "对事故报告和调查处理中的违法行为，任何单位和个人有权向安全生产监督管理部门、监察机关或者其他有关部门举报，接到举报的部门应当依法及时处理。 第二章 事故报告"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第九条", "text": "事故发生后，事故现场有关人员应当立即向本单位负责人报告；单位负责人接到报告后，应当于1小时内向事故发生地县级以上人民政府安全生产监督管理部门和负有安全生产监督管理职责的有关部门报告。 情况紧急时，事故现场有关人员可以直接向事故发生地县级以上人民政府安全生产监督管理部门和负有安全生产监督管理职责的有关部门报告。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第十条", "text": "安全生产监督管理部门和负有安全生产监督管理职责的有关部门接到事故报告后，应当依照下列规定上报事故情况，并通知公安机关、劳动保障行政部门、工会和人民检察院： (一)特别重大事故、重大事故逐级上报至国务院安全生产监督管理部门和负有安全生产监督管理职责的有关部门； (二)较大事故逐级上报至省、自治区、直辖市人民政府安全生产监督管理部门和负有安全生产监督管理职责的有关部门； (三)一般事故上报至设区的市级人民政府安全生产监督管理部门和负有安全生产监督管理职责的有关部门。 安全生产监督管理部门和负有安全生产监督管理职责的有关部门依照前款规定上报事故情况，应当同时报告本级人民政府。国务院安全生产监督管理部门和负有安全生产监督管理职责的有关部门以及省级人民政府接到发生特别重大事故、重大事故的报告后，应当立即报告国务院。 必要时，安全生产监督管理部门和负有安全生产监督管理职责的有关部门可以越级上报事故情况。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第十一条", "text": "安全生产监督管理部门和负有安全生产监督管理职责的有关部门逐级上报事故情况，每级上报的时间不得超过2小时。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第十二条", "text": "报告事故应当包括下列内容： (一)事故发生单位概况； (二)事故发生的时间、地点以及事故现场情况； (三)事故的简要经过； (四)事故已经造成或者可能造成的伤亡人数(包括下落不明的人数)和初步估计的直接经济损失； (五)已经采取的措施； (六)其他应当报告的情况。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第十三条", "text": "事故报告后出现新情况的，应当及时补报。 自事故发生之日起30日内，事故造成的伤亡人数发生变化的，应当及时补报。道路交通事故、火灾事故自发生之日起7日内，事故造成的伤亡人数发生变化的，应当及时补报。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第十四条", "text": "事故发生单位负责人接到事故报告后，应当立即启动事故相应应急预案，或者采取有效措施，组织抢救，防止事故扩大，减少人员伤亡和财产损失。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第十五条", "text": "事故发生地有关地方人民政府、安全生产监督管理部门和负有安全生产监督管理职责的有关部门接到事故报告后，其负责人应当立即赶赴事故现场，组织事故救援。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第十六条", "text": "事故发生后，有关单位和人员应当妥善保护事故现场以及相关证据，任何单位和个人不得破坏事故现场、毁灭相关证据。 因抢救人员、防止事故扩大以及疏通交通等原因，需要移动事故现场物件的，应当做出标志，绘制现场简图并做出书面记录，妥善保存现场重要痕迹、物证。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第十七条", "text": "事故发生地公安机关根据事故的情况，对涉嫌犯罪的，应当依法立案侦查，采取强制措施和侦查措施。犯罪嫌疑人逃匿的，公安机关应当迅速追捕归案。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第十八条", "text": "安全生产监督管理部门和负有安全生产监督管理职责的有关部门应当建立值班制度，并向社会公布值班电话，受理事故报告和举报。 第三章 事故调查"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第十九条", "text": "特别重大事故由国务院或者国务院授权有关部门组织事故调查组进行调查。 重大事故、较大事故、一般事故分别由事故发生地省级人民政府、设区的市级人民政府、县级人民政府负责调查。省级人民政府、设区的市级人民政府、县级人民政府可以直接组织事故调查组进行调查，也可以授权或者委托有关部门组织事故调查组进行调查。 未造成人员伤亡的一般事故，县级人民政府也可以委托事故发生单位组织事故调查组进行调查。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第二十条", "text": "上级人民政府认为必要时，可以调查由下级人民政府负责调查的事故。 自事故发生之日起30日内(道路交通事故、火灾事故自发生之日起7日内)，因事故伤亡人数变化导致事故等级发生变化，依照本条例规定应当由上级人民政府负责调查的，上级人民政府可以另行组织事故调查组进行调查。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第二十一条", "text": "特别重大事故以下等级事故，事故发生地与事故发生单位不在同一个县级以上行政区域的，由事故发生地人民政府负责调查，事故发生单位所在地人民政府应当派人参加。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第二十二条", "text": "事故调查组的组成应当遵循精简、效能的原则。 根据事故的具体情况，事故调查组由有关人民政府、安全生产监督管理部门、负有安全生产监督管理职责的有关部门、监察机关、公安机关以及工会派人组成，并应当邀请人民检察院派人参加。 事故调查组可以聘请有关专家参与调查。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第二十三条", "text": "事故调查组成员应当具有事故调查所需要的知识和专长，并与所调查的事故没有直接利害关系。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第二十四条", "text": "事故调查组组长由负责事故调查的人民政府指定。事故调查组组长主持事故调查组的工作。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第二十五条", "text": "事故调查组履行下列职责： (一)查明事故发生的经过、原因、人员伤亡情况及直接经济损失； (二)认定事故的性质和事故责任； (三)提出对事故责任者的处理建议； (四)总结事故教训，提出防范和整改措施； (五)提交事故调查报告。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第二十六条", "text": "事故调查组有权向有关单位和个人了解与事故有关的情况，并要求其提供相关文件、资料，有关单位和个人不得拒绝。 事故发生单位的负责人和有关人员在事故调查期间不得擅离职守，并应当随时接受事故调查组的询问，如实提供有关情况。 事故调查中发现涉嫌犯罪的，事故调查组应当及时将有关材料或者其复印件移交司法机关处理。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第二十七条", "text": "事故调查中需要进行技术鉴定的，事故调查组应当委托具有国家规定资质的单位进行技术鉴定。必要时，事故调查组可以直接组织专家进行技术鉴定。技术鉴定所需时间不计入事故调查期限。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第二十八条", "text": "事故调查组成员在事故调查工作中应当诚信公正、恪尽职守，遵守事故调查组的纪律，保守事故调查的秘密。 未经事故调查组组长允许，事故调查组成员不得擅自发布有关事故的信息。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第二十九条", "text": "事故调查组应当自事故发生之日起60日内提交事故调查报告；特殊情况下，经负责事故调查的人民政府批准，提交事故调查报告的期限可以适当延长，但延长的期限最长不超过60日。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第三十条", "text": "事故调查报告应当包括下列内容： (一)事故发生单位概况； (二)事故发生经过和事故救援情况； (三)事故造成的人员伤亡和直接经济损失； (四)事故发生的原因和事故性质； (五)事故责任的认定以及对事故责任者的处理建议； (六)事故防范和整改措施。 事故调查报告应当附具有关证据材料。事故调查组成员应当在事故调查报告上签名。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第三十一条", "text": "事故调查报告报送负责事故调查的人民政府后，事故调查工作即告结束。事故调查的有关资料应当归档保存。 第四章 事故处理"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第三十二条", "text": "重大事故、较大事故、一般事故，负责事故调查的人民政府应当自收到事故调查报告之日起15日内做出批复；特别重大事故，30日内做出批复，特殊情况下，批复时间可以适当延长，但延长的时间最长不超过30日。 有关机关应当按照人民政府的批复，依照法律、行政法规规定的权限和程序，对事故发生单位和有关人员进行行政处罚，对负有事故责任的国家工作人员进行处分。 事故发生单位应当按照负责事故调查的人民政府的批复，对本单位负有事故责任的人员进行处理。 负有事故责任的人员涉嫌犯罪的，依法追究刑事责任。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第三十三条", "text": "事故发生单位应当认真吸取事故教训，落实防范和整改措施，防止事故再次发生。防范和整改措施的落实情况应当接受工会和职工的监督。 安全生产监督管理部门和负有安全生产监督管理职责的有关部门应当对事故发生单位落实防范和整改措施的情况进行监督检查。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第三十四条", "text": "事故处理的情况由负责事故调查的人民政府或者其授权的有关部门、机构向社会公布，依法应当保密的除外。 第五章 法律责任"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第三十五条", "text": "事故发生单位主要负责人有下列行为之一的，处上一年年收入40%至80%的罚款；属于国家工作人员的，并依法给予处分；构成犯罪的，依法追究刑事责任： (一)不立即组织事故抢救的； (二)迟报或者漏报事故的； (三)在事故调查处理期间擅离职守的。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第三十六条", "text": "事故发生单位及其有关人员有下列行为之一的，对事故发生单位处100万元以上500万元以下的罚款；对主要负责人、直接负责的主管人员和其他直接责任人员处上一年年收入60%至100%的罚款；属于国家工作人员的，并依法给予处分；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任： (一)谎报或者瞒报事故的； (二)伪造或者故意破坏事故现场的； (三)转移、隐匿资金、财产，或者销毁有关证据、资料的； (四)拒绝接受调查或者拒绝提供有关情况和资料的； (五)在事故调查中作伪证或者指使他人作伪证的； (六)事故发生后逃匿的。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第三十七条", "text": "事故发生单位对事故发生负有责任的，依照下列规定处以罚款： (一)发生一般事故的，处10万元以上20万元以下的罚款； (二)发生较大事故的，处20万元以上50万元以下的罚款； (三)发生重大事故的，处50万元以上200万元以下的罚款； (四)发生特别重大事故的，处200万元以上500万元以下的罚款。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第三十八条", "text": "事故发生单位主要负责人未依法履行安全生产管理职责，导致事故发生的，依照下列规定处以罚款；属于国家工作人员的，并依法给予处分；构成犯罪的，依法追究刑事责任： (一)发生一般事故的，处上一年年收入30%的罚款； (二)发生较大事故的，处上一年年收入40%的罚款； (三)发生重大事故的，处上一年年收入60%的罚款； (四)发生特别重大事故的，处上一年年收入80%的罚款。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第三十九条", "text": "有关地方人民政府、安全生产监督管理部门和负有安全生产监督管理职责的有关部门有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任： (一)不立即组织事故抢救的； (二)迟报、漏报、谎报或者瞒报事故的； (三)阻碍、干涉事故调查工作的； (四)在事故调查中作伪证或者指使他人作伪证的。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第四十条", "text": "事故发生单位对事故发生负有责任的，由有关部门依法暂扣或者吊销其有关证照；对事故发生单位负有事故责任的有关人员，依法暂停或者撤销其与安全生产有关的执业资格、岗位证书；事故发生单位主要负责人受到刑事处罚或者撤职处分的，自刑罚执行完毕或者受处分之日起，5年内不得担任任何生产经营单位的主要负责人。 为发生事故的单位提供虚假证明的中介机构，由有关部门依法暂扣或者吊销其有关证照及其相关人员的执业资格；构成犯罪的，依法追究刑事责任。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第四十一条", "text": "参与事故调查的人员在事故调查中有下列行为之一的，依法给予处分；构成犯罪的，依法追究刑事责任： (一)对事故调查工作不负责任，致使事故调查工作有重大疏漏的； (二)包庇、袒护负有事故责任的人员或者借机打击报复的。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第四十二条", "text": "违反本条例规定，有关地方人民政府或者有关部门故意拖延或者拒绝落实经批复的对事故责任人的处理意见的，由监察机关对有关责任人员依法给予处分。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第四十三条", "text": "本条例规定的罚款的行政处罚，由安全生产监督管理部门决定。 法律、行政法规对行政处罚的种类、幅度和决定机关另有规定的，依照其规定。 第六章 附则"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第四十四条", "text": "没有造成人员伤亡，但是社会影响恶劣的事故，国务院或者有关地方人民政府认为需要调查处理的，依照本条例的有关规定执行。 国家机关、事业单位、人民团体发生的事故的报告和调查处理，参照本条例的规定执行。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第四十五条", "text": "特别重大事故以下等级事故的报告和调查处理，有关法律、行政法规或者国务院另有规定的，依照其规定。"}, {"law": "生产安全事故报告和调查处理条例_20070409.docx", "no": "第四十六条", "text": "本条例自2007年6月1日起施行。国务院1989年3月29日公布的《特别重大事故调查程序暂行规定》和1991年2月22日公布的《企业职工伤亡事故报告和处理规定》同时废止。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第一条", "text": "为防止和减少生产安全事故，严格追究生产安全事故发生单位及其有关责任人员的法律责任，正确适用事故罚款的行政处罚，依照《中华人民共和国行政处罚法》《中华人民共和国安全生产法》《生产安全事故报告和调查处理条例》等规定，制定本规定。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第二条", "text": "应急管理部门和矿山安全监察机构对生产安全事故发生单位（以下简称事故发生单位）及其主要负责人、其他负责人、安全生产管理人员以及直接负责的主管人员、其他直接责任人员等有关责任人员依照《中华人民共和国安全生产法》和《生产安全事故报告和调查处理条例》实施罚款的行政处罚，适用本规定。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第三条", "text": "本规定所称事故发生单位是指对事故发生负有责任的生产经营单位。 本规定所称主要负责人是指有限责任公司、股份有限公司的董事长、总经理或者个人经营的投资人，其他生产经营单位的厂长、经理、矿长（含实际控制人）等人员。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第四条", "text": "本规定所称事故发生单位主要负责人、其他负责人、安全生产管理人员以及直接负责的主管人员、其他直接责任人员的上一年年收入，属于国有生产经营单位的，是指该单位上级主管部门所确定的上一年年收入总额；属于非国有生产经营单位的，是指经财务、税务部门核定的上一年年收入总额。 生产经营单位提供虚假资料或者由于财务、税务部门无法核定等原因致使有关人员的上一年年收入难以确定的，按照下列办法确定： （一）主要负责人的上一年年收入，按照本省、自治区、直辖市上一年度城镇单位就业人员平均工资的5倍以上10倍以下计算； （二）其他负责人、安全生产管理人员以及直接负责的主管人员、其他直接责任人员的上一年年收入，按照本省、自治区、直辖市上一年度城镇单位就业人员平均工资的1倍以上5倍以下计算。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第五条", "text": "《生产安全事故报告和调查处理条例》所称的迟报、漏报、谎报和瞒报，依照下列情形认定： （一）报告事故的时间超过规定时限的，属于迟报； （二）因过失对应当上报的事故或者事故发生的时间、地点、类别、伤亡人数、直接经济损失等内容遗漏未报的，属于漏报； （三）故意不如实报告事故发生的时间、地点、初步原因、性质、伤亡人数和涉险人数、直接经济损失等有关内容的，属于谎报； （四）隐瞒已经发生的事故，超过规定时限未向应急管理部门、矿山安全监察机构和有关部门报告，经查证属实的，属于瞒报。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第六条", "text": "对事故发生单位及其有关责任人员处以罚款的行政处罚，依照下列规定决定： （一）对发生特别重大事故的单位及其有关责任人员罚款的行政处罚，由应急管理部决定； （二）对发生重大事故的单位及其有关责任人员罚款的行政处罚，由省级人民政府应急管理部门决定； （三）对发生较大事故的单位及其有关责任人员罚款的行政处罚，由设区的市级人民政府应急管理部门决定； （四）对发生一般事故的单位及其有关责任人员罚款的行政处罚，由县级人民政府应急管理部门决定。 上级应急管理部门可以指定下一级应急管理部门对事故发生单位及其有关责任人员实施行政处罚。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第七条", "text": "对煤矿事故发生单位及其有关责任人员处以罚款的行政处罚，依照下列规定执行： （一）对发生特别重大事故的煤矿及其有关责任人员罚款的行政处罚，由国家矿山安全监察局决定； （二）对发生重大事故、较大事故和一般事故的煤矿及其有关责任人员罚款的行政处罚，由国家矿山安全监察局省级局决定。 上级矿山安全监察机构可以指定下一级矿山安全监察机构对事故发生单位及其有关责任人员实施行政处罚。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第八条", "text": "特别重大事故以下等级事故，事故发生地与事故发生单位所在地不在同一个县级以上行政区域的，由事故发生地的应急管理部门或者矿山安全监察机构依照本规定"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第七条", "text": "规定的权限实施行政处罚。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第九条", "text": "应急管理部门和矿山安全监察机构对事故发生单位及其有关责任人员实施罚款的行政处罚，依照《中华人民共和国行政处罚法》《安全生产违法行为行政处罚办法》等规定的程序执行。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第十条", "text": "应急管理部门和矿山安全监察机构在作出行政处罚前，应当告知当事人依法享有的陈述、申辩、要求听证等权利；当事人对行政处罚不服的，有权依法申请行政复议或者提起行政诉讼。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第十一条", "text": "事故发生单位主要负责人有《中华人民共和国安全生产法》"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第一百一十条", "text": "、《生产安全事故报告和调查处理条例》"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第三十六条", "text": "规定的下列行为之一的，依照下列规定处以罚款： （一）事故发生单位主要负责人在事故发生后不立即组织事故抢救，或者在事故调查处理期间擅离职守，或者瞒报、谎报、迟报事故，或者事故发生后逃匿的，处上一年年收入60%至80％的罚款；贻误事故抢救或者造成事故扩大或者影响事故调查或者造成重大社会影响的，处上一年年收入80%至100％的罚款； （二）事故发生单位主要负责人漏报事故的，处上一年年收入40%至60％的罚款；贻误事故抢救或者造成事故扩大或者影响事故调查或者造成重大社会影响的，处上一年年收入60%至80％的罚款； （三）事故发生单位主要负责人伪造、故意破坏事故现场，或者转移、隐匿资金、财产、销毁有关证据、资料，或者拒绝接受调查，或者拒绝提供有关情况和资料，或者在事故调查中作伪证，或者指使他人作伪证的，处上一年年收入60%至80％的罚款；贻误事故抢救或者造成事故扩大或者影响事故调查或者造成重大社会影响的，处上一年年收入80%至100％的罚款。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第十二条", "text": "事故发生单位直接负责的主管人员和其他直接责任人员有《生产安全事故报告和调查处理条例》"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第三十六条", "text": "规定的行为之一的，处上一年年收入60%至80％的罚款；贻误事故抢救或者造成事故扩大或者影响事故调查或者造成重大社会影响的，处上一年年收入80%至100％的罚款。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第十三条", "text": "事故发生单位有《生产安全事故报告和调查处理条例》"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第三十六条", "text": "第一项至第五项规定的行为之一的，依照下列规定处以罚款： （一）发生一般事故的，处100万元以上150万元以下的罚款； （二）发生较大事故的，处150万元以上200万元以下的罚款； （三）发生重大事故的，处200万元以上250万元以下的罚款； （四）发生特别重大事故的，处250万元以上300万元以下的罚款。 事故发生单位有《生产安全事故报告和调查处理条例》"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第三十六条", "text": "第一项至第五项规定的行为之一的，贻误事故抢救或者造成事故扩大或者影响事故调查或者造成重大社会影响的，依照下列规定处以罚款： （一）发生一般事故的，处300万元以上350万元以下的罚款； （二）发生较大事故的，处350万元以上400万元以下的罚款； （三）发生重大事故的，处400万元以上450万元以下的罚款； （四）发生特别重大事故的，处450万元以上500万元以下的罚款。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第十四条", "text": "事故发生单位对一般事故负有责任的，依照下列规定处以罚款： （一）造成3人以下重伤（包括急性工业中毒，下同），或者300万元以下直接经济损失的，处30万元以上50万元以下的罚款； （二）造成1人死亡，或者3人以上6人以下重伤，或者300万元以上500万元以下直接经济损失的，处50万元以上70万元以下的罚款； （三）造成2人死亡，或者6人以上10人以下重伤，或者500万元以上1000万元以下直接经济损失的，处70万元以上100万元以下的罚款。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第十五条", "text": "事故发生单位对较大事故发生负有责任的，依照下列规定处以罚款： （一）造成3人以上5人以下死亡，或者10人以上20人以下重伤，或者1000万元以上2000万元以下直接经济损失的，处100万元以上120万元以下的罚款； （二）造成5人以上7人以下死亡，或者20人以上30人以下重伤，或者2000万元以上3000万元以下直接经济损失的，处120万元以上150万元以下的罚款； （三）造成7人以上10人以下死亡，或者30人以上50人以下重伤，或者3000万元以上5000万元以下直接经济损失的，处150万元以上200万元以下的罚款。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第十六条", "text": "事故发生单位对重大事故发生负有责任的，依照下列规定处以罚款： （一）造成10人以上13人以下死亡，或者50人以上60人以下重伤，或者5000万元以上6000万元以下直接经济损失的，处200万元以上400万元以下的罚款； （二）造成13人以上15人以下死亡，或者60人以上70人以下重伤，或者6000万元以上7000万元以下直接经济损失的，处400万元以上600万元以下的罚款； （三）造成15人以上30人以下死亡，或者70人以上100人以下重伤，或者7000万元以上1亿元以下直接经济损失的，处600万元以上1000万元以下的罚款。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第十七条", "text": "事故发生单位对特别重大事故发生负有责任的，依照下列规定处以罚款： （一）造成30人以上40人以下死亡，或者100人以上120人以下重伤，或者1亿元以上1.5亿元以下直接经济损失的，处1000万元以上1200万元以下的罚款； （二）造成40人以上50人以下死亡，或者120人以上150人以下重伤，或者1.5亿元以上2亿元以下直接经济损失的，处1200万元以上1500万元以下的罚款； （三）造成50人以上死亡，或者150人以上重伤，或者2亿元以上直接经济损失的，处1500万元以上2000万元以下的罚款。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第十八条", "text": "发生生产安全事故，有下列情形之一的，属于《中华人民共和国安全生产法》"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第一百一十四条", "text": "第二款规定的情节特别严重、影响特别恶劣的情形，可以按照法律规定罚款数额的2倍以上5倍以下对事故发生单位处以罚款： （一）关闭、破坏直接关系生产安全的监控、报警、防护、救生设备、设施，或者篡改、隐瞒、销毁其相关数据、信息的； （二）因存在重大事故隐患被依法责令停产停业、停止施工、停止使用有关设备、设施、场所或者立即采取排除危险的整改措施，而拒不执行的； （三）涉及安全生产的事项未经依法批准或者许可，擅自从事矿山开采、金属冶炼、建筑施工，以及危险物品生产、经营、储存等高度危险的生产作业活动，或者未依法取得有关证照尚在从事生产经营活动的； （四）拒绝、阻碍行政执法的； （五）强令他人违章冒险作业，或者明知存在重大事故隐患而不排除，仍冒险组织作业的； （六）其他情节特别严重、影响特别恶劣的情形。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第十九条", "text": "事故发生单位主要负责人未依法履行安全生产管理职责，导致事故发生的，依照下列规定处以罚款： （一）发生一般事故的，处上一年年收入40％的罚款； （二）发生较大事故的，处上一年年收入60％的罚款； （三）发生重大事故的，处上一年年收入80％的罚款； （四）发生特别重大事故的，处上一年年收入100％的罚款。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第二十条", "text": "事故发生单位其他负责人和安全生产管理人员未依法履行安全生产管理职责，导致事故发生的，依照下列规定处以罚款： （一）发生一般事故的，处上一年年收入20％至30%的罚款； （二）发生较大事故的，处上一年年收入30％至40%的罚款； （三）发生重大事故的，处上一年年收入40％至50%的罚款； （四）发生特别重大事故的，处上一年年收入50％的罚款。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第二十一条", "text": "个人经营的投资人未依照《中华人民共和国安全生产法》的规定保证安全生产所必需的资金投入，致使生产经营单位不具备安全生产条件，导致发生生产安全事故的，依照下列规定对个人经营的投资人处以罚款： （一）发生一般事故的，处2万元以上5万元以下的罚款； （二）发生较大事故的，处5万元以上10万元以下的罚款； （三）发生重大事故的，处10万元以上15万元以下的罚款； （四）发生特别重大事故的，处15万元以上20万元以下的罚款。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第二十二条", "text": "违反《中华人民共和国安全生产法》《生产安全事故报告和调查处理条例》和本规定，存在对事故发生负有责任以及谎报、瞒报事故等两种以上应当处以罚款的行为的，应急管理部门或者矿山安全监察机构应当分别裁量，合并作出处罚决定。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第二十三条", "text": "在事故调查中发现需要对存在违法行为的其他单位及其有关人员处以罚款的，依照相关法律、法规和规章的规定实施。"}, {"law": "生产安全事故罚款处罚规定_20240301.docx", "no": "第二十四条", "text": "本规定自2024年3月1日起施行。原国家安全生产监督管理总局2007年7月12日公布，2011年9月1日第一次修正、2015年4月2日第二次修正的《生产安全事故罚款处罚规定（试行）》同时废止。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第一条", "text": "为规范用人单位劳动防护用品的使用和管理，保障劳动者安全健康及相关权益，根据《中华人民共和国安全生产法》、《中华人民共和国职业病防治法》等法律、行政法规和规章，制定本规范。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第二条", "text": "本规范适用于中华人民共和国境内企业、事业单位和个体经济组织等用人单位的劳动防护用品管理工作。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第三条", "text": "本规范所称的劳动防护用品，是指由用人单位为劳动者配备的，使其在劳动过程中免遭或者减轻事故伤害及职业病危害的个体防护装备。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第四条", "text": "劳动防护用品是由用人单位提供的，保障劳动者安全与健康的辅助性、预防性措施，不得以劳动防护用品替代工程防护设施和其他技术、管理措施。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第五条", "text": "用人单位应当健全管理制度，加强劳动防护用品配备、发放、使用等管理工作。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第六条", "text": "用人单位应当安排专项经费用于配备劳动防护用品，不得以货币或者其他物品替代。该项经费计入生产成本，据实列支。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第七条", "text": "用人单位应当为劳动者提供符合国家标准或者行业标准的劳动防护用品。使用进口的劳动防护用品，其防护性能不得低于我国相关标准。 鼓励用人单位购买、使用获得安全标志的劳动防护用品。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第八条", "text": "劳动者在作业过程中，应当按照规章制度和劳动防护用品使用规则，正确佩戴和使用劳动防护用品。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第九条", "text": "用人单位使用的劳务派遣工、接纳的实习学生应当纳入本单位人员统一管理，并配备相应的劳动防护用品。对处于作业地点的其他外来人员，必须按照与进行作业的劳动者相同的标准，正确佩戴和使用劳动防护用品。 第二章劳动防护用品选择"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第十条", "text": "劳动防护用品分为以下十大类： 防御物理、化学和生物危险、有害因素对头部伤害的头部防护用品。 防御缺氧空气和空气污染物进入呼吸道的呼吸防护用品。 防御物理和化学危险、有害因素对眼面部伤害的眼面部防护用品。 防噪声危害及防水、防寒等的听力防护用品。 防御物理、化学和生物危险、有害因素对手部伤害的手部防护用品。 （六）防御物理和化学危险、有害因素对足部伤害的足部防护用品。 （七）防御物理、化学和生物危险、有害因素对躯干伤害的躯干防护用品。 （八）防御物理、化学和生物危险、有害因素损伤皮肤或引起皮肤疾病的护肤用品。 （九）防止高处作业劳动者坠落或者高处落物伤害的坠落防护用品。 （十）其他防御危险、有害因素的劳动防护用品。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第十一条", "text": "用人单位应按照识别、评价、选择的程序（见附件1），结合劳动者作业方式和工作条件，并考虑其个人特点及劳动强度，选择防护功能和效果适用的劳动防护用品。 （一）接触粉尘、有毒、有害物质的劳动者应当根据不同粉尘种类、粉尘浓度及游离二氧化硅含量和毒物的种类及浓度配备相应的呼吸器（见附件2）、防护服、防护手套和防护鞋等。具体可参照《呼吸防护用品自吸过滤式防颗粒物呼吸器》（GB2626）、《呼吸防护用品的选择、使用及维护》（GB 和《个体防护装备足部防护鞋（靴）的选择、使用和维护指南》（GB 等标准。 工作场所存在高毒物品目录中的确定人类致癌物质（见附件3），当浓度达到其1 职业接触限值（PC-TWA或MAC）时，用人单位应为劳动者配备相应的劳动防护用品，并指导劳动者正确佩戴和使用。 （二）接触噪声的劳动者，当暴露于80dB 的工作场所时，用人单位应当根据劳动者需求为其配备适用的护听器；当暴露于LEX 的工作场所时，用人单位必须为劳动者配备适用的护听器，并指导劳动者正确佩戴和使用（见附件2）。具体可参照《护听器的选择指南》（GB 三）工作场所中存在电离辐射危害的，经危害评价确认劳动者需佩戴劳动防护用品的，用人单位可参照电离辐射的相关标准及《个体防护装备配备基本要求》（GB 为劳动者配备劳动防护用品，并指导劳动者正确佩戴和使用。 （四）从事存在物体坠落、碎屑飞溅、转动机械和锋利器具等作业的劳动者，用人单位还可参照《个体防护装备选用规范》（GB 等标准，为劳动者配备适用的劳动防护用品。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第十二条", "text": "同一工作地点存在不同种类的危险、有害因素的，应当为劳动者同时提供防御各类危害的劳动防护用品。需要同时配备的劳动防护用品，还应考虑其可兼容性。 劳动者在不同地点工作，并接触不同的危险、有害因素，或接触不同的危害程度的有害因素的，为其选配的劳动防护用品应满足不同工作地点的防护需求。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第十三条", "text": "劳动防护用品的选择还应当考虑其佩戴的合适性和基本舒适性，根据个人特点和需求选择适合号型、式样。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第十四条", "text": "用人单位应当在可能发生急性职业损伤的有毒、有害工作场所配备应急劳动防护用品，放置于现场临近位置并有醒目标识。 用人单位应当为巡检等流动性作业的劳动者配备随身携带的个人应急防护用品。 劳动防护用品采购、发放、培训及使用"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第十五条", "text": "用人单位应当根据劳动者工作场所中存在的危险、有害因素种类及危害程度、劳动环境条件、劳动防护用品有效使用时间制定适合本单位的劳动防护用品配备标准（见附件4）。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第十六条", "text": "用人单位应当根据劳动防护用品配备标准制定采购计划，购买符合标准的合格产品。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第十七条", "text": "用人单位应当查验并保存劳动防护用品检验报告等质量证明文件的原件或复印件。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第十八条", "text": "用人单位应当确保已采购劳动防护用品的存储条件，并保证其在有效期内。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第十九条", "text": "用人单位应当按照本单位制定的配备标准发放劳动防护用品，并作好登记（见附件5）。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第二十条", "text": "用人单位应当对劳动者进行劳动防护用品的使用、维护等专业知识的培训。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第二十一条", "text": "用人单位应当督促劳动者在使用劳动防护用品前，对劳动防护用品进行检查，确保外观完好、部件齐全、功能正常。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第二十二条", "text": "用人单位应当定期对劳动防护用品的使用情况进行检查，确保劳动者正确使用。 劳动防护用品维护、更换及报废"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第二十三条", "text": "劳动防护用品应当按照要求妥善保存，及时更换。 公用的劳动防护用品应当由车间或班组统一保管，定期维护。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第二十四条", "text": "用人单位应当对应急劳动防护用品进行经常性的维护、检修，定期检测劳动防护用品的性能和效果，保证其完好有效。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第二十五条", "text": "用人单位应当按照劳动防护用品发放周期定期发放，对工作过程中损坏的，用人单位应及时更换。"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第二十六条", "text": "安全帽、呼吸器、绝缘手套等安全性能要求高、易损耗的劳动防护用品，应当按照有效防护功能最低指标和有效使用期，到期强制报废。 附则"}, {"law": "用人单位劳动防护用品管理规范_20180115.doc", "no": "第二十七条", "text": "本规范所称的工作地点，是指劳动者从事职业活动或进行生产管理而经常或定时停留的岗位和作业地点。 第二十八 条 煤矿劳动防护用品的管理，按照《煤矿职业安全卫生个体防护用品配备标准》（AQ1051）规定执行。 附件1 劳动防护用品选择程序 一般粉尘，如煤尘、水泥尘、木粉尘你、云母尘、滑石尘及其他粉尘。 过滤效率至少满足《呼吸防护用品自吸过滤式防颗粒物呼吸器》（GB2626）规定的KN90级别的防颗粒物呼吸器 可更换式防颗粒物半面罩或全面罩，过滤效率至少满足GB2626规定的 KN95级别的防颗粒物呼吸器 过滤效率至少满足GB2626规定的 KN95级别的防颗粒物呼吸器 过滤效率至少满足GB2626 规定的KN100级别的防颗粒物呼吸器 过滤效率至少满足GB2626规定的 KP95级别的防颗粒物呼吸器 防毒面具 面罩类型： 工作场所毒物浓度超标不大于10倍，使用送风或自吸过滤半面罩；工作场所毒物浓度超标不大于100倍，使用送风或自吸过滤全面罩；工作场所毒物浓度超标大于100倍，使用隔绝式或送风过滤式全面罩 用人单位应为劳动者配备适用的护听器，并指导劳动者正确佩戴和使用。劳动者暴露于工作场所LEX 的耳塞、耳罩或者同时佩戴耳塞和耳罩，耳塞和耳罩组合使用时的声衰减值，可按二者中较高的声衰减值增加5dB估算 注：根据最新发布的《高毒物品目录》和确定人类致癌物质随时调整。 附件 4 用人单位劳动防护用品配备标准 岗位 发放人： 日期： 年 月 日 实施作业 否 定性分析 选择符合标准的防护用品 采取工程措施并确认能否完全消除危害 能 否 否 是 符合标准 不符合标准 确定识别范围 佩戴劳动防护用品 劳动防护用品操作、使用培训 购置劳动防护用品 是否符合国家或行业标准要求求 根据伤害部位选择相应防护用品 是 是否对人体造成伤害及其危害程度 可能产生的危险、有害因素是否已知"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第一条", "text": "为加强职业健康检查工作，规范职业健 康检查机构管理，保护劳动者健康权益，根据《中华 人民共和国职业病防治法》（以下简称《职业病防治 法》），制定本办法。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第二条", "text": "本办法所称职业健康检查是指医疗卫 生机构按照国家有关规定，对从事接触职业病危害作 业的劳动者进行的上岗前、在岗期间、离岗时的健康 国家卫生健康委员会规章 国家卫生健康委员会发布 - 2 - 检查。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第三条", "text": "国家卫生健康委负责全国范围内职业 健康检查工作的监督管理。 县级以上地方卫生健康主管部门负责本辖区职 业健康检查工作的监督管理；结合职业病防治工作实 际需要，充分利用现有资源，统一规划、合理布局； 加强职业健康检查机构能力建设，并提供必要的保障 条件。 第二章 职业健康检查机构"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第四条", "text": "医疗卫生机构开展职业健康检查，应当 在开展之日起15 个工作日内向省级卫生健康主管部 门备案。备案的具体办法由省级卫生健康主管部门依 据本办法制定，并向社会公布。 省级卫生健康主管部门应当及时向社会公布备 案的医疗卫生机构名单、地址、检查类别和项目等相 国家卫生健康委员会规章 国家卫生健康委员会发布 - 3 - 关信息，并告知核发其《医疗机构执业许可证》的卫 生健康主管部门。核发其《医疗机构执业许可证》的 卫生健康主管部门应当在该机构的《医疗机构执业许 可证》副本备注栏注明检查类别和项目等信息。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第五条", "text": "承担职业健康检查的医疗卫生机构（以 下简称职业健康检查机构）应当具备以下条件： （一）持有《医疗机构执业许可证》，涉及放射 检查项目的还应当持有《放射诊疗许可证》； （二）具有相应的职业健康检查场所、候检场所 和检验室，建筑总面积不少于400 平方米，每个独立 的检查室使用面积不少于6 平方米； （三）具有与备案开展的职业健康检查类别和项 目相适应的执业医师、护士等医疗卫生技术人员； （四）至少具有1 名取得职业病诊断资格的执业 医师； （五）具有与备案开展的职业健康检查类别和项 目相适应的仪器、设备，具有相应职业卫生生物监测 国家卫生健康委员会规章 国家卫生健康委员会发布 - 4 - 能力；开展外出职业健康检查，应当具有相应的职业 健康检查仪器、设备、专用车辆等条件； （六）建立职业健康检查质量管理制度； （七）具有与职业健康检查信息报告相应的条 件。 医疗卫生机构进行职业健康检查备案时，应当提 交证明其符合以上条件的有关资料。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第六条", "text": "开展职业健康检查工作的医疗卫生机 构对备案的职业健康检查信息的真实性、准确性、合 法性承担全部法律责任。 当备案信息发生变化时，职业健康检查机构应当 自信息发生变化之日起10 个工作日内提交变更信息。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第七条", "text": "职业健康检查机构具有以下职责： （一）在备案开展的职业健康检查类别和项目范 围内，依法开展职业健康检查工作，并出具职业健康 检查报告； （二）履行疑似职业病的告知和报告义务； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 5 - （三）报告职业健康检查信息； （四）定期向卫生健康主管部门报告职业健康检 查工作情况，包括外出职业健康检查工作情况； （五）开展职业病防治知识宣传教育； （六）承担卫生健康主管部门交办的其他工作。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第八条", "text": "职业健康检查机构应当指定主检医师。 主检医师应当具备以下条件： （一）具有执业医师证书； （二）具有中级以上专业技术职务任职资格； （三）具有职业病诊断资格； （四）从事职业健康检查相关工作三年以上，熟 悉职业卫生和职业病诊断相关标准。 主检医师负责确定职业健康检查项目和周期，对 职业健康检查过程进行质量控制，审核职业健康检查 报告。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第九条", "text": "职业健康检查机构及其工作人员应当 关心、爱护劳动者，尊重和保护劳动者的知情权及个 国家卫生健康委员会规章 国家卫生健康委员会发布 - 6 - 人隐私。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第十条", "text": "省级卫生健康主管部门应当指定机构 负责本辖区内职业健康检查机构的质量控制管理工 作，组织开展实验室间比对和职业健康检查质量考 核。 职业健康检查质量控制规范由中国疾病预防控 制中心制定。 第三章 职业健康检查规范"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第十一条", "text": "按照劳动者接触的职业病危害因素， 职业健康检查分为以下六类： （一）接触粉尘类； （二）接触化学因素类； （三）接触物理因素类； （四）接触生物因素类； （五）接触放射因素类； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 7 - （六）其他类（特殊作业等）。 以上每类中包含不同检查项目。职业健康检查机 构应当在备案的检查类别和项目范围内开展相应的 职业健康检查。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第十二条", "text": "职业健康检查机构开展职业健康检 查应当与用人单位签订委托协议书，由用人单位统一 组织劳动者进行职业健康检查；也可以由劳动者持单 位介绍信进行职业健康检查。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第十三条", "text": "职业健康检查机构应当依据相关技 术规范，结合用人单位提交的资料，明确用人单位应 当检查的项目和周期。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第十四条", "text": "在职业健康检查中，用人单位应当如 实提供以下职业健康检查所需的相关资料，并承担检 查费用： （一）用人单位的基本情况； （二）工作场所职业病危害因素种类及其接触人 员名册、岗位（或工种）、接触时间； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 8 - （三）工作场所职业病危害因素定期检测等相关 资料。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第十五条", "text": "职业健康检查的项目、周期按照《职 业健康监护技术规范》（GBZ 188)执行，放射工作人 员职业健康检查按照《放射工作人员职业健康监护技 术规范》(GBZ 235)等规定执行。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第十六条", "text": "职业健康检查机构可以在执业登记 机关管辖区域内或者省级卫生健康主管部门指定区 域内开展外出职业健康检查。外出职业健康检查进行 医学影像学检查和实验室检测，必须保证检查质量并 满足放射防护和生物安全的管理要求。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第十七条", "text": "职业健康检查机构应当在职业健康 检查结束之日起30 个工作日内将职业健康检查结果， 包括劳动者个人职业健康检查报告和用人单位职业 健康检查总结报告，书面告知用人单位，用人单位应 当将劳动者个人职业健康检查结果及职业健康检查 机构的建议等情况书面告知劳动者。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 9 -"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第十八条", "text": "职业健康检查机构发现疑似职业病 病人时，应当告知劳动者本人并及时通知用人单位， 同时向所在地卫生健康主管部门报告。发现职业禁忌 的，应当及时告知用人单位和劳动者。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第十九条", "text": "职业健康检查机构要依托现有的信 息平台，加强职业健康检查的统计报告工作，逐步实 现信息的互联互通和共享。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第二十条", "text": "职业健康检查机构应当建立职业健 康检查档案。职业健康检查档案保存时间应当自劳动 者最后一次职业健康检查结束之日起不少于15 年。 职业健康检查档案应当包括下列材料： （一）职业健康检查委托协议书； （二）用人单位提供的相关资料； （三）出具的职业健康检查结果总结报告和告知 材料； （四）其他有关材料。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 10 - 第四章 监督管理"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第二十一条", "text": "县级以上地方卫生健康主管部门 应当加强对本辖区职业健康检查机构的监督管理。按 照属地化管理原则，制定年度监督检查计划，做好职 业健康检查机构的监督检查工作。监督检查主要内容 包括： （一）相关法律法规、标准的执行情况； （二）按照备案的类别和项目开展职业健康检查 工作的情况； （三）外出职业健康检查工作情况； （四）职业健康检查质量控制情况； （五）职业健康检查结果、疑似职业病的报告与 告知以及职业健康检查信息报告情况； （六）职业健康检查档案管理情况等。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第二十二条", "text": "省级卫生健康主管部门应当对本 辖区内的职业健康检查机构进行定期或者不定期抽 国家卫生健康委员会规章 国家卫生健康委员会发布 - 11 - 查；设区的市级卫生健康主管部门每年应当至少组织 一次对本辖区内职业健康检查机构的监督检查；县级 卫生健康主管部门负责日常监督检查。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第二十三条", "text": "县级以上地方卫生健康主管部门 监督检查时，有权查阅或者复制有关资料，职业健康 检查机构应当予以配合。 第五章 法律责任"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第二十四条", "text": "无《医疗机构执业许可证》擅自开 展职业健康检查的，由县级以上地方卫生健康主管部 门依据《医疗机构管理条例》"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第四十四条", "text": "的规定进行 处理。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第二十五条", "text": "职业健康检查机构有下列行为之 一的，由县级以上地方卫生健康主管部门责令改正， 给予警告，可以并处3 万元以下罚款： （一）未按规定备案开展职业健康检查的； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 12 - （二）未按规定告知疑似职业病的； （三）出具虚假证明文件的。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第二十六条", "text": "职业健康检查机构未按照规定报 告疑似职业病的，由县级以上地方卫生健康主管部门 依据《职业病防治法》"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第七十四条", "text": "的规定进行处理。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第二十七条", "text": "职业健康检查机构有下列行为之 一的，由县级以上地方卫生健康主管部门给予警告， 责令限期改正；逾期不改的，处以三万元以下罚款： （一）未指定主检医师或者指定的主检医师未取 得职业病诊断资格的； （二）未按要求建立职业健康检查档案的； （三）未履行职业健康检查信息报告义务的； （四）未按照相关职业健康监护技术规范规定开 展工作的； （五）违反本办法其他有关规定的。"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第二十八条", "text": "职业健康检查机构未按规定参加 实验室比对或者职业健康检查质量考核工作，或者参 国家卫生健康委员会规章 国家卫生健康委员会发布 - 13 - 加质量考核不合格未按要求整改仍开展职业健康检 查工作的，由县级以上地方卫生健康主管部门给予警 告，责令限期改正；逾期不改的，处以三万元以下罚 款。 第六章 附则"}, {"law": "职业健康检查管理办法_20190228.pdf", "no": "第二十九条", "text": "本办法自2015 年5 月1 日起施行。 2002 年3 月28 日原卫生部公布的《职业健康监护管 理办法》同时废止。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第一条", "text": "为了加强对职业卫生技术服务机构的监督管理，规范职业卫生技术服务行为，根据《中华人民共和国职业病防治法》，制定本办法。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第二条", "text": "在中华人民共和国境内申请职业卫生技术服务机构资质，从事职业卫生检测、评价技术服务以及卫生健康主管部门实施职业卫生技术服务机构资质认可与监督管理，适用本办法。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第三条", "text": "本办法所称职业卫生技术服务机构，是指为用人单位提供职业病危害因素检测、职业病危害现状评价、职业病防护设备设施与防护用品的效果评价等技术服务的机构。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第四条", "text": "国家对职业卫生技术服务机构实行资质认可制度。职业卫生技术服务机构应当依照本办法取得职业卫生技术服务机构资质；未取得职业卫生技术服务机构资质的，不得从事职业卫生检测、评价技术服务。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第五条", "text": "职业卫生技术服务机构资质由省、自治区、直辖市卫生健康主管部门认可及颁发证书。 省、自治区、直辖市卫生健康主管部门统称资质认可机关。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第六条", "text": "取得资质的职业卫生技术服务机构，可以根据认可的业务范围在全国从事职业卫生技术服务活动。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第七条", "text": "国家卫生健康委、国家疾控局依据各自职责负责指导全国职业卫生技术服务机构的监督管理工作。 县级以上地方卫生健康、疾病预防控制主管部门依据各自职责负责本行政区域内职业卫生技术服务机构的监督管理工作。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第八条", "text": "国家鼓励职业卫生技术服务行业加强自律，规范执业行为，维护行业秩序。 第二章 资质认可"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第九条", "text": "申请职业卫生技术服务机构资质的申请人，应当具备下列条件： （一）能够独立承担民事责任； （二）有固定工作场所，实验室、档案室等场所的面积与所申请资质、业务范围相适应； （三）具有符合要求的实验室，具备与所申请资质、业务范围相适应的仪器设备； （四）有健全的内部管理制度和质量保证体系； （五）具有满足学历、专业、技术职称等要求的专业技术人员，专业技术人员不少于十五名； （六）有专职技术负责人和质量控制负责人。专职技术负责人具有高级专业技术职称和三年以上职业卫生相关工作经验，或者中级专业技术职称和八年以上职业卫生相关工作经验。质量控制负责人具有高级专业技术职称和三年以上相关工作经验，或者中级专业技术职称和五年以上相关工作经验； （七）具有与所申请业务范围相适应的检测、评价能力； （八）截至申请之日五年内无严重违法失信记录； （九）正常运行并可以供公众查询信息的网站； （十）法律、行政法规规定的其他条件。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第十条", "text": "申请人应当组织专业技术人员接受专业培训，确保专业技术人员熟悉职业病防治法律、法规和标准规范，并具备与其从事的职业卫生技术服务相适应的专业能力。 对专业技术人员的培训，申请人可以自行开展或者委托有条件的培训机构开展。专业技术人员的培训计划、培训记录（包括书面及影像资料）等应当归档备查。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第十一条", "text": "申请人应当提交下列材料： （一）法定代表人或者主要负责人签署的申请表； （二）法定代表人或者主要负责人签署的知悉承担职业卫生技术服务的法律责任、义务、权利和风险的承诺书； （三）营业执照或者其他法人资格证明； （四）工作场所产权证明或者租赁合同； （五）专业技术人员、专职技术负责人、质量控制负责人的名单及其技术职称证书、劳动关系证明； （六）仪器设备清单、工作场所布局与面积示意图； （七）在申请职业卫生技术服务业务范围内，能够证明具有相应业务能力的其他材料。 申请人对申请材料的真实性负责。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第十二条", "text": "申请职业卫生技术服务机构资质，按照下列程序办理： （一）申请人按照本办法"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第五条", "text": "的规定向其机构所在地资质认可机关提出申请，并提交本办法"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第十一条", "text": "第一款规定的材料； （二）资质认可机关应当自收到申请材料之日起五个工作日内作出是否受理的决定。对材料齐全，符合规定形式的，应当予以受理，并出具书面受理文书；对材料不齐全或者不符合规定形式的，应当当场或者在五个工作日内一次性告知申请人需要补正的全部内容；决定不予受理的，应当向申请人书面说明理由； （三）资质认可机关应当自受理资质申请之日起二十个工作日内，依据职业卫生技术服务机构资质认可技术评审准则，组织对申请人进行技术评审，并根据技术评审结论作出资质认可决定。决定认可的，应当自作出决定之日起十个工作日内向申请人颁发资质证书；决定不予认可的，应当向申请人书面说明理由。二十个工作日内不能作出认可决定的，经资质认可机关负责人批准，可以延长十个工作日，并应当将延长期限的理由告知申请人。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第十三条", "text": "国家卫生健康委制定职业卫生技术服务机构资质认可有关文书样式和内容、职业卫生技术服务机构资质认可技术评审准则以及资质证书的样式，并向社会公布。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第十四条", "text": "资质认可机关应当建立技术评审专家库（以下简称专家库）及其管理制度。 技术评审专家应当熟悉职业病防治法律、法规和标准规范，具有相关专业高级技术职称，连续五年以上职业卫生工作经验，良好的职业道德。 技术评审专家应当依据技术评审准则开展工作，出具评审意见，并对评审意见负责。 技术评审专家不得从事与本人有利害关系的技术评审活动。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第十五条", "text": "国家卫生健康委制定并公开职业卫生技术服务机构专业技术人员考核评估大纲，资质认可机关建立题库。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第十六条", "text": "资质认可机关应当从专家库中随机抽取相关专业的三至七名专家（应为单数）组成专家组，对申请人进行技术评审。 技术评审包括申请材料的技术审查和现场技术考核。申请材料的技术审查结论分为“通过”、“不通过”。技术审查结论为“通过”的，继续开展现场技术考核；技术审查结论为“不通过”的，不开展现场技术考核。 现场技术考核应当包括下列内容： （一）核查现场有关设备、设施、仪器、仪表等； （二）依据考核评估大纲和题库，考核评估专职技术负责人、质量控制负责人及有关专业技术人员专业知识和实际操作能力； （三）抽查原始工作记录、影像资料、报告、总结、档案等资料； （四）进行必要的盲样检测。 现场技术考核的时间一般不超过十个工作日。现场技术考核结论分为“通过”、“不通过”。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第十七条", "text": "职业卫生技术服务机构资质证书有效期为五年。资质证书有效期届满需要延续的，职业卫生技术服务机构应当在有效期届满三个月前向原资质认可机关提出申请。经审核合格的，予以批准延续；不合格的，不予批准延续，并向申请人书面说明理由。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第十八条", "text": "职业卫生技术服务机构取得资质一年以上，需要增加业务范围的，应当向原资质认可机关提出申请。资质认可机关应当按照本办法的规定进行认可。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第十九条", "text": "职业卫生技术服务机构变更名称、法定代表人或者主要负责人、注册地址、实验室地址的，应当向原资质认可机关申请办理变更手续。 职业卫生技术服务机构分立、合并的，应当申请办理资质认可变更手续或者重新申请职业卫生技术服务机构资质认可。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第二十条", "text": "职业卫生技术服务机构资质证书遗失的，应当自证书遗失之日起三十日内向原资质认可机关书面申请补发。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第二十一条", "text": "职业卫生技术服务机构不得涂改、倒卖、出租、出借职业卫生技术服务机构资质证书，或者以其他形式非法转让职业卫生技术服务机构资质证书。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第二十二条", "text": "资质认可机关对取得资质的职业卫生技术服务机构应当及时向社会公布，接受社会监督。 第三章 技术服务"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第二十三条", "text": "职业卫生技术服务机构应当建立、健全职业卫生技术服务责任制。主要负责人对本机构的职业卫生技术服务工作全面负责。专职技术负责人和质量控制负责人应当按照法律、法规和标准规范的规定，加强职业卫生技术服务的全过程管理。报告审核人、授权签字人、技术服务项目负责人及参与人员按照职责分工参与技术服务，在技术报告及原始记录上签字，并承担相应责任。未达到技术评审考核评估要求的专业技术人员，职业卫生技术服务机构不得安排其参与职业卫生技术服务。 职业卫生技术服务机构应当组织专业技术人员每年接受不少于八学时的继续教育培训。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第二十四条", "text": "职业卫生技术服务机构应当按照法律法规和《工作场所空气中有害物质监测的采样规范》（GBZ159）、《电离辐射防护与辐射源安全基本标准》(GB18871)、《工业企业设计卫生标准》（GBZ1）、《工作场所有害因素职业接触限值》（GBZ2.1、GBZ2.2）等标准规范的要求，开展现场调查、职业病危害因素识别、现场采样、现场检测、样品管理、实验室分析、数据处理及应用、危害程度评价、防护措施及其效果评价、技术报告编制等职业卫生技术服务活动，如实记录技术服务原始信息，确保相关数据信息可溯源，科学、客观、真实地反映技术服务事项，并对出具的职业卫生技术报告承担法律责任。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第二十五条", "text": "职业卫生技术服务机构应当依法独立开展职业卫生技术服务活动。因检测项目限制或者样品保存时限有特殊要求而无法自行检测的，可以委托具备相应检测能力的职业卫生技术服务机构进行样品测定。样品现场采集和检测结果分析及应用等工作不得委托其他机构实施。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第二十六条", "text": "职业卫生技术服务机构应当公开办事制度和程序，方便服务对象，并采取措施保证服务质量。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第二十七条", "text": "职业卫生技术服务机构应当在认可的范围内开展技术服务工作，并接受技术服务所在地卫生健康、疾病预防控制主管部门的监督管理。 职业卫生技术服务机构应当按照规定及时报送职业卫生技术服务内容、时间、参与人员等相关信息。职业卫生技术服务信息报送管理规定由国家卫生健康委统一制定，并向社会公布。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第二十八条", "text": "职业卫生技术服务机构开展技术服务时，应当以书面形式与用人单位明确技术服务内容、范围以及双方的责任。 用人单位提出的技术服务内容、范围及要求违反法律、法规和标准规范规定的，职业卫生技术服务机构应当予以拒绝。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第二十九条", "text": "职业卫生技术服务机构及其工作人员在从事职业卫生技术服务活动中，不得有下列行为： （一）超出资质认可范围从事技术服务活动； （二）出具虚假或者失实的职业卫生技术报告； （三）转包职业卫生技术服务项目； （四）擅自更改、简化职业卫生技术服务程序和相关内容； （五）法律、法规规定的其他违法行为。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第三十条", "text": "职业卫生技术服务机构不得使用非本机构专业技术人员从事职业卫生技术服务活动。 职业卫生技术服务机构专业技术人员不得有下列行为： （一）在职业卫生技术报告或者有关原始记录上代替他人签字； （二）未参与相应职业卫生技术服务事项而在技术报告或者有关原始记录上签字； （三）其他违反法律、法规和标准规范的行为。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第三十一条", "text": "职业卫生技术服务机构应当建立职业卫生技术服务档案，并长期妥善保管。职业卫生技术服务档案包括职业卫生技术服务过程控制记录、现场勘查记录、相关原始记录、影像资料、技术报告及相关证明材料。 职业卫生技术服务机构应当为专业技术人员提供必要的个体防护用品。 职业卫生技术服务机构应当自出具职业卫生技术报告之日起二十个工作日内,在本单位网站上公开技术报告相关信息（涉及国家秘密、商业秘密、技术秘密及个人隐私的信息和法律、法规规定可不予公开的除外），公开的时间不少于五年。公开的信息应包括以下内容： （一）用人单位名称、地址及联系人； （二）技术服务项目组人员名单； （三）现场调查、现场采样、现场检测的专业技术人员名单、时间，用人单位陪同人； （四）证明现场调查、现场采样、现场检测的图像影像。 第四章 监督管理"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第三十二条", "text": "资质认可机关应当对其认可的职业卫生技术服务机构在资质认可有效期内至少进行一次评估检查，重点检查资质条件保持和符合情况。 评估检查可以通过能力验证、现场核查等方式开展。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第三十三条", "text": "县级以上地方卫生健康、疾病预防控制主管部门应当依据各自职责按照有关“双随机、一公开”的规定，加强对本行政区域内从业的职业卫生技术服务机构事中事后监管。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第三十四条", "text": "县级以上地方卫生健康、疾病预防控制主管部门对职业卫生技术服务机构的监督检查，主要包括下列内容： （一）是否以书面形式与用人单位明确技术服务内容、范围以及双方的责任； （二）是否按照标准规范要求开展现场调查、职业病危害因素识别、现场采样、现场检测、样品管理、实验室分析、数据处理及应用、危害程度评价、防护措施及其效果评价、技术报告编制等职业卫生技术服务活动； （三）技术服务内部审核、原始信息记录等是否规范； （四）职业卫生技术服务档案是否完整； （五）技术服务过程是否存在弄虚作假等违法违规情况； （六）是否按照规定向技术服务所在地卫生健康主管部门报送职业卫生技术服务相关信息； （七）是否按照规定在网上公开职业卫生技术报告相关信息； （八）依法应当监督检查的其他内容。 县级以上地方卫生健康、疾病预防控制主管部门在对用人单位职业病防治工作进行监督检查过程中，应当加强对有关职业卫生技术服务机构提供的职业卫生技术服务进行延伸检查。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第三十五条", "text": "县级以上卫生健康主管部门应当建立职业卫生技术服务机构信息管理系统，会同疾病预防控制主管部门建立职业卫生技术服务机构及其从业人员信用档案，记录违法失信行为并依法向社会公开，依据职业卫生技术服务机构信用状况，实行分类监管。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第三十六条", "text": "职业卫生技术服务机构有下列情形之一的，资质认可机关应当注销其资质： （一）资质认可有效期届满未延续的； （二）依法终止的； （三）资质认可依法被撤销、撤回，或者资质证书依法被吊销的； （四）法律、法规规定的应当注销资质认可的其他情形。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第三十七条", "text": "卫生健康、疾病预防控制主管部门及其工作人员不得有下列行为： （一）要求用人单位接受指定的职业卫生技术服务机构进行职业卫生技术服务； （二）变相设立法律、法规规定以外的行政许可； （三）限制本行政区域外职业卫生技术服务机构到本地区开展职业卫生技术服务； （四）干预职业卫生技术服务机构开展正常活动； （五）向职业卫生技术服务机构收取或者变相收取费用； （六）向职业卫生技术服务机构摊派财物、推销产品； （七）在职业卫生技术服务机构报销任何费用； （八）对不具备资质条件的申请人予以资质认可。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第三十八条", "text": "任何单位或者个人发现职业卫生技术服务机构及其从业人员、卫生健康和疾病预防控制主管部门及其工作人员、技术评审专家违反有关职业病防治的法律、法规和本办法规定的行为，有权向县级以上卫生健康、疾病预防控制主管部门或者其他有关部门举报。 卫生健康、疾病预防控制主管部门应当为举报人保密，并依法进行核查和处理。 第五章 法律责任"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第三十九条", "text": "县级以上卫生健康、疾病预防控制主管部门工作人员不履行本办法规定的职责，徇私舞弊、滥用职权、弄虚作假、玩忽职守，依法给予相应处分。 技术评审专家在职业卫生技术服务机构技术评审工作中徇私舞弊、弄虚作假、玩忽职守的，撤销其技术评审专家资格，终身不得再进入专家库。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第四十条", "text": "申请人隐瞒有关情况或者提供虚假材料申请职业卫生技术服务机构资质认可的，资质认可机关不予受理或者不予认可，并给予警告；申请人自资质认可机关作出不予受理或者不予认可决定之日起一年内不得再次申请职业卫生技术服务机构资质。 职业卫生技术服务机构以欺骗、贿赂等不正当手段取得职业卫生技术服务机构资质认可的，资质认可机关应当撤销其资质认可，并给予警告；申请人自资质认可机关撤销其资质认可之日起三年内不得再次申请职业卫生技术服务机构资质。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第四十一条", "text": "未取得职业卫生技术服务资质认可擅自从事职业卫生检测、评价技术服务的，由县级以上地方疾病预防控制主管部门责令立即停止违法行为，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上十倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上五万元以下的罚款；情节严重的，对直接负责的主管人员和其他直接责任人员，依法给予降级、撤职或者开除的处分。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第四十二条", "text": "职业卫生技术服务机构有下列行为之一的，由县级以上地方疾病预防控制主管部门责令立即停止违法行为，给予警告，没收违法所得；违法所得五千元以上的，并处违法所得二倍以上五倍以下的罚款；没有违法所得或者违法所得不足五千元的，并处五千元以上二万元以下的罚款；情节严重的，由原资质认可机关取消其资质认可；对直接负责的主管人员和其他责任人员，依法给予降级、撤职或者开除的处分；构成犯罪的，依法追究刑事责任： （一）超出资质认可范围从事职业卫生技术服务的； （二）未按照《职业病防治法》的规定履行法定职责的； （三）出具虚假证明文件的。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第四十三条", "text": "职业卫生技术服务机构有下列行为之一的，由县级以上地方疾病预防控制主管部门责令改正，给予警告，并处一万元以上三万元以下罚款；构成犯罪的，依法追究刑事责任： （一）涂改、倒卖、出租、出借职业卫生技术服务机构资质证书，或者以其他形式非法转让职业卫生技术服务机构资质证书的； （二）未按规定向技术服务所在地卫生健康主管部门报送职业卫生技术服务相关信息的； （三）未按规定在网上公开职业卫生技术报告相关信息的； （四）其他违反本办法规定的行为。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第四十四条", "text": "职业卫生技术服务机构有下列情形之一的，由县级以上地方疾病预防控制主管部门责令改正，给予警告，可以并处三万元以下罚款： （一）未按标准规范开展职业卫生技术服务，或者擅自更改、简化服务程序和相关内容的； （二）未按规定实施委托检测的； （三）转包职业卫生技术服务项目的；职业卫生技术服务机构管理办法 （四）未按规定以书面形式与用人单位明确技术服务内容、范围以及双方责任的； （五）使用非本机构专业技术人员从事职业卫生技术服务活动的； （六）安排未达到技术评审考核评估要求的专业技术人员参与职业卫生技术服务的。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第四十五条", "text": "职业卫生技术服务机构专业技术人员有下列情形之一的，由县级以上地方疾病预防控制主管部门责令改正，给予警告，并处一万元以下罚款： （一）在职业卫生技术报告或者有关原始记录上代替他人签字的； （二）未参与相应职业卫生技术服务事项而在技术报告或者有关原始记录上签字的； （三）其他违反本办法规定的行为。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第四十六条", "text": "已经取得资质认可的职业卫生技术服务机构，不再符合规定的资质条件的，由原资质认可机关责令其改正，通报批评；情节严重的，依法撤销其资质认可。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第四十七条", "text": "本办法所规定的行政处罚，除规定由原资质认可机关实施的以外，由技术服务所在地的县级以上地方疾病预防控制主管部门决定。 第六章 附 则"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第四十八条", "text": "本办法下列用语的含义： 专业技术人员，是指在职业卫生技术服务机构或者拟申请职业卫生技术服务机构资质的单位中专职从事职业卫生技术服务工作的人员。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第四十九条", "text": "个人剂量监测、放射防护器材和含放射性产品检测、医疗机构放射性危害评价等技术服务机构的管理另行规定。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第五十条", "text": "本办法施行前已经取得职业卫生技术服务机构资质的，资质继续有效。资质有效期满后，需要继续从事职业卫生技术服务的，按照本办法的规定申请资质认可延续。"}, {"law": "职业卫生技术服务机构管理办法_20230928.docx", "no": "第五十一条", "text": "本办法自2021年2月1日起施行。原国家安全生产监督管理总局2012年4月27日公布、2015年5月29日修改的《职业卫生技术服务机构监督管理暂行办法》同时废止。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第一条", "text": "为了规范职业病危害项目的申报工作，加强对用人单位职业卫生工 作的监督管理，根据《中华人民共和国职业病防治法》，制定本办法。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第二条", "text": "用人单位（煤矿除外）工作场所存在职业病目录所列职业病的危害 因素的，应当及时、如实向所在地安全生产监督管理部门申报危害项目，并接受 安全生产监督管理部门的监督管理。 煤矿职业病危害项目申报办法另行规定。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第三条", "text": "本办法所称职业病危害项目，是指存在职业病危害因素的项目。 职业病危害因素按照《职业病危害因素分类目录》确定。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第四条", "text": "职业病危害项目申报工作实行属地分级管理的原则。 中央企业、省属企业及其所属用人单位的职业病危害项目，向其所在地设区 的市级人民政府安全生产监督管理部门申报。 前款规定以外的其他用人单位的职业病危害项目，向其所在地县级人民政府 安全生产监督管理部门申报。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第五条", "text": "用人单位申报职业病危害项目时，应当提交《职业病危害项目申报 表》和下列文件、资料： （一）用人单位的基本情况； （二）工作场所职业病危害因素种类、分布情况以及接触人数； （三）法律、法规和规章规定的其他文件、资料。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第六条", "text": "职业病危害项目申报同时采取电子数据和纸质文本两种方式。 用人单位应当首先通过“职业病危害项目申报系统”进行电子数据申报，同 时将《职业病危害项目申报表》加盖公章并由本单位主要负责人签字后，按照本 办法"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第五条", "text": "的规定，连同有关文件、资料一并上报所在地设区的市级、 县级安全生产监督管理部门。 受理申报的安全生产监督管理部门应当自收到申报文件、资料之日起5个工作 日内，出具《职业病危害项目申报回执》。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第七条", "text": "职业病危害项目申报不得收取任何费用。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第八条", "text": "用人单位有下列情形之一的，应当按照本条规定向原申报机关申报 变更职业病危害项目内容： （一）进行新建、改建、扩建、技术改造或者技术引进建设项目的，自建设 项目竣工验收之日起30日内进行申报； （二）因技术、工艺、设备或者材料等发生变化导致原申报的职业病危害因 素及其相关内容发生重大变化的，自发生变化之日起15日内进行申报； （三）用人单位工作场所、名称、法定代表人或者主要负责人发生变化的， 自发生变化之日起15日内进行申报； （四）经过职业病危害因素检测、评价，发现原申报内容发生变化的，自收 到有关检测、评价结果之日起15日内进行申报。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第九条", "text": "用人单位终止生产经营活动的，应当自生产经营活动终止之日起15 日内向原申报机关报告并办理注销手续。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第十条", "text": "受理申报的安全生产监督管理部门应当建立职业病危害项目管理档 案。职业病危害项目管理档案应当包括辖区内存在职业病危害因素的用人单位数 量、职业病危害因素种类、行业及地区分布、接触人数等内容。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第十一条", "text": "安全生产监督管理部门应当依法对用人单位职业病危害项目申报 情况进行抽查，并对职业病危害项目实施监督检查。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第十二条", "text": "安全生产监督管理部门及其工作人员应当保守用人单位商业秘密 和技术秘密。违反有关保密义务的，应当承担相应的法律责任。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第十三条", "text": "安全生产监督管理部门应当建立健全举报制度，依法受理和查处 有关用人单位违反本办法行为的举报。 任何单位和个人均有权向安全生产监督管理部门举报用人单位违反本办法的 行为。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第十四条", "text": "用人单位未按照本办法规定及时、如实地申报职业病危害项目 的，责令限期改正，给予警告，可以并处5万元以上10万元以下的罚款。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第十五条", "text": "用人单位有关事项发生重大变化，未按照本办法的规定申报变更 职业病危害项目内容的，责令限期改正，可以并处5000元以上3万元以下的罚款。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第十六条", "text": "《职业病危害项目申报表》、《职业病危害项目申报回执》的式 样由国家安全生产监督管理总局规定。"}, {"law": "职业病危害项目申报办法_20120601.pdf", "no": "第十七条", "text": "本办法自2012年6月1日起施行。国家安全生产监督管理总局2009 年9月8日公布的《作业场所职业危害申报管理办法》同时废止。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第一条", "text": "为了规范职业病诊断与鉴定工作，加强 职业病诊断与鉴定管理，根据《中华人民共和国职业 病防治法》（以下简称《职业病防治法》），制定本办 法。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第二条", "text": "职业病诊断与鉴定工作应当按照《职业 病防治法》、本办法的有关规定及《职业病分类和目 录》、国家职业病诊断标准进行，遵循科学、公正、 及时、便捷的原则。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第三条", "text": "国家卫生健康委负责全国范围内职业 国家卫生健康委员会规章 国家卫生健康委员会发布 - 2 - 病诊断与鉴定的监督管理工作，县级以上地方卫生健 康主管部门依据职责负责本行政区域内职业病诊断 与鉴定的监督管理工作。 省、自治区、直辖市卫生健康主管部门（以下简 称省级卫生健康主管部门）应当结合本行政区域职业 病防治工作实际和医疗卫生服务体系规划，充分利用 现有医疗卫生资源，实现职业病诊断机构区域覆盖。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第四条", "text": "各地要加强职业病诊断机构能力建设， 提供必要的保障条件，配备相关的人员、设备和工作 经费，以满足职业病诊断工作的需要。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第五条", "text": "各地要加强职业病诊断与鉴定信息化 建设，建立健全劳动者接触职业病危害、开展职业健 康检查、进行职业病诊断与鉴定等全过程的信息化系 统，不断提高职业病诊断与鉴定信息报告的准确性、 及时性和有效性。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第六条", "text": "用人单位应当依法履行职业病诊断、鉴 定的相关义务： 国家卫生健康委员会规章 国家卫生健康委员会发布 - 3 - （一）及时安排职业病病人、疑似职业病病人进 行诊治； （二）如实提供职业病诊断、鉴定所需的资料； （三）承担职业病诊断、鉴定的费用和疑似职业 病病人在诊断、医学观察期间的费用； （四）报告职业病和疑似职业病； （五）《职业病防治法》规定的其他相关义务。 第二章 诊断机构"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第七条", "text": "医疗卫生机构开展职业病诊断工作，应 当在开展之日起十五个工作日内向省级卫生健康主 管部门备案。 省级卫生健康主管部门应当自收到完整备案材 料之日起十五个工作日内向社会公布备案的医疗卫 生机构名单、地址、诊断项目（即《职业病分类和目 录》中的职业病类别和病种）等相关信息。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 4 -"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第八条", "text": "医疗卫生机构开展职业病诊断工作应 当具备下列条件： （一）持有《医疗机构执业许可证》； （二）具有相应的诊疗科目及与备案开展的诊断 项目相适应的职业病诊断医师及相关医疗卫生技术 人员； （三）具有与备案开展的诊断项目相适应的场所 和仪器、设备； （四）具有健全的职业病诊断质量管理制度。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第九条", "text": "医疗卫生机构进行职业病诊断备案时， 应当提交以下证明其符合本办法"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第八条", "text": "规定条件的 有关资料： （一）《医疗机构执业许可证》原件、副本及复 印件； （二）职业病诊断医师资格等相关资料； （三）相关的仪器设备清单； （四）负责职业病信息报告人员名单； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 5 - （五）职业病诊断质量管理制度等相关资料。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第十条", "text": "职业病诊断机构对备案信息的真实性、 准确性、合法性负责。 当备案信息发生变化时，应当自信息发生变化之 日起十个工作日内向省级卫生健康主管部门提交变 更信息。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第十一条", "text": "设区的市没有医疗卫生机构备案开 展职业病诊断的，省级卫生健康主管部门应当根据职 业病诊断工作的需要，指定符合本办法"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第八条", "text": "规定条 件的医疗卫生机构承担职业病诊断工作。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第十二条", "text": "职业病诊断机构的职责是： （一）在备案的诊断项目范围内开展职业病诊 断； （二）及时向所在地卫生健康主管部门报告职业 病； （三）按照卫生健康主管部门要求报告职业病诊 断工作情况； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 6 - （四）承担《职业病防治法》中规定的其他职责。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第十三条", "text": "职业病诊断机构依法独立行使诊断 权，并对其作出的职业病诊断结论负责。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第十四条", "text": "职业病诊断机构应当建立和健全职 业病诊断管理制度，加强职业病诊断医师等有关医疗 卫生人员技术培训和政策、法律培训，并采取措施改 善职业病诊断工作条件，提高职业病诊断服务质量和 水平。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第十五条", "text": "职业病诊断机构应当公开职业病诊 断程序和诊断项目范围，方便劳动者进行职业病诊 断。 职业病诊断机构及其相关工作人员应当尊重、关 心、爱护劳动者，保护劳动者的隐私。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第十六条", "text": "从事职业病诊断的医师应当具备下 列条件，并取得省级卫生健康主管部门颁发的职业病 诊断资格证书： （一）具有医师执业证书； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 7 - （二）具有中级以上卫生专业技术职务任职资 格； （三）熟悉职业病防治法律法规和职业病诊断标 准； （四）从事职业病诊断、鉴定相关工作三年以上； （五）按规定参加职业病诊断医师相应专业的培 训，并考核合格。 省级卫生健康主管部门应当依据本办法的规定 和国家卫生健康委制定的职业病诊断医师培训大纲， 制定本行政区域职业病诊断医师培训考核办法并组 织实施。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第十七条", "text": "职业病诊断医师应当依法在职业病 诊断机构备案的诊断项目范围内从事职业病诊断工 作，不得从事超出其职业病诊断资格范围的职业病诊 断工作；职业病诊断医师应当按照有关规定参加职业 卫生、放射卫生、职业医学等领域的继续医学教育。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第十八条", "text": "省级卫生健康主管部门应当加强本 国家卫生健康委员会规章 国家卫生健康委员会发布 - 8 - 行政区域内职业病诊断机构的质量控制管理工作，组 织开展职业病诊断机构质量控制评估。 职业病诊断质量控制规范和医疗卫生机构职业 病报告规范另行制定。 第三章 诊断"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第十九条", "text": "劳动者可以在用人单位所在地、本人 户籍所在地或者经常居住地的职业病诊断机构进行 职业病诊断。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第二十条", "text": "职业病诊断应当按照《职业病防治 法》、本办法的有关规定及《职业病分类和目录》、国 家职业病诊断标准，依据劳动者的职业史、职业病危 害接触史和工作场所职业病危害因素情况、临床表现 以及辅助检查结果等，进行综合分析。材料齐全的情 况下，职业病诊断机构应当在收齐材料之日起三十日 内作出诊断结论。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 9 - 没有证据否定职业病危害因素与病人临床表现 之间的必然联系的，应当诊断为职业病。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第二十一条", "text": "职业病诊断需要以下资料： （一）劳动者职业史和职业病危害接触史（包括 在岗时间、工种、岗位、接触的职业病危害因素名称 等）； （二）劳动者职业健康检查结果； （三）工作场所职业病危害因素检测结果； （四）职业性放射性疾病诊断还需要个人剂量监 测档案等资料。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第二十二条", "text": "劳动者依法要求进行职业病诊断 的，职业病诊断机构不得拒绝劳动者进行职业病诊断 的要求,并告知劳动者职业病诊断的程序和所需材料。 劳动者应当填写《职业病诊断就诊登记表》，并提供 本人掌握的职业病诊断有关资料。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第二十三条", "text": "职业病诊断机构进行职业病诊断 时，应当书面通知劳动者所在的用人单位提供本办法 国家卫生健康委员会规章 国家卫生健康委员会发布 - 10 -"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第二十一条", "text": "规定的职业病诊断资料，用人单位应当在 接到通知后的十日内如实提供。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第二十四条", "text": "用人单位未在规定时间内提供职 业病诊断所需要资料的，职业病诊断机构可以依法提 请卫生健康主管部门督促用人单位提供。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第二十五条", "text": "劳动者对用人单位提供的工作场 所职业病危害因素检测结果等资料有异议，或者因劳 动者的用人单位解散、破产，无用人单位提供上述资 料的，职业病诊断机构应当依法提请用人单位所在地 卫生健康主管部门进行调查。 卫生健康主管部门应当自接到申请之日起三十 日内对存在异议的资料或者工作场所职业病危害因 素情况作出判定。 职业病诊断机构在卫生健康主管部门作出调查 结论或者判定前应当中止职业病诊断。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第二十六条", "text": "职业病诊断机构需要了解工作场 所职业病危害因素情况时，可以对工作场所进行现场 国家卫生健康委员会规章 国家卫生健康委员会发布 - 11 - 调查，也可以依法提请卫生健康主管部门组织现场调 查。卫生健康主管部门应当在接到申请之日起三十日 内完成现场调查。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第二十七条", "text": "在确认劳动者职业史、职业病危害 接触史时，当事人对劳动关系、工种、工作岗位或者 在岗时间有争议的，职业病诊断机构应当告知当事人 依法向用人单位所在地的劳动人事争议仲裁委员会 申请仲裁。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第二十八条", "text": "经卫生健康主管部门督促，用人单 位仍不提供工作场所职业病危害因素检测结果、职业 健康监护档案等资料或者提供资料不全的，职业病诊 断机构应当结合劳动者的临床表现、辅助检查结果和 劳动者的职业史、职业病危害接触史，并参考劳动者 自述或工友旁证资料、卫生健康等有关部门提供的日 常监督检查信息等，作出职业病诊断结论。对于作出 无职业病诊断结论的病人，可依据病人的临床表现以 及辅助检查结果，作出疾病的诊断，提出相关医学意 国家卫生健康委员会规章 国家卫生健康委员会发布 - 12 - 见或者建议。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第二十九条", "text": "职业病诊断机构可以根据诊断需 要，聘请其他单位职业病诊断医师参加诊断。必要时， 可以邀请相关专业专家提供咨询意见。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第三十条", "text": "职业病诊断机构作出职业病诊断结 论后，应当出具职业病诊断证明书。职业病诊断证明 书应当由参与诊断的取得职业病诊断资格的执业医 师签署。 职业病诊断机构应当对职业病诊断医师签署的 职业病诊断证明书进行审核，确认诊断的依据与结论 符合有关法律法规、标准的要求，并在职业病诊断证 明书上盖章。 职业病诊断证明书的书写应当符合相关标准的 要求。 职业病诊断证明书一式五份，劳动者一份，用人 单位所在地县级卫生健康主管部门一份，用人单位两 份，诊断机构存档一份。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 13 - 职业病诊断证明书应当于出具之日起十五日内 由职业病诊断机构送达劳动者、用人单位及用人单位 所在地县级卫生健康主管部门。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第三十一条", "text": "职业病诊断机构应当建立职业病 诊断档案并永久保存，档案应当包括： （一）职业病诊断证明书； （二）职业病诊断记录； （三）用人单位、劳动者和相关部门、机构提交 的有关资料； （四）临床检查与实验室检验等资料。 职业病诊断机构拟不再开展职业病诊断工作的， 应当在拟停止开展职业病诊断工作的十五个工作日 之前告知省级卫生健康主管部门和所在地县级卫生 健康主管部门，妥善处理职业病诊断档案。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第三十二条", "text": "职业病诊断机构发现职业病病人 或者疑似职业病病人时，应当及时向所在地县级卫生 健康主管部门报告。职业病诊断机构应当在作出职业 国家卫生健康委员会规章 国家卫生健康委员会发布 - 14 - 病诊断之日起十五日内通过职业病及健康危害因素 监测信息系统进行信息报告，并确保报告信息的完 整、真实和准确。 确诊为职业病的，职业病诊断机构可以根据需 要，向卫生健康主管部门、用人单位提出专业建议； 告知职业病病人依法享有的职业健康权益。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第三十三条", "text": "未承担职业病诊断工作的医疗卫 生机构，在诊疗活动中发现劳动者的健康损害可能与 其所从事的职业有关时，应及时告知劳动者到职业病 诊断机构进行职业病诊断。 第四章 鉴定"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第三十四条", "text": "当事人对职业病诊断机构作出的 职业病诊断有异议的，可以在接到职业病诊断证明书 之日起三十日内，向作出诊断的职业病诊断机构所在 地设区的市级卫生健康主管部门申请鉴定。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 15 - 职业病诊断争议由设区的市级以上地方卫生健 康主管部门根据当事人的申请组织职业病诊断鉴定 委员会进行鉴定。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第三十五条", "text": "职业病鉴定实行两级鉴定制，设区 的市级职业病诊断鉴定委员会负责职业病诊断争议 的首次鉴定。 当事人对设区的市级职业病鉴定结论不服的，可 以在接到诊断鉴定书之日起十五日内，向原鉴定组织 所在地省级卫生健康主管部门申请再鉴定，省级鉴定 为最终鉴定。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第三十六条", "text": "设区的市级以上地方卫生健康主 管部门可以指定办事机构，具体承担职业病诊断鉴定 的组织和日常性工作。职业病鉴定办事机构的职责 是： （一）接受当事人申请； （二）组织当事人或者接受当事人委托抽取职业 病诊断鉴定专家； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 16 - （三）组织职业病诊断鉴定会议，负责会议记录、 职业病诊断鉴定相关文书的收发及其他事务性工作； （四）建立并管理职业病诊断鉴定档案； （五）报告职业病诊断鉴定相关信息； （六）承担卫生健康主管部门委托的有关职业病 诊断鉴定的工作。 职业病诊断机构不能作为职业病鉴定办事机构。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第三十七条", "text": "设区的市级以上地方卫生健康主 管部门应当向社会公布本行政区域内依法承担职业 病诊断鉴定工作的办事机构的名称、工作时间、地点、 联系人、联系电话和鉴定工作程序。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第三十八条", "text": "省级卫生健康主管部门应当设立 职业病诊断鉴定专家库（以下简称专家库），并根据 实际工作需要及时调整其成员。专家库可以按照专业 类别进行分组。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第三十九条", "text": "专家库应当以取得职业病诊断资 格的不同专业类别的医师为主要成员，吸收临床相关 国家卫生健康委员会规章 国家卫生健康委员会发布 - 17 - 学科、职业卫生、放射卫生、法律等相关专业的专家 组成。专家应当具备下列条件： （一）具有良好的业务素质和职业道德； （二）具有相关专业的高级专业技术职务任职资 格； （三）熟悉职业病防治法律法规和职业病诊断标 准； （四）身体健康，能够胜任职业病诊断鉴定工作。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第四十条", "text": "参加职业病诊断鉴定的专家，应当由 当事人或者由其委托的职业病鉴定办事机构从专家 库中按照专业类别以随机抽取的方式确定。抽取的专 家组成职业病诊断鉴定委员会（以下简称鉴定委员 会）。 经当事人同意，职业病鉴定办事机构可以根据鉴 定需要聘请本省、自治区、直辖市以外的相关专业专 家作为鉴定委员会成员，并有表决权。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第四十一条", "text": "鉴定委员会人数为五人以上单数， 国家卫生健康委员会规章 国家卫生健康委员会发布 - 18 - 其中相关专业职业病诊断医师应当为本次鉴定专家 人数的半数以上。疑难病例应当增加鉴定委员会人 数，充分听取意见。鉴定委员会设主任委员一名，由 鉴定委员会成员推举产生。 职业病诊断鉴定会议由鉴定委员会主任委员主 持。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第四十二条", "text": "参加职业病诊断鉴定的专家有下 列情形之一的，应当回避： （一）是职业病诊断鉴定当事人或者当事人近亲 属的； （二）已参加当事人职业病诊断或者首次鉴定 的； （三）与职业病诊断鉴定当事人有利害关系的； （四）与职业病诊断鉴定当事人有其他关系，可 能影响鉴定公正的。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第四十三条", "text": "当事人申请职业病诊断鉴定时，应 当提供以下资料： 国家卫生健康委员会规章 国家卫生健康委员会发布 - 19 - （一）职业病诊断鉴定申请书； （二）职业病诊断证明书； （三）申请省级鉴定的还应当提交市级职业病诊 断鉴定书。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第四十四条", "text": "职业病鉴定办事机构应当自收到 申请资料之日起五个工作日内完成资料审核，对资料 齐全的发给受理通知书；资料不全的，应当当场或者 在五个工作日内一次性告知当事人补充。资料补充齐 全的，应当受理申请并组织鉴定。 职业病鉴定办事机构收到当事人鉴定申请之后， 根据需要可以向原职业病诊断机构或者组织首次鉴 定的办事机构调阅有关的诊断、鉴定资料。原职业病 诊断机构或者组织首次鉴定的办事机构应当在接到 通知之日起十日内提交。 职业病鉴定办事机构应当在受理鉴定申请之日 起四十日内组织鉴定、形成鉴定结论，并出具职业病 诊断鉴定书。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 20 -"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第四十五条", "text": "根据职业病诊断鉴定工作需要，职 业病鉴定办事机构可以向有关单位调取与职业病诊 断、鉴定有关的资料，有关单位应当如实、及时提供。 鉴定委员会应当听取当事人的陈述和申辩，必要 时可以组织进行医学检查，医学检查应当在三十日内 完成。 需要了解被鉴定人的工作场所职业病危害因素 情况时，职业病鉴定办事机构根据鉴定委员会的意见 可以组织对工作场所进行现场调查，或者依法提请卫 生健康主管部门组织现场调查。现场调查应当在三十 日内完成。 医学检查和现场调查时间不计算在职业病鉴定 规定的期限内。 职业病诊断鉴定应当遵循客观、公正的原则，鉴 定委员会进行职业病诊断鉴定时，可以邀请有关单位 人员旁听职业病诊断鉴定会议。所有参与职业病诊断 鉴定的人员应当依法保护当事人的个人隐私、商业秘 国家卫生健康委员会规章 国家卫生健康委员会发布 - 21 - 密。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第四十六条", "text": "鉴定委员会应当认真审阅鉴定资 料，依照有关规定和职业病诊断标准，经充分合议后， 根据专业知识独立进行鉴定。在事实清楚的基础上， 进行综合分析，作出鉴定结论，并制作职业病诊断鉴 定书。 鉴定结论应当经鉴定委员会半数以上成员通过。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第四十七条", "text": "职业病诊断鉴定书应当包括以下 内容： （一）劳动者、用人单位的基本信息及鉴定事由； （二）鉴定结论及其依据，鉴定为职业病的，应 当注明职业病名称、程度（期别）； （三）鉴定时间。 诊断鉴定书加盖职业病鉴定委员会印章。 首次鉴定的职业病诊断鉴定书一式五份，劳动 者、用人单位、用人单位所在地市级卫生健康主管部 门、原诊断机构各一份，职业病鉴定办事机构存档一 国家卫生健康委员会规章 国家卫生健康委员会发布 - 22 - 份；省级鉴定的职业病诊断鉴定书一式六份，劳动者、 用人单位、用人单位所在地省级卫生健康主管部门、 原诊断机构、首次职业病鉴定办事机构各一份，省级 职业病鉴定办事机构存档一份。 职业病诊断鉴定书的格式由国家卫生健康委员 会统一规定。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第四十八条", "text": "职业病鉴定办事机构出具职业病 诊断鉴定书后，应当于出具之日起十日内送达当事 人，并在出具职业病诊断鉴定书后的十日内将职业病 诊断鉴定书等有关信息告知原职业病诊断机构或者 首次职业病鉴定办事机构，并通过职业病及健康危害 因素监测信息系统报告职业病鉴定相关信息。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第四十九条", "text": "职业病鉴定结论与职业病诊断结 论或者首次职业病鉴定结论不一致的，职业病鉴定办 事机构应当在出具职业病诊断鉴定书后十日内向相 关卫生健康主管部门报告。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第五十条", "text": "职业病鉴定办事机构应当如实记录 国家卫生健康委员会规章 国家卫生健康委员会发布 - 23 - 职业病诊断鉴定过程，内容应当包括： （一）鉴定委员会的专家组成； （二）鉴定时间； （三）鉴定所用资料； （四）鉴定专家的发言及其鉴定意见； （五）表决情况； （六）经鉴定专家签字的鉴定结论。 有当事人陈述和申辩的，应当如实记录。 鉴定结束后，鉴定记录应当随同职业病诊断鉴定 书一并由职业病鉴定办事机构存档，永久保存。 第五章 监督管理"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第五十一条", "text": "县级以上地方卫生健康主管部门 应当定期对职业病诊断机构进行监督检查，检查内容 包括： （一）法律法规、标准的执行情况； 国家卫生健康委员会规章 国家卫生健康委员会发布 - 24 - （二）规章制度建立情况； （三）备案的职业病诊断信息真实性情况； （四）按照备案的诊断项目开展职业病诊断工作 情况； （五）开展职业病诊断质量控制、参加质量控制 评估及整改情况； （六）人员、岗位职责落实和培训情况； （七）职业病报告情况。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第五十二条", "text": "设区的市级以上地方卫生健康主 管部门应当加强对职业病鉴定办事机构的监督管理， 对职业病鉴定工作程序、制度落实情况及职业病报告 等相关工作情况进行监督检查。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第五十三条", "text": "县级以上地方卫生健康主管部门 监督检查时，有权查阅或者复制有关资料，职业病诊 断机构应当予以配合。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 25 - 第六章 法律责任"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第五十四条", "text": "医疗卫生机构未按照规定备案开 展职业病诊断的，由县级以上地方卫生健康主管部门 责令改正，给予警告，可以并处三万元以下罚款。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第五十五条", "text": "职业病诊断机构有下列行为之一 的，其作出的职业病诊断无效，由县级以上地方卫生 健康主管部门按照《职业病防治法》的"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第八十条", "text": "的规 定进行处理： （一）超出诊疗项目登记范围从事职业病诊断 的； （二）不按照《职业病防治法》规定履行法定职 责的； （三）出具虚假证明文件的。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第五十六条", "text": "职业病诊断机构未按照规定报告 职业病、疑似职业病的，由县级以上地方卫生健康主 管部门按照《职业病防治法》"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第七十四条", "text": "的规定进行 处理。 国家卫生健康委员会规章 国家卫生健康委员会发布 - 26 -"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第五十七条", "text": "职业病诊断机构违反本办法规定， 有下列情形之一的，由县级以上地方卫生健康主管部 门责令限期改正；逾期不改的，给予警告，并可以根 据情节轻重处以三万元以下罚款： （一）未建立职业病诊断管理制度的； （二）未按照规定向劳动者公开职业病诊断程序 的； （三）泄露劳动者涉及个人隐私的有关信息、资 料的； （四）未按照规定参加质量控制评估，或者质量 控制评估不合格且未按要求整改的； （五）拒不配合卫生健康主管部门监督检查的。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第五十八条", "text": "职业病诊断鉴定委员会组成人员 收受职业病诊断争议当事人的财物或者其他好处的， 由省级卫生健康主管部门按照《职业病防治法》第八 十一条的规定进行处理。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第五十九条", "text": "县级以上地方卫生健康主管部门 国家卫生健康委员会规章 国家卫生健康委员会发布 - 27 - 及其工作人员未依法履行职责，按照《职业病防治法》"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第八十三条", "text": "第二款规定进行处理。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第六十条", "text": "用人单位有下列行为之一的，由县级 以上地方卫生健康主管部门按照《职业病防治法》第 七十二条规定进行处理： （一）未按照规定安排职业病病人、疑似职业病 病人进行诊治的； （二）拒不提供职业病诊断、鉴定所需资料的； （三）未按照规定承担职业病诊断、鉴定费用。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第六十一条", "text": "用人单位未按照规定报告职业病、 疑似职业病的，由县级以上地方卫生健康主管部门按 照《职业病防治法》"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第七十四条", "text": "规定进行处理。 第六章 附则"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第六十二条", "text": "本办法所称“证据”，包括疾病的 证据、接触职业病危害因素的证据，以及用于判定疾 国家卫生健康委员会规章 国家卫生健康委员会发布 - 28 - 病与接触职业病危害因素之间因果关系的证据。"}, {"law": "职业病诊断与鉴定管理办法_20210401.pdf", "no": "第六十三条", "text": "本办法自公布之日起施行。原卫生 部2013 年2 月19 日公布的《职业病诊断与鉴定管理 办法》同时废止。"}];
